window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[2] = [{"id":1834,"category_id":2,"category_code":"s2","source_id":1,"title":"تقاضای بخیل از مسکین ","content":"مسکینی نزد بخیلی رفت و از او حاجتی خواست. بخیل گفت: اول تو حاجت مرا روا کن تا من هم حاجت تو را برآورم. مسکین گفت: حاجت تو چیست؟ گفت: حاجتم این است که از من حاجتی نخواهی."},{"id":1835,"category_id":2,"category_code":"s2","source_id":2,"title":"شاهینی که پرواز نمی کرد ","content":"پادشاهی دو شاهین کوچک به عنوان هدیه دریافت کرد. آنها را به مربی پرندگان دربار سپرد تا برای استفاده در مراسم شکار تربیت کند. \r\nیک ماه بعد، مربی نزد پادشاه آمد و گفت که یکی از شاهین‌ها تربیت شده و آماده شکار است اما نمی‌داند چه اتفاقی برای آن یکی افتاده و از همان روز اول که آن را روی شاخه‌ای قرار داده تکان نخورده است. \r\nاین موضوع کنجکاوی پادشاه را برانگیخت و دستور داد تا پزشکان و مشاوران دربار، کاری کنند که شاهین پرواز کند. اما هیچکدام نتوانستند. \r\n \r\nروز بعد پادشاه دستور داد تا به همه مردم اعلام کنند که هر کس بتواند شاهین را به پرواز درآورد ...\r\nپاداش خوبی از پادشاه دریافت خواهد کرد. \r\nصبح روز بعد پادشاه دید که شاهین دوم نیز با چالاکی تمام در باغ در حال پرواز است. \r\nپادشاه دستور داد تا معجزه‌گر شاهین را نزد او بیاورند. \r\nدرباریان کشاورزی متواضع را نزد شاه آوردند و گفتند اوست که شاهین را به پرواز درآورد.  \r\nپادشاه پرسید: «تو شاهین را به پرواز درآوردی؟ چگونه این کار را کردی؟ شاید جادوگر هستی؟ \r\nکشاورز گفت: سرورم، کار ساده‌ای بود، من فقط شاخه‌ای راکه شاهین روی آن نشسته بود بریدم. شاهین فهمید که بال دارد و شروع به پرواز کرد. \r\n"},{"id":1836,"category_id":2,"category_code":"s2","source_id":3,"title":"من اینجا مسافرم ","content":"جهانگردی به دهکده ای رفت تا زاهد معروفی را زیارت کند و دید که زاهد در اتاقی ساده زندگی می کند. اتاق پر از کتاب بود و غیر از آن فقط میز و نیمکتی دیده می شد.\r\n\r\nجهانگرد پرسید: لوازم منزلتان کجاست؟...\r\nزاهد گفت: مال تو کجاست؟\r\nجهانگرد گفت:من اینجا مسافرم.\r\nزاهد گفت: من هم.\r\n"},{"id":1837,"category_id":2,"category_code":"s2","source_id":4,"title":"عدالت و لطف خدا ","content":"زنى به حضور حضرت داوود (ع) آمد و گفت: اى پیامبر خدا پروردگار تو ظالم است یا عادل؟\r\n\r\nداوود (ع) فرمود: خداوند عادلى است که هرگز ظلم نمى کند.\r\nسپس فرمود: مگر چه حادثه اى براى تو رخ داده است که این سؤال را مى کنى؟\r\nزن گفت: من بیوه زن هستم و سه دختر دارم، با دستم ریسندگى مى کنم، دیروز شال بافته خود را در میان پارچه اى گذاشته بودم و به طرف بازار مى بردم تا بفروشم و با پول آن غذاى کودکانم را تهیه سازم ، ناگهان پرنده اى آمد و آن پارچه را از دستم ربود و برد و تهیدست و محزون ماندم و چیزى ندارم که معاش کودکانم را تأمین نمایم .\r\nهنوز سخن زن تمام نشده بود که ...\r\nدر خانه داوود (ع) را زدند ، حضرت اجازه وارد شدن به خانه را داد ، ناگهان ده نفر تاجر به حضور داوود (ع) آمدند و هر کدام صد دینار (جمعاً هزار دینار) نزد آن حضرت گذاردند و عرض کردند: این پولها را به مستحقش بدهید. حضرت داوود (ع) از آن ها پرسید : علت این که شما دسته جمعى این مبلغ را به اینجا آورده اید چیست ؟ عرض کردند: ما سوار کشتى بودیم ، طوفانى برخاست ، کشتى آسیب دید و نزدیک بود غرق گردد و همه ما به هلاکت برسیم ، ناگهان پرنده اى دیدیم ، پارچه سرخ بسته اى به سوى ما انداخت ، آن را گشودیم ، در آن شال بافته دیدیم ، به وسیله آن مورد آسیب دیده کشتى را محکم بستیم و کشتى بى خطر گردید و سپس طوفان آرام شد و به ساحل رسیدیم و ما هنگام خطر نذر کردیم که اگر نجات یابیم هر کدام صد دینار، بپردازیم و اکنون این مبلغ را که هزار دینار از ده نفر ماست به حضورت آورده ایم تا هر که را بخواهى ، به او صدقه بدهى.\r\n\r\nحضرت داوود (ع) به زن متوجه شد و به او فرمود : پروردگار تو در دریا براى تو هدیه مى فرستد، ولى تو او را ظالم مى خوانى ؟ سپس ‍ هزار دینار را به آن زن داد و فرمود : این پول را در تأمین معاش کودکانت مصرف کن ، خداوند به حال و روزگار تو ، آگاهتر از دیگران است.\r\n"},{"id":1838,"category_id":2,"category_code":"s2","source_id":5,"title":"پاسخ جالب آسیابان به زاهد ","content":"زاهدی کیسه ای گندم نزد آسیابان برد. آسیابان گندم او را در کنار سایر کیسه ها گذاشت تا به نوبت آرد کند.\r\n \r\nزاهد گفت: «اگر گندم مرا زودتر آرد نکنی دعا می کنم خرت سنگ بشود».\r\n \r\nآسیابان گفت: «تو که چنین مستجاب الدعوه هستی دعا کن گندمت آرد بشود.» \r\n"},{"id":1839,"category_id":2,"category_code":"s2","source_id":6,"title":"گنجشک و آتش ","content":"\r\nگنجشکی با عجله و تمام توان به آتش نزدیک می شد و برمی گشت!\r\nپرسیدند : چه می کنی ؟\r\nپاسخ داد : در این نزدیکی چشمه آبی هست و من مرتب نوک خود را پر از آب می کنم و...\r\nآن را روی آتش می ریزم !\r\nگفتند : حجم آتش در مقایسه با آبی که تو می آوری بسیار زیاد است ! و این آب فایده ای ندارد!\r\n\r\nگفت : شاید نتوانم آتش را خاموش کنم ، اما آن هنگام که خداوند می پرسد : زمانی که دوستت در آتش می سوخت تو چه کردی؟\r\nپاسخ میدم : هر آنچه از من بر می آمد!\r\n"},{"id":1840,"category_id":2,"category_code":"s2","source_id":7,"title":"خوک و گاو ","content":"مرد ثروتمندی به کشیشی می گوید:\r\nنمی دانم چرا مردم مرا خسیس می پندارند.\r\nکشیش گفت:\r\nبگذار حکایت کوتاهی از یک گاو و یک خوک برایت نقل کنم.\r\n\r\n\r\nخوک روزی به گاو گفت: مردم از طبیعت آرام و چشمان حزن انگیز تو به نیکی سخن می گویند و تصور می کنند تو خیلی بخشنده هستی. زیرا هر روز برایشان شیر و سرشیر می دهی.\r\nاما در مورد من چی؟...\r\nمن همه چیز خودم را به آنها می دهم از گوشت ران گرفته تا سینه ام را. حتی از موی بدن من برس کفش و ماهوت پاک کن درست می کنند. با وجود این کسی از من خوشش نمی آید. علتش چیست؟\r\nمی دانی جواب گاو چه بود؟\r\n\r\nجوابش این بود:\r\nشاید علتش این باشد که\r\n\"هر چه من می دهم در زمان حیاتم می دهم\"\r\n"},{"id":1841,"category_id":2,"category_code":"s2","source_id":8,"title":"زود قضاوت نکنید!","content":"مسئولین یک مؤسسه خیریه متوجه شدند که وکیل پولداری در شهرشان زندگی می‌کند و تا کنون حتی یک ریال هم به خیریه کمک نکرده است. پس یکی از افرادشان را نزد اوفرستادند.\r\nمسئول خیریه: آقای وکیل ما در مورد شما تحقیق کردیم و متوجه شدیم که الحمدالله از درآمد بسیار خوبی برخوردارید ولی تا کنون هیچ کمکی به خیریه نکرده‌اید.\r\nنمی‌خواهید در این امر خیر شرکت کنید؟\r\nوکیل: آیا شما در تحقیقاتی که در مورد من کردید متوجه شدید که\r\n مادرم بعد از یک بیماری طولانی سه ساله، هفته پیش درگذشت و در طول آن سه سال، حقوق بازنشستگی‌اش کفاف مخارج سنگین درمانش را نمی‌کرد؟  زود قضاوت کردید؟\r\nمسئول خیریه: (با کمی شرمندگی) نه، نمی‌دانستم. خیلی تسلیت می‌گویم.\r\nوکیل: آیا در تحقیقاتی که در مورد من کردید فهمیدید که برادرم در جنگ هر دو پایش را از دست داده و دیگر نمی‌تواند کار کند و زن و 5 بچه دارد و سالهاست که خانه نشین است و نمی‌تواند از پس مخارج زندگیش برآید؟زود قضاوت کردید؟\r\nمسئول خیریه: (با شرمندگی بیشتر) نه . نمی‌دانستم. چه گرفتاری بزرگی... \r\nوکیل: آیا در تحقیقاتتان متوجه شدید که خواهرم سالهاست که در یک بیمارستان روانی است و چون بیمه نیست در تنگنای شدیدی برای تأمین هزینه‌های درمانش قرار\r\nدارد؟  زود قضاوت کردید؟\r\nمسئول خیریه که کاملاً شرمنده شده بود گفت: ببخشید. نمی‌دانستم اینهمه گرفتاری\r\nدارید... \r\nوکیل: خوب. حالا وقتی من به اینها یک ریال کمک نکرده‌ام شما چطور انتظار دارید\r\nبه خیریه شما کمک کنم؟\r\n \r\nباز هم زود قضاوت کردید؟؟؟؟\r\n"},{"id":1842,"category_id":2,"category_code":"s2","source_id":9,"title":"ترک ","content":"\r\nاز من پرسید: ســیــگار\r\nرا تــرک نـکردی؟؟؟ گفتـم نــه\r\nکبریــت را ترکــ کرده ام\r\n...\r\nســیـگار را بـا ســیـگار\r\nروشـــــن میـکنم\r\n"},{"id":1843,"category_id":2,"category_code":"s2","source_id":10,"title":"توقع ","content":"\r\nیک (روز) خانواده ی لاک پشتها تصمیم گرفتند که به پیکنیک بروند. از آنجا\r\nکه لاک پشت ها به صورت طبیعی در همه ی موارد یواش عمل می کنند، هفت سال\r\nطول کشید تا برای سفرشون آماده بشن!\r\nدر نهایت خانواده ی لاک پشت خانه را برای پیدا کردن یک جای مناسب ترک\r\nکردند. در سال دوم سفرشان (بالاخره) پیداش کردند. برای مدتی حدود شش ماه\r\nمحوطه رو تمیز کردند، و سبد پیکنیک رو باز کردند، و مقدمات رو آماده\r\nکردند. بعد فهمیدند که نمک نیاوردند!\r\nپیکنیک بدون نمک یک فاجعه خواهد بود، و همه آنها با این مورد موافق\r\nبودند. بعد از یک بحث طولانی،....\r\nجوانترین لاک پشت برای آوردن نمک از خانه\r\nانتخاب شد.\r\nلاک پشت کوچولو ناله کرد، جیغ کشید و توی لاکش کلی بالا و پایین پرید، گر\r\nچه او سریعترین لاک پشت بین لاک پشت های کند بود!\r\nاو قبول کرد که به یک شرط بره؛ اینکه هیچ کس تا وقتی اون برنگشته چیزی\r\nنخوره. خانواده قبول کردن و لاک پشت کوچولو به راه افتاد.\r\nسه سال گذشت... و لاک پشت کوچولو برنگشت. پنج سال ... شش سال ... سپس در\r\nسال هفتم غیبت او، پیرترین لاک پشت دیگه نمی تونست به گرسنگی ادامه بده .\r\nاو اعلام کرد که قصد داره غذا بخوره و شروع به باز کردن یک ساندویچ کرد.\r\nدر این هنگام لاک پشت کوچولو ناگهان فریاد کنان از پشت یک درخت بیرون\r\nپرید،« دیدید می دونستم که منتظر نمی مونید. منم حالا نمی رم نمک\r\nبیارم»!!!!\r\n"},{"id":1844,"category_id":2,"category_code":"s2","source_id":11,"title":"آلفرد نوبل ","content":"آلفرد نوبل از جمله افراد معدودی بود که این شانس را داشت تا قبل از مردن، آگهی وفاتش را بخواند! حتما می دانید که نوبل مخترع دینامیت است. زمانی که برادرشلودویگ فوت شد، روزنامه‌ها اشتباهاً فکر کردند که نوبل معروف (مخترعدینامیت) مرده است. آلفرد وقتی صبح روزنامه ها را می‌خواند با دیدن آگهی صفحه اول، میخکوب شد:....\r\n\"آلفرد نوبل، دلال مرگ و مخترع مر‌گ آور ترین سلاح بشری مرد!\"\r\n\r\nآلفرد، خیلی ناراحت شد. با خود فکر کرد: آیا خوب است که من را پس از مرگ این گونه بشناسند؟\r\nسریع وصیت نامه‌اش را آورد. جمله‌های بسیاری را خط زد و اصلاح کرد. پیشنهاد کرد ثروتش صرف جایزه‌ای برای صلح و پیشرفت‌های صلح آمیز شود.\r\n"},{"id":1845,"category_id":2,"category_code":"s2","source_id":12,"title":"امتحان ","content":"استاد سختگیر فیزیک اولین دانشجو را برای پرسش فرا میخواند و سئوال را مطرح میکند\r\nشما در قطاری نشسته اید که با سرعت هشتاد کیلومتر در ساعت حرکت میکند و ناگهان شما گرما زده شده اید، حالا چکار میکنید؟\r\nدانشجوی بی تجربه فورا ً جواب میدهد\r\n من پنجره کوپه را پائین میکشم تا باد بوزد\r\nاکنون پروفسور میتواند سئوال اصلی را بدینترتیب مطرح کند\r\nحال که شما پنجره کوپه را باز کرده اید....\r\nدر جریان هوای اطراف قطار اختلال حاصل میشود\r\nو لازم است موارد زیر را محاسبه کنید\r\nمحاسبه مقا ومت جدید هوا در مقابل قطار؟\r\nتغییر اصطکاک بین چرخها و ریل؟\r\nآیا در اثر باز کردن پنجره، سرعت قطار کم میشود و اگر آری، به چه اندازه؟\r\nحسب المعمول دهان دانشجو باز مانده بود و قادر به حل این مسئله نبود و سرافکنده جلسه امتحان را ترک کرد\r\nهمین بلا سر بیست دانشجوی بعدی هم آمد که همگی در امتحان شفاهی فیزیک مردود شدند\r\nپروفسور آخرین دانشجو را برای امتحان فرا میخواند و طبق معمول سئوال اولی را میپرسد\r\nشما در قطاری نشسته اید که با سرعت هشتاد کیلومتر در ساعت حرکت میکند و ناگهان شما گرما زده شده اید، حالا چکار میکنید؟\r\nاین دانشجوی خبره میگوید؛ من کتم را در میارم\r\nپروفسور اضافه میکند که هوا بیش از اینها گرمه\r\nدانشجو میگه خوب ژاکتم را هم در میارم\r\nهوای کوپه مثل حمام زونا داغه\r\nدانشجو میگه اصلا ً لخت مادر زاد میشم\r\nپروفسور گوشزد میکند که دو آفریقائی نکره و نانجیب در کوپه هستند و منتظرند تا شما لخت شی\r\nدانشجو به آرامی میگوید\r\nمیدانید آقای پروفسور، این دهمین بار است که من در امتحان شفاهی فیزیک شرکت میکنم واگر قطار مملو از آفریقائیهای ... باشد، من آن پنجره لامصب را باز نمیکنم.\r\n"},{"id":1846,"category_id":2,"category_code":"s2","source_id":13,"title":"جواب منطقی ","content":"یک دختر خانم زیبا خطاب به رئیس شرکت امریکائی ج پ مورگان نامه‌ای بدین مضمون نوشته است :\r\nمی‌خواهم در آنچه اینجا می‌گویم صادق باشم.من 25 سال دارم و بسیار زیبا ، با سلیقه و خوش‌اندام هستم. آرزو دارم با مردی با درآمد سالانه 500 هزار دلار یا بیشتر ازدواج کنم.شاید تصور کنید که سطح توقع من بالاست ، اما حتی درآمد سالانه یک میلیون دلار در نیویورک هم به طبقه متوسط تعلق دارد چه برسد به 500 هزار دلار.خواست من چندان زیاد نیست. هیچ کس درآنجا با درآمد سالانه 500 هزار دلاری وجود دارد؟آیا شما خودتان....\r\nازدواج کرده‌اید؟ سئوال من این است که چه کنم تا با اشخاص ثروتمندی مثل شما ازدواج کنم؟چند سئوال ساده دارم:1- پاتوق جوانان مجرد کجاست ؟2- چه گروه سنی از مردان به کار من می‌آیند ؟3- چرا بیشتر زنان افراد ثروتمند ، از نظر ظاهری متوسطند ؟4- معیارهای شما برای انتخاب زن کدامند ؟\r\n امضا ، خانم زیبا\r\n"},{"id":1847,"category_id":2,"category_code":"s2","source_id":14,"title":"انسانیت، ساده یا پیچیده! ","content":"چند وقت پیش با پدر و مادرم رفته بودیم رستوران که هم آشپزخانه بود هم چند تا میز گذاشته بود برای مشتریها ,, افراد زیادی اونجا نبودن , 3نفر ما بودیم با یه زن و شوهر جوان و یه پیرزن پیر مرد که نهایتا 60-70 سالشون بود ,,\r\nما غذا مون رو سفارش داده بودیم که یه جوان نسبتا 35 ساله اومد تو رستوران یه چند دقیقه ای گذشته بود که اون جوانه گوشیش زنگ خورد , البته من با اینکه بهش نزدیک بودم ولی صدای زنگ خوردن گوشیش رو نشنیدم , بگذریم شروع کرد با صدای بلند صحبت کردن و ...\r\nبعد از اینکه صحبتش تمام شد رو کرد به همه ما ها و با خوشحالی گفت که خدا بعد از 8 سال یه بچه بهشون داده و همینطور که داشت از خوشحالی ذوق میکرد روکرد به صندوق دار رستوران و گفت این چند نفر مشتریتون مهمونه من هستن میخوام شیرینیه بچم رو بهشون بدم ,,\r\nبه همشون باقالی پلو با ماهیچه بده ,, خوب ما همه گیمون با تعجب و خوشحالی داشتیم بهش نگاه میکردیم که من از روی صندلیم بلند شدم و رفتم طرفش , اول بوسش کردم و بهش تبریک گفتم و بعد بهش گفتم ما قبلا غذا مون رو سفارش دادیم و مزاحم شما نمیشیم, اما بلاخره با اسرار زیاد پول غذای ما و اون زن و شوهر جوان و اون پیره زن پیره مرد رو حساب کرد و با غذای خودش که سفارش داده بود از رستوران خارج شد , ,,,\r\nخب این جریان تا این جاش معمولی و زیبا بود , اما اونجایی خیلی تعجب کردم که دیشب با دوستام رفتیم سینما که تو صف برای گرفتن بلیط ایستاده بودیم , ناگهان با تعجب همون پسر جوان رو دیدم که با یه دختر بچه 4-5 ساله ایستاده بود تو صف ,,, از دوستام جدا شدم و یه جوری که متوجه من نشه نزدیکش شدم و باز هم با تعجب دیدم که دختره داره اون جوان رو بابا خطاب میکنه ,,\r\nدیگه داشتم از کنجکاوی میمردم , دل زدم به دریا و رفتم از پشت زدم رو کتفش ,, به محض اینکه برگشت من رو شناخت , یه ذره رنگ و روش پرید ,, اول با هم سلام و علیک کردیم بعد من با طعنه بهش گفتم , ماشالله از 2-3 هفته پیش بچتون بدنیا اومدو بزرگم شده ,, همینطور که داشتم صحبت میکردم پرید تو حرفم گفت ,, داداش او جریان یه دروغ بود , یه دروغ شیرین که خودم میدونم و خدای خودم,,\r\n\r\nدیگه با هزار خواهشو تمنا گفت ,,,,, اون روز وقتی وارد رستوران شدم دستام کثیف بود و قبل از هر کاری رفتم دستام رو شستم ,, همینطور که داشتم دستام رو میشستم صدای اون پیرمرد و پیر زن رو شنیدم البته اونا نمیتونستن منو ببینن که دارن با خنده باهم صحبت میکنن , پیرزن گفت کاشکی می شد یکم ولخرجی کنی امروز یه باقالی پلو با ماهیچه بخوریم ,, الان یه سال میشه که ماهیچه نخوردم ,,, پیر مرده در جوابش گفت , ببین امدی نسازیها قرار شد بریم رستوران و یه سوپ بخریم و برگردیم خونه اینم فقط بخاطر اینکه حوصلت سر رفته بود ,, من اگه الان هم بخوام ولخرجی کنم نمیتونم بخاطر اینکه 18 هزار تومان بیشتر تا سر برج برامون نمونده ,,\r\n\r\nهمینطور که داشتن با هم صحبت میکردن او کسی که سفارش غذا رو میگیره اومد سر میزشون و گفت چی میل دارین ,, پیرمرده هم بیدرنگ جواب داد , پسرم ما هردومون مریضیم اگه میشه دو تا سوپ با یه دونه از اون نونای داغتون برامون بیار ,,\r\nمن تو حالو هوای خودم نبودم همینطور اب باز بود و داشت هدر میرفت , تمام بدنم سرد شده بود احساس کردم دارم میمیرم ,, رو کردم به اسمون و گفتم خدا شکرت فقط کمکم کن ,, بعد امدم بیرون یه جوری فیلم بازی کردم که اون پیر زنه بتونه یه باقالی پلو با ماهیچه بخوره همین ,,\r\nازش پرسیدم که چرا دیگه پول غذای بقیه رو دادی ماهاکه دیگه احتیاج نداشتیم ,, گفت داداشمی ,, پول غذای شما که سهل بود من حاضرم دنیای خودم و بچم رو بدم ولی ابروی یه انسان رو تحقیر نکنم ,, این و گفت و رفت ,,\r\nیادم نمیاد که باهاش خداحافظی کردم یا نه , ولی یادمه که چند ساعت روی جدول نشسته بودم و به درودیوار نگاه میکردم و مبهوت بودم ,,,, واقعا راسته که خدا از روح خودش تو بدن انسان دمید.\r\n"},{"id":1848,"category_id":2,"category_code":"s2","source_id":15,"title":"بیل گیتس در رستوران ","content":"بعد از خوردن غذا بیل گیتس 5 دلار به عنوان انعام به پیش خدمت دادپیشخدمت ناراحت شد\r\nبیل گیتس متوجه ناراحتی پیشخدمت شد و سوال کرد : چه اتفاقی افتاده؟\r\nپیشخدمت : من متعجب شدم ....\r\nبخاطر اینکه در میز کناری پسر شما 50 دلار به من انعام داد در \r\nدرحالی که شما که پدر او هستید و پولدار ترین انسان روی زمین هستید فقط 5دلار انعام می دهید !\r\nگیتس خندید و جواب معنا داری گفت :\r\nاو پسر پولدار ترین مرد روی زمینه و من پسر یک نجار ساده ام.\r\n"},{"id":1849,"category_id":2,"category_code":"s2","source_id":16,"title":"چند می فروشی؟ ","content":"مرد کشاورزی یک زن نق نقو داشت که از صبح تا نصف شب در مورد چیزی شکایت میکرد. تنها زمان آسایش مرد زمانی بود که با قاطر پیرش در مزرعه شخم میزد. \r\nیک روز، وقتی که همسرش برایش ناهار آورد، کشاورز قاطر پیر را  به زیر سایه ای راند و شروع به خوردن ناهار خود کرد. بلافاصله همسر نق نقو مثل همیشه شکایت را آغاز کرد. ناگهان قاطر پیر با هر دو پای عقبی لگدی به پشت سر زن و در دم کشته شد.\r\nدر مراسم تشییع جنازه چند روز بعد، کشیش متوجه چیز عجیبی شد. هر وقت...\r\nیک زن عزادار برای تسلیت گویی به مرد کشاورز نزدیک میشد، مرد گوش میداد و بنشانه تصدیق سر خود را بالا و پایین میکرد،  اما هنگامی که یک مرد عزادار به او نزدیک میشد، او بعد از یک دقیقه گوش کردن سر خود را بنشانه مخالفت تکان میداد.\r\nپس از مراسم تدفین، کشیش از کشاورز قضیه را پرسید.\r\nکشاورز گفت: \r\nخوب، این زنان می آمدند چیز خوبی  در مورد همسر من میگفتند، که چقدر خوب بود، یا چه قدر خوشگل یا خوش لباس بود، بنابراین من هم تصدیق میکردم.\r\nکشیش پرسید، پس مردها چه میگفتند؟\r\nکشاورز گفت: \r\nآنها می خواستند بدانند که آیا قاطر را حاضرم بفروشم یا نه\r\n"},{"id":1850,"category_id":2,"category_code":"s2","source_id":17,"title":"استاد اصولا منطق چیست ؟ ","content":"معلم کمی فکر کرد و جواب داد : گوش کنید ، مثالی می زنم ، دو مرد - پیش من می آیند. یکی تمیز ودیگری کثیف من به آن ها پیشنهاد\r\nمی کنم حمام کنند.شما فکر می کنید ، کدام یک این کار را انجام دهند ؟\r\nهردو شاگرد یک زبان جواب دادند : خوب مسلما کثیفه !\r\nمعلم گفت : نه ، تمیزه . چون او به حمام کردن عادت کرده و کثیفه قدر\r\nآن را نمی داند.پس چه کسی حمام می کند ؟\r\nحالا پسرها می گویند : تمیزه !\r\nمعلم جواب داد : ....\r\nنه ، کثیفه ، چون او به حمام احتیاج دارد.وباز پرسید :\r\nخوب ، پس کدامیک از مهمانان من حمام می کنند ؟\r\nیک بار دیگر شاگردها گفتند : کثیفه !\r\nمعلم دوباره گفت : اما نه ، البته که هر دو ! تمیزه به حمام عادت دارد و\r\nکثیفه به حمام احتیاج دارد. خوب بالاخره کی حمام می گیرد ؟\r\nبچه ها با سر درگمی جواب دادند : هر دو !\r\nمعلم بار دیگر توضیح می دهد : نه ، هیچ کدام ! چون کثیفه به حمام\r\nعادت ندارد و تمیزه هم نیازی به حمام کردن ندارد!\r\nشاگردان با اعتراض گفتند : بله درسته ، ولی ما چطور می توانیم\r\nتشخیص دهیم ؟هر بار شما یک چیزی را می گویید و هر دفعه هم درست است\r\nمعلم در پاسخ گفت : خوب پس متوجه شدید ، این یعنی: منطق !\r\nو از دیدگاه هر کس متفاوت است.\r\n"},{"id":1851,"category_id":2,"category_code":"s2","source_id":18,"title":"چشمه ","content":"در باغی چشمه‌ای‌بود و دیوارهای بلند گرداگرد آن باغ، تشنه‌ای دردمند بالای دیوار با حسرت به آب نگاه می‌کرد. ناگهان خشتی از دیوار کند و در چشمه افکند. صدای آب مثل صدای یار شیرین و زیبا به گوشش آمد. آب در نظرش شراب بود. مرد آنقدر از صدای آب لذت می‌برد که تند تند خشت‌ها را می‌کند و در آب می‌افکند.\r\nآب فریاد زد: های، چرا خشت می‌زنی؟ از این خشت زدن بر من چه فایده‌ای می‌بری؟...\r\nتشنه گفت: ای آب شیرین! در این کار دو فایده است. اول اینکه شنیدن صدای آب برای تشنه مثل شنیدن صدای موسیقی رُباب است. نوای آن حیات بخش است، مرده را زنده می‌کند. مثل صدای رعد و برق بهاری برای باغ سبزه و سنبل می‌آورد. صدای آب مثل هدیه برای فقیر است. پیام آزادی برای زندانی است، بوی یوسف لطیف و زیباست که از پیراهنِ یوسف به پدرش یعقوب می‌رسید .\r\nفایدة دوم اینکه: من هر خشتی که برکنم به آب شیرین نزدیکتر می‌شوم، دیوار کوتاهتر می‌شود. \r\nخم شدن و سجده در برابر خدا، مثل کندن خشت است. هر بار که خشتی از غرور خود بکنی، دیوار غرور تو کوتاهتر می‌شود و به آب حیات و حقیقت نزدیکتر می‌شوی. هر که تشنه‌تر باشد تندتر خشت‌ها را می‌کند. هر که آواز آب را عاشق‌تر باشد. خشت‌های بزرگتری برمی‌دارد.\r\n"},{"id":1852,"category_id":2,"category_code":"s2","source_id":19,"title":"برنده ی جایزه","content":"تصور کن برنده یک مسابقه شدی و جایزه ات اینه که بانک هر روز صبح یک حساب برات باز می کنه و توش هشتاد و شش هزار و چهار صد دلار پول می گذاره. ولی دو تا شرط داره.\r\nیکی اینکه همه پول رو باید تا شب خرج کنی، وگرنه هر چی اضافه بیاد ازت پس می گیرند. نمی تونی تقلب کنی و یا اضافهٔ پول رو به حساب دیگه ای منتقل کنی. هر روز صبح بانک برات یک حساب جدید با همون موجودی باز می کنه.\r\nشرط بعدی اینه که بانک می تونه هر وقت بخواد بدون اطلاع قبلی حسابو ببنده و بگه جایزه تموم شد.\r\nحالا بگو چه طوری عمل می کنی؟\r\nاو زمان زیادی برای پاسخ به این سوال نیاز نداشت و سریعا... \r\nهمه ما این حساب جادویی رو در اختیار داریم ؛ \"زمان\". این حساب با ثانیه ها پر می شه. هر روز که از خواب بیدار می شیم، هشتاد و شش هزار و چهار صد ثانیه به ما جایزه میدن و شب که می خوابیم مقداری رو که مصرف نکردیم نمی تونیم به روز بعد منتقل کنیم. لحظه هایی که زندگی نکردیم از دستمون رفته. دیروز ناپدید شده. هر روز صبح جادو می شه و هشتاد و شش هزار و چهار صد ثانیه به ما می دن. یادت باشه که من و تو فعلا از این نعمت برخورداریم ولی بانک می تونه هر وقت بخواد حسابو بدون اطلاع قبلی ببنده. ما به جای استفاده از موجودیمون نشستیم بحث و جدل می کنیم و غصه می خوریم. بیا از زمانی که برامون باقی مونده لذت ببریم. ازت تمنا می کنم.\r\n"},{"id":1853,"category_id":2,"category_code":"s2","source_id":20,"title":"درخت مشکلات ","content":"نجار، یک روز کاری دیگر را هم به پایان برد . آخر هفته بود و تصمیم گرفت دوستی را برای صرف نوشیدنی به خانه اش دعوت کند.موقعی که نجار و دوستش به خانه رسیدند.قبل از ورود ، نجار چند دقیقه در سکوت جلو درختی در باغچه ایستاد .....\r\nعد با دو دستش ، شاخه های درخت را گرفت .چهره اش بی درنگ تغییر کرد.خندان وارد خانه شد، همسر و فرزندانش به استقبالش آمدند ، برای فرزندانش قصه گفت ، و بعد با دوستش به ایوان رفتند تا نوشیدنی بنوشند .از آنجا می توانستند درخت را ببینند . دوستش دیگر نتوانست جلو کنجکاوی اش را بگیرد، و دلیل رفتار نجار را پرسید.نجار گفت :\r\n (( آه این درخت مشکلات من است . موقع کار ، مشکلات فراوانی پیش می آید ، اما این مشکلات مال من است و ربطی به همسر و فرزندانم ندارد. وقتی به خانه می رسم ، مشکلاتم را به شاخه های آن درخت می آویزم . روز بعد ، وقتی می خواهم سر کار بروم ، دوباره آنها را از روی شاخه بر می دارم .جالب این است که وقتی صبح به سراغ درخت می روم تا مشکلاتم را بردارم ، خیلی از مشکلات ، \r\nدیگر آنجا نیستند ، و بقیه هم خیلی سبکتر شده اند .))\r\n"},{"id":1854,"category_id":2,"category_code":"s2","source_id":21,"title":"حکایت سید مهدی قوام و زن روسپی ","content":"انگار باران چشم‌های زن، تمامی ندارد. چندسال بعد…نمی‌دانم چندسال… حرم صاحب اصلی محفل! سید، دست به سینه از رواق خارج می‌شود.\r\nچراغ‌های مسجد دسته دسته روشن می‌شوند. الحمدلله، ده شب مجلس با آبروداری برگزار شد.\r\nآقا سید مهدی که از پله‌های منبر پایین می‌آید، حاج شمس‌الدین ـ بانی مجلس ـ هم کم کم از میان جمعیت راه باز می‌کند تا برسد بهش.\r\nجمعیت هم همینطور که سلام می‌کنند راه باز می‌کنند تا دم در مسجد.\r\nوقت خداحافظی، حاجی دست می کند جیب کتش…\r\nآقا سید، ناقابل، اجرتون با صاحب اصلی محفل…\r\nدست شما درد نکند، بزرگوار!\r\nسید پاکت را بدون اینکه حساب کتاب کند، می‌گذار پر قبایش. مدت‌ها بود که دخل را سپرده بود دست دیگری!\r\nآقا سید، حاج مرشد شما رو تا دم در منزل همراهی می‌کنن…\r\nحاج مرشد، پیرمرد ۵۰ ، ۶۰ ساله، لبخندزنان نزدیک می‌شود. التماس دعای حاج شمس و راهی راه…\r\nزن، خیلی جوان نبود. اما هنوز سن میانسالی‌اش هم نرسیده بود. مضطرب، این طرف آن طرف را نگاه می‌کرد.\r\nزیر تیر چراغ برق خیابان لاله زار، جوراب شلواری توری، رنگ تند لب‌ها، گیس‌های پریشان… رنگ دیگری به خود گرفته بود.\r\nدوره و زمونه‌ای نبود که معترضش بشوند…\r\n***\r\nحاج مرشد!\r\nجانم آقا سید؟\r\nآنجا را می‌بینی؟ آن خانم…\r\nحاجی که انگار تازه حواسش جمع آن طرف خیابان شده بود، زود سرش را انداخت پایین.\r\nاستغفرالله ربی و اتوب‌الیه…\r\nسید انگار فکرش جای دیگری است…\r\nحاجی، برو صدایش کن بیاید اینجا.\r\nحاج مرشد انگار که درست نشنیده باشد، تند به سیدمهدی نگاه می‌کند:\r\nحاج آقا، یعنی قباحت نداره؟! من پیرمرد و شمای سید اولاد پیغمبر! این وقت شب… یکی ببیند نمی‌گوید اینها با این فاحشه چه کار دارند؟\r\nسبحان الله…\r\nسید مکثی می‌کند.\r\nبزرگواری کنید و ایشون رو صدا کنید. به ما نمی‌خورد مشتری باشیم؟!\r\nحاج مرشد، بالاخره با اکراه راضی می‌شود. اینبار، او مضطرب این طرف و آن طرف را نگاه می‌کند و سمت زن می‌رود.\r\nزن که انگار تازه حواسش جمع آنها شده، کمی خودش را جمع و جور می‌کند.\r\nبه قیافه‌شان که نمی‌خورد مشتری باشند! حاج مرشد، کماکان زیرلب استغفرالله می‌گوید.\r\n- خانم! بروید آنجا! پیش آن آقاسید. باهاتان کاری دارند.\r\nزن، با تردید، راه می‌افتد.\r\nحاج مرشد، همانجا می‌ایستد. می‌ترسد از مشایعت آن زن!…\r\nزن چیزی نمی‌گوید. سکوت کرده. مشتری اگر مشتری باشد، خودش…\r\nدخترم! این وقت شب، ایستاده‌اید کنار خیابان که چه بشود؟\r\nشاید زن، کمی فهمیده باشد! کلماتش قدری هوای درد دل دارد، همچون چشم‌هایش که قدری هوای باران:\r\nحاج آقا! به خدا مجبورم! احتیاج دارم…\r\nسید؛ ولی مشتری بود!\r\nپاکت را بیرون می‌آورد و سمت زن می‌گیرد:\r\nاین، مال صاحب اصلی محفل است! من هم نشمرده‌ام. مال امام حسین(ع) است…\r\nتا وقتی که تمام نشده، کنار خیابان نایست!…\r\nسید به حاجی ملحق می‌شود و دور…\r\nانگار باران چشم‌های زن، تمامی ندارد…\r\n***\r\nچندسال بعد…نمی‌دانم چندسال… حرم صاحب اصلی محفل!\r\nسید، دست به سینه از رواق خارج می‌شود. زیر لب همینجور سلام می‌دهد و دور می‌شود. به در صحن که می‌رسد، نگاهش به نگاه مرد گره می‌خورد و زنی به شدت محجوب که کنارش ایستاده.\r\nمرد که انگار مدت مدیدی است سید را می‌پاییده، نزدیک می‌آید و عرض ادبی.\r\nزن بنده می‌خواهد سلامی عرض کند.\r\nمرد که دورتر می‌ایستد، زن نزدیک می‌آید و کمی نقاب از صورتش بر می‌گیرد که سید صدایش را بهتر بشنود. صدا، همان صدای خیابان لاله زار است و همان بغض:\r\nآقا سید! من را نشناختید؟ یادتان می‌آید که یکبار، برای همیشه دکان مرا تعطیل کردید؟ همان پاکت…\r\nآقا سید! من دیگر… خوب شده‌ام!\r\nاین بار، نوبت باران چشمان سید است…سید مهدی قوام ـ از روحانی های اخلاقی دهه ۴۰ تهران ـ یکی تعریف می‌کرد: روزی که پیکر سید مهدی قوام را آوردند قم که دفن کنند،به اندازه‌ی دو تا صحن بزرگ حرم حضرت معصومه کلاه شاپویی و لنگ به دست آمده بودند و صحن را پر کرده بودند.\r\nزار زار گریه می‌کردند و سرشان را می‌کوبیدند به تابوت…\r\n"},{"id":1855,"category_id":2,"category_code":"s2","source_id":22,"title":"ایراد پیرزن به مناره مسجد و تدبیر معمار ","content":"روایت شده است در حدود ٧٠٠ سال پیش، در اصفهان مسجدی بزرگ میساختند. اما چند روز قبل از افتتاح مسجد، کارگرها و معماران جمع شده بودند و آخرین خرده کاری ها را انجام میدادند.\r\n\r\nپیرزنی از آنجا رد میشد وقتی مسجد را دید به یکی از کارگران گفت: فکر کنم یکی از مناره ها کمی کجه! کارگرها خندیدند. اما معمار که این حرف را شنید، سریع گفت: چوب بیاورید! کارگر بیاورید! چوب را به مناره تکیه بدهید. فشار بدهید. فششششششااااررر...!!!\r\n....\r\nو مدام از پیرزن میپرسید: مادر، درست شد؟!!\r\n\r\nمدتی طول کشید تا پیرزن گفت: بله! درست شد!!! تشکر کرد و دعایی کرد و رفت...\r\nکارگرها حکمت این کار بیهوده و فشار دادن مناره را از معمار با تجربه پرسیدند؟!\r\nمعمار گفت: اگر این پیرزن، راجع به کج بودن این مناره با دیگران صحبت میکرد و شایعه پا میگرفت، این مناره تا ابد کج میماند و دیگر نمیتوانستیم اثرات منفی این شایعه را پاک کنیم... این است که من گفتم در همین ابتدا جلوی آن را بگیرم !\r\n"},{"id":1856,"category_id":2,"category_code":"s2","source_id":23,"title":"به او اعتماد کن ","content":"مردی ثروتمند وجود داشت که همیشه پر از اضطراب و دلواپسی بود. با اینکه از همه ثروتهای دنیا بهره مند بود،هیچ گاه شاد نبود.او خدمتکاری داشت که ایمان درونش موج می زد. روزی خدمتکار وقتی دید مرد تا حد مرگ نگران است به او گفت:\r\n((ارباب،آیا حقیقت دارد که خداوندپیش از بدنیا آمدن شما جهان را اداره می کرد؟))\r\nاو پاسخ داد:((بله))\r\n خدمتکار پرسید:....\r\n((آیا درست است که خداوند پس از آنکه شما دنیا را ترک کردید آنرا همچنان اداره می کند؟))\r\nارباب دوباره پاسخ داد:((بله))\r\nخدمتکار گفت:\r\n((پس چطور است به خدا اجازه بدهید وقتی شما در این دنیا هستید او آنرا ادره کند؟))\r\nبه او اعتماد کن ، وقتی تردیدهای تیره به تو هجوم می آورند\r\nبه او اعتماد کن ، وقتی که نیرویت کم است\r\nبه او اعتماد کن ، زیرا وقتی به سادگی به او اعتماد کنی\r\nاعتمادت سخت ترین چیزها خواهد بود...\r\n"},{"id":1857,"category_id":2,"category_code":"s2","source_id":24,"title":"بیشرمانه زیستن ","content":"روزی، در مجلس ختمی، مرد متین و موقری که در کنارم نشسته بود و قطره اشکی هم در چشم داشت، آهسته به من گفت: آیا آن مرحوم را از نزدیک می شناختید؟\r\n\r\nگفتم: خیر قربان! خویشِ دور بنده بوده و به اصرار خانواده آمده ام، تا متقابلا، در روز ختم من، خویشان خویش، به اصرار خانواده بیایند.\r\nحرفم را نشنید، چرا که می خواست حرفش را بزند. پس گفت: بله... خدا رحمتش کند! چه خوب آمد و چه خوب رفت. آزارش به یک مورچه هم نرسید. زخمی هم به هیچکس نزد. حرف تندی هم به هیچکس نگفت. اسباب رنجش خاطر هیچکس را فراهم نیاورد. هیچکس از او هیچ گله و شکایتی نداشت. دوست و دشمن از او راضی بودند و به او احترام می گذاشتند... حقیقتا چه خوب آمد و چه خوب رفت...\r\nگفتم: این، به راستی که بیشرمانه زیستن است و بیشرمانه مردن.\r\nبا این صفات خالی از صفت که جنابعالی برای ایشان بر شمردید، نمی آمد و نمی رفت خیلی آسوده تر بود، چرا که هفتاد سال به ناحق و به حرام، نان کسانی را خورد که به خاطر حقیقت می جنگند و زخم می زنند و می سوزانند و می سوزند و می رنجانند و رنج می کشند... و این بیچاره ها که با دشمن، دشمنی می کنند و با دوست دوستی، دائما گرسنه اند و تشنه، چرا که آب و نان شان را همین کسانی خورده اند و می خورند که زندگی را \"بیشرمانه مردن\" تعریف می کنند.\r\n\r\nآخر آدمی که در طول هفتاد سال عمر، آزارش به یک مدیر کلّ دزد  منحرف، به آدم بدکار هرزه، به یک چاقو کش باج بگیر محله هم نرسیده، چه جور جانوری است؟ آدمی که در طول هفتاد سال، حتی یک شکنجه گر را از خود نرنجانده و توی گوش یک خبرچین خودفروش نزده است، با چنگ و دندان به جنگ یک رباخوار کلاه بردار نرفته، پسِ گردن یک گران فروش متقلب نزده، و تفی بزرگ به صورت یک سیاستمدار خودباخته ی وابسته به اجنبی نینداخته، با کدام تعریفِ آدمیت و انسانیت تطبیق می کندو به چه درد این دنیا می خورد؟\r\nآقا ی محترم!ما نیامده ایم که بود و نبودمان هیچ تاثیری بر جامعه بر تاریخ، بر زندگی و بر آینده نداشته باشد. ما آمده ایم که با دشمنان آزادی دشمنی کنیم و برنجانیم شان، و همدوش مردان با ایمان تفنگ برداریم و سنگر بسازیم، و همپای آدمهای عاشق، به خاطر اصالت و صداقت عشق بجنگیم.\r\n\r\nما آمده ایم  که با حضورمان، جهان را دگرگون کنیم، نیامده ایم تا پس از مرگمان بگویند: از کرم خاکی هم بی آزارتر بود و از گاو مظلومتر، ما باید وجودمان و نفس کشیدنمان، و راه رفتنمان، و نگاه کردنمان،و لبخند زدنمان هم مانند تیغ به چشم و گلوی بدکاران و ستمگران برود...\r\n\r\nما نیامده ایم فقط به خاطر آنکه همچون گوسفندی زندگی کرده باشیم که پس از مرگمان، گرگ و چوپان و سگ گله، هر سه ستایشمان کنند...\r\n\r\nگمان می کنم که آن آقا خیلی وقت بود که از کنارم رفته بود، و شاید من هم، فقط در دل خویش سخن می گفتم تا مبادا یکی از خویشاوندان خوب را چنان برنجانم که در مجلس ختمم حضور به هم نرساند.\r\n"},{"id":1858,"category_id":2,"category_code":"s2","source_id":25,"title":"مرا بغل کن ","content":"روزی زنی روستائی که هرگز حرف دلنشینی از همسرش نشنیده بود، بیمار شد شوهر او که راننده موتور سیکلت بود و از موتورش براى‌ حمل و نقل کالا در شهر استفاده مى‌کردبراى اولین بار همسرش را سوار موتورسیکلت خود کرد. زن با احتیاط سوار موتور شد و از دست پاچگی و خجالت نمی دانست دست هایش را کجا بگذارد که ناگهان شوهرش گفت:\r\nمرا بغل کن. زن پرسید: چه کار کنم؟ و وقتی متوجه حرف شوهرش شد ناگهان صورتش سرخ شد با خجالت کمر شوهرش را بغل کرد و کم کم اشک صورتش را خیس نمود. به نیمه راه رسیده بودند که زن از شوهرش خواست به خانه برگردند، شوهرش با تعجب پرسید: چرا؟ تقریبا به بیمارستان رسیده ایم. زن جواب داد: دیگر لازم نیست، بهتر شدم. سرم درد نمی کند. شوهر همسرش را به خانه رساند ولى هرگز متوجه نخواهد شد که گفتن همان جمله ى ساده ى \"مرا بغل کن\" چقدر احساس خوشبختى را در قلب همسرش باعث شده که در همین مسیر کوتاه، سردردش را خوب کرده است.\r\n"},{"id":1859,"category_id":2,"category_code":"s2","source_id":26,"title":"کی بیشتر می فهمه! ","content":"شخصی مادر پیرش را در زنبیلی می گذاشت و هرجا می رفت، همراه خودش میبرد. روزی حضرت عیسی او را دید، به وی فرمود: آن زن کیست گفت مادرم است. فرمود: او را شوهر بده. گفت: پیر است و قادر به حرکت نیست. پیرزن دستش را از زنبیل بیرون آورد و بر سر پسرش زد و گفت: آخه نکبت! تو بهتر می فهمی یا پیغمبر خدا؟"},{"id":1860,"category_id":2,"category_code":"s2","source_id":27,"title":"پشت هر مرد یه زن باهوش وجود داره! ","content":"خانم باربارا والترز که از مجریان بسیار سرشناس تلویزیون های معتبر آمریکاست سالها پیش از شروع مبارزات آزادی طلبانه افغانستان داستانی مربوط به نقشهای جنسیتی در کابل تهیه کرد. در سفری که به افغانستان داشت متوجه شده بود که زنان همواره و بطور سنتی 5 قدم عقب تر از همسرانشان راه می روند.\r\nخانم والترز اخیرا نیز سفری به کابل داشت ملاحظه کرد که هنوز هم زنان پشت سر همسران خود قدم بر می دارند و...\r\nعلی رغم کنار زدن رژیم طالبان، زنان شادمانه سنت قدیمی را پاس می دارند.\r\nخانم والترز به یکی از این زنان نزدیک شده و می پرسد: چرا شما زنان اینقدر خوشحالید از اینکه سنت دیرین را که زمانی برای از میان برداشتنش تلاش می کردید همچنان ادامه می دهید؟\r\nاین زن مستقیم به چشمان خانم والترز خیره شده و می گوید: بخاطر مین های زمینی!!\r\n"},{"id":1861,"category_id":2,"category_code":"s2","source_id":28,"title":"پاسخ دکتر حسابی ","content":"یکی از دانشجویان دکتر حسابی به ایشان گفت : شما سه ترم است که مرا از این درس می اندازید. من که نمی خواهم موشک هوا کنم . می خواهم در روستایمان معلم شوم . \r\nدکتر جواب داد : تو اگر نخواهی موشک هواکنی و فقط بخواهی معلم شوی قبول ، ولی تو نمی توانی به من تضمین بدهی که یکی از شاگردان تو در روستا ، نخواهد موشک هوا کند .\r\n"},{"id":1862,"category_id":2,"category_code":"s2","source_id":29,"title":"جراح و تعمیرکار ","content":"\r\nروزی جراحی برای تعمیر اتومبیلش آن را به تعمیرگاهی برد!\r\nتعمیرکار بعد از تعمیر به جراح گفت: من تمام اجزا ماشین را به خوبی می شناسم و موتور و قلب آن را کامل باز می کنم و تعمیر میکنم! در حقیقت من آن را زنده می کنم! حال چطور درآمد...\r\nسالانه ی من یک صدم شما هم نیست؟!\r\nجراح نگاهی به تعمیرکار انداخت و گفت : اگر می خواهی درآمدت ۱۰۰برابر من شود اینبار سعی کن زمانی که موتور در حال کار است آن را تعمیر کنی!\r\n"},{"id":1863,"category_id":2,"category_code":"s2","source_id":30,"title":"ارزش کار ","content":"جنگ جهانی اول مثل بیماری وحشتناکی ، تمام دنیا رو گرفته بود. یکی از سربازان به محض این که دید دوست تمام دوران زندگی اش در باتلاق افتاده و در حال دست و پنجه نرم کردن با مرگ است از مافوقش اجازه خواست تا برای نجات دوستش برود و او را از باتلاق خارج کند.\r\nمافوق به سرباز گفت : اگر بخواهی می توانی بروی ، اما هیچ فکر کردی این کار ارزشش را دارد یا نه ؟\r\nدوستت احتمالا مرده و ممکن است تو حتی زندگی خودت را هم به خطر بیندازی\r\nحرف های مافوق اثری نداشت و ...\r\nسرباز به نجات دوستش رفت. به شکل معجزه آسایی توانست به دوستش برسد، او را روی شانه هایش کشید و به پادگان رساند.\r\nافسر مافوق به سراغ آن ها رفت، سربازی را که در باتلاق افتاده بود معاینه کرد و با مهربانی و دلسوزی به دوستش نگاه کرد و گفت :من به تو گفتم ممکنه که ارزشش را نداشته باشه، دوستت مرده! خود تو هم زخم های عمیق و مرگباری برداشتی\r\nسرباز در جواب گفت: قربان ارزشش را داشت.\r\n\r\nمنظورت چیه که ارزشش را داشت!؟ می شه بگی؟\r\nسرباز جواب داد: بله قربان، ارزشش را داشت، چون زمانی که به او رسیدم هنوز زنده بود، من از شنیدن چیزی که او گفت احساس رضایت قلبی می کنم.\r\nاون گفت: \" جیم .... من می دونستم که تو به کمک من می آیی\"\r\n"},{"id":1864,"category_id":2,"category_code":"s2","source_id":31,"title":"آرزو ","content":"همگی به صف ایستاده بودند تا از آنها پرسیده شود ؛ نوبت به او رسید : \"دوست داری روی زمین چه کاره باشی؟\" گفت: می خواهم به دیگران یاد بدهم، پس پذیرفته شد! چشمانش رابست، دید به شکل درختی در یک جنگل بزرگ درآمده است. باخودگفت : حتما اشتباهی رخ داده است! من که این را نخواسته بودم؟!....\r\n\r\nسالها گذشت تا اینکه روزی داغ تبر را روی کمر خود احساس کرد ، با خود گفت : این چنین عمر من به پایان رسید و من بهره ی خود را از زندگی نگرفتم! با فریادی غم بار سقوط کرد و با صدایی غریب که از روی تنش بلند میشد به هوش آمد!\r\nحالا تخته سیاهی بر دیوار کلاس شده بود!\r\n"},{"id":1865,"category_id":2,"category_code":"s2","source_id":32,"title":"هر که بامش بیش برف بیشتر ","content":"یکی از پادشاهان عمرش به سر آمد و دار فانی را بدرود گفت و به سوی عالم باقی شتافت چون وارث و جانشینی نداشت وصیت کرد.بامداد نخستین روز پس از مرگش اولین کسی که از دروازه ی شهر در آید تاج شاهی را بر سر وی نهند و کلیه ی اختیارات مملکت را به او واگذار کنند.\r\n\r\nاتفاقا فردای آن روز؛اولین فردی که وارد شهر شد گدائی بود که در همه ی عمر مقداری پول اندوخته و لباسی کهنه و پاره که وصله بر وصله بود به تن داشت.\r\nارکان دولت و بزرگان وصیت شاه را به جای آوردند و کلیه خزائن و گنجینه ها به او تقدیم داشتند و او را از خاک مذلت بر داشتند و به تخت عزت و قدرت نشاندند.پس از مدتی که درویش به مملکتداری مشغول بود.به تدریج ...\r\nبعضی از امرای دولت سر از اطاعت و فرمانبرداری وی پیچیدند و پادشاهان ممالک همسایه نیز از هر طرف به کشور او تاختند.درویش به مقاومت برخاست و چون دشمنان تعدادشان زیادتر و قوی تر بود به ناچار شکست خورد و بعضی از نواحی و برخی از شهرها از دست وی بدر رفت. درویش از این جهت خسته خاطر و آرزده دل گشت.\r\n\r\nدر این هنگام یکی از دوستان سابقش که در حال درویشی رفیق سیر و سفر او بود به آن شهر وارد شد و یار جانی و برادر ایمانی خود را در چنان مقام و مرتبه دید به نزدش شتافت و پس از ادای احترام و تبریک و درود و سلام گفت ای رفیق شفیق شکر خدای را که گلت از خار برآمد و خار از پایت بدر آمد.بخت بلندت یاوری کرد و اقبال و سعادت رهبری؛تا بدین پایه رسیدی!\r\nدرویش پادشاه شده گفت:ای یار عزیز در عوض تبریک؛تسلیت گوی آن دم که تو دیدی غم نانی داشتم و امروز تشویش جهانی!\r\n\r\nرنج خاطر و غم و غصه ام امروز در این مقام و مرتبه صدها برابر آن زمان و دورانی است که به اتفاق به گدائی مشغول بودیم و روزگار می گذراندیم!\r\n"},{"id":1866,"category_id":2,"category_code":"s2","source_id":33,"title":"رستوران مبتکر ","content":"یکی از غذاخوری های بین راه بر سر در ورودی با خط درشت نوشته بود:\r\nشما در این مکان غذا میل بفرمایید، ما پول آن را از نوه شما دریافت خواهیم کرد.\r\nراننده ای با خواندن این تابلو اتومبیلش را فوراً پارک کرد و وارد شد و ناهار مفصلی سفارش داد و نوش جان کرد.\r\nبعد از خوردن غذا سرش را پایین انداخت که بیرون برود، ولی دید....\r\nکه خدمتگزار با صورتحسابی بلند بالا جلویش سبز شده است.\r\nبا تعجب گفت: مگر شما ننوشته اید که پول غذا را از نوه من خواهید گرفت؟!\r\nخدمتگزار با لبخند جواب داد: چرا قربان، ما پول غذای امروز شما را از نوه تان خواهیم گرفت،\r\nولی این صورتحساب مال مرحوم پدربزرگ شماست.\r\n"},{"id":1867,"category_id":2,"category_code":"s2","source_id":34,"title":"پیرمرد و سالک ","content":"پیر مردی بر قاطری بنشسته بود و از بیابانی می گذشت .. سالکی را بدید که پیاده بودپیر مرد گفت : ای مرد به کجا رهسپاری؟ سالک گفت : به دهی که گویند مردمش خدا نشناسند و کینه و عداوت می ورزند و زنان خود را از ارث محروم می‌کنندپیر مرد گفت : به خوب جایی می روی \r\nسالک گفت : چرا ؟پیر مرد گفت : من از مردم آن دیارم و دیری است که چشم انتظارم تا کسی بیاید و این مردم را هدایت کند سالک گفت : پس آنچه گویند راست باشد ؟پیر مرد گفت : تا راست چه باشد\r\nسالک گفت : آن کلام که بر واقعیتی صدق کند \r\nپیر مرد گفت : در آن دیار کسی را شناسی که در آنجا منزل کنی ؟\r\nسالک گفت : نه \r\nپیر مرد گفت : مردمانی چنین بد سیرت چگونه تو را میزبان باشند ؟...\r\nسالک گفت : ندانم \r\nپیر مرد گفت : چندی میهمان ما باش . باغی دارم و دیری است که با دخترم روزگار می گذرانم \r\nسالک گفت : خداوند تو را عزت دهد اما نیک آن است که به میانه مردمان کج کردار روم و به کار خود رسم \r\nپیر مرد گفت : ای کوکب هدایت شبی در منزل ما بیتوته کن تا خودت را بازیابی و هم دیگران را بازسازی \r\nسالک گفت : برای رسیدن شتاب دارم \r\nپیر مرد گفت : نقل است شیخی از آن رو که خلایق را زودتر به جنت رساند آنان را ترکه می زد تا هدایت شوند . ترسم که تو نیز با مردم این دیار کج کردار آن کنی که شیخ کرد \r\nسالک گفت : ندانم که مردم با ترکه به جنت بروند یا نه ؟\r\nپیر مرد گفت : پس تامل کن تا تحمل نیز خود آید . خلایق با خدای خود سرانجام به راه آیندپیرمرد و سالک به باغ رسیدند . از دروازه باغ که گذر کردند \r\nسالک گفت : حقا که اینجا جنت زمین است . آن چشمه و آن پرندگان به غایت مسرت بخش اند \r\nپیر مرد گفت : بر آن تخت بنشین تا دخترم ما را میزبان باشددختر با شال و دستاری سبز آمد و تنگی شربت بیاورد و نزد میهمان بنهاد . سالک در او خیره بماند و در لحظه دل باخت . شب را آنجا بیتوته کرد و سحرگاهان که به قصد گزاردن نماز برخاست \r\nپیر مرد گفت : با آن شتابی که برای هدایت خلق داری پندارم که امروز را رهسپاری \r\nسالک گفت : اگر مجالی باشد امروز را میهمان تو باشم \r\nپیر مرد گفت : تامل در احوال آدمیان راه نجات خلایق است . اینگونه کن سالک در باغ قدمی بزد و کنار چشمه برفت . پرنده ها را نیک نگریست و دختر او را میزبان بود . طعامی لذیذ بدو داد و گاه با او هم کلام شد . دختر از احوال مردم و دین خدا نیک آگاه بود و سالک از او غرق در حیرت شد . روز دگر سالک نماز گزارد و در باغ قدم زد پیرمرد او را بدید و گفت : لابد به اندیشه ای که رهسپار رسالت خود بشوی سالک چندی به فکر فرو رفت و گفت : عقل فرمان رفتن می دهد اما دل اطاعت نکند\r\nپیر مرد گفت : به فرمان دل روزی دگر بمان تا کار عقل نیز سرانجام گیرد سالک روزی دگر بماند\r\nپیر مرد گفت : لابد امروز خواهی رفت , افسوس که ما را تنها خواهی گذاشت \r\nسالک گفت : ندانم خواهم رفت یا نه , اما عقل به سرانجام رسیده است . ای پیرمرد من دلباخته دخترت هستم و خواستگارش پیر مرد گفت : با اینکه این هم فرمان دل است اما بخر دانه پاسخ گویم سالک گفت : بر شنیدن بی تابم \r\nپیر مرد گفت : دخترم را تزویج خواهم کرد به شرطی \r\nسالک گفت : هر چه باشد گر دن نهم \r\nپیر مرد گفت : به ده بروی و آن خلایق کج کردار را به راه راست گردانی تا خدا از تو و ما خشنود گردد\r\nسالک گفت : این کار بسی دشوار باشد\r\nپیر مرد گفت : آن گاه که تو را دیدم این کار سهل می نمود\r\nسالک گفت : آن زمان من رسالت خود را انجام می دادم اگر خلایق به راه راست می شدند , و اگر نشدند من کار خویشتن را به تمام کرده بودم \r\nپیر مرد گفت : پس تو را رسالتی نبود و در پی کار خود بوده ای \r\nسالک گفت : آری \r\nپیر مرد گفت : اینک که با دل سخن گویی کج کرداری را هدایت کن و باز گرد آنگاه دخترم از آن تو\r\nسالک گفت : آن یک نفر را من بر گزینم یا تو ؟\r\nپیر مرد گفت : پیر مردی است ربا خوار که در گذر دکان محقری دارد و در میان مردم کج کردار ,او شهره است \r\nسالک گفت : پیرمردی که عمری بدین صفت بوده و به گناه خود اصرار دارد چگونه با دم سرد من راست گردد ؟\r\nپیر مرد گفت : تو برای هدایت خلقی می رفتی \r\nسالک گفت : آن زمان رسم عاشقی نبود\r\nپیر مرد گفت : نیک گفتی . اینک که شرط عاشقی است برو به آن دیار و در احوال مردم نیک نظر کن , می خواهم بدانم جه دیده و چه شنیده ای ؟\r\nسالک گفت : همان کنم که تو گویی \r\nسالک رفت , به آن دیار که رسید از مردی سراغ پیر مرد را گرفت مرد گفت : این سوال را از کسی دیگر مپرس \r\nسالک گفت : چرا ؟مرد گفت : دیری است که توبه کرده و از خلایق حلالیت طلبیده و همه ثروت خود را به فقرا داده و با دخترش در باغی روزگار می گذراند \r\nسالک گفت : شنیده ام که مردم این دیار کج کردارند \r\nمرد گفت : تازه به این دیار آمده ام , آنچه تو گویی ندانم . خود در احوال مردم نظاره کن سالک در احوال مردم بسیار نظاره کرد . هر آنکس که دید خوب دید و هر آنچه دید زیبا . برگشت دست پیر مرد را بوسید پیر مرد گفت : چه دیدی ؟\r\nسالک گفت : خلایق سر به کار خود دارند و با خدای خود در عبادت \r\nپیر مرد گفت : وقتی با دلی پر عشق در مردم بنگری آنان را آنگونه ببینی که هستند، نه آنگونه که خود خواهی.\r\n"},{"id":1868,"category_id":2,"category_code":"s2","source_id":35,"title":"دزد و عارف ","content":"دزدی وارد کلبه فقیرانه عارفی شد\r\nکه کلبه درخارج شهر واقع شده بود عارف بیداربود اوجز یک پتو چیزی نداشت .\r\n\r\nاوشب ها نیمی از پتو را زیر خود می انداخت ونیمی دیگر را روی خود می کشید  روزها نیز بدن برهنه خویش را با آن می پوشاند.\r\nعارف پیر دزد رادید وچشمان خود رابست ،مبادا دزد را شرمنده کرده باشد آن دزد راهی دراز را آمده بود، به امید آنکه چیزی نصیبش شود  .اوباید درفقری شدید بوده باشد، زیرا به خانه محقرانه این پیر عارف زده بود.\r\nعارف پتو را برسرکشیدوبرای حال زار آن دزد و نداری خویش گریست : خدایا چیزی در خانه من نیست و این دزد بینوا بادست خالی و ناامید از این جا خواهد رفت. اگر او دوسه روز پیش مرا از تصمیم خویش باخبر ساخته بود ،می رفتم ، پولی قرض می گرفتم، وبرای این مردک بینوا روی تاقچه می گذاشتم...\r\nآن عارف فرزانه نگران نبود که دزد اموال اوراخواهد برد اونگران بود که چیزی در خور ندارد تا نصیب دزد شود واوراخوشحال کند .\r\nداخل خانه عارف تاریک بود .پیرمرد شمعی روشن کرد تا دزد بتواند درپرتو آن زمین نخورد وخانه را بهتر وارسی کند.\r\nاستاد شمع را برد تا روی تاقچه بگذارد که ناگهان با دزد چهره به چهره برخورد کرد دزد بسیار ترسیده بود. او می دانست که این مرد مورد اعتماد اهالی شهر است بنابر این اگر به مردم موضوع دزدی او را بگوید همه باور خواهند کرد .\r\nاما آن پیر عارف گفت: نترس آمده ام تا کمکت کنم داخل خانه تاریک است . وانگهی من سی سال است که در این خانه زندگی می کنم وهنوز هیچ چیز در آن پیدا نکرده ام بیا با هم بگردیم اگر چیزی پیدا کردیم پنجاه پنجاه تقسیمش می می کنیم .\r\nالبته اگر تو راضی باشی. اگر هم خواستی می تونی همه اش را برداری زیرا من سالها گشته ام و چیزی پیدا نکرده ام .پس همه آن مال تو. بالاخره یابنده تو بودی .\r\nدل دزد نرم شد.استاد نه او را تحقیر کرد نه سرزنش.\r\nدزد گفت: مرا ببخشید استاد.نمی دانستم که این خانه شماست وگرنه جسارت نمی کردم.\r\nعارف گفت: اما درست نیست که دست خالی از این  جابروی.من یک پتو دارم هوا دارد سرد می شود لطف کن و این پتو را از من قبول کن.\r\nاستاد پتو را به دزد داد دزد از اینکه می دید در آن خانه چیزی جز پتو وجود ندارد شگفت زده شد سعی کرد استاد را متقاعد کند تا پتو را نزد خود نگه دارد .\r\nاستادگفت:  احساسات مرا بیش از این جریحه دارنکن دفعه دیگر پیش از این که به من سری  بزنی مرا خبر کن .اگر به چیزی خاص هم نیاز داشتی بگو تا همان را برایت آماده کنم تو مرا غافلگیر و شرمنده کردی ، می دانم که این پتوی کهنه ارزشی ندارد اما دلم نمی آید تو را بادست خالی روانه کنم لطف کن وآن را از من بپذیر .تا ابد ممنون تو خواهم بود .\r\n\r\nدزد گیج شده بود او نمی دانست چه کار کند . تا کنون به چنین آدمی برخورد نکرده بود. خم شد پاهای استاد را بوسید پتو را تا کرد و بیرون رفت.\r\nاو وزیر و وکیل و فرماندار دیده بود ولی انسان ندیده بود .\r\nپیش از انکه دزد از خانه بیرون رود استاد صدایش کرد وگفت: فراموش نکن که امشب مرا خوشحال کردی من همه عمرم را مثل یک گدا زندگی کرده ام . من چون چیزی نداشتم از لذت بخشیدن نیز محروم بوده ام اما امشب تو به من لذت بخشیدن را چشاندی  ممنونم...\r\n"},{"id":1869,"category_id":2,"category_code":"s2","source_id":36,"title":"پلیدی و نیکی","content":"پسر به سفر دوری رفته بود و ماه ها بود که از او خبری نداشتند ...\r\nمادرش دعا می کرد که او سالم به خانه باز گردد. هر روز به تعداد اعضای خانواده اش نان می پخت و همیشه یک نان اضافه هم می پخت و پشت پنجره می گذاشت تا رهگذری گرسنه که از آن جا می گذشت نان را بر دارد . هر روز مردی گو‍ژ پشت از آن جا می گذشت و نان را بر می داشت و به جای آن که از او تشکر کند می گفت:\r\nهر کار پلیدی که بکنید با شما می ماند و هر کار نیکی که انجام دهید به شما باز می گردد !!!\r\n\r\nاین ماجرا هر روز ادامه داشت تا این که زن از گفته های مرد گوژ پشت ناراحت و رنجیده شد  و به خود گفت : او نه تنها تشکر نمی کند بلکه هر روز این جمله ها را به زبان می آورد . نمی د انم منظورش چیست؟\r\nیک روز که زن از گفته های مرد گو‍ژ پشت کاملا به تنگ آمده بود تصمیم گرفت از شر او خلاص شود بنابر این نان او را زهر آلود کرد و آن را با دست های لرزان پشت پنجره گذاشت، اما ناگهان به خود گفت : این چه کاری است که می کنم ؟ .....\r\nبلافاصله نان را برداشت و دور انداخت و نان دیگری برای مرد گوژ پشت پخت .\r\nمرد مثل هر روز آمد و نان را برداشت و حرف های معمول خود را تکرار کرد و به راه خود رفت.\r\n\r\nآن شب در خانه پیر زن به صدا در آمد . وقتی که زن در را باز کرد، فرزندش را دید که نحیف و خمیده با لباس هایی پاره پشت در ایستاده بود او گرسنه، تشنه و خسته بود، در حالی که به مادرش نگاه می کرد، گفت:\r\nمادر اگر این معجزه نشده بود نمی توانستم خودم را به شما برسانم. در چند فرسنگی این جا چنان گرسنه و ضعیف شده بودم که داشتم از هوش می رفتم . ناگهان رهگذری گو‍ژ پشت را دیدم که به سراغم آمد. او لقمه ای غذا خواستم و او یک نان به من داد و گفت : این تنها چیزی است که من هر روز می خورم امروز آن را به تو می دهم زیرا که تو بیش از من به آن احتیاج داری .\r\n\r\nوقتی که مادر این ماجرا را شنید رنگ از چهره اش پرید. به یاد آورد که ابتدا نان زهر آلودی برای مرد گوژ پشت پخته بود و اگربه ندای وجدانش گوش نکرده بود و نان دیگری برای او نپخته بود، فرزندش نان زهر آلود را می خورد .\r\nبه این ترتیب بود که آن زن معنای سخنان روزانه مرد گوژ پشت را دریافت:\r\nهر کار پلیدی که انجام می دهیم با ما می ماند و نیکی هایی که انجام می دهیم به خود ما باز می گردد.\r\n"},{"id":1870,"category_id":2,"category_code":"s2","source_id":37,"title":"تاجر میمون ","content":"روزی روزگاری در روستایی در هند؛ مردی به روستایی‌ها اعلام کرد که برای خرید هر میمون 20 دلار به آنها پول خواهد داد. روستایی‌ها هم که دیدند اطراف‌شان پر است از میمون؛ به جنگل رفتند و شروع به گرفتن‌شان کردند و مرد هم هزاران میمون به قیمت 20 دلار از آنها خرید ولی با کم شدن تعداد میمون‌ها روستایی‌ها دست از تلاش کشیدند. به همین خاطر مرد این‌بار پیشنهاد داد برای هر میمون به آنها 40 دلار خواهد پرداخت. با این شرایط روستایی‌ها فعالیت خود را از سر گرفتند. پس از مدتی موجودی باز هم کمتر و کمتر شد تا روستایی‌ان دست از کار کشیدند و برای کشاورزی سراغ کشتزارهای‌شان رفتند.\r\n\r\nاین بار پیشنهاد به 45 دلار رسید و\r\nدر نتیجه تعداد میمون‌ها آن‌قدر کم شد که به سختی می‌شد میمونی برای گرفتن پیدا کرد. این‌بار نیز مرد تاجر ادعا کرد که برای خرید هر میمون60 دلار خواهد داد ولی چون برای کاری باید به شهر می‌رفت کارها را به شاگردش محول کرد تا از طرف او میمون‌ها را بخرد.\r\n \r\nدر غیاب تاجر، شاگرد به روستایی‌ها گفت: «این همه میمون در قفس را ببینید! من آنها را به 50 دلار به شما خواهم فروخت تا شما پس از بازگشت مرد آنها را به60 دلار به او بفروشید.» روستایی‌ها که [احتمالا مثل شما] وسوسه شده بودند پول‌های‌شان را روی هم گذاشتند و تمام میمون‌ها را خریدند... البته از آن به بعد دیگر کسی مرد تاجر و شاگردش را ندید و تنها روستایی‌ها ماندند و یک دنیا میمون.\r\n\r\n"},{"id":1871,"category_id":2,"category_code":"s2","source_id":38,"title":"کلاس فلسفه ","content":"پروفسور فلسفه با بسته  سنگینی وارد کلاس درس فلسفه شد و بار سنگین خود را روبروی دانشجویان   خود روی میز گذاشت.\r\nوقتی کلاس شروع شد، بدون هیچ کلمه ای، یک شیشه بسیار بزرگ از داخل بسته برداشت   و شروع به پر کردن آن با چند توپ گلف کرد.\r\nسپس  از شاگردان خود پرسید که، آیا این ظرف پر است؟\r\nو همه دانشجویان موافقت کردند.\r\nسپس پروفسور ظرفی از سنگریزه برداشت و آنها رو به داخل شیشه...\r\nریخت و شیشه رو به آرامی تکان داد. سنگریزه ها در بین مناطق باز بین توپ های گلف قرار گرفتند؛   سپس دوباره از دانشجویان پرسید که آیا ظرف پر است؟ و باز همگی موافقت کردند.\r\nبعد دوباره پروفسور ظرفی از ماسه را برداشت و داخل شیشه ریخت؛ و خوب البته، ماسه ها همه جاهای خالی رو پر کردند. او یکبار دیگرپرسید که آیا ظرف پر است و دانشجویان یکصدا گفتند: \"بله\". \r\n\r\nبعد پروفسور دو فنجان پر از قهوه از زیر میز برداشت و روی همه محتویات داخل شیشه خالی کرد. \"در حقیقت دارم جاهای خالی بین ماسه ها رو پر می کنم!\" همه دانشجویان خندیدند.\r\nدر حالی که صدای خنده فرو می نشست، پروفسور گفت: \" حالا من می خوام که متوجه این مطلب بشین که این شیشه نمایی از زندگی شماست، توپهای گلف مهمترین چیزها در زندگی شما هستند – خدایتان، خانواده تان، فرزندانتان، سلامتیتان ، دوستانتان و مهمترین علایقتان- چیزهایی که اگر همه چیزهای دیگر از بین بروند ولی اینها باقی بمانند، باز زندگیتان پای برجا خواهد بود.\r\nاما سنگریزه ها سایر چیزهای قابل اهمیت هستند مثل کارتان، خانه تان و ماشی نتان. ماسه ها هم سایر چیزها هستند- مسایل خیلی ساده.\"\r\nپروفسور ادامه داد: \"اگر اول ماسه ها رو در ظرف قرار بدید، دیگر جایی برای سنگریزه ها و توپهای گلف باقی نمی مونه، درست عین زندگیتان. اگر شما همه زمان و انرژیتان را روی چیزهای ساده و پیش پا افتاده صرف کنین، دیگر جایی و زمانی برای مسایلی که برایتان اهمیت داره باقی نمی مونه. به چیزهایی که برای شاد بودنتان اهمیت داره توجه زیادی کنین، با فرزندانتان بازی کنین، زمانی رو برای چک آپ پزشکی بذارین. با دوستان و اطرافیانتان به بیرون بروید و با اونها خوش بگذرونین.\r\nهمیشه زمان برای تمیز کردن خانه و تعمیر خرابیها هست. همیشه در دسترس باشین.\r\n\r\nاول مواظب توپ های گلف باشین، چیزهایی که واقعاً برایتان اهمیت دارند، موارد دارای اهمیت رو مشخص کنین. بقیه چیزها همون ماسه ها هستند.\"\r\nیکی از دانشجویان دستش را بلند کرد و پرسید: پس دو فنجان قهوه چه معنی داشتند؟\r\nپروفسور لبخند زد و گفت: \" خوشحالم که پرسیدی. این فقط برای این بود که به شما نشون بدم که مهم نیست که زندگیتان چقدر شلوغ و پر مشغله ست، همیشه در زندگی شلوغ هم ، جائی برای صرف دو فنجان قهوه با یک دوست هست! \"\r\n"},{"id":1872,"category_id":2,"category_code":"s2","source_id":39,"title":"ظرفیت انسان ها ","content":"مردی از دست روزگار سخت می نالید. پیش استادی رفت و برای رفع غم و رنج خود راهی خواست.استاد لیوان اب نمکی را به خورد او داد و از مزه اش پرسید؟\r\nآن مرد آب را به بیرون از دهان ریخت و گفت: خیلی شور و غیر قابل تحمل است.\r\nاستاد وی را کنار دریا برده و به وی گفت همان مقدار اب بنوشد و بعد از مزه اش پرسید؟\r\nمرد گفت: ...\r\nخوب است و می توان تحمل کرد.\r\nاستاد گفت شوری آب همان سختی های زندگی است. شوری این دو آب یکی ولی ظرفشان متفاوت بود. سختی و رنج دنیا همیشه ثابت است و این ظرفیت ماست که مزه انرا تعین می کند پس وقتی در رنج هستی بهترین کار بالا بردن ظرفیت و درک خود از مسائل است.\r\n"},{"id":1873,"category_id":2,"category_code":"s2","source_id":40,"title":"طرح هدف مند منصور خلیفه دوم عباس ","content":"داستان از این قراره که منصور دوانیقی خلیفه دوم عباسی بعد  از انتقال پایتخت به بغداد تصمیم گرفت برای دفاع از این شهر دور اونو دیوار بکشه .  اما دلش نمی خواست پول ساختن دیوارو از جیب خودش بده . بنابر این تصمیم خاصی اتخاذ کرد . اون در شهر اعلام کرد که قراره سرشماری بشه و هر کس به تعداد اعضای  خانواده یک سکه نقره دریافت خواهد کرد . مردم که هم طمع کار شده بودند و هم از بس به اعوامل خلیفه مالیات داده بودند خسته شده بودند...\r\nوقتی مامور ثبت میومد ، اعضای خانواده رو زیاد میگفتند. مثلا اونی که اعضای خانوادش 4 نفر بودند تعداد رو 8 نفر میگفت و 8 سکه نقره میگرفت .  و مامور ثبت بعد از دادن 8 سکه نقره  ، یه پلاک رو سر در خونه نصب میکرد و تعداد اعضای خانواده رو روی اون حک میکردند . خلاصه بعد از اتمام سر شماری مردم سخت خوشحال بودند که سر منصورو کلاه گذاشتن . اما بلافاصله بعد از اتمام سر شماری خلیفه حکمی صادر کرد که : به منظور حفظ مملکت و دفاع از کیان کشور و ایجاد امنیت ما خلیفه مسلمین تصمیم گرفتیم که بر گرداگرد شهر دیوار بکشیم . بنابر این هر یک از سکنه شهر میبایست برای تامین امنیت یک سکه طلا پرداخت نماید .  بیچاره مردم شهر تازه فهمیدند چه خبره. حالا اونی که تعداد اعضای خانواده رو زیاد گفته بود و یک سکه نقره گرفته بود بایستی به ازای اون یه نفر یه سکه طلا که قیمتش بیشتر از سکه نقره بود می پرداختند .\r\n"},{"id":1874,"category_id":2,"category_code":"s2","source_id":41,"title":"لنگه کفش ","content":"پیرمردی سوار بر قطار به مسافرت می رفت\r\nبه علت بی توجهی یک لنگه کفش ورزشی وی از پنجره قطار بیرون افتاد\r\nمسافران دیگر برای پیرمرد تاسف می خوردند\r\nولی پیرمرد بی درنگ ...\r\nلنگه ی دیگر کفشش را هم بیرون انداخت.\r\nهمه تعجب کردند\r\nپیرمرد گفت که یک لنگه کفش نو برایم بی مصرف می شود ولی اگر کسی یک جفت کفش نو بیابد، چه قدر خوشحال خواهد شد.\r\n"},{"id":1875,"category_id":2,"category_code":"s2","source_id":42,"title":"پند سقراط ","content":"روزی سقراط ، حکیم معروف یونانی، مردی را دید که خیلی ناراحت و متاثراست. علت ناراحتیش را پرسید ،پاسخ داد:\"در راه که می آمدم یکی از  آشنایان را دیدم.سلام کردم جواب نداد و با بی اعتنایی و خودخواهی گذ شت  و رفت و من از این طرز رفتار او خیلی رنجیدم.\"  \r\nسقراط گفت:\"چرا رنجیدی؟\" مرد با تعجب گفت :\"خب معلوم است، چنین رفتاری   ناراحت کننده است.\"\r\nسقراط پرسید:....\r\n\"اگر در راه کسی را می دیدی که به زمین افتاده و از درد وبیماری به خود می پیچد، آیا از دست او دلخور و رنجیده می شدی؟\"\r\nمرد گفت:\"مسلم است که هرگز دلخور نمی شدم.آدم که از بیمار بودن کسی دلخور نمی شود.\"\r\nسقراط پرسید:\"به جای دلخوری چه احساسی می یافتی و چه می کردی؟\"\r\nمرد جواب داد:\"احساس دلسوزی و شفقت و سعی می کردم طبیب یا دارویی به او برسانم.\"\r\nسقراط گفت:\"همه ی این کارها را به خاطر آن می کردی که او را بیمار می دانستی،آیا انسان تنها جسمش بیمار می شود؟ و آیا کسی که رفتارش نادرست است،روانش بیمار نیست؟ اگر کسی فکر و روانش سالم باشد،هرگز رفتار بدی از او دیده نمی شود؟ بیماری فکر و روان نامش \"غفلت\" است و باید به جای دلخوری و رنجش ،نسبت به کسی که بدی می کند و غافل است،دل سوزاند و کمک کرد و به او طبیب روح و داروی جان رساند. پس از دست هیچکس دلخور مشو و کینه به دل مگیر و آرامش خود را هرگز از دست مده و بدان که هر وقت کسی بدی می کند، در آن لحظه بیمار است.\r\n"},{"id":1876,"category_id":2,"category_code":"s2","source_id":43,"title":"سه آمریکایی و سه ایرانی ","content":"سه نفر آمریکایی و سه نفر ایرانی با همدیگر برای شرکت در یک کنفرانس می رفتند. در ایستگاه قطار سه آمریکایی هر کدام یک بلیط خریدند، اما در کمال تعجب دیدند که ایرانی ها سه نفرشان یک بلیط خریده اند. یکی از آمریکایی ها گفت: چطور است که شما سه نفری با یک بلیط مسافرت می کنید؟ یکی از ایرانی ها گفت: صبر کن تا نشانت بدهیم.\r\n\r\nهمه سوار قطار شدند. آمریکایی ها روی صندلی های تعیین شده نشستند، اما ایرانی ها سه نفری رفتند توی یک توالت و در را روی خودشان قفل کردند. بعد، مامور کنترل قطار آمد و بلیط ها را کنترل کرد. بعد، در توالت را زد و گفت: بلیط، لطفا! بعد، در توالت باز شد و از لای در یک بلیط آمد بیرون، مامور قطار آن بلیط را نگاه کرد و به راهش ادامه داد. آمریکایی ها که این را دیدند، به این نتیجه رسیدند که\r\nچقدر ابتکار هوشمندانه ای بوده است.\r\nبعد از کنفرانس آمریکایی ها تصمیم گرفتند در بازگشت همان کار ایرانی ها را انجام دهند تا از این طریق مقداری پول هم برای خودشان پس انداز کنند. وقتی به ایستگاه رسیدند، سه نفر آمریکایی یک بلیط خریدند، اما در کمال تعجب دیدند که آن سه ایرانی هیچ بلیطی نخریدند. یکی از آمریکایی ها پرسید: چطور می خواهید بدون بلیط سفر کنید؟ یکی از ایرانی ها گفت: صبر کن تا نشانت بدهم.\r\nسه آمریکایی و سه ایرانی سوار قطار شدند، سه آمریکایی رفتند توی یک توالت و سه ایرانی هم رفتند توی توالت بغلی آمریکایی ها و قطار حرکت کرد. چند لحظه بعد از حرکت قطار یکی از ایرانی ها از توالت بیرون آمد و رفت جلوی توالت آمریکایی ها و گفت: بلیط ، لطفا !!!\r\n"},{"id":1877,"category_id":2,"category_code":"s2","source_id":44,"title":"مید نباید هرگز خاموش شود ","content":"چهار شمع به آرامی می سوختند، محیط آن قدر ساکت بود که می شد صدای صحبت آنها را شنید.اولین شمع گفت: « من صلح هستم، هیچ کس نمی تواند مرا همیشه روشن نگه دارد. فکر می کنم که به زودی خاموش شوم. هنوز حرف شمع صلح تمام نشده بود که شعله آن کم و بعد خاموش شد. »\r\nشمع دوم گفت: ...\r\n« من ایمان هستم، واقعا انگار کسی به من نیازی ندارد برای همین من دیگر رعبتی ندارم که بیشتر از این روشن بمانم . » حرف شمع ایمان که تمام شد ،نسیم ملایمی وزیدو آن را خاموش کرد.\r\nوقتی نوبت به سومین شمع رسید با اندوه کفت: « من عشق هستم توانایی آن را ندارم که روشن بمانم، چون مردم مرا به کناری انداخته اند و اهمیتم را نمی فهمند، آها حتی فراموش کرده اند که به نزدیکترین کسان خود محبت کنند و عشق بورزند. » پس شمع عشق هم بی درنگ خاموش شد . کودکی وارد اتاق شد و دید که سه شمع دیگر نمی سوزند. او گفت: « شما که می خواستید تا آخرین لحظه روشن بمانید، پس چرا دیگر نمی سوزید؟» چهارمین شمع گفت: « نگران نباشد، تا وقتی من روشن هستم، به کمک هم می توانیم شمع های دیگر را روشن کنیم. من امید هستم. » چشمان کودک درخشید، شمع امید را برداشت و بقیه شمع ها را روشن کرد.\r\nبنابر این شعله امید هرگز نباید خاموش شود. ما باید همیشه امید و ایمان و صلح و عشق را در وجود خود حفظ کنیم.\r\n"},{"id":1878,"category_id":2,"category_code":"s2","source_id":45,"title":"نهمین در بهشت ","content":"شاعر و فرشته ای با هم دوست شدند ، فرشته پری به شاعر داد و شاعـر شعری بـه فرشته . شاعر پر فرشته را لای دفتر شعرش گذاشت و شعرهایش بوی آسمان گرفت. و فرشته شعـر شاعر را زمزمه کرد و دهانش مزه عشق گرفت  \r\nخدا گفت: دیگر تمام شد.دیگرزندگی برای هر دوتان دشـوار می شود. زیرا شاعری که بـوی آسمـان را بشنود ، زمیـن برایش کوچـک اسـت و فـرشته ای کـه مـزه عـشق را  بچشد، آسمـان برایش تنـگ .  \r\nفرشته دست شاعر را گرفـت تا راه های آسمان را نشانش بدهـد و...\r\nشاعـر بال فرشته را گرفت تـا کوچـه پس کوچـه های زمیـن را به او معرفی کند . شـب کـه هر دو به خانه برگشتند ، روی بال های فرشته قدری خاک بود و روی شانه های شاعر چند تا پر .... فرشته پیش شاعر آمد و گفت : می خواهم عاشق شوم .  شاعر گفت : نه . تو فرشته ای و عشق کار تو نیست . فرشته اصرار کرد واصرار کرد .\r\nشاعر گفت : اما پیش از عاشقی باید عصیان کرد و اگـر چنین کنی از بهشت اخراجت می کنند . آیا آدم و سرنوشت تلخش را فراموش کرده ای ؟\r\nاما فرشته باز هم پافشاری کرد . آن قـدر که شاعر به ناچار نشانی درخـت ممنوعه را به او داد.\r\nفرشته رفت و از میوه آن درخت خورد .اما پرهایش ریخت و پشیمان شد. آ ن گاه پیش خدا رفت و گفت: خدایا مرا ببخش . من به خودم ظلم کرده ام . عصیان کردم و عاشق شدم . آ یا حالا مرا از بهشت بیرون می کنی ؟  \r\n_ پس تو هم این قصـه را وارونه فهمیدی !  \r\n پس تو هـم نمی دانی تنها آن که عصیـان می کند و عاشق می شود، می تواند به بهشت وارد شود ! و آ ن وقـت خدا نهمین در بهشت را باز کرد . فرشته وارد شد و شاعـر را دیـد که آنجـا نشسته است در سوگ هشت بهشت و رنج هبوط !  فرشته حقیقت ماجرا را برایش گفت . اما او باور نکرد. آدم ها هیچ کدام این قصه را باور نمی کنند. تنها آن فرشته است که می داند بهشت واقعی کجاست!\r\n"},{"id":1879,"category_id":2,"category_code":"s2","source_id":46,"title":"لحظه های عاشقانه ","content":"زن نصف شب از خواب بیدار می‌‌شود و می‌‌بیند که شوهرش در رختخواب نیست، ربدشامبرش را می‌‌پوشد و به دنبال او به طبقه ی پایین می‌‌رود،و شوهرش در آشپزخانه نشست بود در حالی‌ که یک فنجان قهوه هم روبرویش بود . در حالی‌ که به دیوار زل زده بود در فکری عمیق فرو رفته بود...\r\nزن او را دید که اشک‌هایش را پاک می‌‌کرد و قهوه‌اش را می‌‌نوشید... \r\nزن در حالی‌ که داخل آشپزخانه می‌‌شد آرام زمزمه کرد : \"چی‌ شده عزیزم؟ چرا این موقع شب اینجا نشستی؟\"\r\nشوهرش نگاهش را از قهوه‌اش بر می‌‌دارد و میگوید : هیچی‌ فقط اون موقع هارو به یاد میارم، ۲۰ سال پیش که تازه همدیگرو ملاقات می‌‌کردیم، یادته؟\r\nزن که حسابی‌ تحت تاثیر احساسات شوهرش قرار گرفته بود، چشم‌هایش پر از اشک شد ا گفت: \"آره یادمه...\"\r\nشوهرش به سختی‌ گفت:\r\n\r\n_ یادته که پدرت ما رو وقتی‌ که رو صندلی عقب ماشین بودیم پیدا کرد؟\r\n_آره یادمه (در حالی‌ که بر روی صندلی‌ کنار شوهرش نشست...)\r\n\r\n_یادته وقتی‌ پدرت تفنگ رو به سمت من نشون گرفته بود و گفت که یا با دختر من ازدواج میکنی‌ یا ۲۰ سال می‌‌فرستمت زندان ؟!\r\n\r\n_آره اونم یادمه...\r\nمرد آهی می‌‌کشد و می‌‌گوید: اگه رفته بودم زندان الان آزاد شده بودم...\r\n"},{"id":1880,"category_id":2,"category_code":"s2","source_id":47,"title":"عالم فروتن ","content":"گویند که زمانی در شهری دو عالم می زیستند . روزی یکی از دو عالم که بسیار پرمدعا بود ? کاسه گندمی بدست گرفت و بر جمعی وارد شد و گفت :\r\nاین کاسه گندم من هستم ! ( از نظر علم و ... ) و سپس دانه گندمی از آن برداشت و گفت :\r\nو این دانه گندم هم فلان عالم است !\r\nو شروع کرد به تعریف از خود .\r\nخبر به گوش آن عالم فرزانه رسید . فرمود به او بگوئید :\r\nآن یک دانه گندم هم خودش است ؟ من هیچ نیستم...\r\n"},{"id":1881,"category_id":2,"category_code":"s2","source_id":48,"title":"به اندازه فاصله زانو تا زمین! ","content":"\r\nروزی دو مرد جوان نزد استادی آمدند و ازاو پرسیدند:\r\nفاصله بین دچار یک مشکل شدن تا راه حل یافتن برای حل مشکل چقدراست؟\r\nاستاد اندکی تامل کرد و گفت:\r\nفاصله مشکل یک فرد و راه نجات او از آن مشکل برای هر شخصی به اندازه فاصله زانوی او تا زمین است!\r\nآن دو مرد جوان گیج و آشفته از نزد او بیرون آمدند و\r\nدر بیرون مدرسه با هم به بحث و جدل پرداختند. اولی گفت:\" من مطمئنم منظور استاد معرفت این بوده است که باید به جای روی زمین نشستن از جا برخاست و شخصا برای مشکل راه حلی پیدا کرد. با یک جا نشینی و زانوی غم در آغوش گرفتن هیچ مشکلی حل نمی شود. \"\r\nدومی کمی فکر کرد و گفت:\" اما اندرزهای پیران معرفت معمولا بارمعنایی عمیق تری دارند و به این راحتی قابل بیان نیستند. آنچه تو می گویی هزاران سال است که بر زبان همه جاری است و همه آن را می دانند. استاد منظور دیگری داشت.\"\r\nآندو تصمیم گرفتن نزد استاد بازگردند و از خود او معنای جمله اش را بپرسند. استاد با دیدن مجدد دو جوان لبخندی زد و گفت:\r\nوقتی یک انسان دچار مشکل می شود. باید ابتدا خود را به نقطه صفربرساند. نقطه صفر وقتی است که انسان در مقابل کائنات و خالق هستی زانو می زند و از او مدد می جوید.\r\nبعد از این نقطه صفر است که فرد می تواند برپا خیزد و با اعتماد به همراهی کائنات دست به عمل زند. بدون این اعتماد و توکل برای هیچ مشکلی راه حل پیدا نخواهد شد. باز هم می گویم...\r\nفاصله بین مشکلی که یک انسان دارد با راه چاره او ، فاصله بین زانوی او و زمینی است که برآن ایستاده است.\r\n"},{"id":1882,"category_id":2,"category_code":"s2","source_id":49,"title":"درسی بزرگ از یک کودک ","content":"سال ها پیش زمانی که به عنوان داوطلب در بیمارستان استانفورد مشغول کار بودم با دختری به نام لیزا آشنا شدم که از بیماری جدی و نادری رنج میبرد.\r\nظاهرا تنها شانس بهبودی او گرفتن خون از برادر پنج ساله خود بودکه او نیز قبلا مبتلا به این بیماری بود و به طرز معجزه آسایی نجات یافته بودو هنوز نیاز به مراقبت پزشکی داشت.پزشک معالج وضعیت بیماری خواهرش را توضیح داد و پرسید آیا برای بهبودی خواهرت مایل به اهدای خون هستی؟؟\r\nبرادر خردسال اندکی تردید کرد و....\r\nسپس نفس عمیقی کشید و گفت:بله من اینکار را برای نجات لیزا انجام خواهم داد.\r\nدر طول انتقال خون کنار تخت لیزا روی تختی دراز کشیده بودو مثل تمامی انسان ها که با مشاهده اینکه رنگ به چهره خواهرش باز میگشت خوشحال بود و لبخند میزد.سپس رنگ چهره اش پریده بیحال شده و لبخند بر لبانش خشکید.\r\nنگاهی به دکتر انداخته و با صدای لرزانی گفت:آیا میتوانم زودتر بمیرم؟؟؟\r\nپسر خردسال به خاطر سن کمش توضیحات دکتر معالج را عوضی فهمیده بود و تصور میکرد باید تمام خونش را به لیزا بدهدو با شجاعت خود را آماده مرگ کرده بود.\r\n"},{"id":1883,"category_id":2,"category_code":"s2","source_id":50,"title":"آزمون دامادها ","content":"\r\nزنی سه دختر داشت که هر سه ازدواج کرده بودند.\r\nیکروز تصمیم گرفت میزان علاقه ای که دامادهایش به او دارند را ارزیابی کند.\r\nیکی از دامادها را به خانه اش دعوت کرد و در حالی که در کنار استخر قدم\r\nمیزدند از قصد وانمود کرد که پایش لیز خورده و خود را درون استخر انداخت.\r\nدامادش فوراً...\r\nشیرجه رفت توی آب و او را نجات داد.\r\nفردا صبح یک ماشین پژو ٢٠٦ نو جلوی پارکینگ خانه داماد بود و روی شیشه اش\r\nنوشته بود: «متشکرم! از طرف مادر زنت»\r\n\r\nزن همین کار را با داماد دومش هم کرد و این بار هم داماد فوراً شیرجه رفت\r\nتوی آب و جان زن را نجات داد.\r\nداماد دوم هم فردای آن روز یک ماشین پژو ٢٠٦ نو هدیه گرفت که روی شیشه اش\r\nنوشته بود: «متشکرم! از طرف مادر زنت»\r\n\r\nنوبت به داماد آخری رسید.\r\nزن باز هم همان صحنه را تکرار کرد و خود را به داخل استخر انداخت اما\r\nداماد از جایش تکان نخورد او پیش خود فکر کرد وقتش رسیده که این پیرزن از\r\nدنیا برود پس چرا من خودم را به خطر بیاندازم؟\r\nهمین طور ایستاد تا مادر زنش در آب غرق شد و مرد.\r\nفردا صبح یک ماشین بی ام ‌و آخرین مدل جلوی پارکینگ خانه داماد سوم بود\r\nکه روی شیشه اش نوشته بود:«متشکرم! ازطرف پدر زنت»\r\n"},{"id":1884,"category_id":2,"category_code":"s2","source_id":51,"title":"افسانه ای از فداکاری زنان ... ","content":"بر بالای تپه‌ای در شهر وینسبرگ آلمان، قلعه ای قدیمی‌و بلند وجود دارد که مشرف بر شهر است. اهالی وینسبرگ افسانه ای جالب در مورد این قلعه دارند که بازگویی آن مایه مباهات و افتخارشان است\r\n \r\nافسانه حاکی از آن است که در قرن 15، لشکر دشمن این شهر را تصرف و قلعه را محاصره می‌کند. اهالی شهر از زن و مرد گرفته تا پیر و جوان، برای رهایی از چنگال مرگ به داخل قلعه پناه می‌برند.\r\nفرمانده دشمن به قلعه پیام می‌فرستد که...\r\nقبل از حمله ویران کننده خود حاضر است به زنان و کودکان اجازه دهد تا صحیح و سالم از قلعه خارج شده و پی کار خود روند.\r\nپس از کمی‌مذاکره، فرمانده دشمن به خاطر رعایت آیین جوانمردی و بر اساس قول شرف، موافقت می‌کند که هر یک از زنان در بند، گرانبها ترین دارایی خود را نیز از قلعه خارج کند به شرطی که به تنهایی قادر به حمل آن باشد.\r\nنا گفته پیداست که قیافه حیرت زده و سرشار از شگفتی فرمانده دشمن به هنگامی‌که هر یک از زنان شوهر خود را کول گرفته و از قلعه خارج می‌شدند بسیار تماشایی بود.\r\n"},{"id":1885,"category_id":2,"category_code":"s2","source_id":52,"title":"تصمیم درست در موقعیت ها ","content":"مردی زیر باران از دهکده کوچکی می گذشت . خانه ای دید که داشت می سوخت و مردی را دید که وسط شعله ها در اتاق نشیمن نشسته بود .مسافر فریاد زد:\r\nهی،خانه ات آتش گرفته است! مرد جواب داد : میدانم . \r\nمسافر گفت:پس چرا بیرون نمی آیی؟\r\nمرد گفت:آخر بیرون باران می آید . مادرم همیشه می گفت اگر زیر باران بروی ، سینه پهلو میکنی\r\nزائوچی در مورد این داستان می گوید : خردمند کسی است که وقتی مجبور شود بتواند موقعیتش را ترک کند .\r\n"},{"id":1886,"category_id":2,"category_code":"s2","source_id":53,"title":"بی وفا ","content":"داریه و تنبک می زد و با صدای بلند آواز می خواند، رهگذری نیم نگاهی به او انداخت و در دل هورا کشان گفت، آی مرد کاش من نیز جای تو بودم اینچنین شاد و بی غم ... مرد گفت: آواز دهل از دور شنیدن خوش است، اینچنین که تو فکر می کنی دل ما خوش و بی غم نیست. از او اصرار و از مرد انکار...\r\n\r\nآخر سر مرد گفت بیا تا شرح داستان این داریه و تنک  را برایت بگویم تا بدانی که این چنین نیست و مرد با صدای غمناکی آغاز کرد....\r\nزنی زیبا و خوش روی داشتم و از جان و دل عاشق ش بودم، از بد روزگان مرضی لاعلاج گریبانش را گرفت، و من به هرجا که فکر کنی بابت علاج و درمانش سفر کردم، به هر ده کوره ای که نور امیدی بود بار سفر می بستیم، این طبیب و آن طبیت، این دعا نویس و آن دعا نویس آخر سر طبیبی حاذق به من گفتم که این زن بیش از یک ماه زنده نخواهد ماند، او را به ولایت خود ببر و بگذر در آرامش ...\r\n\r\nیک قطره اشک از گوشه چشم مرد بر گونه های سیاه چرده ش سرازیر شد و اینچنین ادامه داد..\r\n\r\nهمسرم را به خانه آوردم و در غم از دست دادن ش روز و شب زاری و تیمار داری می کردم و سعی می کردم بهترین لحظات را در آخرین روزهای زندگی برایش فراهم کنم. \r\nیکی از چیزهای که زنم را اذیت می کرد فکر این موضوع بود که من پس از او با زن دیگری ازدواج خواهم کرد و او را به فراموشی خواهم سپرد و از طرفی چون هیچ زنی جزء همسرم برای من قابل تعریف نبود و زن م نیز در شرف مرگ بود، روزی برای آرامش او مردانگی ام را از بین بردم!\r\n\r\nیک ماه سر آمد اما زن من نمرد، روز به روز که می گذشت او سر زنده تر می شد و پس  از چند ماه بیماری به کل از درون او رخت بست.\r\nپس از آن زنم به شدت بد خلق شده است علت را جویا شدم و متوجه شدم که او از نداشتن مردانگی در من دلخور است کار به جای کشید که گفت می خواهد از من طلاق گرفته و شوهری دیگر برگزیند!!؟؟\r\nمن به شدت از این درخواست او ناراحت شده بودم اما فکر اینکه زن م را نداشته باشم تمام درونم را می آزرد، به او پیشنهادی دادم و گفتم اگر این مشکل را حل کنم تو با من خواهی ماند؟ و او نیز قبول کرد.\r\n\r\nاکنون هر هفته به ولایت های اطرف می روم و پسر جوانی را برمی گزینم و برای زنم می آورم، این داریه و تنبک هم از آن است که وقتی آنها مشغولنند صدای آنها را نشونم.\r\n"},{"id":1887,"category_id":2,"category_code":"s2","source_id":54,"title":"پاره آجر ","content":"روزی مردی ثروتمند در اتومبیل جدید و گران قیمت خود با سرعت فراوان از خیابان کم رفت و آمدی می گذشت .\r\nناگهان از بین دو اتومبیل پارک شده در کنار خیابان ، یک پسر بچه پاره آجری به سمت او پرتاب کرد . پاره آجر به اتومبیل او برخورد کرد .\r\nمرد پایش را روی ترمز گذاشت و سریع پیاده شد و دید که اتومبیلش صدمه زیادی دیده است . به طرف پسرک رفت تا او را به سختی تنبیه کند ....\r\nپسرک گریان ، با تلاش فراوان بالاخره توانست توجه مرد را به سمت پیاده رو ، جایی که برادر فلجش از روی صندلی چرخدار به زمین افتاده بود جلب کند .\r\nپسرک گفت :\r\n\" اینجا خیابان خلوتی است و به ندرت کسی از آن عبور می کند . هر چه منتظر ایستادم و از رانندگان کمک خواستم ، کسی توجه نکرد . برادر بزرگم از روی صندلی چرخدارش به زمین افتاده و من زور کافی برای بلند کردنش ندارم . \"\r\n\" برای اینکه شما را متوقف کتم ، ناچار شدم از این پاره آجر استفاده کنم \"\r\n\r\nمرد متاثر شد و به فکر فرو رفت ... برادر پسرک را روی صندلی اش نشاند ، سوار ماشینش شد و به راه افتاد ....\r\nدر زندگی چنان با سرعت حرکت نکنید که دیگران مجبور شوند برای جلب توجه شما ، پاره آجر به طرفتان پرتاب کنند !\r\nخدا در روح ما زمزمه می کند و با قلب ما حرف می زند ....\r\nاما بعضی اوقات زمانی که ما وقت نداریم گوش کنیم، او مجبور می شود پاره آجری به سمت ما پرتاب کند.\r\n"},{"id":1888,"category_id":2,"category_code":"s2","source_id":55,"title":"کشتن خلق","content":"شخصی از روی خشم مادر خود را کشت. به قاتل گفتند که تو به سبب سرشت بد خویش حتی از حق مادری یاد نکردی!؟ بگو که چرا مادر خود را کشتی؟\r\nگفت:او مرتکب کاری شده بود که برای وی ننگ بود او را کشتم تا خاک عیب او را بپوشاند.\r\nگفتند:آن مرد را میکشتی.\r\nگفت :در این صورت باید هرروز یک نفر را میکشتم. من او را کشتم و خود را از کشتن خلق رهاندم. گلوی او را ببرم بهتر است از این که گلوی خلق را ببرم\r\nدر نتیجه آن مادر بدخو نفس توست که فسادش همه جا را فرا گرفته. هوشیار باش و نفس خود را بکش. زیرا که به خاطر او هر لحظه در صدد کشتن کسی بر میآیی.\r\nنقس توست آن مادر بد خاصیت که فساد اوست در هر ناحیت\r\nهین بکش اورا که بهر آن دنی هر دمی قصد عزیزی می کنی\r\n\r\nاگر نفس را بکشی از عذرخواستن رها میشوی و دیگر در دنیا دشمنی نخواهی یافت. در این جا مولانا اشارهای دارد که بعضیها میگویند پس چرا پیامبران که نفس خود را کشتهاند دشمن و حسود دارند.\r\nای جوینده راستی گوش کن تا جواب اشکال تردید آمیزت را بشنوی. منکران با خودشان دشمنی میکردند و آنان به خودشان ضربه میزدند. دشمن کسی است که قصد جان آدم را بکند، آن نیست که خود در حال جان کندن باشد. مانند آن غلامی که برای انتقام از خواجهی خود، خودکشی میکند.و خود را از بام خانه سرنگون میکند تا به اربات خود ضرر بزند !؟!\r\nلذا اگر کودک به مربی خود، بیمار بر طبیب خود، رختشوی بر خورشید و یا ماهی بر آب خشمگین شود، تو خود دقت کن که کدام زیان میبینند و سرانجام کدامیک بدبخت میشوند ؟\r\nگر شود بیمار دشمن با طبیب ور کند کودک عداوت با ادیب\r\nدر حقیقت رهزن راه خودند راه عقل و جان خودرا خود زدند\r\n\r\nگازری گر خشم گیرد زآفتاب ماهیی گر خشم می گیرد ز آب\r\nتو یکی بنگر کرا دارد زیان عاقبت که بود سیاه اختر از آن\r\nاگر خدا تو را زشت رو آفریده باشید، هوشیار باش که زشت خو نباشی.\r\nاگر کفشت پاره شد به سنگلاخ مرو.\r\nاگر دو عیب داری سعی مکن آن را چهار عیب کنی.\r\nبه نظر من در این دنیای تلاش و تجربه هیچ چیزی شایسته تر از اخلاق نیکو نیست. پس قبل از آن که با دیگران مبارزه کنیم با خود به تفاهم برسیم.\r\nمن ندیدم در جهان جست و جو هیچ اهلیت به از خوی نکو\r\n"},{"id":1889,"category_id":2,"category_code":"s2","source_id":56,"title":"شکارچی....","content":"مردی از کنار جنگلی رد می شد ، شیری را دید که برای شغالی را خط ونشان می کشد . شغال به خانه رفت و در را بست ولی شیر همچنان به حرکات رزمی اش ادامه داد و شغال را به جدال فرا خواند . مرد سرگرم تماشای آنان بود که کلاغی از بالای درخت از او پرسید چه چیز تو را این چنین متعجب کرده است؟\r\nمرد گفت: به خط و نشانهای شیر فکر می کنم ،شغال هم بی توجه به خانه اش رفته بیرون نمی آید!\r\nکلاغ گفت ای نادان آنها تو را سرگرم کرده اند تا روباه بتواند غذایت رابخورد !\r\nمرد دید غذایش از دستش رفته از کلاغه پرسید روباه غذایم را برد شیر و شغال را چه حاصل؟\r\nکلاغه چنین توضیح داد : روباه گرسنه بود توان حمله نداشت ، غذایت را خورد و نیرو گرفت، شیرهم بدنش کوفته بود خودش را گرم کرد تا هنگام حمله آماده باشد و شغال هم خسته بود رفت خانه تا نیرویی تازه کند تا آن زمان که جلوتر رفتی هرسه بتو حمله کنند و تو را بخورند!؟\r\nمردپرسید: از اطلاعاتی که به من دادی تو را چه حاصل؟\r\nکلاغ گفت: آنها کیسه زر تو را به من وعده داده بودند تا تو را سرگرم کنم.\r\n"},{"id":1890,"category_id":2,"category_code":"s2","source_id":57,"title":"در سختی چه کسی زنده می ماند؟","content":"دو نفر از اهالى خراسان ، با هم به سفر رفتند، يكى از آنها ضعيف بود و هر دو شب ، يكبار غذا مى خورد، ديگرى قوى بود و روزى سه بار غذا مى خورد، از قضاى روزگار در كنار شهرى به اتهام اينكه جاسوسى دشمن هستند، دستگير شدند، و هر دو را در خانه اى زندانى نمودند، و در آن زندان را با گل گرفتند و بستند، بعد از دو هفته معلوم شد كه جاسوس ‍ نيستند و بى گناهند. در را گشودند، ديدند قوى مرده ، ولى ضعيف زنده مانده است ، مردم در اين مورد تعجب نمودند كه چرا قوى مرده است ؟!\r\nطبيب فرزانه اى به آنها گفت : اگر ضعيف مى مرد باعث تعجب بود، زيرا مرگ قوى از اين رو بود كه پرخور بود، و در اين چهارده روز، طاقت بى غذايى نياورد و مرد، ولى آن ضعيف كم خور بود، مطابق عادت خود صبر كرد و سلامت ماند.\r\n"},{"id":1891,"category_id":2,"category_code":"s2","source_id":58,"title":"برنده","content":"کنیث در دوره ی اول دبیرستان درس می خواند و از اینکه قرار بود در یکی از مسابقات انتخابی المپیک شرکت جوید، شور و حال و هیجان خاصی داشت. پدرو مادر او در روز مسابقه گوش به زنگ و امیدوار در جایگاه تماشاچیان نشسته بودند که کنیث بهتر از دیگران دوید و نخستین مسابقه را برد. او از دریافت جایزه و از ابراز احساسات جماعت حاضر در ورزشگاه سر از پا نمی شناخت.\r\nدومین مسابقه آغاز شد و کنیث شروع به دویدن کرد. کمی مانده به خط پایان، یعنی درست لحظه ای که کنیث می توانست برای بار دوم برنده شود، از حرکت باز ایستاد و از مسیر مسابقه خارج شد. پدرو مادرش به نرمی از او پرسیدند: « چرا این کار را کردی، کنیث؟ اگر ادامه می دادی دومین مسابقه را هم برده بودی.»\r\nکنیث معصومانه پاسخ داد: « درسته، مادر، اما من یکی از جایزه ها را برده بودم، در صورتی که بیلی هنوز صاحب جایزه ای نشده بود.»\r\n"},{"id":1892,"category_id":2,"category_code":"s2","source_id":59,"title":"پای بزرگ، قلبی بزرگتر","content":"هوا نا به هنگام گرم بود . به همین خاطر توقف جلوی مغازه بستنی فروشی امری کاملا طبیعی به نظر می رسید. دختر کوچولویی که پولش را محکم در دست گرفته بود ،وارد بستنی فروشی شد .بستنی فروش قبل از آن که او کلمه ای بر زبان جاری نماید با اوقات تلخی به او گفت از مغازه خارج شده و تابلوی روی در را بخواند و تا وقتی کفش پایش نکرده وارد مغازه نشود. دخترک به آرامی از مغازه بیرون رفت ،و مرد درشت هیکلی به دنبال او از مغازه خارج شد.دختر کوچولو مقابل مغازه ایستاد و تابلوی روی در را خواند :ورود پابرهنه ها ممنوع!دخترک در حالی که اشک چشمانش بر روی گونه هایش می غلتید راهش را گرفت تا برود .\r\nدر این لحظه مرد درشت هیکل او را صدا زد . او کنار پیاده رو نشست ، کفش های بزرگ نمره 44 خود را در آورد و در مقابل دخترکوچولو جفت کرد و گفت : بیا بکن تو پاهات. درسته که با این کفش ها نمی تونی خوب راه بروی ، امااگر بتونی یه جوری آنها را با پاهات بکشی، می تونی بستنی ات را بخری.\r\nمرد دختر کوچولو را بلند کرد و پاهای او را توی کفش ها میزان نمود و گفت: عجله نکن ، بس که این کفش رو با پاهام این ور و اون ور کشیده ام خسته ام. تا بری و برگردی من اینجا راحت می شینم و بستنی ام را می خورم. چشمان براق دختر کوچولو هنگام هجوم او به سمت پیشخوان و خریدن بستنی صحنه ای نبود که از ذهن زدوده شود. بله، او مرد درشت هیکلی بود، شکم گنده ای داشت ، کفش های بزرگی داشت ،\r\nاما مهم تر از همه ، قلب بزرگی داشت.\r\n"},{"id":1893,"category_id":2,"category_code":"s2","source_id":60,"title":"بدهی آسان","content":"در شهر «واسط» (بین كوفه و بصره) چند نفر پارسا از بقالى نسیه برده بودند و مبلغى بدهكار او بودند. بقال پى در پى از آنها مى خواست كه بدهكارى خود را بپردازند، و با آنها برخورد خشن مى كرد و با سخنان درشت ، حق خود را مطالبه مى نمود، آنها از خشونتهاى بقال ناراحت بودند، ولى بر اثر تهیدستى چاره اى جز صبر و تحمل نداشتند.\r\nدر این میان ، صاحبدلى گفت : «وعده دادن نفس به غذا آسانتر از وعده دادن پول به بقال است ».\r\n(یعنى به شكم خود در مورد غذا وعده امروز و فردا بده ، و خود را بدهكار بقال ننما، كه وعده به شكم آسان است و وعده به بقال سخت مى باشد.) \r\n"},{"id":1894,"category_id":2,"category_code":"s2","source_id":61,"title":"موفقیت و سقراط","content":"مرد جوانی از سقراط رمز موفقیت را پرسید که چیست. سقراط به مرد جوان گفت که صبح روز بعد به نزدیکی رودخانه بیاید. هر دو حاضر شدند. سقراط از مرد جوان خواست که همراه او وارد رودخانه شود. وقتی وارد رودخانه شدند و آب به زیر گردنشان رسید سقراط با زیر آب بردن سر مرد جوان، او را شگفت زده کرد.\r\nمرد تلاش می کرد تا خود را رها کند اما سقراط قوی تر بود و او را تا زمانی که رنگ صورتش کبود شد محکم نگاه داشت. سقراط سر مرد جوان را از آب خارج کرد و اولین کاری که مرد جوان انجام داد کشیدن یک نفس عمیق بود.\r\nسقراط از او پرسید، \" در آن وضعیت تنها چیزی که می خواستی چه بود؟\" پسر جواب داد: \"هوا\"\r\nسقراط گفت:\" این راز موفقیت است! اگر همانطور که هوا را می خواستی در جستجوی موفقیت هم باشی، بدستش خواهی آورد\" رمز دیگری وجود ندارد.\r\n"},{"id":1895,"category_id":2,"category_code":"s2","source_id":62,"title":"فرمانروایی دیوجانس و اسارت اسکندر","content":"نوشته اند: روزى اسكندر مقدونى، نزد ديوجانس آمد تا با او گفت و گو كند. ديوجانس كه مردى خلوت گزيده و عارف مسلك بود، اسكندر را آن چنان كه او توقع داشت، احترام نكرد و وقعى ننهاد . اسكندر از اين برخورد و مواجهه ديوجانس ، برآشفت و گفت :اين چه رفتارى است كه تو با ما دارى؟\r\nآيا گمان كرده اى كه از ما بى نيازى ؟\r\nآرى ، بى نيازم .\r\nتو را بى نياز نمى بينم .بر خاك نشسته اى و سقف خانه ات ، آسمان است . از من چيزى بخواه تا تو را بدهم .\r\nاى شاه !من دو بنده حلقه به گوش دارم كه آن دو، تو را اميرند . تو بنده بندگان منى .\r\nآن بندگان تو كه بر من اميرند، چه كسانى اند؟\r\nخشم و شهوت. من آن دو را رام خود كرده ام ؛ حال آن كه آن دو بر تو اميرند و تو را به هر سو كه بخواهند مى كشند.\r\nبرو آن جا كه تو را فرمان مى برند؛، نه اين جا كه فرمانبرى زبون و خوارى. \r\n"},{"id":1896,"category_id":2,"category_code":"s2","source_id":63,"title":"دعا با زبان پاك","content":"در بنى اسرائيل مردى بود اولادى نداشت . خيلى مايل بود خداوند به او فرزندى عنايت كند. سى سال دعا كرد به نتيجه نرسيد وقتى كه ديد خداوند دعاى او را مستجاب نمى كند، گفت : خدايا! دور از منى ، دعايم را نمى شنوى ؟ يا نزديك به منى ولى دعايم را مستجاب نمى كنى ؟\r\nكسى به خوابش آمد و به او گفت :\r\nسى سال خدا را با زبان بد و هرزه قلب سركش و ناپاك و نيت نادرست خواندى دعايت مستجاب نشد، اينك زبانت را از گناه بازدار و قلبت را از آلودگى پاك كن ! با نيت راست دعا كن ! تا دعايت مستجاب گردد.\r\nمرد از خواب بيدار شد و به دستورات او عمل كرد با زبان و دل پاك خدا را خواند، خداوند هم دعايش را مستجاب نمود، خواسته او برآورده شد و خداوند به او فرزندى عنايت كرد.\r\n"},{"id":1897,"category_id":2,"category_code":"s2","source_id":64,"title":"گنجشک ها","content":"\r\nگنجشکی با عجله و با تمام توان به آتش نزدیک می‌شد و برمی‌گشت‌! \r\nپرسیدند : چه می‌کنی؟\r\nپاسخ داد: در این نزدیکی چشمه آبی هست و من مرتب نوک خود را پر از آب می‌کنم و آن را روی آتش می‌ریزم…\r\nگفتند: حجم آتش در مقایسه با آبی که تو می‌آوری بسیار زیاد است و این آب فایده‌ای ندارد.\r\nگفت: شاید نتوانم آتش را خاموش کنم، اما آن هنگام که خدا می‌پرسد: زمانی که دوستت در آتش می‌سوخت تو چه کردی؟\r\nپاسخ می‌دهم: هر آنچه از من بر می‌آمد!!\r\n"},{"id":1898,"category_id":2,"category_code":"s2","source_id":65,"title":"مصاحبه شغلی","content":"در پایان مصاحبه شغلی برای استخدام در شرکتی، مدیر منابع انسانی شرکت از مهندس جوان صفر کیلومتر ام آی تی پرسید: «و برای شروع کار، حقوق مورد انتظار شما چیست؟»\r\nمهندس گفت: «حدود ۷۵۰۰۰ دلار در سال، بسته به اینکه چه مزایایی داده شود.»\r\nمدیر منابع انسانی گفت: «خب، نظر شما درباره ۵ هفته تعطیلی، ۱۴ روز تعطیلی با حقوق، بیمه کامل درمانی و حقوق بازنشستگی ویژه و خودروی شیک و مدل بالای در اختیار چیست؟»\r\nمهندس جوان از جا پرید و با تعجب پرسید: «شوخی می کنید؟»\r\nمدیر منابع انسانی گفت: «بله، اما اول تو شروع کردی.»\r\n"},{"id":1899,"category_id":2,"category_code":"s2","source_id":66,"title":"زيبايي انسان درچيست؟","content":"روزي شاگردان نزد حکيم رفتند و پرسيدند: «استاد زيبايي انسان درچيست؟»\r\nحکيم 2 کاسه کنار شاگردان گذاشت وگفت: «به اين 2 کاسه نگاه کنيد اولي ازطلا درست شده است ودرونش سم است و دومي کاسه اي گليست و درونش آب گوارا است، شما کدام راميخوريد؟»\r\nشاگردان جواب دادند: «کاسه گلي را.»\r\nحکيم گفت: « آدمي هم همچون اين کاسه است. آنچه که آدمي را زيبا ميکند درونش واخلاقش است. بايد سيرتمان رازيباکنيم نه صورتمان را.»\r\n"},{"id":1900,"category_id":2,"category_code":"s2","source_id":67,"title":"کوزه عسل","content":"مرد خیاطی کوزه ای عسل در دکانش داشت.یک روز می خواست دنبال کاری برود. به شاگردش گفت: این کوزه پر از زهر است! مواظب باش به آن دست نزنی! شاگرد که می دانست استادش دروغ می گوید حرفی نزد و ...\r\nاستادش رفت. شاگرد هم پیراهن یک مشتری را بر داشت و به دکان نانوایی رفت و آن را به مرد نانوا داد و دو نان داغ و تازه گرفت و بعد به دکان برگشت و تمام عسل را با نان خورد و کف دکان دراز کشید. خیاط ساعتی نگذشته بود که بازگشت و با حیرت از شاگردش پرسید: چرا خوابیده ای؟\r\nشاگرد ناله کنان پاسخ داد: تو که رفتی من سرگرم کار بودم، دزدی آمد و یکی از پیراهن ها را دزدید و رفت. وقتی من متوجه شدم،از ترس تو، زهر توی کوزه را خوردم و دراز کشیدم تا بمیرم و از کتک خوردن و تنبیه آسوده شوم!\r\n"},{"id":1901,"category_id":2,"category_code":"s2","source_id":68,"title":"معلم، سیب و توت فرنگی","content":"یک خانم معلم ریاضی به یک پسر هفت ساله ریاضی یاد می‌داد. یک روز ازش پرسید: اگر من بهت یک سیب و یک سیب و یکی بیشتر سیب بدهم تو چند تا سیب خواهی داشت؟\r\nپسر بعد از چند ثانیه با اطمینان گفت: ۴ تا! معلم نگران شده انتظار یک جواب صحیح آسان رو داشت.\r\nاو نا امید شده بود. او فکر کرد : شاید بچه خوب گوش نکرده است ... تکرار کرد: خوب گوش کن، خیلی ساده است, اگر به دقت گوش کنی می‌تونی جواب صحیح بدهی.\r\nاگر من به تو یک سیب و یک سیب دیگه و یکی بیشتر سیب بدهم تو چند تا سیب خواهی داشت؟\r\nپسر که در قیافه معلمش نومیدی می‌دید دوباره شروع کرد به حساب کردن با انگشتانش. تلاش او برای یافتن جواب صحیح نبود تلاشش برای یافتن جوابی بود که معلمش را خوشحال کند. برای همین با تامل پاسخ داد: 4 تا !!! نومیدی در صورت معلم باقی ماند و به یادش اومد که پسر توت فرنگی رو دوست دارد. او فکر کرد شاید پسرک سیب رو دوست ندارد و برای همین نمی‌تونه تمرکز داشته باشه. در این موقع او با هیجان فوق العاده و چشم‌های برق‌زده پرسید: اگر من به تو یک توت فرنگی و یکی دیگه و یکی بیشتر توت فرنگی بدهم تو چند تا توت فرنگی خواهی داشت؟\r\nمعلم خوشحال بنظر می‌رسید.\r\nپسرک با انگشتانش دوباره حساب کرد. و سپس با تامل جواب داد: 3تا! \r\nحالا خانم معلم تبسم پیروزمندانه ای داشت. برای نزدیک شدن به موفقیتش او خواست به خودش تبریک بگه ولی یه چیزی مونده بود او دوباره از پسر پرسید: اگر من به تو یک سیب و یک سیب دیگه و یکی دیگه بیشتر سیب بدهم تو چند تا سیب خواهی داشت؟ پسرک فوری جواب داد : 4 تا !!!\r\nخانم معلم مبهوت شده بود و با صدای گرفته و خشمگین پرسید: چطور؟ آخه چطور؟! پسرک با صدای پایین و با تامل پاسخ داد : خانوم اجازه ؟! برای اینکه من قبلا یک سیب تو کیفم داشتم !!!\r\n\r\nنتیجه اخلاقی: قضاوت عجولانه نداشته باشیم. \r\n"},{"id":1902,"category_id":2,"category_code":"s2","source_id":69,"title":"قناعت","content":"حاتم طایی را گفتند از تو بزرگ همت تر در جهان دیده‌ای یا شنیده‌ای گفت بلی روزی چهل شتر قربان کرده بودم امرای عرب را پس به گوشه صحرایی به حاجتی برون رفته بودم ،خارکنی را دیدم پشته فراهم آورده. گفتمش به مهمانی حاتم چرا نروی که خلقی بر سماط او گرد آمده‌اند؟ گفت:\r\nهر که نان از عمل خویش خورد*****************منت حاتم طائى نبرد\r\nمن او را به همت و جوانمردی از خود برتر دیدم.\r\n\r\nنتیجه اخلاقی: قال امیر المومنین علی علیه السلام: «القناعة مال لا ينفد»\r\nترجمه: قناعت ثروتی است پایان ناپذیر.\r\n"},{"id":1903,"category_id":2,"category_code":"s2","source_id":70,"title":"اختراع تازه","content":"\r\nمنلیک شاه حبشه با ابهت بود و ضمنا منلیک نو گرا بود.\r\nشنید در نیو یورک محکومین را به روشی جدید اعدام می کنند . دستور داد ازین اختراع تازه -صندلی الکتریکی- سه تا خریدند. محموله که رسید چیزی به خاطر منلیک آمد . در کشور او ، حبشه پدیده ای به نام برق وجود نداشت.\r\nمنلیک مقتصد بود یکی از سه صندلی الکتریکی را تبدیل کرد به تخت شاهی حبشه.\r\nنتیجه اخلاقی: حتی اگر پادشاه هم باشی, تقلید کورکورانه از غرب باعث می شه روی صندلی الکتریکی بشینی.\r\n"},{"id":1904,"category_id":2,"category_code":"s2","source_id":71,"title":"پاسخ جالب انیشتین به خواستگارش","content":"می گویند مریلین مونرو یک وقتی نامه ای نوشت به البرت اینشتین که فکرش را بکن که اگر من و تو ازدواج کنیم بچه ها یمان با زیبایی من و هوش و نبوغ تو چه محشری می شوند!\r\nاقای اینشتین هم نوشت ممنون از این همه لطف و دست و دلبازی خانم. واقعا هم که چه غوغایی می شود! ولی این یک روی سکه است. فکرش را بکنید که اگر قضیه بر عکس شود چه رسوایی بزرگی بر پا می شود! \r\n"},{"id":1905,"category_id":2,"category_code":"s2","source_id":72,"title":"شاخص اقتصادی از دیدگاه شاه عباس","content":"مي گويند شاه عباس از وزير خود پرسيد: امسال اوضاع اقتصادي کشور چگونه است؟\r\nوزير گفت: الحمد لله به گونه اي است که تمام پينه دوزان توانستند به زيارت کعبه روند!\r\nشاه عباس گفت: نادان! اگر اوضاع مالي مردم خوب بود مي بايست کفاشان به مکه مي رفتند نه پينه ‌دوزان، چون مردم نمي توانند کفش بخرند ناچار به تعميرش مي پردازند، بررسي کن و علت آن را پيدا نما تا کار را اصلاح کنيم.\r\n"},{"id":1906,"category_id":2,"category_code":"s2","source_id":73,"title":"مدیریت بدون میز","content":"خاطره ویژه از شهید محمد بروجردی:\r\n\r\nفرمانده سپاه منطقه ۸ و جانشین قرار گاه حمزه بود. نشد یکبار در «قرارگاه حمزه»، او را پشت میزش ببینم. اگر هم کاری با او داشتم یا می آمد بیرون از اتاق و به کارم رسیدگی می کرد یا اگر هم داخل اتاقش می رفتیم، از پشت میز کارش بلند می شد و می آمد این طرف میز و خیلی راحت کنارم می نشست و صحبت می کردیم.\r\nتعجب کرده بودم که این چه جور مدیری است که هیچ وقت پشت میزش نیست. با خودم گفتم که حتماً با من اینطوره. خلاصه احترام ما را نگه می دارد. چند وقتی به کارهایش دقت کردم تا جواب سوالم را پیدا کنم و بفهمم که فقط با من چنین کاری می کند یا با بقیه مراجعین هم این طوریست. متوجه شدم آقای بروجردی با همه همین شکلی تا می کند، یعنی اصلاً پشت میز به کارهایشان رسیدگی نمی کند.\r\nبالاخره یک روز دلم را زدم به دریا و با خجالت پرسیدم: حاج آقا! چرا شما با ارباب رجوع پشت میزت برخورد نمی کنی؟ با خنده گفت: «برادرمن! میز ریاست یک حال و هوای خاصی دارد که آدم را می گیرد. پشت آن میز من فرمانده و رئیسم و مخاطبم، ارباب رجوع است. من می آیم این طرف و کنار مردم می نشینم تا توی آن حال و هوای خاص با آنها برخورد نکنم. این طرف میز من برادر مردم هستم و مثل یک برادر به مشکلاتشان رسیدگی می کنم.»\r\nچیزی نداشتم که بگویم. فقط سرم را انداختم پایین.\r\n"},{"id":1907,"category_id":2,"category_code":"s2","source_id":74,"title":"راهی آسان برای ورود به بهشت","content":"شخصى محضر پيامبر اسلام صلى الله عليه و آله و سلم مشرف شد. حضرت به او فرمودند: آيا مى خواهى تو را به كارى راهنمايى كنم كه به وسيله آن داخل بهشت شوى؟\r\nمرد پاسخ داد: مى خواهم يا رسول الله !\r\nحضرت فرمودند: از آن چه خداوند به تو داده است انفاق كن و به ديگران بده!\r\nمرد: اگر خود نيازمندتر از ديگران باشم، چه كنم؟\r\nفرمودند: مظلوم را يارى كن!\r\nمرد: اگر خودم ناتوان تر از او باشم، چه كنم؟\r\nفرمودند: نادانى را راهنمايى كن!\r\nمرد: اگر خودم نادان تر از او باشم ، چه كنم؟\r\nفرمودند: در اين صورت زبانت را جز در موارد خير نگهدار!\r\nسپس رسول خدا صلی الله علیه و آله و سلم فرمودند:\r\nآيا خوشحال نمى شوى كه يكى از اين صفات را داشته باشى و به بهشت داخلت نمايند؟\r\n"},{"id":1908,"category_id":2,"category_code":"s2","source_id":75,"title":"قرض","content":"در روزگاران دور شخصي عمه مهرباني داشت. روزي از عمه خود پول قرض مي خواهد و عمه با خوش رويي به او مي گويد: برادرزاده عزيزم! برو گوشه قالی را بلند كن. زير آن چند سكه است، بردار و كار خود را راه بينداز. جوان هم خوشحال و خندان سكه ها را برداشته و به راه خود مي رود.\r\nبار ديگر جوان در تنگناي مالي گرفتار مي شود و به ياد عمه خود مي افتد و به خانه او رفته و مجدداً طلب قرض مي كند. عمه با همان روي خوش و لحن مهربان به او مي گويد: عزيزم ! برو همان گوشه قالی را بلند كن و سكه ها را بردار.\r\nجوان با خوشحالی به سوی قالی می رود، ولي وقتي آن را بلند مي كند، سكه اي نمي یابد! با تعجب مي گويد ، عمه جان اينجا كه سكه اي نيست؟\r\nو عمه او در پاسخ مي گويد: عزيزم ! سكه ها را سرجایش گذاشتی كه حالا مي خواهي برداري؟!\r\n"},{"id":1909,"category_id":2,"category_code":"s2","source_id":76,"title":"گوهرشاد خانم و جوان عاشق","content":"گوهرشاد خانم(همسر شاهرخ میرزا و عروس امیر تیمور گورکانی) سازنده ی مسجد معروف گوهرشاد مشهد، پیش از ساختن مسجد به دست اندرکاران گفت: از محل آوردن مصالح ساختمانی تا مسجد برای حیوانات باربر ظرفهای آب و علف بگذارید، مبادا حیوانی در حال گرسنگی و تشنگی بار بکشد. از زدن حیوانات پرهیز کنید، ساعات کار باید معین باشد و مزد مطابق زحمت داده شود و...\r\n\r\nگوهرشاد خانم، بیشتر وقتها خود جهت هدایت و سرکشی حاضر می شد و دستورات لازم را می دارد. روزی یکی از کارگران به طور ناگهانی چشمانش به صورت او افتاد و در اثر همین نگاه، آتش عشق در وجودش شعله ور گشته و عاشق دلباخته ی او شد؛ اما در این باره نمی توانست چیزی بگوید تا اینکه غم و غصه ی فراوان او را مریض کرد. به خانم گزارش دادند که یکی از کارگران که با مادرش زندگی می کرد مریض شده است. بعد از شنیدن این ماجرا خانم به عیادتش رفت و علّت را جویا شد. مادر کارگر جوان گفت: او عاشق شما شده است.\r\nخانم با اینکه عروس شاهزاده بود، اما هیچ ناراحت نشد! به مادر جوان گفت: باشد، وقتی من از همسرم جدا شدم با او ازدواج می کنم ولی به شرط اینکه مهریه من را قبل از ازدواج بپردازد و آن این است که چهل شبانه روز در محراب این مسجد نیمه کاره عبادت کند.\r\nجوان پذیرفت، چند روز از پی عشق او عبادت کرد؛ ولی با توجّه خاص امام رضا (علیه السلام) حالش تغییر یافت ( و از آن پس بخاطر خدا عبادت کرد).\r\n\r\nپس از چهل روز, گوهرشاد خانم از حالش جویا شد، جوان به فرستاده ی خانم گفت: به خاطر لذّتی که در اطاعت و بندگی خدا یافتم، از لذت نفس شهوانی پرهیز کرده ام.(بخاطر اینکه لذت عبادت را فهمیده ام, دیگر عاشق خدا شده ام.) \r\n"},{"id":1910,"category_id":2,"category_code":"s2","source_id":77,"title":"فقط دردش کم باشه !","content":"رامبد کیف مدرسه را با عجله گوشه ای پرتاب کرد و بی درنگ به سمت قلک کوچکی که روی تاقچه بود ، رفت .\r\nهمه خستگی روزش را بر سر قلک بیچاره خالی کرد . پولهای خرد را که هنوز با تکه های قلک قاطی بود در جیبش ریخت و با سرعت از خانه خارج شد .\r\nوارد مغازه شد . با ذوق گفت : ببخشید آقا ! یه کمربند می خواستم . آخه ، آخه فردا تولد پدرم هست ... .\r\nمغازه دار میگه : به به . مبارک باشه . چه جوری باشه ؟ چرم یا معمولی ، مشکی یا قهوه ای ، ...\r\nپسرک چند لحظه به فکر فرو رفت .\r\n- فرقی نداره . فقط ... ، فقط دردش کم باشه !\r\n"},{"id":1911,"category_id":2,"category_code":"s2","source_id":78,"title":"انتقام خانم ها ","content":"\r\nزن :میشه تو کار باغچه کمکم کنی؟ \r\nمرد :تو فکر کردی من باغبونم ؟!\r\nزن :میشه توی تعمیر دستگیره در کمکم کنی ؟\r\nمرد :تو فکر کردی من نجارم ؟\r\nبعد از ظهر مرد از سر کار برگشته و می بیند همه چیز درست شده است .........!!!!!!!\r\nمرد:کی دستگیره رو درست و باغچه رو رو براه کرد ؟\r\nزن:مرد همسایه و در ازاش ازم خواست یا یک همبرگر به او بدهم یا یک لب !\r\nمرد :حتما تو به او همبرگر دادی ؟\r\nزن :تو فکر کردی من گارسون رستورانم ؟!!\r\n"},{"id":1912,"category_id":2,"category_code":"s2","source_id":79,"title":"حرکت ","content":"شبی از شبها، شاگردی در حال عبادت و تضرع و گریه و زاری بود.\r\nدر همین حال مدتی گذشت، تا آنکه استاد خود را، بالای سرش دید، که با تعجب و حیرت؛ او را، نظاره می کند !\r\nاستاد پرسید : برای چه این همه ابراز ناراحتی و گریه و زاری می کنی؟\r\nشاگرد گفت : برای طلب بخشش و گذشت خداوند از گناهانم، و برخورداری از لطف خداوند!\r\nاستاد گفت : سوالی می پرسم ، پاسخ ده؟\r\nشاگرد گفت : با کمال میل؛ استاد.\r\nاستاد گفت : اگر مرغی را، پروش دهی ، هدف تو از پرورشِ آن چیست؟\r\nشاگرد گفت: خوب معلوم است استاد؛ برای آنکه از گوشت و تخم مرغ آن بهره مند شوم .\r\nاستاد گفت: اگر آن مرغ، برایت گریه و زاری کند، آیا از تصمیم خود، منصرف خواهی شد؟\r\nشاگردگفت: خوب راستش نه...!نمی توانم هدف دیگری از پرورش آن مرغ، برای خود، تصور کنم!\r\nاستاد گفت: حال اگر این مرغ ، برایت تخم طلا دهد چه؟ آیا باز هم او را، خواهی کشت، تا از آن بهره مند گردی؟!\r\nشاگرد گفت : نه هرگز استاد، مطمئنا آن تخمها، برایم مهمتر و با ارزش تر ، خواهند بود!\r\nاستاد گفت :\r\nپس تو نیز؛ برای خداوند، چنین باش!\r\nهمیشه تلاش کن، تا با ارزش تر از جسم ، گوشت ، پوست و استخوانت؛ گردی.\r\nتلاش کن تا آنقدر برای انسانها، هستی و کائنات خداوند، مفید و با ارزش شوی\r\nتا مقام و لیاقتِ توجه، لطف و رحمتِ او را، بدست آوری .\r\nخداوند از تو گریه و زاری نمی خواهد!\r\nاو، از تو حرکت، رشد، تعالی، و با ارزش شدن را می خواهد و می پذیرد،\r\nنه ابرازِ ناراحتی و گریه و زاری را.....!\r\n"},{"id":1913,"category_id":2,"category_code":"s2","source_id":80,"title":"لیوان آب و مشکلات!","content":"استادى در شروع کلاس درس، لیوانى پر از آب به دست گرفت. آن را بالا نگاه داشت که همه ببینند. بعد از شاگردان پرسید: به نظر شما وزن این لیوان چقدر است؟ شاگردان جواب دادند 50 گرم، 100 گرم، 150 گرم.\r\nاستاد گفت: من هم بدون وزن کردن، نمی دانم دقیقاً وزنش چقدر است. اما سوال من این است: اگر من این لیوان آب را چند دقیقه همین طور نگه دارم، چه اتفاقى خواهد افتاد.\r\nشاگردان گفتند: هیچ اتفاقى نمی افتد. استاد پرسید: خوب، اگر یک ساعت همین طور نگه دارم، چه اتفاقى می افتد؟ یکى از شاگردان گفت: دست تان کم کم درد می گیرد. حق با توست. حالا اگر یک روز تمام آن را نگه دارم چه؟\r\nشاگرد دیگرى جسارتاً گفت: دست تان بی حس می شود. عضلات به شدت تحت فشار قرار می گیرند و فلج می شوند. و مطمئناً کارتان به بیمارستان خواهد کشید و همه شاگردان خندیدند. استاد گفت: خیلى خوب است. ولى آیا در این مدت وزن لیوان تغییر کرده است؟ شاگردان جواب دادند: نه پس چه چیز باعث درد و فشار روى عضلات می شود؟ من چه باید بکنم؟\r\n\r\nشاگردان گیج شدند: یکى از آنها گفت: لیوان را زمین بگذارید. استاد گفت: دقیقاً . مشکلات زندگى هم مثل همین است. اگر آنها را چند دقیقه در ذهن تان نگه دارید، اشکالى ندارد. اگر مدت طولانی ترى به آنها فکر کنید، به درد خواهند آمد. اگر بیشتر از آن نگه شان دارید، فلج تان می کنند و دیگر قادر به انجام کارى نخواهید بود.\r\nفکر کردن به مشکلات زندگى مهم است. اما مهم تر آن است که در پایان هر روز و پیش از خواب، آنها را زمین بگذارید. به این ترتیب تحت فشار قرار نمی گیرید، هر روز صبح سرحال و قوى بیدار می شوید و قادر خواهید بود از عهده هر مسئله و چالشى که برایتان پیش می آید، برآیید! دوست من، یادت باشد که لیوان آب را همین امروز زمین بگذار. زندگى همین است!\r\n"},{"id":1914,"category_id":2,"category_code":"s2","source_id":81,"title":"جایگاه ادب","content":"روزی از یک ریاضیدان نظرش را در باره انسانیت پرسیدند ، در جواب گفت : \r\nاگر زن یا مرد دارای ادب و اخلاق باشند : نمره یک میدهیم 1\r\nاگر دارای زیبائی هم باشند پس یک صفر جلوی عدد یک میگذاریم : 10\r\nاگر پول هم داشته باشند 2 تا صفرجلوی عددیک میگذاریم : 100 \r\nاگردارای اصل ونسب هم باشند 3 تا صفرجلوی عدد یک میگذاریم : 1000\r\nولی اگر زمانی عدد 1 رفت ( اخلاق )؛ چیزی به جز صفر باقی نمیماند ، 000\r\nصفر هم به تنهائی هیچ است و با آن انسان هیچ ارزشی ندارد و این یادآور کلام حکیم ارد بزرگ است که می گوید : نخستین گام در راه پیروزی ، آموختن ادب است و نکو داشت دیگران .\r\n"},{"id":1915,"category_id":2,"category_code":"s2","source_id":82,"title":"مرد خسیس و طلاهایش","content":"در زمانهای دور مردی ژنده پوش بود ، این مرد طلاهای با ارزشی داشت اما بسیار خسیس بود و زندگی فقیرانه ایی برای خود درست کرده بود . طلاها را در کیسه ایی ریخته و هر شب سوراخی حفر می کرد و آنها را در آن پنهان می ساخت و این کار را هر شب تکرار می کرد . بلاخره در یکی از آن شب ها دزدی او را دید و پی به رازش برد و بعد از رفتن مرد خسیس سوراخ را باز کرد و طلا ها را دزدید و برد .\r\nآن شب مرد خسیس کابوس دزدیده شدن طلاهایش را دید صبح زود به طرف سوراخ که در کنار دیوار باغی کنده بود دوید و فهمید کابوس اش حقیقت داشته در کنار سوراخ نشست و گریست فریاد و فغان می کشید مسافری که از آنجا می گذشت علت نالانی مرد خسیس را پرسید و او ماجرا را گفت .\r\nمسافر گفت چرا طلاها را در داخل خانه ات پنهان نکردی تا هر وقت خواستی از آنها برای خرید استفاده کنی .\r\nمرد خسیس فریاد کشید و گفت : مردک من طلاهایم را خرج کنم . مگر آنها را از سر راه یافته ام ! کور خوانده اید من طلاهایم را خرج چیزهای بی ارزش نمی کنم .\r\nمسافر از تغییر حالت و حرفهای مرد خسیس شگفت زده شده بود . حکیم ارد بزرگ می گوید : خسیس خود را بیمار و بیچاره می سازد . \r\nمسافر سکه طلایی به مرد خسیس داد و گفت این را بگیر و سوراخ کندن ، را فراموش کن ، اما مرد خسیس تا روزی که زنده بود این کار را ادامه داد .\r\n"},{"id":1916,"category_id":2,"category_code":"s2","source_id":83,"title":"دو همسفر","content":"دویست سال پیش دو دوست همسفر شده بودند از کوهها و دشتها گذشتند تا به جنگلی پر درخت رسیدند کمی که در جنگل پیش رفتند صدای خرناس یک خرس قهوه ایی بزرگ را شنیدند صدا آنقدر نزدیک بود که آن دو همسفر از ترس گیج شده بودند یکی از دوستان از درختی بالا رفت بدون توجه به دوستش و اینکه چه عاقبتی در انتظار اوست دوست دیگر که دید تنهاست خود را بر زمین انداخت چون شنیده بود خرس ها با مردگان کاری ندارند . \r\nخرس که نزدیک شد سرش را نزدیک صورت مسافر بخت برگشته روی زمین کرد و چون او را بی حرکت دید پس از کمی خیره شدن به او راهش را گرفت و رفت . \r\nدوست بالای درخت پایین آمد و به دوستش که نشسته بود گفت آن خرس به تو چه گفت ، چون دیدم در نزدیکی گوشت دهانش را تکان می دهد . دوست دیگر گفت : خرس به من گفت : با دوستی همسفر شو که پشتیبان و یاورت باشد نه آنکه تا ترسید رهایت کند . به قول حکیم ارد بزرگ : «دوستی تنها برآیند نیاز ما نیست ، از خودگذشتگی نخستین پایه دوستی است» .\r\nآن دو همان جا از هم جدا شدند . دوست ترسویی که به بالای درخت رفته بود تا انتهای جنگل می دوید و از ترس زوزه می کشید .\r\n"},{"id":1917,"category_id":2,"category_code":"s2","source_id":84,"title":"گاهی باید نشنید!","content":"چند قورباغه از جنگلی عبور می کردند که ناگهان دو تا از آنها به داخل گودال عمیقی افتادند.\r\n\r\nبقیه قورباغه ها در کنار گودال جمع شدند و وقتی دیدند که گودال چقدر عمیق است به دو قورباغه دیگر گفتند: که دیگر چاره ای نیست شما به زودی خواهید مرد.\r\nدو قورباغه این حرفها را نشنیده گرفتند و با تمام توانشان کوشیدند که از گودال بیرون بپرند. اما قورباغه های دیگر مدام می گفتند: که دست از تلاش بردارند چون نمی توانند از گودال خارج شوند و خیلی زود خواهند مرد. بالاخره یکی از دو قورباغه تسلیم گفته های دیگر قورباغه ها شد و دست از تلاش برداشت. سر انجام به داخل گودال پرت شد و مرد.\r\nاما قورباغه دیگر با تمام توان برای بیرون آمدن از گودال تلاش می کرد. هر چه بقیه قورباغه ها فریاد میزدند که تلاش بیشتر فایده ای ندارد او مصمم تر می شد تا اینکه بالاخره از گودال خارج شد. وقتی بیرون آمد. بقیه قورباغه ها از او پرسیدند: مگر تو حرفهای ما را نمی شنیدی؟\r\nمعلوم شد که قورباغه ناشنواست. در واقع او در تمام مدت فکر می کرد که دیگران او را تشویق می کنند.\r\n"},{"id":1918,"category_id":2,"category_code":"s2","source_id":85,"title":"اُمیت و روژوه","content":"\"خسرو\" (اشک بیست و چهارم) فرمانروای ایران پس از آنکه توسط مجلس مهستان به پادشاهی دودمان اشکانیان ایران انتخاب شد .\r\nشنید عده ایی از رایزنان دربار به شاهزادگان \" اُمیت \" و \" روژوه \" ، فرزندان \"پاکور\" پادشاه پیشین ایرانزمین نهیب می زنند که پادشاهی از آن شماست و نه عمویتان خسرو!\r\nهر دو برادر با این سخنان سرافکنده و سرشکسته می شدند ، بیشتر روزها در انزوا و تنها بودند .\r\nپادشاه ایران ماجرای این دو را شنید از این روی امیت و روژوه را فراخواند و به آنها گفت : ریش سفیدان و خردمندان ایران مرا به فرمانروایی برگزیده اند اما باز هم برای من ارزش برادرم پاکور که اکنون در بین ما نیست و شما فرزندان او، بسیار مهمتر از این عنوان است . حال اگر هر دو شما به این نتیجه رسیده اید که بهتر است من در این موقعیت نباشم نامه ایی برای مجلس مهستان می نویسم و از آنها خواهم خواست این عنوان را به کس دیگری بدهند ، شاید انتخاب آنها شما باشید .\r\nفرمانروا ، پسران پادشاه پیشین را تنها گذاشت تا فکر کنند . وقتی برگشت دید در مقابل تخت پادشاهی دو تاج شاهزادگی پسران پاکور است و این بدان معنا بود که آنها به شرایط جدید تن داده و نظر مجلس مهستان را پذیرفته اند و دیگر سهمی از قدرت برای خود قائل نیستند .\r\nپاکور دستور داد تاج ها را به آنها برگردانند و از آنها خواست در کشورداری تنهایش نگذارند . و به آنها گفت قوی باشند و به سخن بدخواهان توجه نکنند و خود باشند یک اشکانی نجیب زاده ، اندیشمند کشورمان حکیم ارد بزرگ می گوید : آدم خودساخته ، بازیچه بادهایی که به هر سو روانند نمی گردد . و اینچنین بود که در طی 19 سال پادشاهی خسرو پادشاه اشکانی ، این دو برادر یاور او و افسرانی شجاع برای کشورمان ایران بودند. \r\nدو نام \"امیت\" و \"روژوه\" که ریشه از زبان پهلوی باستان دارند امروز \"امید\" و \"روزبه\" خوانده می شوند .\r\n"},{"id":1919,"category_id":2,"category_code":"s2","source_id":86,"title":"نقشه شکست خورده","content":"\r\nآن روز صبح یک دسته صورتحساب تازه رسیده بود . نامه شرکت بیمه ، از لغو شدن قرارداد هایشان خبر می داد. \r\nزن آه کشید و با نگرانی از جا برخاست تا شوهرش را در جریان بگذارد. آشپزخانه بوی گاز می داد.\r\nروی میز کار شوهرش نامه ای پیدار کرد .\r\n«...پول بیمه عمر من برای زندگی تو و بچه ها کافی خواهد بود...»\r\n"},{"id":1920,"category_id":2,"category_code":"s2","source_id":87,"title":"دوستان","content":"\r\nیکی از روزهای سال اول دبیرستان بود. من از مدرسه به خانه بر می گشتم که یکی از بچه های کلاس را دیدم. اسمش مارک بود و انگار همه‌ی کتابهایش را با خود به خانه می برد. \r\nبا خودم گفتم: 'کی این همه کتاب رو آخر هفته به خانه می بره. حتما ً این پسر خیلی بی حالی است!' \r\nمن برای آخر هفته ¬ام برنامه‌ ریزی کرده بودم. (مسابقه‌ی فوتبال با بچه ها، مهمانی خانه‌ی یکی از همکلاسی ها) بنابراین شانه هایم را بالا انداختم و به راهم ادامه دادم.‌ \r\nهمینطور که می رفتم،‌ تعدادی از بچه ها رو دیدم که به طرف او دویدند و او را به زمین انداختند. کتابهاش پخش شد و خودش هم روی خاکها افتاد. \r\nعینکش افتاد و من دیدم چند متر اونطرفتر، ‌روی چمنها پرت شد. سرش را که بالا آورد، در چشماش یه غم خیلی بزرگ دیدم. بی اختیار قلبم به طرفش کشیده شد و بطرفش دویدم. در حالیکه به دنبال عینکش می گشت، ‌یه قطره درشت اشک در چشمهاش دیدم. \r\nهمینطور که عینکش را به دستش می‌دادم، گفتم: ' این بچه ها یه مشت آشغالن!' \r\nاو به من نگاهی کرد و گفت: ' هی ، متشکرم!' و لبخند بزرگی صورتش را پوشاند. از آن لبخندهایی که سرشار از سپاسگزاری قلبی بود. \r\nمن کمکش کردم که بلند شود و ازش پرسیدم کجا زندگی می کنه؟ معلوم شد که او هم نزدیک خانه‌ی ما زندگی می کند. ازش پرسیدم پس چطور من تو را ندیده بودم؟ \r\nاو گفت که قبلا به یک مدرسه‌ی خصوصی می رفته و این برای من خیلی جالب بود. پیش از این با چنین کسی آشنا نشده بودم. ما تا خانه پیاده قدم زدیم و من بعضی از کتابهایش را برایش آوردم. \r\nاو واقعا پسر جالبی از آب درآمد. من ازش پرسیدم آیا دوست دارد با من و دوستانم فوتبال بازی کند؟ و او جواب مثبت داد. \r\nما تمام اخر هفته را با هم گذراندیم و هر چه بیشتر مارک را می شناختم، بیشتر از او خوشم می‌آمد. دوستانم هم چنین احساسی داشتند. \r\nصبح دوشنبه رسید و من دوباره مارک را با حجم انبوهی از کتابها دیدم. به او گفتم:' پسر تو واقعا بعد از مدت کوتاهی عضلات قوی پیدا می کنی،‌با این همه کتابی که با خودت این طرف و آن طرف می بری!' مارک خندید و نصف کتابها را در دستان من گذاشت. \r\nدر چهار سال بعد، من و مارک بهترین دوستان هم بودیم. وقتی به سال آخر دبیرستان رسیدیم، هر دو به فکر دانشکده افتادیم. مارک تصمیم داشت به جورج تاون برود و من به دوک. \r\nمن می دانستم که همیشه دوستان خوبی باقی خواهیم ماند. مهم نیست کیلومترها فاصله بین ما باشد. \r\nاو تصمیم داشت دکتر شود و من قصد داشتم به دنبال خرید و فروش لوازم فوتبال بروم. \r\nمارک کسی بود که قرار بود برای جشن فارغ التحصیلی صحبت کند. من خوشحال بودم که مجبور نیستم در آن روز روبروی همه صحبت کنم. \r\nمن مارک را دیدم. او عالی به نظر می رسید و از جمله کسانی به شمار می آمد که توانسته اند خود را در دوران دبیرستان پیدا کنند. \r\nحتی عینک زدنش هم به او می آمد. همه‌ی دخترها دوستش داشتند. پسر، گاهی من بهش حسودی می کردم! \r\nامروز یکی از اون روزها بود. من میدیم که برای سخنرانی اش کمی عصبی است. بنابراین دست محکمی به پشتش زدم و گفتم: ' هی مرد بزرگ! تو عالی خواهی بود!' \r\nاو با یکی از اون نگاه هایش به من نگاه کرد( همون نگاه سپاسگزار واقعی) و لبخند زد: ' مرسی'. \r\nگلویش را صاف کرد و صحبتش را اینطوری شروع کرد: ' فارغ التحصیلی زمان سپاس از کسانی است که به شما کمک کرده اند این سالهای سخت را بگذرانید. والدین شما، معلمانتان، خواهر برادرهایتان شاید یک مربی ورزش... اما مهمتر از همه، دوستانتان... \r\nمن اینجا هستم تا به همه ی شما بگویم دوست کسی بودن، بهترین هدیه ای است که شما می توانید به کسی بدهید. من می خواهم برای شما داستانی را تعریف کنم.' \r\nمن به دوستم با ناباوری نگاه می کردم، در حالیکه او داستان اولین روز آشناییمان را تعریف می کرد. به آرامی گفت که در آن تعطیلات آخر هفته قصد داشته خودش را بکشد. او گفت که چگونه کمد مدرسه اش را خالی کرده تا مادرش بعدا ً وسایل او را به خانه نیاورد. \r\nمارک نگاه سختی به من کرد و لبخند کوچکی بر لبانش ظاهر شد. \r\nاو ادامه داد: 'خوشبختانه، من نجات پیدا کردم. دوستم مرا از انجام این کار غیر قابل بحث، باز داشت.' \r\nمن به همهمه‌ ای که در بین جمعیت پراکنده شد گوش می دادم، در حالیکه این پسر خوش قیافه و مشهور مدرسه به ما درباره‌ی سست ترین لحظه های زندگیش توضیح می داد. \r\nپدر و مادرش را دیدم که به من نگاه می کردند و لبخند می زدند. همان لبخند پر از سپاس. \r\nمن تا آن لحظه عمق این لبخند را درک نکرده بودم. \r\nهرگز تاثیر رفتارهای خود را دست کم نگیرید. با یک رفتار کوچک، شما می توانید زندگی یک نفر را دگرگون نمایید: برای بهتر شدن یا بدتر شدن. \r\n"},{"id":1921,"category_id":2,"category_code":"s2","source_id":88,"title":"کلک اقتصادی","content":"روزی روزگاری در روستایی در هند؛ مردی به روستایی‌ها اعلام کرد که برای خرید هر میمون ۱۰ دلار به آنها پول خواهد داد. روستایی‌ها هم که دیدند اطراف‌شان پر است از میمون؛ به جنگل رفتند و شروع به گرفتن‌شان کردند و مرد هم هزاران میمون به قیمت ۱۰ دلار از آنها خرید ولی با کم شدن تعداد میمون‌ها روستایی‌ها دست از تلاش کشیدند. به همین خاطر مرد این‌بار پیشنهاد داد برای هر میمون به آنها ۲۰ دلار خواهد پرداخت. با این شرایط روستایی‌ها فعالیت خود را از سر گرفتند. پس از مدتی موجودی باز هم کمتر و کمتر شد تا روستایی‌ان دست از کار کشیدند و برای کشاورزی سراغ کشتزارهای‌شان رفتند.\r\nاین بار پیشنهاد به ۲۵ دلار رسید و در نتیجه تعداد میمون‌ها آن‌قدر کم شد که به سختی می‌شد میمونی برای گرفتن پیدا کرد. این‌بار نیز مرد تاجر ادعا کرد که برای خرید هر میمون ۵۰ دلار خواهد داد ولی چون برای کاری باید به شهر می‌رفت کارها را به شاگردش محول کرد تا از طرف او میمون‌ها را بخرد. \r\nدر غیاب تاجر، شاگرد به روستایی‌ها گفت: «این همه میمون در قفس را ببینید! من آنها را به ۳۵ دلار به شما خواهم فروخت تا شما پس از بازگشت مرد آنها را به ۵۰ دلار به او بفروشید.» روستایی‌ها که [احتمالا مثل شما] وسوسه شده بودند پول‌های‌شان را روی هم گذاشتند و تمام میمون‌ها را خریدند... البته از آن به بعد دیگر کسی مرد تاجر و شاگردش را ندید و تنها روستایی‌ها ماندند و یک دنیا میمون!... \r\n"},{"id":1922,"category_id":2,"category_code":"s2","source_id":89,"title":"صدای دل انگیز زندگی","content":"سفره را جمع کردم ودر یخچال گذاشتم ولی ناگاه !! صدای دلنشینی و آهنگینی را شنیدم.\r\nبه مادر گفتم : می شنوید؟\r\nگفت : چی ؟\r\nگفتم: صدای آهنگی دلنشین می آید\r\nمادر گفت: آنچه می شنوی ، قل قل سماور است و صدای گر گر بخاری ، صدای باد که شیشه های پنجره را می لرزاند ، صدای خش خش کاغذی که خواهرت روی آن می نویسد . صدای شستشوی ظرفهای من و صدای بوق و عبور ماشینها در خیابان است .\r\nگفتم صدای دیگر هم هست\r\nصدای آهنگین شما که داشتید حرف می زدید !\r\nپدر گفت : و صدای گوش تیز کردن من که داشتم به حرف های شما گوش می دادم !\r\nهر سه خندیدیم .\r\n"},{"id":1923,"category_id":2,"category_code":"s2","source_id":90,"title":"بداخلاق","content":"\r\nروزگاری پسر کوچکی بود که بسیار بداخلاق وعصبانی بود\r\nپدرش یک کیسه میخ به او داو گفت:\r\nهروقت عصبانی شدی باید یک میخ به پشت دیوار بکوبی \r\nاولین روز،پسر ۳۷میخ به دیوار کوبید.\r\nپس از چند هفته او یاد گرفت چطور عصبانیتش را کنترل کند ،\r\nتعدادمیخ هایی که کوبیده میشد رفته رفته کم شدند.\r\nاومتوجه شد که کنترل اعصاب به مراتب از کوبیدن میخ روی دیوار آسان تراست \r\nسرانجام روزی رسید که پسر به هیچ وجه عصبانی نمیشد \r\nاوموضوع را به پدرش گفت و پدر پیشنهاد کرد که پسر به ازای هرروز \r\nکه اعصابش را کنترل میکند یک میخ را از دیوار بکشد .\r\nروزها گذشت وسر انجام پسر توانست به پدرش بگوید \r\nکه میخ ها تمام شده اند .پدر دست پسرش را گرفت وبه طرف دیوار برد \r\nوگفت :((کارت را خوب انجام دادی پسرم ،اما به این سوراخ های\r\nروی دیوار نگاه کن دیوار هرگز مثل قبل نخواهد شد .\r\nوقتی هنگام عصبانیت چیزی میگی ،آنها هم مانند این میخ ها از \r\nخودشان بیم وترس باقی میگذارند . توشاید با چاقو به کسی بزنی ،\r\nهرقدر که بگویی متاسفم هنوز هم زخم آنجاست .\r\nزخم زبان هم به بدی زخم جسمی است.))\r\n"},{"id":1924,"category_id":2,"category_code":"s2","source_id":91,"title":"الکساندر فلمینگ","content":"کشاورز فقیر اسکاتلندی بود که فلمینگ نام داشت .یک \r\nروز وقتی برای تامین معاش خانواده اش کار می کرد ،صدای \r\nگریه وکمکی از باتلاقی که در همان نزدیکی قرار داشت شنید .\r\nاو ابزار کارش را بر زمین انداخت وبه طرف باتلاق دوید .در انجا پسر\r\nوحشت زده ای بود و برای رهایی از آن داد وفریاد و تقلا می کرد .فلمینگ کشاورز،\r\nپسر را از مرگ وحشتناک وتدریجی نجات داد .روز بعد یک کالسکه تجملاتی به محل زندگی\r\nمرد اسکاتلندی آمد .یک نجیب زاده با لباسی زیبا پیاده شد وخودش را پدر پسری که فیلمینگ کشاورز \r\nاو را نجات داده بود معرفی کرد .نجیب زاده گفت :((شما جان پسر مرا نجات داده اید ، \r\nمن می خواهم جبران کنم .))کشاورز اسکاتلندی در حالی که دست پس میزد پاسخ داد:\r\n((من در قبال کاری که انجام داده ام چیزی قبول نمیکنم .))در همین لحظه پسر کشاورز به طرف در کلبه آمد.\r\nنجیب زاده پرسید :((آیا این پسر شماست؟))کشاورز باغرور جواب داد بله او گفت:\r\n((من با شما معامله ای میکنم .اجازه بدهید او را ببرم وتحت آموزش های خوبی قرار دهم .\r\nاگر پسرت هم به خوبی پدرش باشد ،مردی خواهد شد که به او افتخار میکنی .))و او قبول کرد \r\nپسر فلمینگ کشاورز از دانشکده پزشکی بیمارستان سنت ماری در لندن فارغ التحصیل شد وهم چنان ادامه داد \r\nتا در سرار جهان به عنوان دانشمند برجسته ،کاشف پنیسیلین ،آقای الکساندر فلمینگ معروف شد .\r\nسال ها بعد پسر نجیب زاده به ذات الریه مبتلا شد \r\nچه چیزی اورا نجات داد ؟...پنیسیلین!!\r\n"},{"id":1925,"category_id":2,"category_code":"s2","source_id":92,"title":"معبد شیوا","content":"راهبی در نزدیکی معبد شیوا زندگی میکرد. در خانه روبرویش یک روسپی اقامت داشت. راهب که میدید مردان زیادی به اون خونه رفت و آمد میکنند تصمیم گرفت با او صحبت کند. زن را سرزنش کرد و گفت: تو بسیار گناهکاری . روز و شب به خدا بی احترامی میکنی. چرا دست از این کار نمیکشی؟چرا کمی به زندگی پس از مرگت فکر نمیکنی؟\r\nزن به شدت از گفته های راهب شرمنده شد و از صمیم قلب به درگاه خدا دعا کرد و بخشش خواست. همچنین از خدای قادر و متعال خواست که راه تازه ای برای امرار معاش به او نشان بدهد. اما راه دیگری پیدا نکرد و بعد از یک هفته گرسنگی دوباره به روسپی گری پرداخت. اما هر بار از درگاه خدا آمرزش میخواست. راهب که از بی تفاوتی زن نسبت به اندرز او خشمگین شده بود فکر کرد: از حالا تا روز مرگ این گناهکار ، میشمرم که چند مرد وارد خانه او شده اند!\r\nو از آن روز کار دیگری نکرد جز این که زندگی آن زن را زیر نظر بگیرد. هر مردی وارد خانه اومیشد، راهب هم ریگی بر ریگ های دیگر میگذاشت ! مدتی گذشت راهب دوباره زن را صدا کرد و گفت: این کوه سنگ را میبینی؟ هر کدام از این سنگها نماینده یکی از گناهان کبیره ای است که انجام داده ای.آن هم بعد از هشدار من! دوباره میگویم مراقب اعمالت باش!\r\nزن به لرزه افتاد ، فهمید گناهانش چقدر انباشته شده. به خانه برگشت اشک پشیمانی ریخت و و دعا کرد: خدایا کی رحمت تو مرا از این زندگی مشقت بار رها میکند؟\r\nخداوند دعایش را پذیرفت و همان روز فرشته مرگ ظاهر شد و جان او را گرفت. فرشته به دستور خدا جان راهب را هم گرفت. و با خود برد. روح روسپی بی درنگ به بهشت رفت اما شیاطین روح راهب را به دوزخ بردند. در راه راهب دید که بر روسپی چه گذشته و شکوه کرد: خدایا این عدالت توست؟ من که تمام زندگی ام را در فقر و اخلاص گذراندم به دوزخ میروم و آن روسپی که فقط گناه کرد به بهشت میرود؟\r\nیکی از فرشته ها پاسخ داد: تصمیمات خداوند همیشه عادلانه است! تو فکر میکردی که عشق خدا یعنی فضولی در رفتار دیگران. هنگامی که تو قلبت را سرشار فضولی میکردی این زن شب و روز دعا میکرد. روح او پس از گریستن چنان سبک میشد که توانستیم او را تا بهشت بالا ببریم. اما آن ریگها چنان روح تو را اسنگین کرده بودند که نتوانستیم آن را بالا ببریم.... \r\nفکر میکنید با قضاوت های نابه جامون تا به حال چقدر روحمون رو سنگین کردیم؟\r\n"},{"id":1926,"category_id":2,"category_code":"s2","source_id":93,"title":"تفسیرهای خاخام","content":"خاخامی در میان مردم محبوبیت زیادی داشت ، همه مسحور گفته هایش می شدند . همه به جز اسحاق که همیشه با تفسیرهای خاخام مخالفت می کرد و اشتباهات او را به یادش می آورد . بقیه از اسحاق به خشم می آمدند ، اما کاری از دستشان بر نمی آمد. \r\n\r\nروزی اسحاق در گذشت . در مراسم خاکسپاری ، مردم متوجه شدند که خاخام به شدت اندوهگین است.\r\nیکی گفت : چرا اینقدر ناراحتید ؟ او که همیشه از شما انتقاد می کرد !\r\nخاخام پاسخ داد : من برای دوستی که اکنون در بهشت است ناراحت نیستم . برای خودم ناراحتم .وقتی همه به من احترام می گذاشتند ، او با من مبارزه می کرد و مجبور بودم پیشرفت کنم .حالا رفته ، شاید از رشد باز بمانم.\r\n"},{"id":1927,"category_id":2,"category_code":"s2","source_id":94,"title":"رویاها","content":"دخترهایش دل خوش کرده اند به پسر عاشق رویاهایشان که هم پولدار است و هم خوش چشم و ابرو و همیشه لبخند زیبایی به لب دارد و هرآنچه او گفت پسرک با کمال میل می پذیرد و دخترک به آرزویش می رسد و می شود همان سیندرلای معروف!! و پسر هایش دل بسته اند به دختر زیبای خیالات شان!! همان همسر وفاداری که وصفش را شنیده بودند، همان که با نگاهش خستگی ها و زشتی های عالم را از ذهن و تن به در می کند!! چه می‌دانم، شاید نتیجه اش باشد از همان فیلمفارسی های معروف عشق و عاشقی. و هر روز همین ها که ذکر و خیرشان بود به دنبال هم می گردند، می بینند، می پسندند و دل می بندند! و می فهمند که نه! این آن که ما می خواستیم نیست و روز از نو روزی از نو..."},{"id":1928,"category_id":2,"category_code":"s2","source_id":95,"title":"دلمشغولی های شاه سلطان حسین","content":"فرمانروای شهر از دیدار شاه سلطان حسین صفوی باز می گشت . بزرگان و ریش سفیدان شهر به دیدار سالار شهر خویش رفته و از حالا شاه ایران زمین جویا می شدند .\r\nفرمانروای شهر گفت : شاه شاداب و آسوده هستند در زمانی که من در مجلس گفتگوی ایشان با بزرگان بودم دیدم ایشان ریز امور کشور را در اختیار دارند قیمت همه اجناس ، سود بازآریان ، میزان خمس ، تعداد مسافران سفر حج ، مشهد و کربلا را به خوبی می دانند و از زندگی خصوصی فرمانروایان شهرهای ایران آگاهند . به این مجموع آگاهی ایشان را از زندگی خصوصی و درس علما را نیز بیفزایید ، این نشان می دهد کشور هیچ مشکلی ندارد .\r\nیکی از ریش سفیدان خردمند از جای برخواسته و گفت خدا خودش این کشور را نگهدارد . پادشاهی که چنین سرگرم اندرون کشور است کی به برون آن می نگرد .\r\nسخن آن پیر خیلی زود آشکار شد . دودمان صفویه بدست تعدادی راهزن سرنگون گشت . اندیشمند یگانه کشورمان ارد بزرگ می گوید : آدمی تنها زمانی دربند رویدادهای روزمره نخواهد شد که در اندیشه ایی فراتر از آنها در حال پرواز باشد .\r\nشاه سلطان حسین به روزمرگی دچار بود تمام هوش خود را برای نگهداری و نگهبانی از چیزهای خرد و بی ارزش بکار گرفته و بیشتر انباردار خوبی بود تا فرمانروایی که باید نظر به آینده کشور داشته باشد .\r\n"},{"id":1929,"category_id":2,"category_code":"s2","source_id":96,"title":"خشم فرمانروا","content":"گویند سربازان سر دسته راهزنان را گرفته و پیش فرمانروای شهر یزد آوردند چون او را بدید بی درنگ شمشیر از نیام بیرون کشیده و سرش را از بدن جدا ساخت یکی از پیشکاران گفت گرگ در گله خویش بزرگ می شود این گرگ حتما خانواده دارد بگویید آنها را هم مجازات کنند . فرمانروا که سخت آشفته بود گفت آنها را هم از میان برخواهم داشت تا کسی هوس راهزنی به سرش نزند . همسر و کودک راهزن و همچنین برادر او را نزد فرمانروا آوردند کودک و زن می گریستند و برادر راهزن التماس می کرد و می گفت چاه کن است و گناهی مرتکب نشده اما فرمانروا در کوره خشم بود و هیچ کس در دفاع از آن نگون بختان دم بر نمی آورد . چون فرمانروا دست به شمشیر برد یکی از رایزنان پیر سالخورده گفت وقتی برادر شما محاکمه شد شما کجا بودید . فرمانروا به یاد آورد که زمانی برادر خود او را به جرم دزدی و غارت از دم تیغ گذرانده بودند. پیرمرد گفت من آن زمان همین جا بودم ، آن فرمانروا هم قصد جان نزدیکان برادر شما را داشت اما همانجا گفتم فرمانروای عادل ، بیگناهان را برای ایجاد عدل نمی کشد .\r\nفرمانروای یزد دست از شمشیر برداشت و گفت این بیچارگان را رها کنید .\r\nارد بزرگ اندیشمند نام آشنای کشورمان می گوید : کین خواهی از خاندان یک بدکار ، تنها نشان ترس است ، نه نیروی آدمهای فرهمند .\r\n"},{"id":1930,"category_id":2,"category_code":"s2","source_id":97,"title":"ساختن روح","content":"آلن جونز کشیش می گوید برای ساختن روح به چهار نیروی نامرئی نیاز داریم : عشق ، مرگ ،قدرت ، زمان .\r\nعشق لازم است زیرا خدا ما را دوست دارد .\r\nآگاهی از مرگ لازم است تا زندگی را بهتر بفهمیم .\r\nمبارزه برای رشد لازم است ، اما نباید در دام قدرتی که در این مبارزه به دست می آید بیفتیم زیرا می دانیم که این قدرت هیچ ارزشی ندارد.\r\nسرانجام باید بپذیریم که روح ما هر چند ابدی است اما در این لحظه گرفتار دام زمان است ، با فرصتها و محدودیتهایش .بدین ترتیب باید طوری عمل کنیم که در زمان بگنجد، کاری کنیم تا به هر لحظه ارزش بگذاریم .نباید این چهار نیرو را مشکلاتی بدانیم که باید حل کنیم ، زیرا خارج از اختیار ماست . باید آنها را بپذیریم و بگذاریم آن چه را که باید به ما بیاموزند .\r\n"},{"id":1931,"category_id":2,"category_code":"s2","source_id":98,"title":"شادی در تنهایی نیست","content":"ناصر خسرو قبادیانی بسوی باختر ایران روان بود . شبی میهمان شبانی شد در روستای کوچکی در نزدیکی سنندج ، نیمه های شب صدای فریاد و ناله شنید برخاست و از خانه بیرون آمد صدای فریاد و ناله های دلخراش و سوزناک از بالای کوه به گوش می رسید . مبهوت فریاد ها و ناله ها بود که شبان دست بر شانه اش گذاشت و گفت : این صداها از آن مردیست که همسر و فرزند خویش را از دست داده ، این مرد پس از چندی جستجو در غاری بر فراز کوه ماندگار شد هر از گاهی شبها ناله هایش را می شنویم . چون در بین ما نیست همین فریاد ها به ما می گوید که هنوز زنده است و از این روی خوشحال می شویم . که نفس می کشد . ناصر خسرو گفت می خواهم به پیش آن مرد روم . مرد گفت بگذار مشعلی بیاورم و او را از شیار کوه بالا برد . ناصر خسرو در آستانه غاری ژرف و در زیر نور مهتاب مردی را دید که بر تخته سنگی نشسته و با دو دست خویش صورتش را پنهان نموده بود .\r\nمرد به آن دو گفت از جان من چه می خواهید ؟ بگذارید با درد خود بسوزم و بسازم .\r\nناصر خسرو گفت : من عاشقم این عشق مرا به سفری طول دراز فرا خوانده ، اگر عاشقی همراه من شو . چون در سفر گمشده خویش را باز یابی . دیدن آدمهای جدید و زندگی های گوناگون تو را دگرگون خواهد ساخت . در غیر اینصورت این غار و این کوهستان پیشاپیش قبرستان تو و خاطراتت خواهد بود . چون پگاه خورشید آسمان را روشن کند براه خواهم افتاد اگر خواستی به خانه شبان بیا تا با هم رویم .\r\nچون صبح شد آن مرد همراه ناصرخسرو عازم سفر بود . سالها بعد آن مرد همراه با همسری دیگر و دو کودک به دیار خویش باز گشت در حالی که لبخندی دلنشین بر لب داشت .\r\n"},{"id":1932,"category_id":2,"category_code":"s2","source_id":99,"title":"فروتنی فریاپت","content":"اردوان (سومین پادشاه اشکانی و فرزند تیرداد یکم) پادشاه ایران از بستر بیماری برخواسته بود با تنی چند از نزدیکان ، کاخ فرمانروایی را ترک گفته و در میان مردم قدم می زد . به درمانگاه شهر که رسیدند اردوان گفت به دیدار پزشک خویش برویم و از او بخاطر آن همه زحمتی که کشیده قدردانی کنیم.\r\nچون وارد درمانگاه شد کودکی را دید که پایش زخمی شده و پزشک پایش را معالجه می نماید. مادر کودک که هنوز پادشاه را نشناخته بود با ناله به پزشک می گفت خدا پای فرزند پادشاه را اینچنین نماید تا دیگر این بلا را بر سر مردم نیاورد .\r\nپادشاه رو به زن کرده و گفت مگر فرزند شاه این بلا را بر سر کودکت آورده و مادر گفت آری کودکم در میانه کوچه بود که فرزند پادشاه فریاپت با اسب خویش چنین بلای را بر سر کودکم آورد . پادشاه گفت مگر فرزند شاه را می شناسی ؟ و زن گفت خیر ، همسایگان او را به من معرفی نمودند . پادشاه دستور داد فریاپت را بیاورند پزشک به زن اشاره نمود که این کسی که اینجاست همان پادشاه ایران است .\r\nزن فکر می کرد به خاطر حرفی که زده او را به جرم گستاخی با تیغ شمشیر به دونیم می کنند . پسر شاه ایران را آوردند و پدر به او گفت چرا این گونه کردی و فرزند گفت متوجه نشدم . و کودک را اصلا ندیدم . پدر گفت از این زن و کودکش عذرخواهی کن . فرزند پادشاه روی به مادر کودک نموده عذر خواست پادشاه ایران کیسه ایی زر به مادر داده و گفت فرزندم را ببخش چون در مرام پادشاهان ایران ، زور گویی و اذیت خلق خویش نیست .\r\nزن با دیدن این هم فروتنی پادشاه و فریاپت به گریه افتاده و می گفت مرا به خاطر گستاخی ببخشید . و پادشاه ایران اردوان در حالی که از درمانگاه بیرون می آمد می گفت : فرزند من باید نمونه نیک رفتاری باشد نمونه…\r\n"},{"id":1933,"category_id":2,"category_code":"s2","source_id":100,"title":"قهرمان های آدمهای کوچک","content":"نادانی رو به خردمندی کرد و گفت فلان شخص ، ثروتمندترین مرد شهر است . باید از او آموخت و گرامیش داشت .\r\nخردمند خندید و گفت فلانی کیسه اش را از پول انباشته آنگاه تو اینجا با جیب خالی بر او می بالی و از من می خواهی همچون تو باشم ؟!\r\nنادان گفت خوب گرامیش مدار ، بزودی از گرسنگی خواهی مرد .\r\nخردمند خندید و از او دور شد . از گردش روزگار مرد ثروتمند در کام دزدان افتاد و آنچه داشت از کف بداد و دزدان کامروا شدند . چون چندی گذشت همان نادان رو به خردمند کرد و گفت فلان دزد بسیار قدرتمند است باید همچون او شکست ناپذیر بود . و خردمند باز بر او خندید و فردای حرف نادان دزد به چنگال سربازان فرمانروای اسیر شده ، برهنه اش نموده و در میدان شهر شلاقش می زدند که خردمند دید نادان با شگفتی این ماجرا را می بیند . دست بر شانه اش گذاشت و گفت عجب قهرمانهایی داری ، هر یک چه زود سرنگون می شوند و نادان گفت قهرمانهای تو هم به خواری می افتند . خردمند خندید و گفت قهرمانان من در ظرف اندیشه تو جای نمی گیرند ، همین جا بمان و شلاق خوردن آن که گرامیش می داشتی را ببین ، و با خنده از او دور شد .\r\n"},{"id":1934,"category_id":2,"category_code":"s2","source_id":101,"title":"عشق بورزید تا به شما عشق بورزند","content":"\r\nروزی روزگاری پسرک فقیری زندگی می کرد که برای گذران زندگی و تامین مخارج تحصیلش دستفروشی می کرد.از این خانه به آن خانه می رفت تا شاید بتواند پولی بدست آورد.روزی متوجه شد که تنها یک سکه 10 سنتی برایش باقیمانده است و این درحالی بود که شدیداً احساس گرسنگی می کرد.تصمیم گرفت از خانه ای مقداری غذا تقاضا کند. بطور اتفاقی درب خانه ای را زد.دختر جوان و زیبائی در را باز کرد.پسرک با دیدن چهره زیبای دختر دستپاچه شد و بجای غذا ، فقط یک لیوان آب درخواست کرد.\r\nدختر که متوجه گرسنگی شدید پسرک شده بود بجای آب برایش یک لیوان بزرگ شیر آورد.پسر با تمانینه و آهستگی شیر را سر کشید و گفت : «چقدر باید به شما بپردازم؟ » دختر پاسخ داد: « چیزی نباید بپردازی.مادر به ما آموخته که نیکی ما به ازائی ندارد.» پسرک گفت: پس من از صمیم قلب از شما سپاسگذاری می کنم\r\nسالها بعد دختر جوان به شدت بیمار شد.پزشکان محلی از درمان بیماری او اظهار عجز نمودند و او را برای ادامه معالجات به شهر فرستادند تا در بیمارستانی مجهز ، متخصصین نسبت به درمان او اقدام کنند.\r\nدکتر هوارد کلی ، جهت بررسی وضعیت بیمار و ارائه مشاوره فراخوانده شد.هنگامیکه متوجه شد بیمارش از چه شهری به آنجا آمده برق عجیبی در چشمانش درخشید.بلافاصله بلند شد و بسرعت بطرف اطاق بیمار حرکت کرد.لباس پزشکی اش را بر تن کرد و برای دیدن مریضش وارد اطاق شد.در اولین نگاه اورا شناخت.\r\n\r\nسپس به اطاق مشاوره باز گشت تا هر چه زود تر برای نجات جان بیمارش اقدام کند.از آن روز به بعد زن را مورد توجهات خاص خود قرار داد و سر انجام پس از یک تلاش طولانی علیه بیماری ، پیروزی ازآن دکتر کلی گردید.\r\nآخرین روز بستری شدن زن در بیمارستان بود.به درخواست دکتر هزینه درمان زن جهت تائید نزد او برده شد.گوشه صورتحساب چیزی نوشت.آنرا درون پاکتی گذاشت و برای زن ارسال نمود.\r\nزن از باز کردن پاکت و دیدن مبلغ صورتحساب واهمه داشت.مطمئن بود که باید تمام عمر را بدهکار باشد.سرانجام تصمیم گرفت و پاکت را باز کرد.چیزی توجه اش را جلب کرد.چند کلمه ای روی قبض نوشته شده بود.آهسته انرا خواند:\r\n\"بهای این صورتحساب قبلاً با یک لیوان شیر پرداخت شده است\"\r\n"},{"id":1935,"category_id":2,"category_code":"s2","source_id":102,"title":"مزدور","content":"روزی ابوریحان درس به شاگردان می گفت که خونریز و قاتلی پای به محل درس و بحث نهاد . شاگردان با خشم به او می نگریستند و در دل هزار دشنام به او می دادند که چرا مزاحم آموختن آنها شده است . آن مرد رسوا روی به حکیم نموده چند سئوال ساده نمود و رفت . فردای آن روز ، شاعری مدیحه سرای دربار ، پای به محل درس گذارده تا سئوالی از حکیم بپرسد شاگردان به احترامش برخواستند و او را مشایعت نموده تا به پای صندلی استاد برسد .\r\nکه دیدند از استاد خبری نیست هر طرف را نظر کردند اثری از استاد نبود . یکی از شاگردان که از آغاز چشمش به استاد بود و او را دنبال می نمود در میانه کوچه جلوی استاد را گرفته و پرسید : چگونه است دیروز آدمکشی به دیدارتان آمد پاسخ پرسش هایش را گفتید و امروز شاعر و نویسنده ایی سرشناس آمده ، محل درس را رها نمودید ؟!\r\nابوریحان گفت : یک بزهکار تنها به خودش و معدودی لطمه میزند ، اما یک نویسنده و شاعر خود فروخته کشوری را به آتش می کشد.\r\nشاگرد متحیر به چشمان استاد می نگریست که ابوریحان بیرونی از او دور شد .\r\nحکیم ارد بزرگ اندیشمند یگانه کشورمان می گوید : هنرمند و نویسنده مزدور ، از هر کشنده ای زیانبارتر است .\r\nابوریحان بیرونی دانشمند آزاده ایی بود که هیچگاه کسب قدرت او را وسوسه ننمود و همواره عمر خویش را وقف ساختن ابوریحان های دیگر کرد .\r\n"},{"id":1936,"category_id":2,"category_code":"s2","source_id":103,"title":"برایت ارزوی کافی میکنم!!!","content":"\r\nدر فرودگاه گفتگوی لحظات آخر بین مادر و دختری را شنیدم: \r\nهواپیما درحال حرکت بود و آنها همدیگر را بغل کردند و مادر گفت: \" دوستت دارم و آرزوی کافی برای تومیکنم.\"\r\nدختر جواب داد: \" مامان زندگی ما باهم بیشتر از کافی هم بوده است. محبت تو همه آن چیزی بوده که من احتیاج داشتم. من نیز آرزوی کافی برای تومیکنم.\" \r\nآنها همدیگر را بوسیدند و دختر رفت. مادر بطرف پنجره ای که من در کنارش نشسته بودم آمد. آنجا ایستاد و می توانستم ببینم که می‌خواست و احتیاج داشت که گریه کند. من نمی‌خواستم که خلوت او را بهم بزنم ولی خودش با این سؤال اینکار را کرد: \" تا حالا با کسی خداحافظی کردید که می‌دانید برای آخرین بار است که او را می‌بینید؟\" \r\nجواب دادم: \" بله کردم. منو ببخشید که فضولی می‌کنم چرا آخرین خداحافظی؟\" \r\nاو جواب داد: \" من پیر و سالخورده هستم او در جای خیلی دور زندگی می‌کنه. من چالش‌های زیادی را پیش رو دارم و حقیقت اینست که سفر بعدی او برای مراسم دفن من خواهد بود.\" \r\n وقتی داشتید خداحافظی می‌کردید شنیدم که گفتید \" آرزوی کافی را برای تو می‌کنم. \" می‌توانم بپرسم یعنی چه؟ \r\nاو شروع به لبخند زدن کرد و گفت: \" این آرزویست که نسل بعد از نسل به ما رسیده. پدر و مادرم عادت داشتند که اینرا به همه بگن.\"\r\nاو مکثی کرد و درحالیکه سعی می‌کرد جزئیات آنرا بخاطر بیاورد لبخند بیشتری زد و گفت: \" وقتی که ما گفتیم \" آرزوی کافی را برای تو می‌کنم. \" ما می‌خواستیم که هرکدام زندگی ای پر از خوبی به اندازه کافی که البته می‌ماند داشته باشیم. \" سپس روی خود را بطرف من کرد و این عبارتها را که در پائین آمده عنوان کرد: \r\n\" آرزوی خورشید کافی برای تو می‌کنم که افکارت را روشن نگاه دارد بدون توجه به اینکه روز چقدر تیره است. آرزوی باران کافی برای تو می‌کنم که زیبایی بیشتری به روز آفتابیت بدهد. \r\nآرزوی شادی کافی برای تو می‌کنم که روحت را زنده و ابدی نگاه دارد \r\nآرزوی رنج کافی برای تو می‌کنم که کوچکترین خوشی‌ها به بزرگترینها تبدیل شوند \r\nآرزوی بدست آوردن کافی برای تو می‌کنم که با هرچه می‌خواهی راضی باشی \r\nآرزوی از دست دادن کافی برای تو می‌کنم تا بخاطر هر آنچه داری شکرگزار باشی \r\nآرزوی سلام‌های کافی برای تو می‌کنم که بتوانی خداحافظی آخرین راحتری داشته باشی \r\nبعد شروع به گریه کرد و از آنجا رفت... \r\nمی گویند که تنها یک دقیقه طول می‌کشد که دوستی را پیدا کنید٬ یکساعت می‌کشد تا از او قدردانی کنید اما یک عمر طول می‌کشد تا او را فراموش کنید...\r\n"},{"id":1937,"category_id":2,"category_code":"s2","source_id":104,"title":"وجود و دریای خرد","content":"پدری به زور فرزند نوجوان خویش را نزد استاد آورد و گفت : من با خانواده ام تازه به شهر ابیورد آمده ایم فرزندم می پندارد همه چیز را می داند و نیاز به درس و مکتب ندارد \r\nاستاد رو به فرزند او کرد و پرسید : آیا اینچنین است ؟\r\nنوجوان گفت : آیا میزان فهم ما از جهان بیشتر از آن چیزی ست که می اندیشیم ؟\r\nاستاد گفت : خیر\r\nنوجوان پرسید آیا فهم ما بالاتر از دیده ، تصور و خیال ماست ؟\r\nاستاد پاسخ داد : خیر ، بیشتر نیست.\r\nنوجوان گفت : حد خیال ، تصور و دیده ما آیا بیشتر از خرد و رشد عقلی و سنی ماست ؟\r\nاستاد پاسخ داد خیر نیست .\r\nنوجوان گفت : پس خرد که ماحصل دانش و تجربه هست و سن که در گذر ایام بدست می آید شاه بیت وجودی هر انسان است. \r\nاستاد گفت آری چنین است. \r\nنوجوان گفت دانش در کف دست استاد است و تجربه در دم خوری با پیران با تجربه و همچنین کار و سفر \r\nاستاد گفت آری اینچنین است. \r\nنوجوان گفت : من به نیکی می دانم سخن شما چیست چون کتاب های مکتب خانه ها را خوانده ام و به یاد سپرده ام امروز بر آنم که به سفر باشم و با پیران گفتگو کنم. \r\nاستاد گفت : خرد همچون دریاست . هر یک از ما با این دریا وجودمان را سیراب می کنیم و درختان و گلهای وجودمان را شکوفا می سازیم . در کتاب ، دریایی از خرد نهفته است اگر می گویی همه را نیک می دانی . خواهم گفت این دریا همچون سیل هستی وجودت را پوشانیده و کمالی در تو نیست . جز غرقه شدن در خردی که نه عرض آن را می دانی و نه طول آنرا . تنها زمانی خرد باعث کمال تو می گردد که تو وجود داشته باشی . دیده شوی و سبزی کمال را که در وجودت نقش بسته به همگان نشان دهی ، آنکه راه تو را می رود در نهایت در جوانی پیر شده و با همان کمالی که هیچ گاه درست درکش نکرده منزوی می گردد. چون همگان را خالی از آن خردی می بیند که در وجود بی وجود خویش می بیند \r\nنوجوان پرسید مگر نباید به دریای خرد فرود آمد. \r\nاستاد گفت باید خرد را مانند باران بر وجود خویش باراند و وجود خویش را سبز کرد که این کمال و دلپذیری است. \r\nپانزده سال بعد استاد مرد ژولیده ایی را در کنار مکتب خانه خویش دید که به شاگردان مشتاق دانش می نگرد و حرفهای آنها را گوش می دهد . آن مرد ژولیده پیش آمد و گفت من هم نوجوان غرقه در دریایم که به مکتب شما نیامدم و امروز می بینم همه چیز برایم بی مفهوم است . و امروز می فهمم مسیرم درست نبوده و افسوس که جوانی و بهار زندگی خویش را در این راه باختم . استاد گفت به گرمابه رو و موی و ریش کوتاه کن پیشم بیا تا به تو بگویم چه باید کرد. \r\nمرد نیز چنین کرد و استاد یکی از همان کتابهایی را که مرد زمانی گفته بود آن را بخوبی می داند داد و گفت یک بار دیگر بخوان و دوباره پیشم بیا مرد فردای آن روز پیش آمد و گفت خواندم .استاد گفت حالا هر روز تنها یک صفحه از این کتاب را برای شاگردان بخوان و آموزش بده . و اینبار با این کار زمین وجود خویش را از زیر این دریای مهیب خارج ساز.\r\n"},{"id":1938,"category_id":2,"category_code":"s2","source_id":105,"title":"نشان لیاقت عشق","content":"\r\nفرمانروایی که می کوشید تا مرزهای جنوبی کشورش را گسترش دهد، با مقاومتهای سرداری محلی مواجه شد و مزاحمتهای سردار به حدی رسید که خشم فرمانروا را برانگیخت و بنابراین او تعداد زیادی سرباز را مامور دستگیری سردار کرد. عاقبت سردار و همسرش به اسارت نیروهای فرمانروا درآمدند و برای محاکمه و مجازات با پایتخت فرستاده شدند.\r\nفرمانروا با دیدن قیافه سردار جنگاور تحت تاثیر قرار گرفت و از او پرسید: ای سردار، اگر من از گناهت بگذرم و آزادت کنم، چه می کنی؟\r\nسردار پاسخ داد: ای فرمانروا، اگر از من بگذری به وطنم باز خواهم گشت و تا آخر عمر فرمانبردار تو خواهم بود.\r\nفرمانروا پرسید: و اگر از جان همسرت در گذرم، آنگاه چه خواهی کرد؟\r\nسردار گفت: آنوقت جانم را فدایت خواهم کرد!\r\nفرمانروا از پاسخی که شنید آنچنان تکان خورد که نه تنها سردار و همسرش را بخشید بلکه او را به عنوان استاندار سرزمین جنوبی انتخاب کرد.\r\nسردار هنگام بازگشت از همسرش پرسید: آیا دیدی سرسرای کاخ فرمانروا چقدر زیبا بود؟ دقت کردی صندلی فرمانروا از طلای ناب ساخته شده بود؟\r\nهمسر سردار گفت: راستش را بخواهی، من به هیچ چیزی توجه نکردم. سردار با تعجب پرسید: پس حواست کجا بود؟\r\nهمسرش در حالی که به چشمان سردار نگاه می کرد به او گفت: تمام حواسم به تو بود. به چهره مردی نگاه می کردم که گفت حاضر است به خاطر من جانش را فدا کند!\r\n"},{"id":1939,"category_id":2,"category_code":"s2","source_id":106,"title":"امنیت در دستگاه دیوانی !","content":"روزی مردی پیش قاضی آمده و گفت : ای قاضی نگهبان دروازه شهر هر بار که من وارد و یا خارج می شوم مرا به تمسخر می گیرد و در مقابل حتی نزدیکانم دشنامم می دهد . قاضی پرسید چرا ؟ این رفتار را می کند مگر تو چه کرده ایی آن مرد گفت : هیچ ، خود در شگفتم چرا با من چنین می کند. \r\nقاضی گفت بیا برویم و خود با لباسی پوشیده در پشت سر شاکی به راه افتاده و به او گفت به دروازه شو تا ببینم این نگهبان چگونه است . به دروازه که رسیدند نگهبان پوز خندی زد و شروع کرد به دشنام گویی و تمسخر آن مرد بیچاره . قاضی صورت خویش را از زیر نقاب بیرون آورد و گفت مردک مگر مریضی که با رهگذران اینچنین می کنی سپس دستور داد او را گرفته و محبس برده و بر کف پایش ۵۰ ضربه شلاق بزنند. \r\nسه روز بعد دستور داد نگهبان را بیاورند و رو کرد به او و گفت مشکل تو با این مرد در چه بود که هر بار او را می دیدی دیوانه میشدی و چنین می گفتی. \r\nمرد گفت : هیچ\r\nقاضی پرسید پس چرا در میان این همه آدم به او می گفتی ؟\r\nگفت : چون می پنداشتم این حق را دارم که با مردم چنین کنم اما هر ضربه شلاق به یادم آورد که باید پا از گلیم خود بیرون نگذارم. \r\nقاضی گفت : عجیب است با این که به تو بدی نکرده بود تو به او می تاختی ؟ چون فکر می کردی این حق را داری !؟\r\nآن مرد گفت سالها به مردم به مانند زیر دست می نگریستم فکر می کردم چون مواجب بگیر سلطانم پس دیگران از من پایین تر هستند . این شد که کم کم به عابرین آن طور برخورد می کردم که دوست داشتم. \r\nقاضی پس از آن ماجرا پنهانی در کار کارمندان و کارگزاران دستگاه دیوانی دقت کرد و دید اغلب آنها دیگر وظایف خویش را آن گونه که دستور گرفته اند انجام نمی دهند و هر یک به شیوه ایی به خطاکاری روی آورده اند . به محضر سلطان شد و شرح جریان را بگفت. \r\nسلطان در دم دستور داد او را بگیرند و به محبس برده و ۵۰ چوب بر کف پای بیچاره قاضی بنوازند . چون قاضی را بار دیگر به پیشگاه سلطان آوردند سلطان گفت : خوب حالا فهمیدی در کار دیوانی دخالت کردن چه مزه ایی دارد . قاضی سر افکنده و گریان گفت : آری و سپاس از چوب سلطان که مرا به خود آورد. \r\nقاضی چون از درگاه سلطانی برون شد با خود گفت : عجبا ! من به پیش سلطان شدم تا خطاهای عوامل حکومت را باز گویم و او به من فهماند زمان چقدر دستگاه و دیوان را عوض می کند . متفکر یگانه کشورمان ارد بزرگ می گوید : ریشه رشد تبهکاری در امنیت بزهکار است . و اینچنین بود که قاضی دست از قضاوت شسته با خانواده عزم ترک دیار خویش کرد . چون از دروازه خارج می شد دید همان نگهبان بزهکار با ترکه ایی در دست ، مردم را مضحکه و مورد ریش خند قرار می دهد...\r\n"},{"id":1940,"category_id":2,"category_code":"s2","source_id":107,"title":"امید ، خود زندگیست","content":"گفته اند اسبی به بیماری گرفتار آمد و پشت دروازه شهر بیفتاد . صاحب اسب او را رها کرده و به داخل شهر شد مردم به او گفتند اسبت از چه بابت به این روزگار پرنکبت بیفتاد و مرد گفت از آنجایی که غمخواران نازنینی همچون شما نداشت و مجبور بود دائم برای من بار حمل کند. \r\nیکی گفت براستی چنین است من هم مانند اسب تو شده ام . مردم به هیکل نحیف او نظری انداختند و او گفت زن و فرزندانم تا توان داشتم و بار می کشیدم در کنارم بودند و امروز من هم مانند اسب این مرد تنهایم و لحظه رفتنم را انتظار می کشم.\r\nمی گویند آن مرد نحیف هر روز کاسه ایی آب از لب جوی برداشته و برای اسب نحیف تر از خود می برد . ودر کنار اسب می نشست و راز دل می گفت . چند روز که گذشت اسب بر روی پای ایستاد و همراه پیرمرد به بازار شد. \r\nصاحب اسب و مردم متعجب شدند . او را گفتند چطور برخواست . پیرمرد خنده ایی کرد و گفت از آنجایی که دوستی همچون من یافت که تنهایش نگذاشتم و در روز سختی کنارش بودم .اندیشمند یگانه کشورمان حکیم ارد بزرگ می گوید : دوستی و مهر ، امید می آفریند و امید زندگی ست.\r\nمی گویند : از آن پس پیر مرد و اسب هر روز کام رهگذران تشنه را سیراب می کردند و دیگر مرگ را هم انتظار نمی کشیدند.\r\n"},{"id":1941,"category_id":2,"category_code":"s2","source_id":108,"title":"خانم نظافتچی","content":"\r\nدر امتحان پایان ترم دانشکده پرستاری، استاد ما سوال عجیبی مطرح کرده بود. من دانشجوی زرنگی بودم و داشتم به سوالات به راحتی جواب می دادم تا به آخرین سوال رسیدم،\r\nنام کوچک خانم نظافتچی دانشکده چیست؟\r\nسوال به نظرم خنده دار می آمد. در طول چهار سال گذشته، من چندین بار این خانم را دیده بودم. ولی نام او چه بود؟\r\nمن کاغذ را تحویل دادم، در حالی که آخرین سوال امتحان بی جواب مانده بود.\r\nپیش از پایان آخرین جلسه، یکی از دانشجویان از استاد پرسید: استاد، منظور شما از طرح آن سوال عجیب چه بود؟\r\nاستاد جواب داد: در این حرفه شما افراد زیادی را خواهید دید. همه آنها شایسته توجه و مراقبت شما هستند، بـاید آنها را بشناسید و به آنهـا محبت کنید حتـی اگر این محبت فقط یک لبخنـد یا یک سلام دادن ساده باشد.\r\nمن هرگز آن درس را فراموش نخواهم کرد.\r\n"},{"id":1942,"category_id":2,"category_code":"s2","source_id":109,"title":"جنگ خوب است یا بد ؟","content":"بر دل مردم شهر نیشابور ترسی بسیار افتاده بود سپاه دشمن به نزدیکی شهر رسیده و تیراندازان و مردان نیزه بدست در پشت کنگره ها ایستاده و کمین گرفته بودند . ارگ فرمانروای شهر پر رفت و آمدتر از هر زمان دیگر بود یکی از سربازان محکم درب خانه خردمند پیر شهر را می کوبید و در نهایت پیرمرد را با خود به ارگ برد فرمانروای شهر نگاهی به صورت آرام و نگاه متین پیر مرد افکنده و گفت می دانم که گلایه ها در سینه داری اما اکنون زمان این سخن ها نیست به من بگو در این زمان چه راهی در پیش روی ماست . شهر در درون سپاه فراوان دشمن گم خواهد شد . دشمن شهرهای بین راه را به آتش کشیده و سرها بریده است . دیوارها و درهای شهر توان مقاومت زیادی ندارند . هیچ سپاهی هم به کمک ما نخواهد آمد ما هستیم و همین خونخواران پیش روی . لشکر آنها همچون نیزه ایی به سینه شهرمان فرود خواهند آمد.\r\nریش سفید شهر خنده اش گرفت : فرمانروا پرسید هنگامه جنگ و ستیز است نه جای خنده .\r\nپیرمرد گفت فرمانروایی که می ترسد جان خویش را هم نمی تواند از مرگ نجات دهد چه برسد به مردم بی پناه را.\r\nفرمانروا گفت سپاه دشمن در نزدیکی نیشابور است آن وقت من نهراسم .\r\nریش سفید گفت در این مواقع هر دو طرف سپاه به فرمانروای خویش و شجاعت او می اندیشند . مردم زندگی و امیدشان را در سیمای شما می بینند و سپاه دشمن هم به فرمانروای خویش .\r\nفرمانروا اگر نباشد نه شهر باقی می ماند و نه سپاه دشمن. ریش سفید ادامه داد راه نجات ما از شمشیر های برهنه دشمن تنها و تنها در به زانو در آوردن فرمانروای آنها خلاصه می شود . شما در درون شهر هستید و آنهم در مرکز شهر و آنها در بیابان و بدون دیوار ، حال فرمانروایی که امنیت ندارد شما هستید یا دشمن ؟.\r\nفرمانروای نیشابور گفت اکنون در اطراف فرمانروای دشمن پنجاه هزار شمشیر بدست حضور دارند چگونه به او دست یابیم . ریش سفید گفت نیشابور شهری بزرگ است بگذار دور شهر حلقه بزنند به این شکل سپاه دشمن پراکنده می شود و تعداد نگهبانان فرمانروای آنان نیز بسیار کم خواهد شد . آن گاه در زمان مناسب عده ایی را با تن پوشهایی همانند سربازان دشمن به سراغ او بفرستید و سپس سر او را بر نیزه کرده بر برج و باروهای شهر بگردانید تا ترس بر جان آنان فرو افتد در غروب همان روز طبل جنگ را به صدا درآورد به گونه ایی که همه حتی سربازان ما هم بدانند فردا کارزار در راه است. فردایش چون سپیده خورشید آسمان دشت را روشن کند سپاهی نخواهید دید.\r\nدر همین هنگام رایزنان دربار نیشابور وارد شده و پند و اندرز دادن را آغاز کردند آنها می گفتند جنگ به سود هیچ کس نیست خونریزی دوای درمان هیچ دردی نیست و قتل کردن عذاب دنیوی و اخروی خواهد داشت . فرمانروا رو به ریش سفید شهر کرده و گفت می بینی رایزنان شهر ما را . پیرمرد گفت نوک پیکان سپاه دشمن از همین جا آغاز می شود . فرمانروا با شنیدن این سخن دستور داد رایزنان ابله را به زندان بیفکنند .\r\nاندیشمند یگانه کشورمان ارد بزرگ می گوید : آنهایی که آمادگی برای پاسخگویی به تجاوز دشمن را با گفتن این سخن که : ” جنگ بد است و باید مهربان بود ، درگیری کار بدیست” را رد می کنند ، ساده لوحانی هستند که خیلی زود در تنور دشمن خواهند سوخت .\r\nچهار روز گذشت دروازه های شهر نیشابور دوباره باز شد ، کشاورزان و باغداران به سوی محل کار خویش بازگشتند و زندگی ادامه یافت .\r\nفرمانروای نیشابور تا پایان زندگی پیرمرد به خانه او می رفت و درس ها می آموخت .\r\n"},{"id":1943,"category_id":2,"category_code":"s2","source_id":110,"title":"سرانجام عشق به ایران","content":"سهروردی را گفتند تا به کی از ایران سخن گویی ؟ گفت تا آن زمان که زنده ام . گفتند این بیماری است چون ایران دختره باکره ای نیست برای تو ، و گنج سلطانی هم برای بی چیزی همانند تو نخواهد بود .\r\nسهروردی خندید و گفت شما عشق ندانید چیست . دوباره او را گرفته و به سیاهچال بردند.\r\nشبها از درون روزن سیاه چال زندان سهروردی ، اشعار حکیم فردوسی را زندانبانان می شنیدند و از این روی ، وعده های غذایش را قطع نمودند و در نهایت سهروردی از گرسنگی به قتل رسید…\r\n"},{"id":1944,"category_id":2,"category_code":"s2","source_id":111,"title":"آزمون شایعه سقراط","content":"\r\nسقراط در یونان باستان به دلیل بهره مندی از دانش فراوان شهرت زیادی داشت . \r\nروزی یکی از اشنایان، فیلسوف بزرگ را دید وگفت :((آیا می دانی الآن درباره دوستت چه چیزی شنیدم ؟))\r\nسقراط پاسخ داد :((یک دقیقه صبر کن !قبل از اینکه چیزی بگویی ،می خواهم یک آزمون کوچک را بگذرانی که\r\nبه ان آزمون سه صافی می گویند.))\r\n-((سه صافی؟!))\r\nسقراط ادامه داد :((بله !پیش از آنکه چیزی درباره دوستم بگوی بهتر است\r\nچند لحظه صبر کنی وآنچه را که قصد گفتنش را داری از صافی بگذرانی .\r\nبه این دلیل آن را آزمون سه صافی نامیده ام .\r\nاولین صافی حقیقت است .\r\nآیا واقعا مطمئن هستی که آنچه می گویی حقیقت دارد؟))\r\nمرد گفت:((نه!راستش را بخواهید فقط آن را شنیدم ...))\r\nسقراط گفت :((بسیار خوب.بنابراین واقعا نمیدانی راست است یا نه .\r\nحالا اجازه بده دومین صافی را امتحان کنیم صافی خوبی .\r\nآیا آنچه را که میخواهی درباره دوستم بگویی مطلب خوبی است ؟))\r\n-((نه برعکس))\r\nسقراط ادمه داد :((بنابراین شما می خواهید چیز بدی را درباره ی او بگویید\r\nاما مطمئن نیستید حقیقت داشته باشد \r\nشاید هنوز بتوانید از آزمون بگذری چون یک صافی دیگر هم مانده است .\r\nصافی سودمندی .\r\nآیا انچه را که می خواهید درباره ی دوستم بگویید برای من مفید است ؟))\r\n((نه واقعا نه...))\r\nخب،سقراط نتیجه گیری کرد :((اگر آنچه را که میخواهیید بگویید راست نیست خوب نیست \r\nوفایده ای هم ندارد ،اصلاچرا بگویید ؟))\r\n"},{"id":1945,"category_id":2,"category_code":"s2","source_id":112,"title":"نقاشی خراب شده ","content":"\r\nیکی بود ویکی نبود .یک نقاش مشهور در حال اتمام نقاشی اش بود. \r\nآن نقاشی به طور باور نکردنی زیبا بودوباید در مراسم ازدواج شاهزاده\r\nخانمی نشان داده می شد.\r\nنقاش آن چنان غرق هیجان ناشی از نقاشی اش بود که \r\nنا خود آگاه در حالی که آن نقاشی ۲*۸متر را تحسین می کرد \r\nچند قدم به طرف عقب رفت.هنگام به عقب رفتن پشتش را نگاه نکرد .\r\nاو آنقدر رفت تا اینکه فقط یک قدم تا لبه ی آن ساختمان بلند \r\nفاصله داشت.فقط با یک قدم بیشتر می توانست خودش را بکشد .\r\nشخصی دید که نقاش چکار می کند \r\nونزدیک بود فریاد بزند و به او اخطار دهد ،اما متوجه شد \r\nکه فریاد او ممکن است نقاش را غافلگیر کند وبر حسب اتفاق \r\nیک قدم دیگر به عقب برود و بیفتد .مرد قلم مو ورنگ برداشت و\r\nروی آن تصویر شروع به نقاشی نمود تا اینکه کاملا به آن آسیب زد.\r\nنقاش وقتی متوجه شد که چه اتفاقی برای نقاشی اش افتاده است \r\nبسیار عصبانی شد وجلو آمد تامرد را بزند.اما افرادی که در ان \r\nنزدیکی بودند اورا گرفتند وآخرین جایی را که او ایستاده بود \r\nونزدیک بود سقوط کند را نشانش دادند.\r\nگاهی ما آیندمان را بسیار ترسیم کرده ایم ،\r\nبا روز های رویایی در کنار کسی که دوستش داریم \r\nاما گویا خداوند وقتی می بند چه خطری مقابل ما است \r\n،نقاش زیبایمان را خراب می کند گاهی اوقات از\r\nآنچه خداوند بر سرمان آورده ناراحت می شویم ویا در محل \r\nکار از مافوقمان عصبانی میشویم اما یک مطلب را نباید\r\nهرگزر فراموش کنیم:\r\nخداوند همیشه بهترین هارا برای ما مهیا می کند.\r\n"},{"id":1946,"category_id":2,"category_code":"s2","source_id":113,"title":"نقطه ی ضعف","content":"\r\nپسری درتصادف دست چپش را از دست داده بود به باشگاهی رفت.\r\nپسر درس هایش را پیش یک استاد ژاپنی شروع کرد.\r\nبا وجود اینکه پسر خوب تمرین میکرد ،\r\nاما نمی توانست بفهمد که چرا استاد پس\r\nاز سه ماه آموزش\r\nفقط یک حرکت را به او آموزش میدهد.\r\nسرانجام پسر گفت:\r\n ((استاد!آیا نباید من حرکات بیشتری یاد بگیرم ؟))\r\nاستاد پاسخ داد:((این تنها حرکتی است که شما می دانید اما در عین \r\nحال تنها حرکتی است که نیاز به دانستن آن دارید.))\r\nپسر حرف استاد را کاملا نمی فهمید اما با توجه به اینکه به او ایمان داشت به تمرین ادامه داد.\r\nچند ماه بعد استاد پسر را به اولین مسابقه اش برد .\r\nاوبا کمال تعجب دو مسابقه اولی را به آسانی پیروز شد.سومین مسابقه\r\nمشکل تر بود ،اما پس از مدتی رقیب او شکیبایی اش را از دست داد\r\nو حمله کرد پسر استادانه از تنها فنش استفاده کرد و مسابقه را برد .\r\nدر حالی که پسر هنوز از موفقیتش مبهوت مانده بود ،به فینال رسید .\r\nاین بار حریف او بزرگتر قوی تر وباتجربه تر بود .\r\nبرای مدتی به نظرمی رسید که پسر مغلوب می شود .\r\nبا توجه به اینکه ممکن بود پسر مصدوم شود،داور وقت استراحت اعلام کرد .\r\nاو نزدیک بود مسابقه را متوقف کند که استاد پادر میانی کرد و اصرار نمود\r\nکه:((نه،بگذار ادامه دهد .))به محض اینکه مسابقه از سر گرفته شد ،رقیبش اشتباه بدی کرد \r\nبلافاصله پسر از تنها فنش استفاده کرد تا او را گیر بیندازد .\r\nپسر مسابقه را برد وقهرمان شد.\r\nدر راه خانه پسر واستاد تمام حرکات را در مسابقات مرور کردند.سپس پسر \r\nتمام جراتش را جمع کرد تا آنچه را که واقعا در ذهنش می گذش از استاد بپرسد \r\n((استاد،چطور من با یک فن تورنومنت را بردم ؟))\r\nاستاد پاسخ داد:((تو به دو دلیل برنده شدی.\r\nاول به خاطر اینکه تو در یکی از مشکل ترین فنون پرتاب\r\nجودو تقریبا استاد شده ای و دوم به این دلیل که تنها \r\nدفاع شناخته شده برای حرکت این است که حریفت\r\nبازوی چپ تورا بگیرد.))\r\nنکته اخلاقی داستان:\r\nبزرگترین ضعف پسر ،بزرگترین قوتش شده بود.\r\n"},{"id":1947,"category_id":2,"category_code":"s2","source_id":114,"title":"مقام از خود ممنون","content":"مامور کنترل مواد مخدر به یک دامداری در ایالت تکزاس امریکا می رود و به صاحب سالخورده ی آن می گوید:\r\nباید دامداری ات را برای جلوگیری از کشت مواد مخدربازدید کنم.\" دامدار، با اشاره به بخشی از مرتع ، می گوید:\r\n\"باشه، ولی اونجا نرو.\". مامور فریاد می زنه:\"آقا! من از طرف دولت فدرال اختیار دارم.\" بعد هم دستش را می برد و از جیب پشتش نشان خود را بیرون می کشد و با افتخار نشان دامدار می دهد و اضافه می کند:\r\n\"اینو می بینی؟ این نشان به این معناست که من اجازه دارم هرجا دلم می خواد برم..در هر منطقه یی...\r\nبدون پرسش و پاسخ. حالی ات شد؟ میفهمی؟\"\r\nدامدار محترمانه سری تکان می دهد، پوزش می خواهد و دنبال کارش می رود\r\nکمی بعد، دامدار پیر فریادهای بلند می شنود و می بیند که ماموراز ترس گاو بزرگ وحشی که هرلحظه به او نزدیک تر می شود، دوان دوان فرار می کند.\r\nبه نظر می رسد که مامور راه فراری ندارد و قبل از این که به منطقه ی امن برسد، گرفتار شاخ گاو خواهد شد. دامدار لوازمش را پرت میکند، باسرعت خود را به نرده ها می رساند واز ته دل فریاد می کشد:\" نشان. نشانت را نشانش بده !\"\r\n"},{"id":1948,"category_id":2,"category_code":"s2","source_id":115,"title":"کوزه های آب","content":"\r\nدر افسانه ای هندی آمده است که مردی هر روز دو کوزه بزرگ آب به دو انتهای چوبی می بست...چوب را روی شانه اش می گذاشت و برای خانه اش آب می برد.\r\nیکی از کوزه ها کهنه تر بود و ترک های کوچکی داشت. هربار که مرد مسیر خانه اش را می پیمود نصف آب کوزه می ریخت.\r\nمرد دو سال تمام همین کار را می کرد. کوزه سالم و نو مغرور بود که وظیفه ای را که به خاطر انجام آن خلق شده به طورکامل انجام می دهد. اما کوزه کهنه و ترک خورده شرمنده بود که فقط می تواندنصف وظیفه اش را انجام دهد.\r\nهر چند می دانست آن ترک ها حاصل سال ها کار است. کوزه پیر آنقدر شرمنده بود که یک روز وقتی مرد آماده می شد تا از چاه آب بکشد تصمیم گرفت با او حرف بزند : \" از تو معذرت می خواهم. تمام مدتی که از من استفاده کرده ای فقط از نصف حجم من سود برده ای...فقط نصف تشنگی کسانی را که در خانه ات منتظرند فرو نشانده ای. \"\r\nمرد خندید و گفت: \" وقتی برمی گردیم با دقت به مسیر نگاه کن. \" موقع برگشت کوزه متوجه شد که در یک سمت جاده...سمت خودش... گل ها و گیاهان زیبایی روییده اند.\r\nمرد گفت: \" می بینی که طبیعت در سمت تو چقدر زیباتر است؟ من همیشه می دانستم که تو ترک داری و تصمیم گرفتم از این موضوع استفاده کنم.\r\nاین طرف جاده بذر سبزیجات و گل پخش کردم و تو هم همیشه و هر روز به آنها آب می دادی. به خانه ام گل برده ام و به بچه هایم کلم و کاهو داده ام. اگر تو ترک نداشتی چطور می توانستی این کار را بکنی؟\r\n"},{"id":1949,"category_id":2,"category_code":"s2","source_id":116,"title":"رقابت یا رفاقت","content":"روزی دو شکارچی برای شکار به جنگلی می روند . در حین شکار ناگهان خرس گرسنه ای را می بینند که قصد حمله به آنها را دارد.\r\nبا دیدن این خرس گرسنه هر دوی آنها پا به فرار می گذارند در حین فرار ناگهان یکی از آنها می ایستد و وسایل خود را دور می اندازد و کفشهایش را نیز از پا در می آورد ...\r\nو دور می اندازد دوستش با تعجب از او می پرسد: فکر می کنی با این کار از خرس گرسنه سریع تر خواهی دوید؟\r\nاو می گوید : از خرس سریع تر نخواهم دوید ولی از تو سریع تر خواهم دوید در این صورت خرس اول به تو می‌رسد و تو را می خورد و من می توانم فرار کنم!\r\n"},{"id":1950,"category_id":2,"category_code":"s2","source_id":117,"title":"چشمها را باید شست","content":"\r\nميگويند در کشور ژاپن مرد ميليونري زندگي ميکرد که از درد چشم خواب بچشم نداشت و براي مداواي چشم دردش انواع قرصها و آمپولها را بخود تزريق کرده بود اما نتيجه چنداني نگرفته بود.\r\nوي پس از مشاوره فراوان با پزشکان و متخصصان زياد درمان درد خود را مراجعه به يک راهب مقدس و شناخته شده مي بيند.*\r\n*وي به راهب مراجعه ميکند و راهب نيز پس از معاينه وي به او پيشنهاد کرد که مدتي به هيچ رنگي بجز رنگ سبز نگاه نکند. پس از بازگشت از نزد راهب، او به تمام مستخدمين خود دستور ميدهد با خريد بشکه هاي رنگ سبز تمام خانه را با سبز رنگ آميزي کند.همينطور تمام اسباب و اثاثيه خانه را با همين رنگ عوض ميکند.\r\nپس از مدتي رنگ ماشين، ست لباس اعضاي خانواده و مستخدمين و هر آنچه به چشم مي آيد را به رنگ سبز و ترکيبات آن تغيير ميدهد و البته چشم دردش هم تسکين مي يابد.*\r\n*مدتي بعد مرد ميليونر براي تشکر از راهب وي را به منزلش دعوت مي نمايد. راهب نيز که با لباس نارنجي رنگ به منزل او وارد ميشود متوجه ميشود که بايد لباسش را عوض کرده و خرقه اي به رنگ سبز به تن کند. او نيز چنين کرده و وقتي به محضر بيمارش ميرسد از او مي پرسد آيا چشم دردش تسکين يافته؟ مرد ثروتمند نيز تشکر کرده و ميگويد :\" بله . اما اين گرانترين مداوايي بود که تاکنون داشته\". مرد راهب با تعجب به بيمارش ميگويد بالعکس اين ارزانترين نسخه اي بوده که تاکنون تجويز کرده ام.*\r\n*براي مداواي چشم دردتان، تنها کافي بود عينکي با شيشه سبز خريداري کنيد و هيچ نيازي به اين همه مخارج نبود.\r\nبراي اين کار نميتواني تمام دنيا را تغيير دهي، بلکه با تغيير ديدگاه و يا نگرشت ميتواني دنيا را به کام خود درآوري.*\r\n"},{"id":1951,"category_id":2,"category_code":"s2","source_id":118,"title":"دانشجوی نمونه","content":"در اولين جلسه دانشگاه استاد ما خودش را معرفی نمود و از ما خواست كه كسی را بيابيم كه تا به حال با او آشنا نشده‌ايم، برای نگاه كردن به اطراف ايستادم، در آن هنگام دستی به آرامی شانه‌ ام را لمس نمود، برگشتم و خانم مسن كوچكی را ديدم كه با خوشرويی و لبخندی كه وجود بی‌ عيب او را نمايش می‌داد، به من نگاه می ‌كرد. او گفت: «سلام عزيزم، نام من رز است، هشتاد و هفت سال دارم، آيا می‌توانم تو را در آغوش بگيرم؟» پاسخ دادم: «البته كه می‌ توانيد»، و او مرا در آغوش خود فشرد. پرسيدم: «چطور شما در چنين سن جوانی به دانشگاه آمده ايد؟» به شوخی پاسخ داد: «من اينجا هستم تا يك شوهر پولدار پيدا كنم، ازدواج كرده يك جفت بچه بياورم، سپس بازنشسته شده و مسافرت نمایم». پرسيدم: «نه، جداً چه چيزی باعث شده؟» كنجكاو بودم كه بفهمم چه انگيزه‌ای باعث شده او اين مبارزه را انتخاب نمايد. به من گفت: «همیشه رويای داشتن تحصيلات دانشگاهی را داشتم و حالا، يكی دارم».\r\nپس از كلاس به اتفاق تا ساختمان اتحاديه دانشجويی قدم زديم و در يك كافه گلاسه سهيم شديم،‌ ما به طور اتفاقی دوست شده بوديم، ‌برای سه ماه ما هر روز با هم كلاس را ترك می‌كرديم، او در طول يك سال شهره ی كالج شد و به راحتی هر كجا كه می‌رفت، دوست پيدا می‌كرد، او عاشق اين بود كه به اين لباس در آيد و از توجهاتی كه ساير دانشجويان به او می‌نمودند، لذت می‌برد، او اينگونه زندگی می‌كرد.\r\nدر پايان آن ترم ما از رز دعوت كرديم تا در ميهمانی ما سخنرانی نمايد، من هرگز چيزی را كه او به ما گفت، فراموش نخواهم كرد، وقتی او را معرفی كردند، در حالی كه داشت خود را برای سخنرانی از پيش مهيا شده‌ اش، آماده می‌كرد، به سوی جايگاه رفت، تعدادی از برگه‌های متون سخنرانی‌اش بروی زمين افتادند، آزرده و كمی دست پاچه به سوی ميكروفون برگشته و به سادگی گفت: «عذر می‌خواهم، من بسيار وحشت زده شده‌ ام بنابراين سخنرانی خود را ايراد نخواهم كرد، اما به من اجازه دهيد كه تنها چيزی را كه می‌دانم، به شما بگويم»، او گلويش را صاف نموده و‌ آغاز كرد: «ما بازی را متوقف نمی‌كنيم چون كه پير شده‌ايم، ما پير می‌شويم زیرا كه از بازی دست می‌كشيم، تنها يك راه برای جوان ماندن، شاد بودن و دست يابی به موفقيت وجود دارد، شما بايد بخنديد و هر روز رضايت پيدا كنيم. ما عادت كرديم كه رويايی داشته باشيم، وقتی روياهايمان را از دست می‌دهيم، می‌ميريم، انسان‌های زيادی در اطرافمان پرسه می‌زنند كه مرده ‌اند و حتی خود نمی‌دانند، تفاوت بسيار بزرگی بين پير شدن و رشد كردن وجود دارد، اگر من كه هشتاد و هفت ساله هستم برای مدت يك سال در تخت خواب و بدون هيچ كار ثمر بخشی بمانم، هشتاد و هشت ساله خواهم شد، هر كسی می‌تواند پير شود، آن نياز به هيچ استعداد خدادادی يا توانايی ندارد، رشد كردن هميشه با يافتن فرصت ها برای تغيير همراه است. متأسف نباشيد، يك فرد سالخورده معمولاً برای كارهايی كه انجام داده تأسف نمی‌خورد، كه برای كارهايی كه انجام نداده است». او به سخنرانی‌اش با ایراد «سرود شجاعان» پايان بخشيد و از فرد فرد ما دعوت كرد كه سرودها را خوانده و آنها را در زندگی خود پياده نمایيم.\r\nدر انتهای سال، رز دانشگاهی را كه سال ها قبل آغاز كرده بود، به اتمام رساند، يك هفته پس از فارغ‌ التحصيلی رز با آرامش در خواب فوت كرد، بيش از دو هزار دانشجو در مراسم خاكسپاری او شركت كردند، به احترام خانمی شگفت‌ انگيز كه با عمل خود برای ديگران سرمشقی شد كه هيچ وقت برای تحقق همه آن چيزهايی كه می‌توانید باشید، دير نيست.\r\n"},{"id":1952,"category_id":2,"category_code":"s2","source_id":119,"title":"همسایه حسود","content":"روزی مردی برای خود خانه ای بزرگ و زیبا خرید که حیاطی بزرگ با درختان میوه داشت.\r\nدر همسایگی او خانه ای قدیمی بود که صاحبی حسود داشت که همیشه سعی می کرد اوقات او را تلخ کند و با گذاشتن زباله کنار خانه اش و ریختن آشغال آزارش می داد.\r\nیک روز صبح خوشحال از خواب برخاست و همین که به ایوان رفت دید یک سطل پر از زباله در ایوان است. سطل را تمیز کرد، برق انداخت و آن را از میوه های تازه و رسیده حیاط خود پر کرد تا برای همسایه ببرد.\r\nوقتی همسایه صدای در زدن او راشنید خوشحال شد وپیش خود فکر کرداین بار دیگر برای دعوا آمده است.\r\nوقتی در را بازکرد مرد به او یک سطل پر از میوه های تازه و رسیده داد و گفت : \" هر کس آن چیزی را با دیگری قسمت میکند که از آن بیشتر دارد .....\"\r\n"},{"id":1953,"category_id":2,"category_code":"s2","source_id":120,"title":"آرزو","content":"مادربزرگ می گفت: با چشمهای بسته آرزوهایت حتما برآورده می شود.آرزو کردم.چشمهایم را که باز کردم از برآورده شدن آرزویم خبری نبود. دلگیر شدم. یادم آمد آن موقع که مادربزرگ این حرف را زده بود آرزوهایم به اندازه یک بسته پفک و یک مشت نخودچی، کوچک بود.\r\nبابای من یک فرشته است.\r\nمداد را محکم توی دستم می گیرم. امروز می خواهم یک دیکته بدون غلط بنویسم و حتی یک نقطه هم جا نگذارم.\r\nمعلم شروع می کند: به نام خدا؛ بابا آب داد. و دوباره تکرار می کند: بابا آب داد.\r\nو من می نویسم: بابا جان داد.\r\nو معلم: بابا با اسب آمد.\r\nو من می نویسم: بابا با فرشته آمد.\r\nو معلم:\r\nو من می نویسم: بابا گوشه اتاق با آن ماسک روی صورتش خیلی زیبا شده بود؛ مثل فرشته های توی کتابهای داستانم نورانی؛ فقط پرواز نمی کرد که دیروز پرواز هم کرد.\r\nمن دیدم که دارد پرواز می کند. به من لبخند زد، برای من دست تکان داد و از من قول گرفت که دختر خوبی باشم.\r\nمن لبخند زدم.\r\nو مادر اشک ریخت.\r\nحالا هر شب توی آسمان کنار فرشته ها برایم دست تکان می دهد.\r\nبابای من یک فرشته است.\r\nمعلم یک بار دیگر می خواند تا چیزی را جا نینداخته باشیم.\r\n-بابا آب داد.\r\nو من نوشته ام: بابا جان داد.\r\n-بابا با اسب آمد.\r\nو من نوشته ام: بابا با فرشته آمد.\r\n"},{"id":1954,"category_id":2,"category_code":"s2","source_id":121,"title":"عقابی که مرغ شد","content":"مردی یک روز تخم عقابی را به صورت اتفاقی در دشت پیدا کرد و آن را بی هیچ هدف خاصی و فقط برای اینکه به نوعی از آن محافظت کرده باشد در لانه مرغی گذاشت. چندی بعد جوجه عقاب با بقیه جوجه ها از تخم بیرون آمد و با آن ها بزرگ شد و در تمام زندگی اش همان کارهایی را انجام داد که مرغ ها می کردند.\r\nبرای پیدا کردن کرم ها و حشرات زمین را می کند و قُدقُد می کرد و گاهی با دست و پا زدن فراوان کمی در هوا پرواز می کرد. سال ها به همین منوال گذشت و عقاب دیگر خیلی پیر شده بود. روزی پرنده با عظمتی را بالای سرش بر فراز آسمان ابری دید. او با شکوه تمام، با یک حرکت جزئی بال های طلایی اش برخلاف جریان شدید باد پرواز می کرد.\r\nعقاب پیر بهت زده نگاهش کرد و پرسید: این کیست؟\r\nهمسایه اش پاسخ داد: این یک عقاب است، سلطان پرندگان. او متعلق به آسمان است و ما زمینی هستیم.\r\nعاقبت، عقاب داستان ما مثل یک مرغ زندگی کرد و مثل یک مرغ هم مُرد، زیرا فکر می کرد که یک مرغ است.\r\n"},{"id":1955,"category_id":2,"category_code":"s2","source_id":122,"title":"آرزوی سنگتراش","content":"\r\nروزی، سنگتراشی که از کار خود ناراضی بود و احساس حقارت می کرد، از نزدیکی خانه بازرگـانی رد می شد. در باز بود و او خانه مجلل، باغ و نوکران بازرگان را دید و به حال خود غبطه خورد و با خود گفت: این بازرگان چقدر قدرتمند است! و آرزو کرد که مانند بازرگان باشد.\r\nدر یک لحظه، او تبدیل به بازرگانی با جاه و جلال شد. تا مدت ها فکر می کرد که از همه قدرتمند تر است، تا این که یک روز حاکم شهر از آنجا عبور کرد، او دید که همه مردم به حاکم احترام می گذارند حتی بازرگانان. مرد با خودش فکر کرد: کاش من هم یک حاکم بودم، آن وقت از همه قوی تر می شدم!\r\nدر همان لحظه، او تبدیل به حاکم مقتدر شهر شد. در حالی که روی تخت روانی نشسته بود، مردم همه به او تعظیم می کردند. احساس کرد که نور خورشید او را می آزارد و با خودش فکر کرد که خورشید چقدر قدرتمند است.\r\nاو آرزو کرد که خورشید باشد و تبدیل به خورشید شد و با تمام نیرو سعی کرد که به زمین بتابد و آن را گرم کند.\r\nپس از مدتی ابری بزرگ و سیاه آمد و جلوی تابش او را گرفت. پس با خود اندیشید که نیروی ابر از خورشید بیشتر است، و تبدیل به ابری بزرگ شد.\r\nکمی نگذشته بود که بادی آمد و او را به این طرف و آن طرف هل داد. این بارآرزو کرد که باد شود و تبدیل به باد شد. ولی وقتی به نزدیکی صخره سنگی رسید، دیگر قدرت تکان دادن صخره را نداشت. با خود گفت که قوی ترین چیز در دنیا، صخره سنگی است و تبدیل به سنگی بزرگ و عظیم شد.\r\nهمان طور که با غرور ایستاده بود، ناگهان صدایی شنید و احساس کرد که دارد خرد می شود. نگاهی به پایین انداخت و سنگتراشی را دید که با چکش و قلم به جان او افتاده است...\r\nیار شفیق\r\n\r\nمحمد بن على ترمذى، از عالمان ربانى و دانشمندان عارف مسلك بود. در عرفان و طریقت ، به علم بسیار اهمیت مى ‏داد ؛ چنان كه او را \"حكیم الاولیاء\" مى ‏خواندند.\r\n\r\nدر جوانى با دو تن از دوستانش ، عزم كردند كه به طلب علم روند. چاره ‏اى جز این ندیدند كه از شهر خود ، هجرت كنند و به جایى روند كه بازار علم و درس ، در آن جا گرم ‏تر است.\r\nمحمد ، به خانه آمد و عزم خود را به مادر خبر داد.مادرش غمگین شد و گفت : اى جان مادر ! من ضعیفم و بى ‏كس و تو حامى من هستى ؛ اگر بروى ، من چگونه روزگار خود را بگذرانم. مرا به كه مى سپارى ؟ آیا روا مى ‏دارى كه مادرت تنها و عاجز بماند و تو دانشمند شوى ؟\r\nاز این سخن مادر ، دردى به دل او فرود آمد. ترك سفر كرد و آن دو رفیق ، به طلب علم از شهر بیرون رفتند.\r\nمدتى گذشت و محمد همچنان حسرت مى ‏خورد و آه مى ‏كشید.\r\nروزى در گورستان شهر نشسته بود و زار مى ‏گریست و مى ‏گفت : من این جا بى ‏كار و جاهل ماندم و دوستان من به طلب علم رفتند. وقتى باز آیند ، آنان عالم‏اند و من هنوز جاهل.\r\nناگاه پیرى نورانى بیامد و گفت : اى پسر!چرا گریانى ؟\r\nمحمد ، حال خود را باز گفت.\r\nپیر گفت : خواهى كه تو را هر روز درسى گویم تا به زودى از ایشان در گذرى و عالم ‏تر از دوستانت شوى ؟\r\nگفت : آرى ، مى‏ خواهم.\r\nپس هر روز ، درسى مى ‏گفت تا سه سال گذشت. بعد از آن معلوم شد كه آن پیر نورانى ، خضر (ع) بود و این نعمت و توفیق ، به بركت رضا و دعاى مادر یافته است.\r\n"},{"id":1956,"category_id":2,"category_code":"s2","source_id":123,"title":"موتور گازی و بنز","content":"یارو نشسته بوده پشت بنز آخرین سیستم، داشته صد و هشتاد تا تو اتوبان میرفته، یهو میبینه یک موتور گازی ازش جلو زد!\r\nخیلی شاکی میشه، پا رو میگذاره رو گاز، با سرعت دویست از بغل موتوره رد میشه.\r\nیک مدت واسه خودش خوش و خرم میره، یهو میبینه دوباره موتور گازیه قیییییژ ازش جلو زد!\r\nدیگه پاک قاط میزنه، پا رو تا ته میگذاره رو گاز، با دویست و چهل تا از موتوره جلو میزنه.\r\nهمینجور داشته با آخرین سرعت میرفته، یهو میبینه، موتور گازیه مثل تیر از بغلش رد شد!!\r\nطرف کم میاره، راهنما میزنه کنار به موتوریه هم علامت میده بزنه کنار.\r\nخلاصه دوتایی وامیستن کنار اتوبان، یارو پیاده میشه، میره جلو موتوریه، میگه: آقا تو خدایی! من مخلصتم، فقط بگو چطور با این موتور گازی کل مارو خوابوندی؟!\r\nموتوریه با رنگ پریده، نفس زنان میگه: والله ... داداش.... خدا پدرت رو بیامرزه که واستادی... آخه ... کش شلوارم گیر کرده به آینه بغلت !!!!\r\n"},{"id":1957,"category_id":2,"category_code":"s2","source_id":124,"title":"حقوق بازنشستگی","content":"هنوز هم بعد از این همه سال، چهره‌ی ویلان را از یاد نمی‌برم. در واقع، در طول سی سال گذشته، همیشـه روز اول مـاه کـه حقوق بازنشستگی را دریافت می‌کنم، به یاد ویلان می‌افتم …\r\nویلان پتی اف، کارمند دبیرخانه‌ی اداره بود. از مال دنیا، جز حقوق اندک کارمندی هیچ عایدی دیگری نداشت. ویلان، اول ماه که حقوق می‌گرفت و جیبش پر می‌شد، شروع می‌کرد به حرف زدن …\r\n\r\nروز اول ماه و هنگامی‌که که از بانک به اداره برمی‌گشت، به‌راحتی می‌شد برآمدگی جیب سمت چپش را تشخیص داد که تمام حقوقش را در آن چپانده بود.\r\nویلان از روزی که حقوق می‌گرفت تا روز پانزدهم ماه که پولش ته می‌کشید، نیمی از ماه سیگار برگ می‌کشید، نیمـی از مـاه مست بود و سرخوش..\r\nمن یازده سال با ویلان هم‌کار بودم. بعدها شنیدم، او سی سال آزگار به همین نحو گذران روزگار کرده است. روز آخر کـه من از اداره منتقل می‌شدم، ویلان روی سکوی جلوی دبیرخانه نشسته بود و سیگار برگ\r\nمی‌کشید. به سراغش رفتم تا از او خداحافظی کنم.\r\nکنارش نشستم و بعد از کلی حرف مفت زدن، عاقبت پرسیدم که چرا سعی نمی کند زندگی‌اش را سر و سامان بدهد تا از این وضع نجات پیدا کند؟\r\nهیچ وقت یادم نمی‌رود. همین که سوال را پرسیدم، به سمت من برگشت و با چهره‌ای متعجب، آن هم تعجبی طبیعی و اصیل پرسید: کدام وضع؟\r\nبهت زده شدم.. همین‌طور که به او زل زده بودم، بدون این‌که حرکتی کنم، ادامه دادم:\r\nهمین زندگی نصف اشرافی، نصف گدایی!!!\r\nویلان با شنیدن این جمله، همان‌طور که زل زده بود به من، ادامه داد:\r\nتا حالا سیگار برگ اصل کشیدی؟\r\nگفتم: نه !\r\nگفت: تا حالا تاکسی دربست گرفتی؟\r\nگفتم: نه !\r\nگفت: تا حالا به یک کنسرت عالی رفتی؟\r\nگفتم: نه !\r\nگفت: تا حالا غذای فرانسوی خوردی؟\r\nگفتم: نه !\r\nگفت: تا حالا یه هفته مسکو موندی خوش بگذرونی؟\r\nگفتم: نه !\r\nگفت: خاک بر سرت، تا حالا زندگی کردی؟\r\nبا درماندگی گفتم: آره، …. نه، … نمی دونم !!!\r\nویلان همین‌طور نگاهم می‌کرد. نگاهی تحقیرآمیز و سنگین ….\r\nحالا که خوب نگاهش می‌کردم، مردی جذاب بود و سالم. به خودم که آمدم، ویلان جلویم ایستاده بود و تاکسی رسیده بود. ویلان سیگار برگی تعارفم کرد و بعد جمله‌ای را گفت. جمله‌ای را گفت که مسیر\r\nزندگی‌ام را به کلی عوض کرد.\r\nویلان پرسید: می‌دونی تا کی زنده‌ای؟\r\nجواب دادم: نه !\r\nویلان گفت: پس سعی کن دست کم نصف ماه رو زندگی کنی.\r\n"},{"id":1958,"category_id":2,"category_code":"s2","source_id":125,"title":"متشکرم","content":"همين چند روز پيش، \"يوليا واسيلي اونا\" پرستار بچه‌هايم را به اتاقم دعوت كردم تا با او تسويه حساب كنم.\r\nبه او گفتم: - بنشينيد يوليا.مي‌دانم كه دست و بالتان خالي است، اما رو در بايستي داريد و به زبان نمي‌آوريد. ببينيد، ما توافق كرديم كه ماهي سي روبل به شما بدهم. اين طور نيست؟\r\n- چهل روبل.\r\n- نه من يادداشت كرده‌ام. من هميشه به پرستار بچه‌هايم سي روبل مي‌دهم. حالا به من توجه كنيد. شما دو ماه براي من كار كرديد.\r\n- دو ماه و پنج روز دقيقا.\r\n- دو ماه. من يادداشت كرده‌ام، كه مي‌شود شصت روبل. البته بايد نه تا يكشنبه از آن كسر كرد.همان‌طور كه مي‌دانيد يكشنبه‌ها مواظب \"كوليا\" نبوده‌ايد و براي قدم زدن بيرون مي‌رفتيد. به اضافه سه روز تعطيلي...\r\n\"يوليا واسيلي اونا\" از خجالت سرخ شده بود و داشت با چين‌هاي لباسش‌ بازي مي‌كرد ولي صدايش در نمي‌آمد.\r\n- سه تعطيلي. پس ما دوازده روبل را براي سه تعطيلي و نه يكشنبه مي‌‌گذاريم كنار... \"كوليا\" چهار روز مريض بود. آن روزها از او مراقبت نكرديد و فقط مواظب \"وانيا\" بوديد. فقط \"وانيا\" و ديگر اين كه سه روز هم شما دندان درد داشتيد و همسرم به شما اجازه داد بعد از شام دور از بچه‌ها باشيد. دوازده و هفت مي‌شود نوزده. تفريق كنيد. آن مرخصي‌ها، آهان شصت منهاي نوزده روبل مي‌ماند چهل و يك روبل. درسته؟\r\nچشم چپ يوليا قرمز و پر از اشك شده بود. چانه‌اش مي‌لرزيد. شروع كرد به سرفه كردن‌هاي عصبي. دماغش را بالا كشيد و چيزي نگفت.\r\n-... و بعد، نزديك سال نو، شما يك فنجان و يك نعلبكي شكستيد. دو روبل كسر كنيد. فنجان با ارزش‌تر از اينها بود. ارثيه بود. اما كاري به اين موضوع نداريم. قرار است به همه حساب‌ها رسيدگي كنيم و... اما موارد ديگر... به خاطر بي‌مبالاتي شما \"كوليا\" از يك درخت بالا رفت و كتش را پاره كرد. ده تا كسر كنيد... همچنين بي‌توجهي شما باعث شد كلفت‌خانه با كفش‌هاي \"وانيا\" فرار كند. شما مي‌بايست چشم‌هايتان را خوب باز مي‌كرديد. براي اين كار مواجب خوبي مي‌گيريد. پس پنج تاي ديگر كم مي‌كنيم... دردهم ژانويه ده روبل از من گرفتيد...\r\nيوليا نجوا كنان گفت:\r\n- من نگرفتم.\r\n- اما من يادداشت كرده‌ام... خيلي خوب. شما شايد... از چهل و يك روبل، بيست و هفت تا كه برداريم، چهارده تا باقي مي‌ماند.\r\nچشم‌هايش پر از اشك شده بود و چهره‌عرق كرده‌اش رقت‌آور به نظر مي‌رسيد. در اين حال گفت:\r\n- من فقط مقدار كمي گرفتم... سه روبل از همسرتان گرفتم نه بيشتر.\r\n- ديدي چه طور شد؟ من اصلا آن سه روبل را از قلم انداخته بودم. سه تا از چهارده تا كم مي‌كنيم. مي‌شود يازده تا... بفرمائيد، سه تا، سه تا، سه تا، يكي و يكي.\r\nيازده روبل به او دادم. آنها را با انگشتان لرزان گرفت و توي جيبش ريخت و به آهستگي گفت:\r\n- متشكرم.\r\nجا خوردم. در حالي كه سخت عصباني شده بودم شروع كردم به قدم زدن در طول و عرض اتاق و پرسيدم:\r\n- چرا گفتي متشكرم؟\r\n- به خاطر پول.\r\n- يعني تو متوجه نشدي كه دارم سرت كلاه مي‌گذارم و دارم پولت را مي‌خورم!؟ تنها چيزي كه مي‌تواني بگويي همين است كه متشكرم؟!\r\n- در جاهاي ديگر همين قدرهم ندادند.\r\n- آنها به شما چيزي ندادند! خيلي خوب. تعجب ندارد. من داشتم به شما حقه مي‌زدم. يك حقه كثيف. حالا من به شما هشتاد روبل مي‌دهم. همه‌اش در اين پاكت مرتب چيده شده، بگيريد... اما ممكن است كسي اين قدر نادان باشد؟ چرا اعتراض نكرديد؟چرا صدايتان در نيامد؟ ممكن است كسي توي دنيا اينقدر ضعيف باشد؟\r\nلبخند تلخي زد كه يعني \"بله، ممكن است.\"\r\nبه خاطر بازي بي‌رحمانه‌اي كه با او كرده‌ بودم عذر خواستم و هشتاد روبلي را كه برايش خيلي غير منتظره بود به او پرداختم. باز هم چند مرتبه با ترس گفت:\r\n- متشكرم. متشكرم.\r\nبعد از اتاق بيرون رفت و من مات و مبهوت مانده بودم كه در چنين دنيايي چه راحت مي‌شود زورگو بود.\r\nمات و مبهوت مانده بودم كه در چنين دنيايي چه راحت مي توان زورگو بود!\r\n"},{"id":1959,"category_id":2,"category_code":"s2","source_id":126,"title":"ناخدا یا مهندس؟","content":"يکي از روزها ناخداي يک کشتي و سرمهندس آن در اين باره بحث مي کردند که در کار اداره و هدايت کشتي کدام يک نقش مهم تري دارند.\r\nبحث به شدت بالا گرفت و ناخدا پيشنهاد کرد که يک روز جايشان را با هم عوض کنند. قرار گذاشتند که سرمهندس سکان کشتي را به دست بگيرد و ناخدا به اتاق مهندس کشتي برود.\r\nهنوز چند ساعتي از جابه جايي نگذشته بود که ناخدا عرق ريزان با سر و وضعي کثيف و روغن مالي بالا آمد و گفت: «مهندس سري به موتورخانه بزن. هرقدر تلاش مي کنم، کشتي حرکت نمي کند.»\r\nسرمهندس فرياد کشيد: «البته که حرکت نمي کند، کشتي به گل نشسته است.»\r\n"},{"id":1960,"category_id":2,"category_code":"s2","source_id":127,"title":"عطر شکلات","content":"پیرمردی در بستر مرگ بود. در لحظات دردناک مرگ، ناگهان بوی عطر شکلات محبوبش از طبقه پایین به مشامش رسید. او تمام قدرت باقیمانده اش را جمع کرد و از جایش بلند شد.\r\nهمانطور که به دیوار تکیه داده بود آهسته آهسته از اتاقش خارج شد و با هزار مکافات خود را به پایین پله ها رساند و نفس نفس زنان به در آشپزخانه رسید و به درون آن خیره شد.\r\nاو روی میز ظرفی حاوی صدها تکه شکلات محبوب خود را دید و با خود فکر کرد یا در بهشت است و یا اینکه ... همسر وفادارش آخرین کاری که ثابت کند چقدر شیفته و شیدای اوست را انجام داده است و بدین ترتیب او این جهان را چون مردی سعادتمند ترک می کند. او آخرین تلاش خود را نیز به کار بست و خودش را به روی میز انداخت و یک تکه از شکلات ها را به دهانش گذاشت و با طعم خوش آن احساس کرد جانی دوباره گرفته است.\r\nسپس مجددا دست لرزان خود را به سمت ظرف برد که ناگهان همسرش با قاشق روی دست او زد و گفت: دست نزن، آنها را برای مراسم عزاداری درست کرده ام!\r\n"},{"id":1961,"category_id":2,"category_code":"s2","source_id":128,"title":"آرزوی دانه ی کوچک","content":"دانه کوچک بود و کسی او را نمی‌دید. سال‌های سال گذشته بود و او هنوز همان دانه کوچک بود.\r\nدانه دلش می‌خواست به چشم بیاید، اما نمی‌دانست چگونه. گاهی سوار باد می‌شد و از جلوی چشمها می‌گذشت. گاهی خودش را روی زمینه روشن برگها می‌انداخت و گاهی فریاد می‌زد و می‌گفت:\r\n\"من هستم، من اینجا هستم، تماشایم کنید .”\r\nاما هیچکس جز پرنده‌ها‌یی که قصد خوردنش را داشتند یا حشره‌هایی که به چشم آذوقه زمستان به او نگاه می‌کردند، به او توجهی نمی‌کرد.\r\nدانه خسته بود از این زندگی؛ از این‌ همه گم‌ بودن و کوچکی خسته بود. یک روز رو به خدا کرد و گفت:\r\n\"نه، این رسمش نیست. من به چشم هیچ‌کس نمی‌آیم. کاشکی کمی بزرگتر، کمی بزرگتر مرا می‌آفریدی.”\r\nخدا گفت:\"اما عزیز کوچکم! تو بزرگی، بزرگتر از آنچه فکر می‌کنی. حیف که هیچ وقت به خودت فرصت بزرگ‌شدن ندادی. رشد ماجرایی است که تو از خودت دریغ کرده‌ای. راستی یادت باشد تا وقتی که می‌خواهی به چشم بیایی، دیده نمی‌شوی. خودت را از چشم‌ها پنهان کن تا دیده شوی.”\r\nدانه کوچک معنی حرف‌های خدا را خوب نفهمید، اما رفت زیر خاک و خودش را پنهان کرد.\r\nسال‌ها بعد دانه کوچک، سپیداری بلند و با شکوه بود که هیچکس نمی‌توانست ندیده‌اش بگیرد. سپیداری که به چشم همه می‌آمد.\r\n"},{"id":1962,"category_id":2,"category_code":"s2","source_id":129,"title":"دلقک","content":"روزی مردی نزد پزشک روانشناس معروف شهر خود رفت. وقتی پزشک او را دید دلیل آمدنش را پرسید، مرد رو به پزشک کردو از غم های بزرگی که در دل داشت برای دکتر تعریف کرد.\r\nمرد گفت: دلم از آدم ها گرفته از دروغگویی ها، از دورویی ها، از نامردی ها، از تنهایی، از خیلی ها از… مرد ادامه داد و گفت: از این زندگی خسته شده ام، از این دنیا بیزارم ولی نمی دانم چه باید کنم، نمی دانم غم هایم را پیش چه کسی مداوا کنم\r\nپزشک به مرد گفت: من کسی را می شناسم که می تواند مشکل تورا حل نمایید. به فلان سیرک برو او دلقک معروف شهر است. کسی است که همه را شاد می کند، همه را می خنداند، مطمئنم اگر پیش او بروی مشکلت حل می شود. هیچ کسی با وجود او غمگین نخواهد بود.\r\nمرد از پزشک تشکر کرد و در حالی که از مطب پزشک خارج می شد رو به پزشک کرد و گفت: مشکل اینجاست که آن دلقک خود منم...\r\n"},{"id":1963,"category_id":2,"category_code":"s2","source_id":130,"title":"دیوانه ی باهوش","content":"مردی در هنگام رانندگی، درست جلوی حیاط یک تیمارستان پنچر شد و مجبورشد همان جا به تعویض لاستیک بپردازد.\r\nهنگامی‌که سرگرم این کار بود، ماشین دیگری به سرعت از روی مهره های چرخ که در کنار ماشین بودند گذشت و آن‌ها را به درون جوی آب انداخت و آب مهره‌ها را برد.\r\nمرد حیران مانده بود که چه کار کند.\r\nتصمیم گرفت که ماشینش را همان جا رها کند و برای خرید مهره چرخ برود.\r\nدر این حین، یکی از دیوانه‌ها که از پشت نرده‌های حیاط تیمارستان نظاره گر این ماجرا بود، او را صدا زد و گفت:\r\nاز ٣ چرخ دیگر ماشین، از هر کدام یک مهره بازکن و این لاستیک را با ٣ مهره ببند و برو تا به تعمیرگاه برسی.\r\nآن مرد اول توجهی به این حرف نکرد ولی بعد که با خودش فکر کرد دید راست می‌گوید و بهتر است همین کار را بکند.\r\nپس به راهنمایی او عمل کرد و لاستیک زاپاس را بست.\r\nهنگامی‌که خواست حرکت کند رو به آن دیوانه کرد و گفت:\r\nخیلی فکر جالب و هوشمندانه ای داشتی.\r\nپس چرا توی تیمارستان انداختنت؟\r\nدیوانه لبخندی زد و گفت:\r\nمن اینجام چون دیوانه ام. ولی احمق که نیستم...\r\n"},{"id":1964,"category_id":2,"category_code":"s2","source_id":131,"title":"قلب کوچک","content":"مادربزرگم می‌گوید: قلب آدم نباید خالی بماند. اگر خالی بماند، ‌مثل گلدان خالی زشت است و آدم را اذیت می‌کند.\r\nمن قلب کوچولویی دارم؛ خیلی کوچولو؛ خیلی خیلی کوچولو.\r\nمادربزرگم می‌گوید: قلب آدم نباید خالی بماند. اگر خالی بماند، ‌مثل گلدان خالی زشت است و آدم را اذیت می‌کند.\r\nبرای همین هم، مدتی ست دارم فکر می‌کنم این قلب کوچولو را به چه کسی باید بدهم؛ یعنی، راستش، چطور بگویم؟ ‌دلم می‌خواهد تمام این قلب کوچولو را مثل یک خانه قشنگ کوچولو، به کسی بدهم که خیلی خیلی دوستش دارم...\r\nیا... نمی‌دانم...\r\nکسی که خیلی خوب است، کسی که واقعا حقش است توی قلب خیلی کوچولو و تمیز من خانه داشته باشد.\r\nخب راست می‌گویم دیگر . نه؟\r\nپدرم می‌گوید:‌ قلب، مهمان خانه نیست که آدم‌ها بیایند، دو سه ساعت یا دو سه روز توی آن بمانند و بعد بروند. قلب، لانه‌ی گنجشک نیست که در بهار ساخته بشود و در پاییز باد آن را با خودش ببرد...\r\nقلب، راستش نمی‌دانم چیست، اما این را می‌دانم که فقط جای آدم‌های خیلی خیلی خوب است. برای همیشه ...\r\nخب... بعد از مدت‌ها که فکر کردم، تصمیم گرفتم قلبم را بدهم به مادرم، تمام قلبم را تمام تمامش را بدهم به مادرم، و این کار را هم کردم اما...\r\nاما وقتی به قلبم نگاه کردم، دیدم، با این که مادر خوبم توی قلبم جا گرفته، خیلی هم راحت است، باز هم نصف قلبم خالی مانده...\r\nخب معلوم است. من از اول هم باید عقلم می‌رسید و قلبم را به هر دوتاشان می‌دادم؛ به پدرم و مادرم.\r\nپس، همین کار را کردم.\r\nبعدش می‌دانید چطور شد؟ بله، درست است. نگاه کردم و دیدم که بازهم، توی قلبم، مقداری جای خالی مانده...\r\nفورا تصمیم گرفتم آن گوشه‌ خالی قلبم را بدهم به چند نفر؛ چند نفر که خیلی دوستشان داشتم؛ و این کار را هم کردم:\r\nبرادر بزرگم، خواهر کوچکم، پدر بزرگم، مادر بزرگم، یک دایی مهربان و یک عموی خوش اخلاقم را هم توی قلبم جا دادم...\r\nفکر کردم حالا دیگر توی قلبم حسابی شلوغ شده... این همه آدم، توی قلب به این کوچکی، مگر می‌شود؟\r\nاما وقتی نگاه کردم،‌خدا جان! می‌دانید چی دیدم؟\r\nدیدم که همه این آدم‌ها، درست توی نصف قلبم جا گرفته‌اند؛ درست نصف!\r\nبا اینکه خیلی راحت هم ولو شده بودند و می‌گفتند و می‌خندیدند. و هیچ گله‌یی هم از تنگی جا نداشتند...\r\nمن وقتی دیدم همه‌ی آدم‌های خوب را دارم توی قلبم جا می‌دهم، سعی کردم این عموی پدرم را هم ببرم توی قلبم و یک گوشه بهش جا بدهم... اما... جا نگرفت... هرچی کردم جا نگرفت...\r\nدلم هم سوخت... اما چکار کنم؟ جا نگرفت دیگر. تقصیر من که نیست حتما تقصیر خودش است. یعنی، راستش، هر وقت که خودش هم، با زحمت و فشار، جا می‌گرفت، صندوق بزرگ پول‌هایش بیرون می‌ماند و او، دَوان دَوان از قلبم می‌آمد بیرون تا صندوق را بردارد...\r\n"},{"id":1965,"category_id":2,"category_code":"s2","source_id":132,"title":"حتما\" دلیلی دارد...","content":"مردی تاجر در حیاط قصرش انواع مختلف درختان و گیاهان و گلها را کاشته و باغ بسیار زیبایی را به وجود آورده بود. هر روز بزرگترین سرگرمی و تفریح او گردش در باغ و لذت بردن از گل و گیاهان آن بود.\r\nتا این که یک روز به سفر رفت. در بازگشت، در اولین فرصت به دیدن باغش رفت.\r\nاما با دیدن آنجا، سر جایش خشکش زد...\r\nتمام درختان و گیاهان در حال خشک شدن بودند ، رو به درخت صنوبر که پیش از این بسیار سر سبز بود، کرد و از او پرسید که چه اتفاقی افتاده است؟\r\nدرخت به او پاسخ داد: من به درخت سیب نگاه می کردم و باخودم گفتم که من هرگز نمی توانم مثل او چنین میوه هایی زیبایی بار بیاورم و با این فکر چنان احساس نارحتی کردم که شروع به خشک شدن کردم...\r\nمرد بازرگان به نزدیک درخت سیب رفت، اما او نیز خشک شده بود...!\r\nعلت را پرسید و درخت سیب پاسخ داد: با نگاه به گل سرخ و احساس بوی خوش آن، به خودم گفتم که من هرگز چنین بوی خوشی از خود متصاعد نخواهم کرد و با این فکر شروع به خشک شدن کردم.\r\nاز آنجایی که بوته ی یک گل سرخ نیز خشک شده بود علت آن پرسیده شد، او چنین پاسخ داد: من حسرت درخت افرا را خوردم، چرا که من در پاییز نمی توانم گل بدهم. پس از خودم نا امید شدم و آهی بلند کشیدم. همین که این فکر به ذهنم خطور کرد، شروع به خشک شدن کردم.\r\nمرد در ادامه ی گردش خود در باغ متوجه گل بسیار زیبایی شد که در گوشه ای از باغ روییده بود.\r\nعلت شادابی اش را جویا شد. گل چنین پاسخ داد: ابتدا من هم شروع به خشک شدن کردم، چرا که هرگز عظمت درخت صنوبر را که در تمام طول سال سر سبزی خود را حفظ می کرد نداشتم، و از لطافت و خوش بویی گل سرخ نیز برخوردار نبودم، با خودم گفتم: اگر مرد تاجر که این قدر ثروتمند، قدرتمند و عاقل است و این باغ به این زیبایی را پرورش داده است می خواست چیزی دیگری جای من پرورش دهد، حتماً این کار را می کرد. بنابراین اگر او مرا پرورش داده است، حتماً می خواسته است که من وجود داشته باشم. پس از آن لحظه به بعد تصمیم گرفتم تا آنجا که می توانم زیباترین موجود باشم... \r\n"},{"id":1966,"category_id":2,"category_code":"s2","source_id":133,"title":"مگس نباشیم!","content":"دیروز پس از یک هفته که مگسی در خانه ام میگشت، جنازه اش را روی میز کارم پیدا کردم...\r\nدیروز پس از یک هفته که مگسی در خانه ام میگشت، جنازه اش را روی میز کارم پیدا کردم.\r\nیک هفته بود که با هم زندگی میکردیم. شبها که دیر میخوابیدم، تا آخرین دقیقه ها دور سرم میچرخید. صبح ها اگر دیر از خواب بیدار می شدم، خبری از او هم نبود. شاید او هم مانند من، سر بر کتابی گذاشته و خوابیده بود.\r\nدر گشت و گذار اینترنتی، متوجه شدم که عمر بسیاری از مگس های خانگی در دمای معمولی حدود ۷ تا ۲۱ روز است.\r\nبا خودم... شمردم. حدود ۷ روز بود که این مگس را میدیدم. این مگس قسمت اصلی یا شاید تمام عمرش را در خانه ی من زندگی کرده بود. احساسم نسبت به او تغییر کرد. به جسدش که بیجان روی میز افتاده بود، خیره شده بودم.\r\nغصه خوردم. این مگس چه دنیای بزرگی را از دست داده است. لابد فکر میکرده «دنیا» یک خانه ی ۵۰ متری است که روزها نور از «ماوراء» به درون آن می تابد و شبها، تاریکی تمام آن را فرا میگیرد. شاید هم مرا بلایی آسمانی میدیده که به مکافات خطاهایش، بر او نازل گشته ام!\r\nشاید نسبت آن مگس به خانه ی من، چندان با نسبت من به عالم، متفاوت نباشد.\r\n\r\nمن مگس های دیگر خانه ام را با این دقت نگاه نکرده ام. شاید در میان آنها هم رقابت برای اینکه بر کدام طبقه کتابخانه بنشینند وجود داشته.\r\nشاید در میان آنها هم مگس دانشمندی بوده است که به دیگران «تکامل» می آموخته و میگفته که ما قبل از اینکه «بال» در بیاوریم، شبیه این انسانهای بدبخت بوده ایم.\r\nشاید به تناسخ هم اعتقاد داشته باشند و فکر کنند در زندگی قبلی انسانهایی بوده اند که در اثر کار نیک، به مقام «مگسی» نائل آمده اند.\r\nشاید برخی از آنها فیلسوف بوده باشند. شاید در باره فلسفه ی زندگی مگسی، حرف ها گفته و شنیده باشند.\r\nشاید برخی از آنها تمام عمر را با حسرت مهاجرت به خانه ی همسایه سر کرده باشند.\r\nمگسی را یادم میآید که تمام یک هفته ی عمرش را پشت شیشه نشسته بود به امید اینکه روزی درها باز شود و به خانه ی همسایه مهاجرت کند…\r\nمگس دیگری را یادم آمد که تمام هفت روز عمرش را بی حرکت بر سقف دستشویی نشسته بود. تو گویی که فکر میکرد با برخواستن از سقف، سقوط خواهد کرد. یا شاید از ترس اینکه بیرون این اتاق بسته ی محبوس، جهنمی برپاست…\r\nبالای سر مگس مرده نشستم و با او حرف زدم:\r\nکاش میدانستی که دنیا بسیار بزرگ تر از این خانه ی کوچک است.\r\nکاش جرأت امتحان کردن دنیاهای جدید را داشتی.\r\nکاش تمام عمر هفت روزه ی خود را بر نخستین دانه ی شیرینی که روی میز من دیدی، صرف نمیکردی.\r\nکاش لحظه ای از بال زدن خسته نمیشدی، وقتی که قرار بود برای همیشه اینجا روی این میز، متوقف شوی.\r\nآن مگس را روی میزم نگاه خواهم داشت تا با هر بار دیدنش به خاطر بیاورم که:\r\n\r\nعمر من در مقایسه با عمر جهان از عمر این مگس نیز کوتاه تر است. شاید در خاطرم بماند که دنیا، بزرگتر و پیچیده تر از چیزی است که می بینم و می فهمم. شاید در خاطرم بماند که بر روی نخستین شیرینی زندگی، ماندگار نشوم.\r\nنمیخواهم مگس گونه زندگی کنم. بر می خیزم. دنیا را میگردم و به خاطر خواهم سپرد که عمر کوتاه است و دنیا، بزرگ.\r\nبزرگتر و متنوع تر از چیزی که چشمانم، به من نشان میدهد…\r\nنگاه کردن به جلو راحت‌تر از تجزیه و تحلیل کردن گذشته است، برای اینکه شما بیشتر تمایل دارید چیزهای جدید را تجربه کنید. اما هم اکنون شما به خاطر اینکه از زمان حال فرارکنید روی آینده تمرکز کرده‌اید. زمان کافی برای کار و فعالیت‌های جدید خود اختصاص بدهید و قبل از اینکه دیر بشود کارهایی که لازم است را انجام دهید.\r\n"},{"id":1967,"category_id":2,"category_code":"s2","source_id":134,"title":"اسب زیبا","content":"مردی، اسب اصیل و بسیار زیبایی داشت که توجه هر بیننده ای را به خود جلب می کرد. همه آرزوی تملک آن را داشتند. بادیه نشین ثروتمندی پیشنهاد کرد که اسب را با دو شتر معاوضه کند، اما مرد موافقت نکرد.\r\nحتی حاضر نبود اسب خود را با تمام شترهای مرد بادیه نشین تعویض کند. بادیه نشین با خود فکر کرد: حالا که او حاضر نیست اسب خود را با تمام دارایی من معاوضه کند، باید به فکر حیله ای باشم. روزی خود را به شکل یک گدا درآورد و در حالی که تظاهر به بیماری می کرد، در حاشیه جاده ای دراز کشید. او می دانست که مرد با اسب خود از آنجا عبور می کند. همین اتفاق هم افتاد... مرد با دیدن آن گدای رنجور، سرشار از همدردی، از اسب خود پیاده شد به طرف مرد بیمار و فقیر رفت و پیشنهاد کرد که او را نزدیک پزشک ببرد.\r\nمرد گدا ناله کنان جواب داد: من فقیرتر از آن هستم که بتوانم راه بروم. روزهاست که چیزی نخورده ام و نمی توانم از جا بلند شوم. دیگر قدرت ندارم. مرد به او کمک کرد که سوار اسب شود. به محض اینکه مرد گدا روی زین نشست، پاهای خود را به پهلوهای اسب زد و به سرعت دور شد. مرد متوجه شد که گول بادیه نشین را خورده است. فریاد زد: صبر کن! می خواهم چیزی به تو بگویم. بادیه نشین که کنجکاو شده بود کمی دورتر ایستاد. مرد گفت: تو اسب مرا دزدیدی. دیگر کاری از دست من برنمی آید، اما فقط کمی وجدان داشته باش و یک خواهش مرا برآورده کن: «برای هیچ کس تعریف نکن که چگونه مرا گول زدی...»\r\nبادیه نشین تمسخرکنان گفت: چرا باید این کار را انجام دهم؟! مرد گفت: چون ممکن است زمانی بیمار درمانده ای کنار جاده ای افتاده باشد. اگر همه این جریان را بشنوند، دیگر کسی به او کمک نخواهد کرد...\r\n"},{"id":1968,"category_id":2,"category_code":"s2","source_id":135,"title":"چقدر به هم بدهکاریم؟","content":"ایستاده‌ام توی صف ساندویچی که ناهار امروزم را سرپایی و در اسرع وقت بخورم و برگردم شرکت. از مواقعی که خوردن، فقط برای سیر شدن است و قرار نیست از آن چیزی که می‌جوی و می‌بلعی لذت ببری، بیزارم. به اعتقاد من حتی وقتی درب باک ماشین را باز می‌کنی تا معده‌اش را از بنزین پر کنی، ماشین چنان لذتی می‌برد و چنان کیفی می‌کند که اگر می‌توانست چیزی بگوید، حداقلش یک \"آخیش!\" یا \"به به!\" بود. حالا من ایستاده‌ام توی صف ساندویچی،‌ فقط برای این که خودم را سیر کنم و بدون آخیش و به به برگردم سر کارم.\r\nنوبتم که می‌شود فروشنده با لبخندی که صورتش را دوست داشتنی کرده سفارش غذا را می‌گیرد و بدون آن که قبضی دستم بدهد می‌رود سراغ نفر بعدی. می‌ایستم کنار، زیر سایهء یک درخت و به جمعیتی که جلوی این اغذیه فروشی کوچک جمع شده‌اند نگاه می‌کنم، که آیا اینها هم مثل من فقط برای سیر شدن آمده‌اند یا واقعا از خوردن یک ساندویچ معمولی لذت می‌برند. آقای فروشندهء خندان صدایم می‌کنم و غذایم را می‌دهد، بدون آن که حرفی از پول بزند.\r\nبا عجله غذا را، سرپا و زیر همان درخت، می‌خورم. انگار که قرار است برگردم شرکت و شاتل هوا کنم، انگار که اگر چند دقیقه دیر برسم کل پروژه‌های این مملکت از خواب بیدار و بعدش به اغما می‌روند. می‌روم روبروی آقای فروشندهء خندان که در آن شلوغی فهرست غذا به همراه اضافاتی که خورده‌ام را به خاطر سپرده است. می‌شود ٧٢٠٠ تومان. یک ١٠ هزار تومانی می‌دهم و منتظر باقی پولم می‌شوم. ٣٠٠٠ هزار تومان بر می‌گرداند. می‌گویم ٢٠٠ تومانی ندارم. می‌گوید اندازهء ٢٠٠ تومان لبخند بزن! خنده‌ام می‌گیرد. خنده‌اش می‌گیرد و می‌گوید: \"این که بیشتر شد. حالا من ١٠٠ به شما بدهکارم!\" تشکر و خداحافظی می‌کنم و موقع رفتن با او دست می‌دهم.\r\nانگار هنوز هم از این آدم‌ها پیدا می‌شوند، آدم‌هایی که هنوز معتقدند لبخند زدن زیبا و لبخند گرفتن ارزشمند است. لبخند زنان دستانم را می‌کنم توی جیبم و آهسته به سمت شرکت بر می‌گردم و توی راه بازگشت آرام زیر لب می‌گویم: \"آخیش! به به!\"\r\n"},{"id":1969,"category_id":2,"category_code":"s2","source_id":136,"title":"سوال قورباغه ها","content":"\r\nمارها قورباغه ها را می خوردند و قورباغه ها غمگین بودند. قورباغه ها به لک لک ها شکایت کردند. لک لک ها مارها را خوردند و قورباغه ها شادمان شدند. لک لک ها گرسنه ماندند و شروع کردند به خوردن قورباغه ها.\r\nقورباغه ها دچار اختلاف دیدگاه شدند، عده ای از آنها با لک لک ها کنار آمدند و عده ای دیگر خواهان بازگشت مارها شدند. مارها بازگشتند و همپای لک لک ها شروع به خوردن قورباغه ها کردند.\r\nحالا دیگر قورباغه ها متقاعد شده اند که برای خورده شدن به دنیا می آیند. تنها یک مشکل برای آنها حل نشده باقی مانده است و آن اینکه نمی دانند توسط دوستانشان خورده می شوند یا دشمنانشان!؟\r\n"},{"id":1970,"category_id":2,"category_code":"s2","source_id":137,"title":"اقتضای طبیعت","content":"شخصی عقربی را دید که در آب برای نجات خویش دست و پا میزند .آن شخص به قصد کمک دستش را به طرف عقرب دراز کرد اما عقرب تلاش کرد تا نیشش بزند !\r\nبا این وجود مرد هنوز تلاش میکرد تا عقرب را از آب بیرون بیاورد اما عقرب دوباره سعی کرد او را نیش بزند !\r\nمردی در آن نزدیکی به او گفت : چرا از نجات عقربی که مدام نیش میزند دست نمیکشی ؟!\r\nآن مرد گفت : عقرب به اقتضای طبیعتش نیش میزند. طبیعت عقرب نیش زدن است و طبیعت من عشق ورزیدن ...\r\nچرا باید از طبیعت خود که عشق ورزیدن است فقط به علت این که طبیعت عقرب نیش زدن است دست بکشم ؟!\r\nهیچگاه از عشق ورزیدن دست نکش همیشه خوب باش حتی اگر اطرافیانت نیشت بزنند ...\r\n"},{"id":1971,"category_id":2,"category_code":"s2","source_id":138,"title":"مخلوط ها","content":"معلم بر روی تابلو رنگ رفته و شکسته کلاس که به دیواری تکیه داده شده بود نوشت\r\nمخلوط ها\r\n\r\nو بعد دو لیوان که یکی آب نمک و دیگری نخودچی و کشمش بود را به دانش آموزان نشان داد و از آنها خواست که به اجزای این دو مخلوط دقت کرده و محتویات دو ظرف را با هم مقایسه کنند.\r\nبعد از مدتی نماینده ی کلاس هر دو لیوان را روی میز معلم گذاشت.یکی از لیوان ها کاملا خالی بود و دیگری همچنان پر از آب و نمک بود. معلم درس را تمام کرد و زنگ خورد\r\nجلسه ی بعد معلم از دانش آموزان پرسید: کسی از درس قبل اشکال یا سوالی ندارد؟\r\nرسول دست گرفت و سوال کرد(خانم ما مخلوط ناهمگن رانفهمیدیم!!!!!)\r\nمعلم دوباره تعریف آن را بر روی تابلو نوشت. رسول سری تکان داد و نشست\r\nمرضیه بی آنکه اجازه بگیرد بلند شد وگفت: (خانم ما مثال مخلوط ناهمگن را نفهمیدیم)\r\nمعلم با مهربانی چند مثال جدید زد و مرضیه با نا امیدی نشست\r\nحسن از آخر کلاس گفت خانم اجازه می شود همان مثال مخلوط ناهمگن جلسه ی قبل را دوباره تکرار کنید.\r\nعصبانیت در چهره معلم پدیدار شد .ابروهایش را در هم کشید و گفت:چرا سوال تکراری می پرسی من این قسمت را چندین بار است که دارم توضیح می دهم .چرا حواست را جمع نمی کنی؟\r\nحسن که گونه هایش قرمز شده بود .سرش را پایین انداخت و زیر لب گفت: خانم آخه مثال مخلوط ناهمگن خیلی خوشمزه بود!!!\r\nمعلم که تازه به دلیل سوالات دانش آموزانش پی برده بود.لحظه ای سکوت کرد .بغضی در گلویش نشست ولی پرده ای از لبخند برلبانش آویخت و به دانش آموزان معصوم و فقیر خود نگاهی انداخت\r\nو همانجا تصمیم گرفت از جلسه بعد همیشه با یک مخلوط ناهمگن به کلاس برود.\r\n"},{"id":1972,"category_id":2,"category_code":"s2","source_id":139,"title":"شمع قرمز","content":"مردي در بستر مرگ افتاده بود. همسرش را فراخواند تا نزدش بيايد و به او گفت: «ديگر زمان وداع ابدي من و تو فرارسيده است؛ پس بيا و براي آخرين بار به من مهر و وفاداري خود را ثابت کن...\r\n\r\nچراکه در مسلک ما گفته شده مرد متاهل هنگام گذر از دروازه بهشت بايد سوگند بخورد که تمام عمر کنار زني والا زندگي کرده است. در کشوي ميز من شمعي قرمز هست، اين شمع متبرک است و آن را از کشيشي گرفته‌ام و براي همين ارزشي بسيار دارد. سوگند بخور تا زماني که اين شمع وجود دارد دوباره ازدواج نکني.»\r\n\r\nزن سوگند خورد و مرد مُرد. در مراسم تشييع جنازه مرد، زن بالاي قبر ايستاده بود و پذيراي تسليت اقوام بود و شمع قرمز روشني در دست داشت و تا تمام شدن آن بالاي سر قبر ايستاد!\r\n"},{"id":1973,"category_id":2,"category_code":"s2","source_id":140,"title":" قلب جغد پیر شکست...","content":"جغدي روي كنگره هاي قديمي دنيا نشسته بود.زندگي را تماشا ميكرد.رفتن و ردپاي آن را.و آدمهايي را مي ديد كه به سنگ و ستون، به در و ديوار دل مي بندند.\r\nجغد اما مي دانست كه سنگ ها ترك مي خورند، ستون ها فرو مي ريزند، درها مي شكنند و ديوارها خراب مي شوند.\r\nاو بارها و بارها تاجهاي شكسته، غرورهاي تكه پاره شده را لابلاي خاكروبه هاي كاخ دنيا ديده بود.\r\nاو هميشه آوازهايي درباره دنيا و ناپايداري اش مي خواند و فكر مي كرد شايد پرده هاي ضخيم دل آدمها، با اين آواز كمي بلرزد.\r\nروزي كبوتري از آن حوالي رد مي شد، آواز جغد را كه شنيد، گفت: بهتر است سكوت كني و آواز نخواني.\r\nآدمها آوازت را دوست ندارند.\r\nغمگين شان مي كني.\r\nدوستت ندارند.\r\nمي گويند بديمني و بدشگون و جز خبر بد، چيزي نداري.\r\nقلب جغد پير شكست و ديگر آواز نخواند.\r\nسكوت او آسمان را افسرده كرد.\r\nآن وقت خدا به جغد گفت: آوازخوان كنگره هاي خاكي من! پس چرا ديگر آواز نمي خواني؟ دل آسمانم گرفته است.\r\nجغد گفت: خدايا! آدمهايت مرا و آوازهايم را دوست ندارند.\r\nخدا گفت: آوازهاي تو بوي دل كندن مي دهد و آدمها عاشق دل بستن اند.\r\nدل بستن به هر چيز كوچك و هر چيز بزرگ.\r\nتو مرغ تماشا و انديشه اي! و آن كه مي بيند و مي انديشد، به هيچ چيز دل نمي بندد.\r\nدل نبستن سخت ترين و قشنگ ترين كار دنياست.\r\nاما تو بخوان و هميشه بخوان كه آواز تو حقيقت است و طعم حقيقت تلخ.\r\nجغد به خاطر خدا باز هم بر كنگره هاي دنيا مي خواند و آنكس كه مي فهمد، مي داند آواز او پيغام است.\r\n"},{"id":1974,"category_id":2,"category_code":"s2","source_id":141,"title":"شاعر بي پول","content":"يک شب نصرت رحماني وارد کافه نادري شد و به اخوان ثالث گفت : من همين حالا سي تومن پول احتياج دارم . اخوان جواب داد : من پولم کجا بود ؟ برو خدا روزي ات را جاي ديگري حواله کند. نصرت رحماني رفت و بعد از مدتي بر گشت و بيست تومان پول و يک خودکار به اخوان داد . اخوان گفت اين پول چيه ؟ تو که پول نداشتي . نصرت رحماني گفت : از دم در ؛ پالتوي تو رو ورداشتم بردم پنجاه تومن فروختم . چون بيش از سي تومن لازم نداشتم ؛ بگير ؛ اين بيست تومن هم بقيه پولت ! ضمنا، اين خودکار هم توي پالتوت بود."},{"id":1975,"category_id":2,"category_code":"s2","source_id":142,"title":"ميرسونمت","content":"يک شب که باران شديدي ميباريد پرويز شاپور از شاملو پرسيد : چرا اينقدر عجله داري ؟ شاملو گفت : مي ترسم به آخرين اتوبوس نرسم . پرويز شاپور گفت : من ميرسونمت . شاملو پرسيد : مگه ماشين داري ؟ شاپور گفت : نه ! اما چتر دارم"},{"id":1976,"category_id":2,"category_code":"s2","source_id":143,"title":"مراعات همسر","content":"همسر حميد مصدق -لاله خانم - روي در ورودي سالن خانه شان با خط درشت نوشته بود: حميد بيماري قلبي دارد . لطفا مراعات کنيد و بيرون از خانه سيگار بکشيد . خود حميد مصدق هم ميآمد بيرون سيگار ميکشيد و ميگفت : به احترام لاله خانم است."},{"id":1977,"category_id":2,"category_code":"s2","source_id":144,"title":"درخت و مسافر","content":"مسافري خسته كه از راهي دور مي آمد ، به درختي رسيد و تصميم گرفت كه در سايه آن قدري اسـتراحت كند غافـل از اين كه آن درخت جـادويي بود ، درختي كه مي توانست آن چه كه بر دلش مي گذرد برآورده سازد...!\r\nوقتي مسافر روي زمين سخت نشست با خودش فكر كرد كه چه خوب مي شد اگـر تخت خواب نـرمي در آن جا بود و او مي تـوانست قـدري روي آن بيارامد.\r\nفـوراً تختي كه آرزويـش را كرده بود در كنـارش پديـدار شـد !!!\r\nمسافر با خود گفت : چقدر گـرسـنه هستم. كاش غذاي لذيـذي داشتم...\r\nناگهان ميـزي مملو از غذاهاي رنگارنگ و دلپذيـر در برابرش آشـكار شد.\r\nپس مـرد با خوشحالي خورد و نوشيد...\r\n\r\nبعـد از سیر شدن ، كمي سـرش گيج رفت و پلـك هايش به خاطـر خستگي و غذايي كه خورده بود سنگين شدند. خودش را روي آن تخت رهـا كرد و در حالـي كه به اتفـاق هاي شـگفت انگيـز آن روز عجيب فكـر مي كرد با خودش گفت : \r\n\r\nقدري ميخوابم. ولي اگر يك ببر گرسنه از اين جا بگـذرد چه؟\r\nو ناگهان ببـري ظاهـر شـد و او را دريد...\r\nهر يك از ما در درون خود درختي جادويي داريم كه منتظر سفارش هايي از جانب ماست.\r\nولي بايد حواسـمان باشد ، چون اين درخت افكار منفي ، ترس ها ، و نگراني ها را نيز تحقق مي بخشد.\r\nبنابر اين مراقب آن چه كه به آن مي انديشيد باشيد... .\r\n"},{"id":1978,"category_id":2,"category_code":"s2","source_id":145,"title":"برخورد یک زن و شوهر با ماموران","content":"زن و مرد از راهي مي رفتند، ماموران آنها را ديدند وآنها را خواستند!\r\nپرسيدند شما چه نسبتي با هم داريد؟\r\nزن و مرد جواب دادند زن و شوهريم\r\nماموران مدرك خواستند،\r\nزن و مرد گفتند نداريم !\r\nماموران گفتند چگونه باور كنيم كه شما زن و شوهريد ؟!\r\nزن و مرد گفتند براي ثابت كردن اين امرنشانه هاي فراواني داريم ... !\r\nاول اينكه آن افرادی كه شما مي گوييد دست در دست هم مي روند،\r\nما دستهايمان از هم جداست!\r\n\r\nدوم، آنها هنگام راه رفتن و صحبت كردن به هم نگاه مي كنند،\r\nما رويمان به طرف ديگريست!\r\nسوم آنكه آنها هنگام صحبت كردن و راه رفتن،با هم با احساس حرف مي زنند،\r\nما احساسي به هم نداريم!\r\nچهارم آنكه آنها با هم بگو بخند مي كنند،\r\nمی بینید که، ما غمگينيم!\r\nپنجم، آنها چسبيده به هم راه مي روند،\r\nاما يكي ازما جلوترازدیگری مي رود!\r\n\r\nششم آنكه آنها هنگام با هم بودن كيكي، بستني ای، چيزي مي خورند،\r\nما هيچ نمي خوريم!\r\n\r\nهفتم، آنها هنگام با هم بودن بهترين لباسهايشان را مي پوشند،\r\nما لباسهاي کهنه تنمان است.. !\r\n"},{"id":1979,"category_id":2,"category_code":"s2","source_id":146,"title":"خر دانا","content":"يک روز يک مرد روستايي يک کوله بار روي خرش گذاشت و خودش هم سوار شد تا به شهر برود.\r\nخر پير و ناتوان بود و راه دور و ناهموار بود و در صحرا پاي خر به سوراخي رفت و به زمين غلطيد. بعد از اينکه روستايي به زور خر را از زمين بلند کرد معلوم شد پاي خر شکسته و ديگر نمي تواند راه برود.\r\nروستايي کوله بار را به دوش گرفت و خر پا شکسته را در بيابان ول کرد و رفت.\r\nخر بدبخت در صحرا مانده بود و با خود فکر مي کرد که «يک عمر براي اين بي انصاف ها بار کشيدم و حالا که پير و دردمند شده ام مرا به گرگ بيابان مي سپارند و مي روند.» خر با حسرت به هر طرف نگاه مي کرد و يک وقت ديد که راستي راستي از دور يک گرگ را مي بيند.\r\nگرگ درنده همينکه خر را در صحرا افتاده ديد خوشحال شد و فريادي از شادي کشيد و شروع کرد به پيش آمدن تا خر را از هم بدرد و بخورد.\r\nخر فکر کرد«اگر مي توانستم راه بروم، دست و پايي مي کردم و کوششي به کار مي بردم و شايد زورم به گرگ مي رسيد ولي حالا هم نبايد نااميد باشم و تسليم گرگ شوم. پاي شکسته مهم نيست. تا وقتي مغز کار مي کند براي هر گرفتاري چاره اي پيدا مي شود.» نقشه اي را کشيد، به زحمت از جاي خود برخاست و ايستاد اما نمي توانست قدم از قدم بردارد. همينکه گرگ به او نزديک شد خر گفت:«اي سالار درندگان، سلام.»\r\nگرگ از رفتار خر تعجب کرد و گفت:«سلام، چرا اينجا خوابيده بودي؟» خر گفت: «نخوابيده بودم بلکه افتاده بودم، بيمارم و دردمندم و حالا هم نمي توانم از جايم تکان بخورم. اين را مي گويم که بداني هيچ کاري از دستم بر نمي آيد، نه فرار، نه دعوا، و درست و حسابي در اختيار تو هستم ولي پيش از مرگم يک خواهش از تو دارم.»\r\nگرگ پرسيد:«خواهش؟ چه خواهشي؟»\r\nخر گفت:«ببين اي گرگ عزيز، درست است که من خرم ولي خر هم تا جان دارد جانش شيرين است، همانطور که جان آدم براي خودش شيرين است البته مرگ من خيلي نزديک است و گوشت من هم قسمت تو است، مي بيني که در اين بيابان ديگر هيچ کس نيست. من هم راضي ام، نوش جانت و حلالت باشد. ولي خواهشم اين است که کمي لطف و مرحمت داشته باشي و تا وقتي هوش و حواس من بجا هست و بيحال نشده ام در خوردن من عجله نکني و بيخود و بي جهت گناه کشتن مرا به گردن نگيري، چرا که اکنون دست و پاي من دارد مي لرزد و زورکي خودم را نگاهداشته ام و تا چند لحظه ديگر خودم از دنيا مي روم. در عوض من هم يک خوبي به تو مي کنم و چيزي را که نمي داني و خبر نداري به تو مي دهم که با آن بتواني صد تا خر ديگر هم بخري.»\r\nگرگ گفت:«خواهشت را قبول مي کنم ولي آن چيزي که مي گويي کجاست؟ خر را با پول مي خرند نه با حرف.»\r\nخر گفت:«صحيح است من هم طلاي خالص به تو مي دهم. خوب گوش کن، صاحب من يک شخص ثروتمند است و آنقدر طلا و نقره دارد که نپرس، و چون من در نظرش خيلي عزيز بودم براي من بهترين زندگي را درست کرده بود. آخور مرا با سنگ مرمر ساخته بود، طويله ام را با آجر کاشي فرش مي کرد، تو بره ام را با ابريشم مي بافت و پالان مرا از مخمل و حرير مي دوخت و بجاي کاه و جو هميشه نقل و نبات به من مي داد. گوشت من هم خيلي شيرين است حالا مي خوري و مي بيني. آنوقت چون خيلي خاطرم عزيز بود هميشه نعل هاي دست و پاي مرا هم از طلاي خالص مي ساخت و من امروز تنها و بي اجازه به گردش آمده بودم که حالم به هم خورد. حالا که گذشت ولي من خيلي خر ناز پرورده اي هستم و نعلهاي دست و پاي من از طلا است و تو که گرگ خوبي هستي مي تواني اين نعلها را از دست و پايم بکني و با آن صدتا خر بخري. بيا نگاه کن ببين چه نعلهاي پر قيمتي دارم!»\r\nهمانطور که ديگران به طمع مال و منال گرفتار مي شوند گرگ هم به طمع افتاد و رفت تا نعل خر را تماشا کند. اما همينکه به پاهاي خر نزديک شد خر وقت را غنيمت شمرد و با همه زوري که داشت لگد محکمي به پوزه گرگ زد و دندانهايش را در دهانش ريخت و دستش را شکست.\r\nگرگ از ترس و از درد فرياد کشيد و گفت:«عجب خري هستي!»\r\nخر گفت:«عجب که ندارد، ولي مي بيني که هر ديوانه اي در کار خودش هوشيار است. تا تو باشي و ديگر هوس گوشت خر نکني!»\r\nگرگ شکست خورده ناله کنان و لنگان لنگان از آنجا فرار کرد. در راه روباهي به او برخورد و با ديدن دست شل و پوزه خونين گرگ از او پرسيد:«اي سرور عزيز، اين چه حال است و دست و صورتت چه شده، شکارچي تيرانداز کجا بود؟»\r\nگرگ گفت:«شکارچي تيرانداز نبود، من اين بلا را خودم بر سر خودم آوردم.»\r\nروباه گفت:«خودت؟ چطور؟ مگر چه کار کردي؟»\r\nگرگ گفت:«هيچي، آمدم شغلم را تغيير بدهم و اينطور شد، کار من سلاخي و قصابي بود، زرگري و آهنگري بلد نبودم ولي امروز رفتم نعلبندي کنم!»\r\n"},{"id":1980,"category_id":2,"category_code":"s2","source_id":147,"title":"جمله ی جادویی","content":"مدت زیادی از زمان ازدواجشان می‌گذشت و طبق معمول زندگی فراز و نشیب‌های خاص خودش را داشت.\r\nیک روز زن که از ساعت‌های زیاد کار شوهر عصبانی بود و همه چیز را از هم پاشیده می‌دید، زبان به شکایت گشود و باعث ناامیدی شوهرش شد.\r\nمرد پس از یک هفته سکوت همسرش، با کاغذ و قلمی‌در دست به طرف او رفت و پیشنهاد کرد هر آنچه را که باعث آزارشان می‌شود را بنویسید و در مورد آن‌ها بحث و تبادل نظر کنند.\r\nزن که گله‌های بسیاری داشت بدون اینکه سرخود را بلند کند، شروع کرد به نوشتن.\r\nمرد پس از نگاهی عمیق و طولانی به همسر، نوشتن را آغاز کرد.\r\nیک ربع بعد با نگاهی به یکدیگر کاغذ‌ها را رد وبدل کردند. مرد به زن عصبانی و کاغذ لبریز از شکایت خیره ماند…\r\nاما زن با دیدن کاغذ شوهر، خجالت زده شد و به سرعت کاغذ خود را پاره کرد.\r\nشوهرش در هر دو صفحه این جمله را تکرار کرده بود:\r\n\"دوستت دارم عزیزم\"\r\n"},{"id":1981,"category_id":2,"category_code":"s2","source_id":148,"title":"کمک به رقبا","content":"یکی از کشاورزان منطقه ای، همیشه در مسابقه‌ها، جایزه بهترین غله را به ‌دست می‌آورد و به ‌عنوان کشاورز نمونه شناخته شده بود. رقبا و همکارانش، علاقه‌مند شدند راز موفقیتش را بدانند. به همین دلیل، او را زیر نظر گرفتند و مراقب کارهایش بودند. پس از مدتی جستجو، سرانجام با نکته‌ عجیب و جالبی روبرو شدند. این کشاورز پس از هر نوبت کِشت، بهترین بذرهایش را به همسایگانش می‌داد و آنان را از این نظر تأمین می‌کرد. بنابراین، همسایگان او می‌بایست برنده‌ مسابقه‌ها می‌شدند نه خود او!\r\nکنجکاویشان بیش‌تر شد و کوشش علاقه‌مندان به کشف این موضوع که با تعجب و تحیر نیز آمیخته شده بود، به جایی نرسید. سرانجام، تصمیم گرفتند ماجرا را از خود او بپرسند و پرده از این راز عجیب بردارند.\r\nکشاورز هوشیار و دانا، در پاسخ به پرسش همکارانش گفت: «چون جریان باد، ذرات بارورکننده غلات را از یک مزرعه به مزرعه‌ دیگر می‌برد، من بهترین بذرهایم را به همسایگان می‌دادم تا باد، ذرات بارورکننده نامرغوب را از مزرعه‌های آنان به زمین من نیاورد و کیفیت محصول‌های مرا خراب نکند!»\r\nهمین تشخیص درست و صحیح کشاورز، توفیق کامیابی در مسابقه‌های بهترین غله را برایش به ارمغان می‌آورد.\r\nگاهی اوقات لازم است با کمک به رقبا و ارتقاء کیفیت و سطح آنها، کاری کنیم که از تأثیرات منفی آنها در امان باشیم.\r\n"},{"id":1982,"category_id":2,"category_code":"s2","source_id":149,"title":"عشق پولی","content":"روزی مرد ثروتمندی همراه دخترش مقدار زیادی شیرینی و خوردنی به مدرسه شیوانا آورد و گفت اینها هدایای ازدواج تنها دختر او با پسر جوان و بیکاری از یک خانواده فقیر است.\r\nشیوانا پرسید: چگونه این دو نفر با دو سطح زندگی متفاوت با همدیگر وصلت کرده اند؟\r\n\r\nمرد ثروتمند پاسخ داد: این پسر شیفته‌ی دخترم است و برای ازدواج با او خودش را عاشق و دلداده نشان داده و به همین دلیل دل دخترم را ربوده است. درحالی که پسر یکی از دوستانم، هم نجیب است و هم عاقل، با اصرار می‌خواهد با دخترم ازدواج کند اما دخترم می‌گوید او بیش از حد جدی نیست و شور و جنون جوانی در حرکات و رفتارش وجود ندارد. اما این پسر بیکار هرچه ندارد دیوانگی و شور و عشق جوانی‌اش بی‌نظیر است. دخترم را نصیحت می‌کنم که فریب نخورد و کمی‌عاقلانه‌تر تصمیم بگیرد اما او اصلا به حرف من گوش نمی‌دهد. من هم به ناچار به ازدواج آن دو با هم رضایت دادم.\r\nشیوانا از دختر پرسید: چقدر مطمئن هستی که او عاشق توست؟\r\nدختر گفت: از همه بیشتر به عشق او ایمان دارم!\r\nشیوانا به دختر گفت: بسیار خوب بیا امتحان کنیم. نزد این عاشق و دلداده برو و به او بگو که پدرت تهدید کرده اگر با او ازدواج کنی حتی یک سکه از ثروتش را به شما نمی‌دهد. بگو که پدرت تهدید کرده که اگر سرو کله‌اش اطراف منزل شما پیدا شود او را به شدت تنبیه خواهد کرد.\r\n\r\nدختر با خنده گفت: من مطمئنم او به این سادگی میدان را خالی نمی‌کند. ولی قبول می‌کنم و به او چنین می‌گویم. چند هفته بعد مرد ثروتمند با دخترش دوباره نزد شیوانا آمدند. شیوانا متوجه شد که دختر غمگین و افسرده است. از او دلیل اندوهش را پرسید.\r\nدختر گفت: به محض اینکه به او گفتم پدرم گفته یک سکه به من نمی‌دهد و هر وقت او را ببیند تنبیه‌اش می‌کند، فوراً از مقابل چشمانم دور شد . از این دهکده فرار کرد. حتی برای خداحافظی هم نیامد.\r\n\r\nشیوانا با خنده گفت: اینکه ناراحتی ندارد. اگر او عاشق واقعی تو بود حتی اگر تو هم می‌گفتی که دیگر علاقه‌ای به او نداری و درخواست جدایی می‌کردی، او هرگز قبول نمی‌کرد. وقتی کسی چیزی را واقعا بخواهد با تمام جان و دل می‌خواهد و هرگز اجازه نمی‌دهد حتی برای یک لحظه آن چیز را از دست بدهد. اگر دیدی او به راحتی رهایت کرد و رفت مطمئن باش که او تو را از همان ابتدا نمی‌خواسته و نفع و صلاح خودش را به تو ترجیح داده است. دیگر برای کسی که از همان ابتدا به تو علاقه‌ای نداشته ناراحتی چه معنایی می‌تواند داشته باشد؟\r\n"},{"id":1983,"category_id":2,"category_code":"s2","source_id":150,"title":"پسران هنرمند","content":"سه نفر زن می خواستند از سر چاه آب بیاورند.\r\nدر فاصله ای نه چندان دور از آن ها پیر مرد دنیا دیده ای نشسته بود و می شنید که هریک از زن ها چه طور از پسرانشان تعریف می کنند.\r\nزن اول گفت : پسرم چنان در حرکات اکروباتی ماهر است که هیچ کس به پای او نمی رسد.\r\nدومی گفت : پسر من مثل بلبل اواز می خواند. هیچ کس پیدا نمی شود که صدایی به این قشنگی داشته باشد .\r\nهنگامی که زن سوم سکوت کرد، آن دو از او پرسیدند :\r\nپس تو چرا از پسرت چیزی نمی گویی؟\r\nزن جواب داد : در پسرم چیز خاصی برای تعریف کردن نیست. او فقط یک پسر معمولی است .ذاتا هیچ صفت بارزی ندارد.\r\nسه زن سطل هایشان را پر کردند و به خانه رفتند .\r\nپیرمرد هم آهسته به دنبالشان راه افتاد. سطل ها سنگین و دست های کار کرده زن ها ضعیف بود .\r\nبه همین خاطر وسط راه ایستادند تا کمی استراحت کنند؛\r\nچون کمرهایشان به سختی درد گرفته بود. در همین موقع پسرهای هر سه زن از راه رسدند .پسر اول روی دست هایش ایستاد و شروع کرد به پا دوچرخه زدن.\r\nزن ها فریاد کشیدند: عجب پسر ماهر و زرنگی است!\r\nپسر دوم هم مانند یک بلبل شروع به خواندن کرد و زن ها با شوق و ذوق در حالی که اشک در چشمانشان حلقه زده بود، به صدای او گوش دادند.\r\nپسر سوم به سوی مادرش دوید. سطل را بلند کرد و آن را به خانه برد.\r\nدر همین موقع زن ها از پیرمرد پرسیدند: نظرت در مورد این پسرها چیست؟\r\nپیرمرد با تعجب پرسید:منظورتان کدام پسرهاست ؟من که اینجا فقط یک پسر می بینم.\r\n"},{"id":1984,"category_id":2,"category_code":"s2","source_id":151,"title":"آبدارچی ماکروسافت","content":"مرد بیکاری برای سِمَتِ آبدارچی در مایکروسافت تقاضا داد. رئیس هیئت مدیره با او مصاحبه کرد و تمیز کردن زمینش رو - به عنوان نمونه کار- دید و گفت: «شما استخدام شدین، آدرس ایمیلتون رو بدین تا فرم‌های مربوطه رو واسه‌تون بفرستم تا پر کنین و همینطور تاریخی که باید کار رو شروع کنین... \r\nمرد جواب داد: «اما من کامپیوتر ندارم، ایمیل هم ندارم!» \r\nرئیس هیئت مدیره گفت: «متأسفم. اگه ایمیل ندارین، یعنی شما وجود خارجی ندارین. و کسی که وجود خارجی نداره، شغل هم نمیتونه داشته باشه.» \r\nمرد در کمال نومیدی اونجا رو ترک کرد. نمیدونست با تنها ۱۰ دلاری که در جیبش داشت چه کار کنه. تصمیم گرفت به سوپرمارکتی بره و یک صندوق ۱۰ کیلویی گوجه فرنگی بخره. یعد خونه به خونه گشت و گوجه فرنگی‌ها رو فروخت. در کمتر از دو ساعت، توانست سرمایه‌اش رو دو برابر کنه. این عمل رو سه بار تکرار کرد و با ۶۰ دلار به خونه برگشت. مرد فهمید میتونه به این طریق زندگیش رو بگذرونه و شروع کرد به این که هر روز زودتر بره و دیرتر برگرده خونه. در نتیجه پولش هر روز دو یا سه برابر میشد. به زودی یه گاری خرید، بعد یه کامیون و به زودی ناوگان خودش رو در خط ترانزیت (پخش محصولات) داشت... \r\nپنج سال بعد، مرد دیگه یکی از بزرگترین خرده فروشان امریکا شد. شروع کرد تا برای آینده خانواده‌اش برنامه‌ریزی کنه و تصمیم گرفت بیمه عمر بگیره. به یه نمایندگی بیمه زنگ زد و سرویسی رو انتخاب کرد. وقتی صحبتشون به نتیجه رسید، نماینده بیمه از آدرس ایمیل مرد پرسید. مرد جواب داد: «من ایمیل ندارم.» \r\nنماینده بیمه با کنجکاوی پرسید: «شما ایمیل ندارین، ولی با این حال تونستین یک امپراطوری در شغل خودتون به وجود بیارین.. میتونین فکر کنین به کجاها میرسیدین اگه یه ایمیل هم داشتین؟» مرد برای مدتی فکر کرد و گفت: \r\nآره! احتمالاً میشدم یه آبدارچی در شرکت مایکروسافت...\r\n"},{"id":1985,"category_id":2,"category_code":"s2","source_id":152,"title":"خلوص پیرزن","content":"\r\nیکشنبه بود و طبق معمول هر هفته خانم نسبتا مسن محله، داشت از کلیسا برمیگشت ...\r\nیکشنبه بود و طبق معمول هر هفته خانم نسبتا مسن محله، داشت از کلیسا برمیگشت …\r\nدر همین حال نوه اش از راه رسید و با کنایه بهش گفت :\r\nمامان بزرگ ، تو مراسم امروز ، پدر روحانی براتون چی موعظه کرد ؟!\r\nخانم پیر مدتی فکر کرد و سرش رو تکون داد و گفت :\r\nعزیزم ، اصلا یک کلمه اش رو هم نمیتونم به یاد بیارم !!!\r\nنوه پوزخندی زد و بهش گفت :\r\nتو که چیزی یادت نمیاد ، واسه چی هر هفته همش میری کلیسا ؟!!\r\nمادر بزرگ تبسمی بر لبانش نقش بست.\r\nخم شد سبد نخ و کامواش رو خالی کرد و داد دست نوه و گفت :\r\nعزیزم ممکنه بری اینو از حوض پر آب کنی و برام بیاری ؟!\r\nنوه با تعجب پرسید : تو این سبد ؟ غیر ممکنه\r\nبا این همه شکاف و درز داخل سبد آبی توش بمونه !!!\r\nرزی در حالی که تبسم بر لبانش بود اصرار کرد : لطفا این کار رو انجام بده عزیزم\r\nدخترک غرولند کنان و در حالی که مادربزرگش رو تمسخر میکرد\r\nسبد رو برداشت و رفت ، اما چند لحظه بعد ، برگشت و با لحن پیروزمندانه ای گفت :\r\nمن میدونستم که امکان پذیر نیست ، ببین حتی یه قطره آب هم ته سبد نمونده !\r\nمادر بزرگ سبد رو از دست نوه اش گرفت و با دقت زیادی وارسیش کرد گفت :\r\nآره، راست میگی اصلا آبی توش نیست اما بنظر میرسه سبده تمیزتر شده ، یه نیگاه بنداز …!\r\n"},{"id":1986,"category_id":2,"category_code":"s2","source_id":153,"title":"طعم هدیه","content":"\r\nروزی فردی جوان هنگام عبور از بیابان، به چشمه آب زلالی رسید.\r\nآب به قدری گوارا بود که مرد سطل چرمی اش را پر از آب کرد تا بتواند مقداری از آن آب را برای استادش که پیر قبیله بود ببرد. مرد جوان پس از مسافرت چهار روزه اش، آب را به پیرمرد تقدیم کرد.\r\nپیرمرد، مقدار زیادی از آب را لاجرعه سر کشید و لبخند گرمی نثار مرد جوان کرد و از او بابت آن آب زلال بسیار قدردانی کرد. مرد جوان با دلی لبریز از شادی به روستای خود بازگشت.\r\nاندکی بعد، استاد به یکی دیگر از شاگردانش اجازه داد تا از آن آب بچشد.\r\nشاگرد آب را از دهانش بیرون پاشید و گفت: آب بسیار بد مزه است.\r\nظاهرا آب به علت ماندن در سطل چرمی، طعم بد چرم گرفته بود. شاگرد با اعتراض از استاد پرسید:\r\nآب گندیده بود. چطور وانمود کردید که گوارا است؟\r\nاستاد در جواب گفت:\r\nتو آب را چشیدی و من خود هدیه را چشیدم.\r\nاین آب فقط حامل مهربانی سرشار از عشق بود و هیچ چیز نمی تواند گواراتر از این باشد.\r\n"},{"id":1987,"category_id":2,"category_code":"s2","source_id":154,"title":" نوی خوب من","content":"حامد با اصرار سوار ماشین پدرش شد .هر کاری کردند از ماشین پیاده بشه نشد که نشد. پدر و مادرش فکر میکردند اگه بفهمه بابا بزرگ رو میخوان ببرن خونه سالمندان و اون دیگه نمی تونه پدر بزرگش رو ببینه قیامت به پا میکنه.اما اینطور نشد.\r\nخیلی اروم نشست صندلی جلوی ماشین، مثل آدم بزرگها.بابا بزرگ هم مات و مبهوت نشسته بود صندلی عقب و غرق در خیالات خودش بود ، وهر چند حالش خوب نبود از بی احساسی حامد کوپولو تعجب زده بود ولی به روی خودش نمی آورد. به اولین خیابان که رسیدند حامد رو به باباش کرد وپرسید :بابا اسم این خیابون چیه؟باباش جوابش رو داد.اما حامد ول کن نبود.اسم تمام خیابونها رو دقیق دقیق میپرسد.بلاخره حوصله باباش سر اومد با ناراحتی پرسید:بچه جون اسم این خیابونها رو میخوای چیکار کنی؟به چه دردت میخوره؟\r\nحامد با صدای معصومانه اش گفت:بابایی میخوام اسم خیابونها رو خوب خوب یاد بگیرم تا وقتی تو هم مثل بابابزرگ پیر شدی ببرمت اونجا تنها زندگی کنی.دنیا رو سرش خراب شد.نگاهی از آیینه به پدر پیرش کرد، خودش رو اون پشت دید . از همون جا بسرعت دور زد . و برگشت بطرف خونشون.حامد کوچولو اون جلو یواشکی داشت میخندید. برگشت و دستای داغ و تب دار بابابزرگش رو تو دستای کوچیکش محکم فشار داد ،اشک از چشمهای پیرمرد سرازیر بود.\r\n"},{"id":1988,"category_id":2,"category_code":"s2","source_id":155,"title":"آهسته تر...","content":"تاجری در روستایی، مقدار زیادی محصول کشاورزی خرید و می‌خواست با آنها را با ماشین به انبار منتقل کند. در راه از پسری پرسید: «تا جاده چقدر راه است؟»\r\nپسر جواب داد: «اگر آرام بروید حدود ده دقیقه کافی است. اما اگر با سرعت بروید نیم ساعت و یا شاید بیشتر.»\r\nتاجر از این تضاد در جواب پسر ناراحت شد و به او بد و بیراه گفت و به سرعت خودرو را به جلو راند. اما پنجاه متر بیشتر نرفته بود که چرخ ماشین به سنگی برخورد کرد و با تکان خوردن ماشین، همه محصول‌ها به زمین ریخت. تاجر وقت زیادی برای جمع کردن محصول ریخته شده صرف کرد و هنگامی که خسته و کوفته به سمت خودرواش بر می‌گشت یاد حرف‌های پسر افتاد و وقتی منظور او را فهمید بقیه راه را آرام و بااحتیاط طی کرد.\r\nشاید گاهی باید آرام تر قدم برداریم تا به مقصد برسیم.\r\nلابروير: «برای كسی كه آهسته و پيوسته راه می‌رود، هيچ راهی دور نیست.»\r\n"},{"id":1989,"category_id":2,"category_code":"s2","source_id":156,"title":"پیرمرد و حیوانات","content":"در یک جنگل سبز و خرم، کلبه چوبی کوچکی بود که پیرمرد مهربانی در آن زندگی می کرد. او عاشق حیوانات بود و به خاطر علاقه به حیوانات بود که به تنهایی در جنگل زندگی می کرد.\r\nپیرمرد مهربان روزها در جنگل می گشت اگر حیوانی زخمی پیدا می کرد آن را به کلبه می برد معالجه و مداوا می کرد. اگر کسی به کمک احتیاج داشت به او کمک می کرد. اگر گاهی شکارچیان برای شکار حیوانات به آن جنگل می آمد، حیوانات را خبر می کرد و کمک می کرد از دست شکارچیان فرار کنند. در جنگل سبز همه ی حیوانات پیرمرد مهربان را دوست داشتند . فقط یک عقاب بود که او را دوست نداشت بلکه دشمن پیرمرد بود.\r\nماجرا این بود که عقاب، پنج سال پیش در دام یک شکارچی افتاده بود. و بال بزرگش شکسته بود. اما توانسته بود از دام فرار کند. عقاب با خودش فکر می کرد شاید این پیرمرد بوده که آن دام را برای او پهن کرده و داستان شکارچیان دروغ است.او همیشه منتظر فرصتی بود تا از پیرمرد انتقام بگیرد.\r\nتا اینکه یک روز از حیوانات دیگر شنید که پیرمرد بیمار شده است و در کلبه ی خود استراحت می کند. عقاب دید که هر کسی دوست دارد به پیرمرد کمک کند. خرس بزرگ از رودخانه برای او ماهی می گیرد. میمون باهوش با کمک خرگوش و سنجاب ،ماهی را برای پیرمرد روی آتش کباب می کند. کلاغ و دارکوب هم به چشمه می روند و برای پیرمرد آب زلال و تمیز می آورند. عقاب با خودش فکر کرد اکنون وقت خوبی برای انتقام گرفتن است. او به اعماق جنگل رفت جایی که می دانست یک مار بزرگ زندگی می کند. او یک غذای لذیذ برای مار برد و از او خواست تا مقداری از زهر کشنده اش را به او بدهد. مار در عوض غذای خوشمزه ای که عقاب برایش آورده بود مقداری از کشنده ترین زهر خودش را به او داد. عقاب زهر را گرفت و پیش حیوانات بازگشت . به حیوانات گفت من تا حالا کاری برای پیرمرد نکرده ام اجازه بدهید این بار من غذایش را ببرم. حیوانات که از نقشه ی مار خبر نداشتند قبول کردند و غذای پیرمرد را به او دادند. مار غذا را زهرآلود کرد و به سمت کلبه راه افتاد. اما وقتی به کلبه رسید دید یک نفر دیگر در کلبه است . یک شکارچی که با تفنگ قصد کشتن پیرمرد را دارد. عقاب پشت در پنهان شد و به حرفهای آنها گوش کرد. شکارچی به پیرمرد می گفت تو همیشه مزاحم کار من هستی. امروز تو را می کشم و برای همیشه از شرت خلاص می شوم. پیرمرد گفت اگر می خواهی مرا بکش اما کاری به حیوانات بیچاره نداشته باش.\r\nشکارچی با صدای بلند خندید و گفت من همه ی آنها را یکی یکی شکار می کنم و هیچ حیوانی در جنگل باقی نمی گذارم این را به تو قول می دهم.\r\nپیرمرد آهی کشید و گفت امیدوارم هرگز موفق به این کار نشوی.\r\nشکارچی تفنگش را روی سر پیرمرد گذاشت و گفت یادت هست پنج سال پیش، عقاب بزرگ و باشکوهی را در دام انداخته بودم و تو آن دام را پاره کردی و کمک کردی تا عقاب فرار کند؟ اکنون تو را می کشم و بدنت را جلوی همان عقاب می اندازم تا تو را با منقارش تکه تکه کند.\r\nدر همین لحظه عقاب که همه ی حرفها را شنید شروع به بال زدن کرد. شکارچی متوجه عقاب شد و به دنبال او دوید و به سمت عقاب شلیک کرد. عقاب فرار کرد و ماهی زهرالود را روی زمین انداخت. شکارچی ماهی را برداشت و بی معطلی شروع به خوردن آن کرد. بعد از خوردن ماهی دوباره به سراغ پیرمرد رفت اما قبل از اینکه تیری شلیک کند سرش گیج رفت و روی زمین افتاد و مرد. یک ساعت بعد عقاب به کلبه ی پیرمرد برگشت و برایش یک ماهی کباب دیگر آورد ولی این بار ماهی زهرالود نبود. از آن روز به بعد عقاب بهترین دوست پیرمرد شد.\r\n"},{"id":1990,"category_id":2,"category_code":"s2","source_id":157,"title":"راز نور و نان","content":"راز نور و نان این همه گندم، این همه کشتزارهای طلایی، این همه خوشه در باد را که می خورد؟ آدم است، آدم است که می خورد\r\nاین همه گنج آویخته بر درخت، این همه ریشه در خاک را که می خورد؟ آدم است، آدم است که می خورد\r\nاین همه مرغ هوا و این همه ماهی دریا، این همه زنده بر زمین را که می خورد؟ آدم است ، آدم است که می خورد\r\nهر روز و هر شب، هر شب و هر روز زنبیل ها و سفره ها پر می شود، اما آدم گرسنه است. آدم همیشه گرسنه است.\r\nدست های میکائیل از رزق پر بود. از هزار خوراک و خوردنی. اما چشم های آدمی همیشه نگران بود. دست هایش خالی و دهانش باز\r\nمیکائیل به خدا گفت: خسته ام ، خسته ام از این آدم ها که هیچ وقت سیر نمی شوند. خدایا چقدر نان لازم است تا آدمی سیر شود؟ چقدر !\r\nخداوند به میکائیل گفت: آنچه آدمی را سیر می کند نان نیست، نور است. تو مامور آن هستی که نان بیاوری. اما نور تنها نزد من است و تا هنگامی که آدمی به جای نور، نان می خورد گرسنه خواهد ماند.\r\n***\r\nمیکائیل راز نان و نور را به فرشته ای گفت. و او نیز به فرشته ای دیگر. و هر فرشته به فرشته دیگری تا آنکه همه هفت آسمان این راز را دانستند. تنها آدم بود که نمی دانست. اما رازها سر می روند. پس راز نان و نور هم سر رفت. و آدمی سرانجام دانست که نور از نان بهتر است. پس در جستجوی نور برآمد. در جستجوی هر چراغ و هر فانوس و هر شمع.\r\n\r\nاما آدم، همیشه شتاب می کند. برای خوردن نور هم شتاب کرد. و نفهمید نوری که آدمی را سیر می کند نه در فانوس است و نه در شمع. نه در ستاره و نه در ماه.\r\nاو ماه را خورد و ستار ها را یکی یکی بلعید. اما باز هم گرسنه بود.\r\n**\r\nخداوند به جبرئیل گفت: سفره ای پهن کن و بر آن کلمه و عشق و هدایت بگذار.\r\nو گفت: هر کس بر سر این سفره بنشیند، سیر خواهد شد.\r\nسفره خدا گسترده شد؛ از این سر جهان تا آن سوی هستی. اما آدم ها آمدند و رفتند. از وسط سفره گذشتند و بر کلمه و عشق و هدایت پا گذاشتند.\r\n\r\nآدم ها گرسنه آمدند و گرسنه رفتند. اما گاهی، فقط گاهی کسی بر سر این سفره نشست و لقمه ای نور برداشت. و جهان از برکت همان لقمه روشن شد.\r\nو گاهی ، فقط گاهی کسی تکه ای عشق برداشت و جهان از همان تکه عشق رونق گرفت.\r\nو گاهی، فقط گاهی کسی جرعه ای از هدایت نوشید و هر که او را دید چنان سرمست شد که تا انتهای بهشت دوید.\r\n***\r\nسفره خدا پهن است اما دور آن هنوز هم چقدر خلوت است.\r\nمیکائیل نان قسمت می کند. آدم ها چنگ می زنند و نان ها را از او می ربایند.\r\nمیکائیل گریه می کند و می گوید: کاش می دانستید، کاش می دانستید که نور از نان بهتر است.\r\n"},{"id":1991,"category_id":2,"category_code":"s2","source_id":158,"title":"هزینه ی آموزش","content":"یکی از کارکنان شرکت « آی . بی . ام » اشتباه بزرگی مرتکب شد و مبلغ ده میلیون دلار به شرکت ضرر زد.\r\nاین کارمند به دفتر واتسون(بنیان گذار شرکت « آی . بی . ام ») احضار شد و پس از ورود گفت:« تصور می کنم باید از شرکت استعفا دهم.»تام واتسون گفت:\r\nشوخی می کنید ما همین الان مبلغ ده میلیون دلار بابت آموزش شما پول دادیم !!!\r\n"},{"id":1992,"category_id":2,"category_code":"s2","source_id":159,"title":"من و پدرم","content":"پدرم این جوری بود وقتی من :\r\n4 ساله که بودم فکر می کردم پدرم هر کاری رو می تونه انجام بده .\r\n5 ساله که بودم فکر می کردم پدرم خیلی چیزها رو می دونه .\r\n6 ساله که بودم فکر می کردم پدرم از همة پدرها باهوشتر.\r\n8 ساله که شدم ، گفتم پدرم همه چیز رو هم نمی دونه.\r\n10 ساله که شدم با خودم گفتم ! اون موقع ها که پدرم بچه بود همه چیز با حالا کاملاً فرق داشت.\r\n12 ساله که شدم گفتم ! خب طبیعیه ، پدر هیچی در این مورد نمی دونه .... دیگه پیرتر از اونه که بچگی هاش یادش بیاد.\r\n14 ساله که بودم گفتم : زیاد حرف های پدرمو تحویل نگیرم اون خیلی اُمله .\r\n16 ساله که شدم دیدم خیلی نصیحت می کنه گفتم باز اون گوش مفتی گیر اُورده .\r\n18 ساله که شدم . وای خدای من باز گیر داده به رفتار و گفتار و لباس پوشیدنم همین طور بیخودی به آدم گیر می ده عجب روزگاریه .\r\n21 ساله که بودم پناه بر خدا بابا به طرز مأیوس کننده ای از رده خارجه\r\n25 ساله که شدم دیدم که باید ازش بپرسم ، زیرا پدر چیزهای کمی درباره این موضوع می دونه زیاد با این قضیه سروکار داشته .\r\n30 ساله بودم به خودم گفتم بد نیست از پدر بپرسم نظرش درباره این موضوع چیه هرچی باشه چند تا پیراهن از ما بیشتر پاره کرده و خیلی تجربه داره .\r\n40 ساله که شدم مونده بودم پدر چطوری از پس این همه کار بر میاد ؟ چقدر عاقله ، چقدر تجربه داره .\r\n50 ساله که شدم حاضر بودم همه چیز رو بدم که پدر برگرده تا من بتونم باهاش دربارة همه چیز حرف بزنم ! اما افسوس که قدرشو نتونستم خیلی چیزها می شد ازش یاد گرفت !\r\n"},{"id":1993,"category_id":2,"category_code":"s2","source_id":160,"title":"فرقی ندارد","content":"شیخ محمد تقی بهلول، بعد از 36 سال تبعید و بازگشت به ایران در پاسخ به رییس ساواک در مورد ترس از مرگ چنین گفت:\r\nکسی که بعضی اقوامش در مشهد باشند و بعضی در تهران\r\nبرایش فرق نمیکند در مشهد زندگی کند یا در تهران ؛ من الان همین حال را دارم .\r\nپدر و مادر و خواهر و بعضی دیگر از عزیزانم به آن عالم رفته اند و بعضی دیگر در این دنیا هستند برای من فرقی ندارد این عالم باشم یا آن عالم.\r\nهر جا باشم پیش اقوام و خویشان خود هستم ...\r\n"},{"id":1994,"category_id":2,"category_code":"s2","source_id":161,"title":"شیرینی فروش","content":"در اوزاکای ژاپن ، شیرینی‌سرای بسیار مشهوری بود\r\nشهرت آن به خاطر شیرینی‌های خوشمزه‌ای بود که می‌پخت .\r\nمشتری‌های بسیار ثروتمندی به این مغازه می‌آمدند ، چون قیمت شیرینی‌ها بسیار گران بود.\r\nصاحب فروشگاه همیشه در همان عقب مغازه بود و هیچ وقت برای خوش‌آمد مشتری‌ها به این طرف نمی‌آمد ، مهم نبود که مشتری چقدر ثروتمند است.\r\nیک روز مرد فقیری با لباس‌های مندرس و موهای ژولیده وارد فروشگاه شد و عمداً نزدیک پیش‌خوان آمد قبل از آن‌که مرد فقیر به پیشخوان برسد ، صاحب فروشگاه از پشت مغازه بیرون پرید و فروشندگان را به کناری کشید و با تواضع فراوان به آن مرد فقیر خوش‌آمد گفت و با صبوری تمام منتظر شد تا آن مرد جیب‌هایش را بگردد تا پولی برای یک تکه شیرینی بیابد.\r\nصاحب فروشگاه خیلی مؤدبانه شیرینی را در دست‌های مرد فقیر قرار داد و هنگامی که او فروشگاه را ترک می‌کرد ، صاحب فروشگاه همچنان تعظیم می‌کرد.\r\nوقتی مشتری فقیر رفت ، فروشندگان نتوانستند مقاومت کنند\r\nو پرسیدند که در حالی که برای مشتری‌های ثروتمند از جای خود بلند نمی‌شوید ، چرا برای مردی فقیر شخصاً به خدمت حاضر شدید ؟\r\nصاحب مغازه در پاسخ گفت :\r\nمرد فقیر همه‌ی پولی را که داشت برای یک تکه شیرینی داد و واقعاً به ما افتخار داد این شیرینی برای او واقعاً لذیذ بود.\r\nشیرینی ما به نظر ثروتمندان خوب است ، اما نه آنقدر که برای مرد فقیر ، خوب و باارزش است.\r\n"},{"id":1995,"category_id":2,"category_code":"s2","source_id":162,"title":"راز بقا","content":"شیر آفریقایی هر شب که می خوابد می داند که فردا باید از کندترین غزال افریقایی کمی تندتر بدود تا از گرسنگی نمیرد. \r\nو غزال آفریقایی هر شب که می خوابد می داند که فردا باید از تندترین شیر آفریقایی کمی تندتر بدود تا کشته نشود.\r\nمهم نیست که تو شیر هستی یا غزال،\r\nمهم این است که فردا را از امروز تند تر بدوی.\r\nاین راز بقاست.\r\n"},{"id":1996,"category_id":2,"category_code":"s2","source_id":163,"title":"مسابقه ی زیبایی","content":"\r\nیک شرکت موفق محصولات زیبایی,در یک شهر بزرگ از مردم خواست که نامه ی مختصری درباره زیباترین زنی که می شناسد همراه با عکس آن زن برای آنها بفرستند.در عرض چند هفته هزار نامه به شرکت ارسال شد.\r\nنامه ای بخصوصی توجه کارکنان را جلب کرد,و فورا آن را به دست رئیس شرکت دادند.نامه توسط یک پسر جوان نوشته شده بود که شرح داده بود خانواده آنها از هم پاشیده شده و در محله ای فقیر نشین زندگی می کند.با تصحیح برخی کلماتش,خلاصه ی نامه اش به شرح زیر است:\r\nزن زیبایی یک خیابان پایین تر از من زندگی می کند.من هر روز او را ملاقات می کنم.او به من این احساس را می دهد که مهم ترین پسر این دنیا هستم.ما با هم شطرنج بازی می کنیم و او به مشکلات من توجه دارد.او مرا درک می کند و وقتی او را ترک می کنم,او همیشه با صدای بلند می گوید که به وجود من افتخار می کند.آن پسر نامه اش را با این مطلب خاتمه می داد:\"این عکس نشان می دهد که او زیباترین زن دنیاست.امیدوارم همسری به این زیبایی داشته باشم.\"\r\nرئیس شرکت در حالی که تحت تاثیر این نامه قرار گرفته بود,خواست که عکس این زن را ببیند.منشی او عکس زنی متبسم و بدون دندان را به دست او داد که سنی از او گذشته و در یک صندلی چرخدار نشسته بود.موهای خاکستریش را دم اسبی کرده بود و چین و چروک صورتش در خطوط چین و چروک چشم هایش محو شده بود.رئیس شرکت با تبسم گفت:\"ما نمی توانیم از این خانم برای تبلیغ استفاده کنیم.او به دنیا نشان می دهد که محصولات ما لزوما ارتباطی با زیبایی ندارد.\"\r\n"},{"id":1997,"category_id":2,"category_code":"s2","source_id":164,"title":"غلامی خضر","content":"روزى حضرت خضر از بازار بنى اسرائيل مى گذشت ناگاه چشم فقيرى به او افتاد و گفت :\r\nبه من صدقه بده خداوند به تو بركت دهد!\r\nخضر گفت :\r\nمن به خدا ايمان دارم ولى چيزى ندارم كه به تو دهم .\r\nفقير گفت :\r\nبوجه الله لما تصدقت على ؛ تو را به وجه (عظمت ) خدا سوگند مى دهم ! به من كمك كند! من در سيماى شما خير و نيكى مى بينم تو آدم خيّرى هستى اميدوارم مضايقه نكنى .\r\nخضر گفت :\r\nتو مرا به امر عظيم (وجه خدا) قسم دادى و كمك خواستى ولى من چيزى ندارم كه به تو احسان كنم مگر اينكه مرا به عنوان غلام بفروشى .\r\nفقير: اين كار نشدنى است چگونه تو را به نام غلام بفروشم ؟ خضر: تو مرا به وجه خدا (خداى بزرگ ) قسم دادى و كمك خواستى من نمى توانم نااميدت كنم مرا به بازار ببر و بفروش و احتياجت را برطرف كن !\r\nفقير حضرت خضر را به بازار آورد و به چهارصد درهم فروخت .\r\nخضر عليه السلام مدتى در نزد خريدار ماند، اما خريدار به او كار واگذار نمى كرد.\r\nخضر: تو مرا براى خدمت خريدى ، چرا به من كار واگذار نمى كنى ؟\r\nخريدار: من مايل نيستم كه تو را به زحمت اندازم ، تو پيرمرد سالخورده هستى .\r\nخضر: من به هر كارى توانا هستم و زحمتى بر من نيست . خريدار: حال كه چنين است اين سنگها را از اينجا به فلان جا ببر!\r\nبا اينكه براى جابجا كردن سنگها شش نفر در يك روز لازم بود، ولى سنگها را در يك ساعت به مكان معين جابجا كرد.\r\nخريدار خوشحال شد و تشويقش نمود و گفت :\r\nآفرين بر تو! كارى كردى كه از عهده يك نفر بيرون بود كه چنين كارى را انجام دهد.\r\nروزى براى خريدار سفرى پيش آمد خواست به مسافرت برود، به خضر گفت :\r\nمن تو را درستكار مى دانم مى خواهم به مسافرت بروم ، تو جانشين من باش ، با خانواده ام به نيكى رفتار كن تا من از سفر برگردم و چون پيرمرد هستى لازم نيست كار كنى ، كار برايت زحمت است .\r\nخضر: نه هرگز زحمتى برايم نيست .\r\nخريدار: حال كه چنين است مقدارى خشت بزن تا برگردم . خريدار به سفر رفت ، خضر به تنهايى خشت درست كرد و ساختمان زيبايى بنا نمود.\r\nخريدار كه از سفر برگشت ، ديد كه خضر خشت را زده و ساختمانى را هم با آن خشت ساخته است ، بسيار تعجب كرد و گفت :\r\nتو را به وجه خدا سوگند مى دهم كه بگويى تو كيستى و چه كاره اى ؟ حضرت خضر گفت :\r\n- چون مرا به وجه خدا سوگند دادى و همين مطلب مرا به زحمت انداخت و به نام غلام فروخته شدم . اكنون مجبورم كه داستانم را به شما بگويم :\r\nفقير نيازمندى از من صدقه خواست و من چيزى از مال دنيا نداشتم كه به او كمك كنم . مرا به وجه خدا قسم داد، لذا خود را به عنوان غلام در اختيار او گذاشتم تا مرا به شما فروخت .\r\nاكنون به شما مى گويم هرگاه سائلى از كسى چيزى بخواهد و به وجه خدا قسم دهد در صورتى كه مى تواند به او كمك كند، سائل را رد كند روز قيامت در حالى محشور خواهد شد كه در صورت او پوست ، گوشت و خون نيست ، تنها استخوانهاى صورتش مى مانند كه وقت حركت صدا مى كنند (فقط با اسكلت در محشر ظاهر مى شود.) خريدار: چون حضرت خضر را شناخت گفت :\r\nمرا ببخش كه تو را نشناختم . و به زحمت انداختم .\r\nخضر گفت : طورى نيست . چون تو مرا نگهداشتى و درباره ام نيكى نمودى .\r\nخريدار: پدر و مادرم فدايت باد! خود و تمام هستى ام در اختيار شماست .\r\nخضر: دوست دارم مرا آزاد كنى تا خدا را عبادت كنم .\r\nخريدار: تو آزاد هستى !\r\nخضر: خداوند را سپاسگزارم كه پس از بردگى مرا آزاد نمود.\r\n"},{"id":1998,"category_id":2,"category_code":"s2","source_id":165,"title":"ایمان","content":"فردي از پروردگار درخواست نمود تا به او بهشت و جهنم را نشان دهد خداوند پذيرفت . او را وارد اتاقي نمود كه جمعي از مردم در اطراف يك ديگ بزرگ غذا نشسته بودند . همه گرسنه،نا اميد و در عذاب بودند. هركدام قاشقي داشت كه به ديگ ميرسيد ولي دسته قاشقها بلند تر از بازوي آنها بود،بطوريكه نميتوانستند قاشق را به دهانشان برسانند! عذاب انها وحشتناك بود. آنگاه خداوند گفت : اكنون بهشت را به تو نشان ميدهم. او به اتاق ديگري كه درست مانند اولي بود وارد شد. ديگ غذا ، جمعي از مردم ، همان قاشقهاي دسته بلند . ولي در آنجا همه شاد و سير بودند. آن مرد گفت : نمي فهمم ؟ چرا مردم در اينجا شادند در حالي كه در اتاق ديگر بدبخت هستند ، با آنكه همه چيزشان يكسان است ؟ خداوند تبسمي كرد و گفت: خيلي ساده است ، در اينجا آنها ياد گرفته اند كه يكديگر را تغذيه كنند . هر كسي با قاشقش غذا در دهان ديگري ميگذارد، چون ايمان دارد كسي هست در دهانش غذايي بگذارد."},{"id":1999,"category_id":2,"category_code":"s2","source_id":166,"title":"سن عاشقی","content":"افسر عراقی تعریف می کرد: \r\nیه پسر بچه رو گرفتیم که ازش حرف بکشیم.\r\nآوردنش سنگر من. خیلی کم سن و سال بود.\r\nبهش گفتم : مگه سن سربازی توی ایران هجده سال تمام نیست؟\r\nسرش رو تکان داد. گفتم : تو که هنوز هجده سالت نشده !\r\nبعد هم مسخره اش کردم و گفتم:\r\nشاید به خاطر جنگ امام خمینی کارش به جایی رسیده که دست به دامن شما بچه ها شده و سن سربازی رو کم کرده؟\r\nجوابش خیلی من رو اذیت کرد با لحن فیلسوفانه ای گفت: \r\nسن سربازی پایین نیومده سن عاشقی و غیرت پایین اومده....\r\n"},{"id":2000,"category_id":2,"category_code":"s2","source_id":167,"title":"فرشته های مسافر","content":"دو فرشته مسافر، برای گذراندن شب، در خانه یک خانواده ثروتمند فرود آمدند. این خانواده رفتار نامناسبی داشتند و دو فرشته را به مهمانخانه مجللشان راه ندادند، بلکه زیرزمین سرد خانه را در اختیار آنها گذاشتند. فرشته پیر در دیوار زیر زمین شکافی دید و آن را تعمیر کرد. وقتی که فرشته جوان از او پرسید چرا چنین کاری کرده، او پاسخ داد:\" همه امور بدان گونه که می نمایند نیستند.\"شب بعد، این دو فرشته به منزل یک خانواده فقیر ولی بسیار مهمان نواز رفتند.بعد از خوردن غذایی مختصر، زن و مرد فقیر، رختخواب خود را در اختیار دو فرشته گذاشتند. صبح روز بعد، فرشتگان، زن و مرد فقیر را گریان دیدند. گاو آنها که شیرش تنها وسیله گذران زندگیشان بود، در مزرعه مرده بود. فرشته جوان عصبانی شد و از فرشته پیر پرسید:\" چرا گذاشتی چنین اتفاقی بیفتد؟ خانواده قبلی همه چیز داشتند و با این حال تو کمکشان کردی، اما این خانواده دارایی اندکی دارند و تو گذاشتی که گاوشان هم بمیرد.\" فرشته پیر پاسخ داد:\"وقتی در زیر زمین آن خانواده ثروتمند بودیم، دیدم که در شکاف دیوار کیسه ای طلا وجود دارد. از آنجا که آنان بسیار حریص و بد دل بودند، شکاف را بستم و طلاها را از دیدشان مخفی کردم. دیشب وقتی در رختخواب زن و مرد فقیر خوابیده بودیم، فرشته مرگ برای گرفتن جان زن فقیر آمد و من به جایش آن گاو را به او دادم. همه امور بدان گونه که می نمایند نیستند و ما گاهی اوقات، خیلی دیر به این نکته پی می بریم.\""},{"id":2001,"category_id":2,"category_code":"s2","source_id":168,"title":"حکمت خداوند","content":"سالهای بسیار دور پادشاهی زندگی میكرد كه وزیری داشت.\r\nوزیر همواره می گفت: هر اتفاقی كه رخ میدهد به صلاح ماست.\r\nروزی پادشاه برای پوست كندن میوه كارد تیزی طلب كرد اما در حین بریدن میوه انگشتش را برید.\r\nوزیر كه در آنجا بود گفت: نگران نباشید تمام چیزهایی كه رخ میدهد در جهت خیر و صلاح شماست!\r\nپادشاه از این سخن وزیر برآشفت و از رفتار او در برابر این اتفاق آزرده خاطر شد و دستور زندانی كردن وزیر را داد...\r\nچند روز بعد پادشاه با ملازمانش برای شكار به نزدیكی جنگلی رفتند. پادشاه در حالی كه مشغول اسب سواری بود راه را گم كرد و وارد جنگل انبوهی شد و از ملازمان خود دور افتاد، در حالی كه پادشاه به دنبال راه بازگشت بود به محل سكونت قبیله ای رسید كه مردم آن در حال تدارك مراسم قربانی برای خدایانشان بودند، زمانی كه مردم پادشاه خوش سیما را دیدند خوشحال شدند زیرا تصور كردند وی بهترین قربانی برای تقدیم به خدای آنهاست!!!\r\n\r\nآنها پادشاه را در برابر تندیس الهه خود بستند تا وی را بكشند، اما ناگهان یكی از مردان قبیله فریاد كشید: چگونه میتوانید این مرد را برای قربانی كردن انتخاب كنید در حالی كه وی بدنی ناقص دارد، به انگشت او نگاه كنید!\r\nبه همین دلیل وی را قربانی نكردند و آزاد شد.\r\nپادشاه كه به قصر رسید وزیر را فراخواند و گفت: اكنون فهمیدم منظور تو از اینكه میگفتی هر چه رخ میدهد به صلاح شماست چه بوده زیرا بریده شدن انگشتم موجب شد زندگی ام نجات یابد اما در مورد تو چی؟\r\nتو به زندان افتادی این امر چه خیر و صلاحی برای تو داشت؟!\r\nوزیر پاسخ داد: پادشاه عزیز مگر نمیبینید، اگر من به زندان نمی افتادم مانند همیشه در جنگل به همراه شما بودم در آنجا زمانی كه شما را قربانی نكردند مردم قبیله مرا برای قربانی كردن انتخاب میكردند، بنابراین میبینید كه حبس شدن نیز برای من مفید بود\r\n"},{"id":2002,"category_id":2,"category_code":"s2","source_id":169,"title":"تقلای ترقی","content":"شخصی تلاش پروانه برای بیرون آمدن از سوراخ کوچک پیله را تماشا می کرد. ناگهان تقلای پروانه متوقف شد و به نظر رسید که خسته شده و دیگر نمی تواند به تلاشش ادامه دهد. آن شخص مصمم شد به پروانه کمک کند و با برش قیچی سوراخ پیله را گشاد کرد. پروانه به راحتی از پیله خارج شد اما جثه اش ضعیف و بال هایش چروکیده بودند. آن شخص به تماشای پروانه ادامه داد. او انتظار داشت پر پروانه گسترده و مستحکم شود و از جثه او محافظت کند اما چنین نشد. در واقع پروانه ناچار شد همه عمر را روی زمین بخزد. و هرگز نتوانست با بال هایش پرواز کند. آن شخص مهربان نفهمید که محدودیت پیله و تقلا برای خارج شدن از سوراخ ریز آن را خدا برای پروانه قرار داده بود تا به آن وسیله مایعی از بدنش ترشح شود و پس از خروج از پیله به او امکان پرواز دهد."},{"id":2003,"category_id":2,"category_code":"s2","source_id":170,"title":"زنجبر عشق","content":"یک روز بعد از ظهر وقتی اسمیت داشت از کار برمی گشت خانه، سر راه زن مسنی را دید که ماشینش خراب شده و ترسان توی برف ایستاده بود. اون زن برای او دست تکان داد تا متوقف شود. اسمیت پیاده شد و خودشو معرفی کرد و گفت من اومدم کمکتون کنم. زن گفت صدها ماشین از جلوی من رد شدند ولی کسی نایستاد، این واقعا لطف شماست.\r\nوقتی که او لاستیک رو عوض کرد و درب صندوق عقب رو بست و آماده رفتن شد، زن پرسید: «من چقدر باید بپردازم؟»\r\nو او به زن چنین گفت: «شما هیچ بدهی به من ندارید. من هم در این چنین شرایطی بوده ام. و روزی یکنفر هم به من کمک کرد، همونطور که من به شما کمک کردم. اگر تو واقعا می خواهی که بدهی ات رو به من بپردازی باید این کار رو بکنی. نگذار زنجیر عشق به تو ختم بشه!»\r\nچند مایل جلوتر زن کافه کوچکی رو دید و رفت تو تا چیزی بخوره و بعد راهشو ادامه بده ولی نتونست بی توجه از لبخند شیرین زن پیشخدمتی بگذره که می بایست هشت ماهه باردار باشه و از خستگی روی پا بند نبود. او داستان زندگی پیشخدمت رو نمی دانست واحتمالا هیچ گاه هم نخواهد فهمید. وقتی که پیشخدمت رفت تا بقیه صد دلارش رو بیاره، زن از در بیرون رفته بود، در حالی که بر روی دستمال سفره یادداشتی رو باقی گذاشته بود. وقتی پیشخدمت نوشته زن رو می خوند اشک در چشمانش جمع شده بود. در یادداشت چنین نوشته بود: «شما هیچ بدهی به من ندارید. من هم در این چنین شرایطی بوده ام. و روزی یک نفر هم به من کمک کرد، همون طور که من به شما کمک کردم. اگر تو واقعا می خواهی که بدهیت رو به من بپردازی، باید این کار رو بکنی. نگذار زنجیر عشق به تو ختم بشه!».\r\nهمان شب وقتی زن پیشخدمت از سرکار به خونه رفت، در حالی که به اون پول و یادداشت زن فکر می کرد به شوهرش گفت :«دوستت دارم اسمیت، همه چیز داره درست می شه».\r\n"},{"id":2004,"category_id":2,"category_code":"s2","source_id":171,"title":"فتح اورست","content":"سر ادموند هیلاری  نخستین کسی بود که در 29 ماه می سال 1953 از کوه اورست به عنوان مرتفع ترین کوه دنیا بالا رفت. با این حال مادامی که انسان اقدام به خواندن کتاب او تحت عنوان«مخاطره بزرگ» نکرده باشد، متوجه نمی شود که هیلاری برای تسخیر قله اورست ناگزیر از رشد کافی برای اجرای این امر خطیر برخوردار بوده است.\r\nجریان از این قرار است که هیلاری در سال 1952 کوشید که از کوه بالا رود، ولی نتوانست. یک هفته پس از این شکست گروهی از کوهنوردان انگلیسی از او خواستند که برای اعضای گروه آنها سخنرانی کند.\r\nهیلاری یا هلهله و کف زدن هایی پر سرو صدای حضار در پشت میکروفن قرار گرفت. سپس مشت گره کرده خود را به طرف نقشه کوه گرفت وبا صدای بلندی گفت: «ای اورست، تو بار اول مرا شکست دادی، ولی این بار منم که تو را شکست خواهم داد چون تو رشد کامل خودت را کرده ای اما من هنوز در حال رشد کردن هستم».\r\n"},{"id":2005,"category_id":2,"category_code":"s2","source_id":172,"title":"با ارزشترین چیز دنیا","content":"روزی فرشته ای از فرمان خدا سرپیچی کرد وبرای پاسخ دادن به عمل اشتباهش در مقابل تخت قضاوت احضار شد. فرشته از خداوند تقاضای بخشش کرد. خداوند با مهربانی نگاهی به فرشته انداخت و فرمود: من تورا تنبیه نمیکنم، ولی تو باید کفاره گناهت را بپردازی. کاری را به تو محول میکنم، به زمین برو و با ارزشترین چیز دنیا را برای من بیاور.\r\nفرشته خوشحال از اینکه فرصتی برای بخشوده شدن دارد به سرعت به سمت زمین رفت. سالها روی زمین به دنبال با ارزشترین چیز دنیا گشت. روزی به یک میدان جنگ رسید، سرباز جوانی رایافت که به سختی زخمی شده بود. مرد جوان دردفاع از کشورش با شجاعت جنگیده بود وحالا درحال مردن بود فرشته آخرین قطره از خون سرباز را برداشت وبا سرعت به بهشت باز گشت.\r\nخداوند فرمود: به راستی چیزی که تو آوردی باارزش است. سربازی که زندگیش را برای کشورش میدهد، برای من خیلی عزیز است، ولی برگرد وبیشتر بگرد.\r\nفرشته به زمین بازگشت وبه جستجوی خود ادامه داد. سالیان دراز در شهرها، جنگلها، ودشتها گردش کرد. سرانجام روزی در بیمارستان بزرگ پرستاری دید که بر اثر یک بیماری در حال مرگ بود.\r\nپرستار از افرادی مراقبت کرده بود که این بیماری را داشتند و آنقدر سخت کار کرده بودکه مقاومتش را از دست داده بود. پرستار رنگ پریده در تختخواب سفری خود خوابیده بود ونفس نفس میزد.\r\nدر حالی که پرستار نفسهای آخرش را میکشید، فرشته آخرین نفس پرستار را برداشت و به سرعت به سمت بهشت رفت.\r\nوبه خداوند گفت: خدوندا مطمئنم آخرین نفس این پرستار فداکار با ارزشترین چیزدر دنیاست. خداوند پاسخ داد: این نفس چیز با ارزشی است. کسی که زندگیش را برای دیگران میدهد، یقینا از نظر من با ارزش است. ولی برگرد ودوباره بگرد.\r\nفرشته برای جستجو ی دوباره به زمین بازگشت وسالیان زیادی گردش کرد.\r\nشبی مرد شروری را که براسبی سوار بود درجنگل یافت. مرد به شمشیر و نیزه مجهز بود. او میخواست از نگهبان جنگل انتقام بگیرد.\r\nمرد به کلبه کوچکی که جنگلبان وخانواده اش درآن زندگی میکردند، رسید. نور از پنجره بیرون میزد. مرد شرور از اسب پایین آمد و از پنجره داخل کلبه را بدقت نگاه کرد.\r\nزن جنگلبان را دیدکه پسرش را میخواباند و صدای اورا که به فرزندش دعای شب را یاد میداد، شنید. چیزی درون قلب سخت مرد، ذوب شد. آیا دوران کودکی خودش را بیاد آورده بود؟\r\nچشمان مرد پر از اشک شده بود وهمان جا از رفتار ونیت زشتش پشیمان شد و توبه کرد.\r\nفرشته قطره ای اشک از چشم مرد برداشت و به سمت بهشت پرواز کرد.\r\nخداوند فرمود:\r\nاین قطره اشک با ارزشترین چیز در دنیاست، برای اینکه این اشک آدمی است که توبه کرده و توبه درهای بهشت را باز میکند.\r\n"},{"id":2006,"category_id":2,"category_code":"s2","source_id":173,"title":"عابد و سگ","content":"روزی در زمانهای قدیم عابدی بود که روی یه کوهی زندگی می کرد. شبها عبادت میکرد و روزهاش رو روزه بود. اون پایین کوه نمی رفت و بین مردم شهر نمی گشت. هر روز برای این عابد ما یه قرص نون میومد. نصفش رو برای افطار می خورد و نصف دیگرش رو هم برای سحر نگه می داشت. روزها به همین منوال می گذشت تا اینکه یه شب نونی برای افطار عابد نرسید و برای سحر هم خبری از اون نون همیشگی نبود. گرسنگی امان عابد رو بریده بود. برای همین هم به روستایی که پایین کوه بود رفت. مردم اون روستا نصرانی بودند. عابد به یکی از خونه ها رفت و تقاضای غذا کرد. صاحبخانه دو قرص نون به عابد داد. وقتی عابد خواست خونه رو ترک کنه، سگ لاغر و لاجونی که جلوی در خونه اون فرد بود، دامن عابد رو کشید و عابد یکی از اون نان ها رو برای سگ انداخت. تا می خواست بره سگ دوباره دامن عابد رو گرفت و عابد قرص بعدی نون رو هم به سگ داد. داشت می رفت که دوباره سگ دامن عابد رو کشید و عابد برگشت و به سگ گفت:\r\nای بی حیا صاحب تو دو قرص نون به من داده، منم جفتش رو به تو دادم دیگه چی می خوای؟ سگ به اذن خدا به حرف اومد و گفت من از این خونه حفاظت می کنم و کارایی رو که به من مربوط میشه رو انجام میدم. اما صاحب این خونه وضع مالیه خوبی نداره. برای همین هم هر وفت که داشته باشن به من هم چیزی میدن تا بخورم. اما گاهاً میشه که چند روز به من غذا نمیدن، اما من هیچ وقت در این خونه رو رها نکردم. حالا من بی حیام یا تو که طاقت یه روز گرسنگی رو نداشتی و یه روز که قرص نونت نرسیده از خدا دل کندی و به دشمنت رو آوردی؟\r\nمرد عابد با شنیدن این سخنان منقلب شد و به عبادتگاه خویش بازگشت و توبه کرد.\r\n"},{"id":2007,"category_id":2,"category_code":"s2","source_id":174,"title":"چرا من؟","content":"آرتور اش قهرمان افسانه ای تنیس هنگامی که تحت عمل جراحی قلب قرار گرفت، با تزریق خون آلوده، به بیماری ایدز مبتلا شد.\r\nطرفداران آرتور از سر تا سر جهان نامه هایی محبت آمیز برایش فرستادند.\r\n\r\nیکی از دوستداران وی در نامه خویش نوشته بود: \"چرا خدا تو را برای ابتلا به چنین بیماری خطرناکی انتخاب کرده؟\" \r\nآرتور اش، در پاسخ این نامه چنین نوشت:\r\nدر سر تا سر دنیا بیش از پنجاه میلیون کودک به انجام بازی تنیس علاقه مند شده و شروع به آموزش می کنند.\r\nحدود پنج میلیون از آن ها بازی را به خوبی فرا می گیرند.\r\nاز آن میان قریب پانصد هزار نفر تنیس حرفه ای را می آموزند\r\nو شاید پنجاه هزار نفر در مسابقات شرکت می کنند\r\nپنج هزار نفر به مسابقات تخصصی تر راه می یابند.\r\nپنجاه نفر اجازه شرکت در مسابقات بین المللی ویمبلدون را می یابند.\r\nچهار نفر به مسابقات نیمه نهایی راه می یابند.\r\nو دو نفر به مسابقات نهایی.\r\nوقتی که من جام جهانی تنیس را در دست هایم می فشردم هرگز نپرسیدم که \"خدایا چرا من؟\"\r\nو امروز وقتی که درد می کشم، باز هم اجازه ندارم که از خدا بپرسم :\"چرا من؟ \"\r\n"},{"id":2008,"category_id":2,"category_code":"s2","source_id":175,"title":"چهار فصل زندگی","content":"مردی چهار پسر داشت.\r\nآنها را به ترتیب به سراغ درخت گلابی ای فرستاد که در فاصله ای دور از خانه شان روییده بود.\r\nپسر اول در زمستان، دومی در بهار، سومی در تابستان و پسر چهارم در پاییز به کنار درخت رفتند.\r\nسپس پدر همه را فراخواند و از آنها خواست که بر اساس آنچه دیده بودند درخت را توصیف کنند.\r\nپسر اول گفت: «درخت زشتی بود، خمیده و درهم پیچیده.» پسر دوم گفت: «نه… درختی پوشیده از جوانه بود و پر از امید شکفتن.»\r\nپسر سوم گفت: «نه… درختی بود سرشار از شکوفه های زیبا و عطرآگین… و با شکوه ترین صحنه ای بود که تا به امروز دیده ام.» پسر چهارم گفت: «نه!!! درخت بالغی بود پربار از میوه ها… پر از زندگی و زایش!»\r\nمرد لبخندی زد و گفت: «همه شما درست گفتید، اما هر یک از شما فقط یک فصل از زندگی درخت را دیده اید!\r\nشما نمی توانید درباره یک درخت یا یک انسان بر اساس یک فصل قضاوت کنید. \r\nوقتی میتوانید قضاوت کنید که همه فصل ها آمده و رفته باشند!\r\nاگر در زمستان تسلیم شوید، امید شکوفایی بهار، زیبایی تابستان و باروری پاییز را از کف داده اید!\r\nمبادا بگذاری درد و رنج یک فصل، زیبایی و شادی تمام فصل های دیگر را نابود کند!\r\nزندگی را فقط با فصل های دشوارش نبین؛ در راه های سخت پایداری کن. لحظه های بهتر بالاخره از راه می رسند...\r\n"},{"id":2009,"category_id":2,"category_code":"s2","source_id":176,"title":"کلنل ساندرس","content":"کلنل ساندرس یک روز در منزل نشسته بود در این میان نوه اش آمد و گفت: بابابزرگ این ماه برایم یک دوچرخه میخری؟\r\nاو نوه اش را خیلی دوست می داشت، گفت: حتماً عزیزم، حساب کرد ماهی ۵۰۰ دلار حقوق بازنشستگی میگیرم و حتی در مخارج خانه هم می مانم. شروع کرد به خواندن کتاب های موفقیت. در یکی از بندهای یک کتاب نوشته بود: قابلیت هایتان را روی کاغذ بنویسید. او شروع کرد به نوشتن. دوباره نوه اش آمد و گفت: بابا بزرگ داری چه کار می کنی؟\r\nپدربزرگ گفت: دارم کارهایی که بلدم را مینویسم. پسرک گفت: بابابزرگ بنویس مرغ های خوشمزه درست می کنی. درست بود.\r\nپیرمرد پودرهایی را درست می کرد که وقتی به مرغ ها میزد مزه مرغ ها شگفت انگیز می شد.\r\nاو راهش را پیدا کرد. پودر مرغ را برای فروش نزد اولین رستوران برد اما صاحب آنجا قبول نکرد، دومین رستوران نه، سومین رستوران نه، او به ۶۲۳ رستوران مراجعه کرد و ششصدوبیست و چهارمین رستوران حاضر شد از پودر مرغ استفاده کند.\r\nامروز کارخانه پودر مرغ کنتاکی در ۱۲۴ کشور دنیا نمایندگی دارد و اگر در آمریکا کسی بخواهد عکس کلنل ساندرس و پودر مرغ کنتاکی را جلوی در رستورانش بزند، باید ۵۰ هزار دلار به این شرکت پرداخت کند .\r\n"},{"id":2010,"category_id":2,"category_code":"s2","source_id":177,"title":"سلف سرویس","content":"وی که تا آن زمان هرگز به چنین رستورانی نرفته بود، در گوشه ای به انتظار نشست، با این نیت که از او پذیرایی شود. اما هرچه لحظات بیشتری سپری میشد، ناشکیبایی او از اینکه میدید پیشخدمتها کوچکترین توجهی به او ندارند، شدت گرفت. \r\nاز همه بدتر اینکه مشاهده میکرد کسانی که پس از او وارد شده بودند، در مقابل بشقابهای پر از غذا نشسته و مشغول خوردن بودند. \r\nوی با ناراحتی به مردی که بر سر میز مجاور نشسته بود،نزدیک شد و گفت: من حدود بیست دقیقه است که در اینجا نشسته ام بدون آنکه کسی کوچکترین توجهی به من نشان دهد. حالا میبینم شما که پنج دقیقه پیش وارد شدید، با بشقابی پر از غذا در مقابل من، اینجا نشسته اید! موضوع چیست؟ مردم این کشور چگونه پذیرایی میشوند؟ \r\nمرد با تعجب گفت: اینجا سلف سرویس است، سپس به قسمت انتهایی رستوران، جایی که غذاها به مقدار فراوان چیده شده بود، اشاره کرد و ادامه داد به آنجا بروید، یک سینی بردارید هر چه میخواهید انتخاب کنید، پول آنرا بپردازید، بعد اینجا بنشینید و آنرا میل کنید! امت فاکس که قدری احساس حماقت میکرد، دستورات مرد را پی گرفت، اما وقتی غذا را روی میز گذاشت، ناگهان به ذهنش رسید که زندگی هم در حکم سلف سرویس است. \r\nهمه نوع رخدادها، فرصتها، موقعیتها، شادیها، سرورها و غم ها در برابر ما قرار دارد،درحالی که اغلب ما بی حرکت به صندلی خود چسبیده ایم و آنچنان محو این هستیم که دیگران دربشقاب خود چه دارندودچار شگفتی شده ایم از اینکه چرا او سهم بیشتری دارد.وهرگز به ذهنمان نمیرسد خیلی ساده از جای خود برخیزیم و ببینیم چه چیزهایی فراهم است،سپس آنچه میخواهیم برگزینیم. \r\nوقتی زندگی چیز زیادی به شما نمیدهد، به دلیل آنست که شما هم چیز زیادی از او نخواسته اید \r\n"},{"id":2011,"category_id":2,"category_code":"s2","source_id":178,"title":"داستان قوم لوط","content":"امام باقر (ع) : قوم لوط بهترین خلق خدا بودند و یکی از کارهای نیک انها این بود که در انجام کارهای خیر با هم متحد بودند و همه اقدام به انجام ان کارها می کردند شیطان به اتحاد انها در کارهای نیک حسد برده و برای به انحراف کشیدن قوم لوط سعی فراوانی نموده و پی فرصتی مناسب می گشت که انها را فریب دهد تا اینکه به فکر افتاد که اول باید زراعت و کشاورزی مردم را خراب کند و میوه های انها را تباه کند \r\nو به این کار مشغول شد.مردم هر صبح که به باغ و مزرعه خود می رفتند مشاهده می کردند که زمینهایشان خراب و میوه هایشان تباه شده است. مردم باهم گفتند که:باید کمین کنیم و ان کسی را که زراعت ما را خراب می کند شناسایی و مجازات کنیم.\r\nوقتی کمین کردند،دیدند جوانی زیبا،خوشرو،و خوش لباس آمد و مشغول خراب کردن زراعت و میوه های انان شد مردم او را دستگیر کردند و گفتند:ای جوان آیا تو زراعت مارا خراب می کنی و حاصل مارا تباه می نمایی؟جوان با کمال جرات و شهامت و شجاعت گفت:بلی ،من هستم که هر شب باعث خرابی زمین و از بین رفتن محصول شما می باشم،مردم همه متفق القول شدند که باید این جوان خرابکار را به قتل برسانیم بنابر این او را به دست شخصی سپردند که شب از او نگبانی کندو فردا صبح جمع شوند و او را به قتل برسانند \r\nآن شخص جوان را به خانه بردند و در رختخوابی در خانه خود خواباند .نیمه شب ان جوان شروع به فریاد و گریه کرد و به صاحب خانه گفت :من هر شب روی شکم پدرم می خوابیدم و امشب تنها هستم و می ترسم .صاحب خانه هم بی خبر از همه چیز گفت:نترس،امشب بیا روی شکم من بخواب آن ملعون با صاحب خانه کاری کرد که او را مجبور به لواط نمود،اول دستور داد که صاحب خانه با او لواط کند و بعد هم خود با صاحب خانه لواط کرد و فرار نمود صبح مردم جمع شدند که جوان خراب کار را اعدام کنند صاحب خانه دستور داستان شب گذشته را برای آنها تعریف کرد.مردم این عمل را یاد گرفتند و با یک دیگر انجام دادند و کار به جایی رسید که زنان خود را رها کرده و هر کس وارد شهرشان می شد ،با او این عمل زشت را انجام میدادند وقتی شیطان متوجه شد که مردم به این عمل حیوانی عادت کردند و دیگر سراغ زنان خود نمی روند به فکر افتاد تا زنان آنها را هم منحرف گرداند.\r\nدر این جا بود که خود را شبیه زن زیبا و خوش قیافه در اورده امد پیش زنان ان شهر و گفت:شنیدم مردان شما زنان خود را رها کرده و با یک دیگر عمل ننگین لواط را انجام می دهند گفتن : آری چنین است مدتهاست که مردان ما سراغ ما دیگر نمی آیند و عمل زنا شویی مارا ترک کرده اند.بعد گفت اکنون که مردان شما با هم لواط میکنند شما نیز با هم مساحقه (هم جنس بازی) را انجام دهید و بعد زنان هم به این عمل عادت کردند و به موعظه ها و نصیحت حضرت لوط گوش ندادند ،خداوند ۳فرشته مقرب خود را یعنی میکائیل،جبرائیل،و اسرافیل را برای هلاکت انها فرستاد .این ۳فرشته هم نزدیکی های صبح شهر را به اسمان برده و رها کردند بعد از ان سنگ از اسمان بر انآن شهر به باریدن گرفت و همه به هلاکت رسیدند.\r\n"},{"id":2012,"category_id":2,"category_code":"s2","source_id":179,"title":"اعتقادت را چند میفروشی؟","content":"مبلغ اسلامی بود . در یکی از مراکز اسلامی لندن. \r\nعمرش را گذاشته بود روی این کار . \r\nتعریف می کرد که یک روز سوار تاکسی می شود و کرایه را می پردازد .\r\nراننده بقیه پول را که برمی گرداند .20 سنت اضافه تر میدهد می گفت: چند دقیقه ای با خودم کلنجار رفتم که بیست سنت اضافه را برگردانم یا نه. آخر سر بر خودم پیروز شدم و بیست سنت را پس دادم و گفتم آقا این را زیاد دادی ...\r\nگذشت و به مقصد رسیدیم . موقع پیاده شدن راننده سرش را بیرون آوردو گفت: آقا از شما ممنونم . پرسیدم بابت چی ؟\r\nگفت: می خواستم فردا بیایم مرکز شما و مسلمان شوم اما هنوز کمی مردد بودم. وقتی دیدم سوار ماشینم شدید خواستم شما را امتحان کنم. با خودم شرط کردم اگر بیست سنت را پس دادید بیایم. فردا خدمت میرسم\r\nتعریف می کرد: تمام وجودم دگرگون شد حالی شبیه غش به من دست داد . من مشغول خودم بودم در حالی که داشتم تمام اسلام را به بیست سنت می فروختم ..\r\n"},{"id":2013,"category_id":2,"category_code":"s2","source_id":180,"title":"همسایه فضول","content":"زن و مرد جوانی به محله جدیدی اسباب کشی کردند. روز بعد هنگام صرف صبحانه زن متوجه شد که همسایه اش در حال آویزان کردن رخت های شسته است.\r\nرو به همسرش کرد و گفت: لباس ها را چندان تمیز نشسته است. احتمالا بلد نیست لباس بشوید شاید هم باید پودرش را عوض کند.\r\nمرد هیچ نگفت.مدتی به همین منوال گذشت و هر بار که زن همسایه لباس های شسته را آویزان می کرد، او همان حرف ها را تکرار می کرد.\r\nیک روز با تعجب متوجه شد همسایه لباس های تمیز را روی طناب پهن کرده است به همسرش گفت: یاد گرفته چه طور لباس بشوید.\r\nمرد پاسخ داد: من امروز صبح زود بیدار شدم و پنجره هایمان را تمیز کردم!\r\n"},{"id":2014,"category_id":2,"category_code":"s2","source_id":181,"title":"فروش نظم","content":"سلطان عبدالحمید میرزا فرمانفرما(ناصرالدوله) هنگام تصدی ایالت کرمان چندین سفر به بلوچستان می رود و در یکی از این مسافرت ها چند تن از سرداران بلوچ از جمله سردار حسین خان را دستگیر و با غل و زنجیر روانه کرمان می کند.پسر خردسال سردار حسین خان نیز با پدر زندانی و در زیر یک غل بودند. چند روز بعد فرزند سردار حسین خان در زندان به دیفتری مبتلا می شود. سردار بلوچ هر چه التماس و زاری می کند که فرزند بیمار او را از زندان آزاد کنند تا شاید بهبود یابد ولی ترتیب اثر نمی دهند. \r\nسردار حسین خان به افضل الملک، ندیم فرمانفرما نیز متوسل می شود.افضل الملک نزد فرمانفرما می رود و وساطت می کند، اما باز هم نتیجه ای نمی بخشد. سردار حسین خان حاضر می شود پانصد تومان از تجار کرمان قرض کرده و به فرمانفرما بدهد تا کودک بیمار او را آزاد کند و افضل الملک این پیشنهاد را به فرمانفرما منعکس می کند، اما باز هم فرمانفرما نمی پذیرد. \r\nافضل الملک به فرمانفرما می گوید: قربان آخر خدایی هست،پیغمبری هست،ستم است که پسری درکنار پدر در زندان بمیرد.اگر پدر گناهکار است ،پسر که گناهی ندارد. فرمانفرما پاسخ می دهد: در مورد این مرد چیزی نگو که فرمانفرمای کرمان،نظم مملکت خود را به پانصد تومان رشوه سردار حسین خان نمی فروشد. \r\nهمان روز پسر خردسال سردار حسین خان در زندان در برابر چشمان اشکبار پدر جان می سپارد.دو سه روز پس از این ماجرا یکی از پسرهای فرمانفرما به دیفتری دچار می شود.هر چه پزشکان برای مداوای او تلاش می کنند اثری نمی بخشد.به دستور فرمانفرما پانصد گوسفند در آن روزها پی در پی قربانی می کنند و به فقرا می بخشند اما نتیجه ای نمی دهد و فرزند فرمانفرما جان می دهد. \r\nفرمانفرما در ایام عزای پسر خود،در نهایت اندوه بسر می برد.درهمین ایام روزی افضل الملک وارد اتاق فرمانفرما می شود.فرمانفرما به حالی پریشان به گریه افتاده و به صدایی بلند می گوید:\r\nافضل الملک!باور کن که نه خدایی هست و نه پیغمبری! والا اگر من قابل ترحم نبودم و دعای من موثر نبوده، لااقل به دعای فقرا و نذر و اطعام پانصد گوسفند می بایست فرزند من نجات می یافت. \r\nافضل الملک در حالی که فرمانفرما را دلداری می دهد می گوید:\r\nاین فرمایش را نفرمایید، چرا که هم خدایی هست و هم پیغمبری، اما می دانید که فرمانفرمای جهان نیز نظم مملکت خود را به پانصد گوسفند رشوه ی فرمانفرما ناصرالدوله نمی فروشد!\r\n"},{"id":2015,"category_id":2,"category_code":"s2","source_id":182,"title":"خوانساری و خراسانی","content":"\r\nروزی آقا حسین خوانساری که از مشاهیر دانشمندان است با ملا محمد باقر خراسانی به راهی می رفتند . شخصی خرس مرده بر خری بار کرده می گذشت . چون خر خراسان و خرس خوانسار شهرت دارد ، ملا باقر از راه ظرافت به آقا حسین گفت : \r\nجناب آقا ! ببینید ! \r\nآقا حسین مطلب او را دریافت و گفت : \r\nهنوز مردۀ ما بر زندۀ شما سوار است ! \r\n"},{"id":2016,"category_id":2,"category_code":"s2","source_id":183,"title":"گریه ی امیرکبیر","content":"هنگامى که خبر رسيد پنج نفر به علت ابتلا به بيمارى آبله جان باخته‌اند، امير بى‌درنگ فرمان داد هر کسى که حاضر نشود آبله بکوبد بايد پنج تومان به صندوق دولت جريمه بپردازد. او تصور مى کرد که با اين فرمان همه مردم آبله مى‌کوبند. اما نفوذ سخن دعانويس‌ها و نادانى مردم بيش از آن بود که فرمان امير را بپذيرند. شمارى که پول کافى داشتند، پنج تومان را پرداختند و از آبله‌کوبى سرباز زدند. شمارى ديگر هنگام مراجعه مأموران در آب انبارها پنهان مى‌شدند يا از شهر بيرون مى‌رفتند.\r\nروز بيست و هشتم ماه ربيع الاول به امير اطلاع دادند که در همه‌ى شهر تهران و روستاهاى پيرامون آن فقط سى‌صد و سى نفر آبله کوبيده‌اند. در همان روز، پاره دوزى را که فرزندش از بيمارى آبله مرده بود، به نزد او آوردند. امير به جسد کودک نگريست و آنگاه گفت: ما که براى نجات بچه‌هايتان آبله‌کوب فرستاديم. پيرمرد با اندوه فراوان گفت: حضرت امير، به من گفته بودند که اگر بچه را آبله بکوبيم جن زده مى‌شود. امير فرياد کشيد: واى از جهل و نادانى، حال، گذشته از اينکه فرزندت را از دست داده‌اى بايد پنج تومان هم جريمه بدهي. پيرمرد با التماس گفت: باور کنيد که هيچ ندارم. اميرکبير دست در جيب خود کرد و پنج تومان به او داد و سپس گفت: حکم برنمى‌گردد، اين پنج تومان را به صندوق دولت بپرداز.\r\nچند دقيقه ديگر، بقالى را آوردند که فرزند او نيز از آبله مرده بود. اين بار اميرکبير ديگر نتوانست تحمل کند. روى صندلى نشست و با حالى زار شروع به گريستن کرد. در آن هنگام ميرزا آقاخان وارد شد. او در کمتر زمانى اميرکبير را در حال گريستن ديده بود. علت را پرسيد و ملازمان امير گفتند که دو کودک شيرخوار پاره دوز و بقالى از بيمارى آبله مرده‌اند. ميرزا آقاخان با شگفتى گفت: عجب، من تصور مى‌کردم که ميرزا احمدخان، پسر امير، مرده است که او اين چنين هاى‌هاى مى‌گريد. سپس، به امير نزديک شد و گفت: گريستن، آن هم به اين گونه، براى دو بچه‌ى شيرخوار بقال و چقال در شأن شما نيست. امير سر برداشت و با خشم به او نگريست، آنچنان که ميرزا آقاخان از ترس بر خود لرزيد. امير اشک‌هايش را پاک کرد و گفت: خاموش باش. تا زمانى که ما سرپرستى اين ملت را بر عهده داريم، مسئول مرگشان ما هستيم. ميرزا آقاخان آهسته گفت: ولى اينان خود در اثر جهل آبله نکوبيده‌اند.\r\nامير با صداى رسا گفت: و مسئول جهلشان نيز ما هستيم. اگر ما در هر روستا و کوچه و خيابانى مدرسه بسازيم و کتابخانه ايجاد کنيم، دعانويس‌ها بساطشان را جمع مى‌کنند. تمام ايرانى‌ها اولاد حقيقى من هستند و من از اين مى‌گريم که چرا اين مردم بايد اين قدر جاهل باشند که در اثر نکوبيدن آبله بميرند.\r\n"},{"id":2017,"category_id":2,"category_code":"s2","source_id":184,"title":"بهترين خبر","content":"روزی روبرت دوونسنزو گلف باز بزرگ آرژانتینی، پس از بردن مسابقه و دریافت چک قهرمانی لبخند بر لب مقابل دوربین خبرنگاران وارد رختکن می شود تا آماده رفتن شود.\r\nپس از ساعتی، او داخل پارکینگ تک و تنها به طرف ماشینش می رفت که زنی به وی نزدیک می شود. زن پیروزیش را تبریک می گوید و سپس عاجزانه می افزاید که پسرش به خاطر ابتلا به بیماری سخت مشرف به مرگ است و او قادر به پرداخت حق ویزیت دکتر و هزینه بالای بیمارستان نیست.\r\nدو ونسنزو تحت تاثیر حرفهای زن قرار گرفت و چک مسابقه را امضا نمود و در حالی که آن را در دست زن می فشرد گفت: برای فرزندتان سلامتی و روزهای خوشی را آرزو می کنم.\r\nیک هفته پس از این واقعه دوونسنزو در یک باشگاه روستایی مشغول صرف ناهار بود که یکی از مدیران عالی رتبه انجمن گلف بازان به میز او نزدیک می شود و می گوید: هفته گذشته چند نفر از بچه های مسئول پارکینگ به من اطلاع دادند که شما در آنجا پس از بردن مسابقه با زنی صحبت کرده اید. می خواستم به اطلاعتان برسانم که آن زن یک کلاهبردار است. او نه تنها بچه مریض و مشرف به مرگ ندارد، بلکه ازدواج هم نکرده. او شما را فریب داده، دوست عزیر!\r\nدو ونسزو می پرسد: منظورتان این است که مریضی یا مرگ هیچ بچه ای در میان نبوده است؟\r\nبله کاملا همینطور است.\r\nدو ونسزو می گوید: در این هفته، این بهترین خبری است که شنیدم.\r\n"},{"id":2018,"category_id":2,"category_code":"s2","source_id":185,"title":"قیمت معجزه!","content":"وقتي سارا دخترک هشت ساله اي بود، شنيد که پدر ومادرش درباره برادر کوچکترش صحبت مي کنند. فهميد برادرش سخت بيمار است و آنها پولي براي مداواي او ندارند. پدر به تازگي کارش را از دست داده بود و نمي توانست هزينه جراحي پرخرج برادر را بپردازد. سارا شنيد که پدر آهسته به مادر گفت: فقط معجزه مي تواند پسرمان را نجات دهد. سارا با ناراحتي به اتاق خوابش رفت و از زير تخت، قلک کوچکش را درآورد. قلک را شکست، سکه ها را روي تخت ريخت و آنها را شمرد، فقط 5 دلار. بعد آهسته از در عقبي خانه خارج شد و چند کوچه بالاتر به داروخانه رفت. جلوي پيشخوان انتظار کشيد تا داروساز به او توجه کند ولي داروساز سرش شلوغ تر از آن بود که متوجه بچه اي هشت ساله شود. دخترک پاهايش را به هم مي زد و سرفه مي کرد، ولي داروساز توجهي نمي کرد، بالاخره حوصله سارا سر رفت و سکه ها را محکم روي شيشه پيشخوان ريخت. داروساز جا خورد، رو به دخترک کرد و گفت: چه مي خواهي؟ دخترک جواب داد: برادرم خيلي مريض است، مي خواهم معجزه بخرم. داروساز با تعجب پرسيد: ببخشيد؟!! دختـرک توضيح داد: برادر کوچک من، داخل سـرش چيزي رفته و بابايم مي گويـد که فقط معجـزه مي تواند او را نجات دهد، من هم مي خواهم معجزه بخرم، قيمتش چقدر است؟ داروساز گفت: متاسفم دخترجان، ولي ما اينجا معجزه نمي فروشيم. چشمان دخترک پر از اشک شد و گفت: شما را به خدا، او خيلي مريض است، بابايم پول ندارد تا معجزه بخرد اين هم تمام پول من است، من کجا مي توانم معجزه بخرم؟ مردي که گوشه ايستاده بود و لباس تميز و مرتبي داشت، از دخترک پرسيد: چقدر پول داري؟ دخترک پول ها را کف دستش ريخت و به مرد نشان داد. مرد لبخنـدي زد و گفت: آه چه جالب، فکـر مي کنم اين پول براي خريد معجزه برادرت کافي باشد! بعد به آرامي دست او را گرفت و گفت: من مي خواهم برادر و والدينت را ببينم، فکر مي کنم معجزه برادرت پيش من باشد. آن مرد ، دکتر آرمسترانگ فوق تخصص مغز و اعصاب در شيکاگو بود. فرداي آن روز عمل جراحي روي مغز پسرک با موفقيت انجام شد و او از مرگ نجات يافت. پس از جراحي، پدر نزد دکتـر رفت و گفت: از شما متشکـرم، نجات پسرم يک معجـزه واقعـي بود، مي خواهم بدانم بابت هزينه عمل جراحي چقدر بايد پرداخت کنم؟ دکتر لبخندي زد و گفت: پنج دلار بود که پرداخت شد . "},{"id":2019,"category_id":2,"category_code":"s2","source_id":186,"title":"در پی خوشبختی","content":"مرد، دوباره آمد همانجای قدیمی روی پله های بانک، توی فرو رفتگی دیوار یک جایی شبیه دل خودش، کارتن را انداخت روی زمین، دراز کشید، کفشهایش را گذاشت زیر سرش، کیسه را کشید روی تنش، دستهایش را مچاله کرد لای پاهایش…\r\nخیابان ساکت بود، فکرش را برد آن دورها، کبریت های خاطرش را یکی یکی آتش زد.\r\nدر پس کورسوی نور شعله های نیمه جان ، خنده ها را میدید و صورت ها را صورتها مات بود و خنده ها پررنگ ، هوا سرد بود، دستهایش سردتر، مچاله تر شد، باید زودتر خوابش میبرد\r\nصدای گام هایی آمد و .. رفت، مرد با خودش فکر کرد، خوب است که کسی از حال دلش خبر ندارد، خنده ای تلخ ماسید روی لبهایش.\r\nاگر کسی می فهمید او هم دلی دارد خیلی بد میشد، شاید مسخره اش می کردند، مرد غرور داشت هنوز، و عشق هم داشت، معشوقه هم داشت، فاطمه، دختری که آن روزهای دور به مرد می خندید، به روزی فکر کرد که از فاطمه خداحافظی کرده بود برای آمدن به شهر…\r\nگفته بود: بر میگردم با هم عروسی می کنیم فاطی، دست پر میام …فاطمه باز هم خندیده بود.\r\nآمد شهر، سه ماه کارگری کرد، برایش خبر آوردند فاطمه خواستگار زیاد دارد، خواستگار شهری، خواستگار پولدار، تصویر فاطمه آمد توی ذهنش، فاطمه دیگر نمی خندید…\r\nآگهی روی دیوار را که دید تصمیمش را گرفت، رفت بیمارستان ، کلیه اش را داد و پولش را گرفت ، مثل فروختن یک دانه سیب بود…!!!\r\nحساب کرد ، پولش بد نبود ، بس بود برای یک عروسی و یک شب شام و شروع یک کاسبی!!!\r\nپیغام داد به فاطمه بگویند دارد برمیگردد…\r\nیک گردنبند بدلی هم خرید، پولش به اصلش نمی رسید، پولها را گذاشت توی بقچه، شب تا صبح خوابش نبرد.\r\nصبح توی اتوبوس بود، کنارش یک مرد جوان نشست.\r\n- داداش سیگار داری؟\r\nسیگاری نبود، جوان اخم کرد.\r\nنیمه های راه خوابش برد، خواب میدید فاطمه می خندد، خودش می خندد، توی یک خانه یک اتاقه و گرم…\r\n\r\nچشم باز کرد ، کسی کنارش نبود ، بقچه پولش هم نبود ، سرش گیج رفت ، پاشد :\r\n- پولام .. پولاااام .\r\nصدای مبهم دلسوزی می آمد ،\r\n- بیچاره ،\r\n- پولات چقد بود؟\r\n- حواست کجاست عمو؟\r\nپیاده شد ، اشکش نمی آمد ، بغض خفه اش می کرد ، نشست کنار جاده ، از ته دل فریاد کشید، جای بخیه های روی کمرش سوخت.\r\nبرگشت شهر، یکهفته از این کلانتری به آن پاسگاه، بیهوده و بی سرانجام ، کمرش شکست ، دل برید ، با خودش میگفت کاشکی دل هم فروشی بود.\r\n…\r\n- پاشو داداش ، پاشو اینجا که جای خواب نیس …\r\nچشمهاشو باز کرد ، صبح شده بود ، تنش خشک شده بود ،خودشو کشید کنار پله ها و کارتن رو جمع کرد.\r\nدر بانک باز شد ، حال پا شدن نداشت ، آدم ها می آمدند و می رفتند.\r\n- داداش آتیش داری؟\r\nصدا آشنا بود، برگشت، خودش بود ، جوان توی اتوبوس ، وسط پیاده رو ایستاده بود ، چشم ها قلاب شد به هم ، فرصت فکر کردن نداشت ، با همه نیرویی که داشت خودشو پرتاب کرد به سمت جوان دزد.\r\n- آی دزد ، آیییییی دزد ، پولامو بده ، نامرد خدانشناس … آی مردم …\r\nجوان شناختش.\r\n- ولم کن مرتیکه گدا ، کدوم پولا ، ولم کن آشغال …\r\nپهلوی چپش داغ شد ، سوخت ، درست جای بخیه ها ، دوباره سوخت ، و دوباره ….افتاد روی زمین.\r\nجوان دزد فرار کرد.\r\n- آییی یی یییییی\r\nمردم تازه جمع شده بودند برای تماشا، دستش را دراز کرد به سمت جوان که دور و دور تر میشد ،\r\n- بگیریتش .. پو . ل .. ام\r\nصدایش ضعیف بود ، صدای مبهم دلسوزی می آمد :\r\n- چاقو خورده …\r\n- برین کنار .. دس بهش نزنین …\r\n- گداس؟\r\n- چه خونی ازش میره …\r\nدستش را گذاشت جای خالیه کلیه اش ، دستش داغ شد\r\nچاقوی خونی افتاده بود روی زمین ، سرش گیج رفت ، چشمهایش را بست و … بست .\r\nنه تصویر فاطمه را دید نه صدای آدم ها را شنید ، همه جا تاریک بود … تاریک .\r\nهمه زندگی اش یک خبر شد توی روزنامه : یک کارتن خواب در اثر ضربات متعدد چاقو مرد . همین…\r\nهیچ آدمی از حال دل آدم دیگری خبر ندارد ، نه کسی فهمید مرد که بود، نه کسی فهمید فاطمه چه شد ؛مثل خط خطی روی کاغذ سیاه می ماند زندگی…\r\nبالاتر از سیاهی که رنگی نیست ، انگار تقدیرش همین بود که بیاید و کلیه اش را بفروشد به یک آدم دیگر ، شاید فاطمه هم مرده باشد ، شاید آن دنیا یک خانه یک اتاقه گرم گیرشان بیاید و مثل آدم زندگی کنند ، کسی چه میداند ؟!\r\nکسی چه رغبتی دارد که بداند ؟\r\nزندگی با ندانستن ها شیرین تر می شود ، قصه آدم ها ، مثل لالایی نیست\r\nقصه آدم ها ، قصیده غصه هاست …\r\n"},{"id":2020,"category_id":2,"category_code":"s2","source_id":187,"title":"ملاقات مدیر","content":"یک روز خانم مسنی با یک کیف پر از پول به یکی از شعب بزرگترین بانک کانادا مراجعه نمود و حسابی با موجودی ۱ میلیون دلار افتتاح کرد .\r\nسپس به رئیس شعبه گفت به دلایلی مایل است شخصاً مدیر عامل آن بانک را ملاقات کند و طبیعتاً به خاطر مبلغ هنگفتی که سپرده گذاری کرده بود ، تقاضی او مورد پذیرش قرار گرفت قرار ملاقاتی با مدیر عامل بانک برای آن خانم ترتیب داده شد . پیرزن در روز تعیین شده به ساختمان مرکزی بانک رفت و به دفتر مدیر عامل راهنمائی شد . مدیر عامل به گرمی به او خوشامد گفت و دیری نگذشت که آن دو سرگرم گپ زدن پیرامون موضوعات متنوعی شدند . تا آنکه صحبت به حساب بانکی پیرزن رسید و مدیر عامل با کنجکاوی پرسید راستی این پول زیاد داستانش چیست یا به تازگی به شما ارث رسیده است . زن در پاسخ گفت خیر ، این پول را با پرداختن به سرگرمی مورد علاقه ام که همانا شرط بندی است ، پس انداز کرده ام . پیرزن ادامه داد و از آنجائی که این کار برای من به عادت بدل شده است ، مایلم از این فرصت استفاده کنم و شرط ببندم که شما شکم دارید !\r\nمرد مدیر عامل که اندامی لاغر و نحیف داشت با شنیدن آن پیشنهاد بی اختیار به خنده افتاد و مشتاقانه پرسید مثلاً سر چه مقدار پول . زن پاسخ داد ۲۰ هزار دلار و اگر موافق هستید ، من فردا ساعت ۱۰ صبح با وکیلم در دفتر شما حاضر خواهم شد تا در حضور او شرط بندی مان را رسمی کنیم و سپس ببینیم چه کسی برنده است . مرد مدیر عامل پذیرفت و از منشی خود خواست تا برای فردا ساعت ۱۰ صبح برنامه ای برایش نگذارد .\r\nروز بعد درست سر ساعت ۱۰ صبح آن خانم به همراه مردی که ظاهراً وکیلش بود در محل دفتر مدیر عامل حضور یافت . پیرزن بسیار محترمانه از مرد مدیر عامل خواست کرد که در صورت امکان پیراهن و زیر پیراهن خود را از تن به درآورد . مرد مدیر عامل که مشتاق بود ببیند سرانجام آن جریان به کجا ختم می شود ، با لبخندی که بر لب داشت به درخواست پیرزن عمل کرد .\r\nوکیل پیرزن با دیدن آن صحنه عصبانی و آشفته حال شد . مرد مدیر عامل که پریشانی او را دید ، با تعجب از پیر زن علت را جویا شد . پیرزن پاسخ داد من با این مرد سر ۱۰۰ هزار دلار شرط بسته بودم که کاری خواهم کرد تا مدیر عامل بزرگترین بانک کانادا در پیش چشمان ما پیراهن و زیر پیراهن خود را از تن بیرون کند !\r\n"},{"id":2021,"category_id":2,"category_code":"s2","source_id":188,"title":"کشیش و راهب","content":"یه روز یه کشیش به یه راهبه پیشنهاد می کنه که با ماشین برسوندش به مقصدش\r\nراهبه سوار میشه و راه میفتن\r\nچند دقیقه بعد راهبه پاهاش رو روی هم میندازه و کشیش زیر چشمی یه نگاهی به پای راهبه میندازه\r\nراهبه میگه: پدر روحانی، روایت مقدس ۱۲۹ رو به خاطر بیار …!\r\nکشیش قرمز میشه و به جاده خیره میشه\r\nچند دقیقه بعد بازم شیطون وارد عمل میشه و کشیش موقع عوض کردن دنده، بازوش رو با پای راهبه تماس میده …!\r\nراهبه باز میگه: پدر روحانی! روایت مقدس ۱۲۹ رو به خاطر بیار!!!\r\nکشیش زیر لب یه فحش میده و بیخیال میشه و راهبه رو به مقصدش می رسونه\r\nبعد از اینکه کشیش به کلیسا بر می گرده سریع میدوه و از توی کتاب روایت مقدس ۱۲۹ رو پیدا می کنه و می بینه که نوشته: به پیش برو و عمل خود را پیگیری کن… کار خود را ادامه بده و بدان که به جلال و شادمانی که می خواهی میرسی!!!\r\nنتیجه اخلاقی : اگه توی شغلت از اطلاعات شغلی خودت کاملا آگاه نباشی، فرصتهای بزرگی رو از دست میدی !\r\n"},{"id":2022,"category_id":2,"category_code":"s2","source_id":189,"title":"هزار دلاری","content":"\r\nبلافاصله بعد از اینکه زن پیتر از زیر دوش حمام بیرون اومد پیتر وارد حمام شد\r\nهمون موقع زنگ در خونه به صدا در اومد\r\nزن پیتر یه حوله دور خودش پیچید و رفت تا در رو باز کنه\r\nهمسایه شون -رابرت- پشت در ایستاده بود\r\nتا رابرت زن پیتر رو دید گفت: همین الان ۱۰۰۰ دلار بهت میدم اگه اون حوله رو بندازی زمین!\r\nبعد از چند لحظه، زن پیتر حوله رو میندازه و رابرت چند ثانیه تماشا می کنه و ۱۰۰۰ دلار به زن پیتر میده و میره …!\r\nزن دوباره حوله رو دور خودش پیچید و برگشت\r\nپیتر پرسید: کی بود زنگ زد؟ زن جواب داد: رابرت همسایه مون بود\r\nپیتر گفت: خوبه… چیزی در مورد ۱۰۰۰ دلاری که به من بدهکار بود گفت؟!\r\nنتیجه اخلاقی : اگه شما اطلاعات حساس مشترک با کسی دارید که به اعتبار و آبرو مربوط میشه، همیشه باید در وضعیتی باشید که بتونید از اتفاقات قابل اجتناب جلوگیری کنید !\r\n"},{"id":2023,"category_id":2,"category_code":"s2","source_id":190,"title":"رفاقت مردانه","content":"\r\nیه شب خانم خونه به خونه بر نمیگرده و تا صبح پیداش نمیشه!\r\nصبح بر میگرده خونه و به شوهرش میگه که دیشب مجبور شده خونه یکی از دوستهای صمیمیش (مونث) بمونه\r\nشوهر بر میداره به ۲۰ تا از صمیمی ترین دوستهای زنش زنگ میزنه ولی هیچکدومشون حرف خانم خونه رو تایید نمیکنن!\r\nیه شب آقای خونه تا صبح برنمیگرده خونه. صبح وقتی میاد به زنش میگه که دیشب مجبور شده خونه یکی از دوستهای صمیمیش (مذکر) بمونه\r\nخانم خونه بر میداره به ۲۰ تا از صمیمی ترین دوستهای شوهرش زنگ میزنه : ۱۵ تاشون تایید میکنن که آقا تمام شب رو خونه ی اونا مونده! ۵ تای دیگه حتی میگن که آقا هنوزم خونه اونا پیش اوناست !!!\r\nنتیجه اخلاقی : یادتون باشه که مردها دوستهای بهتری برای همدیگه هستند !\r\n"},{"id":2024,"category_id":2,"category_code":"s2","source_id":191,"title":"پاره آجر","content":"روزی مردی ثروتمند در اتومبیل جدید و گران قیمت خود با سرعت فراوان از خیابان کم رفت و آمدی می گذشت.\r\nناگهان از بین دو اتومبیل پارک شده در کنار خیابان یک پسر بچه پاره آجری به سمت او پرتاب کرد. پاره آجر به اتومبیل او برخورد کرد!\r\nمرد پایش را روی ترمز گذاشت و سریع پیاده شد و دید که اتومبیلش صدمه زیادی دیده است. به طرف پسرک رفت و او را سرزنش کرد.\r\nپسرک گریان با تلاش فراوان بالاخره توانست توجه مرد را به سمت پیاده رو، جایی که برادر فلجش از روی صندلی چرخدار به زمین افتاده بود جلب کند.\r\nپسرک گفت: “اینجا خیابان خلوتی است و به ندرت کسی از آن عبور می کند. برادر بزرگم از روی صندلی چرخدارش به زمین افتاده و من زور کافی برای بلند کردنش ندارم”.\r\n“برای اینکه شما را متوقف کنم ناچار شدم از این پاره آجر استفاده کنم”.\r\nمرد بسیار متاثر شد و از پسر عذر خواهی کرد. برادر پسرک را بلند کرد و روی صندلی نشاند و سوار اتومبیل گرانقیمتش شد و به راهش ادامه داد …\r\nنتیجه اخلاقی : خدا در روح ما زمزمه می کند و با قلب ما حرف می زند. اما بعضی اوقات زمانی که وقت نداریم به ندای قلبمان گوش کنیم، او مجبور می شود بگونه ای عمل کند که شاید به مزاقمان خوش نیاید …\r\n"},{"id":2025,"category_id":2,"category_code":"s2","source_id":192,"title":"نصفه شب","content":"\r\nساعت ۳ شب بود که صدای تلفن , پسری را از خواب بیدار کرد.\r\nپشت خط مادرش بود .پسر با عصبانیت گفت: چرا این وقت شب مرا از خواب بیدار کردی؟\r\nمادر گفت : ۲۵ سال قبل در همین موقع شب تو مرا از خواب بیدار کردی\r\nفقط خواستم بگویم تولدت مبارک .\r\nپسر از اینکه دل مادرش را شکسته بود تا صبح خوابش نبرد\r\nصبح سراغ مادرش رفت . وقتی داخل خانه شد مادرش را پشت میز تلفن\r\nبا شمع نیمه سوخته یافت… ولی مادر دیگر در این دنیا نبود . . .\r\n"},{"id":2026,"category_id":2,"category_code":"s2","source_id":193,"title":"رییس جوان قبیله","content":"\r\nمردان قبیله از رییس جدید می پرسند:\r\n«آیا زمستان سختی در پیش است؟»\r\nرییس جوان قبیله که هیچ تجربه‌ای در این زمینه نداشت، جواب میده «برای احتیاط برید هیزم تهیه کنید»\r\nبعد میره به سازمان هواشناسی کشور زنگ میزنه: «آقا امسال زمستون سردی در پیشه؟»\r\nپاسخ: «اینطور به نظر میاد»\r\nپس رییس به مردان قبیله دستور میده که بیشتر هیزم جمع کنند\r\nو برای اینکه مطمئن بشه یه بار دیگه به سازمان هواشناسی زنگ میزنه:\r\n«شما نظر قبلیتون رو تایید می کنید؟» پاسخ: «صد در صد»\r\nرییس به همه افراد قبیله دستور میده که تمام توانشون رو برای جمع آوری هیزم بیشتر صرف کنند.\r\nبعد دوباره به سازمان هواشناسی زنگ میزنه: «آقا شما مطمئنید که امسال زمستان سردی در پیشه؟»\r\nپاسخ: بگذار اینطوری بگم؛ سردترین زمستان در تاریخ معاصر!!!\r\nرییس: «از کجا می دونید؟»\r\n>> پاسخ: «چون سرخ پوست ها دیوانه وار دارن هیزم جمع می کنن!!\r\nخیلی وقتها ما خودمان مسبب وقایع اطرافمان هستیم.\r\n"},{"id":2027,"category_id":2,"category_code":"s2","source_id":194,"title":"شغال و روباه","content":"شغالی مرغی از خانه پیر زنی دزدید. پیر زن در عقب او نفرین کنان فریاد میکرد : ای وای! مرغ دو منی مرا شغال برد . شغال از این مبالغه سخت در غضب شد و از غایت تعجّب و غضب به پیر زن دشنام داد . در آن میان روباهی به شغال رسید و گفت : چرا این قدر بر افروخته ای ؟ گفت : ببین این پیرزن چه قدر چقدر دروغگو و بی انصاف است . مرغی را که یک چارک هم نمیشود دو من میخواند . روباه گفت : بده ببینم چه قدر سنگین است ! وقتی مرغ را گرفت روی به گریز نهاد و گفت : به پیرزن بگو مرغ را به پای من چهار من حساب کند ."},{"id":2028,"category_id":2,"category_code":"s2","source_id":195,"title":"غسل دیوانه!","content":"مردی از فقیهی پرسید : من هنگامی که جهت غسل در نهر آب فرو می روم و سه مرتبه تکرار می کنم و یقین نمی کنم که آب تمام بدن را فرا گرفته یا نه چه چاره سازم ؟ \r\nفقیه گفت نماز نخوان.\r\nآن مرد با تعجب گفت: از کجا می گویی ؟\r\nفقیه گفت از قول رسول اکرم (ص) که فرمود: \" واجبات از دیوانه برداشته شده تا موقعی که از دیوانگی خارج شود. \"\r\nهر کسی که سه مرتبه درآب فرو رود و یقین نکند که غسل کرده مجنون است.\r\n"},{"id":2029,"category_id":2,"category_code":"s2","source_id":196,"title":"گوش ما پر است","content":"گویند مردی بر لب رودخانه رخت می شست. ناگهان شتری را دید که به سوی او می آید. \r\nبرفور تشت را واژگون کرد، و برای ترساندن شتر به تشت کوبی پرداخت. \r\nشتر در حالیکه به آرامی از کنار وی عبور میکرد گفت: برادر! بیخود به خودت زحمت مده، من شتر نقاره خانه ام از این سروصداها بسیار شنیده ام!\r\n"},{"id":2030,"category_id":2,"category_code":"s2","source_id":197,"title":"هزینه ی امیدواری دادن!","content":"بزرگمهر حکیم در کشتی نشسته بود که طوفان شد ناخدا گفت که دیگر امیدی نیست و باید دعا کرد مسافران همه نگران بودند اما بزرگمهر آرام نشسته بود گفتند در این وقت چرا اینگونه آرامی او گفت نگران نباشید زیرا مطمئنم که نجات پیدا میکنیم وهمانگونه شد که او گفته بود و کشتی به سلامت به ساحل رسید مسافرین دور بزرگمهر حلقه زدند که تو پیامبری یا جادوگر !!! از کجا میدانستی که نجات پیدا میکنیم بزرگمهر گفت: من هم مثل شما نمدانستم اما گفتم بگذار به اینها امیدواری بدهم چرا که اگر نجات نیافتیم دیگر من و شما زنده نیستیم که بخواهید مرا مواخذه کنید."},{"id":2031,"category_id":2,"category_code":"s2","source_id":198,"title":"ربا","content":"زاهدی مهمان پادشاهی بود.چون بنشستند ، کم تر از آ ن خورد که ارادت او بود و چون به نماز برخاستند ، بیشتر \r\nاز آن کرد که عادت او ، تاظن صلاح درحق او زیادت کنند.\r\n\" ترسم نرسی به کعبه ای اعرابی\r\nکاین ره که تو می روی به ترکستان است\"\r\nچون به مقام خویش باز آمد، سفره خواست تا تناولی کند.\r\nپسری داشت صاحب فراست\"گفت: ای پدر , باری به دعوت سلطان در طعام نخوردی؟ گفت : در نظر ایشان چیزی \r\nنخوردم که به کار آید ، گفت:\"نماز راهم قضا کن که چیزی نکردی که به کارآید\" \r\nگلستان سعدی\r\n"},{"id":2032,"category_id":2,"category_code":"s2","source_id":199,"title":"سبد گردو","content":"حکایت میکنند که روزی مردی ثروتمند سبدی بزرگ را پر از گردو کرد، آن را پشت اسب گذاشت و وارد بازار دهکده شد، سپس سبد را روی زمین گذاشت و به مردم گفت این سبد گردو را هدیه میدهم به مردم این دهکده، فقط در صف بایستید و هر کدام یک گردو بردارید. به اندازه تعداد اهالی، گردو در این سبد است و به همه می‌رسد.\"\r\n\r\nمرد ثروتمند این را گفت و رفت. مردم دهکده پشت سر هم صف ایستادند و یکی‌یکی از داخل سبد گردو برداشتند. پسربچه باهوشی هم در صف ایستاد. اما وقتی نوبتش رسید در کنار سبد ایستاد و نوبتش را به نفر بعدی داد. به این ترتیب هر کسی یک گردو برمی‌داشت و پی کار خود می‌رفت. مردی که خیلی احساس زرنگی می‌کرد با خود گفت: \"نوبت من که رسید دو تا گردو برمی‌دارم و فرار می‌کنم. در نتیجه به این پسر باهوش چیزی نمی‌رسد.\"\r\n\r\nاو چنین کرد و دو گردو برداشت و در لابه‌لای جمعیت گم شد. سرانجام وقتی همه گردوهایشان را گرفتند و رفتند، پسرک با لبخند سبد را از روی زمین برداشت و بر دوش خود گذاشت و گفت: \"من از همان اول گردو نمی‌خواستم این سبد ارزشی بسیار بیشتر از همه گردوها دارد.\" این را گفت و با خوشحالی راهی منزل خود شد.\r\n\r\nخیلی‌ها دلشان به گردوبازی خوش است و از این غافلند که آنچه گرانبهاست و ارزش بسیار بیشتری دارد سبدی است که این گردوها در آن جمع شده‌اند. خیلی‌ها قدر خانواده و همسر و فرزند خود را نمی‌دانند و دایم با آنها کلنجار می‌روند و از این نکته طلایی غافلند که این سبدی که این افراد را گرد هم و به اسم خانواده جمع کرده ارزشی به مراتب بیشتراز لجاجت‌ها و جدل‌های افراد خانواده دارد. خیلی‌ها وقتی در شرکت یا موسسه‌ای کار می‌کنند سعی دارند تک‌خوری کنند و در حق بقیه نفرات مجموعه ظلم روا دارند و فقط سهم بیشتری به دست آورند. آنها از این نکته ظریف غافلند که تیمی که در قالب شرکت، آنها را گرد هم جمع کرده مانند سبدی است که گردوها را در خود نگه می‌دارد و حفظ این سبد و تیم به مراتب بیشتر از چند گردوی اضافه است.\r\n\r\nبسیاری اوقات در زندگی گردوها آنقدر انسان را به خود سرگرم می‌کنند که فرد اصلا متوجه نمی‌شود به خاطر لجاجت و یا یکدندگی و کله‌شقی و تعصب و خودخواهی فردی و گروهی در حال از دست دادن سبد نگهدارنده گردوهاست و وقتی سبد از هم می‌پاشد و گردوها روی زمین ولو می‌شوند و هر کدام به سویی می‌روند، تازه می‌فهمند که نقش سبد در این میان چقدر تعیین‌کننده بوده است.\r\n\r\nبیایید در هر جمعی که هستیم سبد و تور نگهدارنده اصلی را ببینیم و آن را قدر نهیم و نگذاریم تار و پود سبد ضعیف شود. چرا که وقتی این تور نگهدارنده از هم بپاشد دیگر هیچ چیزی در جای خود بند نخواهدشد و به هیچ‌کس سهم شایسته و درخورش نخواهد رسید. دیگر فرصت‌ها برابر در اختیار کسی قرار نخواهد گرفت و آرامش و قراری که در یک چهارچوب محکم و استوار قابل حصول است به دست نخواهد آمد.\r\n"},{"id":2033,"category_id":2,"category_code":"s2","source_id":200,"title":"افسوس خوردن","content":"\r\nشیخی\r\nلطیفه ای برای حضار تعریف کرد همه دیوانه وار خندیدند.\r\nبعد از لحظه ای او دوباره همان لطیفه را گفت و تعداد کمتری از حضار خندیدند.\r\nاو مجدد لطیفه را تکرار کرد تا اینکه دیگر کسی در جمعیت به آن لطیفه نخندید.\r\nاو لبخندی زد و گفت:\r\nوقتی که نمیتوانید بارها و بارها به لطیفه ای یکسان بخندید،\r\nپس چرا بارها و بارها به گریه و افسوس خوردن در مورد مسئله ای مشابه ادامه میدهید؟\r\nگذشته را فراموش کنید و به جلو نگاه کنید ...\r\n"},{"id":2034,"category_id":2,"category_code":"s2","source_id":201,"title":"کاسه ی عسل","content":"آورده اند که:\r\n«جوحی»در کودکی چند روز شاگرد خیاطی بود.روزی استادش کاسه عسل به \r\nدکّان برد.خواست که به کاری رود.جوحی را گفت:«در این کاسه زهر است.زنهار\r\nتا نخوری که هلاک شوی»!گفت:«مرا با آن چکار است؟»چون استاد برفت جوحی \r\nوصله جامه ای به صراف داد و پاره ای نان فزونی بستد و با آن عسل تمام بخورد!\r\nاستاد باز آمد و وصله طلبید.جوحی گفت:«مرا مزن تا راست بگویم!حال آنکه من \r\nغافل شدم دزد وصله را ربود!من ترسیدم که تو بیائی و مرا بزنی!گفتم:«زهر بخورم\r\nتا تو باز آئی من مرده باشم!آن زهر که در کاسه بود تمام بخوردم ولی هنوز زنده ام\r\nباقی تو دانی!!!»\r\n"},{"id":2035,"category_id":2,"category_code":"s2","source_id":202,"title":"جامه ی تلخک","content":"\r\nآورده اند که:\r\nاز بهر روز عید سلطان محمود خلعت هر کس تعیین می کرد.چون به تلخک رسید\r\nفرمود که پالانی بیاورید و به او بدهید‌ چنان کردند.\r\nچون مردم خلعت پوشیدند تلخک آن پالان را در دوش گرفت و به مجلس سلطان آمد\r\nگفت:«ای بزرگان عنایت سلطان در حق بنده از اینجا معلوم کنید که شما را خلعت \r\nازخزانه فرمود و جامه خاص از تن در آورد و بر من پوشانید!!!»\r\n"},{"id":2036,"category_id":2,"category_code":"s2","source_id":203,"title":"بادنجان بورانی","content":"\r\nآورده اند که:\r\nسلطان محمود را در حالت گرسنگی بادنجان بورانی آوردند.خوشش آمد!\r\nگفت:«بادنجان طعامی است خوش»ندیمی در مدح بادنجان فصلی پرداخت.\r\nچون سیر شد گفت:«بادنجان سخت مضر است!»\r\nندیم باز در مضرت بادنجان مبالغتی تمام کرد.\r\nسلطان گفت:«ای مردک نه آن زمان که مدحش می گفتی نه حال که مضرتش باز\r\nمیگوئی؟!»\r\nگفت:«من ندیم توام نه ندیم بادنجان! مرا چیزی باید گفت که تو را خوش آید نه بادنجان را !!!»\r\n"},{"id":2037,"category_id":2,"category_code":"s2","source_id":204,"title":"داور آواز","content":"\r\nآورده اند که\r\nفتحعلی شاه قاجار گه گاه شعر می سرود و روزی شاعر دربار را به داوری\r\nگرفت. شاعر هم که شعر را نپسندیده بود بی پروا نظر خود را باز گفت.فتحعلی\r\nشاه فرمان داد او را به طویله برند و در ردیف چهار پایان به آخور ببندند.\r\nشاعر ساعتی چند آنجا بود تا آن که شاه دوباره او را خواست و از نو شعر را برایش \r\nخواند سپس پرسید:«حالا چطور است؟».شاعر هم بی آنکه پاسخی بدهد \r\nراه خروج پیش گرفت!. شاه پرسید:کجا می روی؟گفت: به طویله!!!\r\n"},{"id":2038,"category_id":2,"category_code":"s2","source_id":205,"title":"تا کی بماند این بازار؟","content":"\r\nآورده اند که ...\r\nدرویشی مستجاب الدعوة در بغداد پدید آمد. \r\nحجاج یوسف را خبر کردند؛ بخواندش و گفت: دعای خیری بر من کن. \r\nگفت: خدایا جانش بستان. \r\nگفت: از بهر خدای این چه دعاست. \r\nگفت: این دعای خیرست ترا و جمله مسلمانان را\r\nای زبردست زیر دست آزار *** گرم تا کی بماند این بازار\r\nبه چه کار آیدت جهانداری *** مردنت به که مردم آزاری\r\n«گلستان سعدی»\r\n"},{"id":2039,"category_id":2,"category_code":"s2","source_id":206,"title":"چرا دوست بگیری...","content":"\r\nآورده اند که ...\r\nنقل است که یک روز شیخ ابوبکر شبلی رحمةالله علیه یکی را دید زار می‌گریست. گفت: چرا می‌گریی؟ گفت: دوستی داشتم بمرد. گفت: ای نادان چرا دوستی گیری که بمیرد؟!\r\n"},{"id":2040,"category_id":2,"category_code":"s2","source_id":207,"title":"این دروغ نتوان گفت","content":"\r\nآورده اند که ...\r\nنقلست از شیخ ابوبکر شبلی رحمةالله علیه که گفت: عمری است که می‌خواهم که گویم \"حسبی الله\" چون می‌دانم که از من این دروغ است نمی‌توانم گفت.\r\n"},{"id":2041,"category_id":2,"category_code":"s2","source_id":208,"title":"یاد پیغمبر","content":"\r\nآ ورده اند که ...\r\nشخصی از مولانا عضد‌الدین پرسید که چونست که در زمان خلفا مردم دعوی خدایی و پیغمبری بسیار می‌کردند و اکنون نمی‌کنند؟\r\nگفت: «مردم این روزگار را چندان از ظلم و گرسنگی افتاده است که نه از خدایشان یاد می‌آید و نه از پیغامبر.»\r\n"},{"id":2042,"category_id":2,"category_code":"s2","source_id":209,"title":"خانه ی ما","content":"آورده اند که ...\r\nجنازه ای را به راهی می بردند. درویشی با پسر بر سر راه ایستاده بودند، پسر از پدر پرسید که بابا در اینجا چیست؟ گفت: آدمی. گفت: کجایش می برند؟\r\nگفت: به جایی که نه خوردنی باشد و نه پوشیدنی، نه نان و نه آب و نه هیزم و نه آتش و نه زر و نه سیم، نه بوریا نه گلیم. گفت: بابا مگر به خانه ی ماش می برند؟!\r\n"},{"id":2043,"category_id":2,"category_code":"s2","source_id":210,"title":"سنگ را بسته اند و سگ را گشاده!","content":"\r\nآورده اند که ...\r\nیکی از شاعران پیش امیر دزدان رفت و ثنایی بر او بگفت. فرمود تا جامه از او برکنند و از ده بیرون کنند. مسکین برهنه به سرما همی رفت. سگان به دنبال وی افتادند. خواست تا سنگی بردارد و سگان را دفع کند. زمین یخ گرفته بود. عاجز شد. گفت: «این چه حرام زاده مردمان اند؛ سنگ را بسته اند و سگ را گشاده!»\r\nامیر از دور بدید و بشنید و بخندید و گفت: «ای حکیم، از من چیزی بخواه.» گفت جامه ی خود می خواهم اگر انعام می فرمایی.\r\nامیدوار بود آدمی به خیر کسان *** مرا به خیر تو امید نیست، شر مرسان\r\n"},{"id":2044,"category_id":2,"category_code":"s2","source_id":211,"title":"عبرت","content":"\r\nآورده اند که ...\r\nچون عمروبن لیث و اسماعیل سامانی به یکدیگر رسیدند، مصاف کردند. اتفاق چنان افتاد که عمروبن لیث به در بلخ شکسته شد و هفتاد هزار سوار او همه به هزیمت رفتند و چون او را پیش امیر اسماعیل آوردند، بفرمود تا او را به یوزبانان سپردند و این از عجایب روزگار است. چون نماز دیگر شد، فراشی که از آن عمروبن لیث بود در لشگرگاه می گشت. چشمش بر عمروبن لیث افتاد؛ دلش بر وی بسوخت. به نزد او رفت. عمرو او را گفت: «امشب پیش من باش که بس تنها مانده ام». بعد از آن گفت: «تا مردم زنده باشد، او را از قوت چاره نیست. تدبیر چیزی خوردنی کن که من گرسنه ام». فراش یک من گوشت به دست آورد و دیگی آهنین پیدا کرده، لختی سرگین خشک برچیده، کلوخی دو سه فراهم نهاد تا قلیه ای بکند. چون گوشت در دیگ انداخت و خود به طلب نمک شد، روز به آخر آمده بود. سگی بیامد و سر در دیگ کرد و پاره ای گوشت برداشت. دهنش بسوخت؛ سبک برآورد. حلقه ی دیگ در گردنش افتاد. از سوزش دیگ به آهنگ خاست و دیگ را ببرد. عمروبن لیث چون آن حال چنان دید، رو سوی سپاه و نگهبانان کرده، بخندید، گفت: «عبرت گیرید که من آن مردم که بامداد مطبخ مرا هزار و چهارصد شتر می کشید و شبانگاه سگی برداشته است و می برد!» و گفت: «اَصبحتُ امیراً و امسیتُ اسیراً».\r\n"},{"id":2045,"category_id":2,"category_code":"s2","source_id":212,"title":"ما را به خیرت امید نیست","content":"\r\nآورده اند که ...\r\nبراى امیرى خرما هدیه آوردند. \r\nخیال کرد خرماى تر و تازه است و قابل نگهدارى نیست. دستور داد فقراى شهر را خبر کنند تا به مسجد بیایند. وقتى آمدند متوجه شد خرما خشک است و قابل نگهداشتن، رو به فقرا کرد و گفت: شنیده ‏ام شما شب ها در مسجد مى ‏خوابید و بى‏ وضو نماز مى ‏خوانید، تصمیم دارم محبوستان کنم.\r\nگفتند: ایهاالامیر قسم مى ‏خوریم که دیگر پاى به مسجد نگذاریم!\r\n"},{"id":2046,"category_id":2,"category_code":"s2","source_id":213,"title":"شعر دزد","content":"\r\nآورده اند که ... \r\nروزى انورى از بازار بلخ مى‏ گذشت، هنگامه ‏اى دید، پیش رفت و سرى در میان کرد، مردى دید که قصاید انورى به نام خود مى ‏خواند و مردم او را تحسین مى ‏کردند.\r\nانورى پیش رفت و گفت: اى مرد این اشعار کیست که مى ‏خوانى؟ \r\nگفت: اشعار انورى\r\nانورى گفت: انورى را مى ‏شناسى؟\r\nگفت: انورى منم.\r\nانورى بخندید و گفت: «شعر دزد» دیده بودم اما «شاعر دزد» ندیده بودم. \r\n"},{"id":2047,"category_id":2,"category_code":"s2","source_id":214,"title":"کار را بسپار به...","content":"\r\nآورده اند که ...\r\nسلطان سنجر را در آن وقت که به دست غزان گرفتار شده بود، پرسیدند :«علت چه بود که مُلکی بدین وسعت و آراستگی که تو را بود، چنین مختل شد؟»\r\nگفت : «کارهای بزرگ به مردم خُرد فرمودم و کارهای خُرد به مردم بزرگ؛ که مردم خُرد کارهای بزرگ را نتوانستند کرد و مردم بزرگ از کارهای خُرد عار داشتند و در پی نرفتند. هر دو کار تباه شد و نقصان به ملک رسید و کار لشکری و کشوری روی به فساد آورد.»\r\n"},{"id":2048,"category_id":2,"category_code":"s2","source_id":215,"title":"کار را بسپار به...","content":"\r\nآورده اند که ...\r\nسلطان سنجر را در آن وقت که به دست غزان گرفتار شده بود، پرسیدند :«علت چه بود که مُلکی بدین وسعت و آراستگی که تو را بود، چنین مختل شد؟»\r\nگفت : «کارهای بزرگ به مردم خُرد فرمودم و کارهای خُرد به مردم بزرگ؛ که مردم خُرد کارهای بزرگ را نتوانستند کرد و مردم بزرگ از کارهای خُرد عار داشتند و در پی نرفتند. هر دو کار تباه شد و نقصان به ملک رسید و کار لشکری و کشوری روی به فساد آورد.»\r\n"},{"id":2049,"category_id":2,"category_code":"s2","source_id":216,"title":"رحمی نما بر ما","content":"\r\nآورده اند که ...\r\nچنان خواندم در اخبار موسی - علیه السلام - که بدان وقت که شبانی می کرد، یک شب گوسپندان را سوی حظیره (پناهگاه) می راند. وقت نماز بود و شبی تاریک، و باران به نیرو آمدی. چون نزدیک حظیره رسید، بره ای بگریخت. موسی - علیه السلام - تنگ دل شد و بر اثر وی بدوید. بر آن جمله که چو دریابد، چوبش بزند. چون بگرفتش، دلش بر وی بسوخت و بر کنار نهاد وی را و دست بر سر وی فرود آورد و گفت: «ای بی چاره! در پس، بیمی نه و در پیش، امیدی نه؛ چرا بگریختی و مادر را رها کردی؟»\r\nبدین ترحم که بکرد، نبوت بر وی مستحکم تر شد.\r\n"},{"id":2050,"category_id":2,"category_code":"s2","source_id":217,"title":"سر گرگ","content":"\r\nآورده اند که ...\r\nذوالنون مصری ، پادشاهی را گفت : « شنیده ام فلان عامل را که فرستاده ای به فلان ولایت، بر رعیت درازدستی می کند و ظلم روا می دارد.» گفت : « روزی سزای او بدهم». گفت : «بلی، روزی سزای او بدهی که مال از رعیت تمام ستده باشد. پس به زجر و مصادره از وی بازستانی و در خزینه نهی، درویش و رعیت را چه سود دارد؟»\r\nپادشاه خجل گشت و دفع مضرت عامل بفرمود در حال.\r\nسر گرگ باید هم اول برید *** نه چون گوسفندان مردم درید\r\n"},{"id":2051,"category_id":2,"category_code":"s2","source_id":218,"title":"نان خوردن به تاریکی","content":"\r\nآورده اند که ...\r\nشبی سی و چند کس از درویشان و جوانمردان نزد ابوالحسن انطاکی جمع شدند و او را گرده ای دو سه نان بود چندان که پنج مرد را دشوار بس باشد . نان ها همه پاره کردند و چراغ بکشتند و بر سفره نشستند تا نان خورند و هر یکی دهان می جنبانید تا دیگران پندارند که همی خورد . چون سفره برداشتند ، نان بر حال خود بود و هیچ یک نخورده بودند ... \r\n"},{"id":2052,"category_id":2,"category_code":"s2","source_id":219,"title":"خدا ما را دوست ندارد!","content":"خبری از غوغای رودخانه ی خروشان نبود. دشت تشنه بود و هر آنچه در دل داشت بخشیده بود به درختان تا زخم های مانده از شلاق سوزان خورشید را التیام بخشند. کودکان نمی خندیدند تا خشکی لب هاشان نترکد. \r\nمردم دسته دسته سوی خانه ی حکیم روان شدند. چون گرد آمدند حکیم را خواندند. \r\nگفت: از من چه می خواهید؟\r\nگفتند: این چه حکایت است، چگونه است که نعمتی از آسمان بر ما فرو نمی ریزد؟ چگونه درهای رحمت خداوند بر ما بسته شده است؟ آیا دعای ما را نمی شنود و از حال ما خبر ندارد؟\r\nگفت: پاک است خداوند از آنچه می پندارید. چگونه فراموش کردید آنگاه که غرق در نعمت بودید؟ چگونه قدر ندانسته و ناسپاسی کردید؟ این بلایی است که خود در آن تقصیر کارید.\r\nگفتند: حکیم! چگونه ما را ناسپاس می خوانی حال آنکه شب و روز ذکر خدا می گوییم و عبادت می کنیم؟ چرا مردمان سرزمین های دیگر که به عیش و نوش مشغولند و غرق در لذات دنیا شدند به چنین بلایی گرفتار نیامدند؟\r\nحکیم نگاهی به جمعیت انداخت و گفت: قرآن خوانده اید؟\r\nگفتند: آری!!!\r\nگفت: \"لاَ تُسْرِفُواْ إِنَّهُ لاَ یُحِبُّ الْمُسْرِفِینَ(1)\" ما اسراف کردیم و خدا ما را دوست ندارد ...\r\n"},{"id":2053,"category_id":2,"category_code":"s2","source_id":220,"title":"آرزوی شیخ","content":"شیخ روزی با مریدان از بازار میوه فروشان گذر کرد و گیلاسی دید که کرمی در آن لولیده و به ولع تمام گیلاس همی خورد.\r\nشیخ گریست و فرمود : خوشا به آن کرم و توانگریش . عمری زیستم و نتوانستم چارکی گیلاس بخرم.\r\nدست ما کوتاه و خرما بر نخیل\r\nآسمان و زمین بر ما شده بخیل\r\nو مریدان رم کردند و سر به بیابان گذاشتند.\r\n"},{"id":2054,"category_id":2,"category_code":"s2","source_id":221,"title":"عمر گوسفند","content":"روزی شیخ از بازار گذر کردی ، گوسفند مذبوحی را دید در قصابی آویزان و مردمان هیچ یک توان و یارای خرید نداشت. شیخ فرمود : عمر این گوسفند بعد از مرگ درازتر است از عمرش قبل مرگ.\r\nو مریدان مدهوش گشتند و نعره ها زدند.\r\n"},{"id":2055,"category_id":2,"category_code":"s2","source_id":222,"title":"رسم مریدی","content":"در ظهر تابستانی شیخ فرمود : هوا بس ناجوانمردانه گرم است.\r\nو مریدان گریستند.\r\nشیخ گفت : زقنبوت ! هرچه که من می گویم که نباید بگریستید ! و مریدان غش غش خندیدند.\r\n"},{"id":2056,"category_id":2,"category_code":"s2","source_id":223,"title":"شیخ و مرد عرب","content":"روزی شیخ و مریدان در بیابان همی برفتی که ناگاه عربی سوار بر شتر به سمت ایشان بیامدی .... شیخ رو به عرب کردی و بفرمودی : ایا این شتر است؟! \r\nمرد عرب به خود فشار زیادی آوردی و سرخ گشتی و جان به جان آفرین تسلیم بنمودی ....\r\nجمله همه مریدان واله و حیران گشتندی و علت را از شیخ جویا شدندی ؟؟\r\nشیخ بگفتا : وی (مرد عرب) جهت تلفظ پ ن پ به خود فشار آوردی و هلاک گشتی ... \r\n"},{"id":2057,"category_id":2,"category_code":"s2","source_id":224,"title":"پند دزد","content":"گويند ابوحامد محمد غزالى آن چه را فرا مى گرفت در دفترها مى نوشت. وقتى (زمانی) با كاروانى در سفر بود و نوشته ها را يك جا بسته با خود برداشت ... در راه گرفتار راهزنان شدند.غزالى رو به آنان كرد و به التماس گفت:اين بسته را از من نگيريد، ديگر هر چه دارم از آن شما.دزدان را طمع زيادت شد، آن را گشودند و جز دفترهاى نوشته چيزى نيافتند.دزدى پرسيد كه اين ها چيست؟چون غزالى وى را به آن ها آگاهى داد، دزد راهزن گفت:علمى را كه دزد ببرد، به چه كار آيد!اين سخن دزد، در غزالى اثرى عميق گذاشت و گفت:پندى به از اين از كسى نشنيدم و ديگر در پى آن شد كه علم را در دفتر جان بنگارد. "},{"id":2058,"category_id":2,"category_code":"s2","source_id":225,"title":"عهد جوانی با خدا","content":"جوانى با خداى متعال عهد و پیمان بست كه به دنیا دل نبندد و به زیورآلات آن ننگرد چون اینها انسان را از یاد خدا باز مى دارد.\r\nروزى از بازارى مى گذشت از جلوى جواهر فروشى رد مى شد دید كه كمربندى مُرصّع به دُرّ و جواهر است ، از عهد خود غافل شد و نگاه طولانى به آن كرد و از زیبائى و حُسن آن تعجب نمود. \r\nصاحب جواهر فروشى دید كه آن جوان با دقت تمام به آن كمربند نگاه مى كند دل از آن نمى برد همینكه آن جوان قدرى از در مغازه جواهر فروشى رد شد صاحب جواهر فروشى كمربند را در دكان ندید فورا از در مغازه بریزآمد و با شتاب تمام خود را به جوان رسانید و دست او را گرفت و گفت اى عیّار تو كمربند را دزدیدى من از تو دست برنمى دارم تا كمربند مرا بدهى و كشان كشان او را به محضر حاكم آورد گفت اى حاكم این جوان دزد است و كمربند جواهرنشان را ربوده .\r\nحاكم نگاهى بسیماى آن جوان كرد و گفت گمان نكنم این جوان دزد باشد زیرا به او این كار نمى آید.\r\nصاحب كمربند گفت چرا او كمربند مرا دزدیده و ما جرا را براى حاكم شرح داد. حاكم دستور داد او را بازرسى كنند وقتى كه او را بازرسى كردند دیدند در زیر لباسهاى جوان كمربند بسته شده ، حاكم متعجب و خشمناك فریاد زد.\r\n((یا فتى اَما نستحیى تلبس لباس الاخیار و تعمل عمل الفجار)) اى جوان آیا حیا نمى كنى و خجالت نمى كشى لباس خوبان را میپوشى و عمل بدكاران را انجام میدهى ؟\r\nجوان وحشت زده و ناراحت گفت : مولاى من قدرى صبر كن تا مطب برایت واضح گردد. سپس رو به آسمان نمود و از صمیم دل گفت الهى لااعود الى مثلها خدایا دیگر به این عمل برنمى گردم مى دانم از یاد تو غافل شدم و به گناه افتادم از كرده خود پشیمان و نادمم توبه مرا بپذیر كه خیلى ناراحتم و آبروى مرا نبر.\r\nقاضى خیال كرد كه جوان عمل دزدى را مى گوید خیلى ناراحت شد و دستور داد او را عریان كنند و تازیانه بزنند (باینكه آن حكم بر خلاف قرآن بود زیرا حكم دزد پس از اثبات دست بریدن بود.)\r\nناگهان صدائى شنیدند ولى صاحب صدا را ندیدند كه فرمود:( ادعو ولاتضربوه انما ارودنا تأ دیبه ) رهاكنید او را زیرا ما مى خواستیم او را تاءدیب نمائیم .\r\nحاكم منقلب گردید واز كرده خود پشیمان شد و از آن جوان عذر خواهى كرد و آمد بین دوچشم او را بوسید و گفت مرا از قصه خود آگاه كن .\r\nجوان جریان عهد خود را با خدا بیان كرد و نقض عهد را نیز عنوان نمود و گفت نقض عهد و پیمان مرا به این رسوائى و بلیه دچار كرد.\r\nصاحب كمربند وقتى از داستان آگاه شد پشیمان و نادم او را قسم داد كه تو را به خدا قسمت مى دهم كه این كمربند را از من قبول كن و مرا حلال نما.\r\nجوان گفت : اى مرد برو دنبال كارت من خودم باعث این كیفر شدم و گوش مالى هم شدم .\r\n"},{"id":2059,"category_id":2,"category_code":"s2","source_id":226,"title":"توبه ی نصوح","content":"(نَصوح ) مردى كوسج (بى ریش ) و مانند زنان داراى دوپستان بود او در یكى از حمامهاى زنانه آن زمان كارگرى مى كرده ، و شستشوى این زن و آن زن را به عهده داشته .\r\nنصوح به اندازه اى چابك و تردست بوده است كه همه زنها مایل بودند كارشان را او عهده دار شود، خورده خورده آوازه نصوح ، بگوش دختر پادشاه وقت رسید، میل كرد كه وى را از نزدیك ببیند.\r\nفرستاد حاضرش كردند، همینكه دختر پادشاه وضعش را دید پسندید و شب او را نزد خود نگهداشت ، روز بعد دستور داد حمامى را خلوت كنند و از ورود اشخاص متفرقه بآنجا جلوگیرى نمایند. سپس نَصوح را بهمراه خود بحمام برد و تنظیف خودش را به او محول نمود. \r\nاز قضا دانه گرانبهائى از دختر پادشاه ، در آنحمام مفقود گشت از این پیش آمد دختر پادشاه در غضب شد و به دو تن از خواصش فرمان داد كه همه كارگران را تفتیش و بازرسى كنند، تا بلكه آن دانه گرانبها پیدا شود. طبق این دستور ماءمورین ، كارگران را یكى بعد از دیگرى مورد بازدید خود قرار دادند. هینمكه نوبت به نَصوح رسید، با اینكه آن بیچاره روحش خبرنداشت ولى از اینجهت مى دانست كه اگر تفتیشش كنند كارش به رسوائى كشیده خواهد شد به خاطر همین هم حاضر نشد كه تفتیشش كنند. لذا به هر طرف كه ماءمورین مى رفتند تا دستگیرش كنند، او به طرف دیگر فرار مى كرد و این عمل او به آنها اینطور نشان مى داد كه دانه را او ربوده و از این نظر ماءمورین براى دستگیرى او اهمیت بیشترى قائل بودند.\r\nنصوح هم چون تنها راه نجات را این دید كه خود را در میان خزانه حمام پنهان كند ناچار خودش را بداخل خزانه رسانید، و همینكه دید ماءمورین براى گرفتنش به خزانه وارد شدند و فهمید كه دیگر كارش تمام است و الا ن است كه رسوا شود، بخداى متعال از ته دل توجه عمیقى نمود و از روى اخلاص از كرده هاى خود توبه كرد و دست حاجت بدرگاه الهى دراز نمود و از او خواست كه از این غم رسوائى نجاتش دهد.\r\nبه مجرّد اینكه نصوح حال توبه و استغفار پیدا كرد و از كرده خود پشیمان گشت ، ناگهان از بیرون حمام صدائى بلند شد كه دست از این بیچاره بردارید چون دانه پیدا شد. پس ، از او دست كشیدند و نصوح خسته و نالان شكر الهى را بجا آورده از خدمت دختر مرخص شد و به خانه خود رفت و هر چه مال كه از راه گناه در آورده بود، همه را بین فقراء قسمت كرد و چون اهالى شهر از او دست بردار نبودند دیگر نمى توانست در آن شهر بماند. و از طرفى نمى توانست راز خودش را به كسى اظهار كند، ناچار از شهر خارج شده و در كوهى كه در چند فرسخى آن شهر بود، سكونت اختیار نمود، و بعبادت خدا مشغول گردید.\r\nاتّفاقا شبى در خواب دید كسى به او مى گوید: اى نصوح چگونه توبه كرده اى و حال آنكه گوشت و پوست تو از فعل حرام روئیده شده است ؟!\r\nتو باید طورى كنى كه گوشتهاى بدنت بریزد، همینكه نصوح از خواب بیدار شد با خودش قرار گذاشت كه سنگهاى گران وزن را حمل كند و بدین وسیله خودش را از گوشتها بكاهاند.\r\nاین برنامه را نصوح مرتبا عمل كرد، تا پس از مدّتى كه گذشت در یكى از روزها همانطوریكه مشغول به كار بود چشمش به میشى افتاد كه در آن كوه چرا مى كند، از این امر به فكر فرو رفت . كه آیا این میش ‍ از كجا آمده و از آن كیست ؟! تا آنكه عاقبت با خود اندیشید كه این میش قطعا از چوپانى فرار كرده و به اینجا آمده پس بایستى من از آن نگهدارى كنم تا صاحبش پیدا شود و باو تسلیمش نمایم ، لذا رفت و آن میش را گرفت و درجائى پنهانش كرد، و از همان علوفه و گیاهان كه خود مى خورد بآن نیز مى خورانید تا اینكه صاحبش آید و از او مواظبت هم میكرد كه آن میش گرسنه نماند. چونكه چند روزى بهمین منوال گذشت آن میش به فرمان الهى به تكلم و حرف آمد و گفت :\r\nاى نصوح خدا را شكر كن كه مرا براى تو آفریده سپس از آن وقت به بعد نصوح از شیر میش مى خورد و عبادت مى كرد تا موقعیكه اتفاقا عبور كاروانى كه راه را گم كرده بود و مردمش از تشنگى نزدیك به هلاكت بودند به آنجا افتاد. همینكه نصوح را دیدند از او آب خواستند.\r\nنصوح گفت : شماها ظرفهایتان را بیاورید تا من به جاى آب شیرتان دهم مردم ظرف مى آوردند و نصوح آنها را از شیر پركرده به آنان رد مى كرد و به قدرت الهى هیچ از آن كم نمى شد بدین وسیله نصوح آن گروه را از تشنگى نجات داد. بعدا راه شهر را بآنها نشان داد.\r\nكاروانیان راهى شهر شدند و هریك از مسافرین در موقع حركت در برابر خدمتى كه آقاى نصوح به آنان كرده بود احسانى نمودند و چون راهى كه نصوح به آنها نشان داده بود نزدیكتر بشهر بود. آنها براى همیشه آمد و رفت خود را از آنجا قرار دادند. بتدریج سایر كاروانها هم بر این راه مطلع شدند. آنها نیز ترك راه قدیمى نموده همین راه را اختیار كردند. قهرا این رفت و آمدها درآمد سرشارى براى نصوح تولید مى نمود، و او از محل این درآمدها بناهائى ساخت و چاهى احداث كرد و آبى جارى نمود و كشت و زراعتى بوجود آورد و جمعى را هم در آن منطقه سكونت داد، و بین آنها بساط عدالت را مقرر فرمود و برایشان حكومت مى كرد و جمعیتى كه در آن محل سكونت داشتند همگى به چشم بزرگى بر نصوح مى نگریستند.\r\nرفته رفته آوازه و حسن تدبیر نصوح به گوش پادشاه وقت كه پدر آن دختر بود، رسید. از شنیدن این خبر به شوق دیدنش افتاد لذا دستور داد تا وى را دعوت بدربار كنند. همینكه دعوت پادشاه به نصوح رسید اجابت نكرد و گفت مرا با دنیا و اهل دنیا كارى نیست . و از این رفتن به دربار عذر خواست مامورین وقتى سخن نصوح را به پادشاه زدند بسیار تعجب كرد واظهار داشت حال كه او براى آمدن عذر دارد پس چه خوب است ما نزد او رویم و قلعه نوبنیادش را مشاهده كنیم . لذا با خواصش بسوى اقامتگاه نصوح حركت كردند.\r\nهمینكه به آن محل رسیدند به قابض الارواح امر شد كه جان پادشاه را بگیر و به زندگانى وى خاتمه دهد، پادشاه بدرود حیات گفت .\r\nاین خبر به نصوح رسید دانست كه وى براى ملاقات او از شهر خارج شده لذا در تجهیزات و مراسم تشییع جنازه اش شركت كرد، و آنجا ماند تا به خاكش سپردند و از این رو كه پادشاه پسرى نداشت اركان دولت مصلحت را در این دیدند كه نصوح را به تخت سلطنت بنشانند پس چنان كردند و نصوح را به زور به پادشاهى منصوب كردند.\r\nنصوح هم چون به پادشاهى رسید، بساط عدالت را در تمام قلمرو مملكتش گسترانید و بعد هم با همان دختر پادشاه كه قبلا گفتیم ازدواج كرد. چون شب زفاف رسید و در بارگاهش نشسته بود، ناگهان شخصى بر او وارد شد و گفت ، چند سال قبل از این به كار شبانى و چوپانى مشغول بودم و میشى از من گم شده بود و اكنون آن را در نزد تو یافته ام ، مالم را به من رد كن .\r\nنصوح گفت : همینطور است الا ن امر مى كنم به تو میش را تسلیم كنند. شخص تازه وارد بار دیگر گفت چون میش مرا نگهدارى كردى هرآنچه از شیرش را خورده اى بتو حلال باد ولى آن مقدار از منافعى كه به تو رسیده نیمى از آنِ تو باشد، باید نیم دیگرش را به من تسلیم دارى .\r\nنصوح دستور داد تا آنچه از اموال منقول و غیر منقول كه در اختیار دارد نصفش را به وى بدهند و منشیان را دستور داد تا كشور را نیز بالمناصافه بینشان تقسیم كنند سپس از چوپان معذرت خواهى كرد تا بلكه زودتر برود. در آن موقع شبان گفت : اى نصوح فقط یك چیز دیگر مانده كه هنوز قسمت نشده ؟! نصوح پرسید كدام است ؟!\r\nچوپان گفت همین دختریست كه به ازدواج خود در آوردى چون آن هم از منفعت میش من است .\r\nنصوح گفت : چون قسمت كردن او، مساوى با خاتمه دادن به حیات وى است بیا و از این امر درگذر؟ شبان قبول نكرد باز گفت : نصف دارائى خودم را به تو مى دهم ، تا از این امر درگذرى ، این مرتبه هم قبول نكرد. نصوح اظهار داشت تمام دارائى خود را مى دهم تا از این امر صرف نظر كنى ، باز نپذیرفت . ناچار جلاّد را طلبید و گفت : دختر را به دو نیم كن . سپس جلاد شمشیر را كشید تا بر فرق دختر زند دختر از وحشت لرزید و جزع كرد و از هوش رفت .\r\nدر این هنگام شبان جلو جلاد را گرفت و خطاب به نصوح كرد و گفت بدان نه من شبان و نه آن میش است بلكه ما هر دو ملكى هستیم ، كه از براى امتحان تو فرستاده شده ایم ، سپس در آنموقع ، میش و چوپان هر دو از نظر غائب شدند. نصوح شكر الهى را بجا آورد و پس از عروسى تا مدتى كه زنده بود عبادت و سلطنت مى كرد و بعضى گفته اند آیه شریفه : تُوبُوا اِلَى اللّه تَوْبَةً نَصُوحا ( 45) اشاره به توبه چنین شخصى است .\r\nاز این داستان نتیجه مى گیریم ، اگر كسى توبه كند خداوند متعال امور دنیا و آخرت او را اصلاح خواهد كرد و دعایش را مستجاب مى كند و او را در بین مردم و ملائكه عزیز و سربلند مى نماید و بزرگترین پاداش را بعد از امتحان در دنیا و آخرت به او عنایت مى نماید.\r\n"},{"id":2060,"category_id":2,"category_code":"s2","source_id":227,"title":"توبه ی جوان هرزه","content":"رابعه عدویه مى گوید:\r\nدوستى داشتم كه جوان بسیار زیبا و قشنگ و دلفریبى بود بر اثر جوانى و زیبائى ، جوانان و دوستان بذه كارش او را به طرف گناه كشاندند و او كم كم هرزه و بى بند و بار و شیّاد و لات شد. \r\nبیشتر كارش به دنبال خانم رفتن و تور كردن دختران معصوم بود و عجیب فرد هرزه و گناهكارى شده بود كه همه از دستش ناراحت بودند. \r\nیك روز كه به دیدن او به خانه اش رفتم ، یك وقت دیدم او در سجّاده عبادتش ایستاده نماز مى خواند و غرق در زهد و تقوى و ورع و عبادت و نماز و طاعت است ، عجب نماز با حال و با خشوع و خضوع و گریان و نالان بود. \r\nاز حالش متعجّب و حیران شدم ! با خود گفتم آن حال گناه و معصیت و بذه كارى چه بود؟! و این حال عبادت و طاعت و گریه و ناله و زهد و تقوى چیست ؟ چطور شده كه عتبة بن علام عوض شده ؟! \r\nصبر كردم تا نمازش را تمام كرد، بعد گفتم : ابن علام خودتى ؟! تو آن كسى نبودى كه همه اش در هوى و هوس و زن بازى و عیش و نوش و غرق در معاصى و گناه و خلاف و عشق و شراب بودى چطور شده به طرف خدا آمدى ؟ با خدا آشتى كردى ؟ و چگونه از گناهان خودت برگشتى ؟! \r\nعتبه گفت : اگر یادت باشد من در اوائل جوانیم خیلى معصیت كار بودم و به خانم ها خیلى علاقه داشتم و در این كار حریص بودم ، همانطور كه مى دانى بیش از هزار زن در بصره گرفتار چنگال عشق من بودند و من هم در این كار اسراف زیادى داشتم . \r\nیك روز كه از خانه بیرون آمدم ناگهان چشمم به خانمى افتاد كه جز چشمهایش چیزى پیدا نبود و حجاب كاملى داشت ، شیطان مرا وسوسه كرد و گویا از قلبم آتشى بر افروخته شد، دنبالش رفتم كه با او حرف بزنم به من راه نمى داد و هرچه با او صحبت مى كردم اعتنایى به من نمى كرد، نزدیكش رفتم ، گفتم : واى بر تو مرا نمى شناسى ؟! من عتبه هستم كه اكثر زنهاى بصره عاشق و دلباخته من هستند ... با تو حرف مى زنم ، به من بى اعتنائى مى كنى ؟! گفت از من چه مى خواهى ؟ گفتم مرا مهمانى كن . \r\nگفت : اى مرد من كه در حجاب و پرده كاملم تو چطور مرا دوست دارى و نسبت به من اظهار علاقه مى كنى ؟ \r\nگفتم : من همان دو چشمهاى قشنگ و زیباى تو را دوست دارم كه مرا فریب داده . \r\nگفت : راست گفتى من از آنها غافل بودم . اگر از من دست بر نمى دارى بیا تا حاجت تو را برآورده كنم . \r\nسپس به راه افتاد تا به منزلش رسید من هم دنبال او رفتم . داخل خانه شد من هم داخل شدم وقتى كه وارد منزلش شدم دیدم چیزى از قبیل اسباب واثاثیه در منزلش نیست . گفتم : مگر در خانه اسباب و اثاثیه ندارى ؟ \r\nگفت : اسباب و اثاثیه این خانه را انتقال داده ایم گفتم كجا؟ گفت مگر قرآن نخوانده اى كه خداوند مى فرماید: \r\nتِلْكِ الدّار الا خِرَةُ تَجْعَلُها لِلَّذینَ لایُریدُونَ عُلُوّا فِى الاَْرْضِ وَلا فَسادا وَالْعاقِبَةُ لِلْمُتَّقینَ .( 44) \r\nاین سراى (دائمى و با عظمت ) آخرت را فقط به افرادى اختصاص ‍ (داده و) مى دهیم كه در نظر ندارند در زمین برترى جوئى و فساد نمایند و عاقبت نیك و شایسته و خوب براى افراد با تقوا و پرهیزگار خواهد بود. \r\nبله ما هرچه داشتیم براى آخرت جاوید فرستادیم دنیاى باقى ماندنى نیست . اكنون اى مرد بیا و از خدا بترس و از این كار درگذر حذر كن از اینكه بهشت همیشگى را به دنیاى فانى بفروشى و حوران را به زنان . \r\nگفتم : از این پرهیزگارى درگذر و حاجت مرا روا كن . \r\nخیلى مرا نصیحت كرد دید فایده اى ندارد گفت : حال كه از این كار نمى گذرى آیا ناگزیرم و ناچارم نیاز تو را برآورم ؟! \r\nگفتم آرى . \r\nدیدم رفت در اُتاق دیگر و مرا به آن حال گذاشت . مشاهده كردم پیرزنى در آن اتاق نشسته است . آن دختر صدا زد برایم آب بیاورید تا وضو بسازم آب آوردند و وضو گرفت و تا نصف شب نماز خواند من همین طول در فكر بودم كه این جا كجاست اینها كى هستند و چرا تا حال طول كشید كه ناگهان فریاد آن دختر را شنیدم كه گفت یك مقدار پنبه و طبقى برایم بیاورید سپس آن پیرزن برایش برد. \r\nبعد از چند دقیقه ناگهان دیدم پیرزن فریادى زد و گفت : \r\nاِنّا لِلّه وَ اِنّا اِلَیْهِ راجِعُون وَلاحَوْلَ وَلاقوة اِلاّ بِاللّهِ الْعَلىِّ العَظیم . \r\nمن وحشت زده پریدم دیدم آن دختر جفت چشمهایش را با كارد بیرون آورده و روى پنبه و داخل طبق گذاشت . وقتى آن پیرزن آن طبق را به سوى من آورد دیدم چشمها با پیه آن هنوز در حركت بود. \r\nپیرزن كه ناراحت و رنگ از صورتش پریده بود گفت : آنچه را كه عاشق بودى و دوست داشتى بگیر (لا بارك اللّه لك فیها) خدا برایت در آنها مبارك نكند ما را تو حیران كردى خدا ترا حیران كند. طبق را جلوى من گذاشت ، من وحشت كرده بودم نمى توانستم حرف بزنم آب دهانم خشك شده بود این چكارى بود كه آن دختر انجام داد. \r\nپیر زن با حالت گریه گفت ما ده نفر زن بودیم كه در خانه اعتكاف كرده بودیم و بیرون نمى رفتیم و خرید خانه را این دختر مى كرد و براى ما چیزى مى آوررد ولى تو ما را حیران و سرگردان و ناراحت و افسرده كردى خوب شد؟! این چشمهائى كه تو به آنها علاقه مند شده بودى . بگیر؟! \r\nهمینكه سخن پیرزن را شنیدم از فرط ناراحتى بیهوش شدم وقتى كه به هوش آمدم آن شب را به فكر فرو رفتم و بر گذشته هایم تاءسّف خوردم گفتم : واى به حال من یك عمر دارم گناه مى كنم هیچ ناراحت نبودم ولى این دختر با این كار مرا ادب كرد به منزل رفتم و تا چهل روز در خانه مریض شدم ، رفتار و كردار و كارِ آن دختر عجیب در من اثر كرده بود و این سبب شد كه من از كار خودم پشیمان و نادم گردم و توبه نمودم . \r\n"},{"id":2061,"category_id":2,"category_code":"s2","source_id":228,"title":" طلبه ی جوان و دختر فراری","content":"شب هنگام محمد باقر - طلبه جوان- در اتاق خود مشغول مطالعه بود که به ناگاه دختری وارد اتاق او شد. در را بست و با انگشت به طلبه بیچاره اشاره کرد که سکوت کند و هیچ نگوید. دختر پرسید: شام چه داری ؟؟ طلبه آنچه را که حاضر کرده بود آورد و سپس دختر که شاهزاده بود و به خاطر اختلاف با زنان حرمسرا خارج شده بود در گوشه‌ای از اتاق خوابید.\r\nصبح که دختر از خواب بیدار شد و از اتاق خارج شد ماموران،شاهزاده خانم را همراه طلبه جوان نزد شاه بردند. شاه عصبانی پرسید چرا شب به ما اطلاع ندادی و .... شب هنگام محمد باقر - طلبه جوان- در اتاق خود مشغول مطالعه بود که به ناگاه دختری وارد اتاق او شد. در را بست و با انگشت به طلبه بیچاره اشاره کرد که سکوت کند و هیچ نگوید. دختر پرسید: شام چه داری ؟؟ طلبه آنچه را که حاضر کرده بود آورد و سپس دختر که شاهزاده بود و به خاطر اختلاف با زنان حرمسرا خارج شده بود در گوشه‌ای از اتاق خوابید.\r\nصبح که دختر از خواب بیدار شد و از اتاق خارج شد ماموران،شاهزاده خانم را همراه طلبه جوان نزد شاه بردند. شاه عصبانی پرسید چرا شب به ما اطلاع ندادی و ....\r\n\r\nمحمد باقر گفت : شاهزاده تهدید کرد که اگر به کسی خبر دهم مرا به دست جلاد خواهد داد. شاه دستور داد که تحقیق شود که آیا این جوان خطائی کرده یا نه؟ و بعد از تحقیق از محمد باقر پرسید چطور توانستی در برابر نفست مقاومت نمائی؟ محمد باقر 10 انگشت خود را نشان داد و شاه دید که تمام انگشتانش سوخته و ... علت را پرسید. طلبه گفت : چون او به خواب رفت نفس اماره مرا وسوسه می نمود. هر بار که نفسم وسوسه می کرد یکی از انگشتان را بر روی شعله سوزان شمع می‌گذاشتم تا طعم آتش جهنم را بچشم و بالاخره از \r\nسر شب تا صبح بدین وسیله با نفس مبارزه کردم و به فضل خدا ، شیطان نتوانست مرا از راه راست منحرف کند و ایمانم را بسوزاند.\r\nشاه عباس از تقوا و پرهیز کاری او خوشش آمد و دستور داد همین شاهزاده را به عقد میر محمد باقر در آوردند و به او لقب میرداماد داد و امروزه تمام علم دوستان از وی به عظمت و نیکی یاد کرده و نام و یادش را گرامی می دارند. از مهمترین شاگردان وی می توان به ملا صدرا اشاره نمود.\r\n"},{"id":2062,"category_id":2,"category_code":"s2","source_id":229,"title":"مسیح و دوست دنیا پرست","content":"شخصى با حضرت عيسى (عليه السلام) همسفر شد تا به كنار آبى رسيدند سه قرص نان داشتند دو تاى آن را با هم خوردند و يكى ديگر را در آن محل گذاردند و براى خوردن آب بر سر نهر رفتند بعد از ساعتى حضرت سراغ آن گرده نان را گرفتند، گفت: اطلاعى ندارم پس هر دو از آنجا راه افتادند رفتند، اتفاقا آهويى با دو بچه آهو به نظر حضرت عيسى (عليه السلام) در آمدند آن حضرت يكى از آن دو آهوى بچه را طلبيد به فرمان حق تعالى آن آهو اجابت كرد به خدمت حضرت آمد آن حضرت آن را ذبح نمودند و كباب و بريان كردند به اتفاق رفيق ميل كردند. \r\nبعد از آن، حضرت خطاب به آن آهو بره كشته شده كردند و فرمودند: قم باذن الله، بلند شو به اذن خدا آهو بره زنده شد و رفت. \r\nحضرت با رفيق خود راهى شدند بعد حضرت فرمود: بحق آن خدايى كه اين آيه بزرگ را به تو نشان داد بگو كه آن قرص نان را كه برداشت گفت: نمى‏دانم (انسان گرفتار دنيا است و مال دنيا، ببينيد اين شخص چقدر و چند دفعه دروغ بگويد شايد به دنيا برسد) خلاصه پس از آن دوباره راهى شدند رسيدند به روى آب روان و يا رودخانه حضرت عيسى (عليه السلام) دست آن رفيق را گرفت به روى آب روان گشتند. \r\nچون از آن آب گذشتند حضرت فرمود: از تو سوال مى‏كنم بحق آن خدايى كه اين معجزه را به تو نشان داد آن گرده نان را كه برداشت، باز گفت: نمى‏دانم و خبر ندارم، از آنجا نيز عبور كردند در بيابان نشستند حضرت عيسى پاره خاك فراهم فرمود و امر كرد: كن ذهبا باذن الله يعنى: طلا بشويد به اذن خداوند تعالى، آن خاك و ريگ به فرمان الهى طلا گرديد، آن حضرت آن طلا را سه قسمت فرمود، يك قسمت را خودش برداشت، قسمت ديگر را به رفيق داد، قسمت سوم را فرمود براى كسى گذاشتم كه آن گرده نان را برداشته باشد. \r\nمريض حريص گفت: من برداشتم، حضرت عيسى وقتى اين جريان را ديدند هر سه قسمت را به او دادند و از او جدا شدند آن مرد با آن سه قسمت طلا در بيابان ماند كه دو نفر ديگر به او رسيدند و به طمع آن مال خطير به دنبال او افتادند و قصد كشتن او را نمودند ناچار زبان ملايمت گشودند و گفتند: اين سه قطعه طلا را تقسيم مى‏كنيم هر كدام يك قطعه برداشتند. \r\nچون به منزل رسيدند، يكى از رفقا را براى خريد نان به قريه نزديك فرستادند رفيقى كه براى تهيه نان رفته بود با خود فكر كرد كه طعام را با زهر مسموم كند و به خورد دو رفيق خود بدهد و هر سه قطعه طلا را تصرف نمايد و همين عمل را انجام داد. \r\nاتفاقا آن دو رفيق هم در بيابان نقشه قتل او را طرح كردند كه وقتى آمد او را بكشند و تمام طلاها را تصرف كنند، چون آن رفيق، آن دو نفر آمد او را كشتند سپس بدون اطلاع از جريان طعام مسموم، از آن طعام خوردند و هر دو مسموم شدند و مردند و آن سه قطعه طلا و سه جنازه كشته شده در بيابان افتاده بود. \r\nبار ديگر حضرت عيسى (عليه السلام) با حواريين از آن طرف عبورشانافتاد و آن سه قطعه طلا و سه جنازه را ملاحظه كردند حضرت عيسى صورت بطرف اصحاب خود كرد و حكايت آنها را نقل فرمود، بعد از آن فرمودند: هذه الدنيا فاحذروها، يعنى اين است دنيا پس دورى كنيد از آن دنيا و دل به آن نبنديد كه نتيجه بعدى گرفتارى است كه ملاحظه فرموديد، كه دل بستن به دنيا چه عاقبت بدى بوجود آورد .\r\n"},{"id":2063,"category_id":2,"category_code":"s2","source_id":230,"title":" به ما ربطی ندارد","content":"\r\nموشی در خانه ی مزرعه دار تله ی موش دید!\r\nبه مرغ و گوسفند و گاو خبر داد.\r\nآنها گفتند: مشکل تو به ما ربطی ندارد!\r\nماری در تله افتاد و زن مزرعه دار را گزید...\r\nاز مرغ برایش سوپ درست کردند!\r\nگوسفند را برای عیادت کنندگان سر بریدند!\r\nنهایتا زن تلف شد.\r\nگاو را برای مراسم ترحیم کشتند ودر این مدت...\r\nموش از سوراخ دیوار نگاه می کرد و\r\nبه مشکلی که به دیگران ربطی نداشت فکر می کرد.\r\n"},{"id":2064,"category_id":2,"category_code":"s2","source_id":231,"title":"مجازات کنیز و غلام زنا کار","content":"«احمد بن طولون» امیر زاده صالحی بود. در سن کودکی، روزی یک عده بینوا را بر در خانه خود مشاهده کرد لذا پیش پدرش رفت تا برای آنها چیزی بگیرد.\r\nپدر به او دستور داد تا به فلان اطاق رفته و قلم و دوات بیاورد تا جهت فقرا و بینوایان چیزی بنویسد. «احمد» بنا به دستور پدر، به همان اطاق وارد شد ولی ناگهان با منظره شرم آوری مواجه شد. او دید که خادمی با کنیزی از آن خانه، با هم مشغول عشقبازی و زنا هستند.\r\n«احمد» بدون معطلی قلم و دوات را برداشت و به نزد پدرش برد ولی از ماجرا چیزی نگفت.\r\nآن کنیز زناکار و خائن، با خود چنین فکر کرد که: «الان احمد داستان ما را به پدرش می گوید و پدر نیز ما را مجازات می کند.» برای پیشگیری از این مطلب، یک راست به نزد «طولون» رفت و گفت: «فرزند شما احمد با اینکه بچه است ولی در فلان اطاق نسبت به من دست خیانت داراز کرده است.»\r\n«طولون» که هرگز از پسرش انتظار چنین عملی را نداشت خیلی ناراحت شد و بدون تحقیق، نامه ای به یکی از مأمورین نوشت که به محض خواندن این نامه، حامل آن را گردن بزن. سپس آن نامه را به دست فرزندش «احمد» داد که به فلان مأمور برساند.\r\nاو که از مضمون نامه بی اطلاع بود، بدنبال امر پدرش حرکت کرد. ناگاه به همان کنیز برخورد کرد. کنیز پرسید: «کجا می روی؟»\r\n«احمد» گفت: «در این نامه حاجت مهمی است و من آن را به محل خود می رسانم.»\r\nکنیز از «احمد» خواست که نامه را به وسیله خادم مورد نظر خود بدهد تا او برساند.» «احمد» نیز قبول کرد و آن کنیز، نامه را به همان خادم زنا کار داد تا غضب امیر نسبت به «احمد» زیادتر شود.\r\nخادم متخلف، نامه را تسلیم مأمور کرد و مأمور با خواندن نامه دستور داد سر از تن خادم جدا کنند. بعد سر بریده اش را نزد امیر فرستاد.\r\nامیر با تعجب، «احمد» را خواست و صدق مطلب را از وی پرسید. «احمد» هر چه که دیده و نگفته بود را به عرض پدر رسانید.\r\n«طولون» دستور داد کنیز بیاید. وقتی که آمد، صدق مطلب را از او خواست و او هم مجبور به گفتن حقیقت ماجرا شد. امیر وقتی که از حقیقت مطلب با خبر گردید دستور داد آن کنیز را مجازات کنند.\r\n"},{"id":2065,"category_id":2,"category_code":"s2","source_id":232,"title":"چهار پند پدر","content":"روزی پدری هنگام مرگ فرزندش را فراخواند و گفت فرزندم تو را چهار وصیت دارم و امیدوارم که در زندگی به این چهار توجه کنی :\r\nاول اینکه اگر خواستی ملکی بفروشی ابتدا دستی به سرو رویش بکش و بعد بفروش\r\nدوم اینکه اگر خواستی با فاحشه ای باشی سعی کن صبح زود به نزدش بروی\r\nسوم اینکه اگر خواستی قمار بازی کنی سعی کن با بزرگترین قمار باز شهر بازی کنی\r\nچهارم اینکه اگر خواستی سیگار یا افیونی شروع کنی با آدم بزرگسالی شروع کن\r\nمدتی پس از مرگ پدر او تصمیم گرفت خانه پدری که تن...ها ارث پدرش بود را بفروشد پس به نصیحت پدرش عمل کرد و آن ملک را با زحمت فراوان سروسامان داد پس از اتمام کار دید خانه بسیار زیبا شده و حیف است که بفروشد پس منصرف شد.\r\nمدتی بعد خواست با فاحشه معروف شهرباشد .طبق نصیحت پدر صبح زود به در خانه اش رفت.اما چون صبح زود بود و فاحشه فرصت نکرده بود آرایش کند دید که او بسیار زشت است و منصرف شد.\r\nمدتی بعد نیز خواست قمار بازی کند.پس از پرسوجوی فراوان بزرگترین قمار باز شهر را پیدا کرد.دید او در خرابه ای زندگی میکند و حتی تن پوش مناسبی هم ندارد.وقتی علتش را پرسید قمارباز بزرگ گفت همه داراییم را در قمار باخته ام.....در نتیجه از این کار هم منصرف شده و به عمق نصایح پدرش پی برد\r\nاما زمانی که دوستانش سیگار برگی به او تعارف کردند که با آنها هم دود شود بیاد وصیت پدر افتاد و نپذیرفت تا با مرد پنجاه ساله ای که پدر یکی از\r\nدوستانش بود شروع کند ولی وقتی او را نزدیک به موت یافت که بر اثر این دود کردنها و مواد مخدر بود خدا را شکر کرد که او آلوده نشده وبه پدر رحمت فرستاد .\r\n"},{"id":2066,"category_id":2,"category_code":"s2","source_id":233,"title":"بخت","content":"روزی روزگاری نه در زمان های دور، در همین حوالی مردی زندگی می کرد که همیشه از زندگی خود گله مند بود و ادعا میکرد “بخت با من یار نیست” و تا وقتی بخت من خواب است زندگی من بهبود نمی یابد…!\r\nپیر خردمندی وی را پند داد تا برای بیدار کردن بخت خود به فلان کشور نزد جادوگری توانا برود…\r\nاو رفت و رفت تا در جنگلی سرسبز به گرگی رسید. گرگ پرسید: ای مرد کجا می روی؟\r\nمرد جواب داد: می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\r\nگرگ گفت : میشود از او بپرسی که چرا من هر روز گرفتار سر دردهای وحشتناک می شوم؟!!\r\nمرد قبول کرد و به راه خود ادامه داد.\r\nاو رفت و رفت تا به مزرعه ای وسیع رسید که دهقانانی بسیار در آن سخت کار می کردند. یکی از کشاورزها جلو آمد و گفت : ای مرد کجا می روی ؟!\r\nمرد جواب داد: می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\r\nکشاورز گفت : می شود از او بپرسی که چرا پدرم وصیت کرده است من این زمین را از دست ندهم زیرا ثروتی بسیار در انتظارم خواهد بود، در صورتی که در این زمین هیچ گیاهی رشد نمیکند و حاصل زحمات من بعد از پنج سال سرخوردگی و بدهکاری است ؟\r\nمرد قبول کرد و به راه خود ادامه داد…\r\nاو رفت و رفت تا به شهری رسید که مردم آن همگی در هیئت نظامیان بودند و گویا همیشه آماده برای جنگ ! شاه آن شهر او را خواست و پرسید : ای مرد به کجا می روی ؟!\r\nمرد جواب داد: می روم نزد جادوگر تا برایم بختم را بیدار کند، زیرا او جادوگری بس تواناست!\r\nشاه گفت : آیا می شود از او بپرسی که چرا من همیشه در وحشت دشمنان بسر می برم و ترس از دست دادن تاج و تختم را دارم، با ثروت بسیار و سربازان شجاع تاکنون در هیچ جنگی پیروز نگردیده ام ؟!!\r\nمرد قبول کرد و به راه خود ادامه داد و پس از راهپیمایی بسیار بالاخره جادوگری را که در پی اش راه ها پیموده بود را یافت و ماجراهای سفر را برایش تعریف کرد.\r\nجادوگر بر چهره مرد مدتی نگریست سپس رازهای را که ازش سوال شده بود با وی در میان گذاشت و گفت : از امروز بخت تو بیدار شده است برو و از آن لذت ببر!\r\nو مرد با بختی بیدار باز گشت…\r\nبه شاه شهر نظامیان گفت : تو رازی داری که وحشت برملا شدنش آزارت می دهد، با مردم خود یک رنگ نبوده ای، در هیچ جنگی شرکت نمی کنی، از جنگیدن هیچ نمی دانی، زیرا تو یک زن هستی و چون مردم تو زنان را به پادشاهی نمی شناسند، ترس از دست دادن قدرت تو را می آزارد و اما چاره کار تو ازدواج است، تو باید با مردی ازدواج کنی تا تو را غمخوار باشد و همراز، مردی که در جنگ ها فرماندهی کند و بر دشمنانت بدون احساس ترس بتازد…\r\nشاه اندیشید و سپس گفت : حالا که تو راز مرا و نیاز مرا دانستی با من ازدواج کن تا با هم کشوری آباد بسازیم…\r\nمرد خنده ای کرد و گفت : بخت من تازه بیدار شده است، نمی توانم خود را اسیر تو نمایم، من باید بروم و بخت خود را بیازمایم، می خواهم ببینم چه چیز برایم جفت و جور کرده است!\r\nو رفت…\r\nبه دهقان گفت : وصیت پدرت درست بوده است، شما باید در زیر زمین بدنبال ثروت باشی نه بر روی آن، در زیر این زمین گنجی نهفته است، که با وجود آن نه تنها تو که خاندانت تا هفت پشت ثروتمند خواهند زیست…!\r\nکشاورز گفت: پس اگر چنین است تو را هم از این گنج نصیبی است، بیا باهم شریک شویم که نصف این گنج از آن تو می باشد.\r\nمرد خنده ای کرد و گفت : بخت من تازه بیدار شده است، نمی توانم خود را اسیر گنج نمایم، من باید بروم و بخت خود را بیازمایم، می خواهم ببینم چه چیز برایم جفت و جور کرده است!\r\nو رفت…\r\nسپس به گرگ رسید و تمام ماجرا را برایش تعریف کرد و سپس گفت: سردردهای تو از یکنواختی خوراک است اگر بتوانی مغز یک انسان کودن و کور مغز را بخوری دیگر سر درد نخواهی داشت!\r\nخواننده محترم شما اگر جای گرگ بودید چکار می کردید ؟!!\r\nبله. درست است! گرگ هم همان کاری را کرد که شاید شما هم می کردید، مرد بیدار بخت قصه ی ما را به جرم غفلت از بخت بیدارش درید و مغز او را خورد…!\r\nبسیاری از مردم نقره را در انتظار طلا از دست می‌دهند. موریس وبستر\r\n"},{"id":2067,"category_id":2,"category_code":"s2","source_id":234,"title":"فرصت","content":"روزی ، پادشاهی تخته سنگی را در وسط جاده قرار داد و برای این که عکس العمل مردم را ببیند خودش را در جایی مخفی کرد.\r\nبعضی از بازرگانان و ندیمان ثروتمند پادشاه بی تفاوت از کنار تخته سنگ می گذشتند، بسیاری هم غُرو لُند می کردند که این چه شهری است که نظم ندارد. حاکم این شهر عجب مرد بی عرضه ای است و … با وجود این، هیچکس تخته سنگ را از وسط بر نمی داشت.\r\nنزدیک غروب، یک روستایی که پشتش بار میوه و سبزیجات بود، نزدیک سنگ شد. بارهایش را زمین گذاشت و با هر زحمتی بود تخته سنگ را از وسط جاده برداشت و آن را کناری نهاد. ناگهان کیسه ای را دید که زیر تخته سنگ قرار داده شده بود، کیسه را باز کرد و داخل آن سکه های طلا و یک یادداشت پیدا کرد که در آن نوشته شده بود:\r\n” هر سد و مانعی می تواند یک شانس برای تغییر زندگی انسان باشد.”\r\n"},{"id":2068,"category_id":2,"category_code":"s2","source_id":235,"title":"دشمن شناسی خروس","content":"گویند روزی خروسی با شیر همدل گشته و در مسافرتی همراه شد رفتند تا به شب خورده و به وقت استراحت رسیدند رفیق ارشد خروس را به بالای درخت فرستاد و خود کنار درخت و به قصد محافظت آرمید. \r\nهنگام سحر که شد خروس به رسم دیرین بانگ شیرین سر داد.روبهی مکار چون آواز پرنده خوش صدا را شنید فرصت مغتنم بدید با حیله پای کوبان آمد و بی خبر از وجود شیر و به لحن عابد پیر گفت اخوی صوت شریف حضرتعالی گویا فقط برای امامت جماعت خلق شده کرم نما و فرود آی تا جماعتی بگزاریم . \r\nخروس با بصیرت ودشمن شناسی جواب داد :اخوی بنده فقط موذنم حضرت پیش نماز،سر سجاده نماز آماده راز و نیازست در این حال روبه شیر را دید که متوجه تعارفات است و فورا پا به فرار بگذاشت شیر صدا زد اخوی کجا می روی مگر قرار نبود نماز جماعت به جای آوریم؟\r\n"},{"id":2069,"category_id":2,"category_code":"s2","source_id":236,"title":"بزکشی","content":"روزگاری مرید ومرشدی خردمند در سفر بودند. در یکی از سفر هایشان در بیابانی گم شدند وتا آمدند راهی پیدا کنند شب فرا رسید. ناگهان از دور نوری دیدند وبا شتاب سمت آن رفتند.در آنجا در چادری محقر زنی با چند فرزند خود زندگی میکرد. آن ها آن شب را مهمان او شدند. واو نیز از شیر تنها بزی که داشت به آن ها داد تا گرسنگی خود را بر طرف کنند. روز بعد مرید و مرشد از زن تشکر کردند و به راه خود ادامه دادند . درمسیر، مرید همواره در فکرآن زن بود و این که چگونه فقط با یک بز زندگی میگذرانند و ای کاش قادر بودند به آن زن کمک میکردند. این موضوع را با مرشد در میان گذاشت. مرشد فرزانه پس از اندکی تامل پاسخ داد:\"اگر واقعا میخواهی به آن ها کمک کنی برگرد و بزشان را بکش!\". مرید ابتدا بسیار متعجب شد ولی از آن جا که به مرشد خود ایمان داشت چیزی نگفت وبرگشت و شبانه بز را در تاریکی کشت واز آن جا دور شد.... سال های سال گذشت و مرید همواره در این فکر بود که بر سر آن زن و بجه هایش چه آمد. روزی از روزها مرید ومرشد وارد شهری زیبا شدند که از نظر تجاری نگین آن منطقه بود.سراغ تاجر بزرگ شهر را گرفتند و مردم آن ها را به قصری در داخل شهر راهنمایی کردند.صاحب قصر زنی بود با لباس های بسیار مجلل و خدم و حشم فراوان که طبق عادتش به گرمی از مسافرین استقبال و پذیرایی کرد، و دستور داد به آن ها لباس جدید داده و اسباب راحتی و استراحت فراهم کنند. پس از استرا حت آن ها نزد زن رفتند تا از رازهای موفقیت وی جویا شوند. زن نیز چون آن ها را مرید و مرشدی فرزانه یافت، پذیرفت و شرح حال خود را این گونه بیان نمود: سال های بسیار پیش شوهرم را از دست دادم و با چند فرزندم و تنها بزی که داشتیم زندگی را سپری میکردیم. یک روز صبح دیدیم که بزمان مرده و دیگر هیچ نداریم. ابتدا بسیار اندوهگین شدیم ولی پس از مدتی مجبور شدیم برای گذران زندگی با فرزندانم هر کدام به کاری روی آوریم.ابتدا بسیار سخت بود ولی کم کم هر کدام از فرزندانم موفقیت هایی در کارشان کسب کردند.فرزند بزرگترم زمین زراعی مستعدی در آن نزدیکی یافت. فرزند دیگرم معدنی از فلزات گرانبها پیدا کرد ودیگری با قبایل اطراف شروع به داد و ستد نمود. پس از مدتی با آن ثروت شهری را بنا نهادیم و حال در کنار هم زندگی میکنیم. مرید که پی به راز مسئله برده بود از خوشحالی اشک در چشمانش حلقه زده بود.... \r\nهر یک از ما بزی داریم که اکتفا به آن مانع رشدمان است، و باید برای رسیدن به موفقیت و موقعیت بهتر آن را فدا کنیم. \r\n"},{"id":2070,"category_id":2,"category_code":"s2","source_id":237,"title":"دریایی باش","content":"شاگردی ازاستاد پیرش خواست که یک درس به یاد ماندنی به اویاد دهد.استاد از شاگردش کیسه ای نمک خواست . استاد پیر مشتی از نمک را داخل لیوان نیمه پری ریخت و ازاو خواست آب را سر بکشد. شاگرد به سختی توانست جرعه کوچکی از آب داخل لیوان را بیاشامد . \r\nاستاد پرسید : \" مزه اش چطور بود ؟ \" \r\nشاگرد پاسخ داد : \" بد جوری شور و بد مزه است ، اصلا نمیشود آن را خورد. \"\r\nپیر فرزانه از شاگردش خواست مشتی نمک بردارد و او را همراهی کند .آن دو رفتند تا کنار دریاچه رسیدند.\r\nاستاد از شاگردش خواست تا نمکها را داخل دریاچه بریزد. سپس لیوانی را از آب دریاچه پر کرد وازشاگردش خواست آن را بنوشد . \r\nشاگرد براحتی تمام آب داخل لیوان را سر کشید . استاد اینبارهم از او مزه آب داخل لیوان را پرسید. \r\nشاگرد پاسخ داد : \" کاملا معمولی بود ..\" \r\nپیرفرزانه گفت : \" رنجها و سختیهایی که انسان در طول زندگی با آنها روبرو میشود همچون مشتی نمک است و اما این روح و قدرت پذیرش انسان است که هر چه بزرگتر و وسیعتر باشد ، میتواند بارآن همه رنج و اندوه را به راحتی تحمل کند. \r\nسعی کن دریا باشی نه لیوان آب\r\n"},{"id":2071,"category_id":2,"category_code":"s2","source_id":238,"title":"شانس","content":"مرد جوانی در آرزوی ازدواج با دختر کشاورزی بود. کشاورز گفت برو در آن قطعه زمین بایست. من سه گاو نر را آزاد میکنم اگر توانستی دم یکی از این گاو نرها را بگیری من دخترم را به تو خواهم داد. مرد قبول کرد، در طویله اولی که بزرگترین بود باز شد . باور کردنی نبود بزرگترین و خشمگین ترین گاوی که در تمام عمرش دیده بود. گاو با سم به زمین میکوبید و به طرف مرد جوان حمله برد. جوان خود را کنار کشید تا گاو از مرتع گذشت. دومین در طویله که کوچکتر بود باز شد. گاوی کوچکتر از قبلی که با سرعت حرکت کرد . جوان پیش خودش گفت : منطق می گوید این را ولش کنم چون گاو بعدی کوچکتر است و این ارزش جنگیدن ندارد. سومین در طویله هم باز شد و همانطور که فکر میکرد ضعیفترین و کوچکترین گاوی بود که در تمام عمرش دیده بود. پس لبخندی زد و در موقع مناسب روی گاو پرید و دستش را دراز کرد تا دم گاو را بگیرد.اما.........گاو دم نداشت!!!! "},{"id":2072,"category_id":2,"category_code":"s2","source_id":239,"title":"معجون آرامش","content":"کسری انوشیروان بر بزرگمهر خشم گرفت و در خانه ای تاریک به زندانش فکند و فرمود او را به زنجیر بستند.چون روزی چند بر این حال بود،کسری کسانی را فرستاد تا از حالش پرسند. آنان بزرگمهر را دیدند با دلی قوی و شادمان.بدو گفتند:در این تنگی و سختی تو را آسوده دل می بینم! گفت:معجونی ساخته ام از شش جزء و به کار می برم و چنین که می بینید مرا نیکو می دارد. گفتند:آن معجون را شرح بازگوی که ما را نیز هنگام گرفتاری به کار آید گفت:آری جزء نخست اعتماد بر خدای عزوجل است ،دوم آنچه مقدر است بودنی است،سوم شکیبایی برای گرفتار بهترین چیزهاست.چهارم اگر صبر نکنم چه کنم،پس نفس خویش را به جزع و زاری بیش نیازارم،پنجم آنکه شاید حالی سخت تر از این رخ دهد.ششم آنکه از این ساعت تا ساعت دیگر امید گشایش باشد چون این سخنان به کسری رسید او را آزاد کرد و گرامی داشت."},{"id":2073,"category_id":2,"category_code":"s2","source_id":240,"title":"نا امیدی","content":"می گویند روزی شیطان تصمیم گرفت که از کار خود دست بکشد، بنابراین اعلام کرد که می خواهد ابزارش را به قیمتی مناسب به فروش بگذارد. پس وسایل کارش را به نمایش گذاشت که شامل خودپرستی، نفرت، ترس، خشم، حسادت، شهوت، قدرت طلبی و غیره می شد.\r\nاما یکی از این ابزار، بسیار کهنه و کار کرده به نظر می رسید و شیطان حاضر نبود که آن را به قیمت ارزان بفروشد. کسی از او پرسید : این وسیله گران قیمت چیست؟ شیطان گفت:این نومیدی و افسردگی ست.\r\nپرسیدند : چرا این همه گران است؟ \r\nشیطان گفت : زیرا این وسیله برای من بیش از این ابزار دیگر مؤثر بوده است. هرگاه سایر وسایلم بی اثر می شوند، تنها با این وسیله می توانم قلب انسان ها را بگشایم و کارم را انجام دهم. اگر بتوانم کسی را وادارم که احساس ناامیدی، یأس، دلسردی، مطرود بودن و تنهایی کند، می توانم هرچه که می خواهم با او بکنم. من این وسیله را روی همه ی انسان ها امتحان کرده ام و به همین دلیل این همه کهنه است.\r\n"},{"id":2074,"category_id":2,"category_code":"s2","source_id":241,"title":"بهشت و جهنم","content":"واعظی در منبر همیشه اوقات در اوصاف بهشت سخن می راند؛ یکی از مستمعین به او اعتراض کرد و گفت : چرا هیچوقت از جهنم سخنی نمی گویید و همواره بهشت را توصیف می کنید ؟\r\nواعظ در پاسخ گفت : چون جهنم را به چشم خواهید دید لذا گفتن ندارد؛ لذا ما آنچه را که نمی بینید برایتان نقل و توصیف می کنیم !\r\n"},{"id":2075,"category_id":2,"category_code":"s2","source_id":242,"title":"نان","content":"عابدی را حکایت کنند که شبی ده من طعام بخوردی و تا سحر ختمی بکردی . صاحب دلی بشنید و گفت : اگر نیم نانی بخوردی و بخفتی ، بسیار از این فاضل تر بودی .\r\nاندرون از طعام خالی دار تا در او نور معرفت بینی\r\nتهی از حکمتی به علتِ آن که پُری از طعام تا بینی\r\nگلستان سعدی\r\n"},{"id":2076,"category_id":2,"category_code":"s2","source_id":243,"title":"عطایش به لقایش بخشیدم","content":"درویشی را ضرورتی پیش آمد .کسی گفت:فلان نعمتی دارد بی قیاس.اگر به سر حاجت تو واقف گردد همانا که در قضای آن توقف روا ندارد.گفت:من او را ندانم.گفت:منت رهبری کنم.دستش گرفت تا به منزل آن شخص درآورد. \r\nیکی را دید لب فروهشته وتند نشسته برگشت وسخن نگفت. کسی گفتش چه کردی؟ گفت: عطای او را به لقایش بخشیدم. \r\nمبر حاجت بنزدیک ترشروی \r\nکه از خوی بدش فرسوده گردی \r\nاگر گویی غم دل با کسی گوی \r\nکه از رویش به نقد آسوده گردی\r\n"},{"id":2077,"category_id":2,"category_code":"s2","source_id":244,"title":"ضرورت عمل و آثار معصیت","content":"ابوسعید ابوالخیر نیشابوری، عارف برجسته رباعیهای نغز دارد. روزی ابوعلی سینا در مجلس وعظ ابوسعید ابوالخیر شرکت کرد. ابوسعید در باره ضرورت عمل و آٍثار طاعت و معصیت سخن می گفت: بو علی رباعی زیر را به عنوان اینکه ما تکیه بر رحمت حق داریم نه بر عمل خویشتن انشا کرد: \r\nمائیم به عفو تو لاکرده \r\nوز طاعت و معصیت تبرا کرده \r\nآنجا که عنایت تو باشد، باشد \r\nناکرده چو کرده، کرده چون ناکرده \r\nابوسعید ابوالخیر فی الفور گفت: \r\nای نیک نکرده و بدیها کرده \r\nوانگه به خلاص خود تمنا کرده \r\nبر عفو مکن تکیه که هرگز نبود \r\nناکرده چو کرده، کرده چو ناکرده . \r\n"},{"id":2078,"category_id":2,"category_code":"s2","source_id":245,"title":"در شکست در پیروزی","content":"در روزگاران قدیم، سرداری بود مهربان و با انصاف. او به دانشمندان و بزرگان، احترام خاصی میگذاشت و همیشه از حرفهایشان استفاده میکرد. روزی به عارفی گفت: « یه جمله ایی به من بگو که در غم و شادی، مرا تسکین دهد. نه از غمها ناراحت شوم و نه از شادیها، مغرور. »\r\nعارف، دو تکه کاغذ برداشت و چیزی نوشت و گفت: « این را در جیب چپت بگذار و این یکی را در جیب راستت. هنگام ناراحتی و شکست، چپت را ببین و موقع شادی و پیروزی، راستت را.»\r\nچندی بعد ، سردار ، در یکی از جنگها، شکست خورد. به لشکرش نگاهی انداخت و آهی کشید. به یاد حرف عارف افتاد. آن برگه را باز کرد و خواند : « این نیز ، بگذرد. »\r\nبا خواندن نوشته روحیه گرفت و آرام شد و سپاه را جمع کرد و سر و سامانی داد و از پشت به دشمن حمله کرد و اینبار ، پیروز شد.\r\nدر حالیکه خوشحال بود ، باز به یاد عارف افتاد. برگه دوم را باز کرد و خواند : در آن نوشته شده بود « این نیز ، بگذرد. »\r\n"},{"id":2079,"category_id":2,"category_code":"s2","source_id":246,"title":"قدر عافیت","content":"پادشاهی با غلامی عجمی در کشتی نشست و غلام ، دیگر دریا را ندیده بود و محنت کشتی نیازموده ، گریه و زاری درنهاد و لرزه براندامش اوفتاد. چندانکه ملاطفت کردند آرام نمی گرفت و عیش ملک ازو منغص بود ، چاره ندانستند . حکیمی در آن کشتی بود ، ملک را گفت : اگر فرمان دهی من او را به طریقی خامش گردانم . گفت : غایت لطف و کرم باشد . بفرمود تا غلام به دریا انداختند . باری چند غوطه خورد ، مویش را گرفتند و پیش کشتی آوردند به دو دست در سکان کشتی آویخت. چون برآمد به گوشه ای بنشست و قرار یافت . ملک را عجب آمد. پرسید: درین چه حکمت بود ؟\r\nگفت : از اول محنت غرقه شدن ناچشیده بود و قدر سلامتی نمی دانست ، همچنین قدر عافیت کسی داند که به مصیبتی گرفتار آید.\r\n"},{"id":2080,"category_id":2,"category_code":"s2","source_id":247,"title":"خانه ی دوست","content":"درویشی را ضرورتی پیش آمد، گلیمى را از خانه یکى از پاک مردان دزدید. قاضى فرمود تا دستش بدر کنند.\r\nصاحب گلیم شفاعت کرد که من او را حلال کردم.\r\nقاضى گفت : به شفاعت تو حد شرع فرو نگذارم.\r\nصاحب گلیم گفت : اموال من وقف فقیران است ، هر فقیرى که از مال وقف به خودش بردارد از مال خودش برداشته ، پس قطع دست او لازم نیست .\r\nقاضى از جارى نمودن حد دزدى منصرف شد، ولى دزد را مورد سرزنش ‍ قرار داد و به او گفت : آیا جهان بر تو تنگ آمده بود که فقط از خانه چنین پاک مردى دزدى کنى ؟!\r\nدزد گفت : اى حاکم ! مگر نشنیده اى که گویند: خانه دوستان بروب ولى حلقه در دشمنان مکوب .\r\n"},{"id":2081,"category_id":2,"category_code":"s2","source_id":248,"title":"ما و او","content":"از شبلی سوال کردند که «عارف کیست؟» گفت؛ «آنکه تاب پشه نیاورد». وقتی دیگر، از او همان سوال کردند، گفت؛ «عارف آن است که هفت آسمان و زمین را به یک موی مژه بردارد». گفتند؛ «یا شیخ، وقتی چنین گفتی و اکنون چنین می گویی؟» گفت؛ «آنگاه ما، ما بودیم. اکنون ما، «او»ست!»"},{"id":2082,"category_id":2,"category_code":"s2","source_id":249,"title":"زشتی و زیبایی","content":"روزی، آدم نادانی که صورت زیبایی داشت، به « افلاطون » که مردی دانشمند بود، گفت: « ای افلاطون، تو مرد زشتی هستی.» \r\nافلاطون گفت: « عیبی که بود گفتی و آن را به همه نشان دادی، اما آنچه که دارم، همه هنر است، ولی تو نمی توانی آن را ببینی. هنر تو، تنها همین حرفی بود که گفتی، بقیه وجود تو سراسر عیب است و زشتی. بدان که قبل از گفتن تو، خود را در آینه دیده بودم و به زشتی صورت خودم پی برده بودم. بعد از آن سعی کردم وجودم را پر از خوبی و دانش کنم تا دو زشتی در یک جا جمع نشود. تو مردی زیبارو هستی، اما سعی کن با رفتار و کارهای زشت خود، این زیبایی رابه زشتی تبدیل نکنی. »\r\n"},{"id":2083,"category_id":2,"category_code":"s2","source_id":250,"title":"شکایت از درد","content":"رابعه مردی را دید که پارچه ای بر سر خود بسته است.پرسید:چرا این پارچه را به سر بسته ای؟\r\nمرد گفت:سرم درد میکند.\r\nرابعه پرسید:چند سال داری؟\r\nمرد گفت:سی سال.\r\nرابعه پرسید:در این سی سال بیشتر تندرست بودی یا بیمار؟\r\nمرد گفت:تندرست.\r\n\r\nرابعه گفت:هرگز در تمام مدت عمرت نشانه ی شکر بر سرت گذاشته ای که اکنون برای یک سر درد پارچه ای به نشانه ی شکایت میبندی؟\r\n"},{"id":2084,"category_id":2,"category_code":"s2","source_id":251,"title":"مردان و زنان","content":"جماعتی خواستند رابعه را امتحان کنند گفتند:همه ی بزرگی ها را به مردان داده اند و تاج جوانمردی بر سر مردان گذاشته اند و کرامت و بزرگواری در مردان بیشتر است.هرگز هیچ زنی پیامبر نبوده است.\r\nرابعه گفت:اینها که گفتید درست است اما تکبر و خود پرستی را بیشتر به مردان داه اند.هیچ زنی (انا ربکم الاعلی) نگفت چنانکه فرعون گفت و هیچ زنی نافرمانی نکرد چنانکه بسیاری از مردان کردند.\r\n"},{"id":2085,"category_id":2,"category_code":"s2","source_id":252,"title":"خریدار دنیا","content":"یکی از بزرگان بصره نزد رابعه امد و از بدی های دنیا بسیار سخن گفت.\r\nرابعه گفت:تو دنیا را بسیار دوست داری.\r\nمرد با تعجب گفت:من این همه از بدی های دنیا گفتم و تو میگویی دنیا را بیشتر دوست دارم؟\r\nرابعه گفت:کسی که به زبان ارزش کالایی را بشکند خریدار ان کالاست.اگر از دنیا فارغ بودی این همه درباره ی آن صحبت نمیکردی.هرکس چیزی را دوست دارد بیشتر از ان صحبت میکند.\r\n"},{"id":2086,"category_id":2,"category_code":"s2","source_id":253,"title":"اعتراض","content":"زاهدی بر منبر رفته بود و مردم را نصیحت میکرد و می گفت:ای مردم از رحمت خدا نا امید نشوید.هرکس دری را بسیار بکوبد بالاخره باز میشود.\r\nرابعه در مجلس او حضور داشت و گفت:چرا می گویی باز میشود؟مگر در رحمت خدا بسته است که باز شود؟\r\n"},{"id":2087,"category_id":2,"category_code":"s2","source_id":254,"title":"مرگ رابعه","content":"وقتی هنگام مرگ رابعه نزدیک شد بزرگان بر بالین او جمع شدند.\r\nرابعه گفت:برخیزید و جا را برای رسولان خدا باز کنید.\r\nآنان برخاسته و بیرون رفتند و در را بستند.\r\nناگهان آوازی شنیدند که:ای نفس آرام یافته به سوی پروردگارت به خشنودی بازگرد و در میان بندگانم در آی و در بهشت من فرود آی.\r\nمدتی گذشت و صدایی نیامد.\r\nبزرگان به اتق رفتند و دیدند رابعه وفات کرده است.\r\n"},{"id":2088,"category_id":2,"category_code":"s2","source_id":255,"title":"پاسخ به نکیر و منکر","content":"بعد از مرگ رابعه او را در خواب دیدند و گفتند:از نکیر و منکر بگو که شب اول قبر با تو چه گفتند؟\r\nگفت:چون آن دو جوانمرد پیش من آمدند و پرسیدند پروردگار تو کیست؟گفتم باز گردید و به پروردگار بگویید با وجود هزاران هزار مخلوق از یاد پیرزنی چون من غافل نماندی.من که از هر دو جهان فقط تو را دارم چگونه فراموشت کرده باشم که اکنون کسانی را پیش من می فرستی و می پرسی پروردگار تو کیست؟\r\n"},{"id":2089,"category_id":2,"category_code":"s2","source_id":256,"title":"دینار در دهان ماهیان","content":"مالک دینار یکی از بزرگان بصره بود.بعضی گفته اند که دینار نام پدر او بود اما بعضی دیگر اعتقاد دارند که روزی مالک با کشتی عازم سفر بود در میان دریا مزد راه از او خواستند.گفت ندارم.\r\nآنقدر او را زدند که از هوش رفت.چون به هوش آمد باز از او مزد خواستند.گفت ندارم.بار دیگر او را زدند و چون پولی نداشتند خواستند پایش را بگیرند و او را به دریا بیندازند.\r\nناگهان ماهیان دریا در حالی که هر کدام دیناری در دهان داشتند از آب بالا آمدند.\r\nمالک دست دراز کرد و از دهان هر یک دیناری برداشت و به صاحبان کشتی داد.\r\nچون آنان این صحنه را دیدند در پای او افتادند.\r\nآنگاه مالک پای از کشتی بیرون گذاشت و بر روی آب رفت و ناپدید شد.به این سبب او را مالک دینار گفته اند.\r\n"},{"id":2090,"category_id":2,"category_code":"s2","source_id":257,"title":"جهاد","content":"روزی مالک تعریف میکرد که:چند سال بود در حسرت جهاد بودم.چون روز جنگ فرا رسید ناگهان تب کردم.به قدری حالم بد بود که نتوانستم به جهاد بروم.خوابیدم و با خود گفتم ای تن اگر تو در نظر خدا ارزش داشتی این تب نمی آمد.\r\nوقتی به خواب رفتم ندایی شنیدم که :ای مالک اگر تو امروز به جنگ میرفتی اسیر میشدی و در اسارت به تو گوشت خوک می خوراندند.پس اگر این تب نبود به کار حرام مجبور میشدی.بنابراین بیماری برایت هدیه ای بزرگ بوده است.\r\nاز خواب بیدار شدم و شکر خداوند گفتم.\r\n"},{"id":2091,"category_id":2,"category_code":"s2","source_id":258,"title":"در راه حج","content":"یک سال رابعه خواست به سفر حج برود.الاغی داشت که بار سفرش را میکشید.در میان راه الاغ مرد و رابعه در صحرا تنها ماند.\r\nقافله ای از کنار او میگذشت.اهل قافله به او گفتند:بار خود را بده تا برایت بیاوریم.\r\nرابعه گفت:من به امید شما نیامده ام.\r\nقافله رفت و رابعه رو به درگاه خداوند کرد و گفت:خدایا آیا توانگران با زنی تنها چنین رفتار میکنند؟مرا به خانه ی خود دعوت کرده ای اما در میان راه الاغم را از من گرفته ای و در بایابان تنها رهایم کرده ای؟\r\nدر همان موقع الاغ مرده به امر خدا از جا برخاست.رابعه بار خود را بر پشت آن گذاشت و دوباره راهی شد.\r\n"},{"id":2092,"category_id":2,"category_code":"s2","source_id":259,"title":"دزد در خانه","content":"شبی رابعه در خواب بود.دزدی به خانه ی او امد و چادرش را برداشت.میخواست از خانه بیرون برود اماراه را پیدا نمیکرد.\r\nچادر را بر سر جایش گذاشت.این بار راه را پیدا کرد.بار دیگر چادر را برداشت و این بار هم راه را پیدا نکرد.تا هفت مرتبه این کار تکرار شد اما فایده ای نداشت.\r\nناگهان از کنج خانه ندایی برخاست:ای مرد خود را به زحمت مینداز او سالهاست خود را به خدا سپرده است.شیطان جرئت نمیکند به او نزدیک شود چه رسد به اینکه دزدی بخواهد به چادر او نزدیک شود.\r\nبیهوده تلاش نکن زیرا اگر یک دوست در خواب باشد دوست دیگر بیدار است.\r\n"},{"id":2093,"category_id":2,"category_code":"s2","source_id":260,"title":"رابعه و ابراهیم ادهم","content":"ابراهیم ادهم که از عارفان بزرگ ان روزگار بود چهارده سال تمام پیاده سفر کرد تا به خانه ی کعبه رسید.او در این مدت دو رکعت نماز می خواند و قدمی بر میداشت و می گفت:اگر دیگران این راه را با قدم می آیند من به دیده می روم.\r\nوقتی ابراهیم به مکه رسید خانه کعبه را ندید و با خود گفت:این دیگر چه حادثه ایست؟شاید به چشم من آسیبی رسیده است.\r\nدر همین فکر بود که ندایی به گوشش رسید:چشم تو آسیب ندیده است.خانه ی کعبه به استقبال بانویی رفته است که به سوی مکه می آید.\r\nابراهیم با حسرت و شگفتی و گفت:این کدام زن است که چنین مقامی دارد؟\r\nناگهان رابعه را دید که عصا زنان می آمد و همین که نزدیک شد خانه ی کعبه به جایگاه خود بازگشت.\r\nابراهیم فریاد زد:ای رابعه این چه شوری است که در جهان انداخته ای؟\r\nرابعه گفت:تو شور در جهان انداخته ای که چهارده سال رنج کشیدی تا به خانه ی خدا رسیدی.\r\nابراهیم گفت:آری من چهارده سال در این راه به نماز مشغول بودم اما در حیرتم که چرا مقام تو را نیافتم؟\r\nرابعه گفت:زیرا که تو در نماز بودی و من در نیاز.\r\n"},{"id":2094,"category_id":2,"category_code":"s2","source_id":261,"title":"لقمه ی حلال","content":"روزی خدمتکار رابعه غذا می پخت و به پیاز احتیاج داشت.از رابعه خواست اجازه بدهد که از همسایه پیاز بگیرد.\r\nرابعه گفت:چهل سال است با خدای خود عهد کرده ام که از غیر او هیچ نخواهم.غذا را بدون پیاز درست کن.\r\nدر همین حال پرنده ای از انجا میگذشت که پیازی در چنگال داشت.پرنده پیاز را رها کرد و در دیگ انداخت.\r\n\r\nکنیزک خوشحال شد اما رابعه گفت:من نمیدانم این پرنده پیاز را از کجا برداشته است.\r\nوترک غذا کرد و نان خالی خورد.\r\n"},{"id":2095,"category_id":2,"category_code":"s2","source_id":262,"title":"موم و سوزن و تارمو","content":"روزی رابعه سه چیز را برای حسن بصری فرستاد:تکه ای موم و یک سوزن و یک تار مو.\r\nحسن بصری از این کار تعجب کرد.پیش رابعه رفت و مقصود او را از این کار پرسید.\r\nرابعه گفت:موم را فرستادم تا بگویم مثل موم خود را بسوز و جهان را روشن کن.سوزن را به این خاطر فرستادم که بگویم برهنه باش و همواره کار کن.چون هر دوی این خصلت ها را به دست آوردی مثل مو باش تا کارهایت باطل نشود.(چرا که مو از همه چیز باریکتر است اما هرگز از درد نمی نالد و شکایتی نمیکند)\r\n"},{"id":2096,"category_id":2,"category_code":"s2","source_id":263,"title":"رابعه و ریسمان","content":"رابعه دو رشته ریسمان بافته بود تا بفروشد و از ان لقمه ای نان بدست آورد.آنها را به بازار برد و به دو درهم فروخت.\r\nیک درهم را در این دست و درهم دیگر را در دست دیگر گرفت.\r\nعلت این کار را از او پرسیدند.گفت:ترسیدم اگر هر دو را با هم در دست گیرم به چشمم زیاد بیاید و مرا فریفته کند.\r\n"},{"id":2097,"category_id":2,"category_code":"s2","source_id":264,"title":"اندوه بزرگ","content":"مردی با ظاهری اندوهگین فریاد میزد:اندوه بزرگی دارم.\r\nرابعه گفت:بگو غمی ندارم زیرا اگر اندوه واقعی در دلت بود جرئت نداشتی که نفس بکشی چه رسد به اینکه فریاد بزنی.\r\n"},{"id":2098,"category_id":2,"category_code":"s2","source_id":265,"title":"هنر","content":"حکیمی پسران را پند همی داد که جانان پدر هنر آموزید که ملک و دولت دنیا اعتماد را نشاید و سیم و زر در سفر بر محل خطر است یا دزد به یک بار ببرد یا خواجه به تفاریق بخورد. اما هنر چشمه زاینده است و دولت پاینده و گر هنرمند از دولت بیفتد غم نباشد که هنر در نفس خود دولت است. هرجا که رود قدر بیند و در صدر نشیند و بی هنر لقمه چیند و سختی بیند."},{"id":2099,"category_id":2,"category_code":"s2","source_id":266,"title":"اجل","content":"دست و پا بریده ای هزار پایی بکشت. صاحبدلی بر او گذر کرد و گفت سبحان الله با هزار پای که داشت چون اجلش فرا رسید از بی دست و پایی گریختن نتوانست."},{"id":2100,"category_id":2,"category_code":"s2","source_id":267,"title":"صید","content":"صیادی ضعیف را ماهی قوی به دام اندر افتاد. طاقت حفظ آن نداشت ماهی بر او غالب آمد و دام از دستش در ربود و برفت. دیگر صیادان دریغ خوردند و ملامتش کردند که چنین صیدی در دامت افتاد و ندانستی نگاه داشتن. گفت ای برادران چه توان کردن؟ مرا روزی نبود و ماهی را همچنان روزی مانده بود. صیاد بی روزی در دجله نگیرد و ماهی بی اجل بر خشک نمیرد."},{"id":2101,"category_id":2,"category_code":"s2","source_id":268,"title":"طاس پر آب","content":"روز شیخ المشایخ نزد ابوالحسن خرقانی آمد؛طاسی پر آب پیش وی نهاده بود.شیخ المشایخ دست در آب کرد و ماهی زنده بیرون آورد.ابوالحسن گفت:\"از آب ماهی نمودن آسان است.از آب،آتش باید نمود.!\" شیخ المشایخ گفت:\"بیا تا به این تنور فرو شویم تا زنده کی برآید.\"شیخ گفت:\"یا عبدالله،بیا تا به نیستی خود فرو شویم تا به هستی او که برآید.\"شیخ المشایخ دیگر سخن نگفت."},{"id":2102,"category_id":2,"category_code":"s2","source_id":269,"title":"سود","content":"کسی از احمد بن محمد بن عبدالکریم آملی معروف به \"ابوالعباس قصاب\"پرسید:\"شیخا!کرامت تو چیست؟\"گفت:\"من کرامت نمی دانم.اما آن دانم که در ابتدا هر روز گوسفندی می کشتم و تا شب بر سر می نهادم و در همه ی شهر می گرداندم تا اندکی سود ببرم یا نه و امروز چنان می بینم که مردان عالم از مشرق تا به مغرب بر می خیزند و به زیارت ما،پای افزار در پا می کنند چه کرامت بالاتر از این می خواهید؟\""},{"id":2103,"category_id":2,"category_code":"s2","source_id":270,"title":"بصیرت نگر","content":"ظهر یکی از روزهای رمضان بود، حسین بن منصور حلاج همیشه برای جزامی‌ها غذا می‌برد و آن روز هم داشت از خرابه‌ای که بیماران جزامی آنجا زندگی می‌کردند می‌گذشت. \r\nجزامی ها داشتند ناهار می‌خوردند، ناهار که چه، ته‌مانده‌ی غذاهای دیگران و چیزهایی که در آشغال‌ها پیدا کرده بودند و چند تکه نان. \r\nیکی از جزامی‌ها بلند میشه به حلاج می‌گوید: «بفرما ناهار!»\r\nحلاج می‌پرسد: «مزاحم نیستم؟»\r\nمی‌گویند: «نه، بفرما.»\r\nحسین حلاج پای سفره جزامی‌ها می‌نشیند. یکی از جزامی‌ها می‌پرسد: «تو چطور که از ما نمی ترسی، دوستان تو حتی چندش‌شان می‌شود از کنار ما رد شوند، ولی تو الان...؟»\r\n\r\nحلاج می‌گوید: «خب آنان الان روزه هستند برای همین این جا نمی‌آیند تا دلشان هوس غذا نکند.»\r\nمی‌پرسند: «پس تو که این همه عارفی و خداپرستی، چرا روزه نیستی؟»\r\nمی‌گوید: «نشد امروز روزه بگیرم…»\r\nحلاج دست به غذاها می‌برد و چند لقمه می‌خورد، درست از همون غذاهایی که جزامی‌ها به آنها دست زده بودند. \r\nچند لقمه که می‌خورد، بلند می‌شود و تشکر می‌کند و می‌رود. \r\nموقع افطار حلاج لقمه‌ای در دهان می‌گذارد و می‌گوید: «خدایا روزه من را قبول کن.»\r\nیکی از دوستاش می‌گوید: «ولی ما تو را دیدیم که داشتی با جزامی‌ها ناهار می‌خوردی!»\r\nحسین حلاج در جوابش می‌گوید: «او خداست، روزه‌ی من برای خداست. او می‌داند که من آن چند لقمه غذا را از روی گرسنگی و هوس نخوردم. دل بنده‌اش را می‌شکستم، روزه‌ام باطل می‌شد یا با خوردن چند لقمه غذا؟»\r\n"},{"id":2104,"category_id":2,"category_code":"s2","source_id":271,"title":"عشق به خدا","content":"\r\nروزی سه عارف بزرگ ،\r\nحسن بصری ، مالک دینار و شفیق بلخی\r\nبه دیدن رابعه عدویه که بیمار بود رفتند. \r\nحسن بصری گفت: \r\nهیچکس در عشق خود نسبت به خداوند صادق نیست \r\nمگر اینکه ضربه های خدای خود را با شکیبایی تحمل کند. \r\nرابعه گفت:\r\n  ازین گفته بوی منیت میاید \r\nشفیق بلخی گفت : هیچکس در دعوی خویش صادق نیست\r\nمگر اینکه در مقابل ضربه های خداوند شکر به جای آورد. \r\nرابعه گفت: \r\nبهتر ازین باید گفت این سخن هنوز بوی منیت میدهد. \r\nمالک دینار گفت : در دعوی خود صادق نیست\r\nهر که از ضربه های دوست خویش لذت نبرد. \r\nرابعه گفت : خوب است اما بهتر ازین باید گفت\r\nهنوز سایه ضعیفی از منیت در آن نهفته است \r\nهمه گفتند اکنون تو خود بگو\r\nاو گفت : هیچکس در دعوی خویش صادق نیست\r\nاگر با مشاهده محبوب خویش رنج و درد خود را فراموش نکند...\r\n"},{"id":2105,"category_id":2,"category_code":"s2","source_id":272,"title":"زیر بار خدا","content":"در سالی که قحطی بیداد کرده بود و مردم همه زانوی غم به بغل گرفته بودند مرد عارفی از کوچه ای می گذشت غلامی را دید که بسیار شادمان و خوشحال است. \r\nبه او گفت چه طور در چنین وضعی می خندی و شادی می کنی ؟\r\nجواب داد که من غلام اربابی هستم که چندین گله و رمه دارد و تا وقتی برای او کار می کنم روزی مرا می دهد پس چرا غمگین باشم در حالی که به او اعتماد دارم؟\r\nآن مرد عارف که از عرفای بزرگ ایران بود گفت: از خودم شرم کردم که غلام به اربابی با چند گوسفند توکل کرده و غم به دل راه نمی دهد و من خدایی دارم که مالک تمام دنیاست و نگران روزی خود هستم!\r\n"},{"id":2106,"category_id":2,"category_code":"s2","source_id":273,"title":"پادشاه و گنهکار","content":"آورده اند که، در روزگار ملوک عجم، یکی از مقربان پادشاه جرمی کرده بود، و پادشاه بر وی متغیر شده بود و در معرض تعذیب افتاده. روزی پادشاه با یکی از خواص خود در باب این مجرم مفاوضت پیوست. ]گفت وگو کرد[ آن خاصگی با این مجرم بد بود، گفت؛ «ای پادشاه، این جرم که او کرده است اگر بنده بودی او را سیاست کردی» ]اگر من بودم، او را مجازات می کردم[ ملک چون این بشنید، گفت:\r\n«اکنون تو نیستی و منم. کردار من به خلاف کردار تو باید باشد»آن مجرم را عفو کرد و بنواخت. و همه ملوک عجم این سخن را بپسندیدند و بر دفاتر ثبت کردند.و فایده این حکایت آن است که ملوک را کار به همت خود باید کردند به اشارت مشیران\r\n"},{"id":2107,"category_id":2,"category_code":"s2","source_id":274,"title":"دزد دستار","content":"ابوبكر رباني اكثر شب ها به دزدي رفتي و چندانكه سعي كرد چيزي نيافت. دستارخود بدزديد و در بغل نهاد. چون در خانه رفت زنش گفت: چه آورد ه اي؟ گفت: اين دستار آورده ام. گفت: اين كه از آن خود توست. گفت: خاموش\r\nتو نداني. از بهر آن دزديد ه ام تا آرمان دزديم باطل نشود.\r\n"},{"id":2108,"category_id":2,"category_code":"s2","source_id":275,"title":"خواجه و غلام بخیل","content":"آورده اند که خواجه ای بود بسیار بخیل و غلامی داشت که به هزار درجه از خواجه بخیل تر بود. روزی خواجه گفت : ای غلام ، نان را بیاور و در را ببند. غلام گفت : ای خواجه ، خطا گفتی. می بایست گفت : در را ببند و نان را بیاور که آن به حزم نزدیک تر است. پس خواجه را این سخن خوش آمد و او را آزاد کرد."},{"id":2109,"category_id":2,"category_code":"s2","source_id":276,"title":"گفت و گوی مرد بخیل با درم و دینار","content":"بخیلی بود که هرگاه درمی به دست می آورد ، آن را در کیسه ای می نهاد و می گفت : ای درم تو بسیار مردم دیده ای و بسیار ناکسان را بزرگ و با قدر کرده ای و بسیار بزرگان را به زمین فرو برده ای ، اکنون به جایی افتاده ای که آفتاب بر تو سایه نتوان انداخت. بیارام و قرار بگیر که تو را از اینجا تحویل نخواهد بود ، مگر به وقت مرگ."},{"id":2110,"category_id":2,"category_code":"s2","source_id":277,"title":"مرد کوفی و کودکان","content":"یکی از بزرگان حکایت می کرد که شبی به خانه مردی خسیس از اهالی کوفه وارد شد. آن مرد کودکانی خردسال داشت. چون ایشان بخفتند و پاسی از شب بگذشت ، آن مرد برمی خواست و هر ساعت کودکان خود را پهلو به پهلو می گرداند. چون صبح شد ، مهمان از او پرسید: دیشب دیدم که تو اطفال خود را پهلو به پهلو می گردانیدی ، چه حکمتی در این کار بود؟\r\nمرد گفت : کودکان من در آغاز شب طعام خورده و خوابیده بودند و چون بر پهلوی چپ خفته بودند ، ترسیدم اگر همچنان تا صبح بخوابند ، آنچه خورده باشند زود هضم شود و صبح زود گرسنه شوند. خواستم که آن غذا در معده ایشان باشد تا صبح زود با خواهش غذا مرا آزار ندهند.\r\n"},{"id":2111,"category_id":2,"category_code":"s2","source_id":278,"title":"شتر دیدی ندیدی","content":"مردی در صحرا دنبال شترش می گشت تا اینکه به پسر باهوشی برخورد کرد و سراغ شتر را از او گرفت\r\nپسر گفت : شتر یک چشمش کور بود؟ مرد گفت: بله\r\nپسر گفت : آیا یک طرف بارش شیرینی و طرف دیگرش ترشی بود؟\r\nمرد گفت : بله بگو ببینم شتر کجاست؟\r\nپسر گفت : من شتری ندیدم!!!\r\nمرد ناراحت شد ، و فکر کرد که شاید پسرک بلایی سر شتر آورده است پسر را نزد قاضی برد و ماجرا را برای او تعریف کرد.\r\nقاضی از پسر پرسید: اگر تو شتر را ندیدی چطور همه مشخصاتش را می دانستی؟\r\nپسر گفت :روی خاک ردپای شتری را دیدم که فقط سبزه های یک طرف را خورده بود ، فهمیدم که شاید یک چشمش کور بوده ، بعد متوجه شدم که در یک طرف راه مگس و در طرف دیگر پشه بیشتر است چون مگس شیرینی دوست دارد و پشه ترشی نتیجه گرفتم که شاید یک لنگه بار شتر شیرینی و یک لنگه دیگر ترشی بوده است.\r\nقاضی گفت : درست است که تو بی گناهی ، ولی زبانت باعث دردسرت شد پس از این به بعد شتر دیدی ندیدی!!\r\nبله دوستان این یک مثل قدیمی است که همه ما شنیده ایم و هنگامی کاربرد دارد که پرحرفی باعث دردسر می شود. آسودگی در کم گفتن است ، و چکار داریم که در کار دیگران دخالت کنیم.\r\n"},{"id":2112,"category_id":2,"category_code":"s2","source_id":279,"title":"چانه زدن","content":"از بزرگی دیگر روایت کنند که در معامله ای که با دیگری داشت، برای مبلغی کم، چانه زنی از حد گذرانید. او را منع کردند که این مقدار ناچیز بدین چانه زنی نمی ارزد.\r\nگفت : چرا من مقداری از مال خود ترک کنم که مرا یک روز و یک هفته و یک ماه و یک سال و همه عمر بس باشد؟ گفتند چگونه؟\r\nگفت : اگر به نمک دهم ، یک روز بس باشد، اگر به حمام روم ، یک هفته ، اگر به حجامت دهم، یک ماه، اگر به جاروب دهم ، یک سال، اگر به میخی دهم و در دیوار زنم، همه عمر بس باشد. پس نعمتی که چندین مصلحت من بدان منوط باشد، چرا بگذارم با کوتاهی از دست من برود؟!\r\n"},{"id":2113,"category_id":2,"category_code":"s2","source_id":280,"title":"بهانه","content":"در زمان مبارک حضرت رسول، کفار را می گفتند که درویشان را طعام دهید. ایشان می گفتند که درویشان بندگان خدایند، اگر خدا خواستی ، ایشان را طعام دادی. چون او نمی دهد، ما چرا بدهیم؟ چنان که در قرآن مجید آمده است « انطعم من لو یشاء الله اطعمه ان انتم الا فی ضلال مبین»\r\nپس واجب باشد که بر هیچ آفریده رحمت نکنند و به حال هیچ مظلومی و مجرمی و محتاجی و مبتلایی و گرفتاری و مجروحی و یتیمی و عیال واری و درویشی و خدمتکاری که بر در خانه، پیر یا زمین گیر شده باشد، التفات ننمایند، بلکه برای رضای خداوند آن قدر که توانند، اذیتی بدیشان رسانند تا موجب دفع درجات و خیرات باشد، و در قیامت در « یوم لا ینفع مال و لابنون» ( روزی که نه مال دنیا به کار آید و نه فرزندان ) ، دست او را بگیرد.\r\n"},{"id":2114,"category_id":2,"category_code":"s2","source_id":281,"title":"نصیحت کلاغ به فرزند خود","content":"گویند کلاغی به جوجه ی خود گفت : چون یکی از آدمیان خم شود ؛ بی درنگ پرواز کن؛ چون می خواهد از زمین سنگ بردارد و به طرف تو پرتاب کند.\r\nجوجه گفت : با دیدن آدمی باید فرار کرد ؛ چون می تواند از پیش سنگ را در آستین خود پنهان کند.\r\n"},{"id":2115,"category_id":2,"category_code":"s2","source_id":282,"title":"دعا برای ظالم","content":"\r\nدرویشی مستجاب الدعوة به بغداد آمد. \r\nخبر به گوش حجاج بن یوسف رسید. \r\nحجاج درویش را خواست و به او گفت:دعایی خیر در حق من بکن. \r\nدرویش گفت:خدایا جانش را بستان. \r\nحجاج گفت:چرا این دعا خیر است. \r\nگفت:این دعا برای تو و همه‌ی مسلمانان خیر است.\r\n"},{"id":2116,"category_id":2,"category_code":"s2","source_id":283,"title":"شیری که عاشق آهو شد","content":"شیر نری دلباخته ‏ی آهوی ماده شد . \r\nشیر نگران معشوق بود و می‏ ترسید بوسیله ‏ی حیوانات دیگر دریده شود . \r\nاز دور مواظبش بود ...\r\nپس چشم از آهو برنداشت تا یک بار که از دور او را می نگریست ، شیری را دید که به آهو حمله کرد . فوری از جا پرید و جلو آمد .\r\nدید ماده شیری است . چقدر زیبا بود ، گردنی مانند مخمل سرخ و بدنی زیبا و طناز داشت .\r\nبا خود گفت : حتما گرسنه است . همان جا ایستاد و مجذوب زیبایی ماده شیر شد . \r\nو هرگز ندید و هرگز نفهمید که آهو خورده شد ...\r\n"},{"id":2117,"category_id":2,"category_code":"s2","source_id":284,"title":"آزمون تنباکو","content":"نقل است شاه عباس صفوي، رجال كشور را به ضيافت شاهانه ميهمان كرد و به خدمتكاران دستور داد تا در سر قليان ها بجاي تنباكو، از سرگين اسب استفاده كنند. ميهمان ها مشغول كشيدن قليان شدند و دود و بوي پهنِ اسب، فضا را پر كرد اما رجال از بيم ناراحتي‌ شاه پشت سر هم بر ني قليان پُك عميق زده و با احساس رضايت دودش را هوا مي دادند! گويي در عمرشان، تنباكويي به آن خوبي‌ نكشيده اند!\r\nشاه رو به آنها كرده و گفت: «سرقليان ها با بهترين تنباكو پر شده اند. آن را حاكم همدان برايمان فرستاده است.»\r\nهمه از تنباكو و عطر آن تعريف كرده و گفتند: «براستي تنباكويي بهتر از اين نمي‌توان يافت.»\r\n\r\nشاه به رئيس نگهبانان دربار، كه پك هاي بسيار عميقي به قليان مي زد، گفت: « تنباكويش چطور است؟»\r\nرئيس نگهبانان گفت: «به سر اعليحضرت قسم، پنجاه سال است كه قليان مي كشم، اما تنباكويي به اين عطر و مزه نديده ام!»\r\nشاه با تحقير به آنها نگاهي‌ كرد و گفت: «مرده شوي تان ببرد كه بخاطر حفظ پست و مقام، حاضريد بجاي تنباكو، پِهِن اسب بكشيد و بَه‌‌‌ بَه‌‌‌‌‌‌ و چَه چَه كنيد.»\r\n"},{"id":2118,"category_id":2,"category_code":"s2","source_id":285,"title":"نماز قضا","content":"زاهدی مهمان پادشاه شد، چون به طعام بنشستند کمتر از آن خورد که ارادت او بود و چون به نماز برخاستند بيش از آن کرد که عادت او تا ظن صلاحيت در حق او زيادت کنند.\r\nچون به مقام خويش آمد سفره خواست تا تناولی کند. پسری صاحب فراست داشت گفت : ای پدر باری به مجلس سلطان در طعام نخوردی؟ گفت : در نظر ايشان چيزی نخوردم که بکار آيد . گفت : نماز را هم قضا کن که چيزی نکردی که بکار آيد.\r\n"},{"id":2119,"category_id":2,"category_code":"s2","source_id":286,"title":"جوان گنهکار","content":"در زمان «مالك دينار» جوانى از زمره اهل معصيت و طغيان از دنيا رفت.\r\nمردم به خاطر آلودگى او جنازه‏اش را تجهيز نكردند، بلكه در مكان پستى و\r\nمحلّ پر از زباله‏اى انداختند و رفتند.\r\nشبانه در عالم رؤيا از جانب حق تعالى به مالك دينار گفتند: بدن بنده ما را بردار\r\nو پس از غسل و كفن در گورستان صالحان و پاكان دفن كن. عرضه داشت: او از\r\nگروه فاسقان و بدكاران است، چگونه و با چه وسيله مقرّب درگاه احديّت شد؟\r\nجواب آمد: در وقت جان دادن با چشم گريان گفت:\r\n\r\nيا مَنْ لَهُ الدُّنيا وَ الآخِرَةُ إرْحَمْ مَن لَيْسَ لَهُ الدُّنيا وَ الآخرَةُ.\r\nاى كه دنيا و آخرت از اوست، رحم كن به كسى كه نه دنيا دارد نه آخرت.\r\nمالك،كدام دردمند به درگاه ما آمد كه دردش را درمان نكرديم؟ و\r\nكدام حاجتمند به پيشگاه ما ناليد كه حاجتش را برنياورديم؟» .\r\n"},{"id":2120,"category_id":2,"category_code":"s2","source_id":287,"title":"مرغابی هستید یا عقاب؟","content":"وقتي شما به شهر نيويورك سفر كنيد، جالب ترين بخش سفر شما هنگامي است كه پس از خروج از هواپيما و فرودگاه، قصد گرفتن يك تاكسي را داشته باشيد. اگر يك تاكسي براي ورود به شهر و رسيدن به مقصد بيابيد شانس به شما روي آورده است. اگر راننده ي تاكسي شهر را بشناسد و از نشاني شما سر در آورد با اقبال ديگري روبرو شده ايد. اگر زبان راننده را بدانيد و بتوانيد با او سخن بگوييد بخت يارتان است و اگر راننده عصباني نباشد، با حسن اتفاق ديگري مواجه هستيد. خلاصه براي رسيدن به مقصد بايد از موانع متعددي بگذريد.\r\nهاروي مك كي مي گويد: «روزي پس از خروج از هواپيما، در محوطه اي به انتظار تاكسي ايستاده بودم كه ناگهان راننده اي با پيراهن سفيد و تميز و پاپيون سياه از اتومبيلش بيرون پريد، خود را به من رساند و پس از سلام و معرفي خود گفت: «لطفا چمدان خود را در صندوق عقب بگذاريد.»\r\nسپس كارت كوچكي را به من داد و گفت: «لطفا به عبارتي كه رسالت مرا تعريف مي كند توجه كنيد.»\r\nبر روي كارت نوشته شده بود: «در كوتاه ترين مدت، با كمترين هزينه، مطمئن ترين راه ممكن و در محيطي دوستانه شما را به مقصد مي رسانم.»\r\nمن چنان شگفت زده شدم كه گفتم نكند هواپيما به جاي نيويورك در كره اي ديگر فرود آمده است. راننده در را گشود و من سوار اتومبيل بسيار آراسته اي شدم. پس از آنكه راننده پشت فرمان قرار گرفت، رو به من كرد و گفت: «پيش از حركت، قهوه ميل داريد؟ در اينجا يك فلاسك قهوه معمولي و فلاسك ديگري از قهوه مخصوص براي كسانيكه رژيم تغذيه دارند، هست.»\r\nگفتم: «خير، قهوه ميل ندارم، اما با نوشابه موافقم».\r\nراننده پرسيد: «در يخدان هم نوشابه دارم و هم آب ميوه.»\r\nسپس با دادن يك بطري نوشابه، حركت كرد و گفت: «اگر ميل به مطالعه داريد مجلات تايم، ورزش و تصوير و آمريكاي امروز در اختيار شما است.»\r\nآنگاه، بار ديگر كارت كوچك ديگري در اختيارم گذاشت و گفت: «اين فهرست ايستگاههاي راديويي است كه مي توانيد از آنها استفاده كنيد. ضمنا من مي توانم درباره بناهاي ديدني و تاريخي و اخبار محلي شهر نيويورك اطلاعاتي به شما بدهم و اگر تمايلي نداشته باشيد مي توانم سكوت كنم. در هر صورت من در خدمت شما هستم.»\r\nاز او پرسيدم: «چند سال است كه به اين شيوه كار مي كنيد؟»\r\nپاسخ داد: « دو سال.»\r\nپرسيدم: «چند سال است كه به اين كار مشغوليد؟»\r\nجواب داد: «هفت سال.»\r\nپرسيدم: «پنج سال اول را چگونه كار مي كردي؟»\r\nگفت: «از همه چيز و همه كس،از اتوبوسها و تاكسي هاي زيادي كه هميشه راه را بند مي آورند، و از دستمزدي كه نويد زندگي بهتري را به همراه نداشت مي ناليدم. روزي در اتومبيلم نشسته بودم و به راديو گوش مي دادم كه وين داير شروع به سخنراني كرد. مضمون حرفش اين بود كه مانند مرغابيها كه مدام واك واك مي كنند، غرغر نكنيد، به خود آييد و چون عقابها اوج گيريد. پس از شنيدن آن گفتار راديويي، به پيرامون خود نگريستم و صحنه هايي را ديدم كه تا آن زمان گويي چشمانم را بر آنها بسته بودم. تاكسيهاي كثيفي كه رانندگانش مدام غرولند مي كردند، هيچگاه شاد و سرخوش نبودند و با مسافرانشان برخورد مناسبي نداشتند. سخنان وين داير، بر من چنان تاثيري گذاشت كه تصميم گرفتم تجديد نظري كلي در ديدگاهها و باورهايم به وجود آورم.»\r\nپرسيدم: « چه تفاوتي در زندگي تو حاصل شد؟»\r\nگفت: «سال اول، درآمدم دوبرابر شد و سال گذشته به چهار برابر رسيد. نكته اي كه مرا به تعجب واداشت اين بود كه در يكي دو سال گذشته، اين داستان را حداقل با سي راننده تاكسي در ميان گذاشتم اما فقط دو نفر از آنها به شنيدن آن رغبت نشان دادند و از آن استقبال كردند. بقيه چون مرغابيها، به انواع و اقسام عذر و بهانه ها متوسل شدند و به نحوي خود را متقاعد كردند كه چنين شيوه اي را نمي توانند برگزينند.»\r\n"},{"id":2121,"category_id":2,"category_code":"s2","source_id":288,"title":"مرد لاف زن","content":"یک مرد لاف زن, پوست دنبه‌ای چرب در خانه داشت و هر روز لب و سبیل خود را چرب می‌کرد و به مجلس ثروتمندان می‌رفت و چنین وانمود می‌کرد که غذای چرب خورده است. دست به سبیل خود می‌کشید. تا به حاضران بفهماند که این هم دلیل راستی گفتار من. امّا ...\r\nشکمش از گرسنگی ناله می‌کرد که‌ ای درغگو, خدا , حیله و مکر تو را آشکار کند! این لاف و دروغ تو ما را آتش می‌زند. الهی, آن سبیل چرب تو کنده شود, اگر تو این همه لافِ دروغ نمی‌زدی, لااقل یک نفر رحم می‌کرد و چیزی به ما می‌داد. ای مرد ابله لاف و خودنمایی روزی و نعمت را از آدم دور می‌کند. شکم مرد, دشمن سبیل او شده بود و یکسره دعا می‌کرد که خدایا این درغگو را رسوا کن تا بخشندگان بر ما رحم کنند, و چیزی به این شکم و روده برسد.\r\nعاقبت دعای شکم مستجاب شد و روزی گربه‌ای آمد و آن دنبة چرب را ربود. اهل خانه دنبال گربه دویدند ولی گربه دنبه را برد. پسر آن مرد از ترس اینکه پدر او را تنبیه کند رنگش پرید و به مجلس دوید, و با صدای بلند گفت پدر! پدر! گربه دنبه را برد. آن دنبه‌ای که هر روز صبح لب و سبیلت را با آن چرب می‌کردی. من نتوانستم آن را از گربه بگیرم. حاضران مجلس خندیدند, آنگاه بر آن مرد دلسوزی کردند و غذایش دادند. مرد دید که راستگویی سودمندتر است از لاف و دروغ.\r\n"},{"id":2122,"category_id":2,"category_code":"s2","source_id":289,"title":"معمار و پیر زن","content":"ميگويند چند صد سال پيش، در اصفهان مسجدي مي ساختند. روز قبل از افتتاح مسجد، كارگرها و معماران جمع شده بودند و آخرين خرده كاري ها را انجام مي دادند.\r\nپيرزني از آنجا رد مي شد وقتي مسجد را ديد به يكي از كارگران گفت: «فكر كنم يكي از مناره ها كمي كجه!»\r\nكارگرها خنديدند. اما معمار كه اين حرف را شنيد، سريع گفت: «چوب بياوريد! كارگر بياوريد! چوب را به مناره تكيه بدهيد. فشار بدهيد.»\r\nدر حالي كه كارگران با چوب به مناره فشار مي آوردند، معمار مدام از پيرزن مي پرسيد: «مادر، درست شد؟!»\r\nمدتي طول كشيد تا پيرزن گفت: «بله! درست شد! تشكر كرد و دعايي كرد و رفت.»\r\nكارگرها حكمت اين كار بيهوده و فشار دادن به مناره اي كه اصلاً كج نبود را پرسيدند. معمار گفت: «اگر اين پيرزن، راجع به كج بودن اين مناره با ديگران صحبت مي كرد و شايعه پا مي گرفت، اين مناره تا ابد كج مي ماند و ديگر نمي توانستيم اثرات منفي اين شايعه را پاك كنيم. اين است كه من گفتم در همين ابتدا جلوي آن را بگيرم!»\r\n"},{"id":2123,"category_id":2,"category_code":"s2","source_id":290,"title":"زبان تبر","content":"هيزم شكن تنومند اما بدخلقي در نزديكي دهكده شيوانا زندگي مي كرد. هيزم شكن بسيار قوي بود و مي توانست در كمتر از يك هفته يكصد تنه تراشيده درخت قطور را تهيه و تحويل دهد اما چون زبان تلخ و تندي داشت با اهالي شهرهاي دور قرار داد مي بست و براي مردم دهكده خودش كاري نمي كرد.\r\nبراي ساختن پلي روي رودخانه نياز به تعداد زيادي تنه درخت و الوار بود و چون فصل باران و سيلاب هم نزديك بود، اهالي دهكده مجبور بودند به سرعت كار كنند و در كمتر از دو هفته پل را بسازند. به همين خاطر لازم بود كسي نزد هيزم شكن برود و از او بخواهد كه كارهاي جاري خودش را متوقف كند و براي پل دهكده تنه درخت آماده كند.\r\nچند نفر از اهالي نزد او رفتند اما جواب منفي گرفتند. براي همين اهالي دهكده، نزد شيوانا آمدند و از او خواستند به شكلي با مرد هيزم شكن سرصحبت را باز كند و او را راضي كند تا براي پل دهكده تنه درخت آماده كند.\r\nشيوانا صبح روز بعد اول وقت لباس كارگري پوشيد. تبري تيز را روي شانه گذاشت و به سمت كلبه هيزم شكن رفت. مردم از دور نگاه مي كردند و مي ديدند كه شيوانا همپاي هيزم شكن تا ظهر تبر زد و درخت اره كرد و سرانجام موقع ناهار با او سر گفتگو را باز كرد و در خصوص نياز اهالي به پل و باران شديدي كه در راه است براي او صحبت كرد. بعد از صرف ناهار هيزم شكن با شادي و خوشحالي درخواست شيوانا را پذيرفت و گفت از همين بعد از ظهر كار را شروع مي كند. شيوانا هم كنار او ايستاد و تا غروب درخت قطع كرد.\r\nشب كه شيوانا به مدرسه برگشت اهالي دهكده را ديد كه با حيرت به او نگاه مي كنند و دليل موافقيت هيزم شكن يكدنده و لجباز را از او مي پرسند. شيوانا با لبخند اشاره اي به تبر كرد و گفت: «اين هيزم شكن قلبي به صافي آسمان دارد. منتهي مشكلي كه دارد اين است كه فقط زبان تبر را مي فهمد. بنابراين اگر مي خواهيد از اين به بعد با هيزم شكن هم كلام شويد چند ساعتي با او تبر بزنيد. در واقع هر كسي زبان ابزار شغل خودش را بهتر از بقيه مي فهمد و شما هر وقت خواستيد با كسي دوست شويد و رابطه صميمانه برقرار كنيد بايد از طريق زبان ابزار شغل و مهارت او با او هم كلام شويد.»\r\n"},{"id":2124,"category_id":2,"category_code":"s2","source_id":291,"title":"سختی روزگار","content":"مردی از دست روزگار سخت می‌نالید. پیش استادی رفت و برای رفع غم و رنج خود راهی خواست. استاد لیوان آب نمکی را به خورد او داد و از مزه‌اش پرسید؟ \r\nآن مرد آب را به بیرون از دهان ریخت و گفت: خیلی شور و غیرقابل تحمل است.\r\nاستاد وی را کنار دریا برده و به وی گفت: همان مقدار آب بنوشد و بعد از مزه‌اش پرسید؟\r\nمرد گفت: خوب است و می‌توان تحمل کرد.\r\nاستاد گفت شوری آب همان سختی‌های زندگی است. شوری این دو آب یکی ولی ظرفشان متفاوت بود. سختی و رنج دنیا همیشه ثابت است و این ظرفیت ماست که مزه آن را تعیین می‌کند پس وقتی در رنج هستی بهترین کار بالا بردن ظرفیت و درک خود از مسائل است.\r\n"},{"id":2125,"category_id":2,"category_code":"s2","source_id":292,"title":"پرواز شاهین","content":"پادشاهي دو شاهين كوچك به عنوان هديه دريافت كرد. آنها را به مربي پرندگان دربار سپرد تا براي استفاده در مراسم شكار تربيت كند. يك ماه بعد، مربي نزد پادشاه آمد و گفت كه يكي از شاهين‌ها تربيت شده و آماده شكار است اما نمي‌داند چه اتفاقي براي آن يكي افتاده و از همان روز اول كه آن را روي شاخه‌اي قرار داده تكان نخورده است.\r\nاين موضوع كنجكاوي پادشاه را برانگيخت و دستور داد تا پزشكان و مشاوران دربار، كاري كنند كه شاهين پرواز كند. اما هيچكدام نتوانستند. روز بعد پادشاه دستور داد تا به همه مردم اعلام كنند كه هر كس بتواند شاهين را به پرواز درآورد پاداش خوبي از پادشاه دريافت خواهد كرد. صبح روز بعد پادشاه ديد كه شاهين دوم نيز با چالاكي تمام در باغ در حال پرواز است. پادشاه دستور داد تا معجزه‌گر شاهين را نزد او بياورند.\r\nدرباريان كشاورزي متواضع را نزد شاه آوردند و گفتند اوست كه شاهين را به پرواز درآورد. پادشاه پرسيد: «تو شاهين را به پرواز درآوردي؟ چگونه اين كار را كردي؟ شايد جادوگر هستي؟»\r\nكشاورز كه ترسيده بود گفت: «سرورم، كار ساده‌اي بود، من فقط شاخه‌اي را كه شاهين روي آن نشسته بود بريدم. شاهين فهميد كه بال دارد و شروع به پرواز كرد.»\r\n"},{"id":2126,"category_id":2,"category_code":"s2","source_id":293,"title":"دوستی خاله خرسه","content":"مردی دلیر و شجاع در راهی می گذشت، دید که اژدهایی خرسی را می بلعد. آن دلیرمرد هم که فریاد خرس مظلوم را بشنید برای رحمت و لطف بدان سو شتافت، ‌خود را به زحمت افکند تا مِهری نماید و دردمند و درمانده ای را نجات دهد.\r\nا‍ژدهایی خرس را درمی کشید// شیر مردی رفت و فریادش رسید\r\nشیر مردانند در عالم مدد// آن زمان کافغان مظلومان رسد\r\nهرکجا دردی،‌ دوا آنجا رود// هرکجا پستی است، ‌آب آنجا رود\r\nآب رحمت بایدت رو پست شو// وانگهان خور خمر رحمت، مست شو \r\nخلاصه با دلاوری تمام با وجود همه ی خطرات، پا پیش نهاد و خرس را از دهان اژدها نجات داد. خرس وقتی این جوامردی را از وی دید به او انس گرفت و در پی او روان شد. مرد خسته شد و خوابید. خرس کشیک می داد و از او مواظبت می کرد تا اینکه مردی دانا و خیرخواه این وضع را دید، پیش رفت و آن مرد را بیدار کرد و گفت : «ای برادر مر تو را این خرس کیست ؟»\r\nمرد داستان خرس و اژدها را باز گفت. مرد گفت :‌ «بر خرسی منه دل ابل ها.»\r\nدوستی ابله بتر از دشمنی است// او به هر حیله که دانی راندنی است \r\nمرد که غفلت چشم و دلش را بسته بود (شجاعت داشت ولی حکمت نداشت) :\r\nگفت: ‌والله از حسودی گفت این// ورنه خرسی چه نگری این مهربین \r\nآن مرد پاسخ داد : « فرض کن به تو حسادت می کنم ولی حسادت دانا بهتر از دوستی نادان است.»\r\nشیر مرد : «برو دنبال کارت !»\r\nمرد دانا گفت :‌«کار من همین بوده است، تو دست از خرس بردار تا من یار تو باشم من دلم به حال تو می سوزد، در دلم نور حق تابیده و به من فهمانده که تو را از دوستی با خرس بازدارم،‌ می دانی که مومن به نور خدا می نگرد.»\r\nهرچه آن مرد دانا گفت در گوش آن شیرمرد فرو نرفت.\r\nاین همه گفت و به گوشش در نرفت// بدگمانی مرد را سدّی است زَفت \r\nشیرمرد چون به آن مرد بدگمان بود که حسودیش می شود، پند او را هم نشنید ، درحالی که به قول سعدی :\r\nمرد باید که گیرد اندر گوش// ور نوشته است پند بر دیوار\r\nحتی دستش را گرفت که با خود ببرد ولی شیرمرد مغرور دستش را رها کرد و گفت : «بیشتر از این در کار من فضولی نکن !»\r\nدانامرد گفت : «من دشمن تو نیستم، دنبالم بیا.»\r\nشیرمرد پاسخ داد : «خوابم می آید.»\r\nدانا مرد گفت : «خوب است در کنار خردمند صاحبدل بخسبی، نه در کنار ابلهی که از جنس تو نیست.»\r\nشیرمرد با خود گفت : «این مرد یا قصد خون ریختن من دارد یا می خواهد مال مرا از دستم درآورد. یا با دوستانش شرط بسته که مرا از این دوست خوب (خرس) محروم کند. بیچاره بر خود خوش بین بود و بر آن مرد دانا بدبین.\r\nآن مسلمان ترک ابله کرد و رفت// زیر لب لاحول گویان باز رفت\r\nشخص خفت و خرس می راندش مگس// وز ستیز آمد مگس زو باز پس\r\nهرچه خرس مگس را می پراند که بر مرد خفته ننشیند سودی نداشت. رفت و سنگ بسیار بزرگی برداشت و بر مگس ها زد که بگریزند. غافل از اینکه مگسهای روی صورت مرد نشسته بودند.\r\n"},{"id":2127,"category_id":2,"category_code":"s2","source_id":294,"title":"لکه ی سیاه","content":"از كوفي عنان (دبير كل سابق سازمان ملل و برنده صلح نوبل) پرسيدند: بهترين خاطره ي شما از دوران تحصيل چه بود؟\r\nاو جواب داد: «روزي معلم علوم ما وارد كلاس شد و برگه ي سفيد رنگي را به تخته سياه چسباند. در وسط آن لكه‌اي با جوهر سياه نمايان بود.»\r\nمعلم از شاگردان پرسيد: «بچه ها در اين برگه چه مي بينيد؟»\r\nهمه جواب دادند: «يك لكه سياه آقا.»\r\nمعلم با چهره اي انديشمندانه لحظاتي در مقابل تخته كلاس راه رفت و سپس با دست خود به اطراف لكه سياه اشاره كرد و گفت: «بچه هاي عزيز چرا اين همه سفيدي اطراف لكه سياه را نديديد؟»\r\nكوفي عنان مي گويد: «از آن روز تلاش كردم اول سفيدي (خوبي‌ها، نكات مثبت، روشنايي ها و…) را بنگرم.»\r\n"},{"id":2128,"category_id":2,"category_code":"s2","source_id":295,"title":"راه رفتن روی آب","content":"شكارچي پرنده سگ جديدي خريده بود، سگي كه ويژگي منحصر به فردي داشت. اين سگ ميتوانست روي آب راه برود. شكارچي وقتي اين را ديد نمي توانست باور كند و خيلي مشتاق بود كه اين را به دوستانش بگويد. براي همين يكي از دوستانش را به شكار مرغابي در بركه اي آن اطراف دعوت كرد.\r\nاو و دوستش شكار را شروع كردند و چند مرغابي شكار كردند. بعد به سگش دستور داد كه مرغابي هاي شكار شده را جمع كند. در تمام مدت چند ساعت شكار، سگ روي آب مي دويد و مرغابي ها را جمع مي كرد. صاحب سگ انتظار داشت دوستش درباره اين سگ شگفت انگيز نظري بدهد يا اظهار تعجب كند، اما دوستش چيزي نگفت.\r\nدر راه برگشت، او از دوستش پرسيد آيا متوجه چيز عجيبي در مورد سگش شده است؟\r\nدوستش پاسخ داد: «آره، در واقع، متوجه چيز غيرمعمولي شدم. سگ تو نمي تواند شنا كند.»\r\nشرح حكايت\r\nبعضي از افراد هميشه به ابعاد و نكات منفي توجه دارند. روي وجوه منفي تيم هاي كاري متمركز نشويد. با توجه به جنبه هاي مثبت و نقاط قوت، در كاركنان و تيم هاي كاري ايجاد انگيزه كنيد.\r\n"},{"id":2129,"category_id":2,"category_code":"s2","source_id":296,"title":"جالیوس و دیوانه","content":"جالینوس روزی از راهی می گذشت، دیوانه ای او را دید مدتی به رخسارش نگریست و سپس به او چشمک زد و آستینش را کشید. جالینوس وقتی به پیش یاران و شاگردان خود آمد گفت : «یکی از شما داروی بهبود دیوانگی به من دهد.» یکی از آنان گفت : «ای دانای هنرمند داروی دیوانگی به چه کارت آیدت ؟»\r\n\r\nجالینوس پاسخ داد : «امروز آمده دیوانه ای به رخسارم نگریست و خندید و آستینم را کشید. او از من خوشش آمده بود.»\r\nشاگرد گفت : «این چه ربطی به دیوانگی تو دارد ؟»\r\nجالینوس گفت :\r\nگر ندیدی جنس خود کی آمدی// کی به غیر جنس، خود را بر زدی\r\nچون دوکس باهم زید بی هیچ شک// در میانشان هست قدر مشترک\r\n"},{"id":2130,"category_id":2,"category_code":"s2","source_id":297,"title":"راز دل به زن نگو","content":"\r\nپدری به پسرش وصیت کرد که در عمرت این سه کار را نکن :\r\nراز دل به زن مگو ، با نو کیسه معامله نکن و با آدم کم عقل رفیق نشو .\r\nبعد از این که پدر ازدنیا رفت پسر خواست بداند که چرا پدرش به\r\nاو چنین وصیتی کرده؟ پیش خودش گفت : امتحان کنم\r\nببینم پدرم درست گفته یا نه.\r\nهم زن گرفت، هم قرض کردو هم با آدم کم عقل دوست شد.\r\nروزی زن جوان از خانه بیرون رفت. مرد فوری رفت گوسفندی آورد و در خانه کشت و خون گوسفند را دور خانه ریخت و لاشه اش را زیرزمین پنهان کرد. زن وارد خانه شد و به شوهرش گفت : چه شده؟ خون ها مال چیست؟\r\nمرد گفت : آهسته حرف بزن. من یک نفر را کشته ام. او دشمن من بود.\r\nاگر حرفی زدی تو را هم می کشم. چون غیر از من و تو کسی از این راز خبرندارد. اگر کسی بفهمد معلوم می شود تو گفته ای.\r\nزن،تا اسم کشته شدن را شنید، فوری به پشت بام رفت و صدا زد : مردم به فریادم برسید.\r\nشوهرم یک نفر را کشته، حالا می خواهد مرا هم بکشد. مردم ده به خانه آنها آمدند. کدخدای ده که کم عقل بود و دوست صمیمی آن مرد بود فوری مرد را گرفت تا به محکمه قاضی ببرد. در راه که می رفتند به آدم نوکیسه(تازه به دوران رسیده) برخوردند.\r\nمرد نوکیسه که از ماجرا خبر شده بود دوید و گریبان مرد را گرفت و گفت : پولی را که به تو قرض داده ام پس بده. چون ممکن است توکشته بشوی و پول من از بین برود.\r\nبه این ترتیب، مرد، حکمت این ضرب المثل را دانست. سپس لاشه گوسفند را نشان داد و اصل ماجرا را به قاضی گفت و آزاد شد.\r\n"},{"id":2131,"category_id":2,"category_code":"s2","source_id":298,"title":"حق الوکاله","content":"خانمی وارد دفتر یک وکیل دادگستری شد و پرسید: آقای وکیل جریمه بچه ای که با سنگ، شیشه پنجاه ریالی را شکسته چقدر است؟\r\nوکیل لحظه ای فکر کرد و گفت: پنجاه ریال از پدرش مطالبه کنید.\r\nخانم گفت: بسیار خوب پس خواهش می کنم پنجاه ریال مرحمت کنید زیرا این هنر پسر شما است که شیشه ما را شکسته است.\r\nوکیل بلافاصله گفت: خانم ببخشید، شما باید پنجاه ریال لطف کنید زیرا حق مشاوره قضایی من در هر نوبت صد ریال است.\r\n"},{"id":2132,"category_id":2,"category_code":"s2","source_id":299,"title":"غرور","content":"در دوران گذشته دو برادر یکی به نام «ضیاء» و دیگری به نام «تاج» در شهر بلخ زندگی می کردند. ضیاء مردی بلندبالا، بذله گو، نکته سنج و خوش اخلاق بود. اما برادرش «تاج» قدی بسیار کوتاه داشت، با این حال از علم بالایی بهره می برد، به همین سبب به برادرش به دیده حقارت می نگریست. حتی از وجود او خجالت می کشید.\r\nروزی ضیاء به مجلس برادرش تاج که با حضور شخصیت های بزرگ برپا شده بود وارد شد، ولی غرور علمی تاج مانع از آن شد که به احترام برادرش بایستد. از این رو نیم خیز شد و به سرعت نشست.\r\nوقتی ضیاء از برادرش آن حرکت ناپسند را دید، با کنایه ای که حکایت از نکته سنجی او داشت، فی البداهه به مزاح گفت: «چون خیلی بلند قامتی، برای ثواب، کمی هم از آن قامت سروت بدزد.\r\n"},{"id":2133,"category_id":2,"category_code":"s2","source_id":300,"title":"سه پله بالاتر","content":"ابن جوزی یکی از خطبای معروف بود. روزی بالای منبر که ۳ پله داشت برای مردم صحبت می کرد زنی از پایین منبر بلند شد و مسئله ای پرسید.ابن جوزی گفت: نمی دانم.\r\nزن گفت: تو که نمی دانی پس چرا ۳ پله از دیگران بالاتر نشسته ای؟ او جواب داد: این سه پله را که من بالاتر نشسته ام به آن اندازه ای است که من می دانم و شما نمی دانید و به اندازه معلوماتم بالا رفته ام. اگر به اندازه مجهولاتم می خواستم بالا روم، لازم بود منبری درست می شد که تا فلک الافلاک بالا می رفت.\r\n"},{"id":2134,"category_id":2,"category_code":"s2","source_id":301,"title":"ظالم رعنا","content":"\r\nاز بایزید پرسیدند: پیر تو که بود؟\r\nگفت: پیرزنی. روزی در صحرا رفتم، پیرزنی با انبانی آرد برسید. مرا گفت: این انبان آرد با من برگیر.\r\nمن چنان بودم که خود نیز نمی توانستم برد. به شیری اشارت کردم. بیامد. انبان بر پشت او نهادم و پیرزن را گفتم: اگر به شهر روی، گویی که را دیدم؟\r\nگفت: ظالمی رعنا را دیدم.\r\nگفتم: هان چه می گویی پیرزن.\r\nگفت: این شیر مکلف است یا نه؟\r\nگفتم: نه.\r\nگفت: تو آن را که مکلف نیست تکلیف کردی، ظالم نباشی؟\r\nگفتم: باشم.\r\nگفت: با این همه می خواهی که اهل شهر بدانند که این شیر فرمان بر داراست و تو صاحب کراماتی.این، نه رعنایی بود؟\r\n"},{"id":2135,"category_id":2,"category_code":"s2","source_id":302,"title":"خواست خدا","content":"يكي از زهاد را بيماري عارض شد. شخصي به عيادت او رفت و او را شادمان ديد و زبانش را به شكر و ثنا متذكر يافت.\r\nگفت: مي خواهي كه خداي تعالي تو را شفا دهد؟\r\nگفت: نه.\r\nگفت: مي خواهي به وضع بيماري بماني؟\r\nگفت: نه.\r\nگفت: پس چه مي خواهي؟\r\nگفت: آن را مي خواهم كه خدا مي خواهد.\r\n"},{"id":2136,"category_id":2,"category_code":"s2","source_id":303,"title":"لقمان و میوه ها","content":"روزگاری، لقمان حکیم در خدمت خواجه ای بود. خواجه، غلام های بسیار داشت. لقمان بسیار دانا همواره مورد توجّه خواجه بود. غلامان دیگر بر او حسد می ورزیدند و همواره پی بهانه ای می گشتند برای بدنام کردن لقمان پیش خواجه.\r\nروزی از روزها، خواجه به لقمان و چند تن از غلامانش دستور داد تا برای چیدن میوه به باغ بروند. غلام ها و لقمان، میوه ها را چیدند و به سوی خانه حرکت کردند. در بین راه غلام ها میوه ها را یک به یک خوردند و تا به خانه برسند، همه میوه ها تمام شد و سبد خالی به خانه رسید. خواجه وقتی درباره میوه ها پرسید، غلام ها که میانه خوشی با لقمان نداشتند.\r\nگفتند: میوه ها را لقمان خورده است.\r\nخواجه از دست لقمان عصبانی شد.\r\nخواجه پرسید: «ای لقمان، چرا میوه ها را خوردی؟ مگر نمی دانستی که من امشب، مهمان دارم؟ اصلاً به من بگو ببینم، چگونه توانستی آن همه میوه را به تنهایی بخوری؟!»\r\nلقمان گفت: من لب به میوه ها نزده ام. این کار، خیانت به خواجه است!»\r\nخواجه گفت: «چگونه می توانی ثابت کنی که تو میوه ها را نخورده ای؟ در حالی که همه غلام ها شهادت می دهند که تو میوه ها را خورده ای!»\r\nلقمان گفت: «ای خواجه، ما را آزمایش کن، تا بفهمی که میوه ها را چه کسی خورده است!»\r\nخواجه برآشفت: «ای لقمان، مرا دست می اندازی؟ چگونه بفهمم که میوه ها را چه کسی خورده است؟ هر کسی که میوه ها را خورده است، میوه ها در شکمش است. برای این کار باید شکم همه شما را پاره کنم تا بفهمم میوه ها در شکم کیست.»\r\nلقمان لبخندی زد و گفت: «کاملاً درست است. میوه ها در شکم کسی است که آن ها را خورده است. اما برای اینکه بفهمید چه کسی میوه ها را خورده است، لازم نیست که شکم همه ما را پاره کنید!\r\nلقمان گفت: دستور بده تا همه آب گرم بخورند و خودت با اسب و ما پیاده به دنبالت بدویم.\r\nخواجه پرسید: «بسیار خوب، اما این کار چه نتیجه ای دارد؟»\r\nلقمان گفت: «نتیجه اش در پایان کار آشکار می گردد!»\r\nخواجه نیز فرمان داد تا آب گرمی آوردند و همه از آن خوردند و خود با اسب در صحرا می رفت و غلامان به دنبال او می دویدند.\r\nپس از ساعتی، لقمان و همه غلام ها به استفراغ افتادند. آب گرمی که خورده بودند، هر چه را که در معده شان بود، بیرون ریخت!\r\nخواجه متوجه شد که همه غلام ها از آن میوه ها خورده اند، جز لقمان. خواجه غلام ها را به خاطر خوردن میوه ها و تهمت ناروا زدن به لقمان، توبیخ کرد و لقمان را مورد لطف قرار داد.\r\nآری، وقتی یک بنده ضعیف مثل لقمان، چنین حکمت هایی دارد، پس آفریننده او که خداوند جهان است، چه حکمت ها دارد. و حکمت ها همه در پیش خداوند است.\r\n"},{"id":2137,"category_id":2,"category_code":"s2","source_id":304,"title":"رفتار خنثی","content":"\r\nبه حكيمي گفتند: چه كسي از عداوت مردم سالم مي ماند؟\r\nجواب داد: آن كسي كه هيچ خير و شري از او ظاهر نشود.\r\nبه جهت آنكه اگر خير از او ظاهر شود اشرار با او دشمني كنند و اگر شر از او ظاهر شد اخيار با او دشمني كنند.\r\n"},{"id":2138,"category_id":2,"category_code":"s2","source_id":305,"title":"بلا و نعمت خاص","content":"از حكيمي پرسيدند: نعمتي كه بر صاحبش رشك نبرند، يا بلائي كه بر گرفتارش دلسوزي نكنند مي شناسي؟\r\nگفت: آري، آن نعمت تواضع است و آن بلا تكبر.\r\n"},{"id":2139,"category_id":2,"category_code":"s2","source_id":306,"title":"عابد و دزد","content":"مردي سجاده عابدي را دزديد. عابد چون ديد، دزد خجالت كشيد و سجاده را واگذاشت و گفت: نمي دانستم كه سجاده از توست. عابد گفت: چگونه نمي دانستي كه سجاده از تو نيست؟!"},{"id":2140,"category_id":2,"category_code":"s2","source_id":307,"title":"مه رویان و بدگویان","content":"يكي از علما را پرسيدند كه يكي با ماه روئي است در خلوت نشسته و درها بسته و رقيبان خفته و نفس طالب و شهوت غالب.\r\nهيچ باشد كه به قوت پرهيزگاري، او به سلامت بماند؟\r\nگفت: اگر از مه رويان به سلامت بماند، از بدگويان نماند!\r\n"},{"id":2141,"category_id":2,"category_code":"s2","source_id":308,"title":"صبر سخت","content":"آمده كه جواني از محبين از شبلي راجع به صبر پرسيد و گفت: كدام صبر شديدتر است؟\r\nشبلي گفت: صبر براي خدا ... جوان گفت: نه.\r\nگفت: صبر همراه با كمك خدا ... گفت: نه\r\nگفت: صبر بر خدا .... گفت: نه\r\nگفت: صبر در راه خدا ... گفت: نه\r\nگفت: صبر با خدا ... گفت: نه.\r\nشبلي گفت: پس واي بر تو! كدام صبر است؟\r\nجوان گفت: صبر از فراق خدا.\r\nپس شبلي آهي كشيد و بيهوش شد و افتاد.\r\n"},{"id":2142,"category_id":2,"category_code":"s2","source_id":309,"title":"پند استاد","content":"استادی با شاگرد خود از میان جنگلی می گذشت. استاد به شاگرد جوان دستور داد نهال نورسته و تازه بار امده ای را از میان زمین برکند.\r\nجوان دست انداخت و براحتی ان رااز ریشه خارج کرد.پس از چندقدمی که گذشتند٬ به درخت بزرگی رسیدند که شاخه های فراوان داشت .استاد گفت:این درخت راهم از جای بر کن.\r\nجوان هرچه کوشید ٬نتوانست.استاد گفت:\r\nبدان که تخم زشتی ها مثل کینه ٬حسدو هرگناه دیگر هنگامی که در دل اثر گذاشت٬ مانند ان نهال نورسته است ٬ که براحتی می توانی ریشه ان رادر خود برکنی٬ولی اگر ان را واگذاری٬بزرگ و محکم شودو همچون ان درخت در اعماق جانت ریشه زند.پس هرگز نمی توانی انرا برکنی و ازخود دور سازی.\r\n"},{"id":2143,"category_id":2,"category_code":"s2","source_id":310,"title":"شکست یک شخص نیست","content":"یکی از مریدان شیوانا مرد تاجری بود که ورشکست شده بود. روزی برای تصمیم گیری در مورد یک موضوع تجاری نیاز به مشاور بود. شیوانا از شاگردان خواست تا آن مرد تاجر را نزد او آورند. یکی از شاگردان به اعتراض گفت: اما او یک تاجر ورشکسته است و نمی توان به مشورتش اعتماد کرد.\r\nشیوانا پاسخ داد: شکست، یک اتفاق است، یک شخص نیست! کسی که شکست خورده در مقایسه با کسی که چنین تجربه ای نداشته است، هزاران قدم جلوتر است. او روی دیگر موفقیت را به وضوح لمس کرده و تارهای متصل به شکست را می شناسد. او بهتر از هر کس دیگری می تواند سیاهچاله های منجر به شکست را به ما نشان دهد.\r\nوقتی کسی موفق می شود بدانید که چیزی یاد نگرفته، اما وقتی کسی شکست می خورد آگاه باشید که او هزاران چیز یاد گرفته که اگر شجاعت خود را از دست نداده باشد می تواند به دیگران منتقل کند. وقتی کسی شکست می خورد هرگز نگوئید او تا ابد شکست خورده است، بلکه بگوئید او هنوز موفق نشده است!\r\n"},{"id":2144,"category_id":2,"category_code":"s2","source_id":311,"title":"سحر خیز باش تا کامروا گردی!","content":"حکایت کرده اند٬ بزرگمهر٬ هرروز صبح زود خدمت انوشیروان می رفت٬ پس از ادای احترام٬رو در روی انوشیروان می گفت:\r\nسحر خیز باش تا کامروا گردی.\r\n\r\nشبی٬ انوشیروان به سرداران نظامی اش٬ دستور داد تا نیمه شب بیدار شوندو سر راه بزرگمهر٬ منتظر بمانند.چون پیش از صبح خواست به درگاه پادشاه بیاید٬ لباس هایش از تنش در بیاورندو از هر طرف به او حمله کنندتاراه فراری برای او باقی نماند.\r\nبزرگمهر راه فراری پیدا نکرد. برهنه به درگاه انوشیروان امد٬پادشاه خندید و گفت:\r\nمگر هر روز نمی گفتی٬سحر خیز باش تا کامروا باشی؟\r\nبزرگمهر گفت:دزدان امشب ٬کامروا شدند٬زیرا انها زودتر ازمن٬ بیدار شده بودند.اگر من زودتر از انها بیدار می شدم و به درگاه پادشاه می امدم من کامرواتر بودم.\r\n"},{"id":2145,"category_id":2,"category_code":"s2","source_id":312,"title":"فرار از زندگی","content":"روزی شاگردی به استاد خویش گفت: استاد می خواهم یکی از مهمترین خصایص انسان ها را به من بیاموزی؟\r\nاستاد گفت: واقعا می خواهی آن را فراگیری؟\r\nشاگرد گفت: بله، با کمال میل.\r\nاستاد گفت: پس آماده شو با هم به جایی برویم.\r\nشاگرد قبول کرد. استاد شاگرد جوانش را به پارکی که در آّن کودکان مشغول بازی بودند، برد.\r\nاستاد گفت: خوب به مکالمات بین کودکان گوش کن. مکالمات بین کودکان به این صورت بود:\r\nالان نوبت من است که فرار کنم و تو باید دنبال من بدوی.\r\nنخیر الان نوبت توست که دنبالم بدوی.\r\nاصلا چرا من هیچ وقت نباید فرار کنم؟ و حرف هایی از این قبیل...\r\nاستاد ادامه داد: همانطور که شنیدی تمام این کودکان طالب آن بودند که از دست دیگری فرار کنند. انسان نیز این گونه است. او هیچگاه حاضر نیست با شرایط موجود روبرو شود و دائم در تلاش است از حقایق و واقعیات زندگی خود فرار کند و هرگز کاری برای بهبود زندگی خود انجام نمی دهد. تو از من خواستی یکی از مهم ترین ویژگی های انسان را برای تو بگویم و من آن را در چند کلام خلاصه می کنم؛ «تلاش برای فرار از زندگی»!\r\n"},{"id":2146,"category_id":2,"category_code":"s2","source_id":313,"title":"خیاط","content":"در شهر مرو خیاطی بود، در نزدیکی گورستان دکانی داشت و کوزه ای در میخی آویخته بود و هر جنازه ای که در آن شهر تشییع می شد سنگی در کوزه می انداخت و هر ماه حساب آن سنگ ها را داشت که چند نفر در آن شهر فوت کرده اند.\r\nاز قضا خیاط بمرد و مردی به طلب به در دکان او آمد.\r\nدر را بسته دید و از همسایه خیاط پرسید که او کجاست. همسایه گفت : خیاط نیز در کوزه افتاد!\r\n"},{"id":2147,"category_id":2,"category_code":"s2","source_id":314,"title":"نصیحت خیرخواهانه","content":"روزی هارون از ابن سماک موعظه و پندی خواست.\r\nابن سماک گفت: ای هارون! بترس از این که در بهشت که به وسعت آسمان هاو زمین است ، برای تو به اندازه جای پایی نباشد.\r\n"},{"id":2148,"category_id":2,"category_code":"s2","source_id":315,"title":"دزد مال و دزد دین","content":"شخصی بسته ای یافت که در آن چیز گرانبهایی بود ودعایی نیز پیوست آن بود.آن شخص بسته را به صاحبش برگرداند.\r\nاو را گفتند : چرا این همه مال را از دست دادی؟\r\nگفت: صاحب مال عقیده داشت که این دعا ،مال او را حفظ میکند ... من دزد مال او هستم ، نه دزد دین او... اگر آن را پس نمی دادم و عقیده صاحب آن مال ، خللی می یافت ، آن وقت من، دزد باورهای او نیز بودم و این کار دور از انصاف است.\r\n"},{"id":2149,"category_id":2,"category_code":"s2","source_id":316,"title":"تیز هوشی کودک","content":"روزی ابن سینا از جلوی دکان آهنگری می گذشت که کودکی را دید. آن کودک از آهنگر مقداری آتش می خواست.\r\nآهنگر گفت: ظرف بیاور تا در آن آتش بریزم. کودک که ظرف به همراه نداشت خم شد و مشتی خاک از زمین برداشت و در کف دست خود ریخت.\r\nآن گاه به آهنگر گفت: آتش بر کف دستم بگذار. ابن سینا از تیزهوشی او به شگفت آمد و در دل به استعداد کودک شادمان شد و او را به شاگردی گرفت و در تربیتش کوشید.\r\n"},{"id":2150,"category_id":2,"category_code":"s2","source_id":317,"title":"از بدخواهت کمک بگیر","content":"مرد برنج فروشی بود که به درس های شیوانا بسیار علاقه داشت. اما به خاطر شغلی که داشت مجبور بود روزها در بازار مشغول کار باشد و شب ها نیز نزد خانواده برود. روزی این مرد نزد شیوانا آمد و به او گفت:\"\r\nدر بازار کسی هست که بدخواه من است و اتفاقا مغازه اش درست مقابل مغازه من است. او عطاری داشت اما از روی کینه و دشمنی برنج هم کنار اجناسش می فروشد و دائم حرکات و سکنات من و شاگردان و وضع مغازه ام را زیر نظر دارد و اگر اشتباهی انجام دهیم بلافاصله آن را برای مشتریان خود نقل می کند. از سوی دیگر به خاطر نوع تفکرم اهل آزاردادن و مقابله مثل نیستم و دوست هم ندارم با چنین شخصی درگیر شوم. مرا راهنمایی کنید که چه کنم!؟\"\r\nشیوانا با لبخند گفت: اینکه آدم بدخواهی با این سماجت و جدیت داشته باشد ، آنقدرها هم بد نیست!! بدخواه تو حتی بیشتر از تو برای بررسی و ارزیابی و تحلیل تو و مغازه ات وقت گذاشته است و وقت می گذارد. تو وقتی در حال خودت هستی او در حال فکر کردن به توست و این یعنی تو هر لحظه می توانی از نتیجه تلاش های او به نفع خودت استفاده کنی.\r\nمن به جای تو بودم به طور پیوسته مشتریانی نزد عطارمی فرستادم و از او در مورد تو پرس و جو می کردم. او هم آخرین نتیجه ارزیابی خودش در مورد کم کاری شاگردان یا نواقص و معایب موجود در مغازه ات را برای آن مشتری نقل می کند و در نتیجه تو با کمترین هزینه از مشورت یک فرد دقیق و نکته سنج استفاده بهره مند می شوی! بگذار بدخواه تو فکر کند از تو به خاطر شرم و حیایی و احترام و حرمتی که داری و نمی توانی واکنش نشان دهی ، جلوتر است.\r\nاز بدخواهت کمک بگیر و نواقص ات را جبران کند. زمان که بگذرد تو به خاطر استفاده تمام وقت از یک مشاور شبانه روزی مجانی به منفعت می رسی و عطار سرانجام به خاطر مشورت شبانه روزی مجانی و بدون سود برای تو سربراه خواهد شد. نهایتا چون تو بی نقص می شوی، و از همه مهم تر واکنش ناشایست نشان نمی دهی، او نیز کمال و توفیق تو را تائید خواهد کرد و دست از بدخواهی برخواهد داشت.\r\n"},{"id":2151,"category_id":2,"category_code":"s2","source_id":318,"title":"پند حکیم","content":"پادشاهی از حکیمی طلب نصیحت کرد. حکیم گفت: از تو مسئله ای پرسم بی نفاق جواب می گویی؟ زر را دوست تر داری یا خصم را؟\r\nگفت: زر را. گفت: چون است که آن را که دوست تر می داری این جا(در دنیا) می گذاری و آنچه دوست نمی داری با خود می بری؟\r\nپادشاه بگریست و گفت: نیکو پند دادی.\r\n"},{"id":2152,"category_id":2,"category_code":"s2","source_id":319,"title":"آهو و سگ","content":"روزی سگی در پی آهویی می دوید، آهو روی عقب کرد و گفت:\r\nای سگ رنج بیهوده به خود راه مده که به من نخواهی رسید زیرا که تو در پی استخوان می دوی و من در پی جان و طالب استخوان هرگز به طالب جان نمی رسد.\r\n"},{"id":2153,"category_id":2,"category_code":"s2","source_id":320,"title":"گندم و موش","content":"شخصی با دوستی گفت: پنجاه من گندم داشتم تا مرا خبر شد موشان تمام خورده بودند.\r\nاو گفت: من نیز پنجاه من گندم داشتم تا موشان را خبر شد، من تمام خورده بودم.\r\nنتیجه ی اخلاقی آنکه فرصت را شمار غنیمت جان برادر\r\n"},{"id":2154,"category_id":2,"category_code":"s2","source_id":321,"title":"صاحب بزغاله","content":"مردی بزغاله ای یافت. به او گفتند: واجب است در معابر ندا دهی تا اگر مالکی دارد بیاید و گمگشته خویش بستاند.\r\nمرد در خیابان فریاد می زد: آی صاحب و آهسته می گفت: بزغاله. (مقصود این که هم به واجب شرعی عمل کرده باشد و هم صاحب بزغاله پیدا نشود.)\r\n"},{"id":2155,"category_id":2,"category_code":"s2","source_id":322,"title":"پذیرایی مهمان","content":"یزیدبن مهلب با پسر خود از زندان عمربن عبدالعزیز فرار کردند. بعد از مسافتی به خیمه ای رسیدند، پیرزالی درآن بود.\r\nبر او وارد شدند. پیر آن ها را پذیرفت و بزغاله ای پخت و نزد آن ها گذاشت.\r\nبعد از صرف غذا یزید از پسر خود پرسید: برای خرج با خود چه داری؟\r\nپسرگفت: یک صددینار.\r\nاو گفت: همه را به پیرزال بده!\r\nپسر گفت: این عجوزه به اندک راضی می شود و تو را هم که نمی شناسد. او گفت: اگر او به اندک راضی می شود من راضی نمی شوم، اگر او مرا نمی شناسد من که خود را می شناسم!\r\n"},{"id":2156,"category_id":2,"category_code":"s2","source_id":323,"title":"دعوت به پارسایی","content":"مرد فاسقی همیشه احکام و مسائل شرعی را به زنش تعلیم می داد و همواره وی را به زهد و پارسایی وا می داشت.\r\nعالمی از او پرسید: سبب چیست که خود آن چنان هستی و زنت را این چنین وا می داری؟\r\nمرد گفت: من خود می دانم به جهنم خواهم رفت می خواهم این زن به بهشت رود تا در جهنم پیش من نباشد و لااقل آن جا از دستش راحت باشم!\r\n"},{"id":2157,"category_id":2,"category_code":"s2","source_id":324,"title":"ظلم معلم","content":"\r\nانوشیروان را معلمی بود.\r\nروزی معلم او را بدون تقصیری بیازرد.\r\nانوشیروان کینه او را در دل گرفت تا به پادشاهی رسید. آن گاه از او پرسید: چرا بی سبب بر من ظلم کردی؟ معلم گفت: چون امید آن داشتم که بعد از پدر به پادشاهی برسی، خواستم که تو را طعم ظلم بچشانم تا در ایام سلطنت به ظلم اقدام نکنی!\r\n"},{"id":2158,"category_id":2,"category_code":"s2","source_id":325,"title":"خدا پرست و فرعون","content":"\r\nدر زمان فرعون دو نفر بدخواه نزد فرعون رفته از شخص سومی که خداپرست بود بدگویی کردند و گفتند: او پروردگار دیگری را پرستیده، تو را به خدایی قبول ندارد.\r\nفرعون گفت: او را نزد من بیاورید. دستور او را اطاعت کردند و مرد خداپرست را پیش فرعون بردند. در این وقت فرعون از دو مرد سعایت کننده پرسید: پروردگار شما کیست؟\r\nگفتند: پروردگار ما تویی. فرعون از خداپرست پرسید: پروردگار تو کیست؟\r\nمرد مومن گفت: پروردگار من همان پروردگار ایشان است. (منظور مرد مومن، خالق آن دو مرد بود که پروردگارعالمیان است) فرعون تصور کرد که او را می گوید بنابراین سعایت کنندگان را سرزنش کرد و از دربار راند.\r\n"},{"id":2159,"category_id":2,"category_code":"s2","source_id":326,"title":"همین و والسلام","content":"\r\nشخصی که قصد مسافرت داشت پیش قاطرچی رفت تا از او قاطر کرایه کند.\r\nصاحب قاطر گفت: چه قدر اسباب داری؟\r\nمسافر گفت: یک صندوق کوچک والسلام\r\nصاحب قاطر گفت: دیگر چیزی نداری؟\r\nمسافرگفت: یک دست رختخواب و والسلام\r\nاو گفت: دیگر چه داری؟\r\nمرد گفت: یک کیسه گونی خردوریز و چهار قالیچه والسلام\r\nاو گفت: دیگر همین؟\r\nمسافر گفت: مادر بچه ها که همراه من است و والسلام\r\nصاحب قاطر هم گوشش را خاراند و گفت: ما هم قاطر کرایه ای نداریم و والسلام\r\n"},{"id":2160,"category_id":2,"category_code":"s2","source_id":327,"title":"نابینا و فضول","content":"نابینایی در شب تاریک سبویی بر دوش و چراغی در دست داشت و به راهی می رفت. شخصی فضول به او رسید و خطاب به وی گفت: ای نادان شب و روز پیش تو یکسان است و روشنی و تاریکی برابر. چرا با خود چراغ حمل می کنی؟\r\nنابینا گفت: این چراغ را برای این برداشته ام تا یک نفر کوردلی چون تو تنه نزند و سبوی مرا نشکند!\r\n"},{"id":2161,"category_id":2,"category_code":"s2","source_id":328,"title":"فردی در چاه","content":"روزی فردی داخل چاله ای افتاد و بسيار دردش آمد ...\r\nیک روحانی او را دید و گفت :حتما گناهی انجام داده ای!\r\nیک دانشمند عمق چاله و رطوبت خاک آن را اندازه گرفت!\r\nیک روزنامه نگار در مورد دردهایش با او مصاحبه کرد!\r\nیک یوگيست به او گفت : این چاله و همچنين دردت فقط در ذهن تو هستند در واقعيت وجود ندارند!!!\r\nیک پزشک برای او دو قرص آسپرین پایين انداخت!\r\nیک پرستار کنار چاله ایستاد و با او گریه کرد!\r\nیک روانشناس او را تحریک کرد تا دلایلی را که پدر و مادرش او را آماده افتادن به داخل چاله کرده بودند پيدا کند!\r\nیک تقویت کننده فکر او را نصيحت کرد که : خواستن توانستن است!\r\nیک فرد خوشبين به او گفت : ممکن بود یکی از پاهات رو بشکنی!!!\r\nسپس فرد بیسوادی گذشت و دست او را گرفت و او را از چاله بيرون آورد...!\r\n"},{"id":2162,"category_id":2,"category_code":"s2","source_id":329,"title":"سگ با هوش و صاحب ناشکر","content":"قصاب با دیدن سگی که به طرف مغازه اش نزدیک می شد حرکتی کرد که از مغازه دورش کند. اما ناگهان کاغذی را در دهان سگ دید. کاغذ را گرفت. روی کاغذ نوشته بود \"لطفا دوازده سوسیس و یک ران گوشت بدین\". یک اسکناس 10 دلاری هم همراه کاغذ بود!\r\nقصاب با کمال و حیرت تعجب، سوسیس و گوشت را در کیسه ای گذاشت و در دهان سگ گذاشت. سگ هم کیسه را گرفت و رفت. او بسیار کنجکاو شده بود و از طرفی وقت بستن مغازه هم بود. این بود که بلافاصله مغازه را تعطیل کرد و بدنبال سگ راه افتاد.\r\n\r\nقصاب با دیدن سگی که به طرف مغازه اش نزدیک می شد حرکتی کرد که از مغازه دورش کند. اما ناگهان کاغذی را در دهان سگ دید. کاغذ را گرفت. روی کاغذ نوشته بود \"لطفا دوازده سوسیس و یک ران گوشت بدین\". یک اسکناس 10 دلاری هم همراه کاغذ بود!\r\nقصاب با کمال و حیرت تعجب، سوسیس و گوشت را در کیسه ای گذاشت و در دهان سگ گذاشت. سگ هم کیسه را گرفت و رفت. او بسیار کنجکاو شده بود و از طرفی وقت بستن مغازه هم بود. این بود که بلافاصله مغازه را تعطیل کرد و بدنبال سگ راه افتاد.\r\n\r\n\r\nسگ در خیابان حرکت کرد تا به محل خط کشی رسید. با حوصله ایستاد تا چراغ سبز شد و بعد از خیابان رد شد. قصاب به دنبالش راه افتاد. سگ رفت تا به ایستگاه اتوبوس رسید نگاهی به تابلو حرکت اتوبوس ها کرد و ایستاد. قصاب متحیر از حرکت سگ منتظر ماند.\r\n\r\nاتوبوس آمد، سگ جلوی اتوبوس آمد و شماره آنرا نگاه کرد و به ایستگاه برگشت. صبر کرد تا اتوبوس بعدی آمد، دوباره شماره آنرا چک کرد. اتوبوس درست بود سوار شد. قصاب هم در حالی که دهانش از حیرت باز بود سوار شد. اتوبوس در حال حرکت به سمت حومه شهر بود و سگ منظره بیرون را تماشا می کرد. پس از چند خیابان سگ روی پنجه باند شد و زنگ اتوبوس را زد. اتوبوس ایستاد و سگ با کیسه پیاده شد. قصاب هم به دنبال او رفت.\r\n\r\nسگ در خیابان حرکت کرد تا به خانه ای رسید. گوشت را روی پله گذاشت و کمی عقب رفت و خودش را به در کوبید. اینکار را باز هم تکرار کرد اما کسی در را باز نکرد. سگ به طرف محوطه باغ رفت و روی دیواری باریک پرید و خودش را به پنجره رساند و سرش را چند بار به پنجره زد و بعد به پایین پرید و به پشت در برگشت.\r\n\r\nمردی در را باز کرد و شروع به فحش دادن و تنبیه سگ کرد. قصاب با عجله به مرد نزدیک شد و داد زد: چه کار می کنی دیوانه؟ این سگ یه نابغه است. این باهوش ترین سگی هست که من تا بحال دیدم.\r\n\r\nمرد نگاهی به قصاب کرد و گقت: تو به این میگی باهوش؟ این دومین بار تو این هفته است که این احمق روش برگشتن سریع به خونه رو فراموش می کنه!\r\n\r\nشاید طرح این داستان با اندازه ای اغراق همراه است که البته برای خیلی ها باورش مشکله ولی نکته های اخلاقی در این نگارش وجود داره که بد نیست بهش توجه داشته باشیم. \r\n\r\nاول اینکه مردم هرگز از چیزهایی که دارند راضی نخواهند بود و \r\nدوم اینکه چیزی که شما آن را بی ارزش می دانید بطور قطع برای کسانی دیگر ارزشمند و غنیمت است و خلاصه سوم اینکه بدانیم دنیا پر از تناقضاتی است که ممکن است در باورمان نگنجد. \r\nپس سعی کنیم ارزش واقعی هر چیزی را درک کنیم و مهمتر اینکه قدر داشته های مان را بدانیم.\r\n"},{"id":2163,"category_id":2,"category_code":"s2","source_id":330,"title":"نخ و سوزن","content":"دوره گرد بساط عینک را کنار پیاده رو پهن کرده بود، نخ و سوزنی در دست داشت و جار می زد:\r\nایها لخلایق، احتیاجی نیست پول خودت را دور بریزی و بدهی نمره عینک برای تو تعیین کنند، یکی از این عینک ها را بردار روی چشم بگذارد، اگر توانستی این نخ را در سوراخ سوزن بکنی، عینک مناسب چشمت است. بردار و حالش را ببر!\r\nپیرمردی عصا به دست که از پیاده رو عبور می کرد مکث کرد. دوره گرد عینک را بر چشم او گذاشت و نخ و سوزن را به دست او داد اما پیرمرد که با عینک، نخ و سوزن را تشخیص می داد هر قدر خواست نخ را در سوزن بکند نتوانست و عینک فروش هم نمی دانست که دست های لرزان پیرمرد قادر نخواهد بود نخ را در سوزن کند. عینک را از چشم او برگرفت و در بساط خود گذاشت.\r\nپیرمرد نومیدانه به راه خود ادامه داد.\r\n"},{"id":2164,"category_id":2,"category_code":"s2","source_id":331,"title":"عمر کوتاه","content":"می.گویند: روزی یکی از انبیای الهی در گذر خود به مردی پیر و فرتوت برخورد که برای خود جایگاهی در بالای درختی کهن سال ساخته بود و در آن به عبادت خدا مشغول بود. سر سخن را با او باز کرد و در نهایت پرسید: حالا چرا اینجا زندگی می.کنی؟\r\nگفت: جوان که بودم در عالم رؤیا به من خبر دادند که بیش از 900 سال زندگی نخواهم کرد، لذا حیفم آمد که این عمر کوتاه را به جای عبادت، در راه ساختن خانه و کاشانه تلف کنم.\r\nآن نبی گفت: اما به من خبر رسیده که زمانی خواهد رسید که در آن زمان مردمان بیش از 80 یا 90 سال عمر نخواهند کرد اما برای خود قصرها و برج.ها می.سازند.\r\nاو گفت: ای بابا، اگر عمر من 90 سال بود که آن را با یک سجده سپری می.کردم.\r\n"},{"id":2165,"category_id":2,"category_code":"s2","source_id":332,"title":"بخیل و حکیم","content":"بخیلی حکیمی را دید که به محنت بسیار سنگ از معدن نقره می کند، ریزه می ساخت بعد از آن می گداخت و قراضه ای حاصل می کرد و با آن معاش می گذراند.\r\nبخیل گفت: ای حکیم، معیشت از این آسان تر میسر است، این همه محنت چرا می کشی؟\r\nگفت: به این محنت و مشقت زر حاصل کردن بر من هزار بار آسان تر است که از مشت تو یک فلس بیرون آوردن.\r\n"},{"id":2166,"category_id":2,"category_code":"s2","source_id":333,"title":"معامله ی بد","content":"مردی زمینش را به مبلغی فروخت و در برابر آن اسبی خرید . حکیمی به او رسید و گفت: \"دانستی که چه معامله‌ایی کردی؟ چیزی را که به آن سرگین می‌دادی و در برابرش جو می‌گرفتی، با چیزی عوض کردی که باید به آن جو بدهی و در برابرش سرگین بگیری!\""},{"id":2167,"category_id":2,"category_code":"s2","source_id":334,"title":"مهلت یکساله","content":"یکی از یکی دیگر درخواست کرد، تا مبلغی را با مهلت یک ماهه به او قرض دهد . آن یکی گفت: \"اکنون مبلغی را که می‌خواهی ندارم . اما می‌توانم نیمی از خواسته ات اجابت کنم و به جای یک ماه به تو یک سال مهلت بدهم!\""},{"id":2168,"category_id":2,"category_code":"s2","source_id":335,"title":"عبادت ستون","content":"مردی به صاحبخانه‌ی خود گفت: \"زحمت بکشید و ستون این سقف را تعمیر کنید که به شدت صدای شکستگی می‌کند.\" صاحبخانه گفت: \"نگران نباش، ستون در حال ذکر گفتن است!\" مرد گفت: \"البته که نگران نیستم ، فقط می‌ترسم نازک دلی در او ایجاد شود و سجده کند!\""},{"id":2169,"category_id":2,"category_code":"s2","source_id":336,"title":"کی بهتر می فهمه؟","content":"شخصی مادر پیرش را در زنبیلی می گذاشت و هرجا می رفت، همراه خودش میبرد. روزی حضرت عیسی او را دید، به وی فرمود: آن زن کیست گفت مادرم است. فرمود: او را شوهر بده. گفت: پیر است و قادر به حرکت نیست. پیرزن دستش را از زنبیل بیرون آورد و بر سر پسرش زد و گفت: آخه نکبت! تو بهتر می فهمی یا پیغمبر خدا؟ "},{"id":2170,"category_id":2,"category_code":"s2","source_id":337,"title":"امتحان دامادها","content":"\r\nزنى سه دختر داشت که هر سه ازدواج کرده بودند. \r\nیکروز تصمیم گرفت میزان علاقه‌اى که دامادهایش به او دارند را ارزیابى کند. \r\nیکى از دامادها را به خانه‌اش دعوت کرد و در حالى که در کنار استخر قدم مى‌زدند از قصد وانمود کرد که پایش لیز خورده و خود را درون استخر انداخت. \r\nدامادش فوراً شیرجه رفت توى آب و او را نجات داد. \r\nفردا صبح یک ماشین پژو ٢٠٦ نو جلوى پارکینگ خانه داماد بود و روى شیشه‌اش نوشته بود: «متشکرم! از طرف مادر زنت» \r\nزن همین کار را با داماد دومش هم کرد و این بار هم داماد فوراً شیرجه رفت توى آب وجان زن را نجات داد. \r\nداماد دوم هم فرداى آن روز یک ماشین پژو ٢٠٦ نو هدیه گرفت که روى شیشه‌اش نوشته بود: «متشکرم! از طرف مادر زنت» \r\nنوبت به داماد آخرى رسید. \r\nزن باز هم همان صحنه را تکرار کرد و خود را به داخل استخر انداخت. \r\nامّا داماد از جایش تکان نخورد. \r\nاو پیش خود فکر کرد وقتش رسیده که این پیرزن از دنیا برود پس چرا من خودم را به خطر بیاندازم. \r\nهمین طور ایستاد تا مادر زنش درآب غرق شد و مرد. \r\nفردا صبح یک ماشین بى‌ام‌و کورسى آخرین مدل جلوى پارکینگ خانه داماد سوم بود که روى شیشه‌اش نوشته بود: «متشکرم! از طرف پدر زنت» \r\n"},{"id":2171,"category_id":2,"category_code":"s2","source_id":338,"title":"فردوسی و شیخ گرگانی","content":"آورده اند که :\r\nو چون فردوسی وفات کرده ، شیخ ابوالقاسم کرگانی بر او نماز نکرده ، و عذر گفته که او مداح کفار بوده ، و بعد از آن به کشف مشاهده کرده که فردوسی در بهشت فردوس با حور در قصور است .\r\nشیخ به او گفته : به چه چیز خدای – تعالی – تو را آمرزید ، و در جنت ساکن گردانید ؟\r\nفردوسی گفته : به دو چیز : یکی به آنکه تو بر من نماز نکردی ! ، و یکی آنکه این بیت در توحید گفته ام که :\r\nجهان را بلندی و پستی تویی ندانم چه ای ، هر چه هستی تویی ....\r\n"},{"id":2172,"category_id":2,"category_code":"s2","source_id":339,"title":"کوروش و خلاف کاران","content":"خورشید هنوز در پشت کوههای باختر فرو نرفته بود که کورش پادشاه ایران دستور داد سپاه در نزدیکی شهر ایلام اردو بزند همه سرخوش از پیروزی خود بر بابل بودند .\r\nدر آن هنگامه پیر زن و پسر جوانی به اردوگاه آمده و نزد پادشاه ایران از کارمند مالیات شهرشان شکایت نمودند . پس از تحقیق معلوم شد آن کارمند هر ساله بیش از آنچه دولت در نظر گرفته از مردم خراج می ستاند .\r\nآن شب کورش پادشاه ایران در همان اردوگاه سرپرست خزانه دارای و مالیات فرمانروایی را از کار برکنار نموده و کس دیگری را به کار گمارد .\r\nاندیشمند کشورمان ارد بزرگ می گوید : ریشه کارمند نابکار ، در نهاد سرپرست و مدیر ناتوان است . و هم او در جایی دیگر می گوید : فرمانروا در برکناری کارمند نابکار زمانی را نباید از دست دهد چون سیاهی کار بزهکار در دید مردم خیلی زود دامن او را نیز خواهد گرفت .\r\n\r\nگفته می شود که پس از برکناری مدیر خزانه داری سه نفر از سرپرستان و اشراف کشور نزد فرمانروای ایران آمده تا پادشاه ایران را از تصمیمی که گرفته است باز دارند . کورش هخامنشی نه تنها از رای خود بر نگشت بلکه آن سه تن را هم از کار برکنار نمود و گفت : اگر تخم بدکاری از خاک ایران کنده نشود آرامشی نخواهیم داشت .\r\n"},{"id":2173,"category_id":2,"category_code":"s2","source_id":340,"title":"شاپور ساسانی و آهنگر ","content":"آهنگری شمشیر بسیار زیبا تقدیم شاپور پادشاه ساسانی نمود . شاپور از او پرسید چه مدت برای ساختن این شمشیر زمان گذاشته ایی و آهنگر پاسخ داد یک سال تمام . پادشاه ایران باز پرسید و اگر یک شمشیر ساده برای سربازان بسازی چقدر زمان می برد ؟ و او گفت سه تا چهار روز .\r\nشاپور گفت آیا این شمشیر قدرتی بیشتر از آن صد شمشیر دیگری که می توانستی بسازی دارد ؟\r\nآهنگر گفت: خیر ، این شمشیر زیباست و شایسته کمر شهریار !\r\nپادشاه ایران گفت : سپاسگذارم از این پیشکش اما ، پادشاه اهل فرمان دادن است نه جنگیدن ، من از شما شمشیر برای سپاهیان ایران می خواهم نه برای خودم ، و به یاد داشته باش سرباز بی شمشیر نگهبان کیان کشور ، پادشاه و حتی جان خویش نیست . این سخن شاپور دوم ما را به یاد این سخن دانای ایرانی ارد بزرگ می اندازد که : فرمانروای شایسته اسیر کاخ ها نمی شود نگاه او بر مرزهای کشور است .\r\nشاپور با نگاهی پدرانه به آهنگر گفت اگر به تو پاداش دهم هر روز صنعتگران و هنرمندان به جای توجه به نیازهای واقعی کشور ، برای من زینت آلات می سازند و این سرآغاز سقوط ایران است . پدرم به من آموخت زندگی ساده داشته باشم تا فرمانرواییم پایدارتر باشد . پس برای سربازان شمشیر بساز که نبردهای بزرگ در راه است .\r\n"},{"id":2174,"category_id":2,"category_code":"s2","source_id":341,"title":"ابومسلم و آزادگی ","content":"ابو جعفر منصور دومین خلیفه عباسی آنگاه که دید محبوبیت ابومسلم بمراتب از او که خلیفه است در بین تبار ایرانیان بیشتر است تصمیم به قتل او گرفت برای اینکار به حیله های بسیاری متوصل شد تا ابومسلم را برای اجرای نقشه شوم خویش به دستگاه خلافت بکشد .\r\nروزی که منصور پلید همچون خفاشی خونخوار قهرمان ایرانیان ، ابومسلم خراسانی را با سربازان سیاه دل خویش دور از دسترس ایرانیان و بخصوص خراسانیان به قتل رساند نبض ایران ایستاده بود .\r\nآنگاه که پیکر شهید سرخ ایران را از دستگاه خلیفه به بیرون کشیدند منصور دید بر روی زمین گردنبندی از پوست آهو افتاده آن را باز کرد و در آن بر پوسته یی نازک به زبان پهلوی خطوطی دید دانشمندان دربار منصور متن را ترجمه کردند :\r\n« سرباز ایران ابومسلم خراسانی »\r\nفیلسوف و متفکر کشورمان ارد بزرگ می گوید : ابومسلم خراسانی نماد برافراشته آزادگی ایرانیان است او بندهای دشمنان ایران را پاره کرد و خون گرمی شد در رگهای سرد کشورمان ، خونی که تا ابد در دل این کشور خواهد جوشید و هر زنجیری را پاره خواهد نمود .\r\nایرانیان از همان روز تصمیم به نابودی دودمان جور و ستم عباسیان را گرفتند کسانی همچون سنباد اسحاق ترک مقنع و بابک خرم دین پرچم انتقام خون ابومسلم را بر دست داشتند و در نهایت به تدبیر مرد جاودانه ایران خواجه نصیرالدین توسی سلسله عباسیان با خواری و خفت تمام به پایان رسید .\r\n"},{"id":2175,"category_id":2,"category_code":"s2","source_id":342,"title":"لب آب","content":"یک خروار گندم به آسیا می‌برد. به لب آبی رسید. خواست که گندم از لب بگذراند. ناگاه سواری را دید که از دور پیدا شد. با خود گفت که این سوار برسد، اول سلام خواهد کرد، بعد از آن خواهد پرسید که بلندی آب چه مقدار است و دیگر خواهد پرسید که این گندم چند من است. چون سوار برسید، پرسید که ای مردک، بلندی آب چه مقدار است؟\" گفت: علیکم السلام و رحمه الله و برکاته! سوار بخندید و گفت: سرت ببرند! گفت: تا به گردن و سینه!\" گفت: خاکت به دهن!\" گفت: \"هشتاد من!"},{"id":2176,"category_id":2,"category_code":"s2","source_id":343,"title":"قربانی کردن شتر","content":"اعرابی‌ در روز عید شتری‌ قربانی‌ كرده‌ بود و در هر مجلسی‌ كه‌ می‌رسید می‌گفت‌ كه‌ من‌ شتری‌ در راه‌ خدا قربانی‌ كرده‌ام‌.\r\nبه‌ او گفتند: «چه‌ معنی‌ دارد كه‌ هر جا می‌رسی‌ ذكر قربانی‌ كردن‌ شتر می‌كنی‌؟ قربانی‌ كردن‌ در راه‌ خدا كه‌ این‌ همه‌ گفتن‌ ندارد!»\r\nاعرابی‌ گفت‌: «سبحان‌ الله! خدای‌ تعالی‌ خودش‌ یك‌ گوسفند فدای‌ اسماعیل‌ كرد، در چند جای‌ قرآن‌ آن‌ را ذكر كرده‌، آن‌ وقت‌ من‌ شتری‌ به‌ این‌ بزرگی‌ قربانی‌ كردم‌ هیچ‌ جا نگویم‌؟»\r\n"},{"id":2177,"category_id":2,"category_code":"s2","source_id":344,"title":"تخته نرد و هوش ایرانی","content":"در زمان پادشاهي انوشيروان خسرو پسر قباد، پادشاه هند «ديورسام بزرگ» براي سنجش خرد و دانايي ايرانيان و اثبات برتري خود شطرنجي را که مهره هاي آن از زمرد و ياقوت سرخ بود، به همراه هدايايي نفيس به دربار ايران فرستاد و «تخت ريتوس» دانا را نيز گماردهء انجام اين کار ساخت. او در نامه اي به پادشاه ايران نوشت: «از آنجا که شما شاهنشاه ما هستيد، دانايان شما نيز بايد از دانايان ما برتر باشند. پس يا روش و شيوهء آنچه را که به نزد شما فرستاده ايم (شطرنج) بازگوييد و يا پس از اين ساو و باج براي ما بفرستيد». شاه ايران پس از خواندن نامه چهل روز زمان خواست و هيچ يک از دانايان در اين چند روز چاره و روش آن را نيافت، تا اينکه روز چهلم بزرگمهر كه جوانترين وزير انوشيروان بود به پا خاست و گفت: «اين شطرنج را چون ميدان جنگ ساخته اند كه دو طرف با مهره هاي خود با هم مي جنگند و هر كدام خرد و دورانديشي بيشتري داشته باشد، پيروز مي شود.» و رازهاي کامل بازي شطرنج و روش چيدن مهره ها را گفت. شاهنشاه سه بار بر او درود فرستاد و دوازده هزار سکه به او پاداش داد. پس از آن «تخت ريتوس» با بزرگمهر به بازي پرداخت. بزرگمهر سه بار بر تخت ريتوس پيروز شد. روز بعد بزرگمهر تخت ريتوس را به نزد خود خواند و وسيلهء بازي ديگري را نشان داد و گفت: اگر شما اين را پاسخ داديد ما باجگزار شما مي شويم و اگر نتوانستيد بايد باجگزار ما باشيد.» ديورسام چهل روز زمان خواست، اما هيچ يک از دانايان آن سرزمين نتوانستند «وين اردشير» را چاره گشايي کنند و به اين ترتيب شاه هندوستان پذيرفت كه باجگزار ايران باشد."},{"id":2178,"category_id":2,"category_code":"s2","source_id":345,"title":"مازیار و گلدیس ","content":"تمیستوکل پادشاه یونان در آرزوی کاخی به زیبایی تخت جمشید بود یکی سرداران خویش که زبان ایرانیان را می دانست فرا خواند و به او گفت شنیده ام سنگ تراشی بنام مازیار و شاگردش بانو گلدیس پرسپولیس را همچون جواهرات تراش داده اند آنهم به گونه ایی که پیک های سرزمینهای دیگر از این همه زیبایی در شگفت شده اند به ایران رو و به هر گونه که امکان دارد این دو را به یونان بیاور می خواهم آنها پرسپولیس زیباتری در آتن بسازند . آن فرمانده یونانی با چند سرباز دیگر با تن پوشی ایرانی به سرزمین ما آمده و پس از چندی با دو هنرمند ایرانی بازگشت . در حالی که دست های آنها بسته ، رویشان زرد و بسیار نحیف و لاغر شده بودند . تمیستوکل دستور داد دست های آنها را باز کنند و به آنها گفت می خواهم هنرمندان یونانی را آموزش دهید و با کمک آنها کاخی باشکوه تر از پرسپولیس برایم بسازید .\r\nمازیار سالخورده گفت نقشی که بر دیوارهای تخت جمشید می تراشیم همه عشق است ما نمی توانیم خواسته شما را انجام دهیم پادشاه یونان تمیستوکل برافروخت و آن دو را به زندان افکند . مازیار و بانو گلدیس یک سال در بدترین شرایط شکنجه شدند اما برای اجنبی خدمتی نکردند تا اینکه خشایارشاه پس از شکست دادن یونان و فتح آتن آن دو هنرمند دلیر و میهن پرست ایرانزمین را آزاد و به همراه خود به ایران بازگرداند و به هر دوی آنها هدیه های ارزشمندی داد .\r\n"},{"id":2179,"category_id":2,"category_code":"s2","source_id":346,"title":"حجاج و دیوانه ","content":"روزی حجاج این یوسف در صحرا با معدودی چند از خاصان خود سیر می‌کرد. از دور غلامی شبان دید که گوسفند می‌چرانید. ملازمان را گفت: \"شما بر جا باشید تا من با آن صحبتی دارم.\" پس اسب خود را برانگیخت و بر سر او رفت و سلام کرد. او جواب داد. حجاج ازو پرسید که ای غلام، حجاج ابن یوسف بر شما چگونه حاکم است؟ غلام گفت: \"لعنت خدا بر او باشد که هرگز ظالم‌تری از او بر مسند حکومت ننشسته، بی‌رحمی، سفاکی، خدانترسی بی‌باکست. امید دارم که روی زمین از لوث ظلم او پاک شود.\" حجاج گفت: \"مرا می‌شناسی؟\" گفت: \"نی!\" گفت: \"منم حجاج!\" غلام گفت: \"مرا می‌شناسی؟\" حجاج گفت: \"نی!\" غلام گفت: \"منم دردان، از غلامان آپی‌شورم و در هر ماه مرا سه بار صرع می‌گردد و دیوانه می‌شوم و امروز در روز جنون من است.\" حجاج بخندید و او را خلعت بخشید."},{"id":2180,"category_id":2,"category_code":"s2","source_id":347,"title":"موسی وشبان","content":"حضرت موسي در راهي چوپاني را ديد كه با خدا سخن مي‌گفت. چوپان مي‌گفت: اي خداي بزرگ تو كجا هستي, تا نوكرِ تو شوم, كفش‌هايت را تميز كنم, سرت را شانه كنم, لباس‌هايت را بشويم پشه‌هايت را بكشم. شير برايت بياورم. دستت را ببوسم, پايت را نوازش كنم. رختخوابت را تميز و آماده كنم. بگو كجايي؟ اي خُدا. همة بُزهاي من فداي تو باد.‌هاي و هوي من در كوه‌ها به ياد توست. چوپان فرياد مي‌زد و خدا را جستجو مي‌كرد.\r\nموسي پيش او رفت و با خشم گفت: اي مرد احمق, اين چگونه سخن گفتن است؟ با چه كسي مي‌گويي؟ موسي گفت: اي بيچاره, تو دين خود را از دست دادي, بي‌دين شدي. بي‌ادب شدي. اي چه حرفهاي بيهوده و غلط است كه مي‌گويي؟ خاموش باش, برو پنبه در دهانت كن تا خفه شوي, شايد خُدا تو را ببخشد. حرف‌هاي زشت تو جهان را آلوده كرد, تو دين و ايمان را پاره پاره كردي. اگر خاموش نشوي, آتش خشم خدا همة جهان را خواهد سوخت,\r\nچوپان از ترس, گريه كرد. گفت اي موسي تو دهان مرا دوختي, من پشيمانم, جان من سوخت. و بعد چوپان, لباسش را پاره كرد. فرياد كشيد و به بيابان فرار كرد.\r\nخداوند به موسي فرمود: اي پيامبر ما, چرا بندة ما را از ما دور كردي؟ ما ترا براي وصل كردن فرستاديم نه براي بريدن و جدا كردن. ما به هر كسي يك خلاق و روش جداگانه داده‌ايم. به هر كسي زبان و واژه‌هايي داده‌ايم. هر كس با زبانِ خود و به اندازة فهمِ خود با ما سخن مي‌گويد. هنديان زبان خاص خود دارند و ايرانيان زبان خاص خود و اعراب زباني ديگر. پادشاه زباني دارد و گدا و چوپان هر كدام زباني و روشي و مرامي مخصوصِ خود. ما به اختلاف زبانها و روش‌ها و صورت‌ها كاري نداريم كارِ ما با دل و درون است. اي موسي, آداب داني و صورت‌گري جداست و عاشقي و سوختگي جدا. ما با عشقان كار داريم. مذهب عاشقان از زبان و مذهب صورت پرستان جداست. مذهب عاشقان عشق است و در دين عشق لفظ و صورت مي‌سوزد و معنا مي‌ماند. صورت و زبان علت اختلاف است. ما لفظ و صورت نمي‌خواهيم ما سوز دل و پاكي مي‌خواهيم. موسي چون اين سخن‌ها را شنيد به بيابان رفت و دنبال چوپان دويد. ردپاي او را دنبال كرد. رد پاي ديگران فرق دارد. موسي چوپان را يافت او را گرفت و گفت: مژده مژده كه خداوند فرمود:\r\nهيچ ترتيبي و آدابي مجو هر چه مي‌خواهد دل تنگت, بگو\r\n"},{"id":2181,"category_id":2,"category_code":"s2","source_id":348,"title":"کاکل زری ،دندون مُرواری ","content":"در زمانهای قدیم سه دختر بودند که زن پدر داشتند . یک روز زن بابا به آنها گفت \"می خواییم حلوا درست کنیم هر که بیشتر کار کنه ته دیگ حلوا را به اون می دیم\" . هرکدام از دخترها کاری کردند ، آخر که حلوا پخته شد توی یک سینی بزرگ ریختند ولی ته دیگ را زن بابا خورد و به دختر ها نداد . دخترها وقتی که زن بابا از خانه رفت بیرون گفتند باید تلافی در بیاریم ، همه حلواها را خوردند و وقتی پدرشان از صحرا برگشت زنش گفت : امروز حلوا پختیم بیارم یه کم هم تو بخور . وقتی سینی حلوا را آورد مرد دید خالی است . زن گفت این کار دختراته و اینجا یا جای منه یا جای دخترها . مرد گفت الان دخترها را می برم بیابان ولشان می کنم . دخترها را برد بیابان و به آنها گفت : من می رم دستشویی و زود برمی گردم . دخترها منتظر پدر ماندند ولی پدرشان نیامد، وقتی رفتند اطراف را گشتند دیدند پدر نیست و آنها هم راه خانه را بلد نبودند . زیر یک درخت نشستند تا اینکه شب شد . داشتند با هم صحبت می کردند. دختر بزرگ گفت : اگر من را پسر پادشاه بگیره لباس همه قشون پادشاه را می دوزم . دختر دوم گفت : اگر من را پسر پادشاه بگیره برای همه سپاه پادشاه نون می پزم . دختر کوچک گفت : اگر من را پسر پادشاه بگیره ، یه دختر دندون مرواری با یک پسر کاکل زری براش به دنیا می آرم . \r\n سه تا از پسرهای پادشاه که به شکار رفته بودند صدایشان را شنیدند و آنها را با خود به شهر بردند و شهر را آینه بندان کردند و هر کدام با یکی از دخترها عروسی کردند . دختر بزرگی یک لباس دوخت پر از سوزن کرد هر یکی از سربازان می پوشیدند سوراخ سوراخ می شدند و سریع لباس را در می آوردند . پسر پادشاه این دختر را طلاق داد . \r\nدختر دوم که قول داده بود نان بپزد خمیر را شور کرده بود سربازان پادشاه هر لقمه نان را که خوردند شور بود و از دهنشان بیرون انداختند . پسر پادشاه دختر دوم را هم طلاق داد و ماند دختر کوچک . دختر کوچک زایید و یک دختر دندون مرواری با یک پسر کاکل زری به دنیا آورد . خواهرهایش که خیلی حسود بودند زود بچه ها را برداشتند و بردند و به جای آنها دو تا توله سگ گذاشتند . پسر پادشاه که از شکار برگشت بهش گفتند که زنت زاییده و دو تا توله سگ به دنیا آورده . ناراحت شد و گفت : زنی که توله سگ بیاره باید ببرندش جلوی دروازه شهر به گچ بگیرند . زن هرچه التماس کرد که این حرفها دروغه و من بچه دندون مرواری و کاکل زری آوردم شوهرش قبول نکرد بنابر این به سربازها گفت : بروید در دروازه شهر چاله بکنید و زن را تا کمر در چاله کنید و گچ بزنید و به بچه ها گفت که بروند سنگش بزنند .\r\nخواهر های زن بچه ها را بردند توی یکی از خرابه های کنار شهر گذاشتند . از قضا یک گوسفند بود که مال یک پیرزن بود هر روز می رفت توی خرابه و به بچه ها شیر می داد و آنها بزرگ می شدند . پیرزن دید که هر روز که بزش می آید شیر ندارد. رفت به چوپان گله گفت که شیر بز من را تو می دوشی . هرچی چوپان گفت من نمی دوشم پیرزن قبول نکرد . چوپان گفت خودت همراه گله بیا ببین که بزت کجا میره . پیرزن با گله رفت ، دید که بزش رفت توی خرابه و دو تا بچه شیرش را خوردند . پیرزن بچه ها را به خونه آورد ، هروقت که بی پول می شد یک نیشگون به دختر می گرفت گریه می کرد و دختر که دندانهایش مروارید بود اشکهایش هم مروارید می شد آنها را جمع می کرد می برد می فروخت و موهای پسر را هم می چید و می فروخت تا اینکه بچه ها بزرگ شدند و هر روز می رفتند دم دروازه با بچه های دیگر بازی می کردند و به زن پسر پادشاه که تو گچ بود سنگ می زدند و این بچه ها نمی دانستند که این زن ، مادرشان است . یک روز پسر پادشاه از زنش پرسید اینقدر بچه ها به تو سنگ می زنند دردت هم میاد ؟ گفت : نه ، فقط یک دختر و پسر هستند که وقتی سنگ می زنند دردم میاد ! \r\nبچه ها بزرگ و بزرگتر شدند و برای خودشان قصری ساختند . خاله هاشون فهمیدند که این ها همان بچه ها هستند با خود گفتند هرجوری شده باید آنها را از بین ببریم . گفتند می ریم بهشون می گیم که خونه شما خیلی قشنگه فقط یه اسب چهل کُرّه می خواد . وقتی اونها میرن اسب را بگیرن اسب اونها را لگد می زنه و می میرن . خاله ها رفتند به پسر کاکل زری گفتند : خونه شما اسب چهل کره می خواد. پسره آمد به خواهرش گفت : این زن گفته خونه شما اسب چهل کره می خواد. خواهرش گفت یه کم شکر وردار برو لب چشمه، وقتی اسب اومد آب بخوره یک مشت شکر بریز توی آب . اسب میگه چه آب شیرینی ! تو هم بهش می گی بیا پالانت کنم ، میاد . باز یک مشت دیگه شکر می ریزی تو آب میگه چه آب شیرینی ، میگی : بیا زینِت کنم و سوارت بشم و این کار را می کنی . وقتی سوارش شدی یک نعره می زنه چهل کُره از زیر بُته ها بیرون میان . کاکل زری این کارها را کرد و اسب چهل کره را به خانه آورد. خاله ها دیدند که بچه ها باز هم سالم هستند . گفتند : خونه شما انار چهل غنچه میخواد . هرکس که به دنبال انار چهل غنچه می رفت دیو او را می کشت چون زیر درخت انار چهل غنچه دیو خوابیده بود . پسر کاکل زری اومد ماجرا را به خواهرش گفت . خواهرش گفت : میری سوار اسب می شی به باد می گی \" سلام راه انار چهل غنچه از کدوم وره\" نشونت می ده ، می رسی به در می گی \" راه انار چهل غنچه از کدوم وره\" به کلیدون می رسی می گی \"راه انار چهل غنچه از کدوم وره \" همه نشونت میدن، میری انار را می چینی و میایی . کاکل زری سوار اسب شد و رفت و از همه نشونی ها را پرسید تا اینکه رسید به کلیدون سلام کرد و در باز شد . رفت توی باغ دید زیر درخت انار ، دیو خوابیده . یواش یواش رفت انار را چید و سوار بر اسب شد . یک دفعه دیو از خواب بیدار شد گفت : کلیدون ، در را قفل کن نذار بره . کلیدون گفت : بره مال خودشه . دیو گفت : در ، بسته شو نذار بره ، گفت : بره مال خودشه .دیو گفت : باد بگیرش .گفت : بره مال خودشه . اومد رسید به خونه ، به خاله ها گفت : انار چهل غنچه آوردم . خاله ها دیدند هیچ بلایی نمی تونند سر این بچه بیارن، گفتن : خونه شما \"ماه دخترون \"می خواد . هر کس می رفت ماه دخترون را بیاره سنگ سیاه می شد . کاکل زری اومد به خواهرش گفت : این زنه می گه خونه شما ماه دخترون می خواد . دندون مرواری گفت : میری سوار بر اسب میشی پای کوه ماه دخترون میگی : ماه دخترون پای اسبم سیاه شد ، ماه دخترون اسبم سیاه شد ، ماه دخترون خودم و اسبم سیاه شدیم ، اون موقع ماه دخترون میاد بیرون . کاکل زری اومد پای کوه دید اونجا پر از سنگ سیاهه ، فهمید اینها آدمهایی بودن که اومدن ماه دخترون را ببینن که سنگ سیاه شدن. کاکل زری کارهایی را که خواهرش گفت کرد تا اینکه دید ماه دخترون از وسط کوه بیرون اومد . کاکل زری او را سوار بر اسب کرد و به خانه اومد . خاله ها دیدند بازهم این بچه ها سالم هستند . اومدن به پسر پادشاه ( که همان پدر بچه ها بود ) گفتند : یه دختر و پسر هستند که خیلی ثروتمندند و توی خانه شان اسب چهل کره دارن ، انار چهل غنچه دارن ، ماه دخترون دارن .... اگر اینها را نکشی پادشاه می شن . پسر پادشاه گفت امشب آنها را دعوت می کنم و در غذایشان زهر می ریزم . رفتند اونها را دعوت کردند. دندون مروارید به کاکل زری گفت : امشب وقتی رفتی مهمانی یک کلاه سرت بذار که اونها ندونن موهای تو زری است و یک چوب با یک گوپ ور میداری وقتی سفره پهن شد می گن : بسم الله ، تو میگی : چوب و گوپ و بسم الله . دست به غذا نمی زنی چون زهر توش کردن . باز میگن بسم الله ، و تو حرف قبلی را می زنی . رفتن مهمانی ، سفره پهن شد . پسر شاه گفت : بسم الله ، کاکل زری گفت : چوب و گوپ و بسم الله .پسر شاه ناراحت شد ، گفت : پسره نفهم چوب و گوپ هم مگه شام می خورن؟ کاکل زری گفت : مرتکه نفهم مگه آدم هم توله سگ به دنیا میاره ؟ بعد کلاهش را ور داشت . پسر پادشاه دید که کاکلش زری است ! دندون مرواری هم خندید ، پسر پادشاه دید که دندونش مروارید است و فهمید که خواهر های زنش دروغ گفتند ... دستور داد آنها را به دم اسب باد پا ببندند و توی صحرا روی زمین بکشند تا تکه تکه شوند . بعد مادرشان را هم از توی گچ درآوردند و به قصر آوردند و با هم زندگی کردند .\r\n"},{"id":2182,"category_id":2,"category_code":"s2","source_id":349,"title":"گاو وخوک","content":"مرد ثروتمندی به کشیشی می گوید:\r\nنمی دانم چرا مردم مرا خسیس می پندارند.\r\nکشیش گفت:\r\nبگذار حکایت کوتاهی از یک گاو و یک خوک برایت نقل کنم...\r\nخوک روزی به گاو گفت: مردم از طبیعت آرام و چشمان حزن انگیز تو به نیکی سخن می گویند و تصور می کنند تو خیلی بخشنده\r\nهستی. زیرا هر روز برایشان شیر و سرشیر می دهی.!!\r\nاما در مورد من چی؟…\r\nمن همه چیز خودم را به آنها می دهم از گوشت ران گرفته تا سینه ام را. حتی از موی بدن من برس کفش و ماهوت پاک کن درست\r\n\r\nمی دانی جواب گاو چه بود؟\r\n\r\nجوابش این بود:\r\nشاید علتش این باشد که\r\n“هر چه من می دهم در زمان حیاتم می دهم”\r\n"},{"id":2183,"category_id":2,"category_code":"s2","source_id":350,"title":"پدر وپسر","content":"\r\nپدری دست بر شانه پسر گذاشت و از او پرسید:تو میتوانی مرا بزنی یا من تورا؟ \r\nپسر جواب داد:من میزنم \r\nپدر ناباورانه دوباره سوال را تکرار کرد ولی باز همان جواب را شنید \r\nبا ناراحتی از کنار پسر رد شد بعد از چند قدم دوباره سوال را تکرار کرد شاید جوابی بهتر بشنود. \r\nپسرم من میزنم یا تو؟ \r\nاین بار پسر جواب داد شما میزنی....!! \r\nپدر گفت چرا دوبار اول این را نگفتی؟؟؟ \r\nپسر جواب داد تا وقتی دست شما روی شانه من بود عالم را حریف بودم ولی وقتی دست از شانه ام کشیدی قوتم را با خود بردی\r\n"},{"id":2184,"category_id":2,"category_code":"s2","source_id":351,"title":"ماجرای آقای گاو !","content":"در یک مدرسه راهنمایی دخترانه در منطقه محروم شهر خدمت می کردم و چند سالی بود که مدیر مدرسه شده بودم.\r\nقرار بود زنگ تفریح اول، پنج دقیقه دیگر نواخته شود و دانش آموزان به حیاط مدرسه بروند.\r\nهنوز دفتر مدرسه خلوت بود و هیاهوی دانش آموزان در حیاط و گفت وگوی همکاران در دفتر مدرسه، به هم نیامیخته بود.\r\nدر همین هنگام، مردی با ظاهری آراسته و سر و وضعی مرتب در دفتر مدرسه حاضر شد و خطاب به من گفت:\r\nبا خانم… دبیر کلاس دومی ها کار دارم و می خواهم درباره درس و انضباط فرزندم از او سؤال هایی بکنم.\r\nاز او خواستم خودش را معرفی کند. گفت:\r\nمن “گاو” هستم ! خانم دبیر بنده را می شناسند. بفرمایید گاو، ایشان متوجه می شوند.\r\nتعجب کردم و موضوع را با خانم دبیر که با نواخته شدن زنگ تفریح، وارد دفتر مدرسه شده بود، در میان گذاشتم.\r\nیکه خورد و گفت: ممکن است این آقا اختلال رفتار داشته باشد. یعنی چه گاو؟ من که چیزی نمی فهمم…\r\nاز او خواستم پیش پدر دانش آموز یاد شده برود و به وی گفتم:\r\nاصلاً به نظر نمی رسد اختلالی در رفتار این آقا وجود داشته باشد. حتی خیلی هم متشخص به نظر می رسد.\r\nخانم دبیر با اکراه پذیرفت و نزد پدر دانش آموز که در گوشه ای از دفتر نشسته بود، رفت.\r\nمرد آراسته، با احترام به خانم دبیر ما سلام داد و خودش را معرفی کرد: “من گاو هستم!”\r\n- خواهش می کنم، ولی…\r\n- شما بنده را به خوبی می شناسید.\r\nمن گاو هستم، پدر گوساله؛ همان دختر۱۳ ساله ای که شما دیروز در کلاس، او را به همین نام صدا زدید…\r\nدبیر ما به لکنت افتاد و گفت: آخه، می دونید…\r\n- بله، ممکن است واقعاً فرزندم مشکلی داشته باشد و من هم در این مورد به شما حق می دهم.\r\nولی بهتر بود مشکل انضباطی او را با من نیز در میان می گذاشتید.\r\nقطعاً من هم می توانستم اندکی به شما کمک کنم.\r\nخانم دبیر و پدر دانش آموز مدتی با هم صحبت کردند.\r\nگفت و شنود آنها طولانی، ولی توأم با صمیمیت و ادب بود. آن پدر، در خاتمه کارتی را به خانم دبیر ما داد و با خداحافظی از همه، مدرسه را ترک کرد.\r\nوقتی او رفت، کارت را با هم خواندیم.\r\nدر کنار مشخصاتی همچون نشانی و تلفن، روی آن نوشته شده بود:\r\nدکتر… عضو هیأت علمی دانشکده روانشناسی و علوم تربیتی دانشگاه… !\r\n"},{"id":2185,"category_id":2,"category_code":"s2","source_id":352,"title":"قدرت بخشش","content":"\r\nبانوى خردمندى در کوهستان سفر مى کرد که سنگ گران قیمتى را در جوى آبى پیدا کرد.\r\nروز بعد به مسافرى رسید که گرسنه بود.\r\nبانوى خردمند کیفش را باز کرد تا در غذایش با مسافر شریک شود.\r\nمسافر گرسنه، سنگ قیمتى را در کیف بانوى خردمند دید\r\nاز آن خوشش آمد و از او خواست که آن سنگ را به او بدهد.\r\nزن خردمند هم بى درنگ، سنگ را به او داد\r\nمسافر بسیار شادمان شد و از این که شانس به او روى کرده بود،\r\nاز خوشحالى سر از پا نمى شناخت.\r\nاو مى دانست که جواهر به قدرى با ارزش است که تا آخر عمر مى تواند\r\nراحت زندگى کند، ولى چند روز بعد، مرد مسافر به راه افتاد\r\nتا هرچه زودتر، بانوى خردمند را پیدا کند.\r\nبالاخره هنگامى که او را یافت، سنگ را پس داد و گفت:\r\n«خیلى فکر کردم. مى دانم این سنگ چقدر با ارزش است،\r\nاما آن را به تو پس مى دهم با این امید که چیزى ارزشمندتر از آن به من بدهى.\r\nاگر مى توانى، آن محبتی را به من بده که به تو قدرت داد این سنگ را به من ببخشى . . .\r\n"},{"id":2186,"category_id":2,"category_code":"s2","source_id":353,"title":"دختر زیبا و خواستگار پیر ! ","content":"روزگاری یک کشاورز در روستایی زندگی می کرد که باید پول زیادی را که از یک پیرمرد قرض گرفته بود، پس می داد.\r\nکشاورز دختر زیبایی داشت که خیلی ها آرزوی ازدواج با او را داشتند. وقتی پیرمرد طمعکار متوجه شد کشاورز نمی تواند پول او را پس بدهد، پیشهاد یک معامله کرد و گفت اگر با دختر کشاورز ازدواج کند بدهی او را می بخشد و دخترش از شنیدن این حرف به وحشت افتاد و پیرمرد کلاه بردار برای اینکه حسن نیت خود را نشان بدهد گفت : اصلا یک کاری می کنیم، من یک سنگریزه سفید و یک سنگریزه سیاه در کیسه ای خالی می اندازم، دختر تو باید با چشمان بسته یکی از این دو را بیرون بیاورد. اگر سنگریزه سیاه را بیرون آورد باید همسر من بشود و بدهی بخشیده می شود و اگر سنگریزه سفید را بیرون آورد لازم نیست که با من ازدواج کند و بدهی نیز بخشیده می شود، اما\r\nاگر او حاضر به انجام این کار نشود باید پدر به زندان برود.\r\nاین گفت و گو در جلوی خانه کشاورز انجام شد و زمین آنجا پر از سنگریزه بود. در همین حین پیرمرد خم شد و دو سنگریزه برداشت. دختر که چشمان تیزبینی داشت متوجه شد او دو سنگریزه سیاه از زمین برداشت و داخل کیسه انداخت. ولی چیزی نگفت !\r\nسپس پیرمرد از دخترک خواست که یکی از آنها را از کیسه بیرون بیاورد.\r\nدست خود را به داخل کیسه برد و یکی از آن دو سنگریزه را برداشت و به سرعت و با ناشی بازی، بدون اینکه سنگریزه دیده بشود، وانمود کرد که از دستش لغزیده و به زمین افتاده. پیدا کردن آن سنگریزه در بین انبوه سنگریزه های دیگر غیر ممکن بود.\r\nدر همین لحظه دخترک گفت : آه چقدر من دست و پا چلفتی هستم ! اما مهم نیست. اگر سنگریزه ای را که داخل کیسه است دربیاوریم معلوم می شود سنگریزه ای که از دست من افتاد چه رنگی بوده است... .\r\n\r\nو چون سنگریزه ای که در کیسه بود سیاه بود، پس باید طبق قرار، آن سنگریزه سفید باشد. آن پیرمرد هم نتوانست به حیله گری خود اعتراف کند و شرطی را که گذاشته بود به اجبار پذیرفت و دختر نیز تظاهر کرد که از این نتیجه حیرت کرده است.\r\n"},{"id":2187,"category_id":2,"category_code":"s2","source_id":354,"title":"همیشه شادباشید","content":"مردی که همسرش را از دست داده بود دختر سه ساله اش را بسیــار دوست می داشت دخترک به بیماری سختی مبتلا شد پدر به هر دری زد تا کودک سلامتی اش را دوباره بدست بیاورد، هرچه پول داشت برای درمان او خرج کرد ولی بیماری جان دخترک را گرفت و او مرد... پدر در خانه اش را بست و گوشه گیر شد. با هیچکس صحبت نمی کرد سرکار نمی رفت. دوستان و آشنایانش خیلی سعی کردند تا او را به زندگی عادی برگردانند ولی موفق نشدند. شبی پدر رویای عجیبی دید، دید که در بهشت است و صف منظمی از فرشتگان کوچک در جاده ای طلایی به سوی کاخی مجلل در حرکت هستند همه فرشته های کوچک در حال شادی بودنند . هر فرشته شمعی در دست داشت و شمع همه فرشتگان به جز یکی روشن بود مرد جلوتر رفت و دید فرشته ای که شمعش خاموش است، همان دختر خودش است پدر فرشته غمگینش را در آغوش گرفت و او را نوازش داد از او پرسید : دلبندم، چرا غمگینی؟ چرا شمع تو خاموش است؟ دخترک به پدرش گفت: باباجان، هر وقت شمع من روشن می شود، اشکهای تو آن را خاموش می کند و هر وقت تو دلتنگ می شوی، من هم غمگین می شوم هر وقت تو گوشه گیر می شوی من نیز گوشه گیر می شوم نمی توانم همانند بقیه شاد باشم . پدر در حالی که اشک در چشمانش حلقه زده بود، از خواب پرید. اشکهایش را پاک کرد، ناراحتی و غم را رها کرد و به زندگی عادی خود بازگشت. \r\nنتیجه اخلاقی : همیشه شادباشید \r\n"},{"id":2188,"category_id":2,"category_code":"s2","source_id":355,"title":"همه همسران من! ","content":"روزی، روزگاری پادشاهی 4 همسر داشت. او عاشق و شیفته همسر چهارمش بود. با دقت و ظرافت خاصی با او رفتار می کرد و او را با جامه های گران قیمت و فاخر می آراست و به او از بهترینها هدیه می کرد. همسر سومش را نیز بسیار دوست می داشت و به خاطر داشتنش به پادشاه همسایه فخر فروشی می کرد. اما همیشه می ترسید که مبادا او را ترک کند و نزد دیگری رود. همسر دومش زنی قابل اعتماد، مهربان، صبور و محتاط بود. هر گاه که این پادشاه با مشکلی مواجه می شد، فقط به او اعتماد می کرد و او نیز همسرش را در این مورد کمک می کرد. همسر اول پادشاه، شریکی وفادار و صادق بود که سهم بزرگی در حفظ و نگهداری ثروت و حکومت همسرش داشت. او پادشاه را از صمیم قلب دوست می داشت، اما پادشاه به ندرت متوجه این موضوع می شد. روزی پادشاه احساس بیماری کرد و خیلی زود دریافت که فرصت زیادی ندارد. او به زندگی پر تجملش می اندیشید و در عجب بود و با خود می گفت: «من 4 همسر دارم، اما الان که در حال مرگ هستم، تنها مانده ام.» بنابراین به همسر چهارمش رجوع کرد و به او گفت: «من از همه بیشتر عاشق تو بوده ام. تو را صاحب لباسهای فاخر کرده ام و بیشترین توجه من نسبت به تو بوده است. اکنون من در حال مرگ هستم، آیا با من همراه می شوی؟» او جواب داد: «به هیچ وجه!» و در حالی که چیز دیگری می گفت از کنار او گذشت. جوابش همچون کاردی در قلب پادشاه فرو رفت. پادشاه غمگین، از همسر سوم سئوال کرد و به او گفت: «در تمام طول زندگی به تو عشق ورزیده ام، اما حالا در حال مرگ هستم. آیا تو با من همراه میشوی؟» او جواب داد: «نه، زندگی خیلی خوب است و من بعد از مرگ تو دوباره ازدواج خواهم کرد.» قلب پادشاه فرو ریخت و بدنش سرد شد. بعد به سوی همسر دومش رفت و گفت: «من همیشه برای کمک نزد تو می آمدم و تو همیشه کنارم بودی. اکنون در حال مرگ هستم. آیا تو همراه من می آیی؟» او گفت: «متأسفم، در این مورد نمی توانم کمکی به تو بکنم، حداکثر کاری که بتوانم انجام دهم این است که تا سر مزار همراهت بیایم\"» جواب او همچون گلوله ای از آتش پادشاه را ویران کرد. ناگهان صدایی او را خواند: «من با تو خواهم آمد، همراهت هستم، فرقی نمی کند به کجا روی، با تو می آیم.» پادشاه نگاهی انداخت، همسر اولش بود. او به علت عدم توجه پادشاه و سوء تغذیه، بسیار نحیف شده بود. پادشاه با اندوهی فراوان گفت: «ای کاش زمانی که فرصت بود به تو بیشتر توجه می کردم.» \r\n\r\nشرح حکایت در حقیقت، همه ما در زندگی کاری خویش 4 همسر داریم. همسر چهارم ما سازمان ما است. بدون توجه به اینکه تا چه حد برایش زمان و امکانات صرف کرده ایم و به او پرداخته ایم، هنگام ترک سازمان و یا محل خدمت، ما را تنها می گذارد. همسر سوم ما، موقعیت ما است که بعد از ما به دیگران انتقال می یابد. همسر دوم ما، همکاران هستند. فرقی نمیکند چقدر با هم بوده ایم، بیشترین کاری که می توانند انجام دهند این است که ما را تا محل بعدی همراهی کنند. همسر اول ما عملکرد ما است. اغلب به دنبال ثروت، قدرت و خوشی از آن غفلت می نماییم. در صورتیکه تنها کسی است که همه جا همراهمان است. همین حالا احیائش کنید، بهبودش دهید و مراقبتش کنید .\r\n"},{"id":2189,"category_id":2,"category_code":"s2","source_id":356,"title":"قورباغه","content":"روزی از روزها گروهی از قورباغه های کوچیک تصمیم گرفتند که با هم مسابقه ی دو بدهند. هدف مسابقه رسیدن به نوک یک برج خیلی بلند بود.جمعیت زیادی برای دیدن مسابقه و تشویق قورباغه ها جمع شده بودند… \r\nو مسابقه شروع شد….\r\nراستش, کسی توی جمعیت باور نداشت که قورباغه های به این کوچیکی بتوانند به نوک برج برسند.شما می تونستید جمله هایی مثل اینها را بشنوید:”اوه,عجب کار مشکلی!!” ، “اونها هیچ وقت به نوک برج نمی رسند.” یا: “هیچ شانسی برای موفقیتشون نیست.برج خیلی بلند ه!”\r\nقورباغه های کوچیک یکی یکی شروع به افتادن کردند…\r\nبجز بعضی که هنوز با حرارت داشتند بالا وبالاتر می رفتند…\r\nجمعیت هنوز ادامه می داد,”خیلی مشکله!!!هیچ کس موفق نمی شه!”\r\nو تعداد بیشتری از قورباغه ها خسته می شدند و از ادامه دادن منصرف می شدند\r\n…\r\nولی فقط یکی به رفتن ادامه داد بالا, بالا و باز هم بالاتر….\r\nاین یکی نمی خواست منصرف بشه! بالاخره بقیه ازادامه ی بالا رفتن منصرف شدند.به جز اون قورباغه کوچولو که بعد از تلاش زیاد تنها کسی بود که به نوک رسید! بقیه ی قورباغه ها مشتاقانه می خواستند بدانند او چگونه این کار رو انجام داده؟\r\nاونا ازش پرسیدند که چطور قدرت رسیدن به نوک برج و موفق شدن رو پیدا کرده؟\r\nو مشخص شد که…\r\nبرنده ی مسابقه کر بوده!!!\r\nنتیجه ی اخلاقی این داستان اینه که:\r\nهیچ وقت به جملات منفی و مأیوس کننده ی دیگران گوش ندید. چون اونا زیبا ترین رویا ها و آرزوهای شما رو ازتون می گیرند . چیز هایی که از ته دلتون آرزوشون رو دارید! هیشه به قدرت کلمات فکر کنید.\r\nچون هر چیزی که می خونید یا می شنوید روی اعمال شما تأثیر میگذاره پس:\r\nهمیشه….\r\nمثبت فکر کنید!\r\nو بالاتر از اون کر بشید هر وقت کسی خواست به شما بگه که به آرزوهاتون نخواهید رسید!\r\nو هیشه باور داشته باشید:\r\nما همراه خدای خودم همه کار می تونیم بکنیم.\r\n"},{"id":2190,"category_id":2,"category_code":"s2","source_id":357,"title":"افتخار بزرگ","content":"\r\nپسر کوچولو به مادر خود گفت:مادر داری به کجا می روی؟\r\nمادر گفت:عزیزم بازیگری معروف که از محبوبیت زیادی برخوردار است\r\nبه شهر ما آمده است.این طلایی ترین فرصتی است که می توانم\r\nاو را ببینم وبا او حرف بزنم،خیلی زود برمیگردم.\r\nاگر او وقت آن را داشته باشد که با من حرف بزند چه محشری می شود.\r\nو در حالی که لبخندی حاکی از شادی به لب داشت با فرزندش خداحافظی کرد….\r\nحدود نیم ساعت بعد مادرش با عصبانیت به خانه برگشت.\r\nپسر به مادرش گفت:مادر چرا چهره ی پریشانی داری؟\r\nآیا بازیگر محبوبت را ملاقات کردی؟…\r\nمادر با لحنی از خستگی و عصبانیت گفت:من و جمعیت زیادی از مردم بسیار منتظر ماندیم اما به ما خبر رساندند که او نیم ساعت است که این شهر را ترک کرده است.ای کاش خدا شهرت و محبوبیتی را که به این بازیگر داده است به ما داده بود.کودک پس از شنیدن حرف های مادر به اتاق خود رفت و لباس های خود رابیرون آورد و گفت:مادر آماده شو با هم به جایی برویم من می توانم این آرزوی تو را برآورده کنم.\r\nاما مادر اعتنایی نکرد و گفت:این شوخی ها چیست او بیش از نیم ساعت است که این شهر را ترک کرده است.حرف های تو چه معنی ای میدهد؟\r\nپسر ملتمسانه گفت:مادرم خواهش می کنم به من اعتماد کن،فقط با من بیا.مادر نیز علیرغم میل باطنی خود درخواست فرزند خود را پذیرفت زیرا او را بسیار دوست می داشت.بنابراین آن دو به بیرون از خانه رفتند.\r\nپس از چندی قدم زدن پسر به مادرش گفت:رسیدیم.در حالی که به کلیسای بزرگ شهر اشاره می کرد.مادر که از این کار فرزندش بسیار دلخور شده بود با صدایی پر از خشم گفت:من به تو گفتم که الان وقت شوخی نیست.این رفتار تو اصلا زیبا نبود.\r\nکودک جواب داد:مادر تو در سخنان خود دقیقا این جمله را گفتی که ای کاش خدا شهرتی و محبوبیتی را که به این بازیگر داده است به ما داده بود پس آیا افتخاری از این بزرگ تر است که با کسی که این شهرت و محبوبیت را داده است نه آن کسی که آن را دریافت کرده است حرف بزنی؟\r\nآیا سخن گفتن با خدا لذت بخش تر از آن نیست که با آن بازیگر محبوب حرف بزنی؟وقتی خدا همیشه در دسترس ماست پس چه نیاز به بنده ی خدا.مادر هیچ نگفت و خاموش ماند.\r\n"},{"id":2191,"category_id":2,"category_code":"s2","source_id":358,"title":"وعده پادشاه","content":"پادشاهى در یک شب سرد زمستان از قصر خارج شد.\r\nهنگام بازگشت سرباز پیرى را دید که با لباسى اندک در سرما نگهبانى مى‌داد.\r\nاز او پرسید: آیا سردت نیست؟\r\nنگهبان پیر گفت: چرا اى پادشاه اما لباس گرم ندارم و مجبورم تحمل کنم.\r\nپادشاه گفت:من الان داخل قصر مى‌روم و مى‌گویم\r\nیکى از لباس‌هاى گرم مرا برایت بیاورند.\r\nنگهبان ذوق زده شد و از پادشاه تشکر کرد.\r\nاما پادشاه به محض ورود به داخل قصر وعده‌اش را فراموش کرد.\r\nصبح روز بعد جسد سرمازده پیرمرد را در حوالى قصر پیدا کردند\r\nدر حالى که در کنارش با خطى ناخوانا نوشته بود:\r\nاى پادشاه من هر شب با همین لباس کم سرما را تحمل مى‌کردم\r\nاما وعده لباس گرم تو مرا از پاى درآورد . . .\r\n"},{"id":2192,"category_id":2,"category_code":"s2","source_id":359,"title":"پیرمرد و دخترش","content":"دهقان پیر، با ناله می‌گفت: ارباب! آخر درد من یکی دو تا نیست\r\nبا وجود این همه بدبختی، نمی‌دانم دیگر خدا چرا با من لج کرده\r\nو چشم تنها دخترم را«چپ» آفریده است؟! دخترم همه چیز را دو تا می‌بیند.\r\nارباب پرخاش کرد و گفت: بدبخت! چهل سال است نان مرا زهر مار می‌کنی!\r\nمگر کور هستی، نمی‌بینی که چشم دختر من هم «چپ» است؟!\r\nدهقان گفت: چرا ارباب می‌بینم … اما … چیزی که هست،\r\nدختر شما همه‌ی این خوشبختی‌ها را «دوتا» می‌بیند\r\n… ولی دختر من، این همه بدبختی را … !\r\n"},{"id":2193,"category_id":2,"category_code":"s2","source_id":360,"title":"تاجر و باغ زیبا","content":"مردی تاجر در حیاط قصرش انواع مختلف درختان و گیاهان و گلها را کاشته\r\nو باغ بسیار زیبایی را به وجود آورده بود.\r\nهر روز بزرگترین سرگرمی و تفریح او گردش در باغ و لذت بردن از گل و گیاهان آن بود.\r\nتا این که یک روز به سفر رفت. در بازگشت، در اولین فرصت به دیدن باغش رفت.\r\nاما با دیدن آنجا، سر جایش خشکش زد…\r\nتمام درختان و گیاهان در حال خشک شدن بودند ،\r\nرو به درخت صنوبر که پیش از این بسیار سر سبز بود، کرد و از او پرسید که چه اتفاقی افتاده است؟\r\nدرخت به او پاسخ داد: من به درخت سیب نگاه می کردم و باخودم گفتم که من هرگز نمی توانم مثل او چنین میوه هایی زیبایی بار بیاورم و با این فکر چنان احساس نارحتی کردم که شروع به خشک شدن کردم…\r\nمرد بازرگان به نزدیک درخت سیب رفت، اما او نیز خشک شده بود…!\r\nعلت را پرسید و درخت سیب پاسخ داد: با نگاه به گل سرخ و احساس بوی خوش آن، به خودم گفتم که من هرگز چنین بوی خوشی از خود متصاعد نخواهم کرد و با این فکر شروع به خشک شدن کردم.\r\nاز آنجایی که بوته ی یک گل سرخ نیز خشک شده بود علت آن پرسیده شد، او چنین پاسخ داد: من حسرت درخت افرا را خوردم، چرا که من در پاییز نمی توانم گل بدهم. پس از خودم نا امید شدم و آهی بلند کشیدم. همین که این فکر به ذهنم خطور کرد، شروع به خشک شدن کردم.\r\nمرد در ادامه ی گردش خود در باغ متوجه گل بسیار زیبایی شد که در گوشه ای از باغ روییده بود.\r\nعلت شادابی اش را جویا شد. گل چنین پاسخ داد: ابتدا من هم شروع به خشک شدن کردم، چرا که هرگز عظمت درخت صنوبر را که در تمام طول سال سر سبزی خود را حفظ می کرد نداشتم، و از لطافت و خوش بویی گل سرخ نیز برخوردار نبودم، با خودم گفتم: اگر مرد تاجر که این قدر ثروتمند، قدرتمند و عاقل است و این باغ به این زیبایی را پرورش داده است می خواست چیزی دیگری جای من پرورش دهد، حتماً این کار را می کرد. بنابراین اگر او مرا پرورش داده است، حتماً می خواسته است که من وجود داشته باشم. پس از آن لحظه به بعد تصمیم گرفتم تا آنجا که می توانم زیباترین موجود باشم…\r\n"},{"id":2194,"category_id":2,"category_code":"s2","source_id":361,"title":"مرد خوشبخت","content":"\r\nپادشاهي پس از اينكه بيمار شد گفت: \r\n«نصف قلمرو پادشاهي ام را به کسي مي دهم که بتواند مرا معالجه کند». \r\nتمام آدم هاي دانا دور هم جمع شدند \r\nتا ببيند چطور مي شود شاه را معالجه کرد، \r\nاما هيچ يک ندانست. \r\nتنها يکي از مردان دانا گفت : \r\nکه فکر مي کند مي تواند شاه را معالجه کند. \r\nاگر يک آدم خوشبخت را پيدا کنيد، \r\nپيراهنش را برداريد \r\nو تن شاه کنيد، \r\nشاه معالجه مي شود. \r\nشاه پيک هايش را براي پيدا کردن يک آدم خوشبخت فرستاد. \r\nآن ها در سرتاسر مملکت سفر کردند \r\nولي نتوانستند آدم خوشبختي پيدا کنند.\r\nحتي يک نفر پيدا نشد که کاملا راضي باشد. \r\nآن که ثروت داشت، بيمار بود. \r\nآن که سالم بود در فقر دست و پا مي زد،\r\nيا اگر سالم و ثروتمند بود زندگي بدي داشت. \r\nيا اگر فرزندي داشت، فرزندانش بد بودند. \r\nخلاصه هر آدمي چيزي داشت که از آن گله و شکايت کند. \r\nآخرهاي يک شب، \r\nپسر شاه از کنار کلبه اي محقر و فقيرانه رد مي شد \r\nکه شنيد يک نفر دارد چيزهايي مي گويد. \r\n« شکر خدا که کارم را تمام کرده ام. \r\nسير و پر غذا خورده ام \r\nو مي توانم دراز بکشم \r\nو بخوابم! \r\nچه چيز ديگري مي توانم بخواهم؟» \r\nپسر شاه خوشحال شد \r\nو دستور داد که پيراهن مرد را بگيرند \r\nو پيش شاه بياورند \r\nو به مرد هم هر چقدر بخواهد بدهند. \r\nپيک ها براي بيرون آوردن پيراهن مرد توي کلبه رفتند، \r\nاما مرد خوشبخت آن قدر فقير بود که پيراهن نداشت!!!. \r\n"},{"id":2195,"category_id":2,"category_code":"s2","source_id":362,"title":"چاپلوسی ممنوع","content":"روزی روزگاری پیرزن فقیری توی زباله‌ها دنبال چیزی برای خوردن می‌گشت که چشمش به یک چراغ قدیمی افتاد. آن را برداشت و رویش دست کشید. می‌خواست ببیند اگر ارزش داشته باشد، آن را ببرد و بفروشد.\r\n\r\nدر همین موقع، دود سفیدی از چراغ بیرون آمد.\r\nپیرزن چراغ را پرت کرد؛ با ترس و تعجب عقب‌عقب رفت و دید که چند قدم آن طرف‌تر، یک غول بزرگ ظاهر شد. غول فوری تعظیم کرد و گفت: «نترس پیرزن! من غول مهربان چراغ جادو هستم. مگر قصه‌های جورواجوری را که برایم ساخته‌اند،‌ نشنیده‌ای؟ حالا یک آرزو کن تا آن را در یک چشم به هم زدن برایت برآورده کنم. امّا یادت باشد که فقط یک آرزو!\"\r\nپیرزن که به خاطر این خوش‌اقبالی توی پوستش نمی‌گنجید،‌ از جا پرید و با خوش‌حالی گفت‌: \"الهی فدات بشم مادر!\"\r\nامّا هنوز جمله ی بعدی را نگفته بود که فدای غول شد و نتوانست آرزویش را به زبان بیاورد.\r\nو مرگ او درس عبرتی شد برای آن‌ها که زیادی تعارف می‌کنند.\r\n"},{"id":2196,"category_id":2,"category_code":"s2","source_id":363,"title":"ارزش","content":"روزی دست پسر بچه ای که در خانه با گلدان کوچکی بازی می کرد، در آن گیر کرد و هر کاری کرد، نتوانست دستش را از گلدان خارج کند. به ناچار پدرش را به کمک طلبید. اما پدرش هم هر چه تلاش کرد نتوانستند دست پسر را از گلدان خارج کنند. پدر دیگر راضی شده بود به شکستن گلدان که تصادفا خیلی هم گرانقیمت بود، فکر کند. قبل از این کار به عنوان آخرین تلاش به پسرش گفت: دستت را باز کن، انگشت هایت را به هم بچسبان و آنها را مثل دست من جمع کن. آن وقت فکر می کنم دستت بیرون می آید. \r\nپسر گفت: \"می دانم اما نمی توانم این کار را بکنم.\" \r\nپدر که از این جواب پسرش شگفت زده شده بود پرسید: \"چرا نمی توانی؟\" \r\nپسر گفت: \"اگر این کار را بکنم سکه ای که در مشتم است، بیرون می افتد.\" شاید شما هم به ساده لوحی این پسر بخندید اما واقعیت این است که اگر دقت کنیم می بینیم همه ما در زندگی به بعضی چیزهای کم ارزش چنان می چسبیم که ارزش دارایی های پرارزشمان را فراموش می کنیم و در نتیجه آنها را از دست می دهیم\r\n(به خاطر بعضی از چیز ها خیلی از چیز ها را از دست داد)\r\n"},{"id":2197,"category_id":2,"category_code":"s2","source_id":364,"title":"ازدواج ","content":"پسر جوان و زیبارویی بود که فکر می کرد باید با زیباترین دختر جهان ازدواج کند.\r\nاوفکر می کرد به این ترتیب بچه هایش زیباترین بچه های روی زمین می شوند. \r\nپسر مدتی با این فکر در جستجوی همسر یکتایی برای خودش گشت. \r\nطولی نکشید که پسر با پیرمردی آشنا شد که سه دختر باهوش و زیبا داشت.\r\nپسر ازپیرمرد درخواست کرد که با یکی از دخترانش آشنا شود. \r\nپیرمرد جواب داد: هیچ یک ازدخترانم ازدواج نکرده اند و با هر کدام که می خواهید آشنا شوید. \r\nپسر خوشحال شد. دختر بزرگ پیرمرد را پسندید و باهم آشنا شدند.\r\nچند هفته بعد، پسرپیش پیرمرد رفت و با مِن و مِن گفت: آقا، دخترتان خیلی زیبا است، اما یک عیب کوچکدارد. متوجه نشدید؟! دخترتان کمی چاق است. \r\nپیرمرد حرفش را تایید کرد و آشنایی با دختر دومش را به پسر پیشنهاد داد.\r\nپسر با دختر دوم پیرمرد آشنا شد و به زودی با یکدیگر قرار ملاقات گذاشتند. \r\nاما چند هفته بعد پسر دوباره پیش پیرمرد رفت و گفت: دختر شما خیلی خوب است.\r\nاما به نظرم یک عیب کوچک دارد. متوجه نشدید؟! دخترتان کمی لوچ است. \r\nپیرمرد حرف او را تایید کرد و آشنایی با دختر سومش را به پسر پیشنهاد کرد.\r\n\r\nبه زودی پسر با دختر سوم پیرمرد دوست شد و با هم به تفریح رفتند. \r\nیک هفته بعد پسر پیش پیرمرد رفت و با هیجان گفت: دختر شما مثل یشمِ بی لک است.\r\nهمان کسی است که دنبالش می گشتم. اگر اجازه دهید، به رویایم برسم و با دختر سوم تان ازدواج کنم!\r\nچندی بعد پسر با دختر سوم پیرمرد ازدواج کرد. چند ماه بعد همسرش دختری به دنیاآورد.\r\nاما وقتی که پسر صورت بچه را دید، از وحشت در جایش میخکوب شد.\r\n\r\nاین زشت ترین بچه ای بود که به عمرش می دید. پسر بسیار غمگین شد و پیش پدر همسرش رفت و\r\nبا گِله گفت: چرا با این که هر دوی ما این قدر زیبا و خوش اندام هستیم، ولی بچه ما به این زشتی است؟\r\nپیرمرد جواب داد: دختر سوم من قبلا دختر بسیار خوبی بود.\r\nاما او هم یک عیب کوچکداشت. متوجه نشدی؟! \r\nاو قبل از آشنا شدن با تو حامله بود!!! \r\nهمگان را برای مدتی و برخی را برای همیشه می توان فریفت\r\nاما همگان را برای همیشه هرگز\r\nمواظب باشید فریب نخورید \r\nدر انتخاب ملاکهای ازدواج دقت کنید.\r\n"},{"id":2198,"category_id":2,"category_code":"s2","source_id":365,"title":"شراب گرانقیمت","content":"واعظی بر منبر می گفت: هرگاه بنده ای مست میرد مست دفن شود و مست سر از گور برآورد. خراسانیی در پای منبر بود گفت به خدا آن شرابی است که یک شیشه آن به صد دینار ارزد."},{"id":2199,"category_id":2,"category_code":"s2","source_id":366,"title":"نام آدم و حوا","content":"واعظی بر منبر می گفت هر که نام آدم و حوّا نوشته در خانه آویزد شیطان بدان خانه در نیاید. طلخک از پای منبر برخاست و گفت مولانا شیطان در بهشت در جوار خدا به نزد ایشان رفت و بفریفت. چگونه می شود که در خانه ی ما از اسم ایشان بپرهیزد؟"},{"id":2200,"category_id":2,"category_code":"s2","source_id":367,"title":"طلخک و سرمای زمستان","content":"سلطان محمود در زمستانی سخت به طلخک گفت که با این جامه ی یک لا در این سرما چه می کنی که من با این همه جامه می لرزم. گفت ای پادشاه تو نیز مانند من کن تا نلرزی. گفت مگر تو چه کرده ای؟ گفت هرچه جامه داشتم همه را در بر کرده ام."},{"id":2201,"category_id":2,"category_code":"s2","source_id":368,"title":"ماهی و یونس","content":"پدر جُحی سه ماهی بریان به خانه برد. جحی در خانه نبود. مادرش گفت این بخوریم پیش از آنکه جحی بیاید. چون سفره بنهادند جحی در زد. مادرش دو ماهی بزرگ در زیر تخت پنهان کرد و یکی کوچک با میان آورد. مگر جحی از شکاف در بدید. چون بنشستند پدرش از جحی پرسید که تو حکایت یونس پیغمبر شنیده ای؟ گفت نه اما از این ماهی بپرسم. سر پیش ماهی برد و از او پرسید و گوش بر دهان ماهی نهاد و گفت این ماهی می گوید من آن زمان کوچک بودم دو ماهی دیگر بزرگتر از من در زیر تخت اند از ایشان بپرس تا بگویند."},{"id":2202,"category_id":2,"category_code":"s2","source_id":369,"title":"چگونه جنگ شروع می شود ","content":"سلطان محمود از طلخک پرسید جنگ میان مردمان چون واقع شود؟ گفت نبینی و نخوری. سلطان گفت ای مردک چه گُه می خوری؟ گفت چنین باشد. یکی گهی می خورد و آن دیگر جوابی می دهد جنگ میان ایشان قائم می شود."},{"id":2203,"category_id":2,"category_code":"s2","source_id":370,"title":"چگونه می گذرانی؟ ","content":"اعرابیی را گفتند چگونه می گذرانی؟ گفت نه چنان که خداوند تعالی خواهد و نه چنان که شیطان خواهد و نه چنان که خود خواهم. گفتند چگونه؟ گفت از آن که خدای تعالی خواهد عابد باشم و چنان نیستم و شیطان خواهد که کافر باشم و چنان نیستم و خود خواهم که شاد و خوش روزی و دارای ثروت کافی باشم و چنان نیز نیستم."},{"id":2204,"category_id":2,"category_code":"s2","source_id":371,"title":"عیدی طلخک ","content":"از بهر روز عید پیش سلطان محمود خلعت هرکس تعیین می کردند. چون به طلخک رسید سلطان فرمود پالانی بیاورید و روز عید به وی دهید. چنان کردند. چون مردم خلعت بپوشیدند طلخک آن پالان بر دوش گرفت و به مجلس سلطان آمد و گفت ای بزرگان عنایت سلطان در حق بنده از آن جا معلوم کنید که شما را خلعت از خزانه فرمود دادن و جامه ی خاص از تن بدر کرده در من پوشانید."},{"id":2205,"category_id":2,"category_code":"s2","source_id":372,"title":"عمر مرغ","content":"مردی مرغی بریان بر سفرۀ یکی از بخیلان دید که دستی بدان دراز نشد و روز دیگر به سفره بازگشت. چون چند روز بر آن روش بگذشت مرد گفت عمر این مرغ پس از بسمل شدن درازتر از عمر او در دوران زندگی است."},{"id":2206,"category_id":2,"category_code":"s2","source_id":373,"title":"شباهت","content":"مردی را گفتند پسرت را به تو شباهتی نباشد. گفت: اگر همسایگان باری ما را رها کنند، فرزندانمان را به ما شباهتی خواهد افتادت."},{"id":2207,"category_id":2,"category_code":"s2","source_id":374,"title":"موسی(ع) یا عیسی(ع)؟","content":"یهودی از نصرانی پرسید: موسی برتر است یا عیسی؟ گفت: عیسی مردگان را زنده می کرد، ولی موسی مردی را بدید و او را به ضربت مشتی بیفکند و آن مرد بمرد؛ عیسی در گهواره سخن می گفت، اما موسی در چهل سالگی می‌گفت: خدایا! گره از زبانم بگشای تا سخنم را دریابند."},{"id":2208,"category_id":2,"category_code":"s2","source_id":375,"title":"گریه ی کودک","content":"مردی کودکی را دید که می گریست و هر چند مادرش او را نوازش می کرد، خاموش نمی‌شد. گفت: خاموش شو تا مادرت را به کار گیرم! مادر گفت: این طفل تا آنچه گویی نبیند به راست نشمارد و باور نکند."},{"id":2209,"category_id":2,"category_code":"s2","source_id":376,"title":"زن عرب","content":"عربی را از حال زنش پرسیدند. گفت زنده است؛ و تا زنده‌است همچنان مار گزنده است."},{"id":2210,"category_id":2,"category_code":"s2","source_id":377,"title":"صنعت پر سود","content":"پسرکی از حُمص (شهری است در سوریه) به بغداد شد و صنعت را پرسود یافت. مادرش او را برای مرمت آسیا به حمص خواند. پسر بدو نوشت که: گردش سرین در عراق، به از چرخش دستاس به حمص باشد."},{"id":2211,"category_id":2,"category_code":"s2","source_id":378,"title":"رای قاضی","content":"زنی نزد قاضی رفت و گفت: این شوی من حق مرا ضایع می‌سازد و حال آنکه من زنی جوانم. مرد گفت: من آنچه توانم کوتاهی نکنم. زن گفت: من به کم از پنج مرتبه راضی نباشم! مرد گفت: لاف نزنم که مرا بیش از سه مرتبه یارا نباشد! قاضی گفت: مرا حالی عجب افتاده است، هیچ دعوی بر من عرض نکنند مگر آنکه از کیسه من چیزی برود! باشد آن دو مرتبه دیگر را من بر گردن گیرم!!"},{"id":2212,"category_id":2,"category_code":"s2","source_id":379,"title":"نماز جمعه","content":"کسی مردی را دید که بر خری کُندرو نشسته. گفتش: کجا می‌روی؟ گفت: به نماز جمعه. گفت: ای نادان اینک سه شنبه باشد. گفت: اگر این خر شنبه‌ام به مسجد رساند نیکبخت باشم!"},{"id":2213,"category_id":2,"category_code":"s2","source_id":380,"title":"ندیدن به ز دیدن","content":"روباه را پرسیدند که در گریختن از سگ، چند حیله دانی؟ گفت: از صد فزون باشد؛ اما نیکوتر از همه اینست که من و او را با یکدیگر اتفاق دیدار نیفتد!"},{"id":2214,"category_id":2,"category_code":"s2","source_id":381,"title":"روباه یا سگ؟","content":"روباهی عربی را بگزید. افسونگر را بیاوردند. پرسید: کدام جانورت گزیده؟ گفت سگی، و شرم کرد بگوید روباهی. چون به افسون خواندن آغاز کرد گفتش چیزی هم از افسون روباه گزیدگی بدان درآمیز!"},{"id":2215,"category_id":2,"category_code":"s2","source_id":382,"title":"فاحشه ای در خم!","content":"مردی در خم نگریست و صورت خویش در آن بدید. مادر را بخواند و گفت: در خمره دزدی نهان است! مادر فراز آمد و در خم نگریست و گفت: آری، فاحشه‌ای نیز همراه دارد!"},{"id":2216,"category_id":2,"category_code":"s2","source_id":383,"title":"لگام اسب","content":"اسبی در مسابقه پیشی گرفت. مردی از شادی بانگ برداشت و به خودستایی پرداخت. کسی که در کنارش بود گفت: مگر این اسب از آن توست؟ گفت: نه! لیکن لگامش از من است."},{"id":2217,"category_id":2,"category_code":"s2","source_id":384,"title":"شیرین ترین","content":"مردی به زنی گفت: خواهم ترا بچشم تا دریابم تو شیرین‌تری یا زن من! گفت این حدیث از شویم پرس که وی من و او را چشیده باشد."},{"id":2218,"category_id":2,"category_code":"s2","source_id":385,"title":"التماس برای بادشکم","content":"مردی را علت قولنج افتاد. تمام شب از خدای درخواست که بادی از وی جدا شود. چون سحر رسید ناامید گشت و دست از زندگی شسته، تشهد می‌کرد، و می‌گفت بار خدایا بهشت نصیبم فرمای! یکی از حاضران گفت: ای نادان! از آغاز شب تا این زمان التماس بادی داشتی، پذیرفته نیامد. چگونه تقاضای بهشتی که وسعت آن به اندازه آسمانها و زمین است از تو مستجاب گردد؟"},{"id":2219,"category_id":2,"category_code":"s2","source_id":386,"title":"نقل وشراب","content":"ظریفی جوانی را دید که در مجلس باده‌گساری نقل بسیار با شراب می‌خورد گفت چنان که می‌بینم تو نقل می‌نوشی و شراب تنقل می‌کنی"},{"id":2220,"category_id":2,"category_code":"s2","source_id":387,"title":"تهی دست نخواهی رفت!","content":"مردی از کسی چیزی بخواست او را دشنام داد گفت مرا که چیزی ندهی چرا به د شنام رانی گفت خوش ندارم که تهی دست روانت کنم."},{"id":2221,"category_id":2,"category_code":"s2","source_id":388,"title":"قوم احمق","content":"مردی را که دعوی پیغمبری می‌کرد نزد معتصم آوردند متعصم گفت شهادت می‌دهم تو پیغمبر احمق هستی گفت آری از آنکه بر قوم شما مبعوث شده‌ام و هر پیامبری از نوع قوم خود باشد."},{"id":2222,"category_id":2,"category_code":"s2","source_id":389,"title":"خواب راست","content":"مردی حجاج را گفت دوش تو را به خواب چنان دیدم که اندر بهشتی گفت اگر خوابت راست باشد در آن جهان بیداد بیش از این جهان باشد."},{"id":2223,"category_id":2,"category_code":"s2","source_id":390,"title":"دام صیاد","content":"شیخی را گفتند خرقه خویش را بفروش گفت اگر صیاد دام خود را فروشد به چه چیز شکار کند."},{"id":2224,"category_id":2,"category_code":"s2","source_id":391,"title":"بهانه بقدر کفایت","content":"یکی اسبی از دوستی به عاریت خواست، گفت: «اسب دارم اما سیاه است». گفت: «مگر اسب سیاه را سوار نشاید شد؟» گفت:«چون نخواهم داد همینقدر بهانه بس است !»"},{"id":2225,"category_id":2,"category_code":"s2","source_id":392,"title":"دروغ بر خدا","content":"زشت رویی در آیینه مینگرست و می گفت:\r\nسپاس خدای را که مرا صورتی نیکو بداد\r\nغلامش ایستاده بود و این سخن می شنید و چون او بدر آمد،کسی بر در خانه او را از حال صاحبش پرسید\r\nگفت:در خانه نشسته و بر خدا دروغ می بندد.\r\n"},{"id":2226,"category_id":2,"category_code":"s2","source_id":393,"title":"موذن","content":"موذنی بانگ میگفت و می دوید\r\nپرسیدن که چرا میدوی\r\nگفت:میگویند که آواز تو از دور خوش است\r\nمیدوم تا آواز خود بشنوم\r\n"},{"id":2227,"category_id":2,"category_code":"s2","source_id":394,"title":"چاه","content":"مردی را پسر در چاه افتاد\r\nگفت:جان بابا ،جایی مرو تا من بروم طناب بیاورم و تو را بیرون کشم.\r\n"},{"id":2228,"category_id":2,"category_code":"s2","source_id":395,"title":"سلطان و خار کش","content":"سلطان محمود،پیری ضعیف را دید که پشتواره خار میکشد\r\nبر او رحمش آمد گفت:\r\nای پیر دو سه دینار زر میخواهی یا درازگوشی یا دو سه گوسفند یا باغی که به تو دهم،تا از این زحمت خلاصی یابی\r\nپیر گفت:زر بده تا در میان بندم و بر درازگوش بنشینم و گوسفندان در پیش گیرم و به باغ روم و به دولت تو در باقی عمر آنجا بیاسایم\r\nسلطان را خوش آمد و فرمود چنان کردند\r\n"},{"id":2229,"category_id":2,"category_code":"s2","source_id":396,"title":"چشم درد","content":"شخصی با دوستی گفت که مرا چشم درد میکند\r\nتدبیر چه باشد؟\r\nگفت مرا پارسال دندان درد میکرد،برکندم.\r\n"},{"id":2230,"category_id":2,"category_code":"s2","source_id":397,"title":"خطیب","content":"خطیبی را گفتند:\r\nمسلمانی چیست؟\r\nگفت:من مردی خطیبم،مرا با مسلمانی چکار\r\n"},{"id":2231,"category_id":2,"category_code":"s2","source_id":398,"title":"جستجوی دزد","content":"دزدی در خانه فقیری می جست\r\nفقیر از خواب بیدار شد و گفت:\r\nای مرد آنچه تو در تاریکی می جویی،ما در روز روشن می جوییم و نمی یابیم\r\n"},{"id":2232,"category_id":2,"category_code":"s2","source_id":399,"title":"گناه دزد","content":"استر طلحک را بدزدیدند.یکی گفت:گناه توست که از پاس آن اهمال ورزیدی.دیگری گفت:گناه آن کس مهم تر است که در طویله باز گذاشته است.طلحک گفت:در این صورت دزد را گناه نباشد.!!!!"},{"id":2233,"category_id":2,"category_code":"s2","source_id":400,"title":"دوستان شیطان","content":"شیطان را پرسیدند که کدام طایفه را دوست داری؟گفت:دلالان را.گفتند: چرا ؟ گفت: از بهر آن که من به سخن دروغ از ایشان راضی بودم،ایشان سوگند دروغ نیز بدان افزودند.!!!!"},{"id":2234,"category_id":2,"category_code":"s2","source_id":401,"title":"سرخ بزکم را یاد آمد!","content":"واعظی بر منبر سخن می گفت.کسی از مجلسیان سخت گریه می کرد.واعظ گفت:ای مجلسیان صدق از این مرد بیاموزید که این همه گریه به سوز می کند.مرد برخاست،گفت:مولانا،بزکی سرخ داشتم،ریشش به ریش تو می مانست که سقط شد.هر گاه تو ریش می جنبانی،مرا از آن بزک یاد می آید و گریه بر من غالب می شود.!"},{"id":2235,"category_id":2,"category_code":"s2","source_id":402,"title":"پلنگ ","content":"بازرگانی زنی زیبا داشت که زهره نام داشت عزم سفر کرد برای او لباسی سفید تهیه کردوکاسه ای نیل به خادم داد وگفت هر وقت زن حرکت ناشایستی کرد یک انگشت نیل بر لباس او بزن تا وقتی که آمدی من بدانم چقدر کارناشایست انجام داده. پس از مدتی به خادم نامه نوشت که\r\nچیزی نکند زهره که ننگی باشد بر جامه او زنیل رنگی باشد\r\nخادم نوشت \r\nگرآمدن خواجه درنگی باشد چون بازآید زهره پلنگی باشد\r\n"},{"id":2236,"category_id":2,"category_code":"s2","source_id":403,"title":"رفتار اعرابی","content":"اعرابیی را گفتند چگونه می گذرانی؟ گفت نه چنان که خداوند تعالی خواهد و نه چنان که شیطان خواهد و نه چنان که خود خواهم. گفتند چگونه؟ گفت از آن که خدای تعالی خواهد عابد باشم و چنان نیستم و شیطان خواهد که کافر باشم و چنان نیستم و خود خواهم که شاد و خوش روزی و دارای ثروت کافی باشم و چنان نیز نیستم."},{"id":2237,"category_id":2,"category_code":"s2","source_id":404,"title":"کله جوش","content":"شخصی را گفتند: شوربای گرم را چه نامند؟ گفت: کلّه‌جوش. گفتند چون سرد شود آن را چه خوانند؟ گفت: ما امانش ندهیم که سرد شود."},{"id":2238,"category_id":2,"category_code":"s2","source_id":405,"title":"سود سفر","content":"شخصی به سفر شد و زیان‌دیده بازگشت. او را گفتند: چه سود بردی؟ گفت: ما را از این سفر سودی جز کوتاه ساختن نماز نبود."},{"id":2239,"category_id":2,"category_code":"s2","source_id":406,"title":"طفل پنج روزه","content":"مردی زنی بگرفت، به روز پنجم فرزندی بزاد. مرد به بازار شد و لوح و دواتی بخرید. او را گفتند: این از بهر چه خریدی؟ گفت: طفلی که پنج روزه زایند سه روزه مکتبی شود."},{"id":2240,"category_id":2,"category_code":"s2","source_id":407,"title":"حلال و حرام","content":"مردی نزد ایاس‌بن معاویه آمد و گفت: اگر خرما خورم زیانیم باشد؟ گفت: نه. گفت: اگر سیاهدانه با نان خورم گناهی کرده‌ام؟ گفت: نه. گفت: اگر اندکی آب بر سر آن نوشم؟ گفت: منعی ندارد. گفت: شراب خرما نیز ترکیب همین چیزها باشد پس از چه رو حرامست؟ ایاس گفت: اگر بر تو اندکی خاک افشانند دردت آید؟ گفت: نه. گفت: اگر بر پیکرت آب پاشند، اندامیت بشکند؟ گفت: نه. گفت: اگر از آب و خاک خمیری کنند و در آفتاب نهند که خشک شود و بر سرت بکوبند چون باشد؟ گفت: آنم می‌کشد. ایاس گفت: آن نیز چون این باشد."},{"id":2241,"category_id":2,"category_code":"s2","source_id":408,"title":"شعبه ی مسح ریش","content":"مردی شعبی را از مسح ریش پرسید. گفت: انگشتان را در بن ریش کن. گفت: ترسم که آب به همه جا نرسد. گفت: اگر ازین ترسی از سر شب محاسن را بخیسان."},{"id":2242,"category_id":2,"category_code":"s2","source_id":409,"title":"تنبک","content":"پیری مست را به حضور هشام بن عبدالملک آوردند و با او شیشه‌ای شراب و عودی بود. هشام گفت: دنبک بر سرش بشکنید و به خوردن آن گندابه‌اش حدّ زنید. پیر بنشست و بگریست. او را گفتند: پیش از آنکه زنیمت گریستن چرا؟ گفت: مرا گریه از زدن نیست لیکن از آن گریم که شما عود را خوار داشتید و دنبک نامیدید و می ناب چون مُشک را گندابه نامیدید. هشام را خوش آمد و از او درگذشت."},{"id":2243,"category_id":2,"category_code":"s2","source_id":410,"title":"هندوانه فروش","content":"مردی بر هندوانه‌فروشی گذشت که بانگ می‌کرد: این همچون خرما و عسل است و شیرین‌تر از شکر است. مرد او را گفت: مرا بیماری است که او را هندوانه‌ی ترش علاج است از این میان یکی تُرش جدا کن. گفت: بخر و ببر و به بانگ من منگر که تمامی آنها از سرکه ترش‌تر باشد."},{"id":2244,"category_id":2,"category_code":"s2","source_id":411,"title":"شفاعت با سخن چینی","content":"آورده‌اند که مُزبِّد در مسجد خفته بود و کنار او مردی نماز می‌گزارد و در دعای خویش (به قنوت) می‌گفت: پروردگارا من نماز می‌کنم و این مرد خفته است. مُزبِّد او را گفت: هی فلان، از خود شفاعت کن ولی از ما سخن‌چینی مکن."},{"id":2245,"category_id":2,"category_code":"s2","source_id":412,"title":"نماز و زکات","content":"روزی مُزبِّد بر در مسجدی ایستاده بود. مؤدّن بانگ اذان برداشت که «حیّ‌علی الصلوة - بشتابید برای نماز» و مردم به انبوه گرد آمدند. پس مُزبِّد گفت: به خدا سوگند اگر گفتی: «حیّ‌علی الزکوة - بشتابید برای دادن زکات» از ده تن یک تن هم نیامدی."},{"id":2246,"category_id":2,"category_code":"s2","source_id":413,"title":"جنگ با شیر","content":"وردکی به جنگ شیر میرفت نعره می زد و بادی رها میکرد گفتند نعره چرا می زنی گفت تا شیر بترسد گفتند پس باد چرا رها می کنی گفت من نیز می ترسم."},{"id":2247,"category_id":2,"category_code":"s2","source_id":414,"title":"چشم مظلوم و روی ظالم!","content":"زنی چشمانی بغایت خوش و خوب داشت روز از شوهر شکایت به قاضی برد قاضی روسپی باره بود از چشمهای او خوشش آمد طمع در او بست و طرف او بگرفت. شوهر در یافت چادر از سرش در کشید .قاضی رویش بدید سخت متنفر شد گفت: بر خیز ای زنک چشم مظلومان داری و روی ظالمان!"},{"id":2248,"category_id":2,"category_code":"s2","source_id":415,"title":"در فکر بودم","content":"یکی در باغ خود رفت، دزدی را پشتواره پیاز در بسته دید. گفت: در این باغ چه کار داری؟ گفت: بر راه می‌گذشتم ناگاه باد مرا در باغ انداخت. گفت: چرا پیاز برکندی؟ گفت: باد مرا می‌ربود، دست در بند پیاز می‌زدم، از زمین برمی‌آمد. گفت: این هم قبول، ولی چه کسی جمع کرد و پشتواره بست؟ گفت: والله من نیز در این فکر بودم که آمدی."},{"id":2249,"category_id":2,"category_code":"s2","source_id":416,"title":"تازه‌آمده‌ام","content":"شخصی در خانه ی مردی خواست نماز بخواند. پرسید که قبله کدام طرف است؟ مرد گفت: من هنوز دو سال است که در این خانه ام. کجا دانم که قبله چون است."},{"id":2250,"category_id":2,"category_code":"s2","source_id":417,"title":"ثناگویی امیر دزدان...","content":"شاعری پیش امیر دزدان رفت و ثنایی بر او بگفت. فرمود تا جامه ازو برکنند و از ده به در کنند. مسکین، برهنه به سرما همی رفت... سگان در قفای وی افتادند. خواست تا سنگی بردارد و سگان را دفع کند. در زمین یخ گرفته بود. عاجز شد، گفت: این چه حرامزاده مردمانند، سگ را گشاده اند و سنگ را بسته! امیر از غرفه بدید و بشنید و بخندید، گفت: ای حکیم، از من چیزی بخواه. گفت جامه خود را می خواهم اگر انعام فرمایی. رضینا من نوالک بالرحیل.\r\nامیدوار بود آدمی به خیر کسان \r\nمرا به خیر تو امٌید نیست،شر مرسان\r\nسالار دزدان را رحمت بر وی آمد و جامه باز فرمود و قبا پوستینی، بر او مزید کرد و درمی چند.\r\n"},{"id":2251,"category_id":2,"category_code":"s2","source_id":418,"title":"زاهد","content":"پادشاهی را مهمی پیش آمد گفت اگر این حالت به مراد من برآید چندین درم دهم زاهدان را چون حاجتش برآمد و تشویش خاطرش برفت وفای نذرش به وجود شرط لازم آمد یکی را از بندگان خاص کیسه درم ‏داد تا صرف کند بر زاهدان گویند غلامی عاقل هشیار بود همه روز بگردید و شبانگه بازآمد و درم‌ها بوسه داد و پیش ملک بنهاد و گفت زاهدان را چندان که گردیدم نیافتم گفت این چه حکایت است آنچه من دانم در این ملک چهارصد زاهد است گفت ای خداوند جهان آن که زاهد است نمی‌ستاند و ‏آن که می‌ستاند زاهد نیست ملک بخندید و ندیمان را گفت چندان که مرا در ‏حق خداپرستان ارادت است و اقرار مرا این شوخ‌دیده را عداوت است و انکار و حق به جانب اوست. ‏\r\nزاهد کــه درم گـرفت و دینار \r\nزاهدتر از او یکی به دست آر\r\n"},{"id":2252,"category_id":2,"category_code":"s2","source_id":419,"title":"مروارید","content":"صدفی به صدف مجاورش گفت:\r\nدر درونم درد بزرگی احساس میکنم ،\r\nدردی سنگین که سخت مرا می رنجاند.\r\nصدف دیگر با راحتی و تکبر گفت: \r\nستایش از آن آسمان ها و دریاهاست.\r\nمن در درونم هیچ دردی احساس نمیکنم.\r\nظاهر و باطنم خوب و سلامت است.\r\nدر همان لحظه خرچنگ آبی از کنارشان عبور کرد و سخنانشان را شنید.\r\nبه آن که ظاهر و باطنش خوب و سلامت بود گفت:\r\nآری ! تو خوب و سلامت هستی اما دردی که همسایه ات در درونش احساس میکند مرواریدی است که زیبایی آن بی حد و اندازه است.\r\n"},{"id":2253,"category_id":2,"category_code":"s2","source_id":420,"title":"مترسک","content":"یک بار به مترسکی گفتم : لابد از ایستادن در این دشت خلوت خسته شده ای. \r\nگفت : لذت ترساندن عمیق و پایدار است من از آن خسته نمی شوم. \r\nدمی اندیشیدم و گفتم : درست است چون که من هم مزه این لذت را چشیده ام . \r\nگفت : فقط کسانی که تن شان از کاه پر شده باشد این لذت را می شناسند.\r\nآنگاه من از پیش او رفتم و ندانستم که که منظورش ستایش از من بود یا خوار کردن من. \r\nیک سال گذشت و مترسک فیلسوف شد.\r\nهنگامی که باز از کنار او میگذشتم دیدم دو کلاغ دارند زیر کلاهش لانه می سازند . \r\n"},{"id":2254,"category_id":2,"category_code":"s2","source_id":421,"title":"راههای رسیدن به خدا","content":"یک روز صبح «بودا» در بین شاگردانش نشسته بود که مردی به جمع آنان نزدیک شد و پرسید:\r\nآیا خدا وجود دارد؟\r\n«بودا» پاسخ داد:\r\nبله، خدا وجود دارد.\r\nبعد از ناهار سروکله‌ی مرد دیگری پیدا شد که پرسید:\r\nآیا خدا وجود دارد؟\r\n«بودا» پاسخ داد:\r\nنه، خدا وجود ندارد.\r\nاواخر روز مرد سومی همین سؤال را از «بودا» پرسید. پاسخ بودا به او چنین بود:\r\nخودت باید این را برای خودت روشن کنی.\r\nیکی از شاگردان گفت:\r\nاستاد این منطقی نیست. شما چطور می‌توانید به یک سؤال سه جواب بدهید؟\r\nبودا که به روشن‌بینی رسیده بود، پاسخ داد:\r\nچون آنان سه شخص مختلف بودند و هرکس از راه خودش به خدا می‌رسد: عده‌ای با اطمینان، عده‌ای با انکار و عده‌ای با تردید.\r\n"},{"id":2255,"category_id":2,"category_code":"s2","source_id":422,"title":"شک...","content":"مردي صبح از خواب بيدار شد و ديد تبرش ناپديد شده . شك كرد كه همسايه اش آن را دزديده باشد ، براي همين ، تمام روز اور ا زير نظر گرفت.\r\nمتوجه شد كه همسايه اش در دزدي مهارت دارد ، مثل يك دزد راه مي رود ، مثل دزدي كه مي خواهد چيزي را پنهان كند ، پچ پچ مي كند ،آن قدر از شكش مطمئن شد كه تصميم گرفت به خانه برگردد ، لباسش را عوض كند ، نزد قاضي برود و شكايت كند .\r\nاما همين كه وارد خانه شد ، تبرش را پيدا كرد . زنش آن را جابه جا كرده بود. مرد از خانه بيرون رفت و دوباره همسايه اش را زير نظر گرفت و دريافت كه او مثل يك آدم شريف راه مي رود ، حرف مي زند ، و رفتار مي كند .\r\n"},{"id":2256,"category_id":2,"category_code":"s2","source_id":423,"title":"راه درست","content":"روزی،گوساله ای باید از جنگل بکری می گذشت تا به چراگاهش برسد.گوساله ی بی فکری بود و راه پر پیچ و خم و پر فراز و نشیبی برای خود باز کرد.\r\nروز بعد،سگی که از آن جا می گذشت،از همان راه استفاده کرد و از جنگل گذشت.مدتی بعد،گوساله راهنمای گله،آن راه را باز دید و گله اش را وادار کرد از آن جا عبور کنند.\r\nمدتی بعد،انسان ها هم از همین راه استفاده کردند:می آمدند و می رفتند،به راست و چپ می پیچیدند،بالا می رفتند و پایین می آمدند،شکوه می کردند و آزار می دیدند و حق هم داشتند.اما هیچ کس سعی نکرد راه جدید باز کند.\r\nمدتی بعد،آن کوه راه،خیابانی شد.حیوانات بیچاره زیر بارهای سنگین،از پا می افتادند و مجبور بودند راهی که می توانستند در سی دقیقه طی کنند،سه ساعته بروند،مجبور بودند که همان راهی را بپیمایند که گوساله ای گشوده بود.\r\nسال ها گذشت و آن خیابان،جاده ی اصلی یک روستا شد،و بعد شد خیابان اصلی یک شهر.همه از مسیر این خیابان شکایت داشتند،مسیر بسیار بدی بود.\r\nدر همین حال،جنگل پیر و خردمند می خندید و می دید که انسان ها دوست دارند مانند کوران،راهی را که قبلا باز شده،طی کنند،و هرگز از خود نپرسند که آیا راه بهتری وجود دارد یا نه؟\r\n"},{"id":2257,"category_id":2,"category_code":"s2","source_id":424,"title":"تعصب یا وفاداری","content":"در صحرا میوه کم بود . خداوند یکی از پیامبران را فراخواند و گفت : « هر کس تنها می تواند یک میوه در روز بخورد »\r\nاین قانون نسل ها برقرار بود ، و محیط زیست آن منطقه حفظ شد . دانه های میوه بر زمین افتاد و درختان جدید رویید . مدتی بعد ،‌ آن جا منطقه ی حاصل خیزی شد و حسادت شهر های اطراف را بر انگیخت . اما هنوز هم مردم هر روز فقط یک میوه می خوردند و به دستوری که پیامبر باستانی به اجدادشان داده بود ، وفادار بودند . اما علاوه بر آن نمی گذاشتند اهالی شهر ها و روستا های همسایه هم از میوه ها استفاده کنند . این فقط باعث می شد که میوه ها روی زمین بریزند و بپوسند .. \r\nخداوند پیامبر دیگری را فراخواند و گفت :« بگذارید هرچه میوه می خواهند بخورند و میوه ها را با همسایگان خود قسمت کنند .» پیامبر با پیام تازه به شهر آمد . اما سنگسارش کردند ، چرا که آن رسم قدیمی ، در جسم و روح مردم ریشه دوانیده بود و نمی شد راحت تغییرش داد . \r\nکم کم جوانان آن منطقه از خود می پرسیدند این رسم بدوی از کجا آ مده . اما نمی شد رسوم بسیار کهن را زیر سؤال برد ، بنابراین تصمیم گرفتند مذهب شان را رها کنند . بدین ترتیب ، می توانستند هر چه می خواهند ، بخورند و بقیه را به نیازمندان بدهد . تنها کسانی که خود را قدیس می دانستند ، به آیین قدیمی وفادار ماندند . اما در حقیقت ، آن ها نمی فهمیدند که دنیا عوض شده و باید همراه با دنیا تغییر کنند. \r\n"},{"id":2258,"category_id":2,"category_code":"s2","source_id":425,"title":"درخت مشکلات","content":"نجار،یک روز کاری دیگر را هم به پایان برد.آخر هفته بود و تصمیم گرفت دوستی را برای صرف نوشیدنی به خانه اش دعوت کند.\r\nموقعی که نجار و دوستش به خانه رسیدند،قبل از ورود،نجار چند دقیقه در سکوت جلو درختی در باغچه ایستاد.بعد با دو دستش،شاخه های درخت را گرفت.\r\nچهره اش بی درنگ تغییر کرد.خندان وارد خانه شد،همسر و فرزندانش به استقبالش آمدند،برای فرزندانش قصه گفت،و بعد با دوستش به ایوان رفتند تا نوشیدنی بنوشند.\r\nاز آن جا می توانستند درخت را ببینند.دوستش دیگر نتوانست جلو کنجکاوی اش را بگیر،و دلیل این رفتار نجار را پرسید.\r\nنجار گفت:«آه،این درخت مشکلات من است.موقع کار،مشکلات فراوانی پیش می آید،اما این مشکلات،مال من است و ربطی هم به همسر و فرزندانم ندارد.وقتی به خانه می رسم،مشکلاتم را به شاخه های آن درخت می آویزم.روز بعد،وقتی می خواهم سر کار بروم،دوباره آن ها را از روی شاخه برمی دارم.جالب این است که وقتی صبح به سراغ درخت می روم تا مشکلاتم را بردارم،خیلی از مشکلات،دیگر آن جا نیستند،و بقیه هم خیلی سبک شده اند.»\r\n"},{"id":2259,"category_id":2,"category_code":"s2","source_id":426,"title":"دشتی پر از گل سرخ","content":"یک حکیم سالخورده‌ی چینی از دشتی پر از برف رد می‌شد که به زنی برخورد که گریه می‌کرد. حکیم پرسید:\r\n- شما چرا گریه می‌کنید؟\r\n- چون به زندگی‌ام فکر می‌کنم، به جوانی‌ام، به آن چهره‌ی زیبایی که در آینه می‌دیدم و مردی که دوستش داشتم. این از رحمت خدا به دور است که به من توانایی به خاطر آوردن گذشته را داده است. او می‌دانست که من بهار زندگی‌ام را به خاطر می‌آورم و گریه می‌کنم.\r\nحکیم در آن دشت پر برف ایستاد و به نقطه‌ای خیره شد و به فکر فرو رفت. عاقبت، گریه‌ی زن بند آمد. او پرسید:\r\n- شما در آن‌جا چه می‌بینید؟\r\nحکیم پاسخ داد:\r\n- دشتی پر از گل سرخ. خداوند وقتی به من توانایی به یاد آوردن را داد، نسبت به من لطف داشت. می‌دانست که من در زمستان همیشه می‌توانم بهار را به خاطر بیاورم و لبخند بزنم.\r\n"},{"id":2260,"category_id":2,"category_code":"s2","source_id":427,"title":"میخواهم خودم باشم","content":"در باغ دیوانه خانه ای قدم می زدم که جوانی را سرگرم خواندن کتاب فلسفه ای دیدم. \r\nمنش و سلامت رفتارش- با بیماران دیگر تناسبی نداشت.کنارش نشستم و پرسیدم:\r\n\"اینجا چه می کنی ؟\"\r\nبا تعجب نگاهم کرد. اما دید که من از پزشکان نیستم. پاسخ داد:\" خیلی ساده پدرم که وکیل ممتازی بود.می خواست راه او را دنبال کنم. عمویم که شرکت بازرگانی بزرگی داشت . دوست داشت از الگوی او پیروی کنم. مادرم دوست داشت تصویری از پدر محبوبش باشم .\r\nخواهرم همیشه شوهرش را به عنوان الگوی یک مرد موفق مثال می زد.\r\nبرادرم سعی می کرد مرا طوری پرورش بدهد که مثل خودش ورزشکاری عالی بشوم.\r\nمکثی کرد و دوباره ادامه داد:\r\n\"در مورد معلم هایم در مدرسه -استاد پیانو- و معلم انگلیسی ام هم همین طور شد. همه اعتقاد داشتند که خودشان بهترین الگویند . هیچ کدام آنطور به من نگاه نمی کردند که باید به یک انسان نگاه کرد... طوری به من نگاه می کردند که انگار در آیینه نگاه می کنند. \r\nبنابراین تصمیم گرفتم خودم را در این آسایشگاه بستری کنم. اینجا دست کم می توانم خودم باشم.\"\r\n"},{"id":2261,"category_id":2,"category_code":"s2","source_id":428,"title":"شکر نعمت","content":"يكى، در پيش بزرگى از فقر خود شكايت مى‏كرد و سخت مى‏ناليد . گفت: خواهى كه ده هزار درهم داشته باشى و چشم نداشته باشى؟ گفت: البته كه نه . دو چشم خود را با همه دنيا عوض نمى‏كنم. \r\nگفت: عقلت را با ده هزار درهم، معاوضه مى‏كنى؟ \r\nگفت: نه . \r\nگفت: گوش ودست و پاى خود را چطور؟ \r\nگفت: هرگز .\r\nگفت: پس هم اكنون خداوند، صدها هزار درهم در دامان تو گذاشته است . باز شكايت دارى و گله مى‏كنى؟!بلكه تو حاضر نخواهى بود كه حال خويش را با حال بسيارى از مردمان عوض كنى و خود را خوش‏تر و خوش بخت‏تر از بسيارى از انسان‏هاى اطراف خود مى‏بينى . پس آنچه تو را داده‏اند، بسى بيش‏تر از آن است كه ديگران را داده‏اند و تو هنوز شكر اين همه را به جاى نياورده، خواهان نعمت بيش‏ترى هستى!\r\n"},{"id":2262,"category_id":2,"category_code":"s2","source_id":429,"title":"سفر کوتاه!","content":"پدر بزرگم میگفت:‍‌«زندگی عجیب کوتاه است.حالا که گذشته را بیاد می آورم،زندگی به نظرم چنان فشرده می آید که مثلا نمی فهمم چطور ممکن است جوانی تصمیم بگیرد با اسبش به دهکده ی بعدی برود،امانترسد که مبادا-قطع نظر از اتفاقات بد-مدت زمان همین زندگی عادی و خوش و خرم،کفایت چنین سفری را نکند.» "},{"id":2263,"category_id":2,"category_code":"s2","source_id":430,"title":"بزرگترین درس زندگی","content":"ترس و وحشت زیردریایی را در برگرفته بود. من آن‌چنان ترسیده بودم که به سختی نفس می‌کشیدم. مرتباً به خود می‌گفتم این مرگ است! مرگ. با وجود اینکه همه‌ی دستگاه‌های خنک کننده و بادبزن‌های برقی را از کار انداخته بودیم و دما به بیش از صد درجه رسیده بود، باز هم می‌لرزیدم و عرق سرد از سر و صورتم جاری بود و با همه‌ی تلاشی که می‌کردم قادر نبودم از به‌هم خوردن دندان‌هایم جلوگیری کنم. من درچنین شرایطی بودم که یکباره حمله قطع شد. گویا تمام ذخایر کشتی مین‌انداز تمام شده بود و ترجیح داده بود که حمله را متوقف کند و آنجا را ترک کند. آن پانزده ساعت که مورد حمله قرار گرفته بودیم، برایم 15 ‏میلیون سال طول کشید. تمام خاطرات گذشته و کارهایی را که ‏مرتکب شده بودم مقابل چشمانم مجسم می‌کردم. مثلاً قبل از اینکه به ارتش ملحق شوم، کارمند بانک بودم و همیشه از حقوق کم، کار زیاد و پیشرفت‌های کوچک و محدود نگران بودم. ناراحت از اینکه قادر نبودم بنا به سلیقه وُ میل خود زندگی کنم، چرا قادر به خریدن یک اتومبیل نبودم، چرا نمی‌توانستم برای زنم لباسی گران‌قیمت تهیه کنم؟ و بدتر از همه اخلاق بد و خشن رئیسم، وضع موجود را برایم طاقت‌فرسا کرده بود. \r\n‏همه‌ی این ماجراها مثل فیلم از مقابل چشمانم می‌گذشت. به خاطر می‌آوردم که چطور شب‌ها خسته و عصبی به خانه می‌رفتم و به خاطر کوچک‌ترین مسئله‌ای با زنم بگومگو می‌کردم. یا هر وقت روبروی آینه قرار می‌گرفتم، آن زخم کوچک روی صورتم که بر اثر تصادف با اتومبیل به جا مانده بود، چگونه باعث ناراحتی‌ام می‌شد و غمگینم می‌کرد. \r\n‏قبل از این ماجرا همه‌ی این مسائل برایم بسیار پررنگ و با اهمیت بود، اما وقتی در اعماق اقیانوس با مرگ دست و پنجه نرم می‌کردم، به خودم قول دادم که اگر از این مهلکه جان سالم به دربردم و بار دیگر چشمم به خورشید و یا ماه و ستارگان افتاد، دیگر مجالی به نگرانی ندهم و هیچ‌گاه نگران این‌گونه مسائل بی‌اهمیت نباشم. هرگز! هرگز! هرگز!!! \r\n‏بله در آن پانزده ساعت پرمخاطره بسیار بیشتر از آن چهار سالی که در دانشگاه سیکاکیوز مشغول تحصیل بودم و کتاب‌های زیادی را مطالعه کرده بودم، درس زندگی را آموختم!\r\n"},{"id":2264,"category_id":2,"category_code":"s2","source_id":431,"title":"گرگ و گوسفند","content":"روزي بود، روزگاري بود. گوسفند سياهي هم بود. روزي گوسفند همان‌طوري سرش زير بود و داشت براي خودش مي‌چريد، يكدفعه سرش را بلند كرد و ديد، اي دل غافل از چوپان و گلّه خبري نيست و گرگ گرسنه‌اي دارد مي‌آيد طرفش. چشم‌هاي گرگ دو كاسه‌ي خون بود.\r\nگوسفند گفت: سلام عليكم.\r\nگرگ دندان‌هايش را به هم ساييد و گفت: سلام و زهر مار! تو اين‌جا چكار مي‌كني؟ مگر نمي‌داني اين كوه‌ها ارث باباي من است؟ الانه تو را مي‌خورم.\r\nگوسفند ديد بدجوري گير كرده و بايد كلكي جور بكند و در برود. اين بود كه گفت: راستش من باور نمي‌كنم اين كوه‌ها مال پدر تو باشند. آخر مي‌داني من خيلي ديرباورم. اگر راست مي‌گويي برويم سر اجاق (زيارتگاه)، تو دست به قبر بزن و قسم بخور تا من باور كنم. البته آن موقع مي‌تواني مرا بخوري.\r\nگرگ پيش خودش گفت: عجب احمقي گير آورده‌ام. مي‌روم قسم مي‌خورم بعد تكه پاره‌اش مي‌كنم و مي‌خورم.\r\nدوتايي آمدند تا رسيدند زير درختي كه سگ گلّه در آنجا خوابيده بود و خواب هفت تا پادشاه را مي‌ديد. گوسفند به گرگ گفت: اجاق اين‌جاست. حالا مي‌تواني قسم بخوري.\r\nگرگ تا دستش را به درخت زد كه قسم بخورد، سگ از خواب پريد و گلويش را گرفت.\r\n"},{"id":2265,"category_id":2,"category_code":"s2","source_id":432,"title":"پرنده ای به رسالت مبعوث شد","content":"خداوند گفت : دیگر پیامبری مبعوث نخواهم فرستاد ، ان گونه که شما انتظار دارید اما جهان هرگز بی پیامبر نخواهد ماند.\r\nوآنگاه پرنده ای را به رسالت مبعوث کرد. \r\nپرنده آوازی خواند که در هر نغمه اش خدا بود عده ای به او گرویدند و ایمان آوردند.\r\nوخدا گفت اگر بدانید حتی با آواز پرنده ای می توان رستگار شد.\r\nخدا رسولی از آسمان فرستاد . باران نام او بود همین که باران ، باریدن گرفت آنان که اشک را می شناختند رسالت او را دریافتند پس بی درنگ توبه کردند و روح شان را زیر بارش بی دریغ خدا شستند .\r\nخدا گفت : اگر بدانید با رسول باران هم می توان به پاکی رسید.\r\nخداوند پیغامبر باد را فرستاد تا روزی بیم دهد و روزی بشارت . پس باد روزی توفان شد و روزی نسیم و آنان که پیام او را فهمیدند روزی در خوف و روزی در رجا زیستند . \r\nخداوند گفت : آن که خبر باد را می فهمد قلبش در بیم و امید می لرزد . قلب مومن این چنین است . \r\nخدا گلی را از خاک برانگیخت تا معاد را معنا کند . \r\nو گل چنان از رستخیز گفت که هر از آن پس هر مومنی گلی که دید رستاخیز را به یاد آورد . \r\nخدا گفت : اگر بفهمید تنها با گلی قیامت خواهد شد . \r\nخداوند یکی از هزاران نامش را به دریا گفت . دریا بی درنگ قیام کرد و چنان به سجده افتاد که هیچ از هزارموج او باقی نماند . مردم تماشا می کردند عده ای پیام را دانستند پس قیام کردند و چنان به سجده افتادند که هیچ از آنها باقی نماند . \r\nخدا گفت : ان که به پیغمبر آبها اقتدا کند به بهشت خواهد رفت . \r\nو یاد دارم که فرشته ای به من گفت : جهان آکنده از فرستاده و پیغمبر مرسل است ، اما همیشه کافری هست تا بارش باران را انکار کند و با گل بجنگد ، تا پرنده را دروغگو بخواند و باد را مجنون و دریا را ساحر . اما هم امروز ایمان بیاور که پیغمبر آب و رسول باران و فرستاده باد برای ایمان آوردن تو کافی است.\r\n"},{"id":2266,"category_id":2,"category_code":"s2","source_id":433,"title":"به او اعتماد کن...","content":"مردی ثروتمند وجود داشت که همیشه پر از اضطراب و دلواپسی بود. با اینکه از همه ثروتهای دنیا بهره مند بود،هیچ گاه شاد نبود.او خدمتکاری داشت که ایمان درونش موج می زد. روزی خدمتکار وقتی دید مرد تا حد مرگ نگران است به او گفت:\r\n((ارباب،آیا حقیقت دارد که خداوندپیش از بدنیا آمدن شما جهان را اداره می کرد؟))\r\nاو پاسخ داد:((بله))\r\nخدمتکار پرسید:\r\n((آیا درست است که خداوند پس از آنکه شما دنیا را ترک کردید آنرا همچنان اداره می کند؟))\r\nارباب دوباره پاسخ داد:((بله))\r\nخدمتکار گفت:\r\n((پس چطور است به خدا اجازه بدهید وقتی شما در این دنیا هستید او آنرا ادره کند؟))\r\n"},{"id":2267,"category_id":2,"category_code":"s2","source_id":434,"title":"رنج یا موهبت","content":"۱.آهنگری با وجود رنجهای متعدد و بیماری اش عمیقا به خدا عشق می ورزید. روزری یکی از دوستانش که اعتقادی به خدا نداشت،از او پرسید:\r\n((تو چگونه می توانی خدایی را که رنج و بیماری نصیبت می کند، را دوست داشته باشی؟))\r\nآهنگر سر به زیر اورد و گفت:\r\nوقتی که میخواهم وسیله آهنی بسازم،یک تکه آهن را در کوره قرار می دهم.سپس آنرا روی سندان می گذارم و می کوبم تا به شکل دلخواه درآید.اگر به صورت دلخواهم درآمد،می دانم که وسیله مفیدی خواهد بود،اگر نه آنرا کنار میگذارم.\r\nهمین موصوع باعث شده است که همیشه به درگاه خدا دعا کنم که خدایا ، مرا در کوره های رنج قرار ده ،اما کنار نگذار...\r\n"},{"id":2268,"category_id":2,"category_code":"s2","source_id":435,"title":"توکل...","content":"زنی که در حومه شهر زندگی می کرد می خواست خانه و اثاثیه اش را بفروشد. زمستان بود و چنان برف سنگینی باریده بود که تقریبا محال بود که هیچ ماشین یا کامیونی بتواند تا در خانه اش برسد. منتها چون از خدا خواسته بودکه اثاثیه اش را به کسی که خدا می خواست و به قیمتی که خدا صلاح می دانست برایش بفروشد ، از ظواهر امر دل نگران نبود. اثاثیه اش را برق انداخت و آماده فروش وسط اتاق گذاشت . وقتی مرا دید گفت : حتی از پنجره به بیرون نگاه نکردم تا انبوه برف را ببینم یا سوز سرما را احساس کنم. تنها به وعده های خدا توکل کردم و بس!\r\nمردم نیز به گونه ای معجزه آسا اتومبیل خود را تا در خانه اش رساندند و نه تنها اثاثیه خانه ، حتی خود خانه نیز بی آنکه کارمزدی به هیچ بنگاه معاملات ملکی پرداخت شود به فروش رفت.\r\n"},{"id":2269,"category_id":2,"category_code":"s2","source_id":436,"title":"دزدیدن و دزدیده شدن!","content":"شهري بود که همة اهالي آن دزد بودند. شبها پس از صرف شام، هرکس دسته کليد بزرگ و فانوس را برمي داشت و از خانه بيرون ميزد؛ براي دستبرد زدن به خانة يک همسايه.حوالي سحر با دست پر به خانه برمي گشت، به خانة خودش که آنرا هم دزد زده بود. \r\nبه اين ترتيب، همه در کنار هم به خوبي و خوشي زندگي ميکردند؛ چون هرکس از ديگري مي دزديد و او هم متقابلاً از ديگري، تا آنجا که آخرين نفر از اولي مي دزديد. \r\nدادو ستدهاي تجاري و به طور کلي خريد و فروش هم در اين شهر به همين منوال صورت مي گرفت؛ هم از جانب خريدارها و هم از جانب فروشنده ها. دولت هم به سهم خود سعي مي کرد حق و حساب بيشتري از اهالي بگيرد و آنها را تيغ بزند و اهالي هم به سهم خود نهايت سعي و کوشش خودشان را مي کردند که سر دولت را شيره بمالند و نم پس ندهند و چيزي از آن بالا بکشند؛ به اين ترتيب در اين شهر زندگي به آرامي سپري مي شد. \r\nنه کسي خيلي ثروتمند بود و نه کسي خيلي فقير و درمانده. روزي، چطورش را نمي دانيم؛ مرد درستکاري گذرش به شهر افتاد و آنجا را براي اقامت انتخاب کرد. \r\nشبها به جاي اينکه با دسته کليد و فانوس دور کوچه ها راه بيفتد براي دزدي، شامش را که مي خورد، سيگاري دود مي کرد و شروع مي کرد به خواندن رمان. دزدها مي امدند؛ چراغ خانه را روشن مي ديدند و راهشان را کج مي کردند و ميرفتند. \r\nاوضاع از اين قرار بود تا اينکه اهالي، احساس وظيفه کردند که به اين تازه وارد توضيح بدهند که گرچه خودش اهل اين کارها نيست، ولي حق ندارد مزاحم کار ديگران بشود. \r\nهرشب که در خانه مي ماند، معنيش اين بود که خانواده اي سر بي شام زمين مي گذارد و روز بعد هم چيزي براي خوردن ندارد. بدين ترتيب، مرد درستکار در برابر چنين استدلالي چه حرفي براي گفتن مي توانست داشته باشد؟ بنابراين پس از غروب آفتاب، او هم از خانه بيرون ميزد و همانطور که از او خواسته بودند، حوالي صبح برمي گشت؛ ولي دست به دزدي نميزد. آخر او فردي بود درستکار و اهل اينکارها نبود. \r\nمي رفت روي پل شهر مي ايستاد و مدتها به جريان آب رودخانه نگاه مي کرد و بعد به خانه برمي گشت و مي ديد که خانه اش مورد دستبرد قرار گرفته است. \r\nدر کمتر از 1 هفته، مرد درستکار دار و ندارد خود را از دست داد؛ چيزي براي خوردن نداشت و خانه اش هم که لخت شده بود. ولي مشکلي اين نبود. \r\nچرا که اين وضعيت البته تقصير خود او بود. نه! مشکل چيز ديگري بود. قضيه از اين قرار بود که اين آدم با اين رفتارش، حال همه را گرفته بود! او اجازه داده بود دار و ندارش را بدزدند بي آنکه خودش دست به مال کسي دراز کند. به اين ترتيب، هر شب يک نفر بود که پس از سرقت شبانه از خانة ديگري، وقتي صبح به خانة خودش وارد ميشد، ميديد خانه و اموالش دست نخورده است؛ خانه اي که مرد درستکار بايد به آن دستبرد ميزد. \r\nبه هر حال بعد از مدتي به تدريج، آنهايي که شبهاي بيشتري خانه شان را دزد نميزد رفته رفته اوضاعشان از بقيه بهتر شد و مال و منالي به هم مي زدند و برعکس، کساني که دفعات بيشتري به خانة مرد درستکار (که حالا ديگر البته از هر چيز به درد نخوري خالي شده بود) دستبرد ميزدند، دست خالي به خانه برميگشتند و وضعشان روزبه روز بدتر ميشد و خود را فقيرتر ميافتند. \r\nبه اين ترتيب، آن عده اي که موقعيت ماليشان بهتر شده بود، مانند مرد درستکار،اين عادت را پيشه کردند که شبها پس از صرف شام، بروند روي پل چوبي و جريان آب رودخانه را تماشا کنند.. اين ماجرا، وضعيت آشفتة شهر را آشفته تر ميکرد؛ چون معنيش اين بود که باز افراد بيشتري از اهالي ثروتمندتر و بقيه فقيرتر ميشدند. \r\nبه تدريج، آنهايي که وضعشان خوب شده بود و به گردش و تفريح روي پل روي آوردند، متوچه شدند که اگر به اين وضع ادامه بدهند، به زودي ثروتشان ته ميکشد و به اين فکر افتادند که \"چطور است به عده اي از اين فقيرها پول بدهيم که شبها به جاي ما هم بروند دزدي\". \r\nقراردادها بسته شد، دستمزدها تعيين و پورسانتهاي هر طرف را هم مشخص کردند: آنها البته هنوز دزد بودند و در همين قرار و مدارها هم سعي ميکردند سر هم کلاه بگذارند و هر کدام از طرفين به نحوي از ديگري چيزي بالا ميکشيد و آن ديگري هم از .... . اما همانطور که رسم اينگونه قراردادهاست، آنها که پولدارتر بودند و ثروتمندتر و تهيدستها عموماً فقيرتر ميشدند. عده اي هم آنقدر ثروتمند شدند که ديگر براي ثروتمند ماندن، نه نياز به دزدي مستقيم داشتند و نه اينکه کسي برايشان دزدي کند. ولي مشکل اينجا بود که اگر دست از دزدي ميکشيدند، فقير ميشدند؛ چون فقيرها در هر حال از آنها ميدزديدند. فکري به خاطرشان رسيد؛ آمدند و فقيرترين آدمها را استخدام کردند تا اموالشان را در مقابل ديگر فقيرها حفاظت کنند، ادارة پليس برپا شد و زندانها ساخته شد. \r\nبه اين ترتيب، چند سالي از آمدن مرد درستکار به شهر نگذشته بود که مردم ديگر از دزديدن و دزديده شدن حرفي به ميان نمياوردند. صحبتها حالا ديگر فقط از دارا و ندار بود؛ اما در واقع هنوز همه دزد بودند. تنها فرد درستکار، همان مرد اولي بود که ما نفهميديم براي چه به آن شهر آمد و کمي بعد هم از گرسنگي مرد.\r\n"},{"id":2270,"category_id":2,"category_code":"s2","source_id":437,"title":"بازی","content":"یک روز بزرگان شهر دیدند که ضرورتی وجود ندارد که همه چیز ممنوع باشد و جارچی‌ها را روانة کوچه و بازار کردند تا به مردم اطلاع بدهند که می‌توانند هر کاری دلشان می‌خواهد بکنند….\r\nشهری بود که در آن، همه چیز ممنوع بود.\r\nو چون تنها چیزی که ممنوع نبود بازی الک دولک بود، اهالی ‌شهر هر روز به صحراهای اطراف می‌رفتند و اوقات خود را با باری الک دولک می‌گذراندند.\r\nو چون قوانین ممنوعیت نه یکباره بلکه به تدریج و همیشه با دلایل کافی وضع شده بودند، کسی دلیلی برای گلایه و شکایت نداشت و اهالی مشکلی هم برای سازگاری با این قوانین نداشتند.\r\nسال ها گذشت. یک روز بزرگان شهر دیدند که ضرورتی وجود ندارد که همه چیز ممنوع باشد و جارچی‌ها را روانة کوچه و بازار کردند تا به مردم اطلاع بدهند که می‌توانند هر کاری دلشان می‌خواهد بکنند.\r\nجارچی ها برای رساندن این خبر به مردم، به مراکز تجمع اهالی شهر رفتند و با صدای بلند به مردم گفتند:”آهای مردم! آهای … ! بدانید و آگاه باشید که از حالا به بعد هیچ کاری ممنوع نیست.”\r\nمردم که دور جارچی ها جمع شده بودند، پس از شنیدن اطلاعیه، پراکنده شدند و بازی الک دولک شان را از سر گرفتند.\r\nجارچی ها دوباره اعلام کردند: “می‌فهمید! شما حالا آزاد هستید که هر کاری دلتان می‌خواهد، بکنید.”\r\nاهالی جواب دادند: “خب! ما داریم الک دولک بازی می‌کنیم.”\r\nجارچی ها کارهای جالب و مفید متعددی را به یادشان آوردند که آنها قبلاً انجام می‌دادند و حالا دوباره می‌توانستند به آن بپردازند.\r\nولی اهالی گوش نکردند و همچنان به بازی الک دولک شان ادامه داند؛ بدون لحظه‌ای درنگ.\r\nجارچی ها که دیدند تلاش شان بی‌نتیجه است، رفتند که به اُمرا اطلاع دهند.\r\nاُمرا گفتند: ”کاری ندارد! الک دولک را ممنوع می‌کنیم.”\r\nآن وقت بود که مردم دست به شورش زدند و همة امرای شهر را کشتند و بی‌درنگ برگشتند و بازی الک دولک را از سر گرفتند.\r\n"},{"id":2271,"category_id":2,"category_code":"s2","source_id":438,"title":"دعای چوپان","content":"چوپانی بود که بیش‌تر از دونه‌هایِ شن ساحل دریا گوسفند داشت. باوجوداین، از ترس اینکه مبادا یکی از اونا بمیره، دل تو دلش نبود. زمستون، طولانی بود و چوپان، کاری نداشت جز اینکه دست به دامن ماه‌های سال بشه. \r\n‏«ای دسامبر، با من بساز! ای ژانویه، حیوونامو از سرما نکش! ای فوریه، اگه باهام مهربون باشی، همیشه چاکرت خواهم بود!» \r\n‏ماه‌ها داشتند دعاهای اونو گوش می‌دادند و از اون جایی که درمقابل هر ابراز لطفی حساس هستند، اونارو اجابت می‌کردند. نه بارون فرستادند، نه تگرگ، نه مرض حیوانا‏ت. گوسفندها به چریدن در طول زمستون ادامه دادند و حتی ‏سرما هم نخوردند. \r\n‏ماه مارس هم که عجیب و غریب‌ترین ماه ازنظر آب و هواست، گذشت و ‏مساعد هم گذشت. آخرین روز ماه فرا رسید و چوپان، دیگه از چیزی ترس نداشت. ماه آوریل و بهار هم اومد و گله، سالم موند. بنابراین، لحن التماس‌آمیز چوپان قطع شد و شروع کرد به رجز خوندن و پررویی: «آهای مارس! آهای مارس! تو که گله‌هارو می‌ترسونی، فکر می‌کنی کی‌رو ترسوندی؟ بره‌ّهارو؟ اوهوی مارس، من دیگه نمی‌ترسم! بهار اومده. دیگه نمی‌تونی کاریم کنی! ای مارس زپرتی، دیگه می‌تونی گورتو از این ده گم کنی و بری.» \r\n‏مارس با شنیدن حرف‌های اون نمک‌نشناس که جرأت می‌کرد این دری‌وری‌هارو بگه، احساس کرد که خونش به جوش اومده. رنجیده خاطر به خونه‌ی برادرش آوریل دوئید و بهش گفت: «ای برادر آوریل، سه‌روزتو به من قرض بده تا چوپونو تنبیه کنم که دیگه از این غلطا نکنه!»\r\n‏آوریل که برادرش مارس رو خیلی دوست داشت، سه‌روزشو بهش قرض داد. مارس قبل از هرکاری، دورتادور دنیا چرخید، بادها، توفان‌ها و طاعون‌هارو که د‏رگردش بودند، جمع کرد و همه‌رو سرِ گله‌ی چوپونه خالی کرد. روز اول، گوسفندهای نر و ماده‌ای که خیلی قوی نبود‏ند، مردند. روز د‏وم، نوبت به بره‌ّها رسید. روز سوم، یه حیوون زنده تو گله نموند و برای چوپون، فقط چشماش موند که گریه کنه.\r\n"},{"id":2272,"category_id":2,"category_code":"s2","source_id":439,"title":"فشار قبر","content":"به رسول خدا صلى الله عليه و آله خبر دادند كه سعد بن معاذ فوت كرده . پيغمبر صلى الله عليه و آله با اصحابشان از جاى برخاسته ، حركت كردند. با دستور حضرت - در حالى كه خود نظارت مى فرمودند - سعد را غسل دادند.\r\nپس از انجام مراسم غسل و كفن ، او را در تابوت گذاشته و براى دفن حركت دادند.\r\nدر تشييع جنازه او، پيغمبر صلى الله عليه و آله پابرهنه و بدون عبا حركت مى كرد. گاهى طرف چپ و گاهى طرف راست تابوت را مى گرفت ، تا نزديكى قبر سعد رسيدند. حضرت خود داخل قبر شدند و او را در لحد گذاشتند و دستور دادند سنگ و آجر و وسايل ديگر را بياورند! سپس با دست مبارك خود، لحد را ساختند و خاك بر او ريختند و در آن خللى ديدند آنرا بر طرف كردند و پس از آن فرمودند:\r\n- من مى دانم اين قبر به زودى كهنه و فرسوده خواهد شد، لكن خداوند دوست دارد هر كارى كه بنده اش انجام مى دهد محكم باشد.\r\nدر اين هنگام ، مادر سعد كنار قبر آمد و گفت :\r\n- سعد! بهشت بر تو گوارا باد!\r\nرسول خدا صلى الله عليه و آله فرمود:\r\n- مادر سعد! ساكت باش ! با اين جزم و يقين از جانب خداوند حرف نزن ! اكنون سعد گرفتار فشار قبر است و از اين امر آزرده مى باشد.\r\nآن گاه از قبرستان برگشتند.\r\nمردم كه همراه پيغمبر صلى الله عليه و آله بودند، عرض كردند:\r\nيا رسول الله ! كارهايى كه براى سعد انجام داديد نسبت به هيچ كس ‍ ديگرى تاكنون انجام نداده بوديد: شما با پاى برهنه و بدون عبا جنازه او را تشييع فرموديد.\r\nرسول خدا فرمود:\r\nملائكه نيز بدون عبا و كفش بودند. از آنان پيروى كردم .\r\nعرض كردند:\r\nگاهى طرف راست و گاهى طرف چپ تابوت را مى گرفتيد!\r\nحضرت فرمود:\r\nچون دستم در دست جبرئيل بود، هر طرف را او مى گرفت من هم مى گرفتم !\r\nعرض كردند:\r\n- يا رسول الله صلى الله عليه و آله بر جنازه سعد نماز خوانديد و با دست مباركتان او را در قبر گذاشتيد و قبرش را با دست خود درست كرديد، باز مى فرماييد سعد را فشار قبر گرفت ؟\r\nحضرت فرمود:\r\n- آرى ، سعد در خانه بداخلاق بود، فشار قبر به خاطر همين است...\r\n"},{"id":2273,"category_id":2,"category_code":"s2","source_id":440,"title":"مردی که زن شد!","content":"حضرت امام جعفر صادق صلوات اللّه علیه حكایت نموده است: \r\nروزى امام حسن مجتبى علیه السلام در جمعى از اقشار مختلف مردم حضور داشت ، كه یكى از افراد آن مجلس گفت :\r\nیابن رسول اللّه ! شما كه این قدر قدرت دارید و مى توانید با دعا معاویه را نابود كنید و زمین عراق و شام را جابه جا نمائید؛ و حتّى كارى كنید كه زن تبدیل به مرد شود؛ و یا مرد، زن گردد، چرا این همه ظلم هاى معاویه را تحمّل كرده و سكوت مى نمایید؟!\r\nناگاه یكى از دوستان معاویه كه در آن جمع حاضر بود؛ با حالت تمسخر و توهین گفت : این شخص - یعنى ؛ امام حسن مجتبى علیه السلام - كارى نمى تواند انجام دهد، چون او توان چنین كارهایى را ندارد.\r\nدر همین حال حضرت به آن دوست معاویه كه از اهالى شام بود خطاب كرد و فرمود: تو خجالت نمى كشى كه در بین مردها نشسته اى ، بلند شو و جاى دیگر بنشین .\r\nامام صادق علیه السلام در ادامه فرمایش خود افزود: ناگهان مرد شامى متوجّه شد كه به هیئت زنان در آمده است ؛ و دیگر علامت مردى در او نیست .\r\nسپس امام حسن مجتبى علیه السلام به آن مرد شامى كه تبدیل به زن شد، فرمود: اینك همسرت به جاى تو مرد گردید؛ و او با تو همبستر مى شود و تو یك فرزند خنثى آبستن خواهى شد.\r\nچند روزى پس از گذشت از این ماجرا، هر دوى آن مرد و زن شامى نزد امام حسن مجتبى علیه السلام آمدند و از كردار و رفتار خود پشیمان شده و توبه كردند.\r\nو حضرت در حقّ آنها دعا كرد و از خداوند متعال، براى آنان درخواست مغفرت نمود؛ و هر دوى آنها به دعاى حضرت، به حالت اوّلشان باز گشتند.\r\n"},{"id":2274,"category_id":2,"category_code":"s2","source_id":441,"title":"ادعای مرد فاسق!","content":"مسافري در شهر بلخ جماعتي را ديد كه مردي زنده را در تابوت انداخته و به سوي گورستان مي‌برند و آن بيچاره مرتب داد و فرياد مي‌زند و خدا و پيغمبر را به شهادت مي‌گيرد كه والله، بالله من زنده‌ام! چطور مي‌خواهيد مرا به خاك بسپاريد؟\r\nاما چند ملا كه پشت سر تابوت هستند، بي توجه به حال و احوال او رو به مردم كرده ومي‌گويند: پدرسوخته ي ملعون دروغ مي‌‌گويد. مُرده.\r\nمسافر حيرت زده حكايت را پرسيد. گفتند: اين مرد فاسق و تاجري ثروتمند و بدون وارث است. چند مدت پيش كه به سفر رفته بود، چهار شاهد عادل خداشناس در محضر قاضي بلخ شهادت دادند كه ُمرده و قاضي نيز به مرگ او گواهي داد. پس يكي از مقدسين شهر زنش را گرفت و يكي ديگر اموالش را تصاحب كرد. حالا بعد از مرگ برگشته و ادعاي حيات مي كند. حال آنكه ادعاي مردي فاسق در برابر گواهي چهار عادل خداشناس مسموع و مقبول نمي‌افتد. اين است كه به حكم قاضي به قبرستانش مي‌بريم، زيرا كه دفن ميّت واجب است و معطل نهادن جنازه شرعا جايزنيست.\r\n"},{"id":2275,"category_id":2,"category_code":"s2","source_id":442,"title":"عدل","content":"اسب درشکه‌ای توی جوی پهنی افتاده بود و قلم دست و کاسه زانویش خرد شده بود. آشکارا دیده می‌شد که استخوان قلم یک دستش از زیر پوست حنایی‌اش جابجا شده و از آن خون آمده بود. کاسه زانوی دست دیگرش به کلی از بند جدا شده بود و به چند رگ و ریشه که تا آخرین مرحله وفاداری‌‌اش را به جسم او از دست نداده بود گیر بود.سم یک دستش _آنکه از قلم شکسته بود _ به طرف خارج برگشته بود و نعل براق ساییده‌ای که به سه دانه میخ گیر بود روی آن دیده می‌شد.\r\nآب جو یخ بسته بود و تنها حرارت تن اسب یخ‌های اطراف بدنش را آب کرده بود. تمام بدنش توی آب گل آلود خونینی افتاده بود. پی در پی نفس می‌زد. پره‌های بینیش باز و بسته می شد. نصف زبانش از لای دندان‌های کلید شده‌اش بیرون زده بود. دور دهنش کف خون‌آلودی دیده می‌شد. یالش به طور حزن‌انگیزی روی پیشانیش افتاده بود و دو سپور و یک عمله راهگذر که لباس سربازی بی سردوشی تنش بود و کلاه خدمت بی‌آفتاب گردان به سر داشت می خواستند آن را از جو بیرون بیاورند.\r\nیکی از سپورها که حنای تندی بسته بود گفت:\r\nمن دمبشو می‌گیرم و شما هر کدامتون یه پاشو بگیرین و یه هو از زمین بلندش می‌کنیم. انوخت نه اینه که حیوون طاقت درد نداره و نمی تونه دساشو رو زمین بذاره یه هو خیز ور می‌دارد. انوخت شما جلدی پاشو ول دین منم دمبشو ول می‌دم. رو سه تا پاش می تونه بند شه دیگه. اون دسش خیلی نشکسه. چطوره که مرغ روی دو پا وایمیسه این نمی‌تونه رو سه پا واسه؟\r\nیک آقایی که کیف قهوه‌ای زیر بغلش بود و عینک رنگی زده بود گفت:\r\n- مگر می‌شود حیوان را اینطور بیرون آورد؟ شما‌ها باید چند نفر بشید و تمام هیکل بلندش کنید و بذاریدش تو پیاده‌رو.\r\nیکی از تماشاچی‌ها که دست بچه خردسالی را در دست داشت با اعتراض گفت:\r\n- این زبون بسته دیگه واسه صاحباش پول نمی‌شه. باید به یه گلوله کلکشو کند.\r\nبعد رویش را کرد به پاسبان مفلوکی که کنار پیاده‌رو ایستاده بود و لبو می خورد و گفت:\r\n- آژدان سرکار که تپونچه دارین چرا اینو راحتش نمی کنین؟ حیوون خیلی رنج می‌بره.\r\nپاسبان همانطور که یک طرف لپش از لبویی که تو دهنش بود باد کرده بود با تمسخر جواب داد:\r\n- زکی قربان آقا! گلوله اولنده که مال اسب نیس و مال دزه دومنده حالو اومدیم و ما اینو همینطور که می‌فرمایین راحتش کردیم به روز قیومت و سوال جواب اون دنیاشم کاری نداریم فردا جواب دولتو چی بدیم؟ آخه از من لاکردار نمی‌پرسن که تو گلولتو چیکارش کردی؟\r\nسید عمامه به سری که پوستین مندرسی روی دوشش بوی گفت:\r\n- ای بابا حیوون با کیش نیس. خدا را خوش نمی‌یاد بکشندش. فردا خوب می‌شه. دواش یه فندق مومیاییه.\r\nتماشاچی روزنامه به دستی که تازه رسیده بود پرسید:\r\n- مگه چطور شده؟\r\nیک مرد چپقی جواب داد:\r\n- و الله من اهل این محل نیستم. من رهگذرم.\r\nلبو فروش سرسوکی همانطور که با چاقوی بی دسته‌اش برای مشتری لبو پوست می‌کند جواب داد:\r\n- هیچی اتول بهش خورده سقط شده. زبون بسته از سحر تا حالا همین جا تو آب افتاده جون می‌کنه. هیشکی به فکرش نیس. اینو... بعد حرفش را قعط کرد و به یک مشتری گفت:\r\nیه قرون!... و آن وقت فریاد زد:\r\nقند بی کپن دارم ! سیری یک قرون می‌دم.\r\nباز همان مرد روزنامه به دست پرسید :\r\n- حالا صاحب نداره؟\r\nمرد کت چرمی قلچماقی که ریخت شوفر ها را داشت و شال سبزی دور گردنش بود جواب داد:\r\n- چطور صاحب نداره. مگه بی صاحبم می‌شه؟ پوسش خودش دس کم پونزده تومن می‌ارزه. درشکه چیش تا همین حالا اینجا بود; به نظر رفت درشکشو بذاره برگرده.\r\nپسربچه ای که دستش تو دست آن مرد بود سرش را بلند کرد و پرسید:\r\n- بابا جون درشکه چیش درشکشو با چی برده برسونه مگه نه اسبش مرده؟\r\nیک آقای عینکی خوش لباس پرسید:\r\n- فقط دستاش خرد شده؟\r\nهمان مرد قلچماق که ریخت شوفر ها را داشت و شال سبزی دور گردنش بود جواب داد:\r\n- درشکه‌چیش می‌گفت دندهاشم خرد شده.\r\nبخار تنکی از سوراخ های بینی اسب بیرون می‌آمد. از تمام بدنش بخار بلند می‌شد. دنده هایش از زیر پوستش دیده می‌شد. روی کفلش جای یک پنج انگشت گل خشک شده داغ خورده بود. روی گردن و چند جای دیگر بدنش هم گلی بود. بعضی جاهای پوست بدنش می‌پرید. بدنش به شدت می‌لرزید. ابدا ناله نمی‌کرد. قیافه‌اش آرام و بی التماس بود. قیافه یک اسب سالم را داشت و با چشمان گشاد و بی اشک به مردم نگاه می‌کرد. \r\n"},{"id":2276,"category_id":2,"category_code":"s2","source_id":443,"title":"قفس","content":"لب جو، نزدیک قفس ، گودالی بود پر از خون دلمه شدهء یخ بسته که پر مرغ و شلغم گندیده و ته سیگار و کله و پاهای بریدهء مرغ و پهن اسب توش افتاده بود.\r\nکف قفس خیس بود. از فضلهء مرغ فرش شده بود. خاک و کاه و پوست ارزن قاتی فضله ها بود. پای مرغ و خروسها و پرهایشان خیس بود. از فضله خیس بود. جایشان تنگ بود. همه تو هم تپیده بودند. مانند دانه های بلال بهم چسبیده بودند. جا نبود کز کنند. جا نبود بایستند. جا نبود بخوابند. پشت سرهم تو سرهم تک میزدند و کاکل هم را میکندند. جا نبود. همه توسری میخوردند. همه جایشان تنگ بود. همه سردشان بود. همه گرسنه شان بود. همه با هم بیگانه بودند. همه جا گند بود. همه چشم به راه بودند. همه مانند هم بودند وهیچکس روزگارش از دیگری بهتر نبود. \r\nآنهائی که پس از توسری خوردن سرشان را پائین میآوردند و زیر پر وبال و لاپای هم قایم میشدند.، خواه ناخواه تکشان تو فضله های کف قفس میخورد. آنوقت از ناچاری از آن تو پوست ارزن رومی ورمیچیدند. آنهائی که حتی جا نبود تکشان به فضله های ته قفس بخورد، بناچار به سیم دیوراهء قفس تک میزدند و خیره به بیرون مینگریستند. اما سودی نداشت و راه فرار نبود. جای زیستن هم نبود. نه تک غضروفی و نه چنگال و نه قدقد خشم آلود و نه زور و فشار و نه تو سرهم زدن راه فرار نمینمود. اما سرگرمشان میکرد. دنیای بیرون به آنها بیگانه و سنگدل بود. نه خیره و دردناک نگریستن و نه زیبائی پر و بالشان به آنها کمک نمیکرد.\r\nتو هم می لولیدند و تو فضلهء خودشان تک میزدند و از کاسه شکستهء کنار قفس آب مینوشیدند و سرهایشان را به نشان سپاس بالا میکردند و به سقف دروغ و شوخگن و مسخرهء قفس مینگریستند و حنجره های نرم و نازکشان را تکان میدادند.\r\nدر آندم که چرت میزدند، همه منتظر و چشم براه بودند. سرگشته و بی تکلیف بودند. رهائی نبود. جای زیست و گریز نبود. فرار از آن منجلاب نبود. آنها با یک محکومیت دستجمعی در سردی و بیگانگی و تنهائی و سرگشتگی و چشم براهی برای خودشان میپلکیدند.\r\nبناگاه در قفس باز شد و در آنجا جنبشی پدید آمد. دستی سیاه سوخته و رگ درآمده و چرکین و شوم و پینه بسته تو قفس رانده شد و میان هم قفسان به کند وکو در آمد. دست باسنگدلی و خشم و بی اعتنائی در میان آن به درو افتاد و آشوبی پدیدار کرد. هم قفسان بوی مرگ آلود آشنائی شنیدند. چندششان شد وپرپر زدند و زیر پر و بال هم پنهان شدند. دست بالای سرشان میچرخید، و مانند آهن ربای نیرومندی آنها را چون برادهء آهن میلرزاند. دست همه جا گشت و از بیرون چشمی چون \"رادار\" آنرا راهنمائی میکرد تا سرانجام بیخ بال جوجهء ریقونه ای چسبید و آن را از آن میان بلند کرد.\r\nاما هنوز دست و جوجه ای که در آن تقلا و جیک جیک میکرد و پر و بال میزد بالای سر مرغ و خروسهای دیگر میچرخید و از قفس بیرون نرفته بود که دوباره آنها سرگرم جویدن در آن منجلاب و توسری خوردن شدند. سردی و گرسنگی و سرگشتگی و بیگانگی و چشم براهی بجای خود بود. همه بیگانه و بی اعتنا و بی مهر، بربر بهم نگاه میکردند و با چنگال خودشان را میخاراندند.\r\nپای قفس، در بیرون کاردی تیز و کهن بر گلوی جوجه مالیده شد و خونش را بیرون جهاند. مرغ و خروسها از تو قفس میدیدند. قدقد میکردند و دیوارهء قفس را تک میزدند. اما دیوار قفس سخت بود. بیرون را مینمود اما راه نمیداد. آنها کنجکاو و ترسان و چشم براه و ناتوان به جهش خون هم قفسشان که اکنون آزاد شده بود نگاه میکردند. اما چاره نبود. این بود که بود. همه خاموش بودند وگرد مرگ در قفس پاشیده شده بود.\r\nهماندم خروس سرخ روی پر زرق و برقی تک خود را توی فضله ها شیار کرد و سپس آن را بلند کرد و بر کاکل شق و رق مرغ زیره ای پا کوتاهی کوفت. در دم مرغ خوابید وخروس به چابکی سوارش شد. مرغ توسری خورده و زبون تو فضله ها خوابید وپا شد. خودش را تکان داد وپر و بالش را پف و پره باد کرد و سپس برای خودش چرید. بعد تو لک رفت. کمی ایستاد، دوباره سرگرم چرا شد.\r\nقدقد و شیون مرغی بلند شد. مدتی دور خودش گشت. سپس شتابزده میان قفس چندک زد و بیم خورده تخم دلمهء بی پوست خونینی تومنجلاب قفس ول داد. در دم دست سیاه سوختهء رگ درآمدهء چرکین شوم پینه بسته ای هوای درون قفس را درید وتخم را از توی گندزار ربود و هماندم در بیرون قفس دهانی چون گور باز شد و آن را بعلیعد. هم قفسان چشم براه، خیره جلو خود را مینگریستند.\r\n"},{"id":2277,"category_id":2,"category_code":"s2","source_id":444,"title":"از وسط برو","content":"یک نفر از پشت سر صدام زد، صدا خیلی آشنا بود، ولی هر کاری کردم صاحب صدا را نشناختم. با هم دست دادیم ... و احوالپرسی کردیم بعدش هم یارو گفت:\r\n- دارم از «وسط محله میام ... رفته بودم پیش دکتر.»\r\n- خدا بد نده !\r\n- وسط سرم یک جوش زده بود، جوش چرکی ... \r\n- ان شاءالله خوب می شه، چیزی نیس.\r\nوسط راه پیشنهاد کرد بریم توی یه کافه ای بشینیم، خستگی بگیریم و قهوه ای بخوریم. قبول کردم.\r\nگارسون را صدا کرد:\r\n- برای ما دو تا قهوه بیار.\r\n- تلخ باشه یا شیرین؟\r\n- مال من متوسط باشه ... نه تلخ نه شیرین، متوسط\r\nدوست من خیلی بی حوصله بود، گفتم:\r\n- از چی ناراحتی؟ جواب داد:\r\n- از دست این پسر وسطی ام کسلم .رفوزه شده . معلم ازش پرسیده: قرون وسطی چیه؟ .نتونسته جواب بده.\r\n- کلاس چندمه؟\r\n- کلاس دوم متوسطه اس \r\nاون یکی امتحاناش بد نشده بود . \r\nهمه ی نمره هاش متوسط بود اما سر قرون وسطی نمره تک آورده و ...\r\n- غصه نخورین . امسال حتماً قبول می شه.\r\n- اما پسر بزرگم تا بخواهی به تاریخ علاقه داره، مخصوصاً به دوران قبل از قرون وسطی و تاریخ دوران بعد از قرون وسطی ...\r\nمن این دوست را هنوز به جا نیاورده بودم. برای این که او را بشناسم، ناچار شروع به سؤال هایی گوناگون کردم:\r\n- حالا تو کدوم محله می نشینید؟\r\n- تو محله ی «اوسط آباد» ... یک روز سرافراز بفرمایین ... از «وسط محله» که تشریف میارین برسید به اوسط آباد میدانگاهی که وایسین، درست روبروتون وسط درخت ها یه خونه ی چوبی می بینید ... اون جا منزل بنده اس ... منزل بدی نیس، اما متأسفانه:\r\nاتاق وسطی اش چکه می کند ...\r\n- کار و بارتون چطوره؟\r\n- بد نیس، متوسطه ... اما وسط ماه گذشته یه معامله یی کردیم که واسطه سرمون کلاه گذاشت، امان از دست این واسطه ها، خدا نکنه آدم به دامشون بیفته ... حالا بگذریم ...\r\n- قربون. به عقیده ی سر کار که وسط گود هستید، وضع دنیا آخرش به کجا می رسه؟ ...\r\n- «آخه این که وضع نشد، باید یک حد وسطی را رعایت کرد ... باید طرفین بشینن، قشنگ با هم حرفاشونو بزنن یه حد وسطی را قبول کنن که وضع دنیا یه خورده آروم بشه ! اصلاً این وضع کاملاً به زیان طبقه ی متوسطه ... طبقه ی بالا که راحته، طبقه ی پایین هم که چیزی حالیش نیست، ولی وای به روزگار طبقه ی وسطی ها ... آخه آقای من، جان من، عزیز من، دنیا و مردم که این وسط اسباب بازی نیستن، آخه ...»\r\nپریدم وسط حرفش ...\r\n- منظور شما ...\r\n- خیر، خیر ... بنده منظوری نداشتم، نمی خواد وسط دعوا نرخ تعیین کنید بنده یه آدمی هستم متوسط الحال کاری هم به کار کسی ندارم، اما این وسط دلم به حال مردم می سوزد! ...\r\n- خب، خوشحالم که کار و بارتون خوبه، ان شاءالله بهترم می شه.\r\n- خدا رو شکر که شریکم آدم خوبیه، نه زیاد پیره نه زیاد جوون، سنش متوسطه، قدش متوسطه، وضع و حالش متوسطه، خلاصه همه چیزش ماشالا خیلی متوسطه ...\r\n- خب با اجازه تون من دیگه باید برم.\r\n- منم کار دارم، می خوام برم مغازه گل فروشی، می خوام چندتایی نشاء گل بخرم و بکارم وسط باغچه مون، راستی، اینو می خواستم عرض کنم: یکی از بدبختی های ما اینست که مملکتمون به اندازه کافی وسطیت نداره ...\r\n- چی فرمودین؟\r\n- عرض کردم ما تا می تونیم باید برای مملکت وسطیت تربیت کنیم ... اصلاً چرا باید دانشگاه کرسی وسطولوژی نداشته باشه؟! .... چرا یه عده وسطولوگ های متخصص برای مملکت وسطولوژیست قابل تربیت نمی کنن؟\r\nگفتم:\r\n- «حق دارید، کاملاً درسته.»\r\nدست همدیگر را فشردیم و جدا شدیم. او از پشت سر مرا صدا زد. گفتم:\r\n- بله؟ ...\r\nداد زد:\r\n- از وسط برو، از وسط برو ... جلو بیفتی زیر دست و پا له میشی، عقب بمونی دستت به جایی بند نیس ... تا می تونی از وسط برو، از وسط برو ...\r\n"},{"id":2278,"category_id":2,"category_code":"s2","source_id":445,"title":"چقدر زود دیر می شود...","content":"\r\nوارد خونه شد و چشمش که به دیوار افتاد بهت زده شد!\r\nدختر کوچولو تکه بزرگی از کاغذ دیواری رو کنده بود!\r\nنتونست خودش رو کنترل کنه و حسابی سرش داد زد و ...\r\nفردا روز پدر بود.\r\nدخترک ، قوطی کوچولوئی رو که با کاغذ دیواری کادو پیچ کرده بود آورد و گفت :\r\nبابائی روزت مبارک ، خیلی دوستت دارم.\r\nخدای من!\r\nحالا چکار کنم؟\r\nهمون طور که کاغذ دیواری رو از دور قوطی باز می کرد ، ذهنش مشغول اتفاق دیروز بود.\r\nدر قوطی رو باز کرد.\r\nخالی بود!\r\nبازعصبانی شد و گفت :\r\nاین که خالیه!\r\nو جواب شنید که :\r\nپره پدر!\r\nپر از بوس!\r\nباباجون چند ماهه هر وقت که می خوام بخوابم این قوطی رو محکم بغل می کنم و کلی بوس واسه تو\r\nمی ذارم توش ، بوس هام رو ندیدی؟!\r\nپدر که خیلی شرمنده شده بود ، فکر می کرد چجوری باید رفتارهای غلطم رو جبران کنم؟\r\nسه روز بعد ، دختر کوچولو در سانحه ای جونش رو از دست داد.\r\nو پدر موند و اون قوطی.\r\nشب ها قوطی رو محکم بغل می کرد و یکی یکی بوسه های خیالی رو از توش در می آورد و روی\r\nگونه هاش می گذاشت و پهنای صورتش رو اشک می پوشوند...\r\nولی یادمون باشه تا عزیزامون هستند و هستیم ، رد عشق\r\nرو هم تو زندگی هامون ببینیم و بگذاریم.\r\nنکنه روزی بیاد که با حسرت به خودمون بگیم :\r\nناگهان چقدر زود دیر می شود...\r\n"},{"id":2279,"category_id":2,"category_code":"s2","source_id":446,"title":"پیرمرد حواس پرت","content":"\r\nمجلس میهمانی بود.\r\nپیر مرد از جایش برخاست تا به بیرون برود.اماوقتی که بلند شد،عصای خویش را بر عکس بر زمین نهاد.\r\nو چون دسته عصا بر زمین بود،تعادل کامل نداشت.\r\nدیگران فکر کردند که او چون پیر شده،دیگر حواس خویش را از دست داده و متوجه نیست که عصایش را بر عکس بر زمین نهاده.\r\nبه همین خاطر با حالتی که خالی از تمسخر نبود به وی گفتند:\r\nپس چرا عصایت را بر عکس گرفته ای؟!\r\nپیر مرد آرام و متین پاسخ داد:\r\nزیرا انتهایش خاکی است؛می خواهم فرش خانه تان خاکی نشود...\r\n"},{"id":2280,"category_id":2,"category_code":"s2","source_id":447,"title":"تو فقط بگو آمین!!","content":"\r\nماه رمضان بود و شهر یکپارچه دعا\r\nو مردمان در شهر به دعا کردن مشغول بودند\r\nدعا،همان دعای همیشگی ماه رمضان بود:\r\n_الهم اشف کل مریض\r\n_الهی آمین!\r\n_الهم اغن کل فقیر\r\n_الهی آمین!\r\n_انک علی کل شیء قدیر\r\n_الهی آمین!!\r\nمرد ساده و بی چاره ما بی آن که کوچکترین چیزی از دعا بفهمد،فقط آمین می گفت!\r\nو حتما پیش خودش هم فکر می کرد:مهم نیست چیزی از دعا نفهمی،خداوند خودش می فهمد و بر آورده می کند!هزچند من نمی فهمم که از خدا چه خواسته ام!!\r\n"},{"id":2281,"category_id":2,"category_code":"s2","source_id":448,"title":"پادشاه و مرد پارسا","content":"\r\nپادشاهی پارسایی را دید از او پرسید:هیچ ما را یاد میکنی؟\r\nمرد پارسا گفت:آری\r\nپادشاه گفت:در چه مواقعی؟\r\nمرد گفت:هر وقت خدا را فراموش میکنم.\r\n"},{"id":2282,"category_id":2,"category_code":"s2","source_id":449,"title":"از بهر خدا...","content":"\r\nبد صدایی بر سر مناره مسجد با صدای بلند قرآن میخواند,صاحبدلی بر او بگذشت گفت:\r\nاز بهر چه میخوانی؟\r\nمرد بد صدا گفت:از بهر خدا میخوانم\r\nصاحبدل گفت:از بهر خدا مخوان\r\nگر تو قرآن بر این نمط خوانی ببری رونق مسلمانی\r\n"},{"id":2283,"category_id":2,"category_code":"s2","source_id":450,"title":"انکار قرآن","content":"تعدادی از دانشمندان جمع شدند تا با تحقیق در متن قرآن ؛ خطا و اشتباهی در آن بیابند و به این ترتیب قرآن را رد کنند!!!!.\r\nلذا بسیار در متن قرآن و کلمات آن دقت کردند تا اینکه به این آیه رسیدند که در مورد داستان حضرت سلیمان است که وقتی مورچه ای لشکر حضرت سلیمان را میبیند به سایر مورچه ها میگوید :پناه بگیرید تا لشکر سلیمان شما را خرد نکنند\r\n(لایحطمنکم)\r\nدر حالی که:\r\nاین کلمه با مصدر (تحطیم = خرد شدن شیشه) در زبان عربی فقط در مورد شیشه به کار میرود اما مورچه ها آن را درباره ی خود بکار برده اند.!!!\r\nپس این اشکالی است که میتوان به متن قرآن گرفت !!!!\r\nبعد از آن یک دانشمند استرالیایی در تحقیقات علمی خود کشف کرد که:بیش از 75 درصد از غشای خارجی بدن مورچه ها را شیشه تشکیل میدهد \r\nو با کشف این معجزه ی قرآن بلافاصله به اسلام ایمان آورد و مسلمان شدنش را اعلام نمود.\r\n"},{"id":2284,"category_id":2,"category_code":"s2","source_id":451,"title":"کره فروش","content":"مرد فقیرى بود که همسرش کره مى ساخت و او آنرا به یکى از بقالى های شهر مى فروخت‌ آن زن کره ها را به صورت دایره های یک کیلویى مى ساخت.‌ مرد آنرا به یکى از بقالى های شهر مى فروخت و در مقابل مایحتاج خانه را مى خرید. ‌روزى مرد بقال به اندازه کره ها شک کرد و تصمیم گرفت آنها را وزن کند.‌ هنگامى که آنها را وزن کرد، اندازه هر کره ۹۰۰ گرم بود. او از مرد فقیر عصبانى شد ‌و روز بعد به مرد فقیر گفت:دیگر از تو کره نمى خرم، ‌تو کره را به عنوان یک کیلو به من مى فروختى در حالى که وزن آن ۹۰۰ گرم است. مرد فقیر ناراحت شد و سرش را پایین انداخت و گفت:ما ترازویی نداریم و‌ یک کیلو شکر از شما خریدیم و آن یک کیلو شکر را به عنوان وزنه قرار مى دادیم .‌ یقین داشته باش که:به اندازه خودت برای تو اندازه مى گیریم!"},{"id":2285,"category_id":2,"category_code":"s2","source_id":452,"title":"بنگاه همسریابی","content":"\r\nمـردی قـصـد ازدواج داشـت.... \r\nپـس بـه یـک بـنـگـاه ازدواج مـراجـعـه کــرد کـه روی آن نـوشـتـه شـده بـود: \"بـنـگـاه هـمـسـریـابـی\" مـرد در را بـاز کـرد و وارد اتـاقـی شـد کـه دو در داشـت....\r\nروی یـکـی از آنـهـا نـوشـتـه شـده بـود \"زشـت\" و روی دیـگـری \"زیـبــا\" در زیـبــا را فـشـار داد و وارد اتـاق شـد....\r\nدو در دیـگــر دیـد,روی یـکـی نـوشـتـه شـده بـود \"کـدبـانـو\" و روی دیـگـری \"شـلـخـتـه\" او از در کـدبـانـوی خـوب وارد شـد.... \r\nدر آنـجـا دو در دیـگــر بـود کـه روی یـکـی \"جـوان\" و روی دیـگـری \"پـا بـه سـن گـذشـتـه\" نـوشـتـه شـده بـود.... \r\nاز در جـوان وارد شـد... تـه اتـاق آیـنـه ی دیـواری بـزرگـی دیـده مـی شـد کـه روی آن نـوشـتـه شـده بـود: \"\"بـا چـنـیـن ادعــا و تـوقـعـاتـی بـهــتــر اسـت اول خـودتـان را در آیـنـه نـگــاه کـنـیـد!!! \"\"\r\n"},{"id":2286,"category_id":2,"category_code":"s2","source_id":453,"title":"معمای حل نشدنی...","content":"مي‌گويند شخصي سر كلاس رياضي خوابش برد. وقتي زنگ را زدند بيدار شد و با عجله دو مساله را كه روي تخته سياه نوشته شده بود يادداشت كرد و بخيال اينكه استاد آنها را بعنوان تكليف منزل داده است به منزل برد و تمام آن روز و آن شب براي حل آنها فكر كرد. هيچيك را نتوانست حل كند، اما تمام آن هفته دست از كوشش برنداشت. سرانجام يكي را حل كرد و به كلاس آورد. استاد بكلي مبهوت شد، زيرا آن‌ها را به عنوان دو نمونه از مسائل غيرقابل حل رياضي داده بود."},{"id":2287,"category_id":2,"category_code":"s2","source_id":454,"title":"قول زن وشوهر","content":"روزگاری در اولیـن صبح عروسی ، زن و شوهـری توافق می‌کنند که در را بر روی هیچـکس باز نکنـند .\r\nدر همیـن زمان ، پدر و مادرِ پسـر ، زنگِ درِ خانه را به صدا درآوردند . زن و شوهر نگاهی به همدیگـر \r\nانداختند اما چون از قبل توافـق کرده بودند ، هیچکدام در را باز نکـردند.\r\nساعتی بعد زنـگ خانه دوباره به صدا در‌آمد و این بار ، پدر و مادرِ دختـر پشتِ در بودند.\r\nزن و شوهر نگاهـی به همدیگـر انداختـند .\r\nاشک در چشمانِ زن جمع شده بود و گفـت : نمیـتوانم ببیـنم که پدر و مادرم پشتِ در باشند و در \r\nرا به رویشان بازنکنـم . شوهر مخالفـتی نکرد و در را به رویشان باز کرد .\r\nسالـــها گذشت ... خداونـد به آنها چهار فرزندِ پسر اعطا کرد . سالِ بعد پنجمـین فرزندشان \r\nدختر بود .\r\nپدرِ خانـواده برای تولدِ این فرزند ، بسیار شادی کرد و چند گوسفـند را سر برید و مهمانیِ \r\nمفصلی به راه انداخت .\r\nمردم متعـجبانه از او پرسیدند : علتِ اینـــهمه شادی و مهمانی دادن چیست ؟ همه این شادی و\r\nمهمـانی را برای\r\nتولدِ پسرهایـشان به راه می‌اندازنـد ...\r\nمـرد به سادگی پاسخ داد ؛ \" چـــون این همـــان کسی است که در را به روی من باز خواهد\r\nکـــرد \"\r\n"},{"id":2288,"category_id":2,"category_code":"s2","source_id":455,"title":"کلید زندگی","content":">>جان لئون<<یکی از معروف ترین و برجسته ترین چهره ی موسیقی دنیا در قرن بیستم,خاطره ای را تعریف میکند که بسیار زیبا و تامل برانگیز است:\r\nوقتی پنج ساله بودم,مادرم همیهش میگفت>>شادی کلید زندگی است<<\r\nمدرسه که رفتم,یک روز معلممان ازم خواست که بنویسم وقتی بزرگ شدیم,در زندگی میخواهیم چه کاره شویم.\r\nمن نوشتم:میخواهم شاد باشم.\r\nمعلم به من گفت:نه...این چه جوابی است؟!سوال را نفهمیدی!\r\nجواب دادم:چرا فهمیدم,این شمایید که مفهوم زندگی را نفهمیدید!\r\nلئو تولستوی:اگر میخواهید شاد باشید,فقط اراده کنید.\r\n"},{"id":2289,"category_id":2,"category_code":"s2","source_id":456,"title":"راه حل عادلانه","content":"دو برادر قطعه زمینی از پدر به ارث بردند.ماه ها ر مورد نحوه ی تقسیم ان بحث و گفت و گو کردند ولی به نتیجه ای نرسیدند.\r\nان ها سرانجام مشکل خود را با ریش سفید ده در میان گذاشتندو از او خواستند در تقسیم زمین به انها کمک کند.\r\nریش سفید کمی تامل کرد و سپس گفت:شیر یا خط بندازید.هرکدام از شما که برنده شد زمین را او تقسیم خواهد کرد.\r\nیکی از برادران گفت:این که شما میفرمایید راه حل نیست!ما ما دوباره به همان جای اول میرسیم.\r\nریش سفید لبخندی زد و گفت:نه!اینطور نیست,کسی که برنده ی شیر یا خط شود,زمین را تقسیم میکند و دیگری انتخاب میکند که کدام را میخواهد.\r\n"},{"id":2290,"category_id":2,"category_code":"s2","source_id":457,"title":"ازمون استخدامی یک شرکت","content":"مصاحبه کننده : در هواپیمائی 500 عدد آجر داریم، 1 عدد آنها را از هواپیما به بیرون پرتاب میکنیم. الان چند عدد آجر داریم ؟\r\nمتقاضی : 499 عدد !\r\nمصاحبه کننده : سه مرحله قرار دادن یک فیل داخل یخچال را شرح دهید.\r\nمتقاضی : مرحله اول: در یخچالو بازمیکنیم - مرحله دوم: فیلو میذاریم تو یخچال - مرحله سوم: در یخچالو میبندیم !!\r\nمصاحبه کننده : حالا چهار مرحله قرار دادن یک گوزن در یخچال را توضی...ح دهید !\r\nمتقاضی : مرحله اول: در یخچالو بازمیکنیم - مرحله دوم: فیلو از تو یخچال در میاریم - مرحله سوم: گوزنو میذاریم تو یخچال - مرحله چهارم: در یخچالو میبندیم !!\r\nمصاحبه کننده : شیر واسه تولدش مهمونی گرفته، همه حیوونا هستن جزیکی. اون کیه ؟\r\nمتقاضی : گوزنه که تو یخچاله !!\r\nمصاحبه کننده : چگونه یک پیرزن از یک برکه پر از سوسمار رد میشود ؟\r\nمتقاضی : خیلی راحت، چون سوسمارا همشون رفتن تولد شیر !!\r\nمصاحبه کننده : سوال آخر. اون پیرزن کشته شد، چرا ؟\r\nمتقاضی : امممممممم، نمیدونم، غرقشد ؟\r\nمصاحبه کننده : نه، اون یه دونه آجری که از هواپیما انداختی پائین خورد تو سرش مرد !!! شما مردود شدین، نفر بعدی لطفا :|\r\n"},{"id":2291,"category_id":2,"category_code":"s2","source_id":458,"title":"نارنجی پوش","content":"\r\nپیرمردی نارنجی پوش در حالی که کودک را در آغوش داشت.\r\nبا سرعت وارد بیمارستان شد و به پرستار گفت:خواهش می کنم به داد این بچه برسید.\r\nبچه ماشین بهش زد و فرار کرد.\r\nپرستار : این بچه نیاز به عمل داره باید پولشو پرداخت کنید.\r\nپیرمرد: اما من پولی ندارم پدر و مادر این بچه رو هم نمی شناسم.\r\nخواهش می کنم عملش کنید من پول و تا شب براتون میارم\r\nپرستار : با دکتری که قراره بچه رو عمل کنه صحبت کنید.\r\nاما دکتر بدون اینکه به کودک نگاهی بیندازد گفت:\r\nاین قانون بیمارستانه. باید پول قبل از عمل پرداخت بشه.\r\nصبح روز بعد…\r\nهمان دکتر سر مزار دختر کوچکش ماتش برده بود و به دیروزش می اندیشید\r\n"},{"id":2292,"category_id":2,"category_code":"s2","source_id":459,"title":"کشاورز و ساعت","content":"\r\nروزی کشاورزی متوجّه شد ساعتش را در انبار علوفه گم کرده است. \r\nساعتی معمولی امّا با خاطره ای از گذشته و ارزشی عاطفی بود. \r\nبعد از آن که در میان علوفه بسیار جستجو کرد و آن را نیافت از گروهی کودکان که در بیرون انبار مشغول بازی بودند مدد خواست و وعده داد که هر کسی آن را پیدا کند جایزه ای دریافت نماید.\r\nکودکان به محض این که موضوع جایزه مطرح شد به درون انبار هجوم آوردند و تمامی کپّه های علف و یونجه را گشتند امّا باز هم ساعت پیدا نشد. \r\nکودکان از انبار بیرون رفتند و درست موقعی که کشاورز از ادامۀ جستجو نومید شده بود، پسرکی نزد او آمد و از وی خواست به او فرصتی دیگر بدهد.\r\nکشاورز نگاهی به او انداخت و با خود اندیشید، \"چرا که نه؟ به هر حال، کودکی صادق به نظر میرسد.\"\r\n"},{"id":2293,"category_id":2,"category_code":"s2","source_id":460,"title":"رسیدن به کمال","content":"\r\nافرادی که در جمع بودند با شنیدن این جملات شوکه و اندوهگین شدند...\r\nپدر شایا ادامه داد:>>به اعتقاد من,هنگامی که خدا بچه ای مانند شایا را به دنیا می اورد,کمال ان بچه را در روشی میگذارد که دیگران با او رفتار میکنند.<<و سپس داستان زیر را در باره ی شایا تعریف کرد.\r\n>>یک روز که شایا و من در پارک قدم میزدیم تعدادی بچه را دیدم که بیسبال بازی میکردند.شایا شرسید:بابا به نظرت اونا منو بازی میدن...؟من میدانستم که پسرم بازی بلدنیست و احتمالا بچه ها اورا توی تیمشان نمیخواهند.اما فهمیدم که اگر پسرم برای بازی پذیرفته شود,حس یکی بودن با ان بچه ها میکند.پس به یکی از بچه ها نزدیک شدم و پرسیدم که :ایا شایا میتواند بازی کند؟!آن بچه به هم تیمی هایش نگاه کرد تا نظر انها را بخواهد,ولی جوابی نگرفت و خودش گفت:ما 6 امتیاز عقب هستیمم و بازی در رآند 9 است.فکر میکنم اون بتونه در تیم ما باشه...\r\nدر نهایت تعجب چوب بیسبال را به شایا دادند!همه میدانستند که این غیر ممکن است زیراشایا حتی بلد نیست که چطور چوب را بگیرد!اما همین که شایا برای زدن ضربه رفت,توپ گیر چند قدمی نزدیک شد تا توپ را خیلی ارام بندازد که شایا حداقل بتواند ضربه ی ارامی به ان بزند...اولین توپی که زده شد,شایا ناشیانه زد و از دست داد!\r\nیکی از هم تیمی های شایا نزدیک شد و دو تایی چوب را گرفتند و روبروی پرتاپ کن ایستادند.توپ گیر دوباره چند قدمی جلو امد وارام توپ را انداخت.شایا و هم تیمی اش,ضربه ارامی زدند و توپ نزدیک توپ گیر افتاد, توپ گیر,توپ را برداشت و میتوانست به اولین نفر تیمش بدهد و شایا باید بیرون میرفت و بازی تمام میشد...اما به جای این کار, او توپ را جایی دور از نفر اول تیمش انداخت و همه داد زدند:شایا, برو به خط اول, برو به خط اول!!!تا به حال شایا به خط اول ندویده بود!\r\nشایا هیجان زده و با شوق, خط عرضی را با شتاب دوید.وقتی که شایا به خط اول رسید,بازیکنی که انجا بود میتوانست توپ را جایی پرتاپ کند که امتیاز بگیرد و شایا از زمین بیرون برود,ولی فهمید که چرا توپ گیر,توپ را انجا انداخته است.توپ را بلند,ان طرف خط سوم پرت کرد و همه داد زدند:بدو به خط 2,بدو به خط2!!!\r\nشایا به سمت خط دوم دوید.در این هنگنم بقیه بچه ها در خط خانه هیجان زده و مشتاق,حلقه زده بودند...همین که شایا به خط دوم رسید,همه داد زدند:برو به 3!!!وقتی به 3 رسید,افراد هر دو تیم دنبالش دویدند و فریاد زدند:شایا برو به خانه...!شایا به خط خانه دوید و همه ی 18 بازیکن,شایا را مثل یکقهرمان روی دوش گرفتند,مانند اینکه او یک ضربه ی خیلی عالی زده و کل تیم برنده شده باشید...<<\r\nپدر شایا در حالی که اشک در چشمانش بود گفت:>>ان 18 پسر به کمال رسیدند...<<\r\nاین داستان را تعمیم بدهیم به خودمان و همه ی کسانی که با انها زندگی میکنیم.هیچ کدام ما کامل نیستیم و جایی از وجودمان ناتوانی هایی داریم,اطرافیان ما هم همینطورند.پس بیایید با ارامش از ناتوانی های اطرافیانمان بگذریم و همدیگر را به خاطر نقص هایمان خرد نکنیم.بلکه با عشق,هم خودمان را به سمت بزرگی و کمال ببریم هم اطرافیانمان را.\r\nاسمان فرصت پرواز بزرگی است...\r\nقصه این است چه اندازه کبوتر باشی\r\nالبرت شوایتزر:تا هنگامی که انسان کلیه ی موجودات را در دایره ی مهر و شفقت خود وارد نکند,به ارامش حقیقی نخواهد رسید\r\n\r\nپس کشاورز کودک را به تنهایی به درون انبار فرستاد. \r\nبعد از اندکی کودک در حالی که ساعت را در دست داشت از انبار علوفه بیرون آمد. \r\nکشاورز از طرفی شادمان شد و از طرف دیگر متحیّر گشت که چگونه کامیابی از آنِ این کودک شد.\r\nپس پرسید، \"چطور موفّق شدی در حالی که بقیه کودکان ناکام ماندند؟\"\r\nپسرک پاسخ داد، \"من کار زیادی نکردم؛ روی زمین نشستم و در سکوت کامل گوش دادم تا صدای تیک تاک ساعت را شنیدم و در همان جهت حرکت کردم و آن را یافتم.\"\r\nنتیجه:\r\nذهن وقتی که در آرامش باشد بهتر از ذهنی که پر از مشغله است فکر میکند. \r\nهر روز اجازه دهید ذهن شما اندکی آرامش یابد و در سکوت کامل قرار گیرد و سپس ببینید چقدر با هوشیاری به شما کمک خواهد کرد زندگی خود را آنطور که مایلید سر و سامان بخشید.\r\n"},{"id":2294,"category_id":2,"category_code":"s2","source_id":461,"title":"نترس ادامه بده","content":"پسر کوچکی مدتی بود به کلاس پیانو میرفت و یاد گرفته بود چند قطعه ی ساده را بنوازد.مادرش برای اینکه اورا در امر یادگیری پیانو تشویق کند,تصمیم گرفت پسر را به یک کنسرت پیانو ببرد.\r\nزمانی که انها وارد سالن شدند و روی صندلی خود نشستند,مادر,یکی از دوستان قدیمی اش را از دور دید و پیش اورفت تا قبل از شروع اجرای کنسرت کمی باهم گفت و گو کنند.زمانی که انها گرم صحبت شدند,پسرک با کنجکاوی به سمت پشت صحنه رفت...مادر که از گفت و گوی با دوستش فارغ شده بود,به سمت صندلی خود بازگشت و با تعجب دید که پسرش سر جای خودش نیست!در همین حین,÷رده کنار رفت و همه با تعجب دیدند که پسر کوچکی پشت پیانو نشسته و قطعه ی کوتاهی را مینوازد!!\r\nدر همین زمان,استاد پیانو روی سن و به کنار پیانو امد و به ارامی به پسر گفت:<<نترس,ادامه بده>>و خودش نیز در کتار او قرار گرفت و در نواختن گوشه هایی از قطعه به پسر کمک کرد.او نیز بدون هیچ ترسی به نواختن ادامه داد.این صحنه,تمامی حاظران را تحت تاثیر قرار داد و شرایط هیجان انگیزی در سالن حاکم شد.\r\nنتیجه:\r\nبه خاطر داشته باشید چنانچه در مسیر زندگی دچار دلهره و ترس شدید,خوب گوش فرادهید...حتما صدای اورا خواهید شنید که میگوید:<<نترس ادامه بده>>\r\n"},{"id":2295,"category_id":2,"category_code":"s2","source_id":462,"title":"شرافت شاخه ای چند است‎ ","content":"سرچهار راه پشت چراغ قرمز ایستاده ایم . یک دختر گل فروش سیزده چهارده ساله ؛ لابه لای ماشینها گل هایش را می فروشد . می ایستد کنار خوش استیل ترین وشاستی بلند ترین و گران ترین ماشین پشت چراغ قرمز می گوید : آقا گل بخرید ؛ آقا برای خانمتان گل بخرید ؛ برای مادرتان گل بخرید ، اگه معلم دارید تو فامیل گل بخرید . مرد میان سال پنجاه و دو سه ساله شیشه ماشین را پایین می کشد و با چندش آور ترین صوت ممکن می گوید : اینطوری که نمی شه ؛ یه بوس بده تا من هم یک گل بخرم . دختر حیران شده است . من حیران شده ام . نمی دانم از کجا ؟ چه وقت آقای خانه از پشت فرمان پایین آمده اند و خیلی خونسرد رفته اند سروقت یارو فکر می کنم الان است که یقه اش را بگیرد و از پنجره ماشین بکشدش بیرون بیاندازتش زیر چرخهای ماشین بیاید از رویش رد شود . ولی او سرش را می آورد پایین صورت به صورت راننده که گیج شده است خیلی محترمانه می گوید : تف تو اون شرافت نداشته ات ! بعد خیلی خونسرد بر می گردد توی ماشین می نشیند دختر را صدا می زند همه ی گلهای مریم و رز را یکجا از او می خرد ؛ چراغ سبز می شود راه می افتیم . مگر دیگر می توان با او حرف زد اخمهایش را درهم کشیده و عرق کرده است ؛ فکر می کنم حتی یک قطره اشک هم سر خورد از گوشه چشمش آمد پایین ."},{"id":2296,"category_id":2,"category_code":"s2","source_id":463,"title":"آگهی عجیب","content":"یک روز وقتى کارمندان به اداره رسيدند، اطلاعيه بزرگى را در تابلوى اعلانات ديدند که روى آن نوشته شده بود: \"ديروز فردى که مانع پيشرفت شما در اين اداره بود درگذشت. شما را به شرکت در مراسم تشييع جنازه که ساعت ١٠ در سالن اجتماعات برگزار مى‌شود دعوت مى‌کنيم\".\r\nدر ابتدا، همه از دريافت خبر مرگ يکى از همکاران‌شان ناراحت مى‌شدند امّا پس از مدتى، کنجکاو مى‌شدند که بدانند کسى که مانع پيشرفت آنها در اداره مى‌شده که بوده است. اين کنجکاوى، تقريباً تمام کارمندان را ساعت ١٠ به سالن اجتماعات کشاند.\r\nرفته رفته که جمعيت زياد مىشد هيجان هم بالا مى‌رفت. همه پيش خود فکر مى‌کردند: اين فرد چه کسى بود که مانع پيشرفت ما در اداره بود؟ به هر حال خوب شد که مرد!\r\nکارمندان در صفى قرار گرفتند و يکى يکى نزديک تابوت مى‌رفتند و وقتى به درون تابوت نگاه مى‌کردند ناگهان خشک‌شان مىزد و زبان‌شان بند مى‌آمد.\r\nآينه‌اى درون تابوت قرار داده شده بود و هر کس به درون تابوت نگاه مى‌کرد، تصوير خود را مى‌ديد. نوشته‌اى نيز بدين مضمون در کنار آينه بود: تنها يک نفر وجود دارد که مى‌تواند مانع رشد شما شود و او هم کسى نيست جز خود شما. شما تنها کسى هستيد که مى‌توانيد زندگى‌تان را متحوّل کنيد. شما تنها کسى هستيد که مى‌توانيد بر روى شادى‌ها، تصورات و موفقيت‌هاي‌تان اثرگذار باشيد. شما تنها کسى هستيد که مى‌توانيد به خودتان کمک کنيد.\r\nزندگى شما وقتى که رئيس‌تان، دوستان‌تان، والدين‌تان، شريک زندگى‌تان يا محل کارتان تغيير مى‌کند، دستخوش تغيير نمي‌شود. زندگى شما تنها فقط وقتى تغيير مى‌کند که شما تغيير کنيد، باورهاى محدود کننده خود را کنار بگذاريد و باور کنيد که شما تنها کسى هستيد که مسئول زندگى خودتان هستيد.\r\n"},{"id":2297,"category_id":2,"category_code":"s2","source_id":464,"title":"سورنا و پیرزن !!!! ... ","content":"می گویند زمانی که سورنا سردار شجاع سپاه امپراتور ایران «ارد دوم» از جنگ بر می گشت به پیرزنی برخورد\r\nپیرزن به او گفت وقتی به جنگ می رفتی به چه دلبسته بودی ؟\r\nگفت به هیچ ! تنها اندیشه ام نجات کشورم بود\r\nپیرزن گفت و اکنون به چه چیز؟\r\nسورنا پاسخ داد به ادامه نگاهبانی از ایران زمین\r\nپیرزن با نگاهی مهربانانه از او پرسید :\r\nآیا کسی هست که بخواهی بخاطرش جان دهی ؟\r\nسورنا گفت : برای شاهنشاه ایران حاضرم هر کاری بکنم\r\nپیرزن گفت : آنانی را که شکست دادی برای آیندگان خواهند نوشت کسی که جانت را برایش میدهی تو را کشته است\r\nو فرزندان سرزمینت از تو به بزرگی و از او به بدی یاد می کنند \r\nسورنا پاسخ داد : ما فدایی این آب و خاکیم\r\nمهم اینست که همه قلبمان برای ایران می تپد \r\nمن سربازی بیش نیستم و رشادت سرباز را به شجاعت فرمانده سپاه می شناسند و آن من نیستم.\r\nپیرزن گفت : وقتی پادشاه نیک ایران زمین از اینجا می گذشت همین سخن را به او گفتم و\r\nاو گفت پیروزی سپاه در دست سربازان شجاع ایران زمین است نه فرمان من\r\nاشک در دیدگان سورنا گرد آمد، بر اسب نشست\r\nسپاهش به سوی کاخ فرمانروایی ایران روان شد.\r\n"},{"id":2298,"category_id":2,"category_code":"s2","source_id":465,"title":"گربه را در حجله باید کشت","content":"میگویند در ایام قدیم دختری تندخو و بد اخلاق وجود داشته که هیج کس حاضر به ازدواج با او نبوده است. پس از چندی پسری از اهالی شهامت به خرج می دهد و تصمیم می گیرد که با وی ازدواج کند. بر خلاف نظر همه ، او میگوید که میتواند دخترک را رام کند. خلاصه پس از مراسم عروسی ، عروس و داماد وارد حجله میشوند و... چند دقیقه از زفاف که میگذرد پسرک احساس تشنگی میکند . گربه ای در اتاق وجود داشته از او میخواهد که آب بیاورد. چند بار تکرار میکند که ای گربه برو و برای من آب بیاور. گربه بیچاره که از همه جا بی خبر بوده از جایش تکان نمی خورد تا اینکه مرد جوان چاقویش را از غلاف بیرون می کشد و سر از تن گربه جدا میکند. سپس رو یه دختر میکند و میگوید برو آب بیار..."},{"id":2299,"category_id":2,"category_code":"s2","source_id":466,"title":"خلافت مامون و جواب امام رضا(ع)","content":"صدایش را صاف کرد، بلند گفت: \r\nمن در آل علی و عباس هر چه گشتم شایسته تر از علی بن موسی کسی را برای خلافت ندیدم. همه گوش می‌ دادند و سر توی سر هم پچ پچ می‌ کردند. مأمون دوباره با صدای بلند گفت من خودم را از خلافت عزل می‌ کنم تا اباالحسن علی بن موسی الرضا به جای من بر تخت بنشیند. این جزئی از برنامه اش بود تا خودی نشان دهد.\r\nامام فرمود:\r\nاگر خدا این خلافت را به تو داده پس حق بخشیدنش را نداری، اگر هم خدا نداده پس اصلاً خلافت مال تو نیست تا اختیار بخشیدن یا نبخشیدنش به دیگران را داشته باشی. همه سکوت کرده بودند. حالا مأمون مثل همیشه سرش را پایین انداخته بود و فقط نگاه های ریز و موشکافانه جمعیت او را می‌ پایید.\r\n"},{"id":2300,"category_id":2,"category_code":"s2","source_id":467,"title":"قصاب قاتل؟!","content":"عصر خلافت امام علي (ع) بود، قصابي را كه چاقوي خون آلود در دست داشت، در خرابه اي ديدند و در كنار او جنازه خون آلود شخصي افتاده بود؛ قرائن نشان مي داد كه كشنده او همين قصاب است، او را دستگير كرده و به حضور امام علي (ع) آوردند. امام علي (ع) به قصاب گفت: در مورد كشته شدن آن مرد، چه نظر داري ؟ قصاب گفت: من او را كشته ام. امام بر اساس ظاهر جريان ، و اقرار قصاب ، دستور داد تا قصاب را ببرند و به عنوان قصاص، اعدام كنند. در اين حال كه ماءمورين، او را به قتلگاه مي بردند، قاتل حقيقي با شتاب به دنبال مأمورين دويد و به آنها گفت: عجله نكنيد و اين قصاب را به حضور امام علي (ع) بازگردانيد. ماءمورين او را به حضور علي (ع) باز گرداندند، قاتل حقيقي به حضور علي (ع) آمد و گفت : اي امير مؤمنان! سوگند به خدا، قاتل آن شخص اين قصاب نيست، بلكه او را من كشته ام. امام به قصاب فرمود: چه موجب شد كه تو اعتراف نمودي من او را كشته ام ؟ قصاب گفت: من در يك بن بستي قرار گرفتم كه غير از اين چاره اي نداشتم، زيرا افرادي مانند اين مأمورين، مرا كنار جنازه بخون آغشته با چاقوي خون آلود بدست ديدند، همه چيز بيانگر آن بود كه من او را كشته ام، از كتك خوردن ترسيدم و اقرار نمودم كه من كشته ام، ولي حقيقت اين است كه من گوسفندي را نزديك آن خرابه كشتم، سپس ادرار بر من فشار آورد، در همان حال كه چاقوي خون آلود در دستم بود، به آن خرابه براي تخلّي رفتم، جنازه بخون آغشته آن مقتول را در آنجا ديدم، در حالي كه دهشت زده شده بودم، برخاستم، در همين هنگام اين گروه به سر رسيدند و مرا به عنوان قاتل دستگير نمودند. اميرمؤمنان علي (ع) فرمود: اين قصاب و اين شخص كه خود را قاتل معرفي مي كند را به حضور امام حسن (ع) ببريد تا او قضاوت نمايد. مأمورين آنها را نزد امام حسن (ع) آوردند و جريان را به عرض ‍ رساندند. امام حسن (ع) فرمود: به امير مؤمنان علي (ع) عرض كنيد، اگر اين مرد قاتل ، آن شخص را كشته است، در عوض جان قصاب را حفظ نموده است، و خداوند در قرآن مي فرمايد: و من احياها فكانّما احيا الناس جميعا.(و هر كس انساني را از مرگ نجات دهد، چنان است كه گوئي همه مردم را نجات بخشيده است)1. آنگاه هم قاتل و هم آن قصاب را آزاد نمود، و ديه مقتول را از بيت المال به ورثه او عطا فرمود. به اين ترتيب، ارفاق و تشويق اسلام شامل حال آن قاتل شد كه مردانگي كرد و موجب نجات يك نفر بي گناه گرديد، و با اين كار جوانمردانه اش، تا حدود زيادي گناه خود را جبران نمود."},{"id":2301,"category_id":2,"category_code":"s2","source_id":468,"title":"تقسیم 17 شتر","content":"شخصی در حال مرگ بود و قبل از مرگش او وصیت کرد: من 17 شتر و 3 فرزند دارم\r\nشتران مرا طوری تقسیم کنید که بزرگترین فرزندم نصف انها را و فرزند دومم یک سوم انها را و فرزند کوچکم یک نهم مجموع شتران را به ارث ببرند\r\nوقتی که بستگانش بعد از مرگ او این وصیت نامه را مطالعه کردند متحیر شدند و به یکدیگر گفتند ما چطور می توانیم این 17 شتر را به این ترتیب تقسیم کنیم؟\r\nو بعد از فکر کردن زیاد به این نتیجه رسیدند که تنها یک مرد در عربستان می تواند به انها کمک کند\r\nبنابراین انها به نزد امام علی رفتند تا مشکل خود را مطرح کنند\r\nحضرت فرمود: رضایت میدهید که من شترم را با شتران شما اضافه کنم آنگاه تقسیم بنمایم. گفتند: چگونه رضایت نمی دهیم. پس شتر خویش را به شتران اضافه نمود و به فرزند بزرگ که سهمش نصف شتران بود، نه شتر داد. به فرزند دوم که سهمش ثلث شتران بود، شش شتر داد و به فرزند سوم که سهم او یک نهم بود، دو شتر داد و در اخر یک شتر باقی ماند که همان شتر حضرت بود.\r\n"},{"id":2302,"category_id":2,"category_code":"s2","source_id":469,"title":"بی غیرت!","content":"\r\nجوان خیلی آرام و متین به مرد نزدیک شد و با لحنی مودبانه گفت:\r\n- ببخشید آقا! من میتونم یکم به خانم شما نگاه کنم و لذت ببرم؟\r\nمرد که اصلاً توقع چنین حرفی رو نداشت و حسابی جا خورده بود، مثل آتشفشان از جا پرید و میان بازار و جمعیت، یقۀ جوان رو گرفت و عصبانی، طوری که رگ گردنش بیرون زده بود، او را به دیوار کوفت و فریاد زد:\r\n- مردیکۀ عوضی، مگه خودت ناموس نداری…؟ خجالت نمیکشی؟؟\r\nاما جوان،خیلی آرام، بدون اینکه از رفتار و فحش های مرد عصبی بشه و واکنشی نشون بده، همان طور مودبانه و متین ادامه داد..\r\n- خیلی عذر میخوام؛ فکر نمیکردم این همه عصبی و غیرتی بشین! دیدم همۀ بازار دارن بدون اجازه نگاه میکنن و لذت میبرن، من گفتم حداقل از شما اجازه بگیرم، که نامردی نکرده باشم…! \r\nحالا هم یقه مو ول کنین! از خیرش گذشتم!!\r\nمرد خشکش زد… همانطور که یقۀ جوان را گرفته بود، آب دهانش را قورت داد و زیر چشمی زنش را برانداز کرد…\r\n"},{"id":2303,"category_id":2,"category_code":"s2","source_id":470,"title":"راننده و جوانان","content":"راننده کامیونی وارد رستوران شد . دقایقی پس از این که او شروع به غذا خوردن کرد ، سه جوان موتور سیکلت سوار هم به رستوران آمدند و یک راست به سراغ میز راننده کامیون رفتند . بعد از چند دقیقه پچ پچ کردن ، اولی سیگارش را در استکان چای راننده خاموش کرد . راننده به او چیزی نگفت .\r\nدومی شیشه نوشابه را روی سر راننده خالی کرد و باز هم راننده سکوت کرد .\r\nوقتی راننده بلند شد تا صورتحساب رستوران را پرداخت کند ، نفر سوم به پشت او پا زد و راننده محکم به زمین خورد ، ولی باز هم ساکت ماند .\r\nدقایقی بعد از خروج راننده از رستوران یکی از جوان ها به صاحب رستوران گفت : چه آدم بی خاصیتی بود ، نه غذا خوردن بلد بود ، نه حرف زدن و نه دعوا !\r\nرستورانچی جواب داد : از همه بد تر رانندگی بلد نبود ، چون وقتی داشت می رفت دنده عقب ، 3 تا موتور نازنین را له کرد و رفت !!!\r\n"},{"id":2304,"category_id":2,"category_code":"s2","source_id":471,"title":"محافظت از خویشتن ","content":"« پادشاهی به عارفی رسید، از او پندی خواست. عارف گفت: هر آنچه را در آن امید رستگاری است، بگیر و آنچه را در آن خطر هلاکت است ، رها کن»"},{"id":2305,"category_id":2,"category_code":"s2","source_id":472,"title":"تخفیف گرفتن دختر بدحجاب!","content":"\r\nهر بار که برای خرید می رفت,کلی تخفیف می گرفت. می گفتːتو خرید بلد نیستی!یه بار با من بیا;برات یه تخفیف حسابی می گیرم. \r\nآن روز با فروشنده جوان,با ناز و کرشمه از هر دری حرف زد وخندید.نیم ساعت بعد ,پس از فروش حیا و نجابتش توانست مانتو را با ده هزار تومان تخفیف بخرد!\r\n"},{"id":2306,"category_id":2,"category_code":"s2","source_id":473,"title":"بهترین عبادت ","content":"امام حسین (ع) می فرماید: جمعی خدا را از شوق بهشت می پرستند، این عبادت سوداگران است و گروهی خدا را از بیم دوزخ می پرستند، این عبادت بردگان است و مردمی هم خدا را از روی شکر می پرستند. این عبادت آزادگان و بهترین عبادت است."},{"id":2307,"category_id":2,"category_code":"s2","source_id":474,"title":"عرق کار","content":"امام کاظم در زمینی که متعلق به شخص خودش بود مشغول کار و اصلاح زمین بود. فعالیت زیاد عرق امام را از تمام بدنش جاري ساخته بود. علی بن ابی حمزه بطائنی در این وقت رسید و عرض کرد:\r\n« قربانت گردم،چرا این کار را به عهده دیگران نمی گذاري؟ »\r\n-چرا به عهده دیگران بگذارم؟افراد از من بهتر همواره از این کارها می کرده اند\r\n-مثلا چه کسانی؟\r\n-رسول خدا و امیر المؤمنین و همه پدران و اجدادم.اساسا کار و فعالیت در زمین از سنن پیغمبران و اوصیاي پیغمبران و بندگان شایسته خداوند است\r\n"},{"id":2308,"category_id":2,"category_code":"s2","source_id":475,"title":"امتحان هوش","content":"تا آخر،هیچ یک از شاگردان نتوانست به سؤالی که معلم عالیقدر طرح کرده بود جواب درستی بدهد.هر کس جوابی داد و هیچ کدام مورد پسند واقع نشد. سؤالی که رسول اکرم در میان اصحاب خود طرح کرد این بود:\r\n« در میان دستگیر ههاي ایمان کدام یک از همه محکمتر است؟ »\r\nیکی از اصحاب:نماز\r\nرسول اکرم:نه\r\nدیگري:زکات\r\nرسول اکرم:نه\r\nسومی:روزه\r\nرسول اکرم:نه\r\nچهارمی:حج و عمره\r\nرسول اکرم:نه\r\nپنجمی:جهاد\r\nرسول اکرم:نه\r\nعاقبت جوابی که مورد قبول واقع شود از میان جمع حاضر داده نشد،خود حضرت فرمود:\r\nتمام اینهایی که نام بردید کارهاي بزرگ و با فضیلتی است،ولی هیچ کدام از اینها آنکه من پرسیدم نیست. محکمترین دستگیر ه هاي ایمان دوست داشتن به خاطر خدا و دشمن داشتن به خاطر خداست.\r\n"},{"id":2309,"category_id":2,"category_code":"s2","source_id":476,"title":"عیادت از مریض...","content":"مرحوم قطب الدّين راوندى در كتاب خود، به نقل از حضرت جوادالا ئمّه عليه السلام حكايت كند: يكى از اصحاب امام رضا عليه السلام مريض شده و در بستر بيمارى افتاده بود، روزى حضرت از او عيادت نمود و ضمن ديدار، به او فرمود: در چه حالتى هستى؟ \r\nعرض كردم: مرگ را بسيار سخت و دردناك مى بينم.\r\nحضرت رضا عليه السلام فرمود: اين ناراحتى كه احساس مى كنى، اندكى از حالات و علائم مرگ مى باشد كه اكنون بر تو عارض شده است، پس اگر تمام حالات و سكرات مرگ بر تو عارض شود، چه خواهى كرد؟!\r\nو بعد از آن، در ادامه فرمايش خود افزود: مردم دو دسته اند: عدّه اى مرگ برايشان وسيله آسايش و استراحت است. و عدّه اى ديگر آن قدر مرگ برايشان سخت و طاقت فرسا است، كه پس از آن احساس راحتى مى كنند. حال چنانچه بخواهى كه مرگ برايت نيك و لذّت بخش باشد، ايمان و اعتقادات خود را نسبت به خداوند متعال و رسالت حضرت محمّد صلى الله عليه و آله و نيز ولايت ما اهل بيت عصمت و طهارت عليهم السلام را تجديد كن و شهادتين را بر زبان و قلب خود جارى گردان.\r\nامام جواد عليه السلام فرمود: بعد از آن كه، آن شخص طبق دستور پدرم شهادتين را گفت، اظهار داشت: يابن رسول اللّه ! ملائكه رحمت الهى با تحيّات و هدايا وارد شدند و بر شما سلام مى دهند.\r\nامام رضا عليه السلام فرمود: چه خوب شد كه ملائكه رحمت الهى را مشاهده مى كنى، از آن ها سؤ ال كن: براى چه آمده اند؟\r\nمريض گفت: آن ها مى گويند چنانچه همه ملائكه با اذن خداوند سبحان، نزد شما حاضر شوند، بدون اجازه حركتى نمى كنند.\r\nپس از آن، با كمال راحتى و آرامش خاطر. چشم هاى خود را بر هم نهاد و گفت: ((السّلام عليك ياابن رسول اللّه !)) پيغمبر اسلام، اميرالمؤ منين و ديگر امامان (سلام اللّه عليهم ) آمدند، و در همين لحظه، جان به جان آفرين تسليم كرد.\r\n"},{"id":2310,"category_id":2,"category_code":"s2","source_id":477,"title":"حضرت موسی و شیطان","content":"حضرت موسي ـ عليه السّلام ـ از پيامبر اسلام ـ صلّي الله عليه و آله ـ نقل شده كه فرمودند: حضرت موسي ـ \r\nعليه السّلام ـ نشسته بود كه شيطان بر او وارد شد در حالي كه عرقچين بلند رنگارنگ بر سرش بود، وقتي كه \r\nنزديك موسي رسيد عرقچين را كنار گذاشت حضرت موسي بر او توجه نمود و سلام كرد، سپس پرسيد تو چه كسي هستي؟ \r\nجواب داد من ابليس هستم، حضرت فرمود: خدا تو را به ما نزديك نكند، براي چه آمدي؟ \r\nگفت: آمدم تا بر تو سلام كنم چون كه نزد خدا مكان و منزلتي داري، \r\nموسي پرسيد: اين عرقچين چيست؟ \r\nدر پاسخ گفت: تا اين كه قلب‌هاي سليم انسانها را به سوي خود جلب كنم، \r\nموسي گفت: آگاهم كن به گناهي كه وقتي كسي انجام دهد بر او غلبه پيدا مي‌كني، \r\nگفت: زماني كه خودش را برتر ببيند، و عملش را زياد بداند، و گناهش در نظرش كوچك جلوه كند، \r\nسپس شيطان به موسي گفت: تو را به سه خصلت سفارش مي‌كنم: \r\n(اوّل) هيچ وقت با زن نامحرم خلوت مكن و زن هم با تو خلوت نكند، زيرا هيچ مردي با زني و زني با مردي خلوت نمي‌كند مگر اين كه خود من همراه آنان هستم نه ياران من،\r\n(دوّم) از عهد و پيمان بستن با خدا به پرهيز، چون كه هيچ كسي با خدا عهد و پيمان نمي‌بندد مگر اين كه من بين او و وفا كردن به عهد مانع ايجاد كنم،\r\n(سوّم) زماني كه تصميم گرفتي صدقه‌اي دهي سريع انجام بده، زيرا همين كه شخصي اراده كرده صدقه دهد؛ خودم مانع مي‌شوم نه ياران من.\r\n"},{"id":2311,"category_id":2,"category_code":"s2","source_id":478,"title":"عاقبت حسودی","content":"روزی و روزگاری درسرزمینی، زنى بود بسیار حسود، همسایه اى داشت به نام خواجه سلمان كه مردى ثروتمند و بسیار شریف و محترم بود، زن بر خواجه رشك مى برد و مى كوشید كه اندكى از نعمت هاى آن مرد شریف را كم كند و نیك نامى او را از میان ببرد؛ ولى كارى از پیش نمى برد و خواجه به حال خود باقى بود. عاقبت روزى تصمیم گرفت، كه خواجه را مسموم كند: حلوایى پخت و در آن زهرى بسیار ریخت و صبحگاهان بر سر راه خواجه ایستاد؛ هنگامى كه خواجه از خانه خارج شد، حلوا را در نانى نهاده، نزد خواجه آورد و گفت: خیراتى است. خواجه، حلوا را بستاند و چون عجله داشت، از آن نخورده به راه افتاد و به سوى مقصدى از شهر خارج شد. در راه به دو جوان برخورد كه خسته و مانده و گرسنه بودند. خواجه را بر آن دو، شفقت آمد. نان وحلوا را بدیشان داد؛ آن دو آن را با خشنودى فراوان، از خواجه گرفتند و خوردند و فى الحال(در جا) مردند. خبر به حاكم شهر رسید، و خواجه را دستگیر كرد، هنگامى كه از وى بازجویى شد، خواجه داستان را گفت. حاكم كسى را به سراغ زن فرستاد، زن را حاضر كردند، چون چشم زن به آن دو جنازه افتاد، شیون و زارى آغاز كرد و فریاد و فغان راه انداخت؛ معلوم شد كه آن دو تن، یكى فرزند او، و دیگرى برادر او بوده است. خود آن زن هم از شدت تأثر و جزع پس از یكى دو روز مرد. آرى خودم كردم كه لعنت بر خودم باد. این حسود بدبخت، گور خود را با دست خود كند و دو جوان رعنایش را فداى حسد خویش كرد؛ تا زنده بود، پیوسته در عذاب بود و سرانجام جان خود را در راه حسد از دست داد و در جهان دیگر به آتش غضب الهى خواهد سوخت."},{"id":2312,"category_id":2,"category_code":"s2","source_id":479,"title":"بشقاب پرنده","content":"پدر بزرگ عینکش را برداشت و آن را جلوی چشم خود گرفت و چند بار جلو و عقب برد. بعد با انتهای زیر پیراهنش شیشه آن را پاک کرد و باز به چشم خود زد و گفت: «یک کمی تار می‌بینم. ببین خانم دیروز آن ساختمان‌ها را می‌دیدم. فکر می‌کنم باید دو، سه سیخ جگر بخورم!»مادر بزرگ آهی کشید و گفت:« از آلودگی هواست. بیست و چهار ساعت دارند می‌گویند که هوا آلوده است. حالا هوس جگر کرده‌ای یک چیزی. اگر دکترت اجازه بدهد!»پدر بزرگ گفت:«خانم یک وقتی یک جایی خواندم که از آلودگی هوا همین‌طور مثل ریگ از آسمان کلاغ می‌باریده. بیچاره کلاغ‌ها، چیزی که کلاغ را بکشد باید خیلی پرزور باشد، نه مثل آلودگی هوای ما که بخار ندارد!»من رفتم کنار پنجره و آسمان را نگاه کردم ببینم کلاغ از آسمان دارد می‌بارد یا نه. به پدربزرگ گفتم:- بعد کلاغ‌ها را پارو می‌کنند؟\r\nبرای چی؟ خب وقتی از آسمان کلاغ ببارد! شاید، راستش من نمی‌دانم چه‌قدر کلاغ باریده بوده، اما یادم است که کلاغ‌های مرده از آسمان ریخته بودند پایین. نمی‌دانم کجا بود خواندم.مادر بزرگ گفت:« گفتند توی این هوای آلوده کودکان و افراد سالمند بیرون نیایند.»پدر بزرگ اول به خودش و بعد به من اشاره کرد و گفت:« کودکان و افراد سالمند! خانم پس مراسم فردا با این حساب مالیده است؟!» داشتم کلمه مالیده است را مثل پدر بزرگ تمرین می‌کردم که مادر بزرگ فریاد زد:« بی‌خود! بزرگ خانواده‌ای، بزرگ خاندانی، دعوت کرده‌اند، مگر می‌شود؟! خوب نیست، زشت است، حالا از آسمان آتش که نمی‌بارد!»پدر بزرگ ادامه داد:« چه با شکوه، بزرگ خاندان! زینت مجلس، خانم پس ما کی به درجه سالمندی می‌رسیم که پایی دراز کنیم و توی این هوای آلوده دنبال تو راه نیفتیم؟ نمی‌شود ما را از بزرگ خاندانی عزل بفرمایید؟»پدر بزرگ دست‌هایش را با عصبانیت تکان می‌داد و من اگر صدبار هم می‌دیدم نمی‌توانستم مثل او تمرین کنم و بگویم چه باشکوه، بزرگ خاندان! همین چند روز پیش بود که آن نوشته را وقتی از مدرسه می‌آمدم خواندم. عکس دوست پدر بزرگ بود با همان قیافه همیشگی که از من می‌پرسید کلاس چندی؟ زیرش نوشته بودند بزرگ خاندان. سرتاسر کوچه عکس او را زده بودند. خیلی هم بزرگ نبود. با پدربزرگ و پدر بزرگ یک خاندان دیگر هر سه روی نیمکت پارک جا می‌گرفتند. تازه من هم می‌توانستم آن وسط بنشینم.پدر بزرگ همین‌طور که قدم می‌زد توی آینه نگاه کرد. دستی به سر و صورتش کشید. حتماً می‌خواست ببیند یک بزرگ خاندان در آینه چه شکلی است. بعد گفت:- گفتند تا پایان هفته هم ادامه دارد، هر چند چیزی از آن به ما نمی‌رسد!- چی؟!- آلودگی دیگر! آلودگی خانم!خب حتماً تا پایان هفته کلاغ‌ها از آسمان می‌ریزند پایین. روی آنتن خانه همسایه چند کلاغ گنده و بزرگ نشسته بودند. حتماً آنها هم بزرگ خاندان کلاغ‌ها بودند. در میهمانی آن روز دو، سه بزرگ خاندان دیگر هم بودند. یکی از آنها همه چیز را فراموش کرده بود و غیر از خوردنی‌ها که فراموش می‌کرد کدام را هنوز نخورده، ده بار از من پرسید پسر کی هستم. بعد که می‌گفتم، باز می‌پرسید پدرت کیه؟ من داشتم با یک عالمه بچه ‌بازی می‌کردم که ناگهان شنیدم پدربزرگ دارد باران کلاغ را برای همه تعریف می‌کند. با عجله رفتم و درست جلوی مبلی که پدر بزرگ روی آن نشسته‌بود روی قالی نشستم. چه قصه عجیبی.پدربزرگ می‌گفت:- درست یادم نیست در چه کشوری بوده، اما یک جایی خواندم که یک روز همین‌طور مثل باران از آسمان کلاغ مرده پایین می‌ریخته.من بین آن همه آدم بزرگ خاندان راستش روم نشد بپرسم بعد کلاغ‌ها را پارو کردند یا نه؟!غروب که برمی‌گشتیم، من کنار پدربزرگ نشستم که هم بیرون را نگاه کنم و هم اگر پدر بزرگ باز قصه کلاغ‌ها را گفت، بهتر گوش کنم. ماشین ما وسط آن همه ماشین گیر کرده بود و من داشتم یک درخت بزرگ را از دور نگاه می‌کردم که آن طرف خیابان بود و روی آن یک عالمه کلاغ می‌نشستند و پرواز می‌کردند. با انگشت آنها را به پدربزرگ نشان ‌دادم. پدر بزرگ آهی کشید و گفت:- من نمی‌دانم این کلاغ‌ها که بال دارند چرا از این‌جا نمی‌روند. من اگر بال داشتم یک دقیقه هم صبر نمی‌کردم. می‌رفتم یک جای خوش آب و هوا، یک جای دور. این کلاغ‌ها توی این دود و دم چه کار می‌کنند؟شب دیر وقت به خانه رسیدیم.پدر بزرگ به زور چند پله را بالا رفت و بعد ایستاد تا مادربزرگ در را باز کرد. وقتی به آپارتمان خودمان می‌رفتم، برگشتم پدر بزرگ را نگاه کردم. خوب است که پدربزرگ کلاغ نیست.سروصدای زیادی ‌شنیدم. وقتی کنار پنجره رفتم، اول خیال کردم از آسمان کلاغ می‌بارد. همه جا تاریک بود. یک بشقاب پرنده کنار خیابان ایستاده بود. روی سرش چند چراغ رنگی روشن بود که می‌چرخید و نور پخش می‌کرد. چند نفر که لباس‌های سفید پوشیده بودند، از بشقاب پرنده بیرون آمدند و باز سوار شدند. نورهای آبی و قرمز و سفید به دیوار اتاق می‌خورد. به رختخوابم برگشتم و بعد دیدم که نورها هم حرکت کردند. به خواب رفتم.صبح که بیدار شدم، پدرم گفت:- عجله کن، خانم این بچه را راه‌بنداز.گفتم: «دیشب من دیدم که یک بشقاب پرنده آمده بود توی خیابان ما.» پدرم فقط مادرم را نگاه کرد و مادرم صورتش را برگرداند.چند روز بعد مرا هم به ملاقات پدربزرگ که در بیمارستان بود، بردند. چون پدربزرگ می‌خواست مرا ببیند. راستش پدر بزرگ را هیچ‌وقت آن‌قدر باشکوه ندیده بودم. رویش یک چادر نایلونی کشیده بودند و ده‌ها لوله به او وصل کرده بودند. توی آن اتاق که مثل یک سفینه فضایی بود، پر بود از دستگاه‌هایی که چراغ‌های آن حرکت می‌کردند و چشمک می‌زدند و روشن و خاموش می‌شدند. حیف شد. ما فقط چند دقیقه پدر بزرگ را نگاه کردیم. پدر بزرگ فقط یک انگشت دستش را برای من حرکت داد.من به پدرم گفتم:« پدر بزرگ توی سفینه بود؟» پدرم نگاهی عجیب به من کرد و گفت:- بله، توی سفینه بود.می‌خواهد پرواز کند!گفتم:- مثل کلاغ؟پدرم یک کمی لب ورچید و بعد به آرامی گفت:- نه، مثل یک فضانورد.دو، سه روز بعد وقتی از پله‌ها پایین می‌آمدم، توی آشپزخانه کسی نبود. یک بسته کاغذ که عکس پدر بزرگ روی آن بود گذاشته بودند کنار پنجره و روی آن نوشته بود بزرگ خاندان... بیرون پنجره را نگاه کردم. هیچ کلاغی در آسمان نبود.\r\n"},{"id":2313,"category_id":2,"category_code":"s2","source_id":480,"title":"داستان طوطی ها","content":"یک خانم برای طرح مشکلش به کلیسا رفت .\r\nاو با کشیش ملاقات کرد و برایش گفت: من دو طوطی ماده دارم که فوق العاده زیبا هستند. اما متاسفانه فقط یک جمله بلدند که بگویند «ما دو تا فاحشه هستیم. میای با هم خوش بگذرونیم؟».\r\nاین موضوع برای من واقعا دردسر شده و آبروی من را به خطرا انداخته. از شما کمک میخواهم. من را راهنمایی کنم که چگونه آنها را اصلاح کنم؟\r\nکشیش که از حرفهای خانم خیلی جا خورده بود گفت: این واقعاً جای تاسف دارد که طوطی های شما چنین عبارتی را بلدند... من یک جفت طوطی نر در کلیسا دارم . آنها خیلی خوب حرف میزنند و اغلب اوقات دعا میخوانند. به شما توصیه میکنم طوطیهایتان را مدتی به من بسپارید، شاید در مجاورت طوطی های من آنها به جای آن عبارت وحشتناک یاد بگیرند کمی دعا بخوانند .\r\nخانم که از این پیشنهاد خیلی خوشحال شده بود با کمال میل پذیرفت.\r\nفردای آن روز خانم با قفس طوطی های خود به کلیسا رفت و به اطاق پشتی نزد کشیش رفت. کشیش در قفس طوطی هایش را باز کرد و خانم طوطی های ماده را داخل قفس کشیش انداخت .\r\nیکی از طوطی های ماده گفت: ما دو تا فاحشه هستیم. میای با هم خوش بگذرونیم؟\r\nطوطی های نر نگاهی به همدیگر انداختند. سپس یکی به دیگری گفت: اون کتاب دعا رو بذار کنار، دعاهامون مستجاب شد!\r\n"},{"id":2314,"category_id":2,"category_code":"s2","source_id":481,"title":"نقش زن در پیشرفت مرد","content":"میگویند زنها در موفقیت و پیشرفت شوهرانشان نقش بسزایی دارند.\r\nساعد مراغه ای از نخست وزیران دوران پهلوی نقل کرده بود:\r\nزمانی که نایب کنسول شدم با خوشحالی پیش زنم آمدم و این خبر داغ را به اطلاع سرکار خانم رساندم...\r\nاما وی با بی اعتنایی تمام سری جنباند و گفت «خاک بر سرت کنند؛ فلانی کنسول است؛ تو نایب کنسولی؟!»\r\nگذشت و چندی بعد کنسول شدیم و رفتیم پیش خانم؛ آن هم با قیافهایی حق به جانب...\r\nباز خانم ما را تحویل نگرفت و گفت «خاک بر سرت کنند؛ فلانی معاون وزارت امور خارجه است و تو کنسولی؟!»\r\nشدیم معاون وزارت امور خارجه؛ که خانم باز گفت «خاک بر سرت؛ فلانی وزیر امور خارجه است و تو...؟!»\r\nشدیم وزیر امور خارجه گفت «فلانی نخست وزیر است... خاک بر سرت کنند!!!»\r\nالقصه آنکه شدیم نخست وزیر و این بار با گامهای مطمئن به خانه رفتم و منتظر بودم که خانم حسابی یکه بخورد و به عذر خواهی بیفتد.\r\nتا این خبر را دادم به من نگاهی کرد؛ سری جنباند و آهی کشید و گفت: «خاک بر سر ملتی که تو نخست وزیرش باشی !\r\n"},{"id":2315,"category_id":2,"category_code":"s2","source_id":482,"title":"اعتصاب","content":"سه تا زن انگليسي ، فرانسوي و ایرانی با هم قرار ميزارن كه اعتصاب كنن و ديگه كارای خونه رو نكنن تا شوهراشون ادب بشن و بعد از يك هفته نتيجه كارو بهم بگن.\r\n\r\nزن فرانسوي گفت:\r\nبه شوهرم گفتم كه من ديگه خسته شدم بنابراين نه نظافت منزل، نه آشپزي، نه اتو و نه … خلاصه از اينجور كارا ديگه بريدم. خودت يه فكري بكن من كه ديگه نيستم يعني بريدم! روز بعد خبري نشد ، روز بعدش هم همينطور . روز سوم اوضاع عوض شد، شوهرم صبحانه را درست كرده بود و اورد تو رختحواب من هم هنوز خواب بودم ، وقتي بيدار شدم رفته بود .\r\n\r\nزن انگليسي گفت:\r\nمن هم مثل فرانسوي همونا را گفتم و رفتم كنار. روز اول و دوم خبري نشد ولي روز سوم ديدم شوهرم ليست خريد و كاملا تهيه كرده بود ، خونه رو تميز كرد و گفت كاري نداري عزيزم منو بوسيد و رفت.\r\n\r\nزن ایرانی گفت :\r\nمن هم عين شما همونا رو به شوهرم گفتم\r\nاما روز اول چيزي نديدم\r\nروز دوم هم چيزي نديدم\r\nروز سوم هم چيزي نديدم\r\nشكر خدا روز چهارم يه كمي تونستم با چشم چپم ببينم.\r\n"},{"id":2316,"category_id":2,"category_code":"s2","source_id":483,"title":"پرش از ارتفاع","content":"\r\nمردی در دهکده ی شیوانا زندگی میکرد که علاقه ی شدیدی به پریدن داشت\r\nاو هر روز از ارتفاع پنج متری روی زمین می پرید و هیچ اتفاقی برای او نمی افتاد\r\nاو هرگاه می خواست از ارتفاع به سمت پایین بپرد نگاهش را به سوی آسمان می کرد\r\nو از کائنات می خواست تا او را سالم به زمین برساند و از هر نوع آسیب و صدمه حفظ کند\r\nاتفاقا هم همیشه چنین می شد و هیچ بلایی بر سر او نمی آمد\r\nروزی این مرد به ارتفاع پنج و نیم متری رفت و سرش را به سوی آسمان بالا برد\r\nو از کائنات خواست تا مثل همیشه او را سالم به زمین برساند\r\nاما این باور محکم زمین خورد و پایش شکست\r\nاو آرزده خاطر نزد شیوانا رفت و از او پرسید :\r\nکائنات هیچ وقت جواب رد به خواسته من نمی داد\r\nمن سال ها بود که از ارتفاع پنج متری می پریدم و هیچ اتفاقی برایم نمی افتاد\r\nچرا این بار فقط به خاطر نیم متر اضافه ارتفاع پایم شکست؟\r\nچرا کائنات مرا حفظ نکرد؟\r\nشیوانا تبسمی کرد و گفت :\r\nاتفاقا این دفعه هم کائنات به نفع تو عمل کرد\r\nکائنات چون می دانست که تو بعد از پنج و نیم عدد شش و هفت را انتخاب می کنی\r\nقبل از این که خودت با این زیاده خواهی بی معنا گردنت را بشکنی\r\nپای تو را شکست تا دست از این بازی برداری و روی زمین قرار گیری\r\n"},{"id":2317,"category_id":2,"category_code":"s2","source_id":484,"title":"من اینجا مسافرم","content":"جهانگردی به دهکده ای رفت تا زاهد معروفی را زیارت کند و دید که زاهد در اتاقی ساده زندگی می کند. اتاق پر از کتاب بود و غیر از آن فقط میز و نیمکتی دیده می شد.\r\nجهانگرد پرسید: لوازم منزلتان کجاست؟...\r\nزاهد گفت: مال تو کجاست؟\r\nجهانگرد گفت:من اینجا مسافرم.\r\nزاهد گفت: من هم.\r\n"},{"id":2318,"category_id":2,"category_code":"s2","source_id":485,"title":"خاطرات زمستان را به بهار نیاور","content":"برفها آب شده بودند و دیگر خبری از سرمای زمستان نبود. فصل یخبندان تمام شده بود و کم کم اهالی دهکده شیوانا می توانستند از خانه هایشان بیرون بیایند و در مزارع به کشت وزرع بپردازند. همه از گرمای خورشید بهاری حظ می کردند و از سبزی و طراوت گیاهان لذت می بردند ...\r\nدر آن روز، شیوانا همراه یکی از شاگردان از مزرعه عبور می کرد. پیرمردی را دید که نوه هایش را دور خود جمع کرده و برای آنها در مورد سرمای شدید زمستان و زندانی بودن در خانه و منتظر آفتاب نشستن صحبت می کند.\r\nشیوانا لختی ایستاد و حرفهای پیرمرد را گوش کرد و سپس او را کنار کشید و گفت:\"اکنون که بهار است و این بچه ها در حال لذت بردن از آفتاب ملایم و نسیم دلنواز بهار هستند، بهتر است روایت یخ و سرما را برای آنها نقل نکنی! خاطرات زمستان، خوب یا بد، مال زمستان است. آنها را به بهار نیاور! با این حرف تو بچه ها نه تنها بهار را دوست نخواهند داشت بلکه از زمستان هم بیشتر خواهند ترسید و در نتیجه زمستان سال بعد، قبل از آمدن یخبندان همه این بچه ها از وحشت تسلیم سرما خواهند شد.\r\nبه جای صحبت از بدبختی های ایام سرما، به این بچه ها یاد بده از این زیبایی و طراوتی که هم اکنون اطرافشان است لذت ببرند. بگذار خاطره بهار در خاطر آنها ماندگار شود و برایشان آنقدر شیرین و جذاب بماند که در سردترین زمستان های آینده، امید به بهاری دلنواز، آنها را تسلیم نکند. پیرمرد اعتراض کرد و گفت :\"اما زمستان سختی بود\"\r\nشیوانا با لبخند گفت:\"ولی اکنون بهار است. آن زمستان سخت حق ندارد بهار را از ما بگیرد. تو با کشیدن خاطرات زمستان به بهار، داری بهار را نیز قربانی می کنی! زمستان را در فصل خودش رها کن!\r\n"},{"id":2319,"category_id":2,"category_code":"s2","source_id":486,"title":"علت ناراحتی","content":"\r\nروزی سقراط حکیم مردی را دید که خیلی ناراحت و متاثر بود.\r\nعلت ناراحتی اش را پرسید. شخص پاسخ داد :\r\nدر راه که می آمدم یکی از آشنایان را دیدم. سلام کردم.\r\nجواب نداد و با بی اعتنایی و خودخواهی گذشت و رفت و من از این طرز رفتار او خیلی رنجیدم.\r\nسقراط گفت : چرا رنجیدی ؟\r\nمرد با تعجب گفت: خوب معلوم است که چنین رفتاری ناراحت کننده است.\r\nسقراط پرسید : اگر در راه کسی را می دیدی که به زمین افتاده و از درد به خود می پیچد.\r\nآیا از دست او دلخور و رنجیده می شدی ؟\r\nمرد گفت : مسلم است که هرگز دلخور نمی شدم. آدم از بیمار بودن کسی دلخور نمی شود.\r\nسقراط پرسید: به جای دلخوری چه احساسی می یافتی و چه می کردی؟\r\nمرد جواب داد : احساس دلسوزی و شفقت و سعی می کردم طبیب یا دارویی به او برسانم.\r\nسقراط گفت : همه این کارها را به خاطر آن می کردی که او را بیمار می دانستی.\r\nآیا انسان تنها جسمش بیمار می شود ؟\r\nو آیا کسی که رفتارش نا درست است، روانش بیمار نیست ؟\r\nاگر کسی فکر و روانش سالم باشد هرگز رفتار بدی از او دیده نمی شود؟\r\nبیماری فکری و روان نامش \"غفلت\" است. و باید به جای دلخوری و رنجش نسبت به کسی که بدی می کند و غافل است دل سوزاند و کمک کرد و به او طبیب روح و داروی جان رساند.\r\nپس از دست هیچ کس دلخور مشو و کینه به دل مگیر و آرامش خود را هرگز از دست مده.\r\nبدان که هر وقت کسی بدی می کند در آن لحظه بیمار است.\r\n"},{"id":2320,"category_id":2,"category_code":"s2","source_id":487,"title":"پاکت نامه","content":"آقای اسمیت به تازگی مدیر عامل یک شرکت بزرگ شده بود. مدیر عامل قبلی یک جلسه خصوصی با او ترتیب داد و در آن جلسه سه پاکت نامه دربسته که شماره های ۱ و ۲ و ۳ روی آنها نوشته شده بود به او داد و گفت: هر وقت با مشکلی مواجه شدی که نمی توانستی آن را حل کنی، یکی از این پاکت ها را به ترتیب شماره باز کن.\r\n\r\nچند ماه اول همه چیز خوب پیش می رفت تا این که میزان فروش شرکت کاهش یافت و آقای اسمیت بد جوری به درد سر افتاد. در ناامیدی کامل، آقای اسمیت به یاد پاکت نامه ها افتاد. سراغ گاوصندوق رفت و نامه شماره ۱ را باز کرد. کاغذی در پاکت بود که روی آن نوشته شده بود: همه تقصیرها را به گردن مدیرعامل قبلی بیانداز. آقای اسمیت یک نشست خبری با حضور سهامداران برگزار کرد و همه مشکلات فعلی شرکت را ناشی از سوء مدیریت مدیرعامل قبلی اعلام کرد. این نشست در رسانه ها بازتاب مثبتی داشت و باعث شد که میزان فروش افزایش یابد و این مشکل پشت سر گذاشته شد.\r\n\r\nیک سال بعد، شرکت دوباره با مشکلات تولید توأم با کاهش فروش مواجه شد. آقای اسمیت، با تجربه خوشایندی که از پاکت اول داشت، بی درنگ سراغ پاکت دوم رفت. پیغام این بود: تغییر ساختار بده. اسمیت به سرعت طرحی برای تغییر ساختار اجرا کرد و باعث شد که مشکلات فروکش کند.\r\nبعد از چند ماه شرکت دوباره با مشکلات روبرو شد. آقای اسمیت به دفتر خود رفت و پاکت سوم را باز کرد. پیغام این بود: سه پاکت نامه آماده کن!\r\n"},{"id":2321,"category_id":2,"category_code":"s2","source_id":488,"title":"الماس","content":"داستانی عبرت آموز در مورد زندگی یک زارع پیر افریقایی وجود دارد که به موفقیت زیادی دست یافت، ولی یک روز از شنیدن داستان کسانی که به افریقا می روند به هیجان آمد.\r\nاو مزرعه خود را می فروشد و تصمیم می گیرد به افریقا برود ، معدن الماس کشف کند و به ثروتی افسانه ای دست یابد . او قاره افریقا را در مدت 12 سال زیر پا می گذارد و عاقبت در نتیجه بی پولی ، تنهایی، خستگی و بیماری و ناامیدی ، خود را به درون اقیانوس پرت می کند و غرق می شود.\r\nاز طرف دیگر ، زارع جدیدی که مزرعه او را خریده بود ، هنگامی که به قاطر خود ، در رودخانه ای که از وسط مزرعه اش می گذرد ، آب دهد ، تکه سنگی پیدا می کند که نور درخشانی از خود ساطع می کند.\r\nمعلوم می شود آن سنگ الماسی است که قیمتی بر آن متصور نیست . کسی که الماس را شناخته است از زارع درخواست می کند که او را به مزرعه اش ببرد و محل را به او نشان دهد و زارع او را به محلی که قاطرش را آب داده بود می برد . آنها در آنجا قطعه سنگ های بسیاری از همان نوع پیدا می کنند و بعداً متوجه می شوند که سرتا سر مزرعه پوشیده از فرسنگ ها معدن الماس است.\r\nزارع پیر پیشین بدون آنکه حتی زیر پای خود را نگاه کند برای کشف الماس به جای دیگری رفته بود .\r\nوقتی هدفی را برای خود تعیین می کنید فکر نکنید برای عملی ساختن آن باید سراسر کشور را زیر پا بگذارید ، شغل خود را عوض کنید ....\r\nببینید دقیقاً کجا هستید و از همان جا کار خود را آغاز کنید . در بیشتر موارد میدان های الماس خود را در همان جا خواهید یافت.\r\n"},{"id":2322,"category_id":2,"category_code":"s2","source_id":489,"title":"ارزشش را داشت","content":"دوست دیرینه اش در وسط میدان جنگ افتاده ، می توانست بیزاری و نفرتی که از جنگ تمام وجودش را فرا گرفته ، حس کند.سنگر آنها توسط نیروهای دشمن محاصره شده بود.\r\nسرباز به ستوان گفت که آیا امکان دارد بتواند برود و خودش را به منطقه مابین سنگرهای خود دشمن برساند و دوستش را که آنجا افتاده بود بیاورد؟ ستوان جواب داد: می توانی بروی اما من فکر نمی کنم که ارزشش را داشته باشد، دوست تو احتمالا مرده و تو فقط زندگی خودت را به خطر می اندازی.\r\n\r\nحرف های ستوان را شنید ، اما سرباز تصمیم گرفت برود به طرز معجزه آسایی خودش را به دوستش رساند، او را روی شانه های خود گذاشت و به سنگر خودشان برگرداند ترکش هایی هم به چند جای بدنش اصابت کرد.\r\n\r\nوقتی که دو مرد با هم بر روی زمین سنگر افتادند، فرمانده سرباز زخمی را نگاه کرد و گفت: من گفته بودم ارزشش را ندارد، دوست تو مرده و روح و جسم تو مجروح و زخمی است.\r\nسرباز گفت: ولی ارزشش را داشت ، ستوان پرسید منظورت چیست؟ او که مرده، سرباز پاسخ داد: بله قربان! اما این کار ارزشش را داشت ، زیرا وقتی من به او رسیدم او هنوز زنده بود و به من گفت: می دانستم که می آیی...\r\nمی دانی ؟! همیشه نتیجه مهم نیست . کاری که تو از سر عشق وظیفه انجام می دهی مهم است. مهم آن کسی است یا آن چیزی است که تو باید به خاطرش کاری انجام دهی. پیروزی یعنی همین.\r\n"},{"id":2323,"category_id":2,"category_code":"s2","source_id":490,"title":"عروس و مادر شوهر","content":"دختري ازدواج کرد و به خانه شوهر رفت. ولي هرگز نمي توانست با مادرشوهرش کنار بيايد و هر روز با هم جرو بحث مي کردند.عاقبت يک روز دختر نزد داروسازي که دوست صميمي پدرش بود، رفت و از او تقاضا کرد تا سمي به او بدهد تا بتواند مادر شوهرش را بکشد!داروساز گفت: اگر سم خطرناکي به او بدهد و مادر شوهرش کشته شود، همه به او شک خواهند برد، پس معجوني به دختر داد و گفت که هر روز مقداري از آن را در غذاي مادر شوهر بريزد تا سم معجون کم کم در او اثر کند و او را بکشد. و توصيه کرد تا در اين مدت با مادر شوهر مدارا کند تا کسي به او شک نکند.دختر معجون را گرفت و خوشحال به خانه برگشت و هر روز مقـداري از آن را در غـذاي مادر شوهـر مي ريخت و با مهرباني به او مي داد.هفته ها گذشت و با مهر و محبت عروس، اخلاق مادر شوهر هم بهتر و بهتر شد.تا آنجا که يک روز دختر نزد داروساز رفت و به او گفت: آقاي دکتر عزيز،خیلی حقه بازی با اون معجونت، با دست خفه ش کردم."},{"id":2324,"category_id":2,"category_code":"s2","source_id":491,"title":"سرگذشت دو سنگ ","content":"در يک موزه معروف که با سنگ های مرمر کف پوش شده بود،مجسّمهُ بسيار زيبای مرمرينی را بــــــــه نمايش گذاشته بودند که مردم از راه های دور و نزديک به ديدنش می آمدند کسی نبود که مجسّمهُ زيبا راببيند و لب به تحسين باز نکند یک شب ،سنگ مرمرینی که کف پوش سالن بود ،شروع به حرف زدن با مجسمه کـــــرد وگفت :این منصفانه نیست که همه پا روی من می گذارند تا تورا تحسین کنند !مگر یادت نیست که ما هردو در یک معدن بودیم؟این عادلانه نیست،من خیلی شاکی ام !مجسمه به آرامی لبخند زد و گفت:«یادت هست که وقتی مجســــمه ساز خواست رویت کارکند ،سرسختی کردی ؟»سنگ جواب داد آری ،چون ابزارش به من آسیب می رسانـد و من گمان کرد م که می خواهد آزارم دهد من تحمل این همه درد و رنج را نداشتم » مجسمه با همان لبخند و آرامش ادامه داد:«ولی من فکر کردم که به طور حتم می خواهد ازمن چیزی بی نظیر بسازد و دراین همه رنج حتماً گنجی نهفته است برای همین به مجسمه ساز گفتم که هرچه می خواهی ضربه بزن و صیقل بده لذا دردها و لطمه هایی راکه ابزارش بر من وارد می کردند با جان و دل خریدم وهر چه رنج ها بیشتر می شدند بیشتر تاب می آوردم تا زیبا تر شوم\r\nز مشکلات طریقت عنان متاب ای دل \r\nکه مرد راه نیند یشد از نشیب و فراز\r\n"},{"id":2325,"category_id":2,"category_code":"s2","source_id":492,"title":"نوبل","content":"آلفرد نوبل از جمله افراد معدودی بود که این شانس را داشت تا قبل از مردن، آگهی وفاتش را بخواند!\r\nزمانی که برادرش لودویگ فوت شد، روزنامه‌ها اشتباهاً فکر کردند که نوبل معروف (مخترع دینامیت) مرده است.\r\nآلفرد وقتی صبح روزنامه ها را می‌خواند با دیدن آگهی صفحه اول، میخکوب شد: \"آلفرد نوبل، دلال مرگ و مخترع مر‌گ آور ترین سلاح بشری مرد!\"\r\nآلفرد، خیلی ناراحت شد. با خود فکر کرد: آیا خوب است که من را پس از مرگ این گونه بشناسند؟\r\nسریع وصیت نامه‌اش را آورد. جمله‌های بسیاری را خط زد و اصلاح کرد.\r\nپیشنهاد کرد ثروتش صرف جایزه‌ای برای صلح و پیشرفت‌های صلح آمیز شود.\r\nامروزه نوبل را نه به نام دینامیت، بلکه به نام مبدع جایزه صلح نوبل، جایزه‌ها فیزیک و شیمی نوبل و ... می‌شناسیم.\r\nاو امروز، هویت دیگری دارد.یک تصمیم، برای تغییر یک سرنوشت کافی است!\r\n"},{"id":2326,"category_id":2,"category_code":"s2","source_id":493,"title":"محبت","content":"\r\nزن جوان دستی بر سر پسرک کشید لبخندی زد و گفت :\r\n(خداوند به ما دستور داده بابت محبتی که می کنیم پول در خواست نکنیم.)\r\nپسرک تشکر کرد و رفت . اما این خاطره هیچ گاه از ذهنش پاک نشد.\r\nسالها گدشت و آن پسر برای ادامه تحصیل به پایتخت رفت و توانست در دانشگاه و در رشته پزشکی قبول شود و چند سال بعد مشهورترین متخصص پایتخت شد.\r\nیک روز او در اتاق خود نشسته بود ، از بخش اورژانس با او تماس گرفتند و در خواست کمک کردند . او به محض رو برو شدن بیمار او را شناخت و فوراً دستور داد او را بستری و اتاق عمل را آماده سازند . طی بیست و چهار ساعت او چند عمل حیاتی بر روی قلب پیر زن انجام داد و او را از مرگ حتمی نجات داد.\r\nروزی که زمان ترک بیمارستان فرا رسید و پاکت صورت حساب را مقابل پیرزن قرار دادند او ناراحت بود.\r\nچون او سالها تمام پولش را خرج بیماری خود کرده بود و دیگر پولی نداشت اما وقتی پاکت را باز کرد ، با کمال حیرت صورت حساب را خواند که نوشته شده بود : (خداوند به ما دستور داده بابت محبتی که می کنیم پول در خواست نکنیم.)\r\n"},{"id":2327,"category_id":2,"category_code":"s2","source_id":494,"title":"فرق دیوانه و احمق","content":"مردي در هنگام رانندگي، درست جلوي حياط يک تيمارستان پنچر شد و مجبورشد همانجا به تعويض لاستيک بپردازد.\r\nهنگامي که سرگرم اين کار بود، ماشين ديگري به سرعت از روي پیچ های چرخ که در کنار ماشين بودند گذشت وآنها را به درون جوي آب انداخت و آب پیچ ها را برد.\r\nمرد حيران مانده بود که چکار کند.\r\nتصميم گرفت که ماشينش را همانجارها کند و براي خريد پیچ چرخ برود.\r\nدر اين حين، يکي از ديوانه ها که از پشت نرده هاي حياط تيمارستان نظاره گر اين ماجرا بود، او را صدا زد و گفت:\r\nاز 3 چرخ ديگر ماشين، از هر کدام يک پیچ بازکن و اين لاستيک را با 3 پیچ ببند و برو تا به تعميرگاه برسي.\r\nآن مرد اول توجهي به اين حرف نکرد ولي بعد که با خودش فکر کرد ديد راست مي گويد و بهتر است همين کار را بکند.\r\nپس به راهنمايي او عمل کرد و لاستيک زاپاس را بست.\r\nهنگامي که خواست حرکت کند رو به آن ديوانه کرد و گفت: «خيلي فکر جالب و هوشمندانه اي داشتي، پس چرا توي تيمارستان انداختنت؟ \r\nديوانه لبخندي زد و گفت: من اينجام چون ديوانه ام، ولي احمق که نيستم \r\n"},{"id":2328,"category_id":2,"category_code":"s2","source_id":495,"title":"وام عجیب","content":"مسافری شیک پوش داخل بانک در منهتن نیویورک شد و یک بلیط از دستگاه گرفت . وقتی شماره اش از بلندگو اعلام شد بلند شد و پیش کارشناس بانک رفت و گفت که برای مدت دو هفته قصد سفر تجاری به اروپا را داره و به همین دلیل نیاز به یک وام فوری به مبلغ 5000 دلار داده . کارشناس نگاهی به تیپ و لباس موجه مرد کرد و گفت که برای اعطای وام نیاز به قدری وثیقه و گارانتی دارد و مرد هم سریع دستش را کرد توی جیبش و کلید ماشین فراری جدیدش را که دقیقا جلوی در بانک پارک کرده بود را به کارشناس داد و رئیس بانک هم پس از تطابق مشخصات مالک خودرو بالاخره با وام آقا موافقت کرد آن هم فقط برای دو هفته کارمند بانک هم سریع کلید ماشین گران قیمت را گرفت و ماشین را به پارکینگ بانک در طبقه پائین انتقال داد . \r\nخلاصه مرد بعد از دو هفته همان طور که قرار بود برگشت 5000 دلار + 15.86 دلار کارمزد وام را پرداخت کرد . کارشناس رو به مرد کرد و از قول رئیس بانک گفت : \" از این که بانک ما رو انتخاب کردید متشکریم . \" و گفت ما چک کردیم و معلوم شد که شما یک مولتی میلیونر هستید ولی فقط من یک سوال برام باقی مانده که با این همه ثروت چرا به خودتون زحمت دادین که 5000 دلار از ما وام بگیرید؟\r\nمسافر یه نگاهی به کارشناس بیچاره کرد و گفت : \" تو فقط به من بگو کجای نیویورک می توانم ماشین 250.000 دلاری را برای 2 هفته با اطمینان خاطر و با فقط 15.86 دلار پارک کنم!!!\r\n"},{"id":2329,"category_id":2,"category_code":"s2","source_id":496,"title":"پند دیوانه","content":"مردی در هنگام رانندگی، درست جلوی حياط يک تيمارستان پنچر شد و مجبورشد همانجا به تعويض لاستيک بپردازدهنگامی که سرگرم اين کار بود، ماشين ديگری به سرعت ازروی مهره های چرخ که در کنار ماشين بودند گذشت و\r\nآنها را به درون جوی آب انداخت و آب مهره ها را برد.\r\nمرد حيران مانده بود که چکار کند.\r\nتصميم گرفت که ماشينش را همانجارها کند و برای خريد مهره چرخ برود.\r\nدر اين حين، يکی از ديوانه ها که از پشت نرده های حياط تيمارستان نظاره گر اين ماجرا بود، او را صدا زد و گفت:\r\nاز ٣ چرخ ديگر ماشين، از هر کدام يک مهره بازکن و اين لاستيک را با ٣ مهره ببند و برو تا به تعميرگاه برسی.\r\n\r\nآن مرد اول توجهی به اين حرف نکرد ولی بعد که با خودش فکر کرد ديد راست می گويد و بهتر است همين کار را بکند.\r\nپس به راهنمايی او عمل کرد و لاستيک زاپاس را بست.\r\nهنگامی که خواست حرکت کند رو به آن ديوانه کرد و گفت: «خيلی فکر جالب و هوشمندانه ای داشتی.\r\nپس چرا توی تيمارستان انداختنت؟\r\nديوانه لبخندی زد و گفت: من اينجام چون ديوانه ام. ولی احمق که نيستم!!ا\r\n"},{"id":2330,"category_id":2,"category_code":"s2","source_id":497,"title":"زن و شوهر","content":"یک خانم و یک آقا که سوار قطاری به مقصدی خیلی دور شده بودند، بعد ازحرکت قطار متوجه شدند که در این کوپه درجه یک که تختخواب دار هم میباشد ، با هم تنها هستند و هیچ مسافر دیگری وارد کوپه نخواهد شد.\r\nساعتها سفر در سکوت محض گذشت و مرد مشغول مطالعه و زن مشغول بافتنی بافتن بود.\r\nشب که وقت خواب رسید خانم تخت طبقه بالا و آقا تخت طبقه پایین را اشغال کردند. اما مدتی نگذشته بود که خانم از طبقه بالا، دولا شد و آقا راصدا زد و گفت: ببخشید! میشه یه لطفی در حق من بفرمایید؟\r\nآقا جواب داد : خواهش میکنم!\r\nخانم: من خیلی سردمه. میشه از مهماندار قطار برای من یک پتوی اضافی بگیرید؟\r\nآقا: من یه پیشنهاد دارم\r\nخانم: چه پیشنهادی؟\r\nآقا : فقط برای همین امشب، تصور کنیم که زن و شوهر هستیم\r\nزن : ریزخندی کرد و با شیطنت گفت\r\nچه اشکال داره ، موافقم\r\nآقا : قبول؟\r\nخانم : قبول!\r\nآقا : خب، حالا مثل بچه آدم خودت پاشو ، برو از مهموندار پتو بگیر. من خوابم میآد . دیگه هم مزاحم من نشو\r\n"},{"id":2331,"category_id":2,"category_code":"s2","source_id":498,"title":"مارتین لوتر","content":"در قرون وسطی کشیشان، بهشت را به مردم می فروختند و مردمان نادان هم با پرداخت پول، قسمتی از بهشت را از آن خود می کردند . . .\r\nفرد دانایی که از این نادانی مردم رنج می برد دست به هر عملی زد نتوانست مردم را از انجام این کار احمقانه باز دارد تا اینکه فکری به سرش زد. به کلیسا رفت و به کشیش مسئول فروش بهشت گفت:\r\n- قیمت جهنم چقدره؟\r\nکشیش تعجب کرد و گفت: جهنم؟!\r\nمرد دانا گفت: بله جهنم.\r\nکشیش بدون هیچ فکری گفت: ۳ سکه\r\nمرد فوری مبلغ را پرداخت کرد و گفت: لطفا سند جهنم را هم بدهید.\r\nکشیش روی کاغذ پاره ای نوشت: سند جهنم\r\nمرد با خوشحالی آن را گرفت از کلیسا خارج شد. به میدان شهر رفت و فریاد زد:\r\n- ای مردم! من تمام جهنم را خریدم و این هم سند آن است. دیگر لازم نیست بهشت را بخرید چون من هیچ کسی را داخل جهنم راه نمی دهم.\r\n\r\nاسم ان مرد، کشیش مارتین لوتر بود\r\n"},{"id":2332,"category_id":2,"category_code":"s2","source_id":499,"title":"مساله","content":"استادی وارد کلاس شد. سه رقم ٢ و ٤ و ٨ را روی تخته سیاه نوشت و سپس رو به شاگردان کرد و پرسید:« خوب، پاسخ چیست؟»\r\nبرخی از شاگردان گفتند:« جمعش می شود ١٤.»\r\nاستاد سرش را به علامت منفی تکان داد.\r\nبرخی دیگر گفتند:«یه تصاعد عددی است و عدد بعد هم می شود ١٦.»\r\nاستاد سرش را به علامت منفی تکان داد.\r\nعده ای که در ته کلاس نشسته بودند گفتند:«جوابش می شود ٦٤.»\r\nباز سرش را به علامت منفی تکان داد و گفت:«نه.» همه ی شما در دادن پاسخ عجله کردید.هیچکدام نپرسیدید:«مسأله چیست؟\r\nمادامی که این سوال کلیدی را نپرسیده باشید نه تنها قادر به تشخیص مسأله نخواهید بود بلکه پاسخ آن را هم نخواهید یافت.»\r\nحق با استاد است اين امر به قدري ساده و پيش پا افتاده است كه اغلب به فراموشي سپرده مي شود . اكثريت قريب به اتفاق ما در غالب موارد بدون آنكه اطلاع درستي از صورت مسأله اي داشته باشيم پاسخ فوري به آن مي دهيم .\r\n\r\nنكته : درك مشكل مساوي با حل آن نيست اما چنانچه مشكلي را خوب درك نكنيد هرگز راه حلي را نيز براي آن نخواهيد يافت . \r\n___________________________\r\nمشكلي كه خوب تشريح و حلاجي شده باشد ، نصفش حل شده است .\r\n"},{"id":2333,"category_id":2,"category_code":"s2","source_id":500,"title":"طناب نازک","content":"از مقابل چند فیل رد می شدم . نظرم به موضوع جالبی جلب شد .متوجه شدم که این حیوانات عظیم الجثه با یک طناب نازک که به پای آنها بسته شده مهار شده اندنه زنجیری ونه قفسی .کاملا مشخص بود که این حیوان هر لحظه اراده کند می توانداین طناب را پاره وسپس فرار کنداما فیل اصلاتلاشی برای پاره کردن این طناب از خود نشان نمی داد.\r\n\r\nچشمم به مربی فیلها افتاد.نزداو رفتم وسوالم را مطرح کردم.مربی گفت هنگامی که این فیلها بسیار کوچک بودند پایشان را می بستم که فرارنکنند.\r\n\r\nآنها آن موقع این موضوع رادرک کرده بودندکه هیچگاه نخواهند توانست این طناب را پاره کنند.الان هم که بزرگ شده اندبنا بر همان باور قبلی تلاشی برای پاره کردن طنابها نمی کنند... \r\n\r\nنتیجه اخلاقی :\r\nشاید بسیاری از ما انسانها در طول زندگی دچار عادات وباورهای غلط شده باشیم که از رشد وارتقایافتنمان جلوگیری میکنند . باورهای غلط را دور بریزیم .\r\n"},{"id":2334,"category_id":2,"category_code":"s2","source_id":501,"title":"واقعیت زندگی","content":"روزی شاگردی به استاد خویش گفت:استاد می خواهم یکی از مهمترین خصایص انسان ها را به من بیاموزی؟استاد گفت: واقعا می خواهی آن را فرا گیری؟شاگرد گفت:بله با کمال میل.استاد گفت:پس آماده شو با هم به جایی برویم.شاگرد قبول کرد.استاد شاگرد جوانش را به پارکی که در آّن کودکان مشغول بازی بودند،برد.استاد گفت:....\r\nخوب به مکالمات بین کودکان گوش کن.مکالمات بین کودکان به این صورت بود:\r\n-الان نوبت من است که فرار کنم و تو باید دنبال من بدوی.\r\n-نخیر الان نوبت توست که دنبالم بدوی.\r\n-اصلا چرا من هیچوقت نباید فرار کنم؟\r\nو حرف هایی از این قبیل...\r\n\r\nاستاد ادامه داد:همانطور که شنیدی تمام این کودکان طالب آن بودند که از دست دیگری فرار کنند.انسان نیز این گونه است.او هیچگاه حاضر نیست با شرایط موجود رو به رو شود و دائم در تلاش است از حقایق و واقعیات زندگی خود فرار کند و هرگز کاری برای بهبود زندگی خود انجام نمی دهد.تو از من خواستی یکی از مهم ترین ویژگی های انسان را برای تو بگویم و من آن را در چند کلام خلاصه میکنم:تلاش برای فرار از زندگی.\r\n"},{"id":2335,"category_id":2,"category_code":"s2","source_id":502,"title":"مسئولیت پذیری","content":"در یک جلسه ی فروش، مدیر فروش بابت میزان فروش بسیار کم کارمندان به آنان پرخاش کرد و گفت: تا دلتان بخواهد بازدهی کم داشتیم و عذر و بهانه فراوان اگه نمی توانید از پس کارتان بربیایید، گمان میکنم کسان دیگری باشند که منتظر فرصت هستند تا محصولات ارزشمندی را که شما افتخار ارائه شان را داشته اید بفروشند؛\r\nپس رو به بازیکن حرفه ای فوتبال بازشسته ای که به تازگی استخدام شده بود کرد و گفت: اگر یک تیم فوتبال ببازد چه میشود؟ بازیکن ها را عوض میکنند، نه!\r\nسنگینی سوال باعث چند ثانیه سکوت شد. سپس بازیکن سابق فوتبال گفت: راستش جناب، اگر کل تیم مشکل داشته باشند معمولا مربی جدید میگیریم!!!\r\n"},{"id":2336,"category_id":2,"category_code":"s2","source_id":503,"title":"خودت رو دست کم نگیر","content":"گروه کُر مدرسه ای برای اجرای کنسرت در مرکز شهر آماده شده بود. هوا خیلی سرد بود.\r\nچندساعتی در آن هوا منتظر ماندند. مردم جمع شده بودند.\r\nرهبر ارکستر برای رهبری گروه در جای خود مستقر شد.\r\nدر این میان یکی از اعضای گروه با خود چنین گفت: در این سرما نمی توانم آواز بخوانم. پنجاه نفر در گروه وجود دارد، اگر فقط دهانم را باز و بسته کنم، کسی متوجه نمی شود.\r\nو رهبر ارکستر کارش را شروع کرد. اما صدایی نشنید چون آن روز همه مثل هم فکر کرده بودند :\r\n\"اگر من نخوانم چه می شود؟\"\r\n"},{"id":2337,"category_id":2,"category_code":"s2","source_id":504,"title":"جاده","content":"یک بنده خدایی، کنار اقیانوس قدم میزد و زیر لب، دعایی را هم زمزمه میکرد. نگاهى به آسمان آبى و دریاى لاجوردی و ساحل طلایى انداخت و گفت :\r\n- خدایا ! میشود تنها آرزوى مرا بر آورده کنى ؟\r\nناگاه، ابرى سیاه، آسمان را پوشاند و رعد و برقى در گرفت و در هیاهوى رعد و برق، صدایى از عرش اعلى بگوش رسید که میگفت :\r\n- چه آرزویى دارى اى بنده ى محبوب من ؟\r\nمرد، سرش را به آسمان بلند کرد و ترسان و لرزان گفت :\r\n- اى خداى کریم ! از تو مى خواهم جاده اى بین کالیفرنیا و هاوایی بسازى تا هر وقت دلم خواست در این جاده رانندگى کنم !\r\nاز جانب خداى متعال ندا آمد که :\r\n- اى بنده ى من ! من ترا بخاطر وفادارى ات بسیار دوست میدارم و مى توانم خواهش ترا بر آورده کنم، اما، هیچ میدانى انجام تقاضاى تو چقدر دشوار است ؟ هیچ میدانى که باید فرمان دهم تا فرشتگانم روى اقیانوس آرام را آسفالت کنند ؟ هیچ میدانى چقدر آهن و سیمان و فولاد باید مصرف شود ؟ من همه ى اینها را مى توانم انجام بدهم، اما، آیا نمى توانى آرزوى دیگرى بکنى ؟\r\nمرد، مدتى به فکر فرو رفت، آنگاه گفت :\r\n- اى خداى من! من از کار زنان سر در نمى آورم ! میشود به من بفهمانى که زنان چرا می گریند؟ میشود به من بفهمانى احساس درونى شان چیست ؟ اصلا میشود به من یاد بدهى که چگونه مى توان زنان را خوشحال کرد؟\r\nصدایی از جانب باریتعالى آمد که : اى بنده من ! آن جاده اى را که خواسته اى، دو بانده باشد یا چهار بانده ؟\r\n"},{"id":2338,"category_id":2,"category_code":"s2","source_id":505,"title":"قول پدرانه","content":"در سال 1989 زمین لرزه هشت و دو ریشتر بیشتر مناطق آمریکا را با خاک یکسان کرد و در کمتر از چند دقیقه بیش از سی هزار کشته بر جای گذاشت.\r\nدر این میان پدری دیوانه وار به سوی مدرسه پسرش دوید اما با دیدن ساختمان ویران شده مدرسه شوکه شد.با دیدن این منظره دلخراش یاد قولی که به پسرش داده بود افتاد: پسرم هر اتفاقی برایت بیفتد من همیشه پیش تو خواهم بود و اشک از چشمانش سرازیر شد. \r\nبا وجود توده آوار و انبوه ویرانی ها کمک به افراد زیر آوار نا ممکن به نظر میرسید اما او هر لحظه تعهد خود به پسرش را به خاطر می آورد. \r\nاو دقیقا روی مسیری که هر صبح به همراه پسرش به سوی کلاس او می پیمودند تمرکز کرد و با به خاطر آوردن محل کلاس به آنجا شتافته و با عجله شروع به کندن کرد. \r\nدیگر والدین در حال ناله و زاری بودند و او را ملامت می کردند که کار بی فایده ای انجام میدهد.ماموران آتش نشانی و پلیس نیز سعی کردند او را منصرف کنند اما پاسخ او تنها یک جمله بود:آیا قصد کمک به مرا دارید یا باید تنها تلاش کنم؟؟؟ \r\nهشت ساعت به کندن ادامه داد.دوازده ساعت... بیست و چهار ساعت...سی و شش ساعت و بالاخره در سی و هشتمین ساعت سنگ بزرگی را عقب کشیده و صدای پسرش را شنید فریاد زد پسرم!جواب شنید : \r\nپدر من اینجا هستم.پدر من به بچه ها گفتم نگران نباشید پدرم حتما ما را نجات خواهد داد. پدر! شما به قولتان عمل کردید. \r\nپدر پرسید وضع آنجا چطور است؟؟ \r\nما 14 نفر هستیم ما زخمی گرسنه و تشنه ایم. وقتی ساختمان فرو ریخت یک قطعه مثلثی شکل ایجاد شد که باعث نجات ما شد. \r\nپسرم بیا بیرون.نه پدر اجازه بدهید اول بقیه بیرون بیایند من مطمئن هستم شما مرا بیرون می آورید و هر اتفاقی بیفتد به خاطر من آنجا خواهید ماند...\r\n"},{"id":2339,"category_id":2,"category_code":"s2","source_id":506,"title":"گریه و زاری","content":"در روزگاري نه چندان دور شبی از شبها، شاگردی در حال عبادت و گریه و زاری بود. مدتي در اين حال بود كه استاد خود را، بالای سرش دید، استاد با تعجب و حیرت؛ او را، نظاره می کرد!\r\nبعد از اندكي مكث استاد پرسید: برای چه این همه ابراز ناراحتی و گریه و زاری می کنی؟\r\nشاگرد گفت: برای طلب بخشش و گذشت خداوند از گناهانم، و برخورداری از لطف خداوند!\r\nاستاد گفت: سوالی می پرسم ، پاسخ ده.\r\nشاگرد گفت: با کمال میل؛ استاد.\r\nاستاد گفت: اگر مرغی را، پروش دهی، هدف تو از پرورشِ آن چیست؟\r\nشاگرد گفت: خوب معلوم است استاد؛ برای آنکه از گوشت و تخم مرغ آن بهره مند شوم .\r\nاستاد گفت: اگر آن مرغ، برایت گریه و زاری کند، آیا از تصمیم خود، منصرف خواهی شد؟\r\nشاگردگفت: خوب راستش نه...! نمیتوانم هدف دیگری از پرورش آن مرغ، برای خود، تصور کنم!\r\nاستاد گفت: حال اگر این مرغ، برایت تخم طلا كند چه؟ آیا باز هم او را، خواهی کشت، تا از آن بهره مند گردی؟!\r\nشاگرد كمي فكر كرد و گفت: نه هرگز استاد، مطمئنا آن تخمها، برایم مهمتر و با ارزش تر، خواهند بود!\r\nاستاد گفت: پس تو نیز؛ برای خداوند، چنین باش! همیشه تلاش کن، تا با ارزش تر از جسم، گوشت، پوست و استخوانت؛ گردی.\r\nتلاش کن تا آنقدر برای انسانها، هستی و کائنات خداوند، مفید و با ارزش شوی تا مقام و لیاقتت توجه، لطف و رحمتِ او را، بدست آورد.\r\nخداوند از تو گریه و زاری نمی‌خواهد! او، از تو حرکت، رشد، تعالی، و با ارزش شدن را می خواهد ومی پذیرد، نه ابرازِ ناراحتی و گریه و زاری را.....!!!\r\n"},{"id":2340,"category_id":2,"category_code":"s2","source_id":507,"title":"لذت بردن","content":"دو میمون روی شاخه درختی نشسته بودند و به غروب خورشید نگاه میکردند. یکی از دیگری پرسید: چرا هنگام غروب رنگ آسمان تغییر میکند؟ میمون دوم گفت: اگر بخواهیم همه چیز را توضیح بدهیم، مجالی برای زندگی نمی ماند. گاهی اوقات باید بدون توضیح از واقعیتی که در اطرافت میبینی، لذت ببری... میمون اول با ناراحتی گفت: تو فقط به دنبال لذت زندگی هستی و هیچ وقت نمی خواهی واقعیتها را با منطق بیان کنی !!! در همین حال هزار پایی از کنار آنها میگذشت...\r\nمیمون اول با دیدن هزار پا از او پرسید: هزار پا، تو چگونه این همه پا را با هماهنگی حرکت میدهی؟\r\nهزارپا جواب داد: تا به امروز راجع به این موضوع فکر نکرده ام ؟!\r\nمیمون دوم گفت: خوب فکر کن چون این میمون راجع به همه چیز توضیح منطقی میخواهد!\r\nهزار پا نگاهی به پاهایش کرد و خواست توضیحی بدهد: خوب اول این پا را حرکت میدهم، نه، نه. شاید اول این یکی را. باید اول بدنم را بچرخانم ... هزار پا مدتی سعی کرد تا توضیح مناسبی برای حرکت دادن پاهایش بیان کند ولی هرچه بیشتر سعی میکرد، ناموفقتر بود.\r\nپس با ناامیدی سعی کرد به راه خودش ادامه دهد، ولی متوجه شد که نمیتواند. با ناراحتی گفت: ببین چه بلایی به سرم آوردی؟! آنقدر سعی کردم چگونگی حرکتم را توضیح دهم که راه رفتن یادم رفت!!!\r\nمیمون دوم به اولی گفت: میبینی؟! وقتی سعی میکنی همه چیز را توضیح دهی اینطور میشود...! پس دوباره به غروب آفتاب خیره شد تا از آن لذت ببرد...\r\n"},{"id":2341,"category_id":2,"category_code":"s2","source_id":508,"title":"داستان والنتاین","content":"در قرن سوم میلادی که مطابق می شود با اوایل امپراطوری ساسانی در ایران ، در روم باستان فرمانروایی بوده است به نام کلودیوس دوم . کلودیوس ، عقاید عجیبی داشت ، از جمله اینکه سربازی خوب خواهد جنگید که مجرد باشد ؛ از این رو ازدواج را برای سربازان امپراطوری روم قد غن می کند. کلودیوس به قدری بی رحم و فرمانش به اندازه ای قاطع بود که هیچ کس جرات کمک به ازدواج سربازان نداشت . اما کشیشی به نام والنتیوس ( همان ولنتاین خودمان ) ، مخفیانه عقد سربازان رومی را با دختران محبوبشان جاری می کرد . کلودیوس دوم از این جریان خبر دار می شود و دستور می دهد که ولنتاین را به زندان بیاندازند . ولنتاین در زندان عاشق دختر زندان بان می شود . سرانجام کشیش به جرم جاری کردن عقد عشاق با قلبی عاشق اعدام می شود . . .\r\nبنابراین او را به عنوان فدایی و شهید راه عشق می دانند و از آن زمان نهاد و سمبلی می شود برای عشق !\r\n"},{"id":2342,"category_id":2,"category_code":"s2","source_id":509,"title":"پسر شیطون","content":"پسربچه صبح از پله ها اومد پائین و ازمادربزرگش پرسید : \" بابا ماما هنوز از خواب بیدار نشدند ؟ \"\r\n- نه عزیز دلبندم. بیا صبحونه ات رو آماده کردم ، زود باش بخورش تا مدرسه ات دیر نشده\r\nپسرک یک خنده شیطنت آمیزی زد و بدون اینکه چیزی بگه سریع رفت آشپزخونه و صبحونه اش رو تموم کرد و پس از مسواک زدن دندونهاش ، کیفش رو برداشت و پرید دم در تا سوار سرویس بشه\r\nظهر شد . زنگ در به صدا در اومد . مادر بزرگ در رو باز کرد . پسره بود که از مدرسه برمیگشت . یه سلامی داد و بازم پرسید : \" بالاخره مامان و بابا بیدار شدند ؟ \"\r\nمادربزرگ گفت : \" نه عزیزم ، حتما خیلی خسته بودند . فکر کنم الانه پا میشن میان . حالا بیا تو ناهارت رو بخور تا از دهن نیفتاده \"\r\n... پسرک بازم اون لبخند شیطنت آمیز رو زد و داخل شد . ناهارش رو خورد و رفت تو اطاقش تا مشقهاشو بنویسه و کمی هم استراحت کنه\r\nبعد از ظهر بود که پسره اومد پیش مادربزرگش و ازش پرسید : \" بابا مامان هنوزهم نیومدند ؟ \"\r\nمادربزرگ که داشت یواش یواش نگران میشد گفت : \" نه ؟ \"\r\nپسرک اینبار دیگه نتونست جلو خودش رو بگیره و زد زیر خنده\r\nمادربزرگ عصبانی شد و سرش قریاد کشید : \" تو چت شده ؟ چرا هر بار که اینو میپرسی ، میخندی ؟ \"\r\nبچه جواب داد : \" شب دیر خیلی وقت بو دو منم داشت خوابم میبرد که یهو دیدم بابا اومده تو اطاقم و دنبال یه چیزی گشت \"\r\n- خوب دنبال چی میگشت ؟\r\nپسره ادامه داد : \" بابا گفتش کف پاش ترک برداشته واسه همین دنبال کرم نرم کننده و مرطوب کننده میگرده ! \"\r\n- بعدش چی شد ؟\r\nپسرک در حالیکه که چشمهاش برق عجیبی میزد گفت : \" هیچی مامان بزرگ، چون اطاق تاریک بود ، به جای کرم ، اشتباهی تیوب چسب فوری رو بهش دادم ! \"\r\n"},{"id":2343,"category_id":2,"category_code":"s2","source_id":510,"title":"امتحان فیزیک","content":"\r\nاستاد سختگیر فیزیک اولین دانشجو را برای پرسش فرا میخواند و سئوال را مطرح میکند\r\nشما در قطاری نشسته اید که با سرعت هشتاد کیلومتر در ساعت حرکت میکند و ناگهان شما گرما زده شده اید، حالا چکار میکنید؟\r\nدانشجوی بی تجربه فورا ً جواب میدهد\r\nمن پنجره کوپه را پائین میکشم تا باد بوزد\r\nاکنون پروفسور میتواند سئوال اصلی را بدینترتیب مطرح کند\r\nحال که شما پنجره کوپه را باز کرده اید....\r\nدر جریان هوای اطراف قطار اختلال حاصل میشود\r\nو لازم است موارد زیر را محاسبه کنید\r\nمحاسبه مقا ومت جدید هوا در مقابل قطار؟\r\nتغییر اصطکاک بین چرخها و ریل؟\r\nآیا در اثر باز کردن پنجره، سرعت قطار کم میشود و اگر آری، به چه اندازه؟\r\nحسب المعمول دهان دانشجو باز مانده بود و قادر به حل این مسئله نبود و سرافکنده جلسه امتحان را ترک کرد\r\nهمین بلا سر بیست دانشجوی بعدی هم آمد که همگی در امتحان شفاهی فیزیک مردود شدند\r\nپروفسور آخرین دانشجو را برای امتحان فرا میخواند و طبق معمول سئوال اولی را میپرسد\r\nشما در قطاری نشسته اید که با سرعت هشتاد کیلومتر در ساعت حرکت میکند و ناگهان شما گرما زده شده اید، حالا چکار میکنید؟\r\nاین دانشجوی خبره میگوید؛ من کتم را در میارم\r\nپروفسور اضافه میکند که هوا بیش از اینها گرمه\r\nدانشجو میگه خوب ژاکتم را هم در میارم\r\nهوای کوپه مثل حمام زونا داغه\r\nدانشجو میگه اصلا ً لخت مادر زاد میشم\r\nپروفسور گوشزد میکند که دو آفریقائی نکره و نانجیب در کوپه هستند و منتظرند تا شما لخت شی\r\nدانشجو به آرامی میگوید\r\nمیدانید آقای پروفسور، این دهمین بار است که من در امتحان شفاهی فیزیک شرکت میکنم واگر قطار مملو از آفریقائیهای ... باشد، من آن پنجره لامصب را باز نمیکنم\r\n"},{"id":2344,"category_id":2,"category_code":"s2","source_id":511,"title":"شرط بندی","content":"\r\nیه روز یه نفر میاد توی یه فروشگاه و به فروشنده میگه :آقا من میخوام باهات سر 500 دلار شرط ببندم که میتونم از تهِ فروشگاهت با شیلنگ , آب بریزم توی این لیوانی که اینجاست ....\r\nفروشنده میگه : باشه مشکلی نیست ...\r\nیارو میره ته فروشگاه و شیلنگ آب رو باز میکنه و آبو میریزه به کل فروشگاه . همه جارو خیس میکنه و هیچی هم توی لیوان نمیریزه ...\r\nفروشنده خوشحال میشه و میگه : تو باختی ... 500 دلارو رد کن بیاد .\r\nیارو در حالی که داشت میخندید 500 دلارو داد به فروشنده ...\r\nفروشنده گفت : چرا میخندی؟ تو الان 500 دلار باختی ...!!\r\nیارو میگه : اونو میبینی اونور خیابون وایساده ؟ \r\nمن با اون سرِ 10 هزار دلار شرط بستم که میتونم بیام توی فروشگاهت و همه جارو خیس کنم و هیچ دعوایی هم نشه ....\r\nو حالا شرطو بردم ... \r\n"},{"id":2345,"category_id":2,"category_code":"s2","source_id":512,"title":"قوانین بهشت","content":"\r\nسه تا زن توی تصادفی کشته شدن و سه تاشون رفتن بهشت!\r\nدمِ درِ بهشت مامور نگهبان گفت:\r\nشما آزادید هر کاری بکنید ، تنها قانون اینجا اینه که : روی اردک ها پا نذارین!\r\nزنها قبول کردن و رفتن توی بهشت. \r\nخیلی زیبا و سرسبز بود ولی همه جا پر از اردک بود!\r\nهمونجا اولین زن پاش رفت روی یه اردک و ازدک له شد...\r\nمامور نگهبان همون لحظه همراه با یه مرد خیلی بدقیافه اومد و گفت :\r\nتو قانون رو نقض کردی و برای تنبیهت باید تا ابد با این مرد بمونی ...\r\nفردا اون روز ، زن دوم پاش رفت روی اردک و مامور نگهبان سریع اومد و همراهش یه مرد زشت دیگه بود و گفت : \r\nتوام قانون رو نقض کردی و باید تا ابد با این مرد بمونی برای تنبیه ...\r\nزن سوم که اینا رو دیده بود خیلی ترسید و حواسشو جمع کرد که پاشو روی اردک ها نذاره!\r\nچند ماه همینجوری گذشت که یه روز نگهبان با یه مرد فوق العاده خوش تیپ و زیبا اومد!نگهبان رو به زن کرد و گفت : شما باید تا ابد پیش همدیگه بمونید ...\r\nزن که توی عمرش همچین مردی ندیده بود با ذوق از مرده پرسید : \r\nواااای من نمیدونم چیکار کردم که پاداشم تو هستی ..!\r\nمرده گفت : منم چیزی نمیدونم ! فقط میدونم که یه اردک رو له کردم ..!\r\n"},{"id":2346,"category_id":2,"category_code":"s2","source_id":513,"title":"مقاومت","content":"\r\nیه زندانی فراری وارد یه خونه ای میشه که پول و غذا گیر بیاره.\r\nاونجا یه زن و مرد و توی تختخواب میبینه !\r\nدستای مردو بالای تخت میبنده و زنشو به صندلی طناب پیچ\r\nمیکنه ،بعد نزدیک خانوم میشه و گردنشو میبوسه و میره دوش بگیره!\r\nمرد به زنش میگه:\r\nگوش کن عشق من!این معلومه که مدت زیادیه با زنی نبوده،\r\nمن دیدم چطور گردنتو ماچ کرد!اگه خواست با تو سکس\r\nداشته باشه با وجودیکه میدونم برات چندش آوره ولی\r\nتو رو خدا مقاومت نکن وگرنه جفتمونو میکشه!\r\nقوی باش عزیزم و بدون من خیلی دوست دارم !\r\nزن جواب میده : اون گردنِ منو ماچ نکرد!به من گفت که همجنس گراست!\r\nو معتقده تو خیلی نازی و از من پرسید :وازلین داریم و من گفتم توی حمومه !\r\nبنابراین عزیزم قوی باش و بدون من خیلی دوست دارم ...!\r\n"},{"id":2347,"category_id":2,"category_code":"s2","source_id":514,"title":"راز زندگي","content":"در افسانه ها آمده روزي که خداوند جهان را آفريد فرشتگان مقرب را به بارگاه\r\nخود فرا خواند و از آنها خواست تا براي پنهان کردن راز زندگي پيشنهاد بدهند∙\r\nيکي از فرشتگان به پروردگار گفت:خداوندا آنرا در زير زمين مدفون کن∙\r\nفرشته ديگري گفت آن را در زير درياها قرار بده∙\r\nو سومي گفت راز زندگي را در کوهها قرار بده∙\r\nولي خداوند فرمود اگر من بخواهم به گفته هاي شما عمل کنم فقط تعداد\r\nکمي از بندگانم قادر خواهند بود آن را بيابند در حالي که من مي خواهم راز\r\nزندگي در دسترس همه بندگانم باشد∙\r\nدر اين هنگام يکي از فرشتگان گفت فهميدم کجاهي خداي مهربان راز\r\nزندگي را در قلب بندگانت قرار بده زيرا هيچ کس به اين فکر نمي افتد که\r\nبراي پيدا کردن آن بايد به قلب و درون خودش نگاه کند∙\r\nو خداوند اين فکر را پسنديد∙\r\n"},{"id":2348,"category_id":2,"category_code":"s2","source_id":515,"title":"جعبه های سیاه و طلایی ","content":"\r\nدر دستانم دو جعبه دارم که خدا به من داده است. او گفت:غصه هایت را درون جعبه سیاه بگذار و شادی هایت را درون جعبه طلایی.به حرف خدا گوش کردم.شادی ها و غصه هایم را درون جعبه ها گذاشتم. جعبه طلایی روز به روز سنگین تر می شد و جعبه سیاه روز به روز سبک تر. \r\nاز روی کنجکاوی جعبه سیاه را باز کردم تا علت را دریابم.دیدم که ته جعبه سوراخ است و غصه هایم از آن بیرون می ریزد.سوراخ جعبه را به خدا نشان دادم و گفتم:در شگفتم که غصه های من کجا هستند؟خدا با لبخندی دلنشین گفت:ای بنده من!همه آنها نزد من٬ اینجا هستند. \r\nپرسیدم پروردگارا!چرا این جعبه ها را به من دادی؟چرا ته جعبه سیاه سوراخ بود ؟گفت:ای بنده من!جعبه طلایی را به تو دادم تا نعمت های خود را بشماری و جعبه سیاه را برای اینکه غم هایت را دور بریزی... \r\n"},{"id":2349,"category_id":2,"category_code":"s2","source_id":516,"title":"کیک مادر بزرگ","content":"پسر کوچکی برای مادر بزرگش توضیح می‌داد که چگونه همه چیز ایراد دارد ... مدرسه، خانواده، دوستان و غیره.\r\nمادر بزرگ که مشغول پختن کیک بود، از پسر کوچولو پرسید که کیک دوست داری؟ و پسر کوچولو پاسخ داد: البته که دوست دارم.\r\nـ روغن چه طور؟\r\nـ نه!\r\nـ و حالا دو تا تخم مرغ.\r\nـ نه مادر بزرگ!\r\nـ آرد چی؟ از آرد خوشت می‌آید؟ جوش شیرین چه طور؟\r\nـ نه مادر بزرگ! حالم از همه‌شان به هم می خورد.\r\nـ بله، همه این چیزها به تنهایی بد به نظر می‌رسند، اما وقتی به درستی با هم مخلوط شوند، یک کیک خوشمزه درست می‌شود.\r\nخداوند هم به همین ترتیب عمل می‌کند. خیلی از اوقات تعجب می‌کنیم که چرا خداوند باید بگذارد ما چنین دوران سختی را بگذرانیم اما او می‌داند که وقتی همه این سختی‌‌ها را به درستی در کنار هم قرار دهد نتیجه همیشه خوب است. ما تنها باید به او اعتماد کنیم. در نهایت همه این پیش آمدها با هم به یک نتیجه فوق العاده می‌رسند.\r\n"},{"id":2350,"category_id":2,"category_code":"s2","source_id":517,"title":"چوپان و عسل ","content":"چوپاني مشغول آب دادن به گوسفندانش کنار رودخانه بود که چشمش به زني که لخت در رودخانه مشغول آب تني بود افتاد ، چوپان که مدتها در صحرا بود و طاقت از کف داده بود زن را بارها و به مدت چندين ساعت مورد تجاوز قرار داد\r\nزن که يک توريست خارجي بود به پليس شکايت برد و پليس چوپان را دستگير کرد و مورد بازجويي قرار داد و چوپان هم به جرم خود اعتراف کرد ولي زن که از تجاوز چوپان چندان هم ناراضي نبود پيشنهادي به چوپان کرد که اگر با او ازدواج کند و به کشور زن بروند او هم از شکايتش صرف نظر ميکند در غير اين صورت چوپان بايد به زندان برود\r\nچوپان که عيالوار بود پيشنهاد زن را نپذيرفت ولي گفت که برادري دارد که مجرد است و اگر زن بخواهد شايد قبول کند که با او ازدواج کند و به کشور زن برود ، زن پرسيد :\r\nآيا اون هم مثل تو قوي بنيه و خوش هيکله ، منظور منو که ميفهمي ؟\r\nچوپان در حالي که گونه هايش به سرخي مي گراييد پاسخ داد :\r\nنميدونم چي بگم ، فقط يادمه دو سال پيش به يه خرس تجاوز کرد ، خرسه دو ساله برامون عسل مياره !\r\n"},{"id":2351,"category_id":2,"category_code":"s2","source_id":518,"title":"طعم مهربانی","content":"\r\nروزی فردی جوان هنگام عبور از بیابان، به چشمه آب زلالی رسید\r\nآب به قدری گوارا بود که مرد سطل چرمی اش را پر از آب کرد تا بتواند مقداری از آن آب را برای استادش که پیر قبیله بود ببرد.\r\nمرد جوان پس از مسافرت چهار روزه اش، آب را به پیرمرد تقدیم کرد.\r\nپیرمرد، مقدار زیادی از آب را لاجرعه سر کشید و لبخند گرمی نثار مرد جوان کرد و از او بابت آن آب زلال بسیار قدردانی کرد.\r\nجوان با دلی لبریز از شادی به روستای خود بازگشت.\r\nاندکی بعد، استاد به یکی دیگر از شاگردانش اجازه داد تا از آن آب بچشد.\r\nشاگرد آب را از دهانش بیرون پاشید و گفت: آب بسیار بد مزه است.\r\nظاهرا آب به علت ماندن در سطل چرمی، طعم بد چرم گرفته بود. شاگرد با اعتراض از استاد پرسید:\r\nآب گندیده بود. چطور وانمود کردید که گوارا است؟\r\nاستاد در جواب گفت:\r\nتو آب را چشیدی و من خود هدیه را چشیدم.\r\nاین آب فقط حامل مهربانی سرشار از عشق بود و هیچ چیز نمی تواند گواراتر از این باشد.\r\n"},{"id":2352,"category_id":2,"category_code":"s2","source_id":519,"title":"هر دو قربان!","content":"\r\nمی گویند ناپلئون در نظارت ارتش بسیار دقیق بود و مرتب از سربازان سان می دید و از وضعیت انها سوال می کرد.یکی از سربازان که گوشش سنگین بود از روبرو شدن با ناپلئون وحشت داشت و میترسید چیزی بپرسد که او نفهمد.دوستش چون از نگرانی او مطلع شد گفت:غمگین نباش ناپلئون از هر سرباز سه سوال میکند.ابتدا میپرسد:سرباز چند سال داری؟تو بگو 22 سال.بعد میپرسد:چند سال است که خدمت میکنی؟بگو دو سال.بعد میپرسد فرانسه را بیشتر دوست داری یا مرا؟بگو هر دو قربان.\r\nسرباز خود را جمع و جور کرده مهیای پاسخ گوئی شد.اما این بار خلاف همیشه ناپلئون ابتدا سوال کرد:سرباز چند سال است که خدمت میکنی؟گفت 22 سال قربان.ناپلئون نگاهی به او کرد و گفت چند سال سن داری؟\r\nگفت 2 سال قربان ناپلئون از مهمل گوئی او عصبانی شد و داد زد:ای سرباز احمق خودت را مسخره میکنی یا مرا؟سرباز با صدای بلند جواب داد هر دو را قربان.\r\nالبته چون کار به اینجا رسید بلافاصله فرمانده جلو امد و وضعیت او را به اطلاع ناپلئون رساند و ناپلئون پوزخندی زد و از انجا دور شد .\r\nاستاد\r\nمردی می خواست تا یک طوطی سخنگو بخرد ، طوطی های متعددی را دید و قیمت جوان‌ترین و زیباترینشان را پرسید . فروشنده گفت : این طوطی ؟ سه چهار میلیون ! ..... و دلیل آورد : این طوطی شعر نو میگه ، تموم شعرای شاملو ، اخوان ، نیما و فروغ رو از حفظه\r\nمشتری به دنبال طوطی ارزان تر ، یکی پیدا کرد که پیر بود اما هنوز آب و رنگی داشت ، رو به فروشنده گفت : پس این را می خرم که پیر است و نباید گران باشد\r\nـ این ؟! ..... فکرش رو نکن ، قیمت این بالای شش هفت میلیونه ..... چون تمام اشعار حافظ و سعدی و خواجوی کرمانی رو از حفظه \r\nمرد نا امید نشد و طوطی دیگری پیدا کرد که حسابی زهوار در رفته بود ، گفت : این که مردنی است و حتماً ارزان ......\r\nـ این؟! ..... فکرش رو نکن ، قیمتش بالای پونزده شونزده میلیونه ..... چون اشعار سوزنی سمرقندی و انوری و مولوی رو حفظه .....\r\nمرد که نمی خواست دست خالی برگردد به طوطی دیگری اشاره می کند که بال و پر ریخته بر کف قفس بی حرکت افتاده و لنگ‌هایش هوا بود ..... انگار نفس هم نمی کشید\r\nـ این یکی را می خرم که پیداست مرده ، حرف که نمی زند ، حتماً هیچ هنری هم ندارد و باید خیلی ارزان باشد .....\r\nـ این یکی؟! ..... اصلاً فکرش رو نکن ! قیمت این بالای شصت هفتاد میلیونه\r\nـ آخه چرا ؟ مگه اینم شعر می خونه ؟\r\nـ نه ..... شعر نمی خونه ، حتی نشدیدم تا امروز حرف بزنه ، اصلا هیچ کاری نمی کنه ..... اما این سه تا طوطی دیگه بهش میگن استاد !\r\n"},{"id":2353,"category_id":2,"category_code":"s2","source_id":520,"title":"مرد شریف","content":"آقای رابینسون هرگز به دندان‌پزشكی نرفته بود، برای اینكه می‌ترسید.\r\nاما بعد دندانش شروع به درد كرد، و به دندان‌پزشكی رفت. دندان‌پزشك بر روی دهان او وقت زیادی گذاشت و كلی كار كرد. در آخرین روز دكتر رابینسون به او گفت: هزینه‌ی تمام این كارها چقدر می‌شود؟ دندان‌پزشك گفت: بیست و پنج پوند. اما از او درخواست پول نكرد.\r\nبعد از یك ماه آقای رابینسون به دندان‌پزشك زنگ زد و گفت: ماه گذشته شما از من تقاضای هیچ پولی برای كارتان نكردید.\r\nدندان‌پزشك پاسخ داد: آه، من هرگز از انسان‌های نجیب تقاضای پول نمی‌كنم.\r\nآقای رابینسون پرسید: پس چگونه‌ زندگی می‌كنید.\r\nدندان‌پزشك گفت: بیشتر انسان‌های شریف به سرعت پول مرا می‌دهند، اما بعضی‌ها نه. من برای پولم دو ماه صبر می‌كنم، و بعد می‌گویم وی مرد شریفی نیست و بعد از وی پولم را می‌خواهم.\r\n"},{"id":2354,"category_id":2,"category_code":"s2","source_id":521,"title":"نتیجه بازدید","content":"به هنگام بازدید از یک بیمارستان روانى، از روان‌پزشک پرسیدم شما چطور می‌فهمید که یک بیمار روانى به بسترى شدن در بیمارستان نیاز دارد یا نه؟\r\nروان‌پزشک گفت: ما وان حمام را پر از آب می‌کنیم و یک قاشق چایخورى، یک فنجان و یک سطل جلوى بیمار می‌گذاریم و از او می‌خواهیم که وان را خالى کند.\r\nمن گفتم: آهان! فهمیدم. آدم عادى باید سطل را بردارد چون بزرگ‌تر است.\r\nروان‌پزشک گفت: نه! آدم عادى درپوش زیر آب وان را بر می‌دارد. شما می‌خواهید تخت‌تان کنار پنجره باشد؟\r\n"},{"id":2355,"category_id":2,"category_code":"s2","source_id":522,"title":"معلم عصبی","content":"معلم عصبی دفتر رو روی میز كوبید و داد زد: سارا ...\r\nدخترك خودش رو جمع و جور كرد، سرش رو پایین انداخت و خودش رو تا جلوی میز معلم كشید و با صدای لرزان گفت : بله خانوم؟\r\nمعلم كه از عصبانیت شقیقه هاش می زد، تو چشمای سیاه و مظلوم دخترك خیره شد و داد زد:\r\nچند بار بگم مشقاتو تمیز بنویس و دفترت رو سیاه و پاره نكن ؟ هـــا؟! فردا مادرت رو میاری مدرسه می خوام در مورد بچه بی انضباطش باهاش صحبت كنم!\r\nدخترك چونه ی لرزونش رو جمع كرد... بغضش رو به زحمت قورت داد و آروم گفت:\r\n\r\nخانوم... مادرم مریضه... اما بابام گفته آخر ماه بهش حقوق می دن...\r\nاونوقت می شه مامانم رو بستری كنیم كه دیگه از گلوش خون نیاد... اونوقت می شه برای خواهرم شیر خشك بخریم كه شب تا صبح گریه نكنه... اونوقت... اونوقت قول داده اگه پولی موند برای من هم یه دفتر بخره كه من دفترهای داداشم رو پاك نكنم و توش بنویسم... اونوقت قول می دم مشقامو ...\r\nمعلم صندلیش رو به سمت تخته چرخوند و گفت بشین سارا ...\r\nو كاسه اشك چشمش روی گونه خالی شد . . .\r\n"},{"id":2356,"category_id":2,"category_code":"s2","source_id":523,"title":"مسلمانان در آمریکا","content":"مردی دارد در پارک مرکزی شهر نیویورک قدم میزند که ناگهان میبیند سگی به دختر بچه ای حمله کرده است مرد به طرف آنها میدود و با سگ درگیر میشود . سرانجام سگ را میکشد و زندگی دختربچه ای را نجات میدهد.\r\nفردا در روزنامه ها می نویسند : \r\nیک نیویورکی شجاع جان دختر بچه ای را نجات داد \r\nاما آن مرد می گوید: من نیوریورکی نیستم \r\nپس روزنامه های صبح می نویسند: \r\nآمریکایی شجاع جان دختر بچه ای را نجات داد . \r\nآن مرد دوباره میگوید: من امریکایی نیستم\r\nاز او میپرسند :خب پس تو کجایی هستی\r\nمن اهل کشور مصر و مسلمان هستم \r\nفردای آن روز روزنامه ها این طور می نویسند : \r\nیک تند روی مسلمان سگ بی گناه امریکایی را کشت\r\n"},{"id":2357,"category_id":2,"category_code":"s2","source_id":524,"title":"پیرمرد زبل","content":"در یک غروب جمعه٬ پیرمردی مو سفید٬ در حالی که دختر جوان و زیبایی بازو به بازویش او را همراهی می کرد٬ وارد یک جواهر فروشی شد و به جواهرفروش گفت: \"برای دوست دخترم یک انگشتر مخصوص می خواهم.\" \r\nمرد جواهرفروش به اطرافش نگاهی انداخت و انگشتر فوق العاده ایی که ارزش آن چهل هزار دلار بود را به پیرمرد و دختر جوان نشان داد. چشمان دختر جوان برقی زد و تمام بدنش از شدت هیجان به لرزه افتاد. \r\nپیرمرد در حال دیدن انگشتر به مرد جواهرفروش گفت: خب٬ ما این رو برمی داریم. جواهرفروش با احترام پرسید که پول اون رو چطور پرداخت می کنید؟ پیرمرد گفت با چک٬ ولی خب من می دونم که شما باید مطمئن بشید که حساب من خوب هست٬ بنابراین من این چک رو الان می نویسم و شما می تونید روز دوشنبه که بانکها باز می شه٬ به بانک من تلفن بزنید و تایید اون رو بگیرید و بعد از آن٬ من در بعدازظهر دوشنبه این انگشتر را از شما می گیرم. \r\nدوشنبه صبح مرد جواهرفروش در حالی که به شدت ناراحت بود به پیرمرد تلفن زد و با عصبانیت به پیرمرد گفت:من الان حسابتون رو چک کردم٬ اصلا نمی تونم تصور کنم که توی حسابتون هیچ پولی وجود نداره! پیرمرد جواب داد: متوجه هستم٬ ولی در عوضش می تونی تصور کنی که من چه آخر هفته معرکه و هیجان انگیزی رو گذروندم؟!! \r\n"},{"id":2358,"category_id":2,"category_code":"s2","source_id":525,"title":"دقت عمل(طنز)","content":"در اولین ساعت درس کلاس تشریح و کالبد شکافی‌ دانشکده پزشکی‌ استاد به دانشجویان سال اول میگوید: به شما تبریک میگویم که در کنکور قبول شده و الان رسما دانشجوی پزشکی‌ هستید. ولی‌ برای فارغ التحصیل شدن و پزشک شدن هم باید \"دقت عمل\" داشته باشید و هم \"رقت عمل\". همه شما باید این کار که من الان می‌کنم را انجام بدهید اگر نه به درد این رشته نمی خورید و اخراج هسید!! سپس یک جسد وارد کلاس می‌کند و ناگهان انگشتش را تا ته در ماتحت جسد فرو می‌کند می گذارد توی دهانش و می مکد. و می گوید حالا شما هم باید همین کار را بکنید!! دانشجوها شوکه می شوند و اعتراض می کنند ولی‌ استاد می گوید الا و بلا باید بکنید وگرنه اخراج هستید. چند تا دخترها غش می کنند، پسرها بالا می اورند، ولی‌ با هر بدبختی هست همه دانشجوها آخرش انگشت در ماتحت جسد می کنند و می گذارند در دهنشان و می مکند\r\nاستاد میگوید: هان. شما همه رقت عمل تان خوب بود ولی‌ دقت عمل نداشتید. شما همگی‌ انگشت اشاره را در ماتحت کردید و مکیدید ولی‌ من انگشت اشاره را در ماتحت کردم و انگشت وسط را مکیدم. سعی‌ کنید بیشتر دقت کنید!\r\n"},{"id":2359,"category_id":2,"category_code":"s2","source_id":526,"title":"قسمت","content":"روزی مردی برای خود خانه ای بزرگ و زیبا خرید که حیاطی بزرگ با درختان میوه داشت. در همسایگی او خانه ای قدیمی بود که صاحبی حسود داشت که همیشه سعی می کرد اوقات او را تلخ کند و با گذاشتن زباله کنار خانه اش و ریختن آشغال آزارش می داد .یک روز صبح خوشحال از خواب برخاست و همین که به ایوان رفت دید یک سطل پر از زباله در ایوان است . سطل را تمیز کرد ، برق انداخت و آن را از میوه های تازه و رسیده حیاط خود پر کرد تا برای همسایه ببرد .وقتی همسایه صدای در زدن او را شنید خوشحال شد و پیش خود فکر کرد این بار دیگر برای دعوا آمده است . وقتی در را باز کرد مرد به او یک سطل پر از میوه های تازه و رسیده داد و گفت : \" هر کس آن چیزی را با دیگری قسمت می کند که از آن بیشتر دارد . \""},{"id":2360,"category_id":2,"category_code":"s2","source_id":527,"title":"آفرینش انسان","content":"روزی دخترک از مادرش پرسید: 'مامان نژاد انسان ها از کجا اومد؟مادر جواب داد: خداوند آدم و حوا را خلق کرد. اون ها بچه دار شدند و این جوری نژادانسان ها به وجود اومد.\r\nدو روز بعد دختر همین سوال رو از پدرش پرسید.\r\nپدرش پاسخ داد: 'خیلی سال پیش میمون ها تکامل یافتند و نژاد انسان ها پدید اومد..'\r\nدخترک که گیج شده بود نزد مادرش رفت و گفت:مامان تو گفتی خدا انسان ها روآفرید ولی بابا میگه انسان ها تکامل یافته ی میمون ها هستند...من که نمی فهمم!\r\nمادرش گفت: عزیز دلم خیلی ساده است. من بهت در مورد خانواده ی خودم گفتم و بابات درمورد خانواده ی خودش!\r\n"},{"id":2361,"category_id":2,"category_code":"s2","source_id":528,"title":"دوران دبستان","content":"\r\nگاو ما ما می کرد\r\nگوسفند بع بع می کرد\r\nسگ واق واق می کرد\r\nو همه با هم فریاد می زدند حسنک کجایی\r\nشب شده بود اما حسنک به خانه نیامده بود. حسنک مدت های زیادی است که به خانه نمی آید. او به شهر رفته و در آنجا شلوار جین و تی شرت های تنگ به تن می کند. او هر روز صبح به جای غذا دادن به حیوانات جلوی آینه به موهای خود ژل می زند.\r\n\r\nموهای حسنک دیگر مثل پشم گوسفند نیست چون او به موهای خود گلت می زند.\r\nدیروز که حسنک با کبری چت می کرد . کبری گفت تصمیم بزرگی گرفته است.کبری تصمیم داشت حسنک را رها کند و دیگر با او چت نکند چون او با پتروس چت می کرد. پتروس همیشه پای کامپیوترش نشسته بود و چت می کرد. پتروس دید که سد سوراخ شده اما انگشت او درد می کرد چون زیاد چت کرده بود. او نمی دانست که سد تا چند لحظه ی دیگر می شکند. پتروس در حال چت کردن غرق شد.\r\n\r\n\r\nبرای مراسم دفن او کبری تصمیم گرفت با قطار به آن سرزمین برود اما کوه روی ریل ریزش کرده بود . ریزعلی دید که کوه ریزش کرده اما حوصله نداشت . ریزعلی سردش بود و دلش نمی خواست لباسش را در آورد . ریزعلی چراغ قوه داشت اما حوصله درد سر نداشت. قطار به سنگ ها برخورد کرد و منفجر شد . کبری و مسافران قطار مردند.\r\nاما ریزعلی بدون توجه به خانه رفت. خانه مثل همیشه سوت و کور بود . الان چند سالی است که کوکب خانم همسر ریزعلی مهمان ناخوانده ندارد او حتی مهمان خوانده هم ندارد. او حوصله ی مهمان ندارد. او پول ندارد تا شکم مهمان ها را سیر کند.\r\nاو در خانه تخم مرغ و پنیر دارد اما گوشت ندارد\r\nاو کلاس بالایی دارد او فامیل های پولدار دارد.\r\nاو آخرین بار که گوشت قرمز خرید چوپان دروغگو به او گوشت خر فروخت . اما او از چوپان دروغگو گله ندارد چون دنیای ما خیلی چوپان دروغگو دارد به همین دلیل است که دیگر در کتاب های دبستان آن داستان های قشنگ وجود ندارد.\r\n"},{"id":2362,"category_id":2,"category_code":"s2","source_id":529,"title":"تکه ای که دوست نداری!؟ ","content":"شیوانا صبح زود از مقابل مغازه نانوایی عبور می کرد. دید نانوا عمدا مقداری آرد ارزان جو را با آرد مرغوب گندم مخلوط می کند تا در طول روز به مردم به اسم نان مرغوب گندم بفروشد و سود بیشتری به دست آورد. شیوانا از مرد نانوا پرسید:\" آیا دوست داری با آن بخش از وجودت که به تو دستور این کار را داد و الآن مشغول انجام این کار است تمام عمر همنشین باشی!؟\"\r\nمرد نانوا با مسخرگی پاسخ داد:\" من فقط برای مدتی اینکار را انجام خواهم داد و بعد که وضع مالی ام بهتر شد اینکار را ترک می کنم و مثل بقیه نانواها آدم درست و صادقی می شوم!؟\"\r\nشیوانا سری تکان داد و گفت:\" متاسفم دوست من!! هر انسانی که کاری انجام می دهد بخشی از وجود او می فهمد که قادربه این کار هست. این بخش همه عمر با انسان می آید. در نگاه و چهره و رفتار و گفتار و صدای آدم خودش را نشان می دهد. کم کم انسان های اطراف ات هم می فهمند که چیزی در وجود تو قادر به این جور کارهای خلاف است و به خاطر آن از توفاصله می گیرند. تو کم کم تنها می شوی و این بخش که تو دیگر دوستش نخواهی داشت همچنان با تو همراه خواهد شد و نهایتا وقتی همه را از دست دادی فقط این بخش از وجودت یعنی بخشی که قادر به فریب است در کلک زدن مهارت دارد با تو می ماند و تو مجبوری تمام عمر با تکه ای که دوست نداری زندگی کنی و حتی در آن دنیا با همان تکه همراه شوی! اگر آنها که محض تفنن و امتحان به کار خلافی دست می زنند و گمان می کنند بعد از این تجربه قادر به بازگشت به حالت پاکی و عصمت اولیه نیستند و بخشی از وجود آنها نسبت به توانایی خود در خطاکاری آگاه و بیدار می شود و همیشه همراهشان می آید ، شاید از همان ابتدا هرگز به سمت کار خلاف حتی برای امتحان هم نمی رفتند.\r\n"},{"id":2363,"category_id":2,"category_code":"s2","source_id":530,"title":"چیزی برای نگرانی وجود نداره","content":"فقط دو چیز وجود داره كه نگرانش باشی: اینكه سالمی یا مریضی.\r\nاگر سالم هستی، دیگه چیزی نمونده كه نگرانش باشی؛ \r\nاما اگه مریضی، فقط دو چیز وجود داره كه نگرانش باشی: اینكه دست آخر خوب می شی یا می میری.\r\nاگه خوب شدی كه دیگه چیزی برای نگرانی باقی نمی مونه؛ \r\nاما اگه بمیری، دو چیز وجود داره كه نگرانش باشی: اینكه به بهشت بری یا به جهنم.\r\nاگر به بهشت بری، چیزی برای نگرانی وجود نداره؛ \r\nولی اگه به جهنم بری، اون قدر مشغول احوالپرسی با دوستان قدیمی می شی كه وقتی برای نگرانی نداری!\r\nپس در واقع هیچ وقت هیچ چیز برای نگرانی وجود نداره!! \r\nامیدوارم همیشه سلامت و شاد باشی \r\n"},{"id":2364,"category_id":2,"category_code":"s2","source_id":531,"title":"بامبو و سرخس","content":"روزی تصمیم گرفتم كه دیگر همه چیز را رها كنم. شغلم ‏را، دوستانم را، زندگی ام را! \r\nبه جنگلی رفتم تا برای آخرین بار با خدا ‏صحبت كنم. به خدا گفتم: آیا می‏ توانی دلیلی برای ادامه زندگی برایم بیاوری؟ \r\nو جواب ‏او مرا شگفت زده كرد. \r\nاو گفت : آیا درخت سرخس و بامبو را می بینی؟ \r\nپاسخ دادم : بلی. \r\nفرمود: ‏هنگامی كه درخت بامبو و سرخس راآفریدم، به خوبی ازآنها مراقبت نمودم. به آنها نور ‏و غذای كافی دادم. دیر زمانی نپایید كه سرخس سر از خاك برآورد و تمام زمین را فرا ‏گرفت اما از بامبو خبری نبود. من از او قطع امید نكردم. در دومین سال سرخسها بیشتر ‏رشد كردند و زیبایی خیره كننده ای به زمین بخشیدند اما همچنان از بامبوها خبری نبود. ‏من بامبوها را رها نكردم. در سالهای سوم و چهارم نیز بامبوها رشد نكردند. اما من ‏باز از آنها قطع امید نكردم. در سال پنجم جوانه كوچكی از بامبو نمایان شد. در ‏مقایسه با سرخس كوچك و كوتاه بود اما با گذشت 6 ماه ارتفاع آن به بیش از 100 فوت ‏رسید. 5 سال طول كشیده بود تا ریشه ‏های بامبو به اندازه كافی قوی شوند.. ریشه هایی ‏كه بامبو را قوی می‏ ساختند و آنچه را برای زندگی به آن نیاز داشت را فراهم می ‏كرد. \r\n‏خداوند در ادامه فرمود: آیا می‏ دانی در تمامی این سالها كه تو درگیر مبارزه با ‏سختیها و مشكلات بودی در حقیقت ریشه هایت را مستحكم می ‏ساختی. من در تمامی این مدت ‏تو را رها نكردم همانگونه كه بامبوها را رها نكردم.\r\n‏هرگز خودت را با دیگران ‏مقایسه نكن. بامبو و سرخس دو گیاه متفاوتند اما هر دو به زیبایی جنگل كمك می كنن. ‏زمان تو نیز فرا خواهد رسید تو نیز رشد می ‏ كنی و قد می كشی!\r\n‏از او پرسیدم : من ‏چقدر قد می‏ كشم.\r\n‏در پاسخ از من پرسید: بامبو چقدر رشد می كند؟ \r\nجواب دادم: هر ‏چقدر كه بتواند. \r\n\r\n‏گفت: تو نیز باید رشد كنی و قد بكشی، هر اندازه كه ‏بتوانی...\r\n"},{"id":2365,"category_id":2,"category_code":"s2","source_id":532,"title":"نمک شناس!!","content":"آنها تا مى توانستند از انواع و اقسام طلا جات و عتيقه جات در كوله بار خود گذاشتند تا ببرند.در اين هنگام چشم سر كرده باند به شى ء درخشنده و سفيدى افتاد، گمان كرد گوهر شب چراغ است ، نزديكش رفت آن را برداشت و براى امتحان به سر زبان زد، معلوم شد نمك است ، بسيار ناراحت و عصبانى شد و از شدت خشم و غضب دستش را بر پيشانى زد بطورى كه رفقايش متوجه او شدند و خيال كردند اتفاقى پيش آمد يا نگهبانان خزانه با خبر شدند.خيلى زود خودشان را به او رسانيدند و گفتند: چه شد؟ چه حادثه اى اتفاق افتاد؟ او كه آثار خشم و ناراحتى در چهره اش پيدا بود گفت : افسوس كه تمام زحمتهاى چندين روزه ما به هدر رفت و ما نمك گير سلطان شديم ، من ندانسته نمكش را چشيدم ، ديگر نمى شود مال و دارايى پادشاه را برد، از مردانگى و مروت به دور است كه ما نمك كسى را بخوريم و نمكدان او را هم بشكنيم و...\r\nآنها در آن دل سكوت سهمگين شب ، بدون اين كه كسى بويى ببرد دست خالى به خانه هاشان باز گشتند.صبح كه شد و چشم نگهبانان به درهاى باز خزانه افتاد تازه متوجه شدند كه شب خبرهايى بوده است ، سراسيمه خود را به جواهرات سلطنتى رسانيدند، ديدند سر جايشان نيستند، اما در آنجا بسته هايى به چشم مى خورد، آنها را كه باز كردند ديدند جواهرات در ميان بسته ها مى باشد، بررسى دقيق كه كردند ديدند كه دزد خزانه را نبرده است و گرنه الآن خدا مى داند سلطان با ما چه مى كرد و...\r\nبالآخره خبر به سلطان رسيد و خود او آمد و از نزديك صحنه را مشاهده كرد، آنقدر اين كار برايش عجيب و شگفت آور بود كه انگشتش را به دندان گرفته و با خود مى گفت : عجب !اين چگونه دزدى است ؟ براى دزدى آمده و با آنكه مى توانسته همه چيز را ببرد ولى چيزى نبرده است ؟ آخر مگر مى شود؟ چرا؟... ولى هر جور كه شده بايد ريشه يابى كنم و ته و توى قضيه را در آورم . در همان روز اعلام كرد: هر كس شب گذشته به خزانه آمده در امان است او مى تواند نزد من بيايد، من بسيار مايلم از نزديك او را ببينم و بشناسم .\r\nاين اعلاميه سلطان به گوش سركرده دزدها رسيد، دوستانش را جمع كرد و به آنها گفت :سلطان به ما امان داده است ، برويم پيش او تا ببينيم چه مى گويد. آنها نزد سلطان آمده و خود را معرفى كردند، سلطان كه باور نمى كرد دوباره با تعجب پرسيد: اين كار تو بوده ؟ گفت : آرى . سلطان پرسيد: چرا آمدى دزدى و با اين كه مى توانستى همه چيز را ببرى ولى چيزى را نبردى ؟ گفت : چون نمك شما را چشيدم و نمك گير شدم و بعد جريان را مفصل براى سلطان گفت . سلطان به قدرى عاشق و شيفته كرم و بزرگوارى او شد كه گفت : حيف است جاى انسان نمك شناسى مثل تو، جاى ديگرى باشد، تو بايد در دستگاه حكومت من كار مهمى را بر عهده بگيرى ، و حكم خزانه دارى را براى او صادر كرد.\r\nآرى او يعقوب ليث بود و چند سالى حكمرانى كرد و سلسله صفاريان را تاءسيس نمود.\r\n"}];
